local THEME_ORDER = { "Default", "Full Black", "Full White", "Water", "Brazil", "Dog Manin", "Sunset", "Neon", "Sakura", "Forest", "Galaxy", "Lava", "Argentina", "Japan", "USA", "Portugal", "Angola", "Mexico", "Shadow", "Midnight", "Cyberpunk", "Aurora", "Matrix", "Candy", "Autumn", "Royal", "Ice", "Blood Moon", "Emerald", "Halloween", "Imperador", "Custom" }
local TH = { cur = THEMES["Default"], name = "Default", binds = {}, hooks = {} }

-- ================================================================ MoonUI ====
local UI = {}
;(function()
    function UI.new(class, props, parent)
        local o = Instance.new(class)
        for k, v in pairs(props or {}) do o[k] = v end
        if parent then o.Parent = parent end
        return o
    end
    local new = UI.new
    -- v24: velocidade global das animacoes (Script Settings > Interface > Animations): Off = instantaneo, Fast, Normal, Slow
    UI.SPEEDS = { Off = 0, Fast = 0.6, Normal = 1, Slow = 1.6 }
    UI.speed = 1
    function UI.tween(o, t, props, style, dir)
        local sp = UI.speed
        if sp ~= 1 then t = (sp <= 0) and 0 or (t * sp) end
        local tw = TweenService:Create(o, TweenInfo.new(t, style or Enum.EasingStyle.Quint, dir or Enum.EasingDirection.Out), props)
        tw:Play(); return tw
    end
    function UI.bind(o, prop, key, instant)
        table.insert(TH.binds, { o, prop, key })
        o[prop] = TH.cur[key]
    end
    function TH.apply(name)
        if not THEMES[name] then return end
        TH.cur, TH.name = THEMES[name], name
        for _, b in ipairs(TH.binds) do
            pcall(function() UI.tween(b[1], 0.4, { [b[2]] = TH.cur[b[3]] }, Enum.EasingStyle.Quad) end)
        end
        for _, f in ipairs(TH.hooks) do pcall(f) end
    end
    function UI.corner(o, r) return new("UICorner", { CornerRadius = UDim.new(0, r or 8) }, o) end
    function UI.stroke(o, col, th, tr)
        return new("UIStroke", { Color = col or C.white, Thickness = th or 1, Transparency = tr or 0, ApplyStrokeMode = Enum.ApplyStrokeMode.Border }, o)
    end
    function UI.grad(o, c0, c1, rot)
        return new("UIGradient", { Color = ColorSequence.new(c0, c1), Rotation = rot or 90 }, o)
    end
    function UI.pad(o, l, t, r, b)
        return new("UIPadding", { PaddingLeft = UDim.new(0, l or 0), PaddingTop = UDim.new(0, t or l or 0), PaddingRight = UDim.new(0, r or l or 0), PaddingBottom = UDim.new(0, b or t or l or 0) }, o)
    end
    function UI.list(o, gap, dir)
        return new("UIListLayout", { Padding = UDim.new(0, gap or 6), SortOrder = Enum.SortOrder.LayoutOrder, FillDirection = dir or Enum.FillDirection.Vertical }, o)
    end
    -- texto: cores "padrao" (text/dim) acompanham o tema
    function UI.text(parent, props)
        local p = { BackgroundTransparency = 1, Font = Enum.Font.GothamBold, TextSize = 14, TextColor3 = C.text, Text = "", TextXAlignment = Enum.TextXAlignment.Left, TextYAlignment = Enum.TextYAlignment.Center, BorderSizePixel = 0 }
        for k, v in pairs(props) do p[k] = v end
        local col = p.TextColor3
        local o = new("TextLabel", p, parent)
        if col == C.text then UI.bind(o, "TextColor3", "text")
        elseif col == C.dim or col == C.dim2 then UI.bind(o, "TextColor3", "dim") end
        return o
    end
    function UI.icon(parent, id, size, col, props)
        local p = { Size = UDim2.fromOffset(size, size), BackgroundTransparency = 1, Image = id, ImageColor3 = col or C.text, BorderSizePixel = 0 }
        for k, v in pairs(props or {}) do p[k] = v end
        local o = new("ImageLabel", p, parent)
        if col == C.icon then UI.bind(o, "ImageColor3", "icon") end
        return o
    end
    -- feedback de clique (encolhe de leve)
    function UI.press(btn)
        local sc = new("UIScale", { Scale = 1 }, btn)
        btn.MouseButton1Down:Connect(function() UI.tween(sc, 0.08, { Scale = 0.965 }, Enum.EasingStyle.Quad) end)
        local function up() UI.tween(sc, 0.22, { Scale = 1 }, Enum.EasingStyle.Back) end
        btn.MouseButton1Up:Connect(up); btn.MouseLeave:Connect(up)
    end
end)()
local new, corner, stroke, grad, pad, list, text, icon, tween, bind = UI.new, UI.corner, UI.stroke, UI.grad, UI.pad, UI.list, UI.text, UI.icon, UI.tween, UI.bind

local function measure(str, size, font)
    local ok, v = pcall(function() return TextService:GetTextSize(str, size, font, Vector2.new(600, 100)) end)
    if ok and v and v.X and v.X > 0 then return v.X end
    return #str * size * 0.62
end
-- Titulo igual ao dos outros scripts: Moon Hub (branco/contorno preto) + [ Premium ] (azul/contorno branco) + By Moon Studio (preto/contorno branco)
local function titlePair(parent, x, y, size, z, studio)
    local font = Enum.Font.GothamBold
    local function word(str, px, py, sz, fill, strokeCol, bindFill, bindStroke)
        local w = measure(str, sz, font) + 6
        local t = new("TextLabel", { BackgroundTransparency = 1, Size = UDim2.fromOffset(w, sz + 6), Position = UDim2.fromOffset(px, py), Text = str, TextSize = sz, Font = font, TextColor3 = fill, ZIndex = z, TextXAlignment = Enum.TextXAlignment.Center, BorderSizePixel = 0 }, parent)
        local st = new("UIStroke", { Color = strokeCol, Thickness = (sz <= 13) and 0.6 or 1, Transparency = 0, ApplyStrokeMode = Enum.ApplyStrokeMode.Contextual }, t)
        if bindFill then bind(t, "TextColor3", bindFill) end
        if bindStroke then bind(st, "Color", bindStroke) end
        return w
    end
    local w1 = word("Moon Hub", x, y, size, TH.cur.title, TH.cur.titleS, "title", "titleS")
    local w2 = word("[ " .. TIER_LABEL .. " ]", x + w1 + 4, y, size, TIER_BR, C.white)
    if studio then word("By Moon Studio", x, y + size + 3, 13, Color3.new(0, 0, 0), C.white) end
    return w1 + 4 + w2
end

-- ================================================================== GUI ====
local gui = new("ScreenGui", { Name = "MoonPremiumHub", ResetOnSpawn = false, IgnoreGuiInset = true, DisplayOrder = 998, ZIndexBehavior = Enum.ZIndexBehavior.Sibling })
pcall(function() gui.Parent = (gethui and gethui()) or game:GetService("CoreGui") end)
if not gui.Parent then gui.Parent = LP:WaitForChild("PlayerGui") end

local conns = {}
local alive = true
local cleanups = {}      -- desfaz efeitos (FPS, fog, anti afk...) ao fechar
local persistNow         -- v89: declarado aqui (so ganha o corpo mais abaixo) pra destroyHub poder chamar na hora
local function destroyHub()
    alive = false
    if persistNow then pcall(persistNow) end   -- garante que a ultima mudanca (ainda no debounce) e salva antes de fechar
    for _, f in ipairs(cleanups) do pcall(f) end
    for _, c in ipairs(conns) do pcall(function() c:Disconnect() end) end
    pcall(function() gui:Destroy() end)
    getgenv().MoonPremiumHub = nil
end
getgenv().MoonPremiumHub = destroyHub

local scale = new("UIScale", {}, gui)
-- v29: celular as vezes entra com workspace.CurrentCamera ainda nil no instante em que esse script roda (a camera
-- so fica pronta um pouco depois do join); antes disso o fit() caia no fallback de 900x500 (tamanho de PC) e o
-- :Connect do ViewportSize nem pegava (o pcall engolia o erro de indexar nil), entao a janela ficava do tamanho
-- de PC pra sempre num celular - e foi isso que causou o card de perfil (e outras coisas) aparecerem fora do
-- lugar no mobile. Agora a gente tenta de novo por alguns segundos ate achar uma camera valida, e tambem fica de
-- olho se a CurrentCamera for troca (acontece em alguns jogos).
local mobileUIActive = false
-- v89: "UI Scale" (Script Settings > Interface) - multiplicador extra por cima do auto-fit, pro jogador deixar a
-- janela menor (mais leve/discreta em celular fraco) ou maior (telao/baixa visao). Variavel separada (nao "cfg",
-- que so e declarado mais abaixo no arquivo - fit() e chamado antes disso existir) e ajustada depois que o cfg
-- salvo carrega, e de novo toda vez que o slider muda.
local uiScaleMul = 1
local function fit()
    local cam = workspace.CurrentCamera
    local vp = cam and cam.ViewportSize or Vector2.new(900, 500)
    local s = math.clamp(math.min(vp.X / 740, vp.Y / 500), 0.5, 1.15)
    if mobileUIActive then s = math.min(s, 0.86) end -- v29: Mobile UI Version - trava um teto mais conservador pra nao passar da tela
    scale.Scale = s * uiScaleMul
end
fit()
local function hookCamera()
    pcall(function()
        local cam = workspace.CurrentCamera
        if cam then table.insert(conns, cam:GetPropertyChangedSignal("ViewportSize"):Connect(fit)) end
    end)
end
hookCamera()
pcall(function() table.insert(conns, workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(function() hookCamera(); fit() end)) end)
-- v29: reforco pros primeiros segundos (cobre o caso da camera demorar pra existir ou do ViewportSize
-- ainda nao estar com o valor final assim que o jogo carrega no celular)
task.spawn(function()
    for i = 1, 20 do
        task.wait(0.5)
        if not alive then return end
        pcall(fit)
    end
end)

-- toasts (deslizam da direita)
local toastHolder = new("Frame", { Size = UDim2.fromOffset(270, 320), Position = UDim2.new(1, -286, 1, -336), BackgroundTransparency = 1 }, gui)
local tl = list(toastHolder, 8); tl.VerticalAlignment = Enum.VerticalAlignment.Bottom
local function notify(title, msg, kind, dur)
    local col = kind == "ok" and C.ok or (kind == "bad" and C.bad or (kind == "warn" and C.warn or C.blue))
    local slot = new("Frame", { Size = UDim2.new(1, 0, 0, 56), BackgroundTransparency = 1, ClipsDescendants = false }, toastHolder)
    local t = new("Frame", { Size = UDim2.fromScale(1, 1), Position = UDim2.fromOffset(290, 0), BackgroundColor3 = Color3.fromRGB(26, 27, 33), BorderSizePixel = 0 }, slot)
    corner(t, 11); stroke(t, col, 1.2, 0.35)
    local bar = new("Frame", { Size = UDim2.new(0, 3, 1, -18), Position = UDim2.fromOffset(9, 9), BackgroundColor3 = col, BorderSizePixel = 0 }, t)
    corner(bar, 2)
    new("TextLabel", { BackgroundTransparency = 1, Position = UDim2.fromOffset(22, 8), Size = UDim2.new(1, -30, 0, 18), Text = title, Font = Enum.Font.GothamBold, TextSize = 13, TextColor3 = C.white, TextXAlignment = Enum.TextXAlignment.Left }, t)
    new("TextLabel", { BackgroundTransparency = 1, Position = UDim2.fromOffset(22, 26), Size = UDim2.new(1, -30, 0, 24), Text = msg, Font = Enum.Font.Gotham, TextSize = 11, TextColor3 = Color3.fromRGB(170, 175, 195), TextXAlignment = Enum.TextXAlignment.Left, TextYAlignment = Enum.TextYAlignment.Top, TextWrapped = true }, t)
    tween(t, 0.45, { Position = UDim2.fromOffset(0, 0) })
    task.delay(dur or 4, function()
        if t.Parent then
            tween(t, 0.35, { Position = UDim2.fromOffset(290, 0) })
            task.wait(0.4); slot:Destroy()
        end
    end)
end

-- v79: notificacao de confirmacao (Sim/Nao) pedida pelo usuario - mesmo canto/estilo dos toasts acima (slide da
-- direita), so que fica no ar esperando um clique: "Sim" chama onYes, "Nao" so fecha. Se ninguem clicar em "secs"
-- segundos (padrao 5), fecha sozinha e conta como "Nao" (nunca chama onYes sem clique explicito).
-- v98: barra de progresso embaixo (alem do texto "Auto "No" em Xs") - encolhe de ponta a ponta durante os "secs"
-- segundos, pra dar uma nocao visual de quanto tempo falta antes de fechar sozinho em "Nao" (igual pedido pelo
-- usuario). O card cresceu um pouco (108 -> 118) pra caber a barra sem encostar nos botoes.
local function confirmToast(title, msg, onYes, secs)
    secs = tonumber(secs) or 5
    local slot = new("Frame", { Size = UDim2.new(1, 0, 0, 118), BackgroundTransparency = 1, ClipsDescendants = false }, toastHolder)
    local t = new("Frame", { Size = UDim2.fromScale(1, 1), Position = UDim2.fromOffset(290, 0), BackgroundColor3 = Color3.fromRGB(26, 27, 33), BorderSizePixel = 0, ClipsDescendants = true }, slot)
    corner(t, 11); stroke(t, C.warn, 1.2, 0.35)
    local bar = new("Frame", { Size = UDim2.new(0, 3, 1, -18), Position = UDim2.fromOffset(9, 9), BackgroundColor3 = C.warn, BorderSizePixel = 0 }, t)
    corner(bar, 2)
    new("TextLabel", { BackgroundTransparency = 1, Position = UDim2.fromOffset(22, 8), Size = UDim2.new(1, -30, 0, 18), Text = title, Font = Enum.Font.GothamBold, TextSize = 13, TextColor3 = C.white, TextXAlignment = Enum.TextXAlignment.Left }, t)
    new("TextLabel", { BackgroundTransparency = 1, Position = UDim2.fromOffset(22, 26), Size = UDim2.new(1, -30, 0, 32), Text = msg, Font = Enum.Font.Gotham, TextSize = 11, TextColor3 = Color3.fromRGB(170, 175, 195), TextXAlignment = Enum.TextXAlignment.Left, TextYAlignment = Enum.TextYAlignment.Top, TextWrapped = true }, t)
    local cd = new("TextLabel", { BackgroundTransparency = 1, Position = UDim2.fromOffset(22, 60), Size = UDim2.new(1, -30, 0, 14), Text = string.format("Auto \"No\" in %ds", secs), Font = Enum.Font.Gotham, TextSize = 10, TextColor3 = C.dim, TextXAlignment = Enum.TextXAlignment.Left }, t)
    local function mkBtn(x, w2, lbl, primary)
        local b = new("TextButton", { Size = UDim2.fromOffset(w2, 26), Position = UDim2.fromOffset(x, 78), BackgroundColor3 = primary and C.bad or C.white, BackgroundTransparency = primary and 0.08 or 0.9, Text = lbl, Font = Enum.Font.GothamBold, TextSize = 11, TextColor3 = C.white, AutoButtonColor = false, ZIndex = 2 }, t)
        corner(b, 8)
        if not primary then local s = stroke(b, C.white, 1, 0.75); bind(s, "Color", "rowS") end
        if not primary then bind(b, "TextColor3", "text") end
        b.MouseEnter:Connect(function() tween(b, 0.15, { BackgroundTransparency = primary and 0.2 or 0.8 }) end)
        b.MouseLeave:Connect(function() tween(b, 0.2, { BackgroundTransparency = primary and 0.08 or 0.9 }) end)
        UI.press(b)
        return b
    end
    local yes = mkBtn(22, 78, "Yes")
    local no = mkBtn(108, 78, "No")
    -- v98: trilho (fundo fraco) + barra que encolhe da esquerda pra direita, mesma cor do aviso (C.warn)
    local trackY = 112
    new("Frame", { Size = UDim2.new(1, -44, 0, 3), Position = UDim2.fromOffset(22, trackY), BackgroundColor3 = C.white, BackgroundTransparency = 0.88, BorderSizePixel = 0 }, t)
    local prog = new("Frame", { Size = UDim2.new(1, -44, 0, 3), Position = UDim2.fromOffset(22, trackY), BackgroundColor3 = C.warn, BorderSizePixel = 0, ZIndex = 2 }, t)
    corner(prog, 2)
    local resolved = false
    local function close(wasYes)
        if resolved then return end
        resolved = true
        if t.Parent then
            tween(t, 0.3, { Position = UDim2.fromOffset(290, 0) })
            task.delay(0.35, function() if slot.Parent then slot:Destroy() end end)
        end
        if wasYes and onYes then pcall(onYes) end
    end
    yes.MouseButton1Click:Connect(function() close(true) end)
    no.MouseButton1Click:Connect(function() close(false) end)
    tween(t, 0.45, { Position = UDim2.fromOffset(0, 0) })
    tween(prog, secs, { Size = UDim2.new(0, 0, 0, 3) }, Enum.EasingStyle.Linear)
    task.spawn(function()
        for i = secs, 1, -1 do
            if resolved then return end
            cd.Text = string.format("Auto \"No\" in %ds", i)
            task.wait(1)
        end
        close(false)
    end)
end

