local persistXform          -- (opcional) o modulo de compat limpa cfg.m antes de gravar
-- v89: "persist()" e chamado em CENTENAS de lugares (todo toggle/slider/select do hub) - e cada slider chama de
-- novo em TODO movimento do mouse enquanto arrasta (Click CPS, Bring Mob Range, Tween Speed, UI Scale...). Antes
-- isso escrevia o arquivo (JSONEncode + writefile) na hora, toda vez - arrastar UM slider disparava dezenas de
-- escritas em disco por segundo, travando a interface. Agora junta varias chamadas seguidas numa so, escrevendo
-- so 0,25s depois da ULTIMA mudanca (igual o debounce que ja existia so pros textboxes). persistNow() continua
-- disponivel pra forcar a escrita na hora (usado ao fechar o hub, pra nunca perder a ultima mudanca).
function persistNow()
    if cfg.autosave and writefile then
        local snap = cfg
        if persistXform then local ok, r = pcall(persistXform, cfg); if ok and type(r) == "table" then snap = r end end
        pcall(writefile, CFG_FILE, HttpService:JSONEncode(snap))
    end
end
local persistSeq = 0
local function persist()
    persistSeq += 1
    local mine = persistSeq
    task.delay(0.25, function() if persistSeq == mine then persistNow() end end)
end


-- ===================================================== organizacao da interface (v23) ====
-- Icone igual em todas as linhas (Dot / Moon / Classic / None), secoes que dobram, busca por aba e ordem das secoes por aba.
-- Tudo fica dentro desta tabela (o limite de 200 variaveis locais por funcao nao deixa criar uma por funcao).
local ORG = { sty = "Dot", rows = {}, of = {}, heads = {}, isHead = {}, isSub = {}, tabOf = {}, order = {}, defFold = {}, query = {}, TXS = { Dot = 40, Moon = 46, Classic = 54, None = 18 } }
ORG.tx = ORG.TXS.Dot
function ORG.h(sub) return (sub and sub ~= "") and 56 or 46 end          -- linha sem legenda fica mais baixa
-- estado visual do glifo: ponto/lua/icone acende no hover e quando o interruptor da linha esta ligado
function ORG.paint(rec, instant)
    local g, k = rec.gl, rec.kind
    if not g then return end
    local lit = rec.on or rec.hov
    local col = rec.tintCol or (lit and TH.cur.acc) or nil
    local t = instant and 0 or 0.18
    local h = rec.h
    if k == "dot" then
        local sz = rec.on and 10 or (rec.hov and 9 or 8)
        tween(g, t, { Size = UDim2.fromOffset(sz, sz), Position = UDim2.fromOffset(22 - sz / 2, h / 2 - sz / 2), BackgroundColor3 = col or TH.cur.dim,
            BackgroundTransparency = (rec.on or rec.tintCol) and 0 or (rec.hov and 0.15 or 0.5) }, Enum.EasingStyle.Quad)
    elseif k == "img" then
        local sz = rec.hov and 22 or 20
        tween(g, t, { Size = UDim2.fromOffset(sz, sz), Position = UDim2.fromOffset(16 - (sz - 20) / 2, (h - sz) / 2), ImageColor3 = col or TH.cur.icon }, Enum.EasingStyle.Back)
    elseif k == "moon" then
        tween(g, t, { ImageTransparency = rec.on and 0.05 or (rec.hov and 0.15 or 0.5) })
    end
end
function ORG.glyph(rec)
    if rec.gl then pcall(function() rec.gl:Destroy() end); rec.gl, rec.kind = nil, nil end
    if rec.noGl or ORG.sty == "None" then return end
    local sty, r, h = ORG.sty, rec.r, math.min(rec.h, 60)   -- linha alta (lista de itens etc.): o glifo fica na altura do titulo, nao no meio
    if sty == "Classic" then
        if not rec.id then return end
        rec.gl = new("ImageLabel", { Size = UDim2.fromOffset(20, 20), Position = UDim2.fromOffset(16, (h - 20) / 2), BackgroundTransparency = 1, Image = rec.id, ImageColor3 = TH.cur.icon, BorderSizePixel = 0, ZIndex = 5 }, r)
        rec.kind = "img"
    elseif sty == "Moon" then
        rec.gl = new("ImageLabel", { Size = UDim2.fromOffset(18, 18), Position = UDim2.fromOffset(15, (h - 18) / 2), BackgroundTransparency = 1, Image = ORG.moon, ScaleType = Enum.ScaleType.Fit, BorderSizePixel = 0, ZIndex = 5 }, r)
        rec.kind = "moon"
    else
        rec.gl = new("Frame", { Size = UDim2.fromOffset(8, 8), Position = UDim2.fromOffset(18, (h - 8) / 2), BackgroundColor3 = TH.cur.dim, BorderSizePixel = 0, ZIndex = 5 }, r)
        corner(rec.gl, 5)
        rec.kind = "dot"
    end
    ORG.paint(rec, true)
end
-- acompanha o x do texto: move o que esta alinhado a esquerda e mantem a borda direita no lugar
function ORG.shift(el, d)
    if not el or d == 0 then return end
    pcall(function()
        local p, s = el.Position, el.Size
        el.Position = UDim2.new(p.X.Scale, p.X.Offset + d, p.Y.Scale, p.Y.Offset)
        if s.X.Scale ~= 0 then el.Size = UDim2.new(s.X.Scale, s.X.Offset - d, s.Y.Scale, s.Y.Offset) end
    end)
end
-- quantas linhas o texto ocupa numa caixa de w pixels (mede com o TextService; sem ele, estima pelo numero de letras)
function ORG.lines(str, w, size, font)
    size, font = size or 11, font or Enum.Font.Gotham
    if type(str) ~= "string" or str == "" then return 0 end
    w = math.max(40, w)
    local ok1, one = pcall(function() return TextService:GetTextSize("Ag", size, font, Vector2.new(10000, 10000)).Y end)
    local ok2, all = pcall(function() return TextService:GetTextSize(str, size, font, Vector2.new(w, 10000)).Y end)
    if ok1 and ok2 and type(one) == "number" and type(all) == "number" and one > 0 then return math.max(1, math.floor(all / one + 0.5)) end
    return math.max(1, math.ceil(#str * size * 0.56 / w))
end
-- legenda em ate 2 linhas dentro da mesma altura da linha (acima disso corta com "..."). Sobe o titulo para centralizar o bloco de texto.
function ORG.fit(rec)
    local ss, tt = rec.ss, rec.tt
    if not (ss and tt and rec.R) or rec.fixed or type(rec.sub) ~= "string" or rec.sub == "" or ss.TextSize ~= 11 then return end
    local n = ORG.lines(rec.sub, (ORG.RW or 408) - rec.tx - rec.R) >= 2 and 2 or 1
    if n == rec.n then return end
    rec.n = n
    local sz = ss.Size
    ss.Size = UDim2.new(sz.X.Scale, sz.X.Offset, 0, n == 2 and 26 or 14)
    ss.TextWrapped = (n == 2)
    ss.TextYAlignment = n == 2 and Enum.TextYAlignment.Top or Enum.TextYAlignment.Center
    if not rec.slider then                              -- (o slider tem o titulo no alto e a barra embaixo: so cresce a caixa da legenda)
        local y0 = (rec.h - (n == 2 and 42 or 32)) / 2
        tt.Position = UDim2.fromOffset(tt.Position.X.Offset, y0)
        ss.Position = UDim2.fromOffset(ss.Position.X.Offset, y0 + (n == 2 and 17 or 18))
    end
end
function ORG.R(r, R)                                   -- reserva R pixels a direita (controle) e deixa o texto ocupar o resto
    local rec = ORG.of[r]
    if not rec then return end
    local w = -(R + rec.tx)
    rec.tt.Size = UDim2.new(1, w, rec.tt.Size.Y.Scale, rec.tt.Size.Y.Offset)
    rec.ss.Size = UDim2.new(1, w, rec.ss.Size.Y.Scale, rec.ss.Size.Y.Offset)
    rec.R = R
    ORG.fit(rec)
end
function ORG.ex(r, ...)                                -- elementos extras alinhados ao texto (barra, legenda...)
    local rec = ORG.of[r]
    if rec then for _, e in ipairs({ ... }) do rec.ex[#rec.ex + 1] = e end end
end
function ORG.on(r, v)
    local rec = ORG.of[r]
    if rec then
        local was = rec.on
        rec.on = v and true or false
        ORG.paint(rec)
        if was ~= rec.on and ORG.badge then ORG.badge(r.Parent) end
    end
end
function ORG.repaint()
    local live = {}
    for _, rec in ipairs(ORG.rows) do
        if rec.r.Parent then live[#live + 1] = rec; ORG.paint(rec) else ORG.of[rec.r] = nil end
    end
    ORG.rows = live
end
table.insert(TH.hooks, ORG.repaint)
function ORG.setStyle(s)
    if not ORG.TXS[s] then s = "Dot" end
    cfg.rowIcons = s
    local eff = (s == "Moon" and not ORG.moon) and "Dot" or s        -- sem a imagem da lua, cai para o ponto
    ORG.sty, ORG.tx = eff, ORG.TXS[eff]
    local live = {}
    for _, rec in ipairs(ORG.rows) do
        if rec.r.Parent then
            live[#live + 1] = rec
            ORG.glyph(rec)
            local d = ORG.tx - rec.tx
            if d ~= 0 and not rec.fixed then
                ORG.shift(rec.tt, d); ORG.shift(rec.ss, d)
                for _, e in ipairs(rec.ex) do ORG.shift(e, d) end
                rec.tx = ORG.tx
                ORG.fit(rec)                                  -- a caixa ficou mais estreita/larga: confere se a legenda ainda cabe em 2 linhas
            end
        else
            ORG.of[rec.r] = nil
        end
    end
    ORG.rows = live
end
-- troca o glifo de UMA linha (ex.: plano vitalicio vira infinito dourado no estilo Classic; nos outros so muda a cor)
function ORG.tint(r, col, img)
    local rec = ORG.of[r]
    if not rec then return end
    rec.tintCol = col
    if img and rec.kind == "img" then pcall(function() rec.gl.Image = img end) end
    ORG.paint(rec, true)
end

-- botao flutuante (reabrir): lua do Moon antigo, anel girando, brilho, estrelinhas, arrastavel
local fabAction
local fab = new("Frame", { Size = UDim2.fromOffset(56, 56), Position = UDim2.new(0, 14, 0.5, -28), BackgroundTransparency = 1, Visible = false, ZIndex = 20, Active = true }, gui)
;(function()
    local MOON_B64 = ""
    local function b64dec(data)
        local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
        local map = {}
        for i = 1, #alphabet do map[string.byte(alphabet, i)] = i - 1 end
        local out, bits, nbits = {}, 0, 0
        for i = 1, #data do
            local v = map[string.byte(data, i)]
            if v then
                bits = bits * 64 + v; nbits = nbits + 6
                if nbits >= 8 then
                    nbits = nbits - 8
                    local byte = math.floor(bits / 2 ^ nbits)
                    bits = bits - byte * 2 ^ nbits
                    out[#out + 1] = string.char(byte)
                end
            end
        end
        return table.concat(out)
    end
    local sc = new("UIScale", { Scale = 1 }, fab)
    -- brilho pulsante atras
    local glow = new("Frame", { Size = UDim2.fromOffset(74, 74), Position = UDim2.fromOffset(-9, -9), BackgroundColor3 = TH.cur.acc, BackgroundTransparency = 0.85, BorderSizePixel = 0, ZIndex = 19 }, fab)
    corner(glow, 37)
    local body = new("TextButton", { Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.fromRGB(12, 14, 24), BackgroundTransparency = 0.08, Text = "", AutoButtonColor = false, BorderSizePixel = 0, ZIndex = 20 }, fab)
    corner(body, 28)
    grad(body, Color3.fromRGB(30, 34, 56), Color3.fromRGB(8, 9, 16), 60)
    -- anel com degrade que gira
    local ring = stroke(body, C.white, 2.5, 0)
    local ringG = new("UIGradient", { Color = ColorSequence.new({ ColorSequenceKeypoint.new(0, C.white), ColorSequenceKeypoint.new(0.5, TH.cur.acc), ColorSequenceKeypoint.new(1, C.white) }) }, ring)
    local inner = new("Frame", { Size = UDim2.new(1, -10, 1, -10), Position = UDim2.fromOffset(5, 5), BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 21 }, body)
    corner(inner, 23); stroke(inner, C.white, 1, 0.85)
    -- estrelinhas
    local stars = {}
    for i, p in ipairs({ { 10, 12, 3 }, { 42, 9, 2 }, { 45, 40, 3 }, { 9, 42, 2 } }) do
        local st = new("Frame", { Size = UDim2.fromOffset(p[3], p[3]), Position = UDim2.fromOffset(p[1], p[2]), BackgroundColor3 = C.white, BackgroundTransparency = 0.4, BorderSizePixel = 0, Rotation = 45, ZIndex = 22 }, body)
        stars[i] = st
    end
    -- lua (imagem do Moon antigo)
    local moon = new("ImageLabel", { Size = UDim2.fromOffset(34, 34), AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), BackgroundTransparency = 1, ScaleType = Enum.ScaleType.Fit, ZIndex = 23 }, body)
    local okImg = false
    if writefile and getcustomasset then
        okImg = pcall(function() writefile("MoonHub_moon.png", b64dec(MOON_B64)); moon.Image = getcustomasset("MoonHub_moon.png") end)
    end
    if not okImg then
        text(moon, { Size = UDim2.fromScale(1, 1), Text = "\u{263E}", TextSize = 28, TextXAlignment = Enum.TextXAlignment.Center, ZIndex = 24 })
    else
        ORG.moon = moon.Image                                   -- a mesma lua serve de icone das linhas (estilo "Moon")
    end
    table.insert(TH.hooks, function()
        local a = TH.cur.acc
        ringG.Color = ColorSequence.new({ ColorSequenceKeypoint.new(0, C.white), ColorSequenceKeypoint.new(0.5, a), ColorSequenceKeypoint.new(1, C.white) })
        tween(glow, 0.4, { BackgroundColor3 = a })
    end)
    -- animacao ociosa
    local t0 = 0
    table.insert(conns, RunService.Heartbeat:Connect(function(dt)
        if not fab.Visible then return end
        t0 = t0 + dt
        ringG.Rotation = (t0 * 90) % 360
        glow.BackgroundTransparency = 0.86 + math.sin(t0 * 2.2) * 0.06
        local spin = fab:GetAttribute("spin")
        if not spin then moon.Rotation = math.sin(t0 * 1.6) * 7 end
        for i, st in ipairs(stars) do st.BackgroundTransparency = 0.45 + math.sin(t0 * 3 + i * 1.7) * 0.4 end
    end))
    -- arrastar / clicar
    local dragging, moved, startPos, startIn, hover = false, false, nil, nil, false
    body.InputBegan:Connect(function(input)
        local ut = input.UserInputType
        if ut == Enum.UserInputType.MouseButton1 or ut == Enum.UserInputType.Touch then
            dragging, moved, startPos, startIn = true, false, fab.Position, input.Position
            tween(sc, 0.1, { Scale = 0.88 })
        elseif ut == Enum.UserInputType.MouseMovement then
            hover = true; tween(sc, 0.2, { Scale = 1.08 }, Enum.EasingStyle.Back)
        end
    end)
    body.MouseLeave:Connect(function() hover = false; if not dragging then tween(sc, 0.2, { Scale = 1 }) end end)
    table.insert(conns, UIS.InputChanged:Connect(function(input)
        if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
            local d = input.Position - startIn
            if d.Magnitude > 8 then moved = true end
            if moved then
                local cam = workspace.CurrentCamera
                local vs = cam and cam.ViewportSize or Vector2.new(800, 600)
                fab.Position = UDim2.fromOffset(math.clamp(startPos.X.Offset + d.X, 0, vs.X - 56), math.clamp((startPos.Y.Scale ~= 0 and startPos.Y.Scale * vs.Y or 0) + startPos.Y.Offset + d.Y, 0, vs.Y - 56))
            end
        end
    end))
    table.insert(conns, UIS.InputEnded:Connect(function(input)
        if dragging and (input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch) then
            dragging = false
            tween(sc, 0.25, { Scale = hover and 1.08 or 1 }, Enum.EasingStyle.Back)
            if not moved then
                fab:SetAttribute("spin", true)
                moon.Rotation = 0
                tween(moon, 0.45, { Rotation = 360 }, Enum.EasingStyle.Back)
                task.delay(0.1, function() if fabAction then fabAction() end end)
                task.delay(0.5, function() fab:SetAttribute("spin", nil) end)
            end
        end
    end))
end)()

-- raiz (move janela + cartao de perfil juntos)
local W, H = 660, 476
local root = new("Frame", { Size = UDim2.fromOffset(W, H), Position = UDim2.fromScale(0.5, 0.5), AnchorPoint = Vector2.new(0.5, 0.5), BackgroundTransparency = 1 }, gui)
local rootScale = new("UIScale", { Scale = 0.93 }, root)
tween(rootScale, 0.55, { Scale = 1 })
local win = new("Frame", { Size = UDim2.fromScale(1, 1), BorderSizePixel = 0, ClipsDescendants = true, Active = true }, root)
bind(win, "BackgroundColor3", "win"); bind(win, "BackgroundTransparency", "winT")
-- Formato da janela. O ClipsDescendants do Roblox corta em RETANGULO (nao acompanha o canto arredondado), por isso
-- tudo que encosta nos cantos (degrade do tema, imagem de fundo, cartao de perfil) recebe o MESMO raio da janela,
-- e a borda e um quadro transparente POR CIMA de tudo (irmao da janela, fora do corte), nao mais um UIStroke
-- escondido atras do conteudo.
local SHAPE = { R = 16, list = {}, set = {}, pads = {} }
function SHAPE.add(c) SHAPE.list[#SHAPE.list + 1] = c; SHAPE.set[c] = true; pcall(function() c.CornerRadius = UDim.new(0, SHAPE.R) end); return c end
local winBorder = new("Frame", { Name = "WinBorder", Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 60, Active = false }, root)
pcall(function() winBorder.Interactable = false end)
SHAPE.add(corner(win, SHAPE.R)); SHAPE.add(corner(winBorder, SHAPE.R))
local winStroke = stroke(winBorder, C.white, 1.5, 0.45)
local winG = grad(winStroke, C.white, C.blue, 0)
winG.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0), NumberSequenceKeypoint.new(1, 0.5) })
-- raio grande: afasta titulo/botoes/rodape do canto para nao ficarem fora da curva
function SHAPE.apply(r)
    r = math.clamp(math.floor((tonumber(r) or 16) + 0.5), 0, 60)
    SHAPE.R = r
    for _, c in ipairs(SHAPE.list) do pcall(function() c.CornerRadius = UDim.new(0, r) end) end
    local e = math.max(0, (r - 14) * 0.55)
    local P = SHAPE.pads
    pcall(function()
        if P.top then P.top.PaddingLeft = UDim.new(0, e); P.top.PaddingRight = UDim.new(0, e) end
        if P.side then P.side.PaddingLeft = UDim.new(0, math.max(0, (r - 40) * 0.5)); P.side.PaddingBottom = UDim.new(0, e * 0.8) end   -- so o rodape chega perto do canto: a lista de abas nao precisa de folga
        if P.content then P.content.PaddingRight = UDim.new(0, e * 0.6); P.content.PaddingBottom = UDim.new(0, e * 0.8) end
    end)
end

