-- ============================================================== estado ====
local State = {
    info = S.info or {}, user = S.user or {}, token = S.token,
    exp = nil, rw = nil, totalSecs = nil, online = true,
}
local function applyInfo(info)
    State.info = info
    local t = os.time()
    State.exp = (not info.lifetime and info.expires_in) and (t + info.expires_in) or nil
    State.rw = (info.rewhid_in and info.rewhid_in > 0) and (t + info.rewhid_in) or nil
    if State.exp and not State.totalSecs then
        local d = info.expires_in / 86400
        local plan = d <= 1.01 and 1 or d <= 7.01 and 7 or d <= 30.01 and 30 or d <= 90.01 and 90 or d <= 180.01 and 180 or 365
        State.totalSecs = plan * 86400
    end
end
applyInfo(State.info)
-- plano B: se o perfil do Discord nao veio, usa os dados do Roblox
;(function()
    local U = State.user
    if (U.name or "") == "" then U.name = LP.Name end
    if (U.display or "") == "" then U.display = LP.DisplayName ~= "" and LP.DisplayName or LP.Name end
    if not U.avatarAsset then U.avatarAsset = "rbxthumb://type=AvatarHeadShot&id=" .. tostring(LP.UserId) .. "&w=150&h=150" end
end)()
local function fmtLeft(sec)
    sec = math.max(0, math.floor(sec))
    local d = math.floor(sec / 86400); sec = sec % 86400
    local h = math.floor(sec / 3600); sec = sec % 3600
    local m = math.floor(sec / 60); local s = sec % 60
    if d > 0 then return string.format("%dd %02dh %02dm %02ds", d, h, m, s) end
    return string.format("%02dh %02dm %02ds", h, m, s)
end
local function fmtShort(sec)
    sec = math.max(0, math.floor(sec))
    local d = math.floor(sec / 86400); local h = math.floor(sec % 86400 / 3600); local m = math.floor(sec % 3600 / 60)
    if d > 0 then return d .. "d " .. h .. "h" end
    if h > 0 then return h .. "h " .. m .. "m" end
    return math.max(1, m) .. "m"
end
local function planName()
    if State.info.lifetime then return "Lifetime" end
    local d = State.totalSecs and math.floor(State.totalSecs / 86400 + 0.5) or 0
    if d == 7 then return "7 days" elseif d == 1 then return "1 day" elseif d > 0 then return d .. " days" end
    return TIER_LABEL
end

