-- ======================================================== componentes ====
ORG.setStyle(cfg.rowIcons)
local ROW_H = 56
-- linha: glifo (igual em todas) + titulo + subtitulo (contorno que acende ao passar o mouse).
-- opt: { fixed = true } a linha cuida do proprio layout (cartao de perfil); { noGl = true } sem glifo.
local function row(parent, iconId, title, sub, height, order, opt)
    height = height or ROW_H
    local r = new("Frame", { Size = UDim2.new(1, 0, 0, height), BorderSizePixel = 0, LayoutOrder = order or 1, ZIndex = 4 }, parent)
    bind(r, "BackgroundColor3", "row"); bind(r, "BackgroundTransparency", "rowT")
    corner(r, 11)
    local st = stroke(r, C.white, 1, 0.9)
    bind(st, "Color", "rowS"); bind(st, "Transparency", "rowST")
    local rec = { r = r, id = iconId, h = height, tx = ORG.tx, ex = {}, fixed = opt and opt.fixed, noGl = opt and opt.noGl, sub = sub }
    ORG.rows[#ORG.rows + 1] = rec; ORG.of[r] = rec
    -- v92: hover um pouco mais "vivo" - alem do contorno, a propria linha clareia levemente (sem mexer em Position/Size,
    -- que ia brigar com o UIListLayout) e volta suave com Sine, pra nao parecer um "liga/desliga" seco
    r.MouseEnter:Connect(function()
        tween(st, 0.2, { Transparency = math.max(0, TH.cur.rowST - 0.18) }, Enum.EasingStyle.Sine)
        tween(r, 0.22, { BackgroundTransparency = math.max(0, TH.cur.rowT - 0.045) }, Enum.EasingStyle.Sine)
        rec.hov = true; ORG.paint(rec)
    end)
    r.MouseLeave:Connect(function()
        tween(st, 0.32, { Transparency = TH.cur.rowST }, Enum.EasingStyle.Sine)
        tween(r, 0.32, { BackgroundTransparency = TH.cur.rowT }, Enum.EasingStyle.Sine)
        rec.hov = false; ORG.paint(rec)
    end)
    ORG.glyph(rec)
    local tx = rec.tx
    local tt = text(r, { Position = UDim2.fromOffset(tx, (height - 32) / 2), Size = UDim2.new(1, -(116 + tx), 0, 16), Text = title, TextSize = 13, ZIndex = 5, RichText = true, TextTruncate = Enum.TextTruncate.AtEnd })
    local ss = text(r, { Position = UDim2.fromOffset(tx, (height - 32) / 2 + 18), Size = UDim2.new(1, -(116 + tx), 0, 14), Text = sub or "", TextSize = 11, Font = Enum.Font.Gotham, TextColor3 = C.dim2, ZIndex = 5, TextTruncate = Enum.TextTruncate.AtEnd })
    if not sub or sub == "" then tt.Position = UDim2.fromOffset(tx, 0); tt.Size = UDim2.new(1, -(116 + tx), 1, 0) end
    rec.tt, rec.ss = tt, ss
    return r, tt, ss, rec.gl
end

-- titulo de secao: clica para dobrar/abrir (o estado fica salvo). Os itens da secao sao os que vem depois dela (LayoutOrder) ate a proxima.
local function section(parent, title, order)
    local t = ORG.tabOf[parent]
    local f = new("TextButton", { Size = UDim2.new(1, 0, 0, 26), BackgroundTransparency = 1, Text = "", AutoButtonColor = false, LayoutOrder = order or 1, ZIndex = 4 }, parent)
    local up = string.upper(title)
    local w = measure(up, 10, Enum.Font.GothamBold)
    local lx = t and 24 or 4
    local chev
    if t then
        chev = new("Frame", { Size = UDim2.fromOffset(12, 12), Position = UDim2.fromOffset(5, 7), BackgroundTransparency = 1, ZIndex = 5 }, f)
        for _, d in ipairs({ { 3.6, 48 }, { 8.4, -48 } }) do
            local b = new("Frame", { Size = UDim2.fromOffset(7, 2), AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromOffset(d[1], 6.5), Rotation = d[2], BorderSizePixel = 0, ZIndex = 5 }, chev)
            corner(b, 1); bind(b, "BackgroundColor3", "dim")
        end
    end
    local lab = text(f, { Position = UDim2.fromOffset(lx, 0), Size = UDim2.fromOffset(w + 8, 26), Text = up, TextSize = 10, TextColor3 = C.dim, ZIndex = 5 })
    local ln = new("Frame", { Size = UDim2.new(1, -(lx + w + 52), 0, 1), Position = UDim2.fromOffset(lx + w + 14, 13), BorderSizePixel = 0, ZIndex = 5 }, f)
    bind(ln, "BackgroundColor3", "line"); bind(ln, "BackgroundTransparency", "lineT")
    local cnt = text(f, { Position = UDim2.new(1, -34, 0, 0), Size = UDim2.fromOffset(34, 26), Text = "", TextSize = 10, TextColor3 = C.dim, TextXAlignment = Enum.TextXAlignment.Right, ZIndex = 5 })
    if t then
        local h = { f = f, title = title, key = (t.name or "?") .. "|" .. string.lower(title), chev = chev, cnt = cnt, lab = lab, tab = t }
        ORG.isHead[f] = h
        local list = ORG.heads[parent]
        if not list then list = {}; ORG.heads[parent] = list end
        list[#list + 1] = h; h.i = #list
        f.MouseButton1Click:Connect(function() ORG.toggle(t, h) end)
        f.MouseEnter:Connect(function() tween(lab, 0.15, { TextColor3 = TH.cur.text }) end)
        f.MouseLeave:Connect(function() tween(lab, 0.2, { TextColor3 = TH.cur.dim }) end)
    end
    return f
end

-- botao pequeno com contorno
local function smallButton(parent, label, w, x, primary)
    local b = new("TextButton", { Size = UDim2.fromOffset(w, 28), Position = x, BackgroundColor3 = primary and C.blue or C.white, BackgroundTransparency = primary and 0 or 0.9, Text = label, Font = Enum.Font.GothamBold, TextSize = 11, TextColor3 = C.white, AutoButtonColor = false, ZIndex = 7 }, parent)
    corner(b, 9)
    if primary then grad(b, Color3.fromRGB(80, 158, 255), C.blue2, 90) else local s = stroke(b, C.white, 1, 0.75); bind(s, "Color", "rowS") end
    if not primary then bind(b, "TextColor3", "text") end
    b.MouseEnter:Connect(function() tween(b, 0.15, { BackgroundTransparency = primary and 0.12 or 0.8 }) end)
    b.MouseLeave:Connect(function() tween(b, 0.2, { BackgroundTransparency = primary and 0 or 0.9 }) end)
    UI.press(b)
    return b
end

-- interruptor animado
local function mkToggle(parent, iconId, title, sub, order, initial, onChange)
    local r = row(parent, iconId, title, sub, ORG.h(sub), order)
    ORG.R(r, 76)
    local TW, TH_, KS = 54, 28, 22
    -- trilho (pill) com brilho interno, contorno e icone de estado
    local track = new("Frame", { Size = UDim2.fromOffset(TW, TH_), Position = UDim2.new(1, -(TW + 14), 0.5, -TH_ / 2), BorderSizePixel = 0, ZIndex = 6, ClipsDescendants = true }, r)
    corner(track, TH_ / 2)
    local tst = stroke(track, C.white, 1.2, 0.7)
    -- (o brilho tem o MESMO formato do trilho: ClipsDescendants corta em retangulo e nao no canto arredondado)
    local sheen = new("Frame", { Size = UDim2.fromScale(1, 1), BackgroundColor3 = C.white, BackgroundTransparency = 0.88, BorderSizePixel = 0, ZIndex = 6 }, track)
    corner(sheen, TH_ / 2)
    grad(sheen, Color3.fromRGB(255, 255, 255), Color3.fromRGB(255, 255, 255), 90).Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.35), NumberSequenceKeypoint.new(0.6, 1), NumberSequenceKeypoint.new(1, 1) })
    -- marca "off" (x apagado) a esquerda e "on" (check) a direita, atras do botao
    local offMark = new("Frame", { Size = UDim2.fromOffset(8, 2), Position = UDim2.new(1, -17, 0.5, -1), BackgroundColor3 = C.white, BackgroundTransparency = 0.6, BorderSizePixel = 0, ZIndex = 6 }, track)
    corner(offMark, 1)
    local onMark = new("ImageLabel", { Size = UDim2.fromOffset(13, 13), Position = UDim2.fromOffset(8, 7), BackgroundTransparency = 1, Image = ICON.check, ImageColor3 = C.white, ImageTransparency = 1, ZIndex = 6 }, track)
    -- botao (knob) com sombra suave
    local shadow = new("Frame", { Size = UDim2.fromOffset(KS + 4, KS + 4), Position = UDim2.fromOffset(2, 3), BackgroundColor3 = Color3.new(0, 0, 0), BackgroundTransparency = 0.78, BorderSizePixel = 0, ZIndex = 6 }, track)
    corner(shadow, (KS + 4) / 2)
    local knob = new("Frame", { Size = UDim2.fromOffset(KS, KS), Position = UDim2.fromOffset(3, 3), BackgroundColor3 = C.white, BorderSizePixel = 0, ZIndex = 7 }, track)
    corner(knob, KS / 2)
    grad(knob, Color3.fromRGB(255, 255, 255), Color3.fromRGB(214, 220, 232), 90)
    local kst = stroke(knob, C.white, 1, 0.8)
    local dotv = new("Frame", { Size = UDim2.fromOffset(6, 6), Position = UDim2.new(0.5, -3, 0.5, -3), BackgroundColor3 = C.white, BackgroundTransparency = 0.2, BorderSizePixel = 0, ZIndex = 8 }, knob)
    corner(dotv, 3)
    local btn = new("TextButton", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Text = "", AutoButtonColor = false, ZIndex = 9 }, r)
    local obj = { on = initial and true or false }
    local down, hover = false, false
    local function render(animate)
        local t = animate and 0.34 or 0
        local w = down and (KS + 6) or KS
        local x = obj.on and (TW - 3 - w) or 3
        tween(track, t, { BackgroundColor3 = obj.on and TH.cur.acc or TH.cur.track }, Enum.EasingStyle.Quint)
        tween(knob, animate and 0.3 or 0, { Position = UDim2.fromOffset(x, 3), Size = UDim2.fromOffset(w, KS) }, Enum.EasingStyle.Back)
        tween(shadow, animate and 0.3 or 0, { Position = UDim2.fromOffset(x - 2, 4), Size = UDim2.fromOffset(w + 4, KS + 4) }, Enum.EasingStyle.Back)
        tween(tst, t, { Transparency = obj.on and 0.25 or (hover and 0.5 or 0.72) })
        tween(sheen, t, { BackgroundTransparency = obj.on and 0.8 or 0.9 })
        tween(onMark, t, { ImageTransparency = obj.on and 0.05 or 1 })
        tween(offMark, t, { BackgroundTransparency = obj.on and 1 or 0.6 })
        tween(dotv, t, { BackgroundColor3 = obj.on and TH.cur.acc or Color3.fromRGB(150, 158, 175), BackgroundTransparency = obj.on and 0 or 0.25 })
        tween(kst, t, { Transparency = hover and 0.4 or 0.8 })
        ORG.on(r, obj.on)
    end
    render(false)
    table.insert(TH.hooks, function() render(true) end)
    function obj.set(v, silent) obj.on = v and true or false; render(true); if not silent and onChange then onChange(obj.on) end end
    btn.MouseButton1Down:Connect(function() down = true; render(true) end)
    btn.MouseButton1Up:Connect(function() down = false end)
    btn.MouseEnter:Connect(function() hover = true; render(true) end)
    btn.MouseLeave:Connect(function() hover = false; if down then down = false; render(true) end end)
    btn.MouseButton1Click:Connect(function() down = false; obj.set(not obj.on) end)
    obj.row = r
    return obj
end

-- ======================================================== abas / paginas ====
local TAB_H, TAB_GAP, HEAD_H = 40, 4, 26
-- barra lateral com rolagem e grupos. As posicoes sao calculadas aqui (sem esperar o UIListLayout), assim o destaque nunca erra.
local tabArea = new("ScrollingFrame", { Size = UDim2.new(1, -24, 1, -118), Position = UDim2.fromOffset(12, 68), BackgroundTransparency = 1, BorderSizePixel = 0,
    ScrollBarThickness = 2, ScrollBarImageColor3 = Color3.fromRGB(130, 135, 155), CanvasSize = UDim2.fromOffset(0, 0), ScrollingDirection = Enum.ScrollingDirection.Y,
    ZIndex = 4, ClipsDescendants = true, ElasticBehavior = Enum.ElasticBehavior.Never }, side)
local hl = new("Frame", { Size = UDim2.new(1, -4, 0, TAB_H), Position = UDim2.fromOffset(0, 0), BorderSizePixel = 0, ZIndex = 3 }, tabArea)
bind(hl, "BackgroundColor3", "hl"); bind(hl, "BackgroundTransparency", "hlT")
corner(hl, 10)
local hlStroke = stroke(hl, C.white, 1, 0.7)
local hlBar = new("Frame", { Size = UDim2.fromOffset(3, 20), Position = UDim2.fromOffset(-1, 10), BorderSizePixel = 0, ZIndex = 5 }, hl)
bind(hlBar, "BackgroundColor3", "acc")
corner(hlBar, 2)

local tabs, curTab = {}, nil
local heads = {}
local function headFor(g)
    local h = heads[g]
    if h then return h end
    h = new("Frame", { Size = UDim2.new(1, -4, 0, HEAD_H), BackgroundTransparency = 1, ZIndex = 4 }, tabArea)
    local w = measure(string.upper(g), 9, Enum.Font.GothamBold)
    text(h, { Position = UDim2.fromOffset(6, 6), Size = UDim2.fromOffset(w + 6, 16), Text = string.upper(g), TextSize = 9, TextColor3 = C.dim, ZIndex = 5 })
    local ln = new("Frame", { Size = UDim2.new(1, -(w + 24), 0, 1), Position = UDim2.fromOffset(w + 16, 14), BorderSizePixel = 0, ZIndex = 5 }, h)
    bind(ln, "BackgroundColor3", "line"); bind(ln, "BackgroundTransparency", "lineT")
    heads[g] = h
    return h
end
local function relayout()
    local y, lastG = 0, nil
    for _, h in pairs(heads) do h.Visible = false end
    for _, t in ipairs(tabs) do
        if t.group ~= lastG then
            lastG = t.group
            local h = headFor(t.group)
            h.Visible = true; h.Position = UDim2.fromOffset(0, y); y += HEAD_H
        end
        t.y = y
        t.btn.Position = UDim2.fromOffset(0, y)
        y += TAB_H + TAB_GAP
    end
    tabArea.CanvasSize = UDim2.fromOffset(0, y)
    if curTab and curTab.y then hl.Position = UDim2.fromOffset(0, curTab.y) end
end
local function tabColors()
    for _, o in ipairs(tabs) do
        local on = o == curTab
        local col = on and TH.cur.text or TH.cur.dim
        tween(o.lab, 0.25, { TextColor3 = col })
        tween(o.ico, 0.25, { ImageColor3 = col })
    end
end
table.insert(TH.hooks, tabColors)
local function selectTab(t, instant)
    if curTab == t then return end
    local prev = curTab
    curTab = t
    if t.lazy then local f = t.lazy; t.lazy = nil; local ok, e = pcall(f); if not ok then warn("[Moon Hub] " .. t.name .. ": " .. tostring(e)) end end
    pcall(ORG.open, t)
    relayout()
    tween(hl, instant and 0 or 0.38, { Position = UDim2.fromOffset(0, t.y or 0) }, Enum.EasingStyle.Quint)
    -- mantem a aba escolhida visivel na lateral
    do
        local vh = tabArea.AbsoluteSize.Y
        if vh < 60 then vh = 300 end
        local cp = tabArea.CanvasPosition.Y
        local top, bot = (t.y or 0) - HEAD_H, (t.y or 0) + TAB_H + 6
        local target = cp
        if top < cp then target = math.max(0, top) elseif bot > cp + vh then target = bot - vh end
        if target ~= cp then tween(tabArea, instant and 0 or 0.3, { CanvasPosition = Vector2.new(0, target) }, Enum.EasingStyle.Quint) end
    end
    tabColors()
    if prev then
        local pp = prev.page
        tween(pp, 0.14, { GroupTransparency = 1 }, Enum.EasingStyle.Quad)
        task.delay(0.15, function() if curTab ~= prev then pp.Visible = false end end)
    end
    t.page.Visible = true
    t.page.GroupTransparency = 1
    t.page.Position = UDim2.fromOffset(0, 12)
    tween(t.page, 0.38, { GroupTransparency = 0, Position = UDim2.fromOffset(0, 0) }, Enum.EasingStyle.Quint)
end
local function addTab(name, iconId, group)
    local btn = new("TextButton", { Size = UDim2.new(1, -4, 0, TAB_H), BackgroundTransparency = 1, Text = "", AutoButtonColor = false, ZIndex = 6 }, tabArea)
    local ico = new("ImageLabel", { Size = UDim2.fromOffset(18, 18), Position = UDim2.fromOffset(16, 11), BackgroundTransparency = 1, Image = iconId, ImageColor3 = TH.cur.dim, ZIndex = 7 }, btn)
    local lab = new("TextLabel", { Position = UDim2.fromOffset(46, 0), Size = UDim2.new(1, -52, 1, 0), BackgroundTransparency = 1, Text = name, TextSize = 12, Font = Enum.Font.GothamMedium, TextColor3 = TH.cur.dim, TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd, ZIndex = 7 }, btn)
    local page = new("CanvasGroup", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Visible = false, ZIndex = 3 }, content)
    text(page, { Position = UDim2.fromOffset(24, 4), Size = UDim2.new(1, -48, 0, 34), Text = name, TextSize = 24, ZIndex = 4 })
    local scroll = new("ScrollingFrame", { Size = UDim2.new(1, 0, 1, -48), Position = UDim2.fromOffset(0, 46), BackgroundTransparency = 1, BorderSizePixel = 0, ScrollBarThickness = 3, ScrollBarImageColor3 = Color3.fromRGB(130, 135, 155), CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.Y, ZIndex = 3 }, page)
    pad(scroll, 24, 2, 24, 18)
    list(scroll, 8)
    scroll.MouseEnter:Connect(function() scroll.ScrollBarThickness = 5 end)
    scroll.MouseLeave:Connect(function() scroll.ScrollBarThickness = 3 end)
    local t = { name = name, btn = btn, ico = ico, lab = lab, page = page, body = scroll, group = group or "Main" }
    t.noSearch = (name == "Account" or name == "Credits")
    ORG.tabOf[scroll] = t
    table.insert(tabs, t)
    relayout()
    btn.MouseButton1Click:Connect(function() selectTab(t) end)
    btn.MouseEnter:Connect(function() if curTab ~= t then tween(lab, 0.15, { TextColor3 = TH.cur.text }); tween(ico, 0.15, { ImageColor3 = TH.cur.text, Position = UDim2.fromOffset(19, 11) }, Enum.EasingStyle.Back) end end)
    btn.MouseLeave:Connect(function() if curTab ~= t then tween(lab, 0.2, { TextColor3 = TH.cur.dim }); tween(ico, 0.2, { ImageColor3 = TH.cur.dim, Position = UDim2.fromOffset(16, 11) }) end end)
    UI.press(btn)
    return t
end
-- ordem final das abas: spec = { {grupo, {nomes...}}, ... }; o que nao estiver na lista vai para "More"
local function sortTabs(spec)
    local place = {}
    for gi, g in ipairs(spec) do
        for ni, n in ipairs(g[2]) do place[n] = { gi, ni, g[1] } end
    end
    local keyed = {}
    for i, t in ipairs(tabs) do
        local pl = place[t.name]
        if pl then t.group = pl[3] end
        keyed[i] = { t, pl and pl[1] or 99, pl and pl[2] or 99, i }
        if not pl then t.group = t.group == "Main" and "More" or t.group end
    end
    table.sort(keyed, function(a, b)
        if a[2] ~= b[2] then return a[2] < b[2] end
        if a[3] ~= b[3] then return a[3] < b[3] end
        return a[4] < b[4]
    end)
    for i, k in ipairs(keyed) do tabs[i] = k[1] end
    relayout()
    if curTab then hl.Position = UDim2.fromOffset(0, curTab.y or 0) end
end

-- ---------- organizacao: dobrar secoes, busca, ordem das secoes ----------
function ORG.text(it)                                  -- todo o texto de um item (titulo, legenda, botoes), minusculo e sem tags
    local parts = {}
    pcall(function()
        if it:IsA("TextLabel") or it:IsA("TextButton") then local x = it.Text; if type(x) == "string" then parts[1] = x end end
        for _, d in ipairs(it:GetDescendants()) do
            if d:IsA("TextLabel") or d:IsA("TextButton") then
                local x = d.Text
                if type(x) == "string" and x ~= "" then parts[#parts + 1] = x end
            end
        end
    end)
    return (string.gsub(string.lower(table.concat(parts, " ")), "<[^>]*>", ""))
end
function ORG.isFolded(h)
    local v = cfg.fold[h.key]
    if v == nil then v = ORG.defFold[h.key] end
    return v and true or false
end
function ORG.toggle(t, h)
    cfg.fold[h.key] = not ORG.isFolded(h)
    persist()
    ORG.refresh(t, true)
end
-- v24: dobrar/abrir uma secao anima as linhas em cascata (dobrando: a altura de cada linha vai a zero e ela some no fim; abrindo: o contrario).
-- So quando o usuario mexe na secao e a aba esta na tela; busca, troca de aba e carga de modulo continuam instantaneas.
ORG.anim = {}
function ORG.endAnim(t)                                -- termina na hora a animacao em andamento da aba e deixa tudo no estado final
    local a = ORG.anim[t]
    if not a then return end
    ORG.anim[t] = nil
    a.dead = true
    for _, tw in ipairs(a.tws) do pcall(function() tw:Cancel() end) end
    for row, st in pairs(a.rows) do
        pcall(function()
            row.Size = st.sz
            row.ClipsDescendants = st.clip
            if row.Visible ~= st.vis then row.Visible = st.vis end
        end)
    end
end
function ORG.runAnim(t, diff)
    local a = { rows = {}, tws = {}, dead = false, left = 0 }
    ORG.anim[t] = a
    local n = #diff
    local sp = UI.speed
    local step = math.min(0.022, 0.3 / math.max(1, n))
    local function done(row)
        a.rows[row] = nil
        a.left = a.left - 1
        if a.left <= 0 and ORG.anim[t] == a then ORG.anim[t] = nil; a.dead = true end
    end
    for i, p in ipairs(diff) do
        local row, vis = p[1], p[2]
        local auto = false
        pcall(function() auto = row.AutomaticSize ~= nil and row.AutomaticSize ~= Enum.AutomaticSize.None end)
        if auto then
            row.Visible = vis                          -- (linha de altura automatica nao anima: entra/sai direto)
        else
            local sz = row.Size
            local st = { sz = sz, clip = row.ClipsDescendants, vis = vis }
            a.rows[row] = st
            a.left = a.left + 1
            local zero = UDim2.new(sz.X.Scale, sz.X.Offset, 0, 0)
            task.delay((i - 1) * step * sp, function()
                if a.dead then return end
                row.ClipsDescendants = true
                if vis then
                    row.Size = zero
                    row.Visible = true
                    a.tws[#a.tws + 1] = tween(row, 0.3, { Size = sz }, Enum.EasingStyle.Quint)
                    task.delay(0.3 * sp + 0.03, function()
                        if a.dead then return end
                        row.Size = sz
                        row.ClipsDescendants = st.clip
                        done(row)
                    end)
                else
                    a.tws[#a.tws + 1] = tween(row, 0.2, { Size = zero }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
                    task.delay(0.2 * sp + 0.03, function()
                        if a.dead then return end
                        row.Visible = false
                        row.Size = sz
                        row.ClipsDescendants = st.clip
                        done(row)
                    end)
                end
            end)
        end
    end
end
-- recalcula o que aparece na aba: secoes dobradas escondem seus itens; com busca, so os itens que combinam (e as secoes deles)
function ORG.refresh(t, animate)
    ORG.endAnim(t)
    local body = t.body
    local q = ORG.query[t] or ""
    local hs = {}
    for _, h in ipairs(ORG.heads[body] or {}) do if h.f.Parent then hs[#hs + 1] = h end end
    table.sort(hs, function(a, b)
        local oa, ob = a.f.LayoutOrder, b.f.LayoutOrder
        if oa ~= ob then return oa < ob end
        return a.i < b.i
    end)
    local bar = t.bar and t.bar.f
    local plan, any, cnt = {}, {}, {}
    for _, c in ipairs(body:GetChildren()) do
        if c ~= bar and c:IsA("GuiObject") and type(c.LayoutOrder) == "number" and not ORG.isHead[c] then
            local o, sec = c.LayoutOrder, nil
            for _, x in ipairs(hs) do if x.f.LayoutOrder < o then sec = x else break end end
            local vis
            if q == "" then vis = not (sec and ORG.isFolded(sec))
            elseif ORG.isSub[c] then vis = false
            else vis = string.find(ORG.text(c), q, 1, true) ~= nil end
            plan[#plan + 1] = { c, vis }
            if sec then cnt[sec] = (cnt[sec] or 0) + 1; if vis then any[sec] = true end end
        end
    end
    local diff = {}
    for _, p in ipairs(plan) do if p[1].Visible ~= p[2] then diff[#diff + 1] = p end end
    if #diff > 0 then
        if animate and not ORG.noAnim and UI.speed > 0 and #diff <= 36 and curTab == t then
            ORG.runAnim(t, diff)
        else
            for _, p in ipairs(diff) do p[1].Visible = p[2] end
        end
    end
    local nFold = 0
    for _, h in ipairs(hs) do
        local fd = ORG.isFolded(h)
        if fd then nFold = nFold + 1 end
        local show = (q == "") or any[h] == true
        if h.f.Visible ~= show then h.f.Visible = show end
        if h.fd ~= fd then h.fd = fd; tween(h.chev, 0.18, { Rotation = fd and -90 or 0 }) end
        local label = (fd and q == "") and tostring(cnt[h] or 0) or ""
        if h.cnt.Text ~= label then h.cnt.Text = label end
    end
    if t.bar then
        local lab = (#hs > 0 and nFold == #hs) and "Unfold all" or "Fold all"
        if t.bar.fb.Text ~= lab then t.bar.fb.Text = lab end
        t.bar.fb.Visible = #hs > 0
    end
end
-- v24: selo na aba da lateral com quantas funcoes dela estao ligadas (some quando nao tem nenhuma). So grupos de funcoes, nao as abas de configuracao.
function ORG.setBadge(t, n)
    local b = t.badge
    if n <= 0 then
        if b and b.n > 0 then
            b.n = 0
            tween(b.sc, 0.18, { Scale = 0.4 })
            tween(b.f, 0.18, { BackgroundTransparency = 1 })
            tween(b.l, 0.18, { TextTransparency = 1 })
        end
        return
    end
    if not b then
        local f = new("Frame", { Size = UDim2.fromOffset(20, 16), AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -10, 0.5, 0), BackgroundColor3 = TH.cur.acc,
            BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 8, Name = "Badge" }, t.btn)
        corner(f, 8)
        local sc = new("UIScale", { Scale = 0.4 }, f)
        local l = text(f, { Size = UDim2.fromScale(1, 1), Text = "", TextSize = 10, TextXAlignment = Enum.TextXAlignment.Center, TextColor3 = C.white, ZIndex = 9 })
        b = { f = f, l = l, sc = sc, n = 0 }
        t.badge = b
        bind(f, "BackgroundColor3", "acc")
        table.insert(TH.hooks, function()
            local a = TH.cur.acc
            b.l.TextColor3 = (a.R * 0.299 + a.G * 0.587 + a.B * 0.114) > 0.62 and Color3.fromRGB(12, 14, 22) or C.white
        end)
        b.l.TextColor3 = (TH.cur.acc.R * 0.299 + TH.cur.acc.G * 0.587 + TH.cur.acc.B * 0.114) > 0.62 and Color3.fromRGB(12, 14, 22) or C.white
    end
    local was = b.n
    b.n = n
    b.l.Text = n > 99 and "99+" or tostring(n)
    b.f.Size = UDim2.fromOffset(n > 9 and 26 or 20, 16)
    if was == 0 then
        tween(b.sc, 0.3, { Scale = 1 }, Enum.EasingStyle.Back)
        tween(b.f, 0.2, { BackgroundTransparency = 0 })
        tween(b.l, 0.2, { TextTransparency = 0 })
    end
end
ORG.noBadgeTab = { ["Farm Settings"] = true }          -- abas que so tem opcoes (nao funcoes): sem selo
function ORG.tabFor(o)                                 -- aba dona de uma linha (a linha pode estar dentro de uma caixa de altura automatica)
    for _ = 1, 4 do
        if not o then return nil end
        local t = ORG.tabOf[o]
        if t then return t end
        o = o.Parent
    end
end
function ORG.badge(inst)
    local t = ORG.tabFor(inst)
    if not t or t.badgeTk then return end
    t.badgeTk = true
    task.delay(0.15, function()
        t.badgeTk = nil
        if not alive then return end
        local n = 0
        if t.group ~= "Main" and t.group ~= "More" and not ORG.noBadgeTab[t.name] then
            for _, rec in ipairs(ORG.rows) do
                if rec.on and not rec.noBadge and rec.r.Parent and ORG.tabFor(rec.r) == t then n = n + 1 end
            end
        end
        ORG.setBadge(t, n)
    end)
end
function ORG.search(t, q)
    q = string.lower(tostring(q or ""))
    q = (string.gsub(string.gsub(q, "^%s+", ""), "%s+$", ""))
    if (ORG.query[t] or "") == q then return end
    ORG.query[t] = q
    ORG.refresh(t)
end
function ORG.foldAll(t, fold)
    for _, h in ipairs(ORG.heads[t.body] or {}) do cfg.fold[h.key] = fold and true or false end
    persist()
    ORG.refresh(t, true)
end
-- barra de busca no topo da aba (so e criada quando a aba abre pela primeira vez, para o script continuar leve)
function ORG.mountBar(t)
    if t.bar or t.noSearch then return end
    local f = new("Frame", { Size = UDim2.new(1, 0, 0, 34), BackgroundTransparency = 1, LayoutOrder = -1, ZIndex = 4, Name = "SearchBar" }, t.body)
    local box = new("TextBox", { Size = UDim2.new(1, -92, 0, 30), Position = UDim2.fromOffset(0, 2), BackgroundColor3 = C.white, BackgroundTransparency = 0.93, BorderSizePixel = 0,
        Text = "", PlaceholderText = "Search this tab...", PlaceholderColor3 = C.dim, Font = Enum.Font.GothamMedium, TextSize = 12, TextColor3 = C.text, ClearTextOnFocus = false,
        TextXAlignment = Enum.TextXAlignment.Left, ZIndex = 5 }, f)
    bind(box, "TextColor3", "text")
    corner(box, 9)
    local bs = stroke(box, C.white, 1, 0.85); bind(bs, "Color", "rowS")
    pad(box, 34, 0, 30, 0)
    -- lupa feita com formas (nao depende de imagem)
    local ring = new("Frame", { Size = UDim2.fromOffset(10, 10), Position = UDim2.fromOffset(12, 12), BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 6 }, f)
    corner(ring, 5); local rs = stroke(ring, C.dim, 1.6, 0); bind(rs, "Color", "dim")
    local hd = new("Frame", { Size = UDim2.fromOffset(6, 2), AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromOffset(23, 23), Rotation = 45, BorderSizePixel = 0, ZIndex = 6 }, f)
    corner(hd, 1); bind(hd, "BackgroundColor3", "dim")
    local clr = new("TextButton", { Size = UDim2.fromOffset(22, 22), Position = UDim2.new(1, -120, 0, 6), BackgroundTransparency = 1, Text = "", AutoButtonColor = false, Visible = false, ZIndex = 7 }, f)
    icon(clr, ICON.x, 12, C.icon, { Position = UDim2.fromOffset(5, 5), ZIndex = 8 })
    local fb = smallButton(f, "Fold all", 82, UDim2.new(1, -82, 0, 3), false)
    local tk = 0
    box:GetPropertyChangedSignal("Text"):Connect(function()
        clr.Visible = box.Text ~= ""
        tk = tk + 1
        local my = tk
        task.delay(0.12, function() if my == tk and alive then ORG.search(t, box.Text) end end)
    end)
    clr.MouseButton1Click:Connect(function() box.Text = "" end)
    fb.MouseButton1Click:Connect(function()
        local allFolded = false
        local hs = ORG.heads[t.body] or {}
        if #hs > 0 then
            allFolded = true
            for _, h in ipairs(hs) do if not ORG.isFolded(h) then allFolded = false break end end
        end
        ORG.foldAll(t, not allFolded)
    end)
    t.bar = { f = f, box = box, fb = fb, clr = clr }
end
-- ordem das secoes da aba (ORG.order[nome da aba] = { "titulo", "*", ... } em minusculas; "*" = o resto, na ordem em que estao)
function ORG.arrange(t)
    local spec = ORG.order[t.name]
    local heads = ORG.heads[t.body]
    if not spec or not heads or #heads < 2 then return end
    local bar = t.bar and t.bar.f
    local kids = {}
    for i, c in ipairs(t.body:GetChildren()) do
        if c ~= bar and c:IsA("GuiObject") and type(c.LayoutOrder) == "number" then kids[#kids + 1] = { c = c, o = c.LayoutOrder, i = i } end
    end
    table.sort(kids, function(a, b)
        if a.o ~= b.o then return a.o < b.o end
        return a.i < b.i
    end)
    local pre, blocks, cur = { items = {} }, {}, nil
    cur = pre
    for _, k in ipairs(kids) do
        local h = ORG.isHead[k.c]
        if h then cur = { h = h, items = { k.c } }; blocks[#blocks + 1] = cur
        else cur.items[#cur.items + 1] = k.c end
    end
    local used, seq = {}, {}
    for _, name in ipairs(spec) do
        if name == "*" then
            seq[#seq + 1] = "*"
        else
            for _, b in ipairs(blocks) do
                if not used[b] and string.lower(b.h.title) == name then used[b] = true; seq[#seq + 1] = b; break end
            end
        end
    end
    local rest = {}
    for _, b in ipairs(blocks) do if not used[b] then rest[#rest + 1] = b end end
    local out, star = {}, false
    for _, x in ipairs(seq) do
        if x == "*" then
            star = true
            for _, b in ipairs(rest) do out[#out + 1] = b end
        else
            out[#out + 1] = x
        end
    end
    if not star then for _, b in ipairs(rest) do out[#out + 1] = b end end
    local n = 0
    for _, c in ipairs(pre.items) do n = n + 1; c.LayoutOrder = n end
    for _, b in ipairs(out) do for _, c in ipairs(b.items) do n = n + 1; c.LayoutOrder = n end end
    for _, o in ipairs(t.objs or {}) do if o.n < n then o.n = n end end      -- itens que chegarem depois entram no fim
end
function ORG.open(t)
    ORG.mountBar(t)
    if not t.arr then t.arr = true; ORG.arrange(t) end
    ORG.refresh(t)
end
function ORG.settle(t)                                 -- conteudo novo chegou (modulo carregado): reordena e refaz a lista
    ORG.arrange(t)
    ORG.refresh(t)
end
function ORG.arrangeAll()
    for _, t in ipairs(tabs) do
        pcall(ORG.arrange, t)
        pcall(ORG.refresh, t)
    end
end

-- rodape da lateral: estado do servidor
local pingLab
;(function()
    local f = new("Frame", { Size = UDim2.new(1, -24, 0, 34), Position = UDim2.new(0, 12, 1, -44), BorderSizePixel = 0, ZIndex = 4 }, side)
    bind(f, "BackgroundColor3", "row"); bind(f, "BackgroundTransparency", "rowT")
    corner(f, 10)
    local fs = stroke(f, C.white, 1, 0.9); bind(fs, "Color", "rowS"); bind(fs, "Transparency", "rowST")
    local d = new("Frame", { Size = UDim2.fromOffset(8, 8), Position = UDim2.fromOffset(12, 13), BackgroundColor3 = C.ok, BorderSizePixel = 0, ZIndex = 5 }, f)
    corner(d, 4)
    task.spawn(function()
        while alive and d.Parent do
            tween(d, 0.9, { BackgroundTransparency = 0.6 }, Enum.EasingStyle.Sine); task.wait(0.95)
            tween(d, 0.9, { BackgroundTransparency = 0 }, Enum.EasingStyle.Sine); task.wait(0.95)
        end
    end)
    pingLab = text(f, { Position = UDim2.fromOffset(28, 0), Size = UDim2.new(1, -34, 1, 0), Text = "Server online", TextSize = 11, Font = Enum.Font.GothamMedium, TextColor3 = C.dim2, ZIndex = 5 })
end)()


-- ================================================== componentes compartilhados (UIX) ====
-- Usados por todas as abas: lista suspensa leve (monta as opcoes so ao abrir), slider com bolha,
-- caixa de texto, botao, paragrafo e seletor de cor. Um unico gerenciador de arrasto para todos os sliders.
local UIX = {}
;(function()
    local isPtr = function(i)
        local t = i.UserInputType
        return t == Enum.UserInputType.MouseButton1 or t == Enum.UserInputType.Touch
    end
    -- remove do tema as ligacoes (bind) de uma arvore que vai ser destruida (evita acumular lixo)
    function UIX.unbind(root)
        local binds = TH.binds
        for i = #binds, 1, -1 do
            local o = binds[i][1]
            if o == root or o:IsDescendantOf(root) then table.remove(binds, i) end
        end
    end
    local active
    function UIX.beginDrag(onMove, onEnd, firstX) active = { move = onMove, done = onEnd }; if firstX then onMove(firstX) end end
    table.insert(conns, UIS.InputChanged:Connect(function(i)
        if active and (i.UserInputType == Enum.UserInputType.MouseMovement or i.UserInputType == Enum.UserInputType.Touch) then active.move(i.Position.X) end
    end))
    table.insert(conns, UIS.InputEnded:Connect(function(i)
        if active and isPtr(i) then local a = active; active = nil; if a.done then a.done() end end
    end))

    -- ------------------------------------------------------------ lista suspensa ----
    local OPT_H = 30
    function UIX.select(parent, iconId, title, sub, order, options, initial, multi, onChange)
        local h0 = ORG.h(sub)
        local r = row(parent, iconId, title, sub, h0, order)
        r.ClipsDescendants = true
        ORG.R(r, 148)
        local pill = smallButton(r, "", 124, UDim2.new(1, -140, 0, (h0 - 28) / 2), false)
        pill.TextTruncate = Enum.TextTruncate.AtEnd; pill.ZIndex = 8
        local obj = { value = initial, open = false, options = options or {} }
        if multi and type(obj.value) ~= "table" then obj.value = {} end
        local holder, marks, dirty = nil, {}, true
        local function listH() return math.min(#obj.options, 7) * OPT_H end
        local function label()
            if multi then
                local t = {}
                for _, o in ipairs(obj.options) do if obj.value[o] then t[#t + 1] = o end end
                if #t == 0 then return "None" end
                local s = table.concat(t, ", ")
                if #t == 1 or #s <= 18 then return s end
                -- cabe pouco na caixa: mostra os primeiros e "+N" (em vez de cortar no meio de uma palavra)
                local out, used = {}, 0
                for _, o in ipairs(t) do
                    local add = (#out > 0 and 2 or 0) + #o
                    if #out > 0 and used + add > 14 then break end
                    out[#out + 1] = o; used = used + add
                end
                local left = #t - #out
                return table.concat(out, ", ") .. (left > 0 and (" +" .. left) or "")
            end
            return tostring(obj.value == nil and "-" or obj.value)
        end
        local function renderMarks()
            for o, m in pairs(marks) do
                local on = (multi and obj.value[o]) or (not multi and obj.value == o)
                tween(m, 0.2, { ImageTransparency = on and 0 or 1 })
            end
        end
        local function render() pill.Text = label(); renderMarks() end
        local function build()
            if holder then UIX.unbind(holder); holder:Destroy() end
            marks = {}
            holder = new("ScrollingFrame", { Size = UDim2.new(1, -24, 0, listH()), Position = UDim2.fromOffset(12, h0 + 6), BackgroundTransparency = 1, BorderSizePixel = 0,
                ScrollBarThickness = 3, CanvasSize = UDim2.fromOffset(0, #obj.options * OPT_H), ZIndex = 8 }, r)
            for i, o in ipairs(obj.options) do
                local b = new("TextButton", { Size = UDim2.new(1, -6, 0, OPT_H - 3), Position = UDim2.fromOffset(0, (i - 1) * OPT_H), BorderSizePixel = 0, Text = "", AutoButtonColor = false, ZIndex = 9 }, holder)
                bind(b, "BackgroundColor3", "hl"); bind(b, "BackgroundTransparency", "hlT")
                corner(b, 8)
                text(b, { Position = UDim2.fromOffset(12, 0), Size = UDim2.new(1, -44, 1, 0), Text = tostring(o), TextSize = 12, Font = Enum.Font.GothamMedium, ZIndex = 10, TextTruncate = Enum.TextTruncate.AtEnd })
                marks[o] = icon(b, ICON.check, 14, C.blue, { Position = UDim2.new(1, -26, 0.5, -7), ZIndex = 10, ImageTransparency = 1 })
                UI.press(b)
                b.MouseButton1Click:Connect(function()
                    if multi then
                        obj.value[o] = (not obj.value[o]) or nil
                    else
                        obj.value = o
                        obj.setOpen(false)
                    end
                    render()
                    if onChange then onChange(obj.value) end
                end)
            end
            dirty = false
            renderMarks()
        end
        function obj.setOpen(v)
            if v and dirty then build() end
            obj.open = v
            tween(r, 0.3, { Size = UDim2.new(1, 0, 0, v and (h0 + 10 + listH()) or h0) }, Enum.EasingStyle.Quint)
        end
        pill.MouseButton1Click:Connect(function() obj.setOpen(not obj.open) end)
        function obj.set(v) obj.value = v; render() end
        function obj.setOptions(list)
            obj.options = list or {}
            dirty = true
            if obj.open then build(); r.Size = UDim2.new(1, 0, 0, h0 + 10 + listH()) end
            render()
        end
        render()
        obj.row = r
        return obj
    end

    -- ----------------------------------------------------- slider + caixa numerica ----
    -- dec = casas decimais (0 = inteiro). fmt(v) opcional para o texto.
    function UIX.slider(parent, iconId, title, sub, order, min, max, initial, onChange, fmt, dec)
        dec = dec or 0
        local m10 = 10 ^ dec
        local hasSub = sub ~= nil and sub ~= ""
        local r, tt, ss = row(parent, iconId, title, sub, hasSub and 72 or 60, order)
        local tx = ORG.of[r].tx
        tt.Position = UDim2.fromOffset(tx, 10); ss.Position = UDim2.fromOffset(tx, 28)
        tt.Size = UDim2.new(1, -(96 + tx), 0, 16); ss.Size = UDim2.new(1, -(96 + tx), 0, 14)
        do local rec = ORG.of[r]; rec.R, rec.slider = 96, true; ORG.fit(rec) end
        local box = new("TextBox", { Size = UDim2.fromOffset(70, 26), Position = UDim2.new(1, -86, 0, 10), BackgroundColor3 = C.white, BackgroundTransparency = 0.9, Text = "", Font = Enum.Font.GothamBold, TextSize = 12, TextColor3 = C.text, ClearTextOnFocus = false, BorderSizePixel = 0, ZIndex = 7 }, r)
        bind(box, "TextColor3", "text")
        corner(box, 8); local bs = stroke(box, C.white, 1, 0.8); bind(bs, "Color", "rowS")
        local track = new("Frame", { Size = UDim2.new(1, -(tx + 26), 0, 6), Position = UDim2.fromOffset(tx, hasSub and 54 or 42), BorderSizePixel = 0, ZIndex = 6 }, r)
        bind(track, "BackgroundColor3", "track"); corner(track, 3)
        ORG.ex(r, track)
        local fill = new("Frame", { Size = UDim2.fromScale(0, 1), BorderSizePixel = 0, ZIndex = 7 }, track)
        bind(fill, "BackgroundColor3", "acc"); corner(fill, 3)
        local knob = new("Frame", { Size = UDim2.fromOffset(16, 16), Position = UDim2.new(0, -8, 0.5, -8), BackgroundColor3 = C.white, BorderSizePixel = 0, ZIndex = 8 }, track)
        corner(knob, 8); local kst = stroke(knob, C.blue, 2, 0); bind(kst, "Color", "acc")
        local ks = new("UIScale", { Scale = 1 }, knob)
        local bub = new("Frame", { Size = UDim2.fromOffset(52, 22), Position = UDim2.new(0, -26, 0, -28), BackgroundColor3 = Color3.fromRGB(16, 18, 28), BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 12 }, knob)
        corner(bub, 7); local bst = stroke(bub, C.white, 1, 1)
        local bubT = text(bub, { Size = UDim2.fromScale(1, 1), Text = "", TextSize = 11, TextXAlignment = Enum.TextXAlignment.Center, ZIndex = 13, TextTransparency = 1 })
        local function showBub(on)
            tween(bub, 0.18, { BackgroundTransparency = on and 0.1 or 1, Position = UDim2.new(0, -26, 0, on and -34 or -28) }, Enum.EasingStyle.Back)
            tween(bst, 0.18, { Transparency = on and 0.6 or 1 })
            tween(bubT, 0.18, { TextTransparency = on and 0 or 1 })
        end
        local hit = new("TextButton", { Size = UDim2.new(1, 16, 0, 28), Position = UDim2.fromOffset(-8, -11), BackgroundTransparency = 1, Text = "", ZIndex = 9 }, track)
        local obj = { value = initial }
        local function show(v) return fmt and fmt(v) or tostring(v) end
        local isPct = fmt ~= nil and tostring(fmt(max)):find("%%") ~= nil   -- mostra % -> o usuario digita em %
        local function render(animate)
            local f = (obj.value - min) / math.max(max - min, 1e-9)
            local t = animate and 0.1 or 0
            tween(fill, t, { Size = UDim2.fromScale(f, 1) })
            tween(knob, t, { Position = UDim2.new(f, -8, 0.5, -8) })
            box.Text = show(obj.value); bubT.Text = box.Text
        end
        local dragging = false
        local function setV(v, silent)
            v = math.clamp(math.floor((tonumber(v) or obj.value) * m10 + 0.5) / m10, min, max)
            if v == obj.value and silent then render(true) return end
            obj.value = v
            render(true)
            if not silent and onChange then onChange(v) end
        end
        local function fromX(x)
            local ap, as = track.AbsolutePosition, track.AbsoluteSize
            if as.X <= 0 then return end
            setV(min + math.clamp((x - ap.X) / as.X, 0, 1) * (max - min))
        end
        hit.InputBegan:Connect(function(i)
            if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
                dragging = true
                tween(ks, 0.18, { Scale = 1.4 }, Enum.EasingStyle.Back); showBub(true)
                UIX.beginDrag(fromX, function()
                    dragging = false; tween(ks, 0.22, { Scale = 1 }, Enum.EasingStyle.Back); showBub(false)
                end, i.Position.X)
            end
        end)
        hit.MouseEnter:Connect(function() if not dragging then tween(ks, 0.15, { Scale = 1.15 }, Enum.EasingStyle.Back) end end)
        hit.MouseLeave:Connect(function() if not dragging then tween(ks, 0.2, { Scale = 1 }) end end)
        box.FocusLost:Connect(function()
            local raw = box.Text
            local n = tonumber((raw:gsub("[^%d%.%-]", "")))
            if n and (isPct or raw:find("%%")) then n = n / 100 end
            setV(n or obj.value)
            box.Text = show(obj.value)
        end)
        render(false)
        obj.row = r
        obj.set = function(v, silent) obj.value = math.clamp(tonumber(v) or min, min, max); render(true); if not silent and onChange then onChange(obj.value) end end
        return obj
    end

    -- ------------------------------------------------------------ caixa de texto ----
    function UIX.input(parent, iconId, title, sub, order, default, placeholder, numeric, onChange)
        local r = row(parent, iconId, title, sub, ORG.h(sub), order)
        ORG.R(r, 184)
        local box = new("TextBox", { Size = UDim2.fromOffset(160, 28), Position = UDim2.new(1, -176, 0.5, -14), BackgroundColor3 = C.white, BackgroundTransparency = 0.9, Text = tostring(default or ""), PlaceholderText = placeholder or "", PlaceholderColor3 = C.dim,
            Font = Enum.Font.GothamMedium, TextSize = 12, TextColor3 = C.text, ClearTextOnFocus = false, BorderSizePixel = 0, ZIndex = 7, TextTruncate = Enum.TextTruncate.AtEnd }, r)
        bind(box, "TextColor3", "text")
        corner(box, 8); local bs = stroke(box, C.white, 1, 0.8); bind(bs, "Color", "rowS")
        box.Focused:Connect(function() tween(bs, 0.15, { Transparency = 0.2 }) end)
        local obj = { row = r, box = box }
        box.FocusLost:Connect(function()
            tween(bs, 0.2, { Transparency = TH.cur.rowST })
            if numeric then box.Text = (box.Text:gsub("[^%d%.%-]", "")) end
            if onChange then onChange(box.Text) end
        end)
        function obj.get() return box.Text end
        function obj.set(v) box.Text = tostring(v or "") end
        return obj
    end

    -- ------------------------------------------------------------------- botao ----
    function UIX.button(parent, iconId, title, sub, order, label, callback)
        local r = row(parent, iconId, title, sub, ORG.h(sub), order)
        local w = math.clamp(measure(label, 11, Enum.Font.GothamBold) + 30, 70, 150)
        ORG.R(r, w + 24)
        local b = smallButton(r, label, w, UDim2.new(1, -(w + 14), 0.5, -14), true)
        b.ZIndex = 8
        local obj = { row = r, btn = b }
        b.MouseButton1Click:Connect(function() if callback then task.spawn(callback) end end)
        function obj.setText(t) b.Text = t end
        return obj
    end

    -- ---------------------------------------------------- paragrafo (texto vivo) ----
    function UIX.para(parent, title, content, order)
        local r = new("Frame", { Size = UDim2.new(1, 0, 0, 40), AutomaticSize = Enum.AutomaticSize.Y, BorderSizePixel = 0, LayoutOrder = order or 1, ZIndex = 4 }, parent)
        bind(r, "BackgroundColor3", "row"); bind(r, "BackgroundTransparency", "rowT")
        corner(r, 11)
        local st = stroke(r, C.white, 1, 0.9); bind(st, "Color", "rowS"); bind(st, "Transparency", "rowST")
        local lay = list(r, 3); pad(r, 16, 10, 14, 10)
        local tl = text(r, { Size = UDim2.new(1, 0, 0, 16), Text = title or "", TextSize = 13, ZIndex = 5, LayoutOrder = 1, TextTruncate = Enum.TextTruncate.AtEnd })
        local cl = text(r, { Size = UDim2.new(1, 0, 0, 14), AutomaticSize = Enum.AutomaticSize.Y, Text = content or "", TextSize = 11, Font = Enum.Font.Gotham, TextColor3 = C.dim2, TextWrapped = true, TextYAlignment = Enum.TextYAlignment.Top, ZIndex = 5, LayoutOrder = 2, RichText = true })
        if (title or "") == "" then tl.Visible = false end
        local obj = { row = r }
        function obj.setTitle(t) tl.Text = tostring(t); tl.Visible = tostring(t) ~= "" end
        function obj.setDesc(t) t = tostring(t or ""); if cl.Text ~= t then cl.Text = t end end
        return obj
    end

    -- -------------------------------------------------------------- seletor de cor ----
    -- linha com amostra + hex; ao clicar abre H / S / V. get() -> Color3, set(Color3)
    local function hsvOf(c) local h, s, v = c:ToHSV(); return h, s, v end
    function UIX.color(parent, iconId, title, order, get, set, sub)
        local H0 = 52
        local r = row(parent, iconId, title, sub, H0, order)
        r.ClipsDescendants = true
        ORG.R(r, 176)
        local sw = new("TextButton", { Size = UDim2.fromOffset(46, 26), Position = UDim2.new(1, -62, 0, 13), BorderSizePixel = 0, Text = "", AutoButtonColor = false, ZIndex = 8 }, r)
        corner(sw, 8); stroke(sw, C.white, 1, 0.5)
        local hexb = new("TextBox", { Size = UDim2.fromOffset(78, 26), Position = UDim2.new(1, -146, 0, 13), BackgroundColor3 = C.white, BackgroundTransparency = 0.9, Text = "", Font = Enum.Font.GothamBold, TextSize = 11, TextColor3 = C.text, ClearTextOnFocus = false, BorderSizePixel = 0, ZIndex = 8 }, r)
        bind(hexb, "TextColor3", "text"); corner(hexb, 8)
        local cur = get()
        local h, s, v = hsvOf(cur)
        local open = false
        local function toHex(c) return string.format("#%02X%02X%02X", math.floor(c.R * 255 + 0.5), math.floor(c.G * 255 + 0.5), math.floor(c.B * 255 + 0.5)) end
        local bars = {}
        local function paint(fromUser)
            cur = Color3.fromHSV(h, s, v)
            sw.BackgroundColor3 = cur; hexb.Text = toHex(cur)
            if bars.h then
                bars.s.g.Color = ColorSequence.new(Color3.fromHSV(h, 0, v), Color3.fromHSV(h, 1, v))
                bars.v.g.Color = ColorSequence.new(Color3.fromHSV(h, s, 0), Color3.fromHSV(h, s, 1))
                bars.h.k.Position = UDim2.new(h, -7, 0.5, -7); bars.s.k.Position = UDim2.new(s, -7, 0.5, -7); bars.v.k.Position = UDim2.new(v, -7, 0.5, -7)
            end
            if fromUser then set(cur) end
        end
        local function mkBar(y, which, grad0)
            local tr = new("Frame", { Size = UDim2.new(1, -32, 0, 10), Position = UDim2.fromOffset(16, y), BackgroundColor3 = C.white, BorderSizePixel = 0, ZIndex = 8 }, r)
            corner(tr, 5)
            local g = new("UIGradient", { Color = grad0 }, tr)
            local k = new("Frame", { Size = UDim2.fromOffset(14, 14), Position = UDim2.new(0, -7, 0.5, -7), BackgroundColor3 = C.white, BorderSizePixel = 0, ZIndex = 9 }, tr)
            corner(k, 7); stroke(k, Color3.new(0, 0, 0), 1.5, 0.35)
            local hit = new("TextButton", { Size = UDim2.new(1, 14, 0, 26), Position = UDim2.fromOffset(-7, -8), BackgroundTransparency = 1, Text = "", ZIndex = 10 }, tr)
            local function fromX(x)
                local ap, as = tr.AbsolutePosition, tr.AbsoluteSize
                if as.X <= 0 then return end
                local f = math.clamp((x - ap.X) / as.X, 0, 1)
                if which == "h" then h = math.min(f, 0.999) elseif which == "s" then s = f else v = f end
                paint(true)
            end
            hit.InputBegan:Connect(function(i) if isPtr(i) then UIX.beginDrag(fromX, nil, i.Position.X) end end)
            bars[which] = { g = g, k = k }
        end
        local function build()
            if bars.h then return end
            local rainbow = {}
            for i = 0, 6 do rainbow[#rainbow + 1] = ColorSequenceKeypoint.new(i / 6, Color3.fromHSV(math.min(i / 6, 0.999), 1, 1)) end
            mkBar(60, "h", ColorSequence.new(rainbow))
            mkBar(84, "s", ColorSequence.new(Color3.new(1, 1, 1), Color3.new(1, 0, 0)))
            mkBar(108, "v", ColorSequence.new(Color3.new(0, 0, 0), Color3.new(1, 1, 1)))
            paint(false)
        end
        local function setOpen(o)
            open = o
            if o then build() end
            tween(r, 0.28, { Size = UDim2.new(1, 0, 0, o and 132 or H0) }, Enum.EasingStyle.Quint)
        end
        sw.MouseButton1Click:Connect(function() setOpen(not open) end)
        r.InputBegan:Connect(function(i) if isPtr(i) and i.Position.Y - r.AbsolutePosition.Y < H0 and not (i.Position.X > sw.AbsolutePosition.X - 90) then setOpen(not open) end end)
        hexb.FocusLost:Connect(function()
            local t = hexb.Text:gsub("[^%x]", "")
            if #t == 6 then
                local rr, gg, bb = tonumber(t:sub(1, 2), 16), tonumber(t:sub(3, 4), 16), tonumber(t:sub(5, 6), 16)
                h, s, v = hsvOf(Color3.fromRGB(rr, gg, bb))
                paint(true)
            else
                hexb.Text = toHex(cur)
            end
        end)
        paint(false)
        local obj = { row = r }
        function obj.refresh() cur = get(); h, s, v = hsvOf(cur); paint(false) end
        return obj
    end

    -- ======================================================= v24: cartoes vivos (status / progresso / contadores) ====
    -- Cor de cada estado: ok (verde) | warn (amarelo) | bad (vermelho) | info (cor de destaque do tema) | off (apagado)
    local function stCol(s)
        if s == "ok" then return C.ok elseif s == "warn" then return C.warn elseif s == "bad" then return C.bad elseif s == "info" then return TH.cur.acc end
        return TH.cur.dim
    end
    UIX.stCol = stCol
    -- bolinhas que pulsam (uma unica tarefa cuida de todas; so as que estao "ligadas")
    UIX.leds = setmetatable({}, { __mode = "k" })
    task.spawn(function()
        local lo = false
        while alive do
            lo = not lo
            for l, on in pairs(UIX.leds) do
                if on and l.Parent then tween(l, 0.9, { BackgroundTransparency = lo and 0.65 or 0 }, Enum.EasingStyle.Sine) end
            end
            task.wait(0.95)
        end
    end)

    -- cartao de estado: barra colorida a esquerda + bolinha do glifo + selo (pill) a direita.
    -- obj.set(estado, titulo, legenda, selo) -> qualquer campo nil = mantem. H opcional (altura do cartao).
    function UIX.status(parent, title, sub, order, H)
        H = H or 68
        local r, tt, ss = row(parent, ICON.gauge, title, (sub and sub ~= "") and sub or "...", H, order)
        local rec = ORG.of[r]
        ORG.R(r, 124)
        tt.TextSize = 14
        local bar = new("Frame", { Size = UDim2.fromOffset(3, H - 26), Position = UDim2.fromOffset(0, 13), BorderSizePixel = 0, ZIndex = 6 }, r)
        corner(bar, 2)
        local pill = new("Frame", { Size = UDim2.fromOffset(100, 26), Position = UDim2.new(1, -114, 0.5, -13), BackgroundColor3 = C.white, BackgroundTransparency = 0.84, BorderSizePixel = 0, ZIndex = 7 }, r)
        corner(pill, 13)
        local pst = stroke(pill, C.white, 1, 0.55)
        local led = new("Frame", { Size = UDim2.fromOffset(7, 7), Position = UDim2.fromOffset(11, 9.5), BackgroundColor3 = C.white, BorderSizePixel = 0, ZIndex = 8 }, pill)
        corner(led, 4)
        local pt = text(pill, { Position = UDim2.fromOffset(24, 0), Size = UDim2.new(1, -30, 1, 0), Text = "", TextSize = 10, TextColor3 = C.ok, ZIndex = 8, TextTruncate = Enum.TextTruncate.AtEnd })
        local obj = { row = r, state = "off" }
        local function paint(instant)
            local col = stCol(obj.state)
            local t = instant and 0 or 0.35
            tween(bar, t, { BackgroundColor3 = col })
            tween(pill, t, { BackgroundColor3 = col })
            tween(pst, t, { Color = col })
            tween(led, t, { BackgroundColor3 = col })
            tween(pt, t, { TextColor3 = col })
            ORG.tint(r, col)
            local live = obj.state == "ok" or obj.state == "info" or obj.state == "warn"
            UIX.leds[led] = live
            if not live then tween(led, 0.2, { BackgroundTransparency = 0 }) end
        end
        function obj.set(state, t, s, p)
            if state and state ~= obj.state then obj.state = state; paint(false) end
            if t and tt.Text ~= t then tt.Text = t end
            if s and rec.sub ~= s then rec.sub = s; ss.Text = s; ORG.fit(rec) end
            if p and pt.Text ~= p then
                pt.Text = p
                local w = math.clamp(measure(p, 10, Enum.Font.GothamBold) + 40, 64, 150)
                tween(pill, 0.28, { Size = UDim2.fromOffset(w, 26), Position = UDim2.new(1, -(w + 14), 0.5, -13) })
                ORG.R(r, w + 24)
            end
        end
        table.insert(TH.hooks, function() if r.Parent then paint(true) end end)
        paint(true)
        return obj
    end

    -- barra de progresso animada: titulo + legenda + valor ("7/10") e a barra embaixo. obj.set(atual, maximo, legenda)
    function UIX.progress(parent, iconId, title, sub, order)
        local hasSub = sub ~= nil and sub ~= ""
        local r, tt, ss = row(parent, iconId, title, sub, hasSub and 70 or 58, order)
        local rec = ORG.of[r]
        local tx = rec.tx
        tt.Position = UDim2.fromOffset(tx, 9); ss.Position = UDim2.fromOffset(tx, 27)
        tt.Size = UDim2.new(1, -(104 + tx), 0, 16); ss.Size = UDim2.new(1, -(104 + tx), 0, 14)
        rec.R, rec.slider = 104, true
        ORG.fit(rec)
        local val = text(r, { Position = UDim2.new(1, -98, 0, 8), Size = UDim2.fromOffset(84, 18), Text = "", TextSize = 13, TextXAlignment = Enum.TextXAlignment.Right, ZIndex = 6 })
        local track = new("Frame", { Size = UDim2.new(1, -(tx + 20), 0, 8), Position = UDim2.fromOffset(tx, hasSub and 52 or 38), BorderSizePixel = 0, ZIndex = 6 }, r)
        bind(track, "BackgroundColor3", "track"); corner(track, 4)
        ORG.ex(r, track)
        local fill = new("Frame", { Size = UDim2.fromScale(0, 1), BackgroundColor3 = TH.cur.acc, BorderSizePixel = 0, ZIndex = 7 }, track)
        corner(fill, 4)
        grad(fill, Color3.new(1, 1, 1), Color3.fromRGB(196, 206, 232), 0)
        local obj = { row = r, cur = nil, max = nil, done = false }
        local function colour() return obj.done and C.ok or TH.cur.acc end
        function obj.set(cur, max, s)
            cur, max = tonumber(cur) or 0, math.max(tonumber(max) or 1, 1)
            if s and rec.sub ~= s then rec.sub = s; ss.Text = s; ORG.fit(rec) end
            if cur == obj.cur and max == obj.max then return end
            local up = obj.cur ~= nil and cur > obj.cur
            obj.cur, obj.max, obj.done = cur, max, cur >= max
            local f = math.clamp(cur / max, 0, 1)
            if cur > 0 and f < 0.04 then f = 0.04 end
            tween(fill, 0.5, { Size = UDim2.fromScale(f, 1), BackgroundColor3 = colour() }, Enum.EasingStyle.Quint)
            val.Text = cur .. "/" .. max
            if up then
                val.TextColor3 = colour()
                tween(val, 0.7, { TextColor3 = TH.cur.text }, Enum.EasingStyle.Quad)
            end
        end
        table.insert(TH.hooks, function() if r.Parent then tween(fill, 0.3, { BackgroundColor3 = colour() }) end end)
        obj.set(0, 1)
        return obj
    end

    -- grade de contadores (numero grande + rotulo). labels = { "Islands", "Golems", ... } ; obj.set(lista de valores)
    function UIX.stats(parent, labels, order)
        local n = math.max(#labels, 1)
        local r = new("Frame", { Size = UDim2.new(1, 0, 0, 58), BorderSizePixel = 0, LayoutOrder = order or 1, ZIndex = 4 }, parent)
        bind(r, "BackgroundColor3", "row"); bind(r, "BackgroundTransparency", "rowT")
        corner(r, 11)
        local st = stroke(r, C.white, 1, 0.9); bind(st, "Color", "rowS"); bind(st, "Transparency", "rowST")
        local cells = {}
        for i = 1, n do
            local cell = new("Frame", { Size = UDim2.new(1 / n, 0, 1, 0), Position = UDim2.new((i - 1) / n, 0, 0, 0), BackgroundTransparency = 1, ZIndex = 5 }, r)
            local num = text(cell, { Position = UDim2.fromOffset(0, 9), Size = UDim2.new(1, 0, 0, 22), Text = "0", TextSize = 17, TextXAlignment = Enum.TextXAlignment.Center, ZIndex = 6 })
            text(cell, { Position = UDim2.fromOffset(0, 32), Size = UDim2.new(1, 0, 0, 14), Text = tostring(labels[i]), TextSize = 10, Font = Enum.Font.GothamMedium, TextColor3 = C.dim, TextXAlignment = Enum.TextXAlignment.Center, ZIndex = 6 })
            if i > 1 then
                local dv = new("Frame", { Size = UDim2.new(0, 1, 1, -24), Position = UDim2.fromOffset(0, 12), BorderSizePixel = 0, ZIndex = 5 }, cell)
                bind(dv, "BackgroundColor3", "line"); bind(dv, "BackgroundTransparency", "lineT")
            end
            cells[i] = { num = num, v = nil }
        end
        local obj = { row = r }
        function obj.set(list)
            for i = 1, n do
                local v = list[i]
                local c = cells[i]
                if v ~= nil and v ~= c.v then
                    local first = c.v == nil
                    c.v = v
                    c.num.Text = tostring(v)
                    if not first then
                        c.num.TextColor3 = TH.cur.acc
                        tween(c.num, 0.8, { TextColor3 = TH.cur.text }, Enum.EasingStyle.Quad)
                    end
                end
            end
        end
        return obj
    end
end)()


