local FX = {}
;(function()
    -- Anti AFK
    local afkConn
    -- v53: o Roblox desconecta quem fica ~20 min sem mexer no teclado/mouse. O farm move o personagem por CFrame, que NAO
    -- conta como atividade, entao com o "Anti AFK" desligado (padrao) o jogo caia sozinho depois de um tempo farmando.
    -- Agora o guarda fica sempre ligado: age se o "Anti AFK" estiver ligado OU se alguma farm estiver rodando.
    function FX.antiafk(on)
        if afkConn then pcall(function() afkConn:Disconnect() end); afkConn = nil end
        pcall(function()
            afkConn = LP.Idled:Connect(function()
                local core = getgenv().MoonPremiumCore
                local farming = core ~= nil and (core.attacking or core.owner ~= nil)
                if not (cfg.antiafk or farming) then return end
                pcall(function()
                    local vu = game:GetService("VirtualUser")
                    vu:CaptureController(); vu:ClickButton2(Vector2.new())
                end)
            end)
        end)
    end
    table.insert(cleanups, function()
        if afkConn then pcall(function() afkConn:Disconnect() end); afkConn = nil end
    end)

    -- Auto Rejoin (reconecta quando aparece a tela de erro/kick)
    local rjConn
    function FX.rejoin(on)
        if rjConn then pcall(function() rjConn:Disconnect() end); rjConn = nil end
        if on then
            pcall(function()
                local overlay = game:GetService("CoreGui").RobloxPromptGui.promptOverlay
                rjConn = overlay.ChildAdded:Connect(function(c)
                    if c.Name == "ErrorPrompt" then
                        notify("Auto Rejoin", "Connection lost. Rejoining...", "warn", 5)
                        task.wait(2)
                        local TS = game:GetService("TeleportService")
                        local ok = pcall(function() TS:TeleportToPlaceInstance(game.PlaceId, game.JobId, LP) end)
                        task.wait(6)
                        if not ok or true then pcall(function() TS:Teleport(game.PlaceId, LP) end) end
                    end
                end)
            end)
        end
    end
    table.insert(cleanups, function() FX.rejoin(false) end)

    -- Notificacoes de eventos (Blox Fruits)
    local function inMap(name) return function() local m = workspace:FindFirstChild("Map"); return m and m:FindFirstChild(name) ~= nil end end
    local function inEnemies(...)
        local names = { ... }
        return function()
            local e = workspace:FindFirstChild("Enemies")
            if not e then return false end
            for _, n in ipairs(names) do if e:FindFirstChild(n) then return true end end
            return false
        end
    end
    local EVENTS = {
        { "Full Moon", function() local sky = Lighting:FindFirstChildOfClass("Sky"); return sky and tostring(sky.MoonTextureId):find("9709149431", 1, true) ~= nil end },
        { "Mirage Island", inMap("MysticIsland") },
        { "Kitsune Island", inMap("KitsuneIsland") },
        { "Prehistoric Island", inMap("PrehistoricIsland") },
        { "Rip Indra", inEnemies("rip_indra", "rip_indra True Form") },
        { "Dough King", inEnemies("Dough King") },
    }
    local seen, evOn = {}, false
    local function scan(announce)
        for _, ev in ipairs(EVENTS) do
            local ok, v = pcall(ev[2])
            v = ok and v and true or false
            if v and not seen[ev[1]] then
                seen[ev[1]] = true
                if announce then
                    notify("Event: " .. ev[1], "Spotted in this server!", "warn", 6)
                    if FX.uw then pcall(FX.uw, "Event: " .. ev[1], "Spotted in this server!") end
                end
            elseif not v then seen[ev[1]] = false end
        end
    end
    local loopRunning = false
    function FX.events(on, announce)
        evOn = on
        if on then
            seen = {}
            scan(announce ~= false)
            if not loopRunning then
                loopRunning = true
                task.spawn(function()
                    while alive and evOn do task.wait(6); if evOn then scan(true) end end
                    loopRunning = false
                end)
            end
        end
    end
    table.insert(cleanups, function() evOn = false end)

    -- Booster FPS (1 = so texturas | 2 = texturas + efeitos)
    local orig = setmetatable({}, { __mode = "k" })
    local lightOrig, fpsMode, addConn = {}, 0, nil
    local FXCLASS = { ParticleEmitter = true, Trail = true, Beam = true, Fire = true, Smoke = true, Sparkles = true, Explosion = true }
    local function remember(o, prop)
        local t = orig[o]
        if not t then t = {}; orig[o] = t end
        if t[prop] == nil then t[prop] = o[prop] end
    end
    local function strip(o, super)
        pcall(function()
            if o:IsA("MeshPart") then remember(o, "TextureID"); o.TextureID = "" end
            if o:IsA("BasePart") then
                remember(o, "Material"); o.Material = Enum.Material.SmoothPlastic
            elseif o:IsA("Decal") or o:IsA("Texture") then
                remember(o, "Transparency"); o.Transparency = 1
            elseif super and FXCLASS[o.ClassName] then
                remember(o, "Enabled"); o.Enabled = false
            end
        end)
    end
    local function restoreAll()
        for o, props in pairs(orig) do
            for p, v in pairs(props) do pcall(function() o[p] = v end) end
        end
        orig = setmetatable({}, { __mode = "k" })
        for k, v in pairs(lightOrig) do pcall(function() Lighting[k] = v end) end
        lightOrig = {}
    end
    function FX.fps(mode)
        if addConn then pcall(function() addConn:Disconnect() end); addConn = nil end
        restoreAll()
        fpsMode = mode
        if mode <= 0 then return end
        local my = mode
        task.spawn(function()
            local n = 0
            for _, o in ipairs(workspace:GetDescendants()) do
                if fpsMode ~= my then return end
                strip(o, my == 2)
                n = n + 1
                if n % 300 == 0 then task.wait() end
            end
        end)
        pcall(function() addConn = workspace.DescendantAdded:Connect(function(o) strip(o, my == 2) end) end)
        if mode == 2 then
            pcall(function()
                lightOrig.GlobalShadows = Lighting.GlobalShadows; Lighting.GlobalShadows = false
                for _, o in ipairs(Lighting:GetChildren()) do
                    if o:IsA("PostEffect") or o:IsA("Atmosphere") then
                        remember(o, o:IsA("PostEffect") and "Enabled" or "Density")
                        if o:IsA("PostEffect") then o.Enabled = false else o.Density = 0 end
                    end
                end
                local T = workspace.Terrain
                for _, p in ipairs({ "WaterWaveSize", "WaterWaveSpeed", "WaterReflectance" }) do remember(T, p); T[p] = 0 end
                settings().Rendering.QualityLevel = Enum.QualityLevel.Level01
            end)
        end
    end
    table.insert(cleanups, function() FX.fps(0) end)

    -- Remove Fog (igual ao Moon Hub principal): Lighting a cada frame, Atmosphere, Clouds, neve/nevoa (particulas),
    -- pecas/decals de nevoa, blur/depth of field e ScreenGuis de clima. Tudo e restaurado ao desligar.
    local F = { on = false, saved = nil, em = setmetatable({}, { __mode = "k" }), tr = setmetatable({}, { __mode = "k" }), fx = setmetatable({}, { __mode = "k" }), conns = {}, gui = {}, scanning = false }
    local FogWords = { "snow", "neve", "blizzard", "fog", "mist", "haze", "weather", "nevoa", "n\u{e9}voa" }
    local function fogNamed(n)
        n = string.lower(n)
        for _, w in ipairs(FogWords) do if string.find(n, w, 1, true) then return true end end
        return false
    end
    local FogPartWords = { "fog", "mist", "haze", "smog", "nevoa", "n\u{e9}voa", "weather" }
    local function fogPartNamed(n)
        n = string.lower(n)
        if string.find(n, "mistake", 1, true) then return false end
        for _, w in ipairs(FogPartWords) do if string.find(n, w, 1, true) then return true end end
        return false
    end
    local function fogCheck(d)
        local cls = d.ClassName
        if cls == "ParticleEmitter" or cls == "Smoke" then
            if F.em[d] ~= nil then return end
            local p = d.Parent
            local g = p and p.Parent
            if not (fogNamed(d.Name) or (p and fogNamed(p.Name)) or (g and g ~= workspace and fogNamed(g.Name))) then return end
            local m = d:FindFirstAncestorOfClass("Model")
            if m and m:FindFirstChildOfClass("Humanoid") then return end
            F.em[d] = d.Enabled
            d.Enabled = false
            if cls == "ParticleEmitter" then pcall(function() d:Clear() end) end
        elseif cls == "Part" or cls == "MeshPart" or cls == "UnionOperation" or cls == "Decal" or cls == "Texture" then
            if F.tr[d] ~= nil then return end
            if not fogPartNamed(d.Name) then
                local p = d.Parent
                if not (p and p ~= workspace and p:IsA("Model") and fogPartNamed(p.Name)) then return end
            end
            local m = d:FindFirstAncestorOfClass("Model")
            if m and m:FindFirstChildOfClass("Humanoid") then return end
            F.tr[d] = d.Transparency
            d.Transparency = 1
        end
    end
    local function fogScan()
        if F.scanning then return end
        F.scanning = true
        task.spawn(function()
            local n = 0
            pcall(function()
                for _, root in ipairs({ workspace, Lighting }) do
                    for _, d in ipairs(root:GetDescendants()) do
                        if not (alive and F.on) then return end
                        fogCheck(d)
                        n = n + 1
                        if n % 1500 == 0 then task.wait() end
                    end
                end
            end)
            F.scanning = false
        end)
    end
    local function fogGui()
        pcall(function()
            for _, g in ipairs(LP.PlayerGui:GetChildren()) do
                if g:IsA("ScreenGui") and g ~= gui and fogNamed(g.Name) then
                    if F.gui[g] == nil then F.gui[g] = g.Enabled end
                    if g.Enabled then g.Enabled = false end
                end
            end
        end)
    end
    local function fogConnect()
        if #F.conns > 0 then return end
        for _, root in ipairs({ workspace, Lighting }) do
            pcall(function()
                table.insert(F.conns, root.DescendantAdded:Connect(function(d)
                    if alive and F.on then pcall(fogCheck, d) end
                end))
            end)
        end
    end
    local function fogDisconnect()
        for _, c in ipairs(F.conns) do pcall(function() c:Disconnect() end) end
        F.conns = {}
    end
    local function fogApply()
        pcall(function()
            if F.on then
                if not F.saved then
                    F.saved = { s = Lighting.FogStart, e = Lighting.FogEnd, atm = {}, clouds = {} }
                    fogConnect(); fogScan(); fogGui()
                end
                if Lighting.FogEnd ~= 1e6 then Lighting.FogEnd = 1e6 end
                if Lighting.FogStart ~= 9e5 then Lighting.FogStart = 9e5 end
                for _, a in ipairs(Lighting:GetChildren()) do
                    if a:IsA("Atmosphere") then
                        if not F.saved.atm[a] then
                            F.saved.atm[a] = { a.Density, a.Haze }
                            pcall(function() F.saved.atmClone = F.saved.atmClone or {}; table.insert(F.saved.atmClone, a:Clone()) end)
                        end
                        a.Density = 0; a.Haze = 0
                        pcall(function() a.Glare = 0; a.Offset = 0 end)
                        pcall(function() a:Destroy() end)
                    end
                end
                local c = workspace.Terrain:FindFirstChildOfClass("Clouds")
                if c then
                    if F.saved.clouds[c] == nil then F.saved.clouds[c] = c.Enabled end
                    if c.Enabled then c.Enabled = false end
                end
                for e in pairs(F.em) do if e.Parent and e.Enabled then e.Enabled = false end end
                for d in pairs(F.tr) do if d.Parent and d.Transparency ~= 1 then d.Transparency = 1 end end
                for _, x in ipairs(Lighting:GetChildren()) do
                    if x:IsA("DepthOfFieldEffect") or x:IsA("BlurEffect") then
                        if F.fx[x] == nil then F.fx[x] = x.Enabled end
                        if x.Enabled then x.Enabled = false end
                    end
                end
            elseif F.saved then
                Lighting.FogStart, Lighting.FogEnd = F.saved.s, F.saved.e
                for a, v in pairs(F.saved.atm) do if a.Parent then a.Density, a.Haze = v[1], v[2] end end
                for _, cl in ipairs(F.saved.atmClone or {}) do pcall(function() cl.Parent = Lighting end) end
                for c, was in pairs(F.saved.clouds) do if c.Parent then c.Enabled = was end end
                for e, was in pairs(F.em) do if e.Parent then e.Enabled = was end end
                for g, was in pairs(F.gui) do if g.Parent then g.Enabled = was end end
                for d, was in pairs(F.tr) do if d.Parent then d.Transparency = was end end
                for x, was in pairs(F.fx) do if x.Parent then x.Enabled = was end end
                F.em, F.gui, F.saved = setmetatable({}, { __mode = "k" }), {}, nil
                F.tr, F.fx = setmetatable({}, { __mode = "k" }), setmetatable({}, { __mode = "k" })
                fogDisconnect()
            end
        end)
    end
    pcall(function() RunService:UnbindFromRenderStep("MoonPremiumFog") end)
    pcall(function()
        RunService:BindToRenderStep("MoonPremiumFog", Enum.RenderPriority.Last.Value, function()
            if not (alive and F.on) then return end
            local t = os.clock()
            if t - (F._t or 0) < 0.2 then return end
            F._t = t
            fogApply()
        end)
    end)
    task.spawn(function()
        local i = 0
        while alive do
            task.wait(1)
            i = i + 1
            if F.on then
                fogGui()
                if i % 15 == 0 then fogScan() end
            end
        end
    end)
    function FX.fog(on)
        F.on = on and true or false
        fogApply()
    end
    table.insert(cleanups, function() FX.fog(false); pcall(function() RunService:UnbindFromRenderStep("MoonPremiumFog") end) end)
end)()


-- ============================================================ Farm engine ====
-- Core: ataque (Melee / Sword / Fruit M1 / Double Attack), Haki, time, Bring Mob, Tween e prioridades.
-- As farms Premium usam getgenv().MoonPremiumCore (Core.setAttack, Core.bring, Core.tweenTo, Core.priorityOrder...).
local Core = { attacking = false, farms = {} }
getgenv().MoonPremiumCore = Core
Core.cfg = cfg
-- v102: virou uma funcao imediata (igual a aba Farm Settings, mesmo motivo - ve o comentario la) em vez de um
-- "do...end" simples - esse bloco e o maior do arquivo inteiro (ataque/Core), de longe o que mais empurrava o
-- chunk principal pro limite de 200 variaveis locais do LuaJIT. Core continua fora (declarado acima), entao
-- continua acessivel do jeito de sempre (getgenv().MoonPremiumCore / Core.xxx).
;(function()
    local RS = game:GetService("ReplicatedStorage")
    local TS = game:GetService("TweenService")
    local cloneref = cloneref or function(x) return x end

    local function getChar()
        local c = LP.Character
        return c, c and c:FindFirstChild("HumanoidRootPart"), c and c:FindFirstChildOfClass("Humanoid")
    end
    local function pressKey(kc)
        pcall(function()
            local v = game:GetService("VirtualInputManager")
            v:SendKeyEvent(true, kc, false, game); task.wait(0.05); v:SendKeyEvent(false, kc, false, game)
        end)
    end

    -- ------------------------------------------------------------ alvos ----
    local BOSS = { ["rip_indra"] = true, ["rip_indra True Form"] = true, ["Dough King"] = true, ["Darkbeard"] = true, ["Order"] = true,
        ["Cake Prince"] = true, ["Soul Reaper"] = true, ["Tyrant of the Skies"] = true, ["Tyrant Of The Skies"] = true, ["Stone"] = true, ["Island Empress"] = true,
        ["Kilo Admiral"] = true, ["Captain Elephant"] = true, ["Beautiful Pirate"] = true, ["Cake Queen"] = true, ["Longma"] = true,
        ["Don Swan"] = true, ["Smoke Admiral"] = true, ["Awakened Ice Admiral"] = true, ["Tide Keeper"] = true, ["Greybeard"] = true,
        -- v68: nomes extras da lista de bosses do script que o usuario mandou (bomba.lua) - alguns desses podem ter
        -- vida abaixo dos 60000 da heuristica, entao o nome garante que nunca sao puxados/agrupados pelo Bring Mob.
        ["Gorilla King"] = true, ["Bobby"] = true, ["Yeti"] = true, ["Mob Leader"] = true, ["Vice Admiral"] = true,
        ["Warden"] = true, ["Chief Warden"] = true, ["Swan"] = true, ["Magma Admiral"] = true, ["Fishman Lord"] = true,
        ["Wysper"] = true, ["Thunder God"] = true, ["Cyborg"] = true, ["Saber Expert"] = true, ["Diamond"] = true,
        ["Jeremy"] = true, ["Fajita"] = true, ["Cursed Captain"] = true }
    local function isBoss(m, hum)
        if m:GetAttribute("Boss") or BOSS[m.Name] then return true end
        if string.find(hum.DisplayName or "", "[Boss]", 1, true) or string.find(m.Name, "[Boss]", 1, true) then return true end
        return hum.MaxHealth >= 60000     -- heuristica: mobs normais tem bem menos vida
    end
    local ALLYATTR = { "Ally", "IsAlly", "Friendly", "IsFriendly", "Summoned", "IsSummon", "IsSummoned", "PlayerOwned", "IsPlayerOwned", "Minion", "IsMinion", "IsShadow" }
    local OWNKEYS = { "Owner", "OwnerId", "OwnerUserId", "OwnerName", "Master", "Summoner", "SummonedBy" }
    -- aliado do jogador (ex.: o Shadow que a carta da dungeon invoca): nunca e alvo nem e puxado
    function Core.isFriendly(m, me)
        local n = string.lower(m.Name)
        local ln = string.lower(me.Name)
        if n == "shadow" or n == ln or string.find(n, "^shadow ?ally") or string.find(n, "^shadow ?clone") or string.find(n, "shadowally", 1, true)
            or string.find(n, "%f[%a]ally%f[%A]") or string.find(n, "%f[%a]summon") then return true end
        if #ln >= 5 and string.find(n, ln, 1, true) then return true end
        for _, a in ipairs(ALLYATTR) do if m:GetAttribute(a) == true then return true end end
        for _, a in ipairs(OWNKEYS) do
            local v = m:GetAttribute(a)
            if v ~= nil and (v == me.UserId or v == me.Name or v == me.DisplayName) then return true end
            local o = m:FindFirstChild(a)
            if o and o:IsA("ObjectValue") and (o.Value == me or (me.Character ~= nil and o.Value == me.Character)) then return true end
        end
        return false
    end
    local cache, cacheAt, cacheN = {}, 0, 0
    -- lista de alvos vivos no alcance (ordenados por distancia). {model, part, hum}
    function Core.targets(maxN)
        local now = os.clock()
        if now - cacheAt < 0.05 and cacheN >= (maxN or 10) then return cache end
        cacheAt, cacheN = now, (maxN or 10)
        local out = {}
        local _, hrp = getChar()
        if not hrp then cache = out; return out end
        local range = tonumber(cfg.range) or 60
        local sel = (Core.force and os.clock() < (Core.forceUntil or 0)) and Core.force or cfg.targets or {}
        local pos = hrp.Position
        pcall(function()
            if sel.NPC or sel.BOSS then
                local f = workspace:FindFirstChild("Enemies")
                if f then
                    for _, m in ipairs(f:GetChildren()) do
                        if not m:GetAttribute("IsBoat") and not Core.isFriendly(m, LP) then
                            local h = m:FindFirstChildOfClass("Humanoid")
                            local r = m:FindFirstChild("HumanoidRootPart") or m.PrimaryPart
                            if h and h.Health > 0 and r then
                                local d = (r.Position - pos).Magnitude
                                if d <= range then
                                    local boss = isBoss(m, h)
                                    if (boss and sel.BOSS) or (not boss and sel.NPC) then out[#out + 1] = { m, r, h, d, Core.isGhost(m) } end
                                end
                            end
                        end
                    end
                end
            end
            if sel.PLAYER then
                for _, p in ipairs(Players:GetPlayers()) do
                    if p ~= LP and (p.Team == nil or p.Team ~= LP.Team) then
                        local m = p.Character
                        local h = m and m:FindFirstChildOfClass("Humanoid")
                        local r = m and m:FindFirstChild("HumanoidRootPart")
                        if h and h.Health > 0 and r then
                            local d = (r.Position - pos).Magnitude
                            if d <= range then out[#out + 1] = { m, r, h, d } end
                        end
                    end
                end
            end
        end)
        table.sort(out, function(a, b) return a[4] < b[4] end)
        -- Multi Account (Moon Sync): se outra conta SINCRONIZADA ja esta em cima do mob mais proximo (NPC comum,
        -- nunca Boss/Player), manda esse mob pro fim da lista e deixa outro assumir - assim duas contas sincronizadas
        -- farmando no mesmo lugar nao ficam as duas brigando pelo MESMO mob. So reordena quando tem outro alvo
        -- disponivel pra assumir o lugar (nunca deixa a conta parada so pra "respeitar" o claim de outra).
        if #out > 1 then
            pcall(function()
                local MS = getgenv().MoonHubSync
                if not (MS and MS.isSynced) then return end
                local free, used = {}, {}
                for _, e in ipairs(out) do
                    local m, h = e[1], e[3]
                    -- sem timestamp (Workspace:GetServerTimeNow() tem bug conhecido de voltar 0 no cliente em alguns
                    -- casos - nao e confiavel pra isso): confia so em "o dono do claim ainda ta sincronizado comigo"
                    -- (MoonSync.synced ja limpa sozinho quando a conta desconecta, via PlayerRemoving)
                    local claimer = (not isBoss(m, h)) and m:GetAttribute("MHClaim")
                    if claimer and claimer ~= LP.UserId and MS.isSynced(claimer) then
                        used[#used + 1] = e
                    else
                        free[#free + 1] = e
                    end
                end
                if #free > 0 and #used > 0 then
                    local merged = {}
                    for _, e in ipairs(free) do merged[#merged + 1] = e end
                    for _, e in ipairs(used) do merged[#merged + 1] = e end
                    out = merged
                end
            end)
        end
        if out[1] then
            pcall(function()
                local MS = getgenv().MoonHubSync
                if MS and MS.claim then
                    local m, h = out[1][1], out[1][3]
                    if not isBoss(m, h) then MS.claim(m) end
                end
            end)
        end
        -- v28: alvo forcado (Sea Events / Raid): prioridade MAXIMA, mesmo com outros NPCs/Enemies por perto
        -- (antes so entrava pelo "alvo extra" abaixo, que exige a lista vazia -> o mar nunca era atacado com NPC perto)
        if Core.seaTarget and os.clock() < (Core.seaTargetUntil or 0) then
            pcall(function()
                local ft = Core.seaTarget
                if ft.m and ft.m.Parent and ft.part and ft.part.Parent then
                    local h = ft.m:FindFirstChildOfClass("Humanoid")
                    if h and h.Health > 0 then
                        local already = false
                        for _, e in ipairs(out) do if e[1] == ft.m then already = true break end end
                        if not already then
                            local d = (ft.part.Position - pos).Magnitude
                            table.insert(out, 1, { ft.m, ft.part, h, d })
                        end
                    end
                end
            end)
        end
        while #out > (maxN or 10) do table.remove(out) end
        -- alvo extra (compat do Moon antigo: Aim.part = golem, monstro do mar, arvore...): entra quando nao ha outro alvo
        if #out == 0 and Core.extra and Core.attacking then
            pcall(function()
                local part = Core.extra()
                local am = part and part.Parent and part:FindFirstAncestorOfClass("Model")
                local h = am and am:FindFirstChildOfClass("Humanoid")
                local r = am and (am:FindFirstChild("HumanoidRootPart") or am.PrimaryPart)
                if h and r and h.Health > 0 then
                    local d = (r.Position - pos).Magnitude
                    if d <= 80 then out[1] = { am, r, h, d } end
                end
            end)
        end
        cache = out
        return out
    end

    -- ---------------------------------------------------- mob fantasma ----
    -- "Puxar" so vale se o SEU cliente e dono da fisica do mob. Se nao for, ele so se mexe na sua tela: o servidor continua
    -- com ele no lugar de origem, nenhum golpe registra, e o golpe em lote ainda gasta uma vaga com ele ("junta 5 mas so
    -- bate em 2"). Aqui: confere o dono (quando o executor tem isnetworkowner), marca como fantasma quem nao perde vida e
    -- deixa as farms soltarem e seguirem em frente (antes ficavam presas no fantasma).
    local GH = setmetatable({}, { __mode = "k" })       -- modelo -> ate quando e tratado como fantasma
    local OWN = setmetatable({}, { __mode = "k" })      -- modelo -> desde quando nao somos donos
    local RST = setmetatable({}, { __mode = "k" })      -- modelo -> episodio de fantasma ja restaurado
    Core.ghosts = GH
    Core.pulledAt = setmetatable({}, { __mode = "k" })   -- modelo -> ultima vez que a farm puxou ele (as farms marcam)
    function Core.isGhost(m)
        local u = GH[m]
        if not u then return false end
        if u > os.clock() then return true end
        GH[m] = nil
        return false
    end
    function Core.markGhost(m, secs)
        GH[m] = os.clock() + (secs or 10)
        Core.ghostCount, Core.ghostAt = (Core.ghostCount or 0) + 1, os.clock()
    end
    -- true = somos donos | false = nao somos | nil = o executor nao tem isnetworkowner
    function Core.owns(r)
        local f = isnetworkowner
        if type(f) ~= "function" or not r then return nil end
        local ok, v = pcall(f, r)
        if ok then return v and true or false end
        return nil
    end
    -- pode puxar este mob? home (opcional) = onde ele nasceu: se virar fantasma, volta pra la na sua tela
    function Core.pullOK(m, r, home)
        local u = GH[m]
        if u and u > os.clock() then
            if home and RST[m] ~= u then RST[m] = u; pcall(function() r.CFrame = CFrame.new(home) end) end
            return false
        end
        -- (v25) NAO marca fantasma por isnetworkowner: em varios executores ele devolve false mesmo com o mob apanhando,
        -- e isso fazia a farm largar todo NPC e trocar de alvo sem matar ninguem.
        OWN[m] = nil
        return true
    end
    -- tempo medio de frame (freio de seguranca do ataque em lote quando o jogo engasga)
    local Perf = { ema = 0.016 }
    Core.perf = Perf
    table.insert(conns, RunService.Heartbeat:Connect(function(dt) Perf.ema = Perf.ema + ((tonumber(dt) or 0.016) - Perf.ema) * 0.1 end))

    -- ------------------------------------------------------ equipar arma ----
    local TIP = { Melee = "Melee", Sword = "Sword", Fruit = "Blox Fruit" }
    -- v111: pedido do usuario - "arruma o click normal de espada e estilo de luta", usando como base o attack.lua
    -- que ele mandou.
    -- v118 fix: a v111 tinha deixado ToolTip como PRIMEIRA opcao (WeaponType so como reserva) - mas o attack.lua
    -- (a referencia real, confirmada pelo usuario) confere SO tool:GetAttribute("WeaponType") pra Melee/Sword,
    -- nunca ToolTip. Invertido no v118: WeaponType primeiro, ToolTip como reserva.
    -- v123 fix: o v118 quebrou a SELECAO AUTOMATICA de fruta ("nao seleciona a fruta automatico pra clicar").
    -- Motivo: frutas TAMBEM tem o atributo WeaponType preenchido (com um valor que nao e "Melee"/"Sword"/"Gun")
    -- - com WeaponType sempre na frente, wtip() de uma fruta nunca mais devolvia "Blox Fruit", e o equip()
    -- (usado pelo modo normal de Fruit) nunca achava nenhuma fruta na mochila pra equipar. O attack.lua so usa
    -- WeaponType pra Melee/Sword mesmo (nunca pra fruta); o bomba.lua/Attack(1).lua so usam ToolTip=="Blox Fruit"
    -- pra fruta (nunca WeaponType). Essa funcao agora respeita os dois ao mesmo tempo: WeaponType só decide
    -- quando for literalmente "Melee"/"Sword"/"Gun" (os 3 valores que o attack.lua conhece); fora isso, ToolTip
    -- decide (cobre "Blox Fruit" e qualquer outra coisa).
    local function wtip(tool)
        if not tool then return nil end
        local ok, wt = pcall(function() return tool:GetAttribute("WeaponType") end)
        if ok and (wt == "Melee" or wt == "Sword" or wt == "Gun") then return wt end
        local tt = tool.ToolTip
        if tt and tt ~= "" then return tt end
        return (ok and wt and wt ~= "") and wt or nil
    end
    Core.wtip = wtip
    local lastEquip = 0
    local function equip(tip)
        local char, _, hum = getChar()
        if not (char and hum) then return nil end
        local cur = char:FindFirstChildOfClass("Tool")
        if cur and wtip(cur) == tip then return cur end
        if os.clock() - lastEquip < 0.15 then return cur end   -- v54: re-equipa mais rapido (0,3 s -> 0,15 s)
        lastEquip = os.clock()
        for _, t in ipairs(LP.Backpack:GetChildren()) do
            if t:IsA("Tool") and wtip(t) == tip then pcall(function() hum:EquipTool(t) end); return t end
        end
        return cur
    end

    -- ------------------------------------------------------- metodos ----
    -- v124: pedido do usuario - "tira o hyper click e o super fast, deixa so o normal e o fast". O "Attack Method"
    -- (Fast/Super/Hyper) hoje SO controla o numero de motores (Heartbeat/Stepped/RenderStepped) do Double Attack -
    -- Melee/Sword e o M1 de fruta normal ja rodam nos 3 motores sempre, direto, sem passar por aqui (sao funcoes
    -- PROPRIAS - netAttack()/meleeM1() pro Melee/Sword, fruitM1() pra fruta - nenhuma das duas olha cfg.method).
    -- "Hyper"/"Super" (3-4 motores chamando o mesmo golpe por frame) era exatamente o tipo de disparo duplicado que
    -- a gente ja identificou como causa de clique sendo filtrado pelo jogo (igual o "reps" tirado antes) - por isso
    -- saem. "Normal" (1 motor) e o mais conservador; "Fast" (2 motores) e o recomendado - mais rapido que o Hyper
    -- antigo de verdade, porque as outras correcoes (ServerState, secureHit sem limite, sem disparo duplicado)
    -- fazem cada disparo valer, em vez de simplesmente mandar mais copias do mesmo golpe.
    local METHOD = {
        ["Normal Attack"] = { engines = 1 },
        ["Fast Attack"]   = { engines = 2 },
    }
    local function method() return METHOD[cfg.method] or METHOD["Fast Attack"] end

    -- ------------------------------------------------------- M1 de fruta ----
    -- v67: lista de frutas "direcionais" (Blade-Blade/Gas-Gas), compartilhada entre o M1 de fruta e o Double Attack
    -- - igual o script de referencia do usuario (bomba.lua / Attack.lua, mesmo hub nos dois) faz: so essas 2 miram
    -- a direcao de cada inimigo com um contador de combo; todo o resto manda 1 tiro "as cegas" sempre pro mesmo
    -- lugar e deixa o jogo decidir quem acerta - e o jogo que realmente funciona, confirmado pelo usuario.
    -- v110: tentativa de colocar Kitsune-Kitsune aqui (combo direcional) pra resolver o "so bate 1 e para" -
    -- v113 fix: o usuario confirmou que isso NAO resolveu (continuou so 1 ataque), e mandou outro script do MESMO
    -- hub de referencia (bomba.lua) que ele confirma estar funcionando - nesse script a Kitsune-Kitsune NAO esta
    -- na lista de frutas direcionais (so Blade-Blade/Gas-Gas), ela usa o tiro as cegas comum igual toda fruta
    -- normal. Tirando ela do DIRFRUIT de volta - a causa real do "so 1 ataque" era outra (ver stripCd() abaixo).
    -- v130: REVERTIDO o v128 (Kitsune em DIRFRUIT + gap 0,03s): o usuario relatou que depois dele a Kitsune parou de
    -- clicar de vez. Voltou ao que funcionava no v127: tiro as cegas + intervalo minimo de 0,05s (ritmo do bomba).
    local DIRFRUIT = { ["Blade-Blade"] = true, ["Gas-Gas"] = true }
    local STATEFUL = { ["Kitsune-Kitsune"] = 0.05, ["T-Rex-T-Rex"] = 0.05 }   -- v127: intervalo minimo (s) igual ao loop do bomba
    -- v67: fonte de inimigos direta (workspace.Enemies), igual o script de referencia - independente de qualquer
    -- toggle de selecao de alvo (NPC/BOSS) nas configs, que era o bug raiz achado no Double Attack (Core.targets()
    -- so devolve algo se essa selecao estiver marcada). So mantive o isFriendly() pra nao bater em aliado/summon.
    -- v87: cache de 0,05s - Blade-Blade/Gas-Gas (DIRFRUIT) chamam isso em TODA fruitM1(), ate 3x por frame (Heartbeat/
    -- Stepped/RenderStepped) com o Click CPS no maximo. Escanear workspace.Enemies inteiro (GetChildren + GetAttribute +
    -- FindFirstChildOfClass por bicho) 3x no MESMO frame e trabalho redobrado pra nada - a lista de inimigos quase
    -- nunca muda dentro de 50ms. O FireServer do golpe continua rodando em toda chamada (isso NAO muda); so a varredura
    -- de quem esta vivo/perto e que passa a ser reaproveitada, liberando mais frame-time pro clique em si (mais rapido
    -- na pratica, principalmente com muitos inimigos na tela, que e onde o Gas-Gas mais trava).
    local dCache, dCacheAt = {}, 0
    local function dEnemies()
        local now = os.clock()
        if now - dCacheAt < 0.05 then return dCache end
        dCacheAt = now
        local f = workspace:FindFirstChild("Enemies")
        if not f then dCache = {}; return dCache end
        local out = {}
        for _, m in ipairs(f:GetChildren()) do
            if m.Parent and not m:GetAttribute("IsBoat") and not (Core.isFriendly and Core.isFriendly(m, LP)) then
                local h = m:FindFirstChildOfClass("Humanoid")
                local r = m:FindFirstChild("HumanoidRootPart") or m.PrimaryPart
                if h and h.Health > 0 and r then out[#out + 1] = { m, r } end
            end
        end
        dCache = out
        return out
    end
    local BLIND = Vector3.new(0.01, -500, 0.01)
    -- v55: o tiro as cegas so acerta quando o alvo esta embaixo do personagem; boss grande / ao lado nao levava dano.
    -- Se o inimigo mais perto NAO esta (quase) embaixo, manda a direcao dele no lugar do vetor fixo.
    local function blindDir()
        local _, hrp = getChar()
        if not hrp then return BLIND end
        local best, bd
        for _, e in ipairs(dEnemies()) do
            local d = e[2].Position - hrp.Position
            local m = d.Magnitude
            if m > 0.01 and m <= 110 and (not bd or m < bd.Magnitude) then bd = d end
        end
        if bd and bd.Y > -0.6 * bd.Magnitude then return bd.Unit end
        return BLIND
    end
    local FR = { combo = 0, last = 0, cdAt = 0 }
    -- v62: T-Rex tirado do BEAST (v43 tinha colocado ele aqui achando que precisava transformar com V igual
    -- Tiger/Leopard/Yeti/Mammoth, mas usuario confirmou explicitamente "nem a t rex" - NAO e isso). Com T-Rex fora
    -- do BEAST, ele cai no caminho generico (blind fire), igual Dragon-Dragon (o usuario confirmou que funciona assim pro Dragon).
    -- v110: Kitsune-Kitsune tirada do BEAST de novo - usuario quer o click NORMAL (sem V) funcionando, nao o
    -- transformado. v113: fica de fora do BEAST e do DIRFRUIT (ver comentarios ali em cima) - tiro as cegas comum.
    local BEAST = { "tiger", "leopard", "yeti", "mammoth", "mamute" }
    local function transform(char, tool)
        if FR.tChar == char then return end
        FR.tChar = char
        local n = string.lower(tool.Name)
        for _, k in ipairs(BEAST) do
            if string.find(n, k, 1, true) then
                task.spawn(function() task.wait(0.4); pressKey(Enum.KeyCode.V) end)
                return
            end
        end
    end
    local function stripCd()
        local now = os.clock()
        if now - FR.cdAt < 0.03 then return end
        FR.cdAt = now
        pcall(function()
            local char = LP.Character
            local tool = char and char:FindFirstChildOfClass("Tool")
            if not tool then return end
            -- v113: Kitsune-Kitsune usa uma marca/combo PROPRIA (visto em outro script de referencia do usuario:
            -- "KitsuneMarkActive") pra sequencia de ataque dela. Essa funcao zera QUALQUER atributo com "combo" no
            -- nome a cada 0,03s pra limpar cooldown falso de OUTRAS frutas - mas na Kitsune isso provavelmente
            -- zera o proprio contador que o jogo usa pra validar o proximo golpe, e e exatamente isso que
            -- explica "bate 1 e para": o servidor nunca ve o contador avancar porque a gente zera ele de volta
            -- antes do golpe seguinte. Pulando a Kitsune aqui (nao toca em nada do tool/char dela).
            if tool.Name == "Kitsune-Kitsune" then return end
            local function isCd(name)
                local n = string.lower(name)
                return string.find(n, "cooldown", 1, true) or string.find(n, "debounce", 1, true) or string.find(n, "combo", 1, true) or n == "cd" or string.find(n, "delay", 1, true)
            end
            for _, holder in ipairs({ tool, char }) do
                for name, v in pairs(holder:GetAttributes()) do
                    if isCd(name) then
                        if type(v) == "number" then holder:SetAttribute(name, 0)
                        elseif type(v) == "boolean" and v == true and string.find(string.lower(name), "cooldown", 1, true) then holder:SetAttribute(name, false) end
                    end
                end
            end
            for _, d in ipairs(tool:GetDescendants()) do
                if (d:IsA("NumberValue") or d:IsA("IntValue")) and isCd(d.Name) then d.Value = 0
                elseif d:IsA("BoolValue") and string.find(string.lower(d.Name), "cooldown", 1, true) then d.Value = false end
            end
        end)
    end
    -- v54: alvo da fruta = inimigo mais perto no alcance; sem inimigo, a parte que a farm escolheu (pedra, vaso, arvore)
    function Core.fruitTarget(hrp)
        local tg = Core.targets(60)
        if tg[1] then return tg[1][2] end
        local ex = Core.extra and Core.extra()
        if typeof(ex) == "Instance" and ex:IsA("BasePart") and ex.Parent and (ex.Position - hrp.Position).Magnitude < 150 then return ex end
    end
    -- v121: pedido do usuario - "arruma todo o m1 fruit igual o bomba lua, quero tudo absolutamente tudo igual".
    -- Reescrito pra seguir a ORDEM EXATA do f102/f103/f104/f105 do bomba.lua:
    --   1) pega a ferramenta equipada
    --   2) se ela tiver o atributo "ServerState" preenchido, NAO faz nada (golpe anterior ainda em andamento) -
    --      essa checagem vem ANTES de confirmar que e fruta, igual o bomba faz em cima do "v776" bruto
    --   3) so DEPOIS confere se e mesmo "Blox Fruit" (ToolTip) e se tem o LeftClickRemote
    --   4) Blade-Blade/Gas-Gas (DIRFRUIT) miram a direcao de cada inimigo com contador de combo 1-5; todo o
    --      resto manda o tiro as cegas Vector3(0.01,-500,0.01),1,true - exatamente como o bomba.
    -- A unica coisa que o bomba NAO tem e que a gente mantem por fora (nao muda o golpe em si): o anti-fantasma
    -- (Core.firedAt), o transform() do BEAST (V-key de Tiger/Leopard/Yeti/Mammoth, pedido separado do usuario) e
    -- o respeito ao Click CPS de Farm Settings (cfg.cps) - que no padrao (120+) nao limita nada, so existe pra
    -- quem QUISER deixar mais devagar de proposito.
    local function fruitM1()
        local char, hrp = getChar()
        local tool = char and char:FindFirstChildOfClass("Tool")
        if tool and tool:GetAttribute("ServerState") ~= nil then Core.why = tool.Name .. ": ServerState busy, aguardando"; return end
        if not (tool and hrp) then Core.why = "fruit M1: no character/tool"; return end
        if tool.ToolTip ~= "Blox Fruit" then Core.why = "fruit M1: wrong tool in hand (" .. tostring(tool.ToolTip) .. ")"; return end
        local remote = tool:FindFirstChild("LeftClickRemote")
        local fname = tool.Name
        if not remote then Core.why = fname .. ": no LeftClickRemote"; return end
        local fGap = Core.cpsGap()
        -- v127: usuario - "na kitsune ele para de bater completamente depois do primeiro hit". Hipotese (nao testada
        -- ao vivo): Kitsune/T-Rex tem maquina de estado no servidor; o "ServerState" so aparece no cliente depois do
        -- ping, e ate la a gente (6 chamadas/frame) mandava dezenas de cliques - o servidor entende como spam/estado
        -- trocado e para de aceitar. O bomba chama a cada 0,05s e por isso so manda 1-3 cliques nessa janela.
        -- So essas 2 frutas ficam no ritmo exato do bomba (0,05s); as demais seguem sem limite.
        local sg = STATEFUL[fname]
        if sg and sg > fGap then fGap = sg end
        if fGap > 0 and os.clock() - (FR.fireAt or 0) < fGap then return end
        FR.fireAt = os.clock()
        Core.firedAt = os.clock()   -- v53: o anti-fantasma (stallScan) tambem vale para a fruta
        transform(char, tool)       -- BEAST (Tiger/Leopard/Yeti/Mammoth): transforma com V antes do golpe
        if DIRFRUIT[fname] then
            if os.clock() - FR.last > 0.65 then FR.combo = 0 end
            local range = tonumber(cfg.range) or 60
            local any = false
            FR.combo = (FR.combo >= 5) and 1 or (FR.combo + 1)
            FR.last = os.clock()
            for _, e in ipairs(dEnemies()) do
                local d = e[2].Position - hrp.Position
                if d.Magnitude <= range and d.Magnitude > 0.01 then
                    any = true
                    pcall(remote.FireServer, remote, d.Unit, FR.combo)
                end
            end
            Core.why = any and (fname .. ": remote fire (combo " .. FR.combo .. ")") or (fname .. ": no enemy in range")
        else
            -- v82: "todos os clicks de fruta ainda mais rapidos": 3 tiros por chamada (x3 motores = ~9 por frame). Kitsune/T-Rex (STATEFUL)
            -- ficam em 1 por chamada: o servidor deles para de aceitar se receber varios antes do estado voltar.
            local shots = sg and 1 or 3
            local bd = blindDir()
            for _ = 1, shots do pcall(remote.FireServer, remote, bd, 1, true) end
            Core.why = fname .. ": remote fire (blind x" .. shots .. ")"
        end
    end

    -- ---------------------------------------------------- Double Attack ----
    -- (script enviado pelo usuario): a fruta na mao + outra fruta da mochila batem ao mesmo tempo
    -- v67: DIRFRUIT e dEnemies() agora moraram pra cima (perto do fruitM1), reaproveitados por aqui tambem - mesma
    -- fonte direta de inimigos pros dois, sem depender de Core.targets()/toggle de selecao de alvo.
    local dClick, dLast = 0, 0
    local function dirAttack(tool, count)
        local remote = tool:FindFirstChild("LeftClickRemote")
        local _, hrp = getChar()
        if not remote or not hrp then return end
        local range = tonumber(cfg.range) or 60
        for _, e in ipairs(dEnemies()) do
            local d = e[2].Position - hrp.Position
            if d.Magnitude <= range and d.Magnitude > 0.01 then
                pcall(remote.FireServer, remote, d.Unit, count)
            end
        end
    end
    -- v72 fix: a v66 tinha adicionado uma "mira" aqui por conta propria (um segundo FireServer mandando a
    -- POSICAO ABSOLUTA do alvo no lugar da direcao) que NAO existe no script de referencia - o LeftClickRemote
    -- espera sempre o mesmo formato (um vetor pequeno tipo direcao, nao a posicao no mundo); mandar a posicao
    -- do jeito errado faz o servidor rejeitar/atrapalhar esse golpe (e possivelmente os seguintes, se ele guarda
    -- algum estado por tool). Voltado a ser EXATAMENTE o blind-fire do script de referencia: 1 unico FireServer,
    -- sempre o mesmo vetor fixo - e o proprio jogo que decide quem leva o dano.
    local function plainAttack(tool)
        local remote = tool:FindFirstChild("LeftClickRemote")
        if not remote then return end
        pcall(remote.FireServer, remote, blindDir(), 1, true)
    end
    -- v102: pedido do usuario - "nao bate com a 2a fruta" (confirmado). O codigo antigo tentava disparar o
    -- LeftClickRemote de uma fruta que NAO estava equipada (so na mochila) ao MESMO TEMPO que a equipada. Fui
    -- conferir o bomba.lua pra portar (como pedido) e achei o motivo real: o mecanismo "2 frutas ao mesmo tempo"
    -- dele tambem existe (AttackConfig.DoubleAttack) mas NUNCA e ativado em lugar nenhum do script - fica morto,
    -- sempre false; nem o bomba realmente consegue bater com a fruta da mochila sem equipar ela primeiro. O motivo:
    -- o jogo so processa o clique da fruta que esta DE VERDADE equipada no personagem - disparar o remote de uma
    -- fruta so na mochila e ignorado pelo servidor (sem erro nenhum do lado do cliente, so nao bate nada - exatamente
    -- o sintoma relatado). Arrumado de forma que REALMENTE funciona: alterna o equip entre as 2 frutas
    -- (hum:EquipTool) a cada DA.interval segundos e so bate com a que estiver de fato equipada no momento - as 2
    -- acabam batendo de verdade, alternando, em vez de uma ficar so "disparando no vazio".
    local DA = { turn = 1, swapAt = 0 }
    local function secondFruit(primary)
        for _, it in ipairs(LP.Backpack:GetChildren()) do
            if it:IsA("Tool") and it.ToolTip == "Blox Fruit" and it ~= primary then return it end
        end
    end
    local function hitFruit(tool)
        if DIRFRUIT[tool.Name] then
            if os.clock() - dLast > 0.65 then dClick = 0 end
            dClick = (dClick >= 5) and 1 or (dClick + 1)
            dLast = os.clock()
            dirAttack(tool, dClick)
        else
            plainAttack(tool)
        end
    end
    local function doubleAttack()
        local char, hrp, hum = getChar()
        if not (char and hrp and hum) then return end
        local equipped = char:FindFirstChildOfClass("Tool")
        if equipped and equipped:GetAttribute("ServerState") ~= nil then return end
        local primary = (equipped and equipped.ToolTip == "Blox Fruit") and equipped or nil
        if not primary then
            for _, it in ipairs(LP.Backpack:GetChildren()) do
                if it:IsA("Tool") and it.ToolTip == "Blox Fruit" then primary = it; break end
            end
        end
        if not primary then return end
        if equipped == primary and not primary:FindFirstChild("LeftClickRemote") then return end
        local second = secondFruit(primary)
        if not second then
            -- so uma fruta: garante ela equipada e bate normal (nada pra alternar)
            if equipped ~= primary then pcall(function() hum:EquipTool(primary) end); return end
            hitFruit(primary)
            return
        end
        -- 2 frutas: troca qual esta equipada a cada DA.interval segundos (da tempo da troca replicar pro servidor
        -- antes de bater) e so dispara o clique com a que estiver REALMENTE equipada no momento
        local now = os.clock()
        local interval = math.clamp(tonumber(cfg.daSwap) or 0.35, 0.15, 0.6)
        if now - DA.swapAt >= interval then DA.swapAt = now; DA.turn = (DA.turn == 1) and 2 or 1 end
        local want = (DA.turn == 1) and primary or second
        if equipped ~= want then pcall(function() hum:EquipTool(want) end); return end
        hitFruit(want)
    end

    -- ------------------------------------------------- Melee / Sword (Net) ----
    local Net = { ready = false, err = "starting..." }
    task.spawn(function()
        local ok, err = pcall(function()
            local modules = RS:WaitForChild("Modules", 40)
            local folder = modules and modules:WaitForChild("Net", 40)
            assert(folder, "Net module not found")
            Net.module = require(folder)
            Net.reg = folder:WaitForChild("RE/RegisterAttack", 40)
            Net.hit = folder:WaitForChild("RE/RegisterHit", 40)
            assert(Net.reg and Net.hit, "attack remotes not found")
            local okH, re = pcall(function() return Net.module:RemoteEvent("RegisterHit", true) end)
            Net.hitRE = (okH and re) or Net.hit
        end)
        Net.ready, Net.err = ok, ok and "ok" or tostring(err)
    end)
    Core.net = Net
    -- Hit extra de validacao: remote com atributo "Id" + chave do "seed". No attack.lua.txt (o script enviado pelo
    -- usuario) essa chamada roda em TODA iteracao do loop de Melee/Sword, sem throttle nenhum (so o InvokeServer
    -- em si, que espera a resposta do servidor, da o ritmo real) - e vem IMEDIATAMENTE depois do RegisterHit,
    -- com o MESMO head/lista. A gente tinha colocado um limite de "no maximo 10x por segundo" por conta propria,
    -- sem base em nenhuma referencia - e com Attack Method em Super/Hyper (ate 50 golpes/s) isso deixava MUITOS
    -- golpes sem o acompanhamento de validacao, o que pode ser exatamente o motivo de "ataca mas nao registra".
    -- v122: tirado o limite de tempo (so falta mesmo quando a chamada anterior ainda esta esperando resposta do
    -- servidor - SEC.busy - pra nao empilhar InvokeServer em paralelo), chamado em TODO netAttack() igual a
    -- referencia.
    local SEC = { remote = nil, id = nil, busy = false }
    local function findSecure()
        if SEC.remote and SEC.remote.Parent then return end
        for _, n in ipairs({ "Util", "Common", "Remotes", "Assets", "FX" }) do
            local f = RS:FindFirstChild(n)
            if f then
                for _, c in ipairs(f:GetChildren()) do
                    if c:IsA("RemoteEvent") and c:GetAttribute("Id") then SEC.remote, SEC.id = c, c:GetAttribute("Id") end
                end
            end
        end
    end
    function Core.secureHit(head, list)
        if SEC.busy or not Net.ready then return end
        SEC.busy = true
        task.spawn(function()
            pcall(function()
                findSecure()
                local seed = Net.module and RS.Modules.Net:FindFirstChild("seed")
                if not (SEC.remote and SEC.id and seed and bit32) then return end
                local k = string.gsub("RE/RegisterHit", ".", function(c)
                    return string.char(bit32.bxor(string.byte(c), math.floor((workspace:GetServerTimeNow() / 10) % 10) + 1))
                end)
                local key = bit32.bxor(SEC.id + 909090, seed:InvokeServer() * 2)
                local cr = cloneref or function(x) return x end
                cr(SEC.remote):FireServer(k, key, head, list)
            end)
            SEC.busy = false
        end)
    end
    -- CanAttack do jogo sempre liberado (nao trava o golpe por estado do cliente); varinhas de pesca ficam como estao
    task.spawn(function()
        pcall(function()
            local cu = require(RS:WaitForChild("Modules", 20):WaitForChild("CombatUtil", 20))
            if cu and cu.CanAttack and hookfunction and not getgenv().MoonCanAttackHook then
                getgenv().MoonCanAttackHook = true
                local orig
                orig = hookfunction(cu.CanAttack, function(...)
                    local ch = LP.Character
                    local tl = ch and ch:FindFirstChildOfClass("Tool")
                    if tl and (tl:GetAttribute("ServerState") ~= nil or string.find(tl.Name, "Rod", 1, true)) then return orig(...) end
                    return true
                end)
            end
        end)
    end)
    local PARTS = { "RightLowerArm", "RightUpperArm", "LeftLowerArm", "LeftUpperArm", "RightHand", "LeftHand" }
    -- O servidor so processa algumas vagas por golpe (4; 10 com a fruta Buddha). Por isso os alvos vao em LOTES dessa
    -- largura e cada golpe leva um lote, em rodizio: todos os NPCs no alcance apanham, nao so os 2-4 mais perto.
    -- Fantasmas (mobs puxados que o servidor nao reconhece) vao por ultimo para nao gastar as vagas.
    local NA = { cursor = 0, sent = 0 }
    Core.na = NA
    -- v63: antes a animacao rapida (swing 5x mais veloz) e o disparo de hit so vinham juntos no modo "Super Fast";
    -- no "Classic" o golpe acertava todo mundo no alcance mas SEM nenhuma animacao, o que fazia o Melee/Sword parecer
    -- 2 sistemas diferentes e desconectados. Agora a animacao fica EMBUTIDA no mesmo clique de sempre (netAttack),
    -- entao so existe UM click de Melee/Sword, que anima E acerta todo mundo no alcance ao mesmo tempo.
    local M1ANIM = { cu = nil, animAt = 0 }
    task.spawn(function()
        pcall(function() M1ANIM.cu = require(RS:WaitForChild("Modules", 20):WaitForChild("CombatUtil", 20)) end)
    end)
    local function playM1Anim(char)
        if cfg.noM1Anim then return end   -- v64: "Attack No Animation" (Farm Settings) - pedido baseado nos scripts de referencia
        local CU = M1ANIM.cu
        if not CU then return end
        local now = os.clock()
        if now - M1ANIM.animAt < 0.08 then return end   -- nao tenta tocar de novo a cada tick, so a cada 80ms
        M1ANIM.animAt = now
        pcall(function()
            local humanoid = char:FindFirstChildOfClass("Humanoid")
            local equipped = char:FindFirstChild("EquippedWeapon")
            if not (humanoid and equipped) then return end
            local name = CU:GetWeaponName(equipped)
            local basic = #CU:GetWeaponData(name).Moveset.Basic
            local key = CU:GetPureWeaponName(name) .. "-basic" .. math.random(1, basic)
            local anim = CU:GetMovesetAnimCache(humanoid)[key]
            if anim then
                anim:Play(0, 1, (anim:GetAttribute("SpeedMult") or 1) * 5)
                anim.TimePosition = 0.01
            end
        end)
    end
    -- v69: Melee/Sword tambem estava preso ao Core.targets(), que SO devolve algo se a selecao de alvo (NPC/BOSS/
    -- PLAYER) nas configs estiver marcada do jeito certo - o MESMO bug raiz achado antes no Double Attack e no M1
    -- de fruta ("para de funcionar do nada"). O script de referencia que o usuario mandou (attack.lua) le direto
    -- workspace.Enemies E workspace.Characters (olha os dois, pra pegar NPC e jogador junto), sem depender de
    -- nenhum toggle. meleeTargets() reproduz exatamente isso, no mesmo formato {modelo, raiz, humanoid, distancia,
    -- fantasma} que Core.targets ja devolvia, pra nao precisar tocar no resto do netAttack/superAttack/recover.
    local function meleeTargets(range)
        local _, hrp = getChar()
        if not hrp then return {} end
        local out = {}
        for _, fname in ipairs({ "Enemies", "Characters" }) do
            local f = workspace:FindFirstChild(fname)
            if f then
                for _, m in ipairs(f:GetChildren()) do
                    if m ~= LP.Character and not m:GetAttribute("IsBoat") and not Core.isFriendly(m, LP) then
                        local h = m:FindFirstChildOfClass("Humanoid")
                        local r = m:FindFirstChild("HumanoidRootPart")
                        if h and r and h.Health > 0 then
                            local d = (r.Position - hrp.Position).Magnitude
                            if d <= range then out[#out + 1] = { m, r, h, d, Core.isGhost(m) } end
                        end
                    end
                end
            end
        end
        table.sort(out, function(a, b) return a[4] < b[4] end)
        return out
    end
    local function netAttack(tip)
        if not Net.ready then Core.why = "Net not ready: " .. tostring(Net.err); return end
        local char, root = getChar()
        if not root then Core.why = "no character"; return end
        local tool = char:FindFirstChildOfClass("Tool")
        -- v120: pedido do usuario - "100% igual o attack.lua". Esse script SO confia em tool:GetAttribute("WeaponType")
        -- pra Melee/Sword, sem nenhum fallback de ToolTip. Trocado aqui pra uma checagem dedicada, exatamente igual
        -- (o wtip() com fallback continua existindo e sendo usado so pelo equip(), pra achar a ferramenta certa na
        -- mochila - isso nao muda o golpe em si).
        local wt = tool and tool:GetAttribute("WeaponType")
        if not tool or wt ~= tip then Core.why = "wrong/no tool in hand (" .. tostring(wt) .. ", want " .. tip .. ")"; return end
        -- v115: pedido do usuario - "tira todas as travas de seguranca e limitador do click de soco e espada,
        -- coloca pra torar". Antes esperava ate 0,8s vendo o atributo "Stun" antes de bater mesmo assim; agora
        -- bate direto, sem esperar nada, estuporado ou nao.
        Core.stunAt = nil
        playM1Anim(char)   -- v63: animacao do golpe embutida no mesmo click que acerta todo mundo no alcance
        -- v126: pedido do usuario - "melhore todos os clicks, deixe mais rapidos". O ritmo de disparo ja e ate 6
        -- chamadas por frame (bem acima do attack.lua/bomba) - subir isso de novo repetiria o que filtrou o click
        -- antes. O ganho real e tirar CUSTO de cada chamada: a varredura de Enemies+Characters, o sort e a montagem
        -- da lista de partes (ate 160 entradas) rodavam do zero em TODA chamada (ate 6x no mesmo frame, mesmo
        -- resultado). Agora a varredura+lista sao reaproveitadas por 0,03s (menos que 2 frames) - o FireServer
        -- continua saindo em TODA chamada, igual; so o trabalho repetido some, sobrando FPS (principalmente no celular).
        local rng = tonumber(cfg.range) or 60
        local nowC = os.clock()
        local NC = NA.cache
        local tg
        if NC and NC.rng == rng and nowC - NC.at < 0.03 and NC.char == char then
            tg = NC.tg
        else
            tg = meleeTargets(rng)                                   -- sem limite: todos os NPCs/jogadores dentro do alcance
            if #tg > 1 then
                -- v137: pedido do usuario - Soco/Espada com o MESMO Bring Mob da fruta, "pegando em todos os NPCs". Os mobs
                -- que o Bring Mob puxou agora (Core.pulledAt < 1 s) vao PRIMEIRO na lista (a cabeca do 1o alvo e a que
                -- o hit leva), depois os outros no alcance, e fantasma por ultimo.
                local pa = Core.pulledAt
                local function rank(t)
                    if t[5] then return 2 end
                    local at = pa[t[1]]
                    return (at and nowC - at < 1) and 0 or 1
                end
                table.sort(tg, function(a, b)
                    local ga, gb = rank(a), rank(b)
                    if ga ~= gb then return ga < gb end
                    return a[4] < b[4]
                end)
            end
            NC = { tg = tg, at = nowC, rng = rng, char = char }
            NA.cache = NC
        end
        if #tg == 0 then Core.why = "no enemy within " .. tostring(cfg.range) .. " studs"; return end
        local hash = tostring(LP.UserId):sub(2, 4) .. tostring(coroutine.running()):sub(11, 15)
        -- v116: pedido do usuario - depois do v115 (tirar os freios), o click de Soco/Espada PAROU de pegar de
        -- vez ("n pega mais"). O "reps" (3 a 6 FireServer IDENTICOS, com o MESMO hash, por chamada) nao existe em
        -- NENHUM script de referencia (attack.lua/bomba.lua/vxeze) - eles disparam UMA vez por iteracao e dependem
        -- do proprio loop (while/task.wait) pra repetir. Suspeita forte: mandar varias copias do mesmo hit no
        -- MESMO instante (ja vinhamos chamando essa funcao ate 3x por frame, por 3 motores, sem limite de CPS)
        -- e o tipo de coisa que o anti-exploit do jogo pode comecar a filtrar/ignorar depois de um tempo - e o
        -- v115 tirando o freio de lag so piorou isso. Voltando a UM disparo por chamada, exatamente como a
        -- referencia - os 3 motores (Heartbeat/Stepped/RenderStepped) + Click CPS continuam dando o ritmo rapido.
        if os.clock() >= (Core.legacyUntil or 0) then
            -- (v26) formato do script do usuario (MoonHub/attack.lua): UM pacote com TODAS as partes de TODOS os NPCs no alcance
            --   RegisterAttack:FireServer() ; RegisterHit:FireServer(cabeca, {{modelo, parte}...}, {}, hash)
            local list, head, nE
            if NC.list then
                list, head, nE = NC.list, NC.head, NC.nE      -- v126: lista de partes ja montada neste ciclo de 0,03s
            else
                list, head, nE = {}, nil, 0
                for _, t in ipairs(tg) do
                    local m = t[1]
                    -- v130: revertido o v129 (1 entrada por NPC) - o usuario relatou que depois dele o Soco/Espada nem
                    -- clicava mais. Voltou a lista COMPLETA de partes de cada NPC, igual ao attack.lua (que ele confirmou
                    -- que funciona).
                    local n0 = #list
                    for _, part in ipairs(m:GetChildren()) do
                        if part:IsA("BasePart") then list[#list + 1] = { m, part } end
                    end
                    if #list == n0 then list[#list + 1] = { m, t[2] } end
                    head = head or m:FindFirstChild("Head") or t[2]
                    nE = nE + 1
                end
                NC.list, NC.head, NC.nE = list, head, nE
            end
            if Core.why and not string.find(Core.why, "stuck stun", 1, true) then Core.why = string.format("attacking %d target(s) in one hit", nE) end
            -- v122: o attack.lua.txt chama isso em TODA iteracao do loop (nao so de vez em quando) - tirado o
            -- limite de 0,5s, igual a referencia.
            pcall(function() Net.module:RemoteEvent("RegisterHit", true) end)
            Net.reg:FireServer()
            Net.hit:FireServer(head, list, {}, hash)
            NA.sent += 1
            Core.firedAt = os.clock()
            Core.secureHit(head, list)
            return
        end
        -- formato antigo (reserva automatica quando o novo fica sem causar dano): lotes de 10 (15 com Buddha), uma parte do corpo por alvo
        -- v115: pedido do usuario - "pegar em 10 npc de uma vez" - o lote minimo subiu de 4 pra 10 (sem Buddha ja garante os 10)
        local cap = (root:FindFirstChild("Buddha") or char:FindFirstChild("Buddha")) and 15 or 10
        local nCh = math.ceil(#tg / cap)
        NA.cursor = NA.cursor % nCh + 1
        local lo = (NA.cursor - 1) * cap + 1
        local hits, first = {}, nil
        for i = lo, math.min(#tg, lo + cap - 1) do
            local t = tg[i]
            local p = t[1]:FindFirstChild(PARTS[math.random(#PARTS)]) or t[2]
            hits[#hits + 1] = { t[1], p }
            first = first or p
        end
        if not first then return end
        if Core.why and not string.find(Core.why, "stuck stun", 1, true) then Core.why = string.format("attacking %d target(s), %d per hit (legacy format)", #tg, #hits) end
        Net.reg:FireServer(0)
        Net.hitRE:FireServer(first, hits, nil, nil, hash)
        NA.sent += 1
        Core.firedAt = os.clock()
        Core.secureHit(first, hits)
    end

    -- ------------------------------------------ v54d: SUPER FAST ATTACK (M1 de Melee e Sword) ----
    -- Codigo enviado pelo usuario: RegisterAttack(0) + animacao basica acelerada 5x (CombatUtil) + RegisterHit numa parte do
    -- corpo dos alvos mais perto (2 alvos, 10 com Buddha). Ritmo pelo Attack Method: Fast 0,05 s | Super 0,03 s | Hyper 0,02 s.
    -- Farm Settings > "Melee / Sword M1": "Super Fast" (este) ou "Classic" (o ataque antigo do hub).
    local SFA = { at = 0, cu = nil }
    task.spawn(function()
        pcall(function() SFA.cu = require(RS:WaitForChild("Modules", 20):WaitForChild("CombatUtil", 20)) end)
    end)
    local SFA_GAP = { ["Normal Attack"] = 0.05, ["Fast Attack"] = 0.03 }
    local function superAttack(tip)
        if not Net.ready then Core.why = "Net not ready: " .. tostring(Net.err); return end
        local now = os.clock()
        if now - SFA.at < (SFA_GAP[cfg.method] or 0.03) then return end
        local char, hrp = getChar()
        local tool = char and char:FindFirstChildOfClass("Tool")
        if not (hrp and tool and wtip(tool) == tip) then
            Core.why = "wrong/no tool in hand (" .. (tool and tostring(wtip(tool)) or "none") .. ", want " .. tip .. ")"
            return
        end
        local stun = char:FindFirstChild("Stun")
        if stun and stun.Value ~= 0 then
            Core.stunAt = Core.stunAt or now
            if now - Core.stunAt < 0.8 then Core.why = "stunned (Stun=" .. tostring(stun.Value) .. ")"; return end
        else
            Core.stunAt = nil
        end
        local tg = meleeTargets(tonumber(cfg.range) or 60)
        if #tg == 0 then Core.why = "no enemy within " .. tostring(cfg.range) .. " studs"; return end
        if #tg > 1 then
            -- fantasmas (puxados que o servidor nao reconhece) por ultimo, senao gastam as vagas do golpe
            table.sort(tg, function(a, b)
                local ga, gb = a[5] and 1 or 0, b[5] and 1 or 0
                if ga ~= gb then return ga < gb end
                return a[4] < b[4]
            end)
        end
        SFA.at = now
        -- 1) registra o ataque
        pcall(function() Net.reg:FireServer(0) end)
        -- 2) animacao basica acelerada 5x
        local CU = SFA.cu
        if CU then
            pcall(function()
                local humanoid = char:FindFirstChildOfClass("Humanoid")
                local equipped = char:FindFirstChild("EquippedWeapon")
                if not (humanoid and equipped) then return end
                local name = CU:GetWeaponName(equipped)
                local basic = #CU:GetWeaponData(name).Moveset.Basic
                local key = CU:GetPureWeaponName(name) .. "-basic" .. math.random(1, basic)
                local anim = CU:GetMovesetAnimCache(humanoid)[key]
                if anim then
                    anim:Play(0, 1, (anim:GetAttribute("SpeedMult") or 1) * 5)
                    anim.TimePosition = 0.01
                end
            end)
        end
        -- 3) alvos: os mais perto (2, ou 10 com Buddha), cada um numa parte do corpo
        local part = PARTS[math.random(#PARTS)]
        local cap = (hrp:FindFirstChild("Buddha") or char:FindFirstChild("Buddha")) and 10 or 2
        local targets = {}
        for i = 1, math.min(#tg, cap) do
            local m = tg[i][1]
            targets[i] = { m, m:FindFirstChild(part) or tg[i][2] }
        end
        -- 4) registra o hit (o servidor aplica o dano)
        local hash = tostring(LP.UserId):sub(2, 4) .. tostring(coroutine.running()):sub(11, 15)
        local hit = Net.hitRE or Net.hit
        pcall(function() hit:FireServer(targets[1][2], targets, nil, nil, hash) end)
        NA.sent += 1
        Core.firedAt = now
        Core.why = string.format("super fast attack: %d target(s)", #targets)
    end
    -- v63: nao existe mais escolha entre "Classic" e "Super Fast" - os dois eram o mesmo golpe (acerta todo mundo no
    -- alcance) só que um tinha animacao e o outro nao, parecendo 2 sistemas separados. Agora so tem UM click de
    -- Melee/Sword (netAttack, com a animacao embutida via playM1Anim la dentro). superAttack() fica guardado sem uso
    -- (nao foi apagado pra nao perder o codigo), caso algum dia precise voltar a atacar so os 2 mais perto.
    local function meleeM1(tip)
        netAttack(tip)
    end

    -- ------------------------------------------ anti-travada (Melee / Sword) ----
    -- Se os alvos nao perdem vida por um tempo, o M1 travou: reforca com o golpe do proprio jogo (CombatFramework),
    -- re-equipa a arma e renova o remote do Net. Volta ao normal sozinho quando o dano volta.
    local CFW = { ctrl = nil, tried = false }
    task.spawn(function()
        CFW.tried = true
        pcall(function()
            local mod = require(LP.PlayerScripts:WaitForChild("CombatFramework", 10))
            local gu = getupvalues or (debug and debug.getupvalues)
            CFW.ctrl = gu(mod)[2]
        end)
    end)
    -- v136: relato de comprador - "so mata o NPC depois de 1 click manual e mesmo assim nao conta xp/dinheiro". Suspeita (nao
    -- confirmada): o controlador do CombatFramework nao foi achado no executor dele (a busca de cima roda UMA vez e falha
    -- em silencio), entao o golpe do proprio jogo nunca saia - so os RegisterHit soltos, que o servidor nao credita. Agora:
    -- (1) tenta achar o controlador de novo a cada 3 s; (2) se ainda nao existe, usa tool:Activate() como reserva.
    local function cfFind()
        if CFW.ctrl or os.clock() - (CFW.retryAt or 0) < 3 then return end
        CFW.retryAt = os.clock()
        pcall(function()
            local ps = LP:FindFirstChild("PlayerScripts")
            local m = ps and ps:FindFirstChild("CombatFramework")
            local gu = getupvalues or (debug and debug.getupvalues)
            if m and gu then CFW.ctrl = gu(require(m))[2] end
        end)
    end
    local function cfAttack()
        pcall(function()
            cfFind()
            local ctrl = CFW.ctrl and CFW.ctrl.activeController
            if not ctrl then
                local ch = LP.Character
                local tl = ch and ch:FindFirstChildOfClass("Tool")
                if tl then pcall(function() tl:Activate() end) end
                return
            end
            ctrl.hitboxMagnitude = 60       -- alcance do golpe (jogador longe do mob)
            ctrl.timeToNextAttack = 0       -- sem espera entre um golpe e outro
            ctrl.attacking = false
            ctrl:attack()
        end)
    end
    -- Fantasma por falta de dano: um mob no alcance, que estamos atingindo, e que nao perde vida enquanto os outros perdem
    -- (ou que foi puxado e continua intacto por muito tempo) e tratado como fantasma. Quem so nao leva golpe nao conta.
    local MH = setmetatable({}, { __mode = "k" })      -- modelo -> { hp, since }
    Core.mh = MH
    local lastDropAt = 0
    local function stallScan(tg, now)
        local firing = now - (Core.firedAt or 0) < 0.6
        for _, t in ipairs(tg) do
            local m, h = t[1], t[3]
            local rec = MH[m]
            if not rec then
                MH[m] = { hp = h.Health, since = now }
            else
                if h.Health < rec.hp - 0.01 then rec.hp, rec.since = h.Health, now; lastDropAt = now
                elseif h.Health > rec.hp then rec.hp = h.Health end
                if not firing then rec.since = now end              -- so conta o tempo em que estamos mesmo batendo
                if not t[5] and not Players:GetPlayerFromCharacter(m) then
                    -- (v25) fantasma = intacto enquanto os OUTROS perdem vida (7 s) ou, se ninguem mais apanha (ex.: so ele sobrou), 20 s
                    local boss = isBoss(m, h)
                    local lim
                    -- v63: NPC que nao perde vida em 5 s enquanto voce bate nele e trocado (pedido do usuario -
                    -- antes era 6s); boss continua com mais folga
                    if boss then lim = (now - lastDropAt < 1.5) and 14 or 30 else lim = 5 end
                    if now - rec.since > lim then MH[m] = nil; Core.markGhost(m, 10) end
                end
            end
        end
    end
    local WD = { hp = nil, n = 0, at = os.clock(), lvl = 0, reAt = 0, netAt = 0 }
    Core.wd = WD
    local function recover(tip)
        local now = os.clock()
        local tg = meleeTargets(tonumber(cfg.range) or 60)
        if #tg == 0 then WD.hp, WD.n, WD.at, WD.lvl = nil, 0, now, 0; return end
        -- v137: o anti-fantasma da FRUTA so olha quem esta bem embaixo (Core.targets(12)); o do Soco/Espada olhava TODO mob em
        -- 60 studs - mob real que o servidor nao registra ainda (fora do alcance dele) ficava 5 s sem perder vida, virava
        -- "fantasma" e saia do Bring Mob, e o grupo puxado encolhia ("nao pega em todos"). Agora, havendo mobs puxados
        -- pelo Bring Mob, so eles entram no teste (o fantasma de verdade e um mob PUXADO que nao apanha).
        local pulled = {}
        for _, t in ipairs(tg) do
            local at = Core.pulledAt[t[1]]
            if at and now - at < 1 then pulled[#pulled + 1] = t end
        end
        stallScan(#pulled > 0 and pulled or tg, now)
        local sum = 0
        for _, t in ipairs(tg) do sum = sum + t[3].Health end
        if WD.hp == nil or WD.n ~= #tg or sum < WD.hp - 0.01 then
            WD.hp, WD.n, WD.at, WD.lvl = sum, #tg, now, 0      -- causou dano (ou o alvo mudou): tudo certo
            return
        end
        if sum > WD.hp then WD.hp = sum end
        local stall = now - WD.at
        WD.lvl = stall > 4 and 3 or (stall > 2 and 2 or (stall > 0.7 and 1 or 0))
        -- v135: removida a troca automatica pro "formato antigo" (lotes de 10, 1 parte por alvo) quando fica 2s sem dano: perto de
        -- mobs fantasma ela disparava toda hora e o Soco/Espada passava a bater no formato fraco ("nao mata direito"). Agora o
        -- golpe e SEMPRE o do attack.lua (todas as partes de todos os alvos no alcance).
        if WD.lvl >= 1 and now - (WD.cfAt or 0) > 0.25 then WD.cfAt = now; cfAttack() end   -- reforco: golpe do jogo (4x por segundo)
        if WD.lvl >= 2 and now - WD.reAt > 3 then WD.reAt = now; lastEquip = 0; equip(tip) end   -- garante a arma na mao
        if WD.lvl >= 3 and now - WD.netAt > 3 then                               -- renova o remote do Net
            WD.netAt = now
            pcall(function()
                local okH, re = pcall(function() return Net.module:RemoteEvent("RegisterHit", true) end)
                Net.hitRE = (okH and re) or Net.hit
            end)
            WD.at = now - 1.5
        end
    end

    -- v53: anti-fantasma para a FRUTA. Antes so rodava com Melee/Sword: com fruta, mob puxado que o servidor nao acompanhou
    -- (aparece puxado so na sua tela) nunca perdia vida e o Level Farm ficava batendo nele para sempre ("mata 1 e para").
    -- Agora quem nao perde vida e marcado como fantasma por alguns segundos e a farm segue para os mobs de verdade.
    local fruitWatchAt = 0
    local function fruitWatch()
        local now = os.clock()
        if now - fruitWatchAt < 0.2 then return end
        fruitWatchAt = now
        local tg = Core.targets(12)
        if #tg > 0 then stallScan(tg, now) end
    end

    -- -------------------------------------------------------- motor ----
    local lastTick = 0
    local function equipByName(sub)
        local char, _, hum = getChar()
        if not (char and hum) then return nil end
        local cur = char:FindFirstChildOfClass("Tool")
        if cur and string.find(string.lower(cur.Name), sub, 1, true) then return cur end
        if os.clock() - lastEquip < 0.15 then return cur end   -- v54: re-equipa mais rapido (0,3 s -> 0,15 s)
        lastEquip = os.clock()
        for _, t in ipairs(LP.Backpack:GetChildren()) do
            if t:IsA("Tool") and string.find(string.lower(t.Name), sub, 1, true) then pcall(function() hum:EquipTool(t) end); return t end
        end
        return cur
    end
    -- Click CPS (Farm Settings): 120 ou mais = sem limite (um ataque por frame); menos que isso espaca os ataques
    function Core.cpsGap()
        return 0   -- v135: pedido do usuario - "tira todas as travas do click": sem limite de CPS (o slider Click CPS nao limita mais)
    end
    -- v54: clique de Gun (usado quando a arma forcada e uma Gun: Mastery, Sub Farm...): mira no mob mais perto
    -- (Mouse.Hit), atira pelo Activate e, se o modulo de tiro por remote estiver carregado, tambem por ele
    -- v112: pedido do usuario - "todos os clicks sem cooldown". Tirado o piso fixo de 0,08s (nao dava pra configurar,
    -- diferente do resto que ja respeita o Click CPS de Farm Settings) - agora atira em toda chamada, no ritmo dos
    -- motores (ate 6x por frame), igual fruta/Melee/Sword ja fazem.
    local function gunAttack(tool)
        local _, hrp = getChar()
        if not (tool and hrp) then return end
        local tp = Core.fruitTarget and Core.fruitTarget(hrp)
        if not tp then return end
        if Core.fruitAim then pcall(Core.fruitAim, tp.Position, tp) end
        local now = os.clock()
        pcall(function() tool:Activate() end)
        if Core.gunShot then pcall(Core.gunShot, tp) end
        Core.firedAt = now
    end
    -- Melee e Sword: UM unico codigo de clique (golpe do jogo + M1 + anti-travada), usado pelo modo normal e pelas armas forcadas
    local function meleeSwordClick(tip)
        if os.clock() - (Core.cfAt or 0) > 0.2 then Core.cfAt = os.clock(); cfAttack() end
        meleeM1(tip)
        -- v135: a anti-travada varre Enemies+Characters inteiro; rodava em TODO disparo (ate 6x por frame) e pesava o clique.
        -- Agora so a cada 0,1 s (o golpe em si continua saindo em toda chamada).
        local nowR = os.clock()
        if nowR - (Core.recAt or 0) >= 0.1 then Core.recAt = nowR; recover(tip) end
    end
    local lastStepAt = 0
    local function step()
        local gap = Core.cpsGap()
        if gap > 0 then
            local nowS = os.clock()
            if nowS - lastStepAt < gap then return end
            lastStepAt = nowS
        end
        local ov = Core.ov
        if ov and os.clock() < (ov.untilT or 0) then
            -- arma escolhida por nome (Sub Farm / Sea Events / Mastery): ataca conforme o tipo da ferramenta na mao
            local tl
            if ov.name then tl = equipByName(ov.name)
            elseif ov.tip then tl = equip(ov.tip)
            else tl = LP.Character and LP.Character:FindFirstChildOfClass("Tool") end
            local tip = tl and wtip(tl)
            if tip == "Melee" or tip == "Sword" then meleeSwordClick(tip)
            elseif tip == "Blox Fruit" then fruitM1(); fruitWatch()
            elseif tip == "Gun" then gunAttack(tl) end
            return
        end
        local tool = cfg.tool
        -- v54b: Melee/Sword tambem soltam o golpe do proprio jogo (CombatFramework) 5x por segundo, alem dos hits pelo remote
        if tool == "Melee" or tool == "Sword" then equip(tool); meleeSwordClick(tool)
        elseif tool == "Double Attack" then
            if not (LP.Character and LP.Character:FindFirstChildOfClass("Tool")) then equip("Blox Fruit") end
            -- v112: pedido do usuario - "todos os clicks sem cooldown". Tirado o piso fixo de 0,03s daqui (nao
            -- dava pra configurar); roda em toda chamada agora, no ritmo dos motores. O "Double Attack Swap"
            -- (cfg.daSwap, Farm Settings) continua existindo - esse e o intervalo de TROCA de fruta equipada,
            -- nao um cooldown de clique, entao fica intocado.
            doubleAttack()
        else equip("Blox Fruit"); fruitM1(); fruitWatch() end
    end
    local function attackTickN(idx)
        return function()
            if not Core.attacking or not alive then return end
            -- Melee/Sword usam os 3 motores sempre (bem rapido); os outros seguem o metodo escolhido
            -- v53: a fruta tambem usa os 3 motores (clique bem mais rapido); so o Double Attack segue o metodo (ele tem trava propria)
            if idx > method().engines and cfg.tool == "Double Attack" then return end
            pcall(step)
        end
    end
    function Core.attackTick() if Core.attacking and alive then pcall(step) end end
    Core.fruitTick, Core.cfAttack, Core.pressKey, Core.equip, Core.equipByName = fruitM1, cfAttack, pressKey, equip, equipByName
    Core.meleeSwordClick = meleeSwordClick -- exposto pro Vulcan/CDK usarem o MESMO click de Melee/Sword do motor principal
    local engineConns = {}
    -- v99: pedido do usuario ("deixa o click de fruta ainda mais rapido") - antes so existiam 3 chamadas de
    -- step()/fruitM1() por frame (Heartbeat/Stepped/RenderStepped). PreSimulation, PreAnimation e PreRender sao
    -- OUTROS sinais do RunService (existem ha varios anos, cada um dispara exatamente 1x por frame tambem, so que
    -- numa fase diferente do pipeline do jogo) - ligando esses 3 extras, step() passa a rodar ate 6x por frame em
    -- vez de 3, dobrando a taxa de clique no teto do Click CPS. Continua 1 FireServer por chamada, igual sempre
    -- foi (SEM rajada dentro da mesma chamada - so manda mais chamadas de verdade por frame, nunca repete a
    -- mesma, evitando o bug antigo do v72 de "da 1 click e trava"). Cada sinal entra num pcall (alguns
    -- clients/executores mais antigos podem nao ter PreSimulation/PreAnimation/PreRender); se faltar algum, so
    -- ele fica de fora e os outros continuam normais. idx continua 1-6 na ordem abaixo, entao o Double Attack
    -- (que trava pelo metodo escolhido, max 3) continua pegando exatamente os mesmos 3 primeiros sinais de antes
    -- (Heartbeat/Stepped/RenderStepped) - comportamento dele intocado.
    local ENGINE_SIGNALS = { "Heartbeat", "Stepped", "RenderStepped", "PreSimulation", "PreAnimation", "PreRender" }
    function Core.setEngines()
        for _, c in ipairs(engineConns) do pcall(function() c:Disconnect() end) end
        engineConns = {}
        local idx = 0
        for _, name in ipairs(ENGINE_SIGNALS) do
            local ok, sig = pcall(function() return RunService[name] end)
            if ok and typeof(sig) == "RBXScriptSignal" then
                idx += 1
                engineConns[#engineConns + 1] = sig:Connect(attackTickN(idx))
            end
        end
    end
    table.insert(cleanups, function()
        Core.attacking = false
        for _, c in ipairs(engineConns) do pcall(function() c:Disconnect() end) end
        getgenv().MoonPremiumCore = nil
    end)
    function Core.setAttack(on)
        Core.attacking = on and true or false
        if Core.attacking then Core.setEngines() end
    end

    -- ---------------------------------------------------------- Haki ----
    local timers, ken = {}, { last = 0, presses = 0, seen = false }
    local function due(k, iv)
        local now = os.clock()
        if (timers[k] or 0) <= now then timers[k] = now + iv; return true end
        return false
    end
    local function kenActive()
        local ok, v = pcall(function()
            local sg = LP.PlayerGui:FindFirstChild("ScreenGui")
            return sg and sg:FindFirstChild("ImageLabel") ~= nil
        end)
        return ok and v == true
    end
    task.spawn(function()
        while alive do
            task.wait(0.5)
            pcall(function()
                local char = getChar()
                if not char then return end
                if cfg.buso and due("buso", 2) and not char:FindFirstChild("HasBuso") then
                    pcall(function() RS.Remotes.CommF_:InvokeServer("Buso") end)
                end
                if cfg.ken and due("ken", 1) then
                    if kenActive() then ken.seen, ken.presses = true, 0
                    else
                        local gap = (ken.presses >= 3 and not ken.seen) and 60 or 5
                        if os.clock() - ken.last >= gap then ken.last = os.clock(); ken.presses += 1; pressKey(Enum.KeyCode.E) end
                    end
                end
                if cfg.v3 and due("v3", 3) then pcall(function() RS.Remotes.CommE:FireServer("ActivateAbility") end) end
                if cfg.v4 and due("v4", 2) then
                    local re, rt = char:FindFirstChild("RaceEnergy"), char:FindFirstChild("RaceTransformed")
                    if re and re.Value >= 1 and not (rt and rt.Value) then pressKey(Enum.KeyCode.Y) end
                end
            end)
        end
    end)

    -- ---------------------------------------------------------- Time ----
    local function clickBtn(btn)
        pcall(function() if firesignal then firesignal(btn.Activated) end end)
        pcall(function() if firesignal then firesignal(btn.MouseButton1Click) end end)
        pcall(function()
            if getconnections then
                for _, c in ipairs(getconnections(btn.Activated)) do pcall(function() c:Fire() end) end
                for _, c in ipairs(getconnections(btn.MouseButton1Click)) do pcall(function() c:Fire() end) end
            end
        end)
    end
    -- v131: pedido do usuario - "Auto Select Team nao escolhe o time sozinho". Dois erros achados aqui:
    -- 1) o remote era RS.Remotes.CommonF (nao existe) - o certo e RS.Remotes.CommF_ (o mesmo usado em todo o resto do
    --    script e no Auto Bounty, onde o time funcionava);
    -- 2) o caminho do botao estava errado ("Main (minimal)" sempre existe e nao tem ChooseTeam dentro do jeito
    --    que a busca esperava) - o caminho real e Main (minimal) > ChooseTeam > Container > <time> > Frame > TextButton.
    -- Agora: espera a tela aparecer, tenta botao (Activated) -> botao (MouseButton1Click) -> remote SetTeam, uma por
    -- vez, e so tenta de novo se ainda estiver sem time (portado do Auto Bounty, que funcionava).
    local function teamName() local t = LP.Team; return t and t.Name end
    local function teamBtn(team)
        local btn
        pcall(function()
            local pg = LP:FindFirstChild("PlayerGui")
            local mm = pg and pg:FindFirstChild("Main (minimal)")
            local ct = mm and mm:FindFirstChild("ChooseTeam")
            local box = ct and ct:FindFirstChild("Container")
            local opt = box and box:FindFirstChild(team)
            local fr = opt and opt:FindFirstChild("Frame")
            btn = fr and fr:FindFirstChild("TextButton")
        end)
        return btn
    end
    local function fireSig(sig)
        if type(firesignal) == "function" and pcall(firesignal, sig) then return true end
        if type(getconnections) == "function" then
            local ok, cons = pcall(getconnections, sig)
            if ok and type(cons) == "table" and #cons > 0 then
                for _, c in ipairs(cons) do pcall(function() c:Fire() end) end
                return true
            end
        end
        return false
    end
    task.spawn(function()
        local t0, tries, lastTry = os.clock(), 0, -10
        while alive and os.clock() - t0 < 300 do
            local n = teamName()
            if n == "Pirates" or n == "Marines" then break end
            if cfg.autoteam and os.clock() - lastTry >= 3 then
                local team = (cfg.team == "Marines") and "Marines" or "Pirates"
                local btn = teamBtn(team)
                if btn or os.clock() - t0 > 12 then       -- tela ainda nao apareceu: espera ate 12s antes de usar so o remote
                    lastTry = os.clock(); tries += 1
                    local step = btn and ((tries - 1) % 3 + 1) or 3
                    if step == 1 then fireSig(btn.Activated)
                    elseif step == 2 then fireSig(btn.MouseButton1Click)
                    else pcall(function() RS.Remotes.CommF_:InvokeServer("SetTeam", team) end) end
                end
            end
            task.wait(0.5)
        end
    end)

    -- ------------------------------------------------------ Bring Mob ----
    -- puxa os mobs mais perto (no maximo cfg.bringN) para a posicao 'center'
    -- accept (opcional): funcao(model) -> true para puxar so os mobs desejados
    -- v47: guarda a posicao de SPAWN de cada mob (antes de qualquer puxao nosso) e nao deixa puxar
    -- quem ja esta longe demais do proprio spawn - puxar um mob que ja andou/foi arrastado muito longe
    -- do lugar onde ele nasceu e o que mais gera NPC fantasma (perde dono de rede / servidor nao acompanha).
    local SPAWN = setmetatable({}, { __mode = "k" })  -- modelo -> posicao de spawn (primeira vez que vimos ele)
    Core.spawnPos, Core.MAX_SPAWN_DRIFT = SPAWN, 200   -- raio maximo (studs) do proprio spawn pra poder puxar
    -- v53: um unico jeito de puxar e de soltar mob, usado por TODAS as farms (Level Farm, Moon antigo, Core.bring).
    -- Antes cada farm puxava de um jeito: o Level Farm ignorava o Bring Mob V2, e quem saia do grupo (ou quando a luta
    -- acabava) ficava parado/flutuando para sempre (PlatformStand, WalkSpeed 0 e a BodyPosition do V2 nunca eram tirados).
    Core.FREEZE = setmetatable({}, { __mode = "k" })   -- modelo -> { ws = WalkSpeed original, jp = JumpPower original }
    -- v68: codigo do Bring Mob (BringEnemy) do script que o usuario mandou - 2 coisas de la que a gente nao tinha:
    -- 1) desliga colisao de TODA parte do corpo (nao so raiz/cabeca) + apaga o Animator + ChangeState(Physics),
    --    reforcado a cada 0,5s por mob (PREP, mesmo throttle que eles usam) - antes so raiz/cabeca ficavam sem
    --    colisao, o resto do corpo colidia com chao/outros mobs e "brigava" com o teleporte.
    -- 2) (v68) so teleportava (r.CFrame = ...) se formos donos da rede da parte (isnetworkowner).
    -- v76 fix: a trava do item 2 QUEBROU o Bring Mob ("nao ta puxando") - o Core.pullOK logo acima (v25) ja tinha
    -- o comentario avisando que isnetworkowner "devolve false em varios executores MESMO com o mob apanhando" e por
    -- isso nunca foi usado pra decidir nada aqui; o v68 ignorou esse aviso e passou a exigir ele pra teleportar.
    -- Quando o executor devolve false (o caso comum nos executores citados), canTp ficava sempre falso e o mob
    -- nunca mais era arrastado - so ficava parado (sem colisao, sem andar) no lugar. Voltando ao comportamento de
    -- sempre tentar teleportar (como era antes do v68 e como o Core.pullOK ja fazia).
    local PREP = setmetatable({}, { __mode = "k" })
    function Core.pullMob(m, r, h, cf)
        if not (m and r and h and cf) then return end
        if not Core.FREEZE[m] then
            Core.FREEZE[m] = { ws = (h.WalkSpeed > 0) and h.WalkSpeed or 16, jp = h.JumpPower }
        end
        Core.pulledAt[m] = os.clock()
        local now = os.clock()
        if now - (PREP[m] or 0) >= 0.5 then
            PREP[m] = now
            pcall(function()
                for _, part in ipairs(m:GetDescendants()) do
                    if part:IsA("BasePart") then part.CanCollide = false end
                end
                local anim = h:FindFirstChild("Animator")
                if anim then anim:Destroy() end
                h:ChangeState(Enum.HumanoidStateType.Physics)
            end)
        end
        pcall(function()
            r.Anchored = false
            local bp = r:FindFirstChild("MoonHubBringPos")
            if bp then bp:Destroy() end
            -- v89: Bring Mob unificado - antes isso era so o caminho do V2 (cfg.bringMobV2); agora e o UNICO
            -- caminho, pra todo mundo. Trava o mob no ponto com um BodyVelocity zerado ("BatmanLock"), sem colisao
            -- em nenhuma parte, CFrame no ponto a cada frame (com dead-zone de 5 studs pra nao tremer) e
            -- WalkSpeed/JumpPower 0 - sem PlatformStand (travava mais firme que o V1 antigo, que usava
            -- PlatformStand e deixava o mob "lutando" pra sair do lugar com menos forca).
            if not r:FindFirstChild("BatmanLock") then
                local lock = Instance.new("BodyVelocity")
                lock.Name = "BatmanLock"
                lock.Velocity = Vector3.zero
                -- v95: forca infinita (igual ao "LockMob" do bomba.lua) em vez de 1e5 - trava mais forte, nunca
                -- e vencida por empurrao/fisica do mob tentando escapar
                lock.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
                lock.Parent = r
            end
            if h.PlatformStand then h.PlatformStand = false end
            -- v60 (bomba.lua BringEnemy): so teleporta se for dono da rede (isnetworkowner) e se estiver a mais de 5 studs do ponto.
            -- Executor cujo isnetworkowner nunca devolve true (v76: "mob nunca mais arrastado") continua teleportando sempre.
            local canTp = true
            if type(isnetworkowner) == "function" then
                local okO, vO = pcall(isnetworkowner, r)
                if okO and vO then
                    Core.ownYes = (Core.ownYes or 0) + 1
                else
                    Core.ownNo = (Core.ownNo or 0) + 1
                    canTp = (Core.ownYes or 0) == 0 and Core.ownNo >= 40
                end
            end
            if canTp and (r.Position - cf.Position).Magnitude > 5 then r.CFrame = CFrame.new(cf.Position) end
            r.AssemblyLinearVelocity = Vector3.zero
            r.CanCollide = false
            h.WalkSpeed = 0
            h.JumpPower = 0
        end)
    end
    function Core.freeMob(m)
        if not m then return end
        local st = Core.FREEZE[m]
        Core.FREEZE[m] = nil
        PREP[m] = nil
        if not m.Parent then return end
        pcall(function()
            local h = m:FindFirstChildOfClass("Humanoid")
            local r = m:FindFirstChild("HumanoidRootPart")
            local bp = r and r:FindFirstChild("MoonHubBringPos")
            if bp then bp:Destroy() end
            local lk = r and r:FindFirstChild("BatmanLock")   -- v54e: solta a trava do V2
            if lk then lk:Destroy() end
            -- v68: devolve a colisao de TODA parte do corpo (agora que desligamos todas, nao so raiz/cabeca)
            for _, part in ipairs(m:GetDescendants()) do
                if part:IsA("BasePart") then part.CanCollide = true end
            end
            if h and h.Health > 0 and st then
                h.PlatformStand = false
                h.WalkSpeed = st.ws
                if st.jp then h.JumpPower = st.jp end
            end
        end)
    end
    -- v54: alcance do Bring Mob (Farm Settings > Bring Mob Range), usado por todas as farms
    -- v138: pedido do usuario - com Soco ou Espada selecionados, o alcance do Bring Mob cai pra 150 (com fruta continua o
    -- valor de Farm Settings). Vale tambem quando uma farm forca a arma (Core.ov) e ela e Melee/Sword.
    -- true quando a arma em uso e Soco/Espada (alcance curto): o Bring Mob fica mais junto e mais perto do golpe
    function Core.shortTool()
        local nowc = os.clock()
        if Core.stAt and nowc - Core.stAt < 0.1 then return Core.stV end
        Core.stAt = nowc
        Core.stV = Core.shortToolRaw()
        return Core.stV
    end
    function Core.shortToolRaw()
        local t = cfg.tool
        local ov = Core.ov
        if ov and os.clock() < (ov.untilT or 0) then
            local tl = LP.Character and LP.Character:FindFirstChildOfClass("Tool")
            local tp = tl and Core.wtip and Core.wtip(tl)
            if tp then t = tp end
        end
        return t == "Melee" or t == "Sword"
    end
    function Core.bringCap(r)
        if Core.shortTool() then return math.min(r, 150) end
        return r
    end
    function Core.bringRange() return Core.bringCap(math.clamp(tonumber(cfg.bringRange) or 300, 50, 350)) end   -- v114: padrao 300, maximo 350
    function Core.bring(center, radius, accept)
        if not cfg.bring then return 0 end   -- v89: Bring Mob unificado (nao tem mais V2 separado)
        local f = workspace:FindFirstChild("Enemies")
        if not f then return 0 end
        local list = {}
        for _, m in ipairs(f:GetChildren()) do
            local h = m:FindFirstChildOfClass("Humanoid")
            local r = m:FindFirstChild("HumanoidRootPart")
            -- v68: nunca agrupa boss (igual a lista de nomes do BringEnemy do usuario) mesmo se o "accept" de quem
            -- chamou nao filtrar isso - seguranca extra, independente de cada farm.
            if h and r and h.Health > 0 and not m:GetAttribute("IsBoat") and not isBoss(m, h) and not Core.isFriendly(m, LP) and (not accept or accept(m)) and not Core.isGhost(m) then
                local home = SPAWN[m]
                if not home then home = r.Position; SPAWN[m] = home end
                -- quem ja esta puxado conta mesmo longe do spawn (senao saia e voltava do grupo a cada passo)
                if Core.FREEZE[m] or (r.Position - home).Magnitude <= Core.MAX_SPAWN_DRIFT then
                    local d = (r.Position - center).Magnitude
                    if d <= (radius or Core.bringRange()) then list[#list + 1] = { r, d, h, m, home } end
                end
            end
        end
        table.sort(list, function(a, b) return a[2] < b[2] end)
        local n = math.min(#list, math.clamp(tonumber(cfg.bringN) or 3, 2, 10))
        local cf, now = CFrame.new(center), {}
        for i = 1, n do
            local r, _, h, m, home = list[i][1], list[i][2], list[i][3], list[i][4], list[i][5]
            if Core.pullOK(m, r, home) then
                now[m] = true
                Core.pullMob(m, r, h, cf)
            end
        end
        for m in pairs(Core.bringLast or {}) do if not now[m] then Core.freeMob(m) end end
        Core.bringLast = now
        pcall(function() sethiddenproperty(LP, "SimulationRadius", 500) end)
        return n
    end

    -- Faxineiro do Bring Mob: qualquer mob que ficou travado (sem animacao, WalkSpeed 0, sem colisao, BodyVelocity "BatmanLock")
    -- e que nenhuma farm puxa ha mais de 3 s e solto de verdade, e devolvido para perto do spawn se foi arrastado longe.
    -- Cobre os caminhos em que a luta acaba sem passar pelo release normal (troca de farm, toggle desligado, alvo morto/trocado,
    -- personagem que morreu, modulo descarregado) - era o que deixava mob "preso"/fantasma flutuando no ar depois.
    task.spawn(function()
        while alive do
            task.wait(1)
            local now = os.clock()
            local stale = {}
            for m in pairs(Core.FREEZE) do
                local at = Core.pulledAt[m]
                if (not m.Parent) or (not at) or now - at > 3 then stale[#stale + 1] = m end
            end
            for _, m in ipairs(stale) do
                local r = m.Parent and m:FindFirstChild("HumanoidRootPart")
                local h = m.Parent and m:FindFirstChildOfClass("Humanoid")
                local home = SPAWN[m]
                pcall(Core.freeMob, m)
                if r and h and h.Health > 0 and home and (r.Position - home).Magnitude > 40 then
                    pcall(function() r.CFrame = CFrame.new(home); r.AssemblyLinearVelocity = Vector3.zero end)
                end
            end
            -- sobras: BatmanLock/MoonHubBringPos em mob que nao esta mais na lista (ex.: perdeu a referencia)
            local en = workspace:FindFirstChild("Enemies")
            if en then
                for _, m in ipairs(en:GetChildren()) do
                    if not Core.FREEZE[m] then
                        local r = m:FindFirstChild("HumanoidRootPart")
                        local lk = r and r:FindFirstChild("BatmanLock")
                        if lk then
                            local at = Core.pulledAt[m]
                            if not at or now - at > 3 then
                                pcall(function() lk:Destroy() end)
                                local h = m:FindFirstChildOfClass("Humanoid")
                                if h and h.Health > 0 and h.WalkSpeed == 0 then pcall(function() h.WalkSpeed = 16; h.PlatformStand = false end) end
                            end
                        end
                    end
                end
            end
        end
    end)

    -- ------------------------------------------------------------- Voo ----
    -- Motor unico de movimento (usado pelo flyTo do v52, pelo Level Farm e por Core.tweenTo):
    --  * velocidade em studs/s, padrao 200 em TODAS as funcoes (Core.DEFSPEED)
    --  * partida suave (0,3 s) e freio nos ultimos 14 studs; o passo e limitado pelo tempo do frame
    --  * se o jogo "puxar de volta" o personagem (rollback), a velocidade cai sozinha por alguns segundos
    Core.DEFSPEED = 200
    function Core.speed(v)
        v = tonumber(v)
        if not v or v ~= v then v = Core.DEFSPEED end
        return math.clamp(v, 30, 600)
    end
    Core.moveStat = { rollbacks = 0, slowUntil = 0, warnAt = 0 }
    function Core.newMover() return { t0 = 0, lastT = 0, slow = 1, rbAt = 0 } end
    -- v149: durante o voo o Humanoid fica em estado Physics (sem corrida/queda/pouso/nado). Em estado normal o Humanoid brigava
    -- com o CFrame a cada frame (ex.: "Landed/Freefall/Swimming" no mar) e dava o "vai, para, volta" do tween.
    function Core.flightPhys(on)
        local _, _, hum = getChar()
        if not hum then return end
        pcall(function()
            if on then
                if hum:GetState() ~= Enum.HumanoidStateType.Physics then hum:ChangeState(Enum.HumanoidStateType.Physics) end
            elseif hum:GetState() == Enum.HumanoidStateType.Physics then
                hum:ChangeState(Enum.HumanoidStateType.GettingUp)
            end
        end)
    end
    -- st: Core.newMover() de quem esta voando | pos: posicao atual | aim: vetor do passo (pode subir na diagonal)
    -- left: distancia que falta ate o destino final (freio) | dt: tempo do frame | speed: studs/s
    function Core.moveStep(st, pos, aim, left, dt, speed)
        local now = os.clock()
        dt = math.clamp(tonumber(dt) or 0.016, 0.001, 0.1)
        if now - st.lastT > 0.3 then st.t0, st.last, st.dir = now, nil, nil end      -- movimento novo
        st.lastT = now
        -- o jogo devolveu o personagem para tras? (bem atras de onde ele foi colocado no frame anterior)
        if st.last and st.dir then
            local back = st.last - pos
            if back.Magnitude > math.max(14, speed * dt * 3) and back:Dot(st.dir) > 8 then
                st.t0 = now
                if now - st.rbAt < 5 then
                    st.slow = 1   -- v147: voo continuo - nao reduz mais a velocidade quando o jogo puxa de volta
                    st.slowUntil = now + 10
                    Core.moveStat.rollbacks += 1
                    Core.moveStat.slowUntil = st.slowUntil
                    if now - Core.moveStat.warnAt > 90 then
                        Core.moveStat.warnAt = now
                        pcall(notify, "Tween", "The game pulled you back (the flight keeps full speed). You can lower Tween Speed in Farm Settings if it keeps happening.", "warn", 5)
                    end
                end
                st.rbAt = now
            end
        end
        if st.slowUntil and now > st.slowUntil then st.slow, st.slowUntil = 1, nil end
        local mag = aim.Magnitude
        if mag < 0.001 then st.last = pos; return pos end
        local dir = aim / mag
        -- v146: voo CONTINUO - sem partida suave (ramp) e sem freio no fim: velocidade cheia do comeco ao fim, sem "engasgar".
        -- (o passo ja e limitado por min(mag, ...) abaixo, entao nao passa do destino)
        local sp = math.max(speed * st.slow, 30)
        local np = pos + dir * math.min(mag, sp * dt)
        st.last, st.dir = np, dir
        return np
    end
    -- voa em linha reta ate 'cf' (sem TweenService). Devolve um objeto com :Cancel() e .PlaybackState
    function Core.tweenTo(cf, speed)
        local _, hrp = getChar()
        if not hrp then return nil end
        if not cfg.flytween then hrp.CFrame = cf; return nil end
        local bv = hrp:FindFirstChild("MoonPremiumFly") or Instance.new("BodyVelocity")
        bv.Name = "MoonPremiumFly"; bv.Velocity = Vector3.zero; bv.MaxForce = Vector3.new(1e9, 1e9, 1e9); bv.Parent = hrp
        local h = { PlaybackState = Enum.PlaybackState.Playing }
        local st, conn = Core.newMover(), nil
        local function finish(state)
            if conn then conn:Disconnect(); conn = nil end
            h.PlaybackState = state
            pcall(function() bv:Destroy() end)
        end
        function h:Cancel() finish(Enum.PlaybackState.Cancelled) end
        conn = RunService.Heartbeat:Connect(function(dt)
            local _, r = getChar()
            if not (alive and r and r.Parent) then finish(Enum.PlaybackState.Cancelled) return end
            local delta = cf.Position - r.Position
            local d = delta.Magnitude
            if d <= 2.5 then r.CFrame = cf; finish(Enum.PlaybackState.Completed) return end
            r.CFrame = CFrame.new(Core.moveStep(st, r.Position, delta, d, dt, Core.speed(speed or cfg.tspeed)))
            r.AssemblyLinearVelocity = Vector3.zero
        end)
        return h
    end
    table.insert(cleanups, function()
        pcall(function() local _, h = getChar(); local b = h and h:FindFirstChild("MoonPremiumFly"); if b then b:Destroy() end end)
    end)

    -- -------------------------------------------------------- Prioridades ----
    -- v44: igual o Sea Events (Priority 1, 2, 3...): o jogador ESCOLHE qual farm e a prioridade 1, qual e a 2, etc, em
    -- vez de reordenar uma lista com Up/Down. Vem com 5 slots (cfg.prioSlotN); um botao na UI cria mais, sem limite.
    -- Slot vazio = "None". Quem nao esta em nenhum slot continua rodando normal (se a funcao dele estiver ligada),
    -- so que depois de todo mundo que foi colocado em algum slot - exatamente como o "OFF" da lista antiga funcionava.
    Core.catalog = { "Auto Bounty", "Boss Farm", "Sea Events", "Farm Level", "Farm Bones", "Cake Prince", "Collect Fruits", "Raid" }
    -- v26: a lista vem SEM prioridades; so estas 4 vem marcadas e o jogador pode mudar
    -- v54b: nenhuma farm entra sozinha nos slots (antes Collect Fruits / Pirate Raid / Factory / Elite iam pra frente de tudo sem voce escolher)
    Core.prioDefault = {}
    Core.PRIO_NONE = "None"
    function Core.ensurePrio()
        local n = math.max(1, math.floor(tonumber(cfg.prioSlotN) or 5))
        local raw = type(cfg.prioSlots) == "table" and cfg.prioSlots or nil
        local slots = {}
        if raw and cfg.prioAutoFilled ~= true then
            -- o jogador ja tem uma escolha propria (ou carregada de uma sessao anterior): so valida contra o catalogo atual
            for i = 1, n do
                local v = raw[i]
                slots[i] = (type(v) == "string" and (v == Core.PRIO_NONE or table.find(Core.catalog, v))) and v or Core.PRIO_NONE
            end
        else
            -- sem escolha do jogador ainda (ou so o preenchimento automatico de antes, cfg.prioAutoFilled): refaz o
            -- padrao com o CATALOGO ATUAL. Isso roda de novo sozinho (idempotente) conforme o catalogo cresce (de 8
            -- itens nativos do Premium pros ~28 com os legados do v52, adicionados depois pelo pcompat2), ate o
            -- jogador mudar alguma coisa na UI - dai o onChange do dropdown marca prioAutoFilled = false e congela.
            local idx = 1
            for _, name in ipairs(Core.catalog) do
                if Core.prioDefault[name] and idx <= n then slots[idx] = name; idx = idx + 1 end
            end
            for i = idx, n do slots[i] = Core.PRIO_NONE end
            cfg.prioAutoFilled = true
        end
        cfg.prioSlotN, cfg.prioSlots = n, slots
        return slots, n
    end
    -- adiciona mais um slot vazio no final (botao "+ Add Slot" na UI)
    function Core.addPrioSlot()
        local slots, n = Core.ensurePrio()
        n = n + 1
        cfg.prioSlotN = n
        slots[n] = Core.PRIO_NONE
        cfg.prioSlots = slots
        return slots, n
    end
    function Core.priorityOrder()
        -- v44: os slots (na ordem 1, 2, 3...) rodam primeiro; quem nao esta em nenhum slot continua rodando depois,
        -- na ordem do catalogo - igual o "OFF" da lista antiga.
        local slots = Core.ensurePrio()
        local out, seen = {}, {}
        for _, name in ipairs(slots) do
            if name ~= Core.PRIO_NONE and table.find(Core.catalog, name) and not seen[name] then
                out[#out + 1] = name; seen[name] = true
            end
        end
        for _, name in ipairs(Core.catalog) do
            if not seen[name] then out[#out + 1] = name; seen[name] = true end
        end
        return out
    end
    function Core.registerFarm(name)
        if not table.find(Core.catalog, name) then table.insert(Core.catalog, name) end
    end
    -- Arbitro: Core.farms[nome] = { want = function() -> bool }. Roda so a PRIMEIRA farm da lista de prioridade que quer rodar.
    function Core.current()
        for _, n in ipairs(Core.priorityOrder()) do
            local f = Core.farms[n]
            if f and f.want and f.want() then return n end
        end
        return nil
    end
    -- v54b: a farm esta ligada agora? (usado pra so mostrar nas prioridades o que esta ativo)
    function Core.isActiveFarm(name)
        local f = Core.farms[name]
        if not f then return false end
        if f.legacy then return (Core.legacyOn and Core.legacyOn(f.key, f.legacy)) and true or false end
        local ok, v = pcall(f.want)
        return ok and v and true or false
    end
    Core.ensurePrio()
    Core.setEngines()
end)()


-- v101: registro compartilhado dos controles nativos (mkToggle/mkSlider/mkSelect) que o "Reset Farm Configs" muda -
-- antes o reset so trocava o VALOR em cfg/Config, sem avisar o controle visual (obj.set), entao o toggle/slider
-- continuava mostrando o estado ANTIGO na tela ate reabrir a aba (ou rodar o script de novo) - "aparece que as
-- opcoes tao ativas, porem nao tao", exatamente o bug relatado. Cada obj.set(v, true) (true = silencioso, nao
-- chama onChange/persist de novo, que ja foi feito uma vez so no fim do reset) atualiza o desenho na hora, sem
-- precisar reabrir nada. Declarado aqui (antes da aba Farm Settings) pra ficar visivel tambem mais abaixo, na aba
-- Normal Farm/Level Farm (Auto Take Quest fica la, nao em Farm Settings).
local RESET_UI = {}
-- ====================================================== aba Farm Settings ====
local farm = addTab("Farm Settings", ICON.crown)
-- v102: virou uma funcao imediata ( (function() ... end)() ) em vez de um "do...end" simples - o script bateu no
-- limite de 200 variaveis locais simultaneas do LuaJIT no chunk principal (cada "do" sozinho NAO cria um escopo de
-- funcao novo pro compilador, entao toda variavel local daqui dentro ainda contava pro limite do arquivo inteiro;
-- uma funcao de verdade ganha seu PROPRIO orcamento de 200). RESET_UI continua fora (declarado antes), pra
-- continuar visivel na aba Normal Farm mais abaixo.
;(function()
    local B = farm.body
    local OPT_H = 30

    -- lista suspensa e slider: componentes compartilhados (UIX), ligados a esta aba
    local function mkSelect(iconId, title, sub, order, options, initial, multi, onChange)
        return UIX.select(B, iconId, title, sub, order, options, initial, multi, onChange)
    end
    local function mkSlider(iconId, title, sub, order, min, max, initial, onChange, fmt)
        return UIX.slider(B, iconId, title, sub, order, min, max, initial, onChange, fmt, 0)
    end

    local o = 0
    local function nx() o += 1; return o end

    -- ---------- Attack ----------
    section(B, "Attack", nx())
    local TOOLS = { "Melee", "Sword", "Blox Fruit ( M1 )", "Double Attack" }
    local toolUi = { ["Blox Fruit ( M1 )"] = "Fruit" }
    local function toolName() return cfg.tool == "Fruit" and "Blox Fruit ( M1 )" or cfg.tool end
    RESET_UI.tool = mkSelect(ICON.wrench, "Attack Tool", "Fruit M1 clicks like Auto Bounty. Double Attack: held fruit + a backpack fruit", nx(), TOOLS, toolName(), false, function(v)
        cfg.tool = toolUi[v] or v; persist()
        if Core.attacking then Core.setAttack(true) end
    end)

    -- v124: removido "Super"/"Hyper" - so afetavam o Double Attack (Melee/Sword e fruta normal ja atacam nos 3
    -- motores sempre, sem depender disso). "Normal" (1 motor) e mais seguro; "Fast" (2 motores) e o recomendado.
    RESET_UI.method = mkSelect(ICON.rocket, "Attack Method", "Only affects Double Attack's attack rate. Normal = safer, Fast = recommended (now stronger than the old Hyper Click)", nx(), { "Normal Attack", "Fast Attack" }, cfg.method, false, function(v)
        cfg.method = v; persist()
        Core.setEngines()
    end)
    -- v63: removido o seletor "Super Fast / Classic" - agora so existe UM click de Melee/Sword (anima e acerta
    -- todo mundo no alcance ao mesmo tempo), entao nao tem mais modo pra escolher. Interface mais limpa.
    -- v64: opcao nova (baseada nos scripts de referencia) pra quem prefere sem a animacao de golpe (so o resultado,
    -- sem o "flash" visual de cada tapa - pode ajudar em telas mais lentas/fracas).
    RESET_UI.noM1Anim = mkToggle(B, ICON.flame, "Attack No Animation", "Skips the swing animation on Melee/Sword M1 - only the hit itself, no visual swing", nx(), cfg.noM1Anim, function(v)
        cfg.noM1Anim = v; persist()
    end)

    RESET_UI.targets = mkSelect(ICON.users, "Attack Select", "Who to hit. You can pick more than one", nx(), { "NPC", "BOSS", "PLAYER" }, (function()
        local t = {}
        for k, v in pairs(type(cfg.targets) == "table" and cfg.targets or {}) do if v then t[k] = true end end
        return t
    end)(), true, function(v)
        cfg.targets = { NPC = v.NPC and true or false, BOSS = v.BOSS and true or false, PLAYER = v.PLAYER and true or false }
        persist()
    end)

    RESET_UI.cps = mkSlider(ICON.finger, "Click CPS", "Attacks per second. 120 or more = no limit (one attack per frame)", nx(), 5, 240, math.clamp(tonumber(cfg.cps) or 120, 5, 240), function(v)
        cfg.cps = v; persist()
    end, function(v) return v >= 120 and "No limit" or (tostring(math.floor(v)) .. "/s") end)
    RESET_UI.range = mkSlider(ICON.eye, "Attack Range", "Distance (studs) at which enemies are hit", nx(), 20, 150, math.clamp(tonumber(cfg.range) or 60, 20, 150), function(v)
        cfg.range = v; persist()
    end)
    RESET_UI.daSwap = mkSlider(ICON.finger, "Double Attack Swap", "Only matters with Double Attack selected: how often (seconds) it swaps which fruit is equipped to hit with both", nx(), 15, 60, math.clamp(math.floor((tonumber(cfg.daSwap) or 0.35) * 100), 15, 60), function(v)
        cfg.daSwap = v / 100; persist()
    end, function(v) return string.format("%.2fs", v / 100) end)
    local testT
    testT = mkToggle(B, ICON.flame, "Attack Nearby Enemies", "Test your settings: attacks what is in range while this is on", nx(), false, function(v)
        Core.setAttack(v)
        if v then notify("Attack", "Attacking with " .. toolName() .. " (" .. cfg.method .. ").", "ok", 2.5) end
    end)
    Core.testToggle = testT
    -- ---------- Movement and Tween ----------
    section(B, "Movement and Tween", nx())
    RESET_UI.flytween = mkToggle(B, ICON.rocket, "Fly Tween", "Flies to the target smoothly. Off = instant teleport", nx(), cfg.flytween, function(v) cfg.flytween = v; persist() end)
    local sTween, sIsland
    sTween = mkSlider(ICON.gauge, "Tween Speed", "Flight speed in studs/s (default 200). If the game pulls you back, lower it", nx(), 50, 500, math.clamp(math.floor(Core.speed(cfg.tspeed)), 50, 500), function(v)
        cfg.tspeed = v; persist()
    end)
    RESET_UI.tspeed = sTween
    sIsland = mkSlider(ICON.rocket, "Island Speed", "Speed on long trips between islands (default 200)", nx(), 50, 500, math.clamp(math.floor(Core.speed(type(cfg.m) == "table" and cfg.m.IslandSpeed or nil)), 50, 500), function(v)
        cfg.m = type(cfg.m) == "table" and cfg.m or {}
        cfg.m.IslandSpeed = v; persist()
    end)
    RESET_UI.height = mkSlider(ICON.layers, "Height Above Enemies", "How high you stay over the enemies while farming", nx(), 5, 40, math.clamp(tonumber(cfg.height) or 15, 5, 40), function(v)
        cfg.height = v; persist()
    end)
    UIX.button(B, ICON.refresh, "Reset All Speeds To 200", "Tween, Island, Boat, Fly Boat and Leviathan speeds back to the default", nx(), "Reset", function()
        cfg.tspeed = 200
        cfg.m = type(cfg.m) == "table" and cfg.m or {}
        for _, k in ipairs({ "IslandSpeed", "SeaSpeed", "SeaFlySpeed", "LevSpeed" }) do cfg.m[k] = 200 end
        persist()
        pcall(function() sTween.set(200, true); sIsland.set(200, true) end)
        pcall(function()                                  -- sliders dos modulos que ja foram abertos
            local O = Core.options
            if O then for _, k in ipairs({ "SeaSpeed", "SeaFlySpeed", "LevSpeed" }) do if O[k] then O[k]:SetValue(200) end end end
        end)
        notify("Speeds", "All speeds are back to 200.", "ok", 2.5)
    end)
    -- v79/v98: pedido do usuario - um reset completo (todos os toggles/sliders/selects de TODAS as abas de farm, nao
    -- so as velocidades) precisa de confirmacao antes de executar (facil de clicar sem querer e perder tudo que
    -- estava configurado). confirmToast mostra "Sim"/"Nao" no canto inferior direito (mesmo lugar dos toasts
    -- normais) e fecha sozinho escolhendo "Nao" se ninguem clicar em 8s (barra embaixo mostra o tempo encolhendo)
    -- - so reseta de verdade se "Sim" for clicado a tempo. cfg.m e o MESMO Config.m usado pelas abas antigas
    -- (Races/Sub Farm/Vulcan/Raid/Fully/etc), entao limpar ele + chamar Core.AFL.resetFarmConfig() (zera tambem
    -- as opcoes nao-salvas, "TR", daquele modulo) cobre tudo de uma vez.
    -- v98: NUNCA mexe nas prioridades (cfg.prio/cfg.prioSlots/cfg.prioSlotN/cfg.prioAutoFilled) - pedido explicito
    -- do usuario. Antes esse reset tambem apagava a ordem de prioridade escolhida; agora ela fica intocada mesmo
    -- clicando "Sim".
    -- v140: pedido do usuario - alem do botao, a MESMA confirmacao (Yes/No) tambem aparece como notificacao ao executar o script
    -- (State.askFarmReset e chamado la embaixo, junto da notificacao de ReWhid).
    local function askFarmReset()
        confirmToast("You Want Reset Farm Settings?", "This resets farm toggles, sliders and selects (every tab) back to default - like Auto Dough King and similar options. Your priority order is never touched.", function()
            cfg.tool, cfg.method, cfg.m1Mode, cfg.cps, cfg.range, cfg.daSwap = "Melee", "Fast Attack", "Super Fast", 120, 60, 0.35
            cfg.targets = { NPC = true, BOSS = true, PLAYER = false }
            cfg.noM1Anim = true
            cfg.team, cfg.autoteam, cfg.v3, cfg.v4, cfg.buso, cfg.ken = "Pirates", true, false, false, true, false
            cfg.bring, cfg.bringN, cfg.bringRange = true, 3, 300
            cfg.flytween, cfg.tspeed, cfg.height, cfg.lvQuest = true, 200, 15, true
            -- v98: cfg.prio / cfg.prioSlots / cfg.prioSlotN / cfg.prioAutoFilled DE PROPOSITO fora daqui - as
            -- prioridades nunca sao resetadas junto
            cfg.m = type(cfg.m) == "table" and cfg.m or {}
            for k in pairs(cfg.m) do cfg.m[k] = nil end
            pcall(function() if Core.AFL and Core.AFL.resetFarmConfig then Core.AFL.resetFarmConfig() end end)
            persist()
            pcall(function() sTween.set(200, true); sIsland.set(200, true) end)
            -- v101: atualiza os controles na tela NA HORA (ve RESET_UI acima) - antes o reset so trocava o valor
            -- em cfg, entao o toggle/slider continuava mostrando o estado antigo (ligado quando ja tinha sido
            -- desligado, por exemplo) ate reabrir a aba. "true" = silencioso, nao dispara o onChange/persist de
            -- novo (ja foi feito aqui em cima).
            pcall(function()
                if RESET_UI.tool then RESET_UI.tool.set("Melee") end
                if RESET_UI.method then RESET_UI.method.set("Fast Attack") end
                if RESET_UI.noM1Anim then RESET_UI.noM1Anim.set(false, true) end
                if RESET_UI.targets then RESET_UI.targets.set({ NPC = true, BOSS = true }) end
                if RESET_UI.cps then RESET_UI.cps.set(120, true) end
                if RESET_UI.range then RESET_UI.range.set(60, true) end
                if RESET_UI.daSwap then RESET_UI.daSwap.set(35, true) end
                if RESET_UI.flytween then RESET_UI.flytween.set(true, true) end
                if RESET_UI.height then RESET_UI.height.set(15, true) end
                if RESET_UI.bring then RESET_UI.bring.set(true, true) end
                if RESET_UI.bringN then RESET_UI.bringN.set("3") end
                if RESET_UI.bringRange then RESET_UI.bringRange.set(300, true) end
                if RESET_UI.team then RESET_UI.team.set("Pirates") end
                if RESET_UI.autoteam then RESET_UI.autoteam.set(true, true) end
                if RESET_UI.v3 then RESET_UI.v3.set(false, true) end
                if RESET_UI.v4 then RESET_UI.v4.set(false, true) end
                if RESET_UI.buso then RESET_UI.buso.set(true, true) end
                if RESET_UI.ken then RESET_UI.ken.set(false, true) end
                if RESET_UI.lvQuest then RESET_UI.lvQuest.set(true, true) end
            end)
            notify("Farm Configs", "Farm settings are back to default (priorities kept) - the screen updates right away. Reopen a Dungeon/Raid/etc tab that was already open if any of ITS toggles still look off.", "ok", 6)
        end, 8)
    end
    State.askFarmReset = askFarmReset
    UIX.button(B, ICON.refresh, "Reset Farm Configs", "Resets EVERY farm toggle, slider and select (every tab) back to default - asks for confirmation first. Priorities are NEVER touched", nx(), "Reset", askFarmReset)

    -- ---------- Bring Mob ----------
    -- v89: V1 e V2 eram 2 toggles separados e confusos (V2 so travava com BodyVelocity e so agrupava mob do MESMO
    -- nome do alvo). Unificado num Bring Mob so: agora SEMPRE usa a trava mais forte (BodyVelocity "BatmanLock",
    -- sem colisao, parado de verdade) e agrupa qualquer inimigo no alcance (sem restricao de nome) - o melhor dos
    -- dois num toggle so, sem o usuario ter que escolher entre V1/V2.
    section(B, "Bring Mob", nx())
    RESET_UI.bring = mkToggle(B, ICON.layers, "Bring Mob", "Pulls and locks the nearby enemies (up to the number below) onto the farm spot, so you hit them all together", nx(), cfg.bring, function(v) cfg.bring = v; persist() end)
    do
        local nums = {}
        for i = 2, 10 do nums[#nums + 1] = tostring(i) end
        RESET_UI.bringN = mkSelect(ICON.cpu, "Bring Mob ( Select Number )", "How many enemies to pull (2 to 10)", nx(), nums, tostring(math.clamp(tonumber(cfg.bringN) or 3, 2, 10)), false, function(v)
            cfg.bringN = tonumber(v) or 3; persist()
        end)
        RESET_UI.bringRange = mkSlider(ICON.eye, "Bring Mob Range", "How far (studs) enemies can be pulled from (default 300). Lower = fewer ghost mobs, higher = bigger groups", nx(), 50, 350,
            math.clamp(tonumber(cfg.bringRange) or 300, 50, 350), function(v) cfg.bringRange = v; persist() end)
    end

    -- ---------- Team and Haki ----------
    section(B, "Team and Haki", nx())
    RESET_UI.team = mkSelect(ICON.shield, "Select Team", "Pirates or Marines", nx(), { "Pirates", "Marines" }, cfg.team, false, function(v) cfg.team = v; persist() end)
    RESET_UI.autoteam = mkToggle(B, ICON.check, "Auto Select Team", "Picks the selected team on the team screen", nx(), cfg.autoteam, function(v) cfg.autoteam = v; persist() end)

    RESET_UI.v3 = mkToggle(B, ICON.sun, "Auto V3", "Uses your race ability (V3) automatically", nx(), cfg.v3, function(v) cfg.v3 = v; persist() end)
    RESET_UI.v4 = mkToggle(B, ICON.power, "Auto V4", "Transforms (Y) when the race bar is full", nx(), cfg.v4, function(v) cfg.v4 = v; persist() end)
    RESET_UI.buso = mkToggle(B, ICON.shield, "Auto Buso", "Keeps Armament Haki on", nx(), cfg.buso, function(v) cfg.buso = v; persist() end)
    RESET_UI.ken = mkToggle(B, ICON.eye, "Auto Instinct", "Keeps Observation Haki on (presses E)", nx(), cfg.ken, function(v) cfg.ken = v; persist() end)

    -- ---------- v54b: eventos so quando aparecem ----------
    section(B, "Events", nx())
    if type(cfg.m) ~= "table" then cfg.m = {} end
    mkToggle(B, ICON.bell, "Events Only When They Spawn", "Collect Fruit, Pirate Raid, Elite Hunter and Chest only take the character when their target really exists (fruit on the ground, raid mobs, Elite alive, chest loaded). No map tours, Castle checks or Elite quests just to look", nx(), cfg.m.VulcSpawnOnly ~= false, function(v)
        cfg.m.VulcSpawnOnly = v; persist()
    end)

    -- ---------- Priorities (ultimo: lista grande que quase ninguem mexe) ----------
    -- v44: igual o Sea Events (Priority 1, 2, 3...): um dropdown por slot, escolhendo QUAL farm e aquela prioridade.
    -- Vem com 5 slots; "+ Add Slot" cria mais um no final, sem limite. Quem nao esta em nenhum slot continua rodando
    -- normal (se estiver ligado), so que depois de quem foi colocado em algum slot.
    section(B, "Priorities", nx())
    do
        local created = {}
        local function clear()
            for _, c in ipairs(created) do pcall(function() c:Destroy() end) end
            created = {}
        end
        function Core.prioOptions(cur)
            local opts = { Core.PRIO_NONE }
            for _, name in ipairs(Core.catalog) do
                if Core.isActiveFarm(name) or name == cur then opts[#opts + 1] = name end
            end
            return opts
        end
        local function render()
            clear()
            local slots, n = Core.ensurePrio()
            Core.prioSels = {}
            for i = 1, n do
                local sel = UIX.select(B, ICON.cpu, "Priority " .. i,
                    (i == 1) and "Only the functions that are ON show up here. With more than one wanting to run, priority 1 goes first, then 2, and so on. The rest keep running normally, after these." or nil,
                    nx(), Core.prioOptions(slots[i]), slots[i], false, function(v)
                        local s = (Core.ensurePrio())
                        s[i] = v; cfg.prioSlots, cfg.prioAutoFilled = s, false; persist()
                    end)
                Core.prioSels[i] = sel
                created[#created + 1] = sel.row
            end
            local addBtn = UIX.button(B, ICON.layers, "Add Slot", "Creates one more priority slot at the end", nx(), "+ Add Slot", function()
                Core.addPrioSlot(); persist(); render()
            end)
            created[#created + 1] = addBtn.row
            local rb = UIX.button(B, ICON.refresh, "Reset Priorities", "Back to the default slots (5)", nx(), "Reset", function()
                cfg.prio, cfg.prioSlots, cfg.prioSlotN = false, false, 5
                Core.ensurePrio(); persist(); render()
                notify("Priorities", "Back to the default slots.", "ok", 2)
            end)
            created[#created + 1] = rb.row
        end
        render()
        Core.renderPrio = render
        -- v54b: a lista de cada slot mostra so as funcoes LIGADAS (+ a que ja esta escolhida no slot); atualiza sozinha a cada 2 s
        task.spawn(function()
            local lastSig
            while alive do
                task.wait(2)
                pcall(function()
                    local act = {}
                    for _, name in ipairs(Core.catalog) do if Core.isActiveFarm(name) then act[#act + 1] = name end end
                    local sig = table.concat(act, "|")
                    if sig ~= lastSig then
                        lastSig = sig
                        local slots = Core.ensurePrio()
                        for i, sel in ipairs(Core.prioSels or {}) do pcall(sel.setOptions, Core.prioOptions(slots[i])) end
                    end
                end)
            end
        end)
        function Core.registerFarm(name)
            if not table.find(Core.catalog, name) then table.insert(Core.catalog, name) end
            render()
        end
    end

end)()

