        { lv = 2600, q = "SubmergedQuest1", i = 1, mob = "Reef Bandit", n = 8, npcn = "Submerged Quest Giver 1", npc = { 10781, -2088, 9260 }, sp = { {10884,-2160,9076},{10980,-2160,9052},{11040,-2156,9279},{11085,-2160,9130},{10900,-2145,9279} } },
