        { lv = 2725, q = "SubmergedQuest3", i = 2, mob = "Grand Devotee", n = 8, npcn = "Submerged Quest Giver 3", npc = { 9637, -1993, 9616 }, sp = { {9720,-1990,10134},{9609,-1994,9956},{9589,-1994,9705},{9559,-1994,9799},{9620,-1994,9872},{9561,-1990,10090} } },
      },
    }

    local PLACE = { [2753915549] = 1, [85211729168715] = 1, [4442272183] = 2, [79091703265657] = 2, [7449423635] = 3, [100117331123089] = 3 }
    local SEA_NAME = { "First Sea", "Second Sea", "Third Sea" }
    local NEXT_SEA_AT = { 700, 1500 }      -- level a partir do qual vale mudar para o proximo mar

    local function getChar()
        local c = LP.Character
        return c, c and c:FindFirstChild("HumanoidRootPart"), c and c:FindFirstChildOfClass("Humanoid")
    end
    local function dist(a, b) return (a - b).Magnitude end

    -- --------------------------------------------------------- leitura do jogo ----
    -- mar: 1) PlaceId conhecido  2) mobs/spawns do mundo (unicos de cada mar)  3) Realm do jogo  4) level (como o v52)
    local MOBSEA
    local function mobSeaMap()
        if MOBSEA then return MOBSEA end
        MOBSEA = {}
        for sea = 1, 3 do
            for _, e in ipairs(LV.DATA[sea] or {}) do
                if MOBSEA[e.mob] == nil then MOBSEA[e.mob] = sea elseif MOBSEA[e.mob] ~= sea then MOBSEA[e.mob] = false end
            end
        end
        return MOBSEA
    end
    local function worldSea()
        local map, score = mobSeaMap(), { 0, 0, 0 }
        local function scan(folder)
            if not folder then return end
            for _, c in ipairs(folder:GetChildren()) do
                local sea = map[(tostring(c.Name):gsub("%s*%b[]", ""):gsub("^%s+", ""):gsub("%s+$", ""))]
                if sea then score[sea] += 1 end
            end
        end
        pcall(function()
            local wo = workspace:FindFirstChild("_WorldOrigin")
            scan(wo and wo:FindFirstChild("EnemySpawns"))
            scan(workspace:FindFirstChild("EnemySpawns"))
            scan(workspace:FindFirstChild("Enemies"))
        end)
        local best, bs = nil, 0
        for i = 1, 3 do if score[i] > bs then best, bs = i, score[i] end end
        return (bs >= 2) and best or nil
    end
    local function seaId(lvl)
        if LV.sea and LV.seaSure then return LV.sea end
        local s, src = PLACE[game.PlaceId], "PlaceId"
        if not s then s, src = worldSea(), "world" end
        if s then LV.sea, LV.seaSure, LV.seaSrc = s, true, src; return s end
        if os.clock() - (LV.seaAt or 0) < 1 and LV.sea then return LV.sea end
        LV.seaAt = os.clock()
        pcall(function()
            local Realm = require(RS.Util.Realm)
            if Realm.getIfCurrentRealmHasTagAsync("IsThirdSea") then s = 3
            elseif Realm.getIfCurrentRealmHasTagAsync("IsSecondSea") then s = 2
            elseif Realm.getIfCurrentRealmHasTagAsync("IsFirstSea") then s = 1 end
        end)
        src = "Realm"
        if not s then
            local l = lvl or (LP:FindFirstChild("Data") and LP.Data:FindFirstChild("Level") and tonumber(LP.Data.Level.Value)) or 1
            s = (l >= 1500 and 3) or (l >= 700 and 2) or 1
            src = "level"
        end
        LV.sea, LV.seaSrc = s, src
        return s
    end
    local function myLevel()
        local d = LP:FindFirstChild("Data")
        local l = d and d:FindFirstChild("Level")
        return l and tonumber(l.Value) or nil
    end
    -- quest certa para o level: a de maior 'lv' que ainda seja <= ao seu level (no mar atual)
    function LV.pick(sea, lvl)
        local list = LV.DATA[sea]
        if not list then return nil end
        local best
        for _, e in ipairs(list) do
            if e.lv <= lvl then best = e else break end
        end
        return best, list[#list]
    end
    -- "Bandit [Lv. 5]" -> "Bandit"
    local function baseName(n)
        n = tostring(n or "")
        n = n:gsub("%s*%b[]", "")
        n = n:gsub("^%s+", ""):gsub("%s+$", "")
        return n
    end
    LV.baseName = baseName

    -- quest ativa (mesma fonte que o jogo usa na janela da quest: GuideData.QuestData, alimentada por Remotes.QuestUpdate)
    local function readQuest()
        local q
        local ok = pcall(function() q = require(RS.GuideModule.GuideData).Data.QuestData end)
        if not ok then q = LV.evQuest end   -- plano B so se o modulo do jogo nao puder ser lido
        if type(q) == "table" and type(q.Info) == "table" and type(q.Info.Task) == "table" then return q end
        return nil
    end
    local function taskNeed(v)
        if type(v) == "number" then return v end
        if type(v) == "table" and type(v.Amount) == "number" then return v.Amount end
        return 1
    end
    local function questProgress(q)
        local have, need, done = 0, 0, true
        for mob, amt in pairs(q.Info.Task) do
            local n = taskNeed(amt)
            local p = q.Progress and q.Progress[mob]
            local h = 0
            if p == true then h = n elseif type(p) == "number" then h = math.min(p, n) end
            have += h; need += n
            if h < n then done = false end
        end
        return have, need, done
    end
    -- entrada da tabela de um mob (e o mar a que ela pertence)
    local function entryForMob(mob)
        local sea = seaId()
        for _, s in ipairs({ sea or 1, 1, 2, 3 }) do
            for _, e in ipairs(LV.DATA[s] or {}) do
                if e.mob == mob then return e, s end
            end
        end
        return nil
    end
    -- quest/indice ao vivo (ReplicatedStorage.Quests, a mesma lista que o v52 usa): se o nome da tabela mudou no jogo, acha pelo mob
    local QMOD, QMAT = nil, -100
    local function questModule()
        if QMOD then return QMOD end
        if os.clock() - QMAT < 20 then return nil end
        QMAT = os.clock()
        pcall(function() local m = RS:FindFirstChild("Quests"); if m then QMOD = require(m) end end)
        if type(QMOD) ~= "table" then QMOD = nil end
        return QMOD
    end
    local QICACHE = setmetatable({}, { __mode = "k" })
    local function liveQI(e)
        if QICACHE[e] then return QICACHE[e][1], QICACHE[e][2] end
        local qm = questModule()
        if not qm then return e.q, e.i end
        local q, i = e.q, e.i
        local l = type(qm[e.q]) == "table" and qm[e.q][e.i]
        if not (type(l) == "table" and type(l.Task) == "table" and l.Task[e.mob]) then
            for qn, levels in pairs(qm) do
                if type(levels) == "table" then
                    for idx, ql in pairs(levels) do
                        if type(ql) == "table" and type(ql.Task) == "table" and ql.Task[e.mob] then q, i = qn, idx end
                    end
                end
            end
        end
        QICACHE[e] = { q, i }
        return q, i
    end
    -- NPC da quest: posicao ao vivo em workspace.NPCs (se existir), senao a da tabela
    -- v54: pontos de spawn reais do jogo para um mob (cache de 30 s)
    local SPC = {}
    function LV.liveSpawns(mob)
        local c = SPC[mob]
        if c and os.clock() - c.at < 30 then return c.list end
        local list = {}
        pcall(function()
            local wo = workspace:FindFirstChild("_WorldOrigin")
            for _, f in ipairs({ wo and wo:FindFirstChild("EnemySpawns"), workspace:FindFirstChild("EnemySpawns") }) do
                for _, s in ipairs(f and f:GetChildren() or {}) do
                    if s:IsA("BasePart") and (baseName(s.Name) == mob or string.sub(s.Name, 1, #mob) == mob) then
                        list[#list + 1] = { s.Position.X, s.Position.Y, s.Position.Z }
                    end
                end
            end
        end)
        SPC[mob] = { at = os.clock(), list = list }
        return list
    end
    local function npcPosOf(e)
        local npcs = workspace:FindFirstChild("NPCs")
        local n = npcs and npcs:FindFirstChild(e.npcn)
        if n then
            local ok, p = pcall(function() return n:GetPivot().Position end)
            -- v54: NPC ainda nao carregado devolve a posicao zerada (centro do mapa): usa a da tabela
            if ok and p and p.Magnitude > 50 then return p end
        end
        return Vector3.new(e.npc[1], e.npc[2], e.npc[3])
    end
    -- NPC qualquer mais perto dos mobs (plano B do v52 quando o NPC da tabela nao aceita)
    local function nearestNpcToMobs(e)
        local npcs = workspace:FindFirstChild("NPCs")
        if not npcs then return nil end
        local a = Vector3.new(e.sp[1][1], e.sp[1][2], e.sp[1][3])
        local bp, bd = nil, 600
        for _, n in ipairs(npcs:GetChildren()) do
            local ok, p = pcall(function() return n:GetPivot().Position end)
            if ok and p and (p.Y <= -500) == (a.Y <= -500) then
                local d = (p - a).Magnitude
                if d < bd then bp, bd = p, d end
            end
        end
        return bp
    end

    -- ------------------------------------------------------------ janela da quest ----
    -- (mesma leitura do Moon Hub Key-Pro v52, que funcionava: Main.Quest + titulo "Defeat N Mob (x/N)")
    local QG
    local function questGui()
        if QG and QG.Parent then return QG end
        local pg = LP:FindFirstChild("PlayerGui")
        local main = pg and pg:FindFirstChild("Main")
        if main then QG = main:FindFirstChild("Quest") or main:FindFirstChild("Quest", true) end
        return QG
    end
    local function guiQuest()
        local g = questGui()
        if not g or g.Visible ~= true then return nil end
        local title
        pcall(function()
            local t = g:FindFirstChild("QuestTitle", true)
            local lb = t and (t:FindFirstChild("Title") or t)
            if lb and lb:IsA("TextLabel") then title = lb.Text end
        end)
        return { title = title or "" }
    end
    -- nome do mob a partir do titulo ("Defeat 8 Bandits (3/8)")
    local function mobFromTitle(title, pref)
        local lt = string.lower(title or "")
        if lt == "" then return nil end
        local function hit(e)
            local m = string.lower(e.mob)
            return string.find(lt, m, 1, true) or (#m > 3 and string.find(lt, string.sub(m, 1, #m - 1), 1, true))
        end
        if pref and hit(pref) then return pref.mob end
        for _, s in ipairs({ seaId() or 1, 1, 2, 3 }) do
            for _, e in ipairs(LV.DATA[s] or {}) do if hit(e) then return e.mob end end
        end
        return nil
    end
    -- estado da quest: {have, need, done, names(set), first, title} ou nil se nao ha quest
    local function questState(pref)
        local q = readQuest()
        if q then
            local have, need, done = questProgress(q)
            local names, first = {}, nil
            for mob in pairs(q.Info.Task) do names[mob] = true; first = first or mob end
            return { src = "data", have = have, need = need, done = done, names = names, first = first, title = q.Info.Name }
        end
        local g = guiQuest()
        if g then
            local a, b = string.match(g.title, "%((%d+)%s*/%s*(%d+)%)")
            local have, need = tonumber(a) or 0, tonumber(b) or 0
            local mob = mobFromTitle(g.title, pref)
            return { src = "window", have = have, need = need, done = (need > 0 and have >= need), names = mob and { [mob] = true } or nil, first = mob, title = g.title }
        end
        return nil
    end

    -- ------------------------------------------------------------ movimento ----
    -- voo passo a passo no Heartbeat (como o flyTo do v52): sem TweenService, com noclip e altitude de cruzeiro
    local CRUISE = 90
    local function setHold(on)
        local _, hrp = getChar()
        if not hrp then return end
        local bv = hrp:FindFirstChild("MoonLvHold")
        if on and not bv then
            bv = Instance.new("BodyVelocity")
            bv.Name = "MoonLvHold"; bv.Velocity = Vector3.zero; bv.MaxForce = Vector3.new(1e9, 1e9, 1e9); bv.Parent = hrp
        elseif not on and bv then
            pcall(function() bv:Destroy() end)
        end
    end
    local function restoreMobs()
        for m, ws in pairs(LV.WS) do
            pcall(function()
                local h = m.Parent and m:FindFirstChildOfClass("Humanoid")
                if h then h.WalkSpeed = ws end
            end)
        end
        for _, m in ipairs(LV.mobs or {}) do Core.freeMob(m) end   -- v53: solta de verdade (V2, PlatformStand)
        LV.WS = {}
        LV.mobs, LV.pullCF, LV.group, LV.anchor = {}, nil, nil, nil
    end
    local function release()
        LV.hold, LV.fly, LV.active, LV.cruiseY, LV.farTrip = nil, nil, false, nil, nil
        if LV.phys then LV.phys = false; Core.flightPhys(false) end   -- v149
        restoreMobs()
        if LV.attackOwned and Core.attacking then Core.setAttack(false) end
        LV.attackOwned = false
        setHold(false)
    end
    LV.release = release
    local function attack(on)
        if on then
            if not Core.attacking then Core.setAttack(true); LV.attackOwned = true end
        elseif LV.attackOwned and Core.attacking then
            Core.setAttack(false); LV.attackOwned = false
        end
    end
    -- voa ate 'pos'. Retorna true quando chegou (e segura o personagem la, com 'cf' se for dado)
    local function goTo(pos, arrive, cf)
        local _, hrp = getChar()
        if not hrp then return false end
        LV.active = true
        setHold(true)
        if dist(hrp.Position, pos) <= (arrive or 12) then
            LV.fly, LV.cruiseY, LV.farTrip = nil, nil, nil
            LV.hold = cf or CFrame.new(pos)
            return true
        end
        LV.hold = nil
        LV.fly = pos
        return false
    end
    local lvSt = Core.newMover()
    table.insert(conns, RunService.Heartbeat:Connect(function(dt)
        if not LV.active then return end
        local _, hrp = getChar()
        if not hrp then return end
        dt = math.min(tonumber(dt) or 0.016, 0.1)
        local cf, t = LV.hold, LV.fly
        if cf then
            hrp.CFrame = cf
            hrp.AssemblyLinearVelocity = Vector3.zero
            hrp.AssemblyAngularVelocity = Vector3.zero
        elseif t then
            local p = hrp.Position
            local hd = dist(Vector3.new(t.X, 0, t.Z), Vector3.new(p.X, 0, p.Z))
            local goal = t
            if hd > 300 then                       -- viagem longa: sobe ate a altitude de cruzeiro e voa por cima (v54: 120 -> 300, viagem curta vai reto)
                LV.cruiseY = LV.cruiseY or (math.max(t.Y, p.Y) + CRUISE)
                -- v147: sobe NA DIAGONAL ja indo pro destino (antes subia reto ate a altitude e so depois seguia = parava/virava)
                goal = Vector3.new(t.X, math.max(LV.cruiseY, p.Y), t.Z)
            else
                LV.cruiseY = nil
            end
            local speed = Core.speed(cfg.tspeed)
            if hd > 400 then LV.farTrip = true end
            if LV.farTrip then speed = math.max(speed, Core.speed(type(cfg.m) == "table" and cfg.m.IslandSpeed or nil)) end   -- v147: viagem longa: Island Speed ate chegar
            local diff = goal - p
            local len = diff.Magnitude
            LV.phys = true; Core.flightPhys(true)   -- v149
            local np = len < 0.01 and goal or Core.moveStep(lvSt, p, diff, dist(t, p), dt, speed)
            hrp.CFrame = CFrame.new(np)
            hrp.AssemblyLinearVelocity = Vector3.zero
            hrp.AssemblyAngularVelocity = Vector3.zero
        end
    end))
    -- noclip no personagem enquanto o farm esta ativo
    table.insert(conns, RunService.Stepped:Connect(function()
        if not LV.active then return end
        local char = LP.Character
        if not char then return end
        for _, p in ipairs(char:GetDescendants()) do
            if p:IsA("BasePart") and p.CanCollide then p.CanCollide = false end
        end
    end))
    -- v54: segura os mobs puxados tambem ANTES da fisica (Stepped), nao so depois (Heartbeat): eles nao escorregam/voltam entre um frame e outro
    table.insert(conns, RunService.Stepped:Connect(function()
        local cf = LV.pullCF
        if not cf then return end
        for _, m in ipairs(LV.mobs) do
            local h = m.Parent and m:FindFirstChildOfClass("Humanoid")
            local r = m:FindFirstChild("HumanoidRootPart")
            if h and r and h.Health > 0 and not Core.isGhost(m) then Core.pullMob(m, r, h, cf) end
        end
    end))
    -- mobs puxados: reaplicados a cada frame (o servidor os empurra de volta se so mexer 1x) + cliente como dono da fisica
    table.insert(conns, RunService.Heartbeat:Connect(function()
        local cf = LV.pullCF
        if not cf then return end
        local now = os.clock()
        if now - (LV.simAt or 0) > 0.25 then
            LV.simAt = now
            pcall(function() sethiddenproperty(LP, "SimulationRadius", 500) end)   -- v60: igual o bomba (500, nao infinito)
        end
        for _, m in ipairs(LV.mobs) do
            local h = m.Parent and m:FindFirstChildOfClass("Humanoid")
            local r = m:FindFirstChild("HumanoidRootPart")
            if h and r and h.Health > 0 and Core.pullOK(m, r, LV.ORIG and LV.ORIG[m]) then
                if LV.WS[m] == nil and h.WalkSpeed > 0 then LV.WS[m] = h.WalkSpeed end
                -- v53: mesmo puxao das outras farms (agora respeita o Bring Mob V2 = BodyPosition)
                Core.pullMob(m, r, h, cf)
            end
        end
    end))

    -- ------------------------------------------------------------ combate ----
    -- mobs vivos com um dos nomes de 'names' (set): nome exato (sem "[Lv. N]"); se nao achar nenhum, por prefixo (como o v52)
    local ORIG = setmetatable({}, { __mode = "k" })   -- posicao original (spawn) de cada mob: ponto estavel para puxar
    LV.ORIG = ORIG
    local function findMobs(names, prefer)
        local out, pre = {}, {}
        local f = workspace:FindFirstChild("Enemies")
        local _, hrp = getChar()
        if not (f and hrp) then return out end
        for _, m in ipairs(f:GetChildren()) do
            local h = m:FindFirstChildOfClass("Humanoid")
            local r = m:FindFirstChild("HumanoidRootPart")
            if h and r and h.Health > 0 and not m:GetAttribute("IsBoat") and not Core.isGhost(m) then
                local bn = baseName(m.Name)
                local hitExact = names[bn]
                local hitPre = false
                if not hitExact then
                    for n in pairs(names) do if string.sub(m.Name, 1, #n) == n then hitPre = true break end end
                end
                if hitExact or hitPre then
                    ORIG[m] = ORIG[m] or r.Position
                    local rec = { m, r, h, dist(r.Position, hrp.Position) }
                    if hitExact then out[#out + 1] = rec else pre[#pre + 1] = rec end
                end
            end
        end
        if #out == 0 then out = pre end
        table.sort(out, function(a, b)
            if prefer then
                local pa, pb = prefer[baseName(a[1].Name)] and 0 or 1, prefer[baseName(b[1].Name)] and 0 or 1
                if pa ~= pb then return pa < pb end
            end
            return a[4] < b[4]
        end)
        return out
    end
    LV.findMobs = findMobs
    local function haveTool()
        local want = ({ Melee = "Melee", Sword = "Sword", Fruit = "Blox Fruit" })[cfg.tool]
        if not want then return true end
        local function scan(c)
            if not c then return false end
            for _, t in ipairs(c:GetChildren()) do if t:IsA("Tool") and t.ToolTip == want then return true end end
            return false
        end
        return scan(LP.Character) or scan(LP:FindFirstChild("Backpack"))
    end

    -- names: set de nomes | e: entrada da tabela (para esperar o respawn) | label: nome para o status
    local function farmMobs(names, e, label, prefer)
        local H = math.clamp(tonumber(cfg.height) or 15, 5, 60)
        local list = findMobs(names, prefer)
        if #list == 0 then
            attack(false)
            restoreMobs()
            LV.anchor = nil
            if not e then LV.text = "No enemies found for " .. label; release(); return end
            -- espera o respawn em cima dos pontos de spawn.
            -- v54: usa os pontos de spawn REAIS do jogo (_WorldOrigin.EnemySpawns) quando existem, e so roda entre os pontos
            -- perto do primeiro (ate 450 studs), do mais perto pro mais longe, 8 s em cada. Antes a tabela misturava pontos de
            -- lugares distantes (ex.: Raider) e ele ficava voando de um lado pro outro "pro nada" a cada 6 s.
            local _, hrp = getChar()
            if LV.spFor ~= e or not LV.spList then
                local raw = LV.liveSpawns(e.mob)
                if #raw == 0 then raw = e.sp end
                local pts = {}
                for _, p in ipairs(raw) do pts[#pts + 1] = Vector3.new(p[1], p[2], p[3]) end
                table.sort(pts, function(a, b) return dist(hrp.Position, a) < dist(hrp.Position, b) end)
                local list = {}
                for _, v in ipairs(pts) do
                    if #list == 0 or dist(v, list[1]) <= 450 then list[#list + 1] = v end
                end
                LV.spFor, LV.spList, LV.spI, LV.spAt = e, list, 1, os.clock()
            elseif os.clock() - LV.spAt > 8 then
                LV.spAt = os.clock(); LV.spI = LV.spI % #LV.spList + 1
            end
            local v = LV.spList[LV.spI] or LV.spList[1]
            if not v then LV.text = "No spawn point known for " .. label; release(); return end
            local p = { v.X, v.Y, v.Z }
            if goTo(Vector3.new(p[1], p[2] + H, p[3]), 15) then LV.text = "Waiting for " .. label .. " to spawn"
            else LV.text = "Going to " .. label .. " spawn" end
            return
        end
        -- grupo puxado: ancorado na posicao ORIGINAL do mob mais perto; muda so quando o grupo inteiro morre
        local now = os.clock()
        local groupAlive = false
        if LV.anchor then
            for _, t in ipairs(list) do if dist(t[2].Position, LV.anchor) < 60 then groupAlive = true break end end
        end
        if not groupAlive then
            local first = list[1]
            LV.anchor = ORIG[first[1]] or first[2].Position
            LV.leadName = first[1].Name
            LV.mobs, LV.topAt = {}, 0
        end
        local anchor = LV.anchor
        local pull = cfg.bring ~= false   -- v89: Bring Mob unificado (nao tem mais V2 separado)
        if pull then
            if now - (LV.topAt or 0) > 0.15 then     -- v54: completa o grupo bem mais rapido (0,4 s -> 0,15 s)
                LV.topAt = now
                local lim = math.clamp(tonumber(cfg.bringN) or 3, 2, 10)
                local cands = {}
                for _, t in ipairs(list) do
                    local d = dist(t[2].Position, anchor)
                    if d < Core.bringRange() then cands[#cands + 1] = { t[1], d, (prefer and prefer[baseName(t[1].Name)]) and 0 or 1 } end
                end
                table.sort(cands, function(a, b) if a[3] ~= b[3] then return a[3] < b[3] end return a[2] < b[2] end)
                local mobs = {}
                for i = 1, math.min(lim, #cands) do mobs[i] = cands[i][1] end
                -- quem saiu do grupo volta a andar
                local keep = {}
                for _, m in ipairs(mobs) do keep[m] = true end
                for _, m in ipairs(LV.mobs) do
                    if not keep[m] then
                        Core.freeMob(m)   -- v53: antes so voltava o WalkSpeed; o mob ficava "deitado" (PlatformStand) no lugar
                        if LV.WS[m] then
                            pcall(function() local h = m:FindFirstChildOfClass("Humanoid"); if h then h.WalkSpeed = LV.WS[m] end end)
                            LV.WS[m] = nil
                        end
                    end
                end
                LV.mobs = mobs
            end
            LV.pullCF = CFrame.new(anchor)
        else
            LV.mobs, LV.pullCF = {}, nil
            anchor = list[1][2].Position         -- sem Bring Mob: fica em cima do mob mais perto
        end
        local stand = anchor + Vector3.new(0, H, 0)
        local standCF = CFrame.new(stand) * CFrame.Angles(0, 0, 0)   -- em pe (reto)
        local _, hrp = getChar()
        local dStand = dist(hrp.Position, stand)
        if goTo(stand, 8, standCF) then
            attack(true)
            LV.text = string.format("Killing %s", label)
        else
            if dStand < 70 then attack(true) else attack(false) end
            LV.text = "Flying to " .. label
        end
    end

    -- ---------------------------------------------------------- submarino ----
    local function netRemote(name)
        local m = RS:FindFirstChild("Modules")
        local n = m and m:FindFirstChild("Net")
        local r = n and n:FindFirstChild(name)
        if r then return r end
        local ok, w = pcall(function() return RS:WaitForChild("Modules", 2):WaitForChild("Net", 2):WaitForChild(name, 2) end)
        return ok and w or nil
    end
    local TIKI = Vector3.new(-16269.7, 25.2, 1373.4)          -- Submarine Worker (Tiki Outpost)
    local SUB_EXIT = Vector3.new(11426, -2155, 9732)          -- saida da Submerged Island
    local function waitFly(pos, maxT)
        local t0 = os.clock()
        while alive and LV.on and os.clock() - t0 < maxT do
            local _, hrp = getChar()
            if not hrp then return false end
            if goTo(pos, 6) then return true end
            task.wait(0.1)
        end
        return false
    end
    function LV.goSub()
        if LV.subBusy then return end
        LV.subBusy = true
        task.spawn(function()
            local ok, err = pcall(function()
                local npcs = workspace:FindFirstChild("NPCs")
                local npc = npcs and npcs:FindFirstChild("Submarine Worker")
                if not npc and npcs then
                    for _, n in ipairs(npcs:GetChildren()) do if string.find(n.Name, "Submarine", 1, true) then npc = n break end end
                end
                local pos = TIKI
                if npc then local okp, p = pcall(function() return npc:GetPivot().Position end); if okp and p then pos = p end end
                LV.subText = "Flying to the Submarine Worker"
                if not waitFly(pos + Vector3.new(0, 4, 0), 120) then return end
                local _, hrp = getChar()
                if not hrp then return end
                LV.hold, LV.fly = nil, nil          -- solta o personagem: o teleporte do servidor nao pode ser desfeito pelo Heartbeat
                local before = hrp.Position
                local function moved()
                    local _, h = getChar()
                    return h and ((h.Position - before).Magnitude > 300 or h.Position.Y <= -500)
                end
                LV.subText = "Talking to the Submarine Worker"
                local attempts = {
                    function() local rf = netRemote("RF/SubmarineWorkerSpeak"); if rf then rf:InvokeServer("TravelToSubmergedIsland") end end,
                    function() RS.Remotes.CommF_:InvokeServer("SubmarineWorkerSpeak", "TravelToSubmergedIsland") end,
                    function()
                        local prompt = npc and npc:FindFirstChildWhichIsA("ProximityPrompt", true)
                        if prompt and fireproximityprompt then fireproximityprompt(prompt) end
                    end,
                }
                for _, try in ipairs(attempts) do
                    pcall(try)
                    for _ = 1, 8 do
                        task.wait(0.5)
                        if moved() then break end
                    end
                    if moved() then
                        LV.subFails, LV.subUntil = 0, os.clock() + 40
                        task.wait(2)
                        return
                    end
                    if not (alive and LV.on) then return end
                end
                LV.subFails = (LV.subFails or 0) + 1
                if LV.subFails == 2 then
                    notify("Level Farm", "Could not travel to the Submerged Island. Talk to the Submarine Worker once by hand and the farm continues.", "warn", 6)
                end
            end)
            if not ok then LV.subText = "Submarine error: " .. tostring(err) end
            LV.subBusy = false
        end)
    end
    function LV.leaveSub()
        local _, hrp = getChar()
        if not hrp then return end
        if dist(hrp.Position, SUB_EXIT) > 20 then
            goTo(SUB_EXIT, 15)
            LV.text = "Leaving the Submerged Island"
            return
        end
        LV.text = "Leaving the Submerged Island (teleport)"
        LV.hold, LV.fly = nil, nil
        if os.clock() - (LV.exitAt or 0) > 3 then
            LV.exitAt = os.clock()
            task.spawn(function()
                local rf = netRemote("RF/SubmarineTransportation")
                if rf then pcall(function() rf:InvokeServer("InitiateTeleport", "Tiki Outpost") end) end
            end)
        end
    end

    -- pega a quest no NPC (com as tentativas/espera/modo cego); blindFn() farma quando a quest nao foi detectada
    local function takeQuest(e, blindFn)
        local now = os.clock()
        -- pegar a quest: voa ate o NPC e usa o StartQuest (mesmo remote do Moon antigo e do Quantum)
        if LV.takenAt and LV.tookOk and not LV.blindUntil and now - LV.takenAt >= 3 then LV.blindUntil = now + 75 end
        if LV.blindUntil then
            if now < LV.blindUntil then
                blindFn()
                LV.text = LV.text .. " (quest not detected, farming anyway)"
                return
            end
            LV.blindUntil, LV.takenAt, LV.tookOk = nil, nil, false
        end
        attack(false); restoreMobs()
        local npcPos = ((LV.altNpc and LV.altFor == e) and LV.altNpc or npcPosOf(e)) + Vector3.new(0, 3, 0)
        if not goTo(npcPos, 14) then
            LV.text = "Going to " .. e.npcn
            return
        end
        if LV.takenAt and now - LV.takenAt < 2 then   -- v54: 5 s -> 2 s esperando a quest aparecer
            LV.text = "Waiting for the quest to register..."
            return
        end
        LV.text = "Taking quest " .. e.q .. " #" .. e.i
        if now - (LV.qAt or 0) > 0.8 then   -- v54: tenta de novo mais rapido
            if (LV.qTries or 0) == 2 and not LV.altNpc then   -- NPC da tabela nao aceitou: tenta o NPC mais perto dos mobs
                LV.altNpc, LV.altFor = nearestNpcToMobs(e), e
            end
            if (LV.qTries or 0) >= 5 then
                if now - (LV.qAt or 0) < 12 then LV.text = "Quest refused, retrying soon (check level and Sea)"; return end
                LV.qTries, LV.altNpc = 0, nil
            end
            LV.qAt, LV.takenAt = now, now
            LV.qTries = (LV.qTries or 0) + 1
            task.spawn(function()
                local ok, res = pcall(function() return RS.Remotes.CommF_:InvokeServer("StartQuest", liveQI(e)) end)
                LV.tookOk = ok
                LV.res = ok and tostring(res) or ("error: " .. tostring(res))
            end)
        end
    end
    LV.E = LV.E or {}
    LV.E.takeQuest = takeQuest

    -- --------------------------------------------------------------- passo ----
    local function step()
        local char, hrp, hum = getChar()
        if not (char and hrp and hum) or hum.Health <= 0 then
            LV.anchor = nil; release(); LV.text = "Waiting for your character"; return
        end
        local lvl = myLevel()
        if not lvl then LV.text = "Reading your level..."; return end
        local sea = seaId(lvl)
        LV.lvl = lvl
        -- v71: antes isso travava a farm pedindo pra ir ligar o NPC em outra aba (Farm Settings > Attack Select) -
        -- se o jogador nunca via essa mensagem (ou nunca ligava aquele toggle a parte) a farm ficava "trava/nao
        -- faz nada" pra sempre, mesmo com Level Farm ligado. Agora liga o NPC sozinho, que e obrigatorio pra essa
        -- farm funcionar de qualquer jeito (nao faz sentido ela pedir pro usuario fazer isso manualmente).
        if not (cfg.targets and cfg.targets.NPC) then
            cfg.targets = cfg.targets or {}
            cfg.targets.NPC = true
            persist()
        end
        if not haveTool() then
            release(); LV.text = "No " .. tostring(cfg.tool) .. " found. Pick a weapon in Farm Settings"; return
        end
        local e, top = LV.pick(sea, lvl)
        if not e then
            release(); LV.entry = nil
            LV.text = string.format("Level %d is too low for the %s (starts at %d)", lvl, SEA_NAME[sea], LV.DATA[sea][1].lv)
            return
        end
        LV.entry = e
        if NEXT_SEA_AT[sea] and lvl >= NEXT_SEA_AT[sea] and not LV.hinted then
            LV.hinted = true
            notify("Level Farm", "You are ready for the next Sea. Farming here still works, but the next Sea gives much more EXP.", "warn", 6)
        end
        -- Submerged Island (Y <= -500): viaja pelo Submarine Worker ao entrar e pelo teleporte de saida ao sair
        local under = e.sp[1][2] <= -500
        local inSub = hrp.Position.Y <= -500
        if LV.subBusy then LV.text = LV.subText or "Traveling..."; return end
        if under and not inSub then
            if os.clock() > (LV.subUntil or 0) and os.clock() - (LV.subTry or 0) > 8 then
                LV.subTry = os.clock()
                LV.goSub()
            end
            if not LV.subBusy then LV.text = "Going to the Submerged Island..." end
            return
        elseif inSub and not under then
            LV.leaveSub()
            return
        end

        local now = os.clock()
        local qs = questState(e)
        do
            local nm = 0
            pcall(function() nm = #findMobs({ [e.mob] = true }) end)
            local dn = dist(hrp.Position, Vector3.new(e.npc[1], e.npc[2], e.npc[3]))
            LV.dbg = string.format("PlaceId %s | Sea %s (%s) | Lv %s | Quest %s #%s (%s) | detected: %s | StartQuest: %s | %s alive: %d | NPC dist: %d",
                tostring(game.PlaceId), tostring(sea), tostring(LV.seaSrc), tostring(lvl), (liveQI(e)), tostring(select(2, liveQI(e))), e.mob, qs and (qs.src or "yes") or "no",
                tostring(LV.res or "-"), e.mob, nm, dn)
        end
        if qs then
            LV.qTries, LV.takenAt, LV.blindUntil, LV.tookOk = 0, nil, nil, false
            LV.have, LV.need = qs.have, qs.need
            LV.lastActive, LV.lastQ = now, qs
            if qs.done then   -- concluida: limpa a janela para poder pegar a proxima
                release()
                LV.text = "Quest complete"
                if now - (LV.doneAt or 0) > 1 then
                    LV.doneAt = now
                    task.spawn(function() pcall(function() RS.Remotes.CommF_:InvokeServer("AbandonQuest") end) end)
                end
                return
            end
            local names, first = qs.names, qs.first
            if not names then names = { [e.mob] = true }; first = e.mob end   -- titulo ilegivel: usa o mob da tabela
            local ent, entSea = nil, nil
            if first then ent, entSea = entryForMob(first) end
            if ent and entSea ~= sea then
                release()
                LV.text = "Quest from another Sea, clearing it"
                LV.staleAt = LV.staleAt or now
                if now - LV.staleAt > 3 then
                    LV.staleAt = nil
                    task.spawn(function() pcall(function() RS.Remotes.CommF_:InvokeServer("AbandonQuest") end) end)
                end
                return
            end
            LV.staleAt = nil
            farmMobs(names, ent, first or "enemies")
            if LV.text:find("^Killing") or LV.text:find("^Flying") then
                LV.text = (qs.title ~= "" and qs.title or first or "Quest") .. " " .. qs.have .. "/" .. qs.need .. " - " .. LV.text
            end
            return
        end
        -- janela da quest piscou? espera um instante antes de achar que acabou (a menos que faltasse so 1 kill)
        if LV.lastQ and LV.lastActive and now - LV.lastActive < 1.0 and (LV.lastQ.need - LV.lastQ.have) > 1 then
            LV.text = "Checking quest..."
            return
        end
        LV.have, LV.need, LV.doneAt, LV.lastQ = 0, 0, nil, nil

        if cfg.lvQuest == false then          -- sem pegar quest: so mata os mobs do seu level
            farmMobs({ [e.mob] = true }, e, e.mob)
            return
        end

        takeQuest(e, function() farmMobs({ [e.mob] = true }, e, e.mob) end)
    end

    -- ------------------------------------------------------------- laco ----
    task.spawn(function()
        local rem = RS:WaitForChild("Remotes", 30)
        local ev = rem and rem:WaitForChild("QuestUpdate", 30)
        if ev then table.insert(conns, ev.OnClientEvent:Connect(function(q) LV.evQuest = q end)) end
    end)
    local function abandonQuest() task.spawn(function() pcall(function() RS.Remotes.CommF_:InvokeServer("AbandonQuest") end) end) end
    LV.E.goTo, LV.E.farmMobs, LV.E.release, LV.E.attack, LV.E.restoreMobs = goTo, farmMobs, release, attack, restoreMobs
    LV.E.questState, LV.E.liveQI, LV.E.npcPosOf, LV.E.findMobs, LV.E.baseName = questState, liveQI, npcPosOf, findMobs, baseName
    LV.E.dist, LV.E.getChar, LV.E.myLevel, LV.E.seaId, LV.E.haveTool, LV.E.abandon = dist, getChar, myLevel, seaId, haveTool, abandonQuest
    Core.farms["Farm Level"] = { want = function() return LV.on end }
    task.spawn(function()
        while alive do
            task.wait(0.1)
            local cur = Core.current and Core.current()
            if LV.on and cur == "Farm Level" then
                LV.owned = true
                local ok, err = pcall(step)
                if not ok then LV.text = "Error: " .. tostring(err) end
            else
                if LV.owned then LV.owned = false; LV.fix = nil; release() end
                LV.text = LV.on and (cur and ("Paused: " .. cur .. " has priority") or "Turned off in Farm Settings > Priorities") or "Off"
            end
        end
    end)
    table.insert(cleanups, function() LV.on = false; release() end)

    -- --------------------------------------------------------------- UI ----
    local nf = addTab("Normal Farm", ICON.flame)
    local B = nf.body
    LV.body = B
    section(B, "Level Farm", 1)
    mkToggle(B, ICON.rocket, "Auto Farm Level", "Takes the right quest for your level, kills the enemies and repeats", 2, false, function(v)
        LV.on = v
        if v then
            LV.fix, LV.hinted, LV.qTries = nil, false, 0
            LV.text = "Starting..."
            notify("Level Farm", "Auto Farm Level is on.", "ok", 2.5)
        else
            LV.owned = false
            release()
            LV.text = "Off"
        end
    end)
    RESET_UI.lvQuest = mkToggle(B, ICON.check, "Auto Take Quest", "Off = only kills the enemies for your level, without taking quests", 3, cfg.lvQuest ~= false, function(v)
        cfg.lvQuest = v; persist()
    end)
    local _, _, stSub = row(B, ICON.gauge, "Status", "Off", 56, 4)
    local _, _, tgSub = row(B, ICON.eye, "Current Target", "--", 56, 5)
    task.spawn(function()
        while alive do
            task.wait(0.4)
            pcall(function()
                stSub.Text = LV.text
                local e = LV.entry
                if e and LV.sea then
                    tgSub.Text = string.format("Lv %s  |  %s  |  %s x%d", tostring(LV.lvl or "?"), SEA_NAME[LV.sea] or "?", e.mob, e.n)
                else
                    tgSub.Text = LV.lvl and ("Lv " .. LV.lvl) or "--"
                end
            end)
        end
    end)
end)()


-- ============================================ Normal Farm: Auto Dough Prince / Auto Bones ====
-- Mesmo motor do Level Farm (voo, Bring Mob, quest so quando nao ha uma ativa), mas mata TODOS os mobs da ilha.
;(function()
    local RS = game:GetService("ReplicatedStorage")
    local Core = getgenv().MoonPremiumCore
    local LV = Core.level
    local E = LV.E
    local B = LV.body
    cfg.dpQuest = (cfg.dpQuest ~= false)
    cfg.bnQuest = (cfg.bnQuest ~= false)

    -- grupo = entradas da tabela de quests (prefixo do nome) + conjunto de mobs + spawns de todos eles
    local function makeGroup(prefix, extra, label, minLv)
        local g = { entries = {}, set = {}, label = label, min = minLv, on = false, text = "Off",
            pseudo = { sp = {}, mob = label, q = prefix, i = 0, npcn = label } }
        for _, e in ipairs(LV.DATA[3] or {}) do
            if string.sub(e.q, 1, #prefix) == prefix then
                g.entries[#g.entries + 1] = e
                g.set[e.mob] = true
                for _, p in ipairs(e.sp) do g.pseudo.sp[#g.pseudo.sp + 1] = p end
            end
        end
        for _, n in ipairs(extra or {}) do g.set[n] = true end
        return g
    end
    local function pickEntry(g, lvl)
        local best
        for _, e in ipairs(g.entries) do if e.lv <= lvl then best = e end end
        return best
    end

    -- um passo do grupo; pre() (opcional) pode assumir o passo (boss) devolvendo true
    local function runGroup(g, autoQuest, pre)
        local char, hrp, hum = E.getChar()
        if not (char and hrp and hum) or hum.Health <= 0 then
            LV.anchor = nil; E.release(); g.text = "Waiting for your character"; return
        end
        local lvl = E.myLevel()
        if not lvl then g.text = "Reading your level..."; return end
        if E.seaId(lvl) ~= 3 then E.release(); g.text = "Go to the Third Sea for " .. g.label; return end
        -- v71: mesmo caso do Level Farm (step() acima) - Dough Prince/Bones/Tiki Outpost (Auto Tyrant) passam por
        -- aqui e travavam pedindo o NPC ligado numa aba diferente, em vez de so ligar. Isso explicava farms/quest
        -- parecendo "travadas do nada" sem nenhum erro visivel.
        if not (cfg.targets and cfg.targets.NPC) then
            cfg.targets = cfg.targets or {}
            cfg.targets.NPC = true
            persist()
        end
        if not E.haveTool() then E.release(); g.text = "No " .. tostring(cfg.tool) .. " found. Pick a weapon in Farm Settings"; return end
        local e = pickEntry(g, lvl)
        if not e then E.release(); g.text = string.format("Level %d is too low for %s (needs %d)", lvl, g.label, g.min); return end
        if hrp.Position.Y <= -500 then LV.leaveSub(); g.text = LV.text; return end
        if pre and pre(g, e) then return end
        local now = os.clock()
        local prefer = { [e.mob] = true }
        local function farm(prefix)
            E.farmMobs(g.set, g.pseudo, g.label, prefer)
            local t = LV.text
            if prefix and (t:find("^Killing") or t:find("^Flying")) then t = prefix .. " - " .. t end
            g.text = t
        end
        Core.farmDbg = string.format("%s | Lv %d | quest %s #%d (%s) | auto quest: %s | StartQuest: %s", g.label, lvl, tostring((E.liveQI(e))),
            tonumber(select(2, E.liveQI(e))) or 0, e.mob, autoQuest and "on" or "off", tostring(LV.res or "-"))
        if not autoQuest then farm(nil); return end
        local qs = E.questState(e)
        if qs then
            LV.qTries, LV.takenAt, LV.blindUntil, LV.tookOk = 0, nil, nil, false
            if qs.done then
                E.release(); g.text = "Quest complete"
                if now - (LV.doneAt or 0) > 1 then LV.doneAt = now; E.abandon() end
                return
            end
            LV.doneAt = nil
            if qs.first and not g.set[qs.first] then          -- quest de outro lugar ficou ativa: limpa para pegar a daqui
                E.release(); g.text = "Another quest is active, clearing it"
                LV.staleAt = LV.staleAt or now
                if now - LV.staleAt > 3 then LV.staleAt = nil; E.abandon() end
                return
            end
            LV.staleAt = nil
            LV.lastActive, LV.lastQ = now, qs
            farm((qs.title ~= "" and qs.title or e.mob) .. " " .. qs.have .. "/" .. qs.need)
            return
        end
        if LV.lastQ and LV.lastActive and now - LV.lastActive < 1.0 and (LV.lastQ.need - LV.lastQ.have) > 1 then
            g.text = "Checking quest..."; return
        end
        LV.lastQ, LV.doneAt = nil, nil
        -- v73: essas 3 farms (Dough Prince/Bones/Tiki Outpost) sao pra matar TODO MUNDO da ilha, nao so o mob da
        -- quest - mas antes, sem quest ativa detectada, E.takeQuest() sempre tomava o personagem (attack(false) +
        -- voa pro NPC da missao) MESMO com mobs vivos do grupo bem na frente, e so voltava a farmar se o StartQuest
        -- realmente "pegasse" (LV.tookOk). Se o jogo nao confirma isso do jeito que o codigo espera pra essas
        -- quests (diferente da Level Farm normal), o personagem fica preso voando pro NPC pra sempre - e por fora
        -- isso e exatamente "so foca no NPC da missao". Agora: se ja tem mob do grupo vivo por perto, farma direto
        -- e nem tenta pegar a quest nesse ciclo (a quest e so um bonus; so vai no NPC quando nao ha nada pra matar).
        -- v145: o Auto Bone voltou a PEGAR a quest (antes nunca pegava com mob vivo perto). Tenta por 15 s a cada 60 s; se o jogo nao confirmar, farma do mesmo jeito.
        if #E.findMobs(g.set, prefer) > 0 then
            if now > (g.takeUntil or 0) then
                if now - (g.lastTake or -1e9) < 60 then
                    farm(nil)
                    g.text = LV.text
                    return
                end
                g.lastTake = now
                g.takeUntil = now + 15
            end
        end
        E.takeQuest(e, function() farm(nil); g.text = g.text .. " (quest not detected, farming anyway)" end)
        g.text = LV.text
    end

    local function register(name, g, step)
        Core.farms[name] = { want = function() return g.on end }
        task.spawn(function()
            while alive do
                task.wait(0.1)
                local cur = Core.current and Core.current()
                if g.on and cur == name then
                    g.owned = true
                    local ok, err = pcall(step)
                    if not ok then g.text = "Error: " .. tostring(err) end
                else
                    if g.owned then g.owned = false; LV.anchor = nil; E.release() end
                    g.text = g.on and (cur and ("Paused: " .. cur .. " has priority") or "Turned off in Farm Settings > Priorities") or "Off"
                end
            end
        end)
        table.insert(cleanups, function() g.on = false; E.release() end)
    end

    -- ------------------------------------------------------------ Dough Prince ----
    local D = makeGroup("CakeQuest", nil, "Dough Prince", 2200)
    local PORTAL = Vector3.new(-2168, 84, -12397)          -- portal da Dimensional Shift
    local function princeAlive()
        local f = workspace:FindFirstChild("Enemies")
        local b = f and f:FindFirstChild("Cake Prince")
        local h = b and b:FindFirstChildOfClass("Humanoid")
        local r = b and b:FindFirstChild("HumanoidRootPart")
        if h and r and h.Health > 0 then return b, r end
    end
    local function hasChalice()
        for _, c in ipairs({ LP.Character, LP:FindFirstChild("Backpack") }) do
            if c and c:FindFirstChild("Sweet Chalice") then return true end
        end
        return (Core.inv and Core.inv.count("Sweet Chalice") > 0) or false
    end
    local function doughPre(g, e)
        local now = os.clock()
        local boss, r = princeAlive()
        if not boss then
            if now - (D.sumAt or 0) > 5 then
                D.sumAt = now
                if hasChalice() then
                    D.sumRes = "You have the Sweet Chalice (the game would summon the Dough King instead)"
                else
                    task.spawn(function()
                        local function call() return pcall(function() return RS.Remotes.CommF_:InvokeServer("CakePrinceSpawner") end) end
                        local ok, res = call()
                        if ok and type(res) == "string" and string.find(res, "open the portal now", 1, true) then task.wait(0.3); ok, res = call() end
                        D.sumRes = ok and tostring(res) or ("error: " .. tostring(res))
                    end)
                end
            end
            Core.farmDbg = nil
            return false
        end
        Core.farmDbg = "Dough Prince boss | summon: " .. tostring(D.sumRes or "-")
        -- v71: mesma correcao do NPC acima, pro BOSS (precisa estar ligado pra atacar o Cake Prince)
        if not (cfg.targets and cfg.targets.BOSS) then
            cfg.targets = cfg.targets or {}
            cfg.targets.BOSS = true
            persist()
        end
        if LP:GetAttribute("CurrentLocation") ~= "Dimensional Shift" then
            E.attack(false); E.restoreMobs()
            if E.goTo(PORTAL, 4) then LV.hold, LV.fly = nil, nil end   -- chegou: solta para o portal teleportar
            g.text = "Dough Prince appeared: entering the Dimensional Shift"
            return true
        end
        local H = math.clamp(tonumber(cfg.height) or 15, 5, 60)
        local stand = r.Position + Vector3.new(0, H, 0)
        E.restoreMobs()
        if E.goTo(stand, 8, CFrame.new(stand) * CFrame.Angles(0, 0, 0)) then
            E.attack(true); g.text = "Killing Dough Prince"
        else
            g.text = "Flying to Dough Prince"
        end
        return true
    end
    register("Cake Prince", D, function() runGroup(D, cfg.dpQuest, doughPre) end)

    -- ------------------------------------------------------------------ Bones ----
    local Bn = makeGroup("HauntedQuest", { "Possessed Mummy" }, "Bones", 1975)
    register("Farm Bones", Bn, function() runGroup(Bn, cfg.bnQuest, nil) end)

    Core.gtext = { ["Cake Prince"] = D, ["Farm Bones"] = Bn }

    -- ----------------------------------------- grupos extras usados pelos modulos do Moon antigo ----
    -- Tyrant of the Skies (ilha Tiki) e Dough King (Cake Land + cacau) usam o mesmo motor de farm (voo, Bring Mob, quest).
    -- Quem chama (Core.groupStep) e o dono da vez no arbitro; quando para de chamar, o motor e solto sozinho.
    local Tk = makeGroup("TikiQuest", nil, "Tiki Outpost", 2450)
    local Co = makeGroup("ChocQuest1", nil, "Conjured Cocoa", 2300)       -- so Cocoa Warrior / Chocolate Bar Battler (os que dropam o cacau)
    Core.groups = { Dough = D, Bones = Bn, Tiki = Tk, Cocoa = Co }
    function Core.groupStep(g, autoQuest, pre)
        g.lastRun, g.ext = os.clock(), true
        g.owned = true
        local ok, err = pcall(runGroup, g, autoQuest and true or false, pre)
        if not ok then g.text = "Error: " .. tostring(err) end
        return g.text
    end
    task.spawn(function()
        while alive do
            task.wait(0.4)
            for _, g in pairs(Core.groups) do
                if g.ext and g.owned and not g.on and os.clock() - (g.lastRun or 0) > 0.8 then
                    g.ext, g.owned = false, false
                    LV.anchor = nil
                    pcall(E.release)
                end
            end
        end
    end)

    -- --------------------------------------------------------------------- UI ----
    local function groupUI(base, title, g, farmTitle, farmSub, qTitle, qSub, key, extra)
        section(B, title, base)
        mkToggle(B, ICON.rocket, farmTitle, farmSub, base + 1, false, function(v)
            g.on = v
            if v then
                LV.anchor = nil; LV.qTries = 0
                g.text = "Starting..."
                notify(title, farmTitle .. " is on.", "ok", 2.5)
            else
                g.owned = false; E.release(); g.text = "Off"
            end
        end)
        mkToggle(B, ICON.check, qTitle, qSub, base + 2, cfg[key] ~= false, function(v) cfg[key] = v; persist() end)
        local _, _, st = row(B, ICON.gauge, "Status", "Off", 56, base + 3)
        task.spawn(function()
            while alive do
                task.wait(0.4)
                pcall(function() st.Text = g.text end)
            end
        end)
    end
    groupUI(10, "Auto Dough Prince", D, "Auto Farm Dough Prince", "Kills every Cake Land enemy, summons the boss and kills it first when it spawns",
        "Auto Quest Dough Prince", "Takes the quest only when you have none active. Off = just kills the enemies", "dpQuest")
    groupUI(20, "Auto Bones", Bn, "Auto Farm Bones", "Kills every Haunted Castle enemy to collect Bones",
        "Auto Quest Bones", "Takes the quest only when you have none active. Off = just kills the enemies", "bnQuest")
end)()


-- ============================================ Inventario (leitura direta dos dados do jogo) ====
-- Metodo do Moon antigo (Fully Vulcan): 1) Net "GetAllItemValues" + ReplicatedStorage.ItemConfig (nomes reais)
-- 2) plano B: store do cliente achado pelo getgc 3) plano C: CommF_ getInventory. Frutas guardadas: getInventoryFruits.
;(function()
    local RS = game:GetService("ReplicatedStorage")
    local Core = getgenv().MoonPremiumCore
    local I = { map = {}, list = {}, total = 0, kinds = 0, state = "not started", at = 0, fruits = {}, fruitsAt = -100, fruitsState = "not read", busy = false }
    Core.inv = I
    local function try(f) local ok, v = pcall(f); if ok then return v end end
    local function norm(s) return "#" .. string.lower((string.gsub(tostring(s), "[^%w]", ""))) end
    local cfgMod, netMod, store, keys

    local function finish(byName, how)
        local m, list, total = {}, {}, 0
        for nm, q in pairs(byName) do
            m[nm] = q; m[norm(nm)] = math.max(m[norm(nm)] or 0, q)
            list[#list + 1] = { nm, q }; total = total + q
        end
        table.sort(list, function(a, b) if a[2] ~= b[2] then return a[2] > b[2] end return a[1] < b[1] end)
        I.map, I.list, I.total, I.kinds = m, list, total, #list
        I.state = string.format("%d item types read (%s)", #list, how)
    end
    local function viaRemote()
        if not netMod then
            local mods = RS:FindFirstChild("Modules"); local nf = mods and mods:FindFirstChild("Net")
            netMod = nf and try(function() return require(nf) end)
        end
        if not cfgMod then
            local ms = RS:FindFirstChild("ItemConfig"); cfgMod = ms and try(function() return require(ms) end)
        end
        if not (netMod and cfgMod) then return false, "Net/ItemConfig missing" end
        local ok, res = pcall(function() return netMod:RemoteFunction("GetAllItemValues"):InvokeServer() end)
        if not ok or type(res) ~= "table" then return false, "GetAllItemValues failed: " .. tostring(res) end
        local by, rows = {}, 0
        for _, r in next, res do
            rows = rows + 1
            local k = tostring(r.ItemId) .. "_" .. tostring(r.NetworkedUID)
            by[k] = by[k] or { id = r.ItemId, at = {} }
            if r.Value ~= nil then by[k].at[r.Key] = r.Value end
        end
        local out, n = {}, 0
        for _, it in next, by do
            local q = tonumber(it.at.Quantity)           -- so Quantity conta (IsOwned tambem vale p/ receitas = falso positivo)
            if q and q > 0 then
                local okc, conf = pcall(function() return cfgMod.match(it.id):unwrap() end)
                local name
                if okc and conf then
                    local dn = conf.Display and conf.Display.Name
                    local dl = conf.Index and conf.Index.DebugLabel
                    local sk = conf.Index and conf.Index.StorageKey
                    name = dn or (dl and (tostring(dl):match("^(.-)%s*%[") or tostring(dl))) or sk
                end
                name = tostring(name or ("ItemId_" .. tostring(it.id)))
                out[name] = (out[name] or 0) + q; n = n + 1
            end
        end
        if n == 0 then return false, "GetAllItemValues returned " .. rows .. " rows but no item matched" end
        finish(out, "GetAllItemValues")
        return true
    end
    local function viaGC()
        if not getgc then return false, "getgc unavailable" end
        if not (store and keys) and os.clock() - (I.gcAt or -99) > 20 then
            I.gcAt = os.clock()
            for _, v in ipairs(getgc(true)) do
                if type(v) == "table" then
                    if not keys and try(function() return rawget(v, "QUANTITY") end) ~= nil and try(function() return rawget(v, "MASTERY") end) ~= nil then keys = v end
                    if not store and type(try(function() return v.GetItems end)) == "function" and type(try(function() return v.ReadItem end)) == "function" then store = v end
                    if store and keys then break end
                end
            end
        end
        if not (store and keys and cfgMod) then return false, "store/keys/config not found" end
        local out, n = {}, 0
        local ok, err = pcall(function()
            local a, b, c = store:GetItems(keys.QUANTITY)
            local function each(fn)
                if type(a) == "function" then for k, v in a, b, c do fn(k, v) end
                elseif type(a) == "table" then for k, v in pairs(a) do fn(k, v) end end
            end
            each(function(_, it)
                local q = type(it) == "table" and tonumber(it.Value)
                if q and q > 0 then
                    local okc, conf = pcall(function() return cfgMod.match(it.ItemId):unwrap() end)
                    local name = okc and conf and ((conf.Display and conf.Display.Name) or (conf.Index and conf.Index.StorageKey)) or ("ItemId_" .. tostring(it.ItemId))
                    out[tostring(name)] = (out[tostring(name)] or 0) + q; n = n + 1
                end
            end)
        end)
        if not ok then return false, "read error: " .. tostring(err) end
        if n == 0 then return false, "game store empty" end
        finish(out, "game store (getgc)")
        return true
    end
    local function viaLegacy()
        local ok, inv = pcall(function() return RS.Remotes.CommF_:InvokeServer("getInventory") end)
        if not ok or type(inv) ~= "table" then return false, "getInventory: " .. tostring(inv) end
        local out, n = {}, 0
        local function cnt(it)
            for _, k in ipairs({ "Count", "Amount", "Quantity", "Qty", "Stack", "Value", "count", "amount", "quantity" }) do
                if tonumber(it[k]) then return tonumber(it[k]) end
            end
            return 1
        end
        local function walk(t, d)
            for key, it in pairs(t) do
                local nm, c
                if type(it) == "table" then
                    local v = it.Name or it.name or it.ItemName or it.Item
                    if v ~= nil and type(v) ~= "table" then nm, c = tostring(v), cnt(it) elseif d < 4 then walk(it, d + 1) end
                elseif type(it) == "number" and type(key) == "string" then nm, c = key, it
                elseif type(it) == "string" and type(key) == "number" then nm, c = it, 1 end
                if nm then out[nm] = (out[nm] or 0) + c; n = n + 1 end
            end
        end
        walk(inv, 0)
        if n == 0 then return false, "getInventory returned nothing" end
        finish(out, "getInventory (remote)")
        return true
    end
    function I.refresh()
        if I.busy or os.clock() - I.at < 5 then return end
        I.busy, I.at = true, os.clock()
        task.spawn(function()
            local errs = {}
            local ok, e1 = viaRemote()
            if not ok then
                errs[#errs + 1] = e1
                local ok2, e2 = viaGC()
                if not ok2 then
                    errs[#errs + 1] = e2
                    local ok3, e3 = viaLegacy()
                    if not ok3 then errs[#errs + 1] = e3; I.state = "could not read: " .. table.concat(errs, " | ") end
                end
            end
            I.busy = false
        end)
    end
    function I.count(name)
        local nk = norm(name)
        return I.map[name] or I.map[nk] or 0
    end
    -- frutas guardadas (getInventoryFruits; aceita lista de tabelas {Name=..}, nomes na chave ou strings)
    function I.refreshFruits()
        if os.clock() - I.fruitsAt < 10 then return end
        I.fruitsAt = os.clock()
        task.spawn(function()
            local ok, inv = pcall(function() return RS.Remotes.CommF_:InvokeServer("getInventoryFruits") end)
            if not ok or type(inv) ~= "table" then I.fruitsState = "could not read: " .. tostring(inv); return end
            local cnt, order = {}, {}
            local function add(nm, c)
                nm = tostring(nm):gsub("%-.*", "")
                if not cnt[nm] then cnt[nm] = 0; order[#order + 1] = nm end
                cnt[nm] = cnt[nm] + (c or 1)
            end
            local function walk(t, d)
                for k, it in pairs(t) do
                    if type(it) == "table" then
                        local nm = it.Name or it.name or it.ItemName
                        if nm ~= nil and type(nm) ~= "table" then add(nm, tonumber(it.Count or it.Amount or it.Quantity) or 1)
                        elseif type(k) == "string" and d >= 1 then add(k, 1)
                        elseif d < 3 then walk(it, d + 1) end
                    elseif type(it) == "string" and type(k) == "number" then add(it, 1) end
                end
            end
            walk(inv, 0)
            table.sort(order)
            local out = {}
            for _, nm in ipairs(order) do out[#out + 1] = { nm, cnt[nm] } end
            I.fruits, I.fruitsState = out, #out .. " stored fruit type(s)"
        end)
    end
    task.spawn(function() while Core and getgenv().MoonPremiumCore == Core do I.refresh(); I.refreshFruits(); task.wait(5) end end)
end)()


-- ================================================== aba Status Server/Script ====
;(function()
    local RS = game:GetService("ReplicatedStorage")
    local StatsS = game:GetService("Stats")
    local Core = getgenv().MoonPremiumCore
    local st = addTab("Status Server/Script", ICON.gauge)
    local B = st.body
    local scriptStart = os.time()
    local firstRun = scriptStart
    pcall(function()
        local fn = "MoonHub_Premium_first.txt"
        if isfile and readfile and isfile(fn) then
            local n = tonumber(readfile(fn)); if n and n > 1e9 and n <= scriptStart then firstRun = n end
        elseif writefile then writefile(fn, tostring(scriptStart)) end
    end)
    local function fmt(sec)
        sec = math.max(0, math.floor(tonumber(sec) or 0))
        local d, h, m, s = math.floor(sec / 86400), math.floor(sec % 86400 / 3600), math.floor(sec % 3600 / 60), sec % 60
        if d > 0 then return string.format("%dd %dh %dm %ds", d, h, m, s) end
        if h > 0 then return string.format("%dh %dm %ds", h, m, s) end
        if m > 0 then return string.format("%dm %ds", m, s) end
        return s .. "s"
    end
    local function money(n)
        local s = tostring(math.floor(tonumber(n) or 0))
        return (s:reverse():gsub("(%d%d%d)", "%1,"):reverse():gsub("^,", ""))
    end
    local SEAS = { [2753915549] = "First Sea", [85211729168715] = "First Sea", [4442272183] = "Second Sea", [79091703265657] = "Second Sea", [7449423635] = "Third Sea", [100117331123089] = "Third Sea" }
    local fps, last = 60, os.clock()
    table.insert(conns, RunService.Heartbeat:Connect(function()
        local now = os.clock()
        local dt = now - last; last = now
        if dt > 0 then fps = fps + (1 / dt - fps) * 0.05 end
    end))
    local function infoRow(icon, title, order, h)
        local _, _, ss = row(B, icon, title, "--", h or 56, order)
        return ss
    end
    local function bigRow(icon, title, order, h)
        local r, tt, ss = row(B, icon, title, "--", h, order)
        local tx = ORG.of[r].tx
        tt.Position = UDim2.fromOffset(tx, 10); tt.Size = UDim2.new(1, -(tx + 16), 0, 16)
        ss.Position = UDim2.fromOffset(tx, 30); ss.Size = UDim2.new(1, -(tx + 16), 0, h - 36)
        ss.TextWrapped = true; ss.TextYAlignment = Enum.TextYAlignment.Top
        ss.TextTruncate = Enum.TextTruncate.None
        return ss, r
    end

    section(B, "Server", 1)
    local sUp = infoRow(ICON.clock, "Server Uptime", 2)
    local sPl = infoRow(ICON.user, "Players", 3)
    local sNet = infoRow(ICON.gauge, "Ping / FPS", 4)
    local sSea = infoRow(ICON.eye, "Sea / In-game time", 5)
    do
        local r, tt, ss = row(B, ICON.keyboard, "Server Job ID", tostring(game.JobId ~= "" and game.JobId or "Studio"), 56, 6)
        ORG.R(r, 98)
        local cb = smallButton(r, "Copy", 66, UDim2.new(1, -80, 0.5, -14), true)
        cb.MouseButton1Click:Connect(function()
            if setclipboard then pcall(setclipboard, tostring(game.JobId)); notify("Copied", "Server Job ID copied.", "ok", 2) end
        end)
    end

    section(B, "Script", 40)
    local cUp = infoRow(ICON.hourglass, "Script Uptime", 41)
    local cFirst = infoRow(ICON.clock, "Time Since First Run", 42)
    local cExec = infoRow(ICON.settings, "Executor", 43)
    local cLv = infoRow(ICON.rocket, "Level Farm", 44)
    local cDbg = bigRow(ICON.eye, "Level Farm Debug", 45, 92)
    local cAtk = bigRow(ICON.flame, "Attack Engine", 46, 104)

    section(B, "Fruit Dealers", 60)
    local nSt, mSt
    local nTimer = infoRow(ICON.clock, "Normal Dealer Restock", 61)
    nSt = bigRow(ICON.gift or ICON.check, "Normal Dealer Stock", 62, 110)
    local mTimer = infoRow(ICON.clock, "Mirage Dealer Restock", 63)
    mSt = bigRow(ICON.gift or ICON.check, "Mirage Dealer Stock", 64, 110)
    local mirage = infoRow(ICON.eye, "Mirage Island / Moon", 65)


    -- ---------------------------------------------------------------- Player / Sessao / Farm ----
    local R, U = {}, {}
    local function addRow(key, icon, title, order, fn, h)
        R[key] = infoRow(icon, title, order, h); U[key] = fn
    end
    local function dv(name)
        local d = LP:FindFirstChild("Data"); local v = d and d:FindFirstChild(name)
        return v and v.Value
    end
    local function statLv(n)
        local d = LP:FindFirstChild("Data"); local s = d and d:FindFirstChild("Stats")
        local f = s and s:FindFirstChild(n); local l = f and f:FindFirstChild("Level")
        return l and l.Value or 0
    end
    local function bounty()
        local l = LP:FindFirstChild("leaderstats"); local b = l and l:FindFirstChild("Bounty/Honor")
        return b and b.Value or 0
    end
    local snap = { beli = dv("Beli") or 0, frag = dv("Fragments") or 0, bounty = bounty(), lvl = dv("Level") or 0, exp = dv("Exp") or 0, t = os.time() }
    local function signed(n) return (n >= 0 and "+" or "-") .. money(math.abs(n)) end
    local function perHour(n) local h = math.max(1, os.time() - snap.t) / 3600; return signed(n / h) .. "/h" end

    section(B, "Player", 10)
    addRow("lvl", ICON.rocket, "Level / Exp", 11, function() return string.format("Lv %s  |  Exp %s", tostring(dv("Level") or "?"), money(dv("Exp"))) end)
    addRow("beli", ICON.gauge, "Beli / Fragments", 12, function() return string.format("$%s  |  %s fragments", money(dv("Beli")), money(dv("Fragments"))) end)
    addRow("bounty", ICON.crown, "Bounty / Honor", 13, function() return money(bounty()) end)
    addRow("race", ICON.user, "Race / Subclass", 14, function() return string.format("%s  |  %s", tostring(dv("Race") or "?"), tostring(dv("Subclass") or "none")) end)
    addRow("fruit", ICON.flame, "Devil Fruit", 15, function()
        local f = tostring(dv("DevilFruit") or "")
        local name = f:gsub(" @.*", "")
        local dt = f:match("@DragonType=(%w+)")
        return (name == "" and "none" or name) .. (dt and ("  (" .. dt .. ")") or "")
    end)
    addRow("stats", ICON.settings, "Stats", 16, function()
        return string.format("Melee %d  |  Defense %d  |  Sword %d  |  Gun %d  |  Fruit %d", statLv("Melee"), statLv("Defense"), statLv("Sword"), statLv("Gun"), statLv("Demon Fruit"))
    end)
    addRow("loc", ICON.eye, "Location", 17, function() return tostring(LP:GetAttribute("CurrentLocation") or "?") end)
    addRow("misc", ICON.hourglass, "Fruit Cap / Sea Events / Points", 18, function()
        return string.format("%s  |  %s cleared  |  %s points", tostring(dv("FruitCap") or "?"), tostring(dv("SeaEventsCleared") or "?"), tostring(dv("Points") or "?"))
    end)
    addRow("ken", ICON.eye, "Observation Haki (Ken)", 19, function()
        return string.format("%s  |  dodges %s / %s", LP:GetAttribute("KenActive") and "active" or "off", tostring(LP:GetAttribute("KenDodgesLeft") or "?"), tostring(LP:GetAttribute("KenMaxDodges") or "?"))
    end)
    addRow("boost", ICON.clock, "EXP Boost / Safe Zone", 20, function()
        return string.format("x%s  |  %s", tostring(LP:GetAttribute("ExpBoost") or 0), LP:GetAttribute("InSafeZone") and "in safe zone" or (LP:GetAttribute("InDangerZone") and "DANGER zone" or "open world"))
    end)

    section(B, "This Session", 24)
    addRow("sLvl", ICON.rocket, "Levels / Exp gained", 25, function()
        return string.format("+%d levels  |  %s exp  (%s)", (dv("Level") or 0) - snap.lvl, money(math.max(0, (dv("Exp") or 0) - snap.exp)), perHour(math.max(0, (dv("Exp") or 0) - snap.exp)))
    end)
    addRow("sBeli", ICON.gauge, "Beli gained", 26, function()
        local d = (dv("Beli") or 0) - snap.beli; return signed(d) .. "  (" .. perHour(d) .. ")"
    end)
    addRow("sFrag", ICON.gauge, "Fragments gained", 27, function()
        local d = (dv("Fragments") or 0) - snap.frag; return signed(d) .. "  (" .. perHour(d) .. ")"
    end)
    addRow("sBounty", ICON.crown, "Bounty gained", 28, function() return signed(bounty() - snap.bounty) end)
    addRow("farm", ICON.rocket, "Active Farm", 29, function()
        local cur = Core and Core.current and Core.current()
        if not cur then return "none (all farms off)" end
        local txt = ""
        if cur == "Farm Level" and Core.level then txt = tostring(Core.level.text)
        elseif Core.gtext and Core.gtext[cur] then txt = tostring(Core.gtext[cur].text) end
        return cur .. "  |  " .. txt
    end)

    section(B, "More Server Info", 30)
    addRow("mem", ICON.gauge, "Memory Usage", 31, function()
        local mb = 0; pcall(function() mb = StatsS:GetTotalMemoryUsageMb() end)
        return string.format("%d MB", mb)
    end)
    addRow("ids", ICON.keyboard, "Place ID / Version", 32, function() return string.format("%s  |  v%s", tostring(game.PlaceId), tostring(game.PlaceVersion)) end)
    addRow("sess", ICON.clock, "Time Played This Session", 33, function() return fmt(os.time() - snap.t) end)
    task.spawn(function()
        while alive do
            for k, fn in pairs(U) do
                pcall(function() R[k].Text = tostring(fn()) end)
            end
            task.wait(1)
        end
    end)


    -- ------------------------------------------------------------------ Inventory ----
    do
        local I = Core and Core.inv
        local KEY = { "Sweet Chalice", "God's Chalice", "Fist of Darkness", "Hallow Essence", "Conjured Cocoa", "Bones", "Volcanic Magnet", "Scrap Metal", "Ember", "Mirror Fractal", "Valkyrie Helm", "Dragon Egg", "Dinosaur Bones", "Mutant Tooth", "Fool's Gold", "Leather", "Angel Wings", "Vampire Fang", "Magma Ore", "Dragon Scale" }
        section(B, "Inventory", 70)
        local iState = infoRow(ICON.settings, "Inventory Reader", 71)
        local iTot = infoRow(ICON.gauge, "Items", 72)
        local iKey, iKeyRow = bigRow(ICON.check, "Key Items", 73, 90)
        local iFr, iFrRow = bigRow(ICON.flame, "Stored Fruits", 74, 70)
        local iAll, iAllRow = bigRow(ICON.eye, "All Items (top 40 by amount)", 75, 120)
        local iTool, iToolRow = bigRow(ICON.rocket, "Backpack / Hand", 76, 70)
        local function fit(rowFrame, label, lines)
            rowFrame.Size = UDim2.new(1, 0, 0, math.clamp(46 + lines * 14, 70, 700))
            local rc = ORG.of[rowFrame]
            label.Size = UDim2.new(1, -((rc and rc.tx or 54) + 16), 0, math.max(14, lines * 14))
        end
        task.spawn(function()
            while alive do
                pcall(function()
                    if not I then iState.Text = "module missing"; return end
                    I.refresh(); I.refreshFruits()
                    iState.Text = tostring(I.state)
                    iTot.Text = string.format("%d item types  |  %s total amount", I.kinds, money(I.total))
                    local keyOut = {}
                    for _, n in ipairs(KEY) do
                        local c = I.count(n)
                        if c > 0 then keyOut[#keyOut + 1] = n .. " x" .. money(c) end
                    end
                    iKey.Text = #keyOut > 0 and table.concat(keyOut, "\n") or "none of the tracked items"
                    fit(iKeyRow, iKey, math.max(1, #keyOut))
                    local fr = {}
                    for _, f in ipairs(I.fruits) do fr[#fr + 1] = f[1] .. (f[2] > 1 and (" x" .. f[2]) or "") end
                    iFr.Text = #fr > 0 and table.concat(fr, "\n") or ("none  (" .. tostring(I.fruitsState) .. ")")
                    fit(iFrRow, iFr, math.max(1, #fr))
                    local all = {}
                    for i = 1, math.min(40, #I.list) do all[#all + 1] = I.list[i][1] .. "  x" .. money(I.list[i][2]) end
                    iAll.Text = #all > 0 and table.concat(all, "\n") or "empty / not read yet"
                    fit(iAllRow, iAll, math.max(1, #all))
                    local tools, held = {}, LP.Character and LP.Character:FindFirstChildOfClass("Tool")
                    if held then tools[#tools + 1] = "[in hand] " .. held.Name .. " (" .. tostring(held.ToolTip) .. ")" end
                    local bp = LP:FindFirstChild("Backpack")
                    if bp then for _, t in ipairs(bp:GetChildren()) do if t:IsA("Tool") then tools[#tools + 1] = t.Name .. " (" .. tostring(t.ToolTip) .. ")" end end end
                    iTool.Text = #tools > 0 and table.concat(tools, "\n") or "empty"
                    fit(iToolRow, iTool, math.max(1, #tools))
                end)
                task.wait(2)
            end
        end)
    end

    -- executor
    local exec = "Unknown"
    pcall(function() if identifyexecutor then local a, b = identifyexecutor(); exec = tostring(a) .. (b and (" " .. tostring(b)) or "") end end)

    -- estoque das lojas (GetFruits normal / GetFruits true = Mirage), atualizado a cada 30s e quando o timer zera
    local stock = { n = nil, m = nil, at = -100, busy = false }
    local function stockText(res)
        if type(res) ~= "table" then return nil end
        local out = {}
        for _, v in pairs(res) do
            if type(v) == "table" and v.Name and (v.OnSale == true or v.InStock == true) then
                out[#out + 1] = (tostring(v.Name):gsub("%-.*", "")) .. "  $" .. money(v.Price)
            end
        end
        table.sort(out)
        return #out > 0 and table.concat(out, "\n") or "No fruits in stock"
    end
    local function refreshStock()
        if stock.busy then return end
        stock.busy, stock.at = true, os.clock()
        task.spawn(function()
            local ok1, r1 = pcall(function() return RS.Remotes.CommF_:InvokeServer("GetFruits") end)
            local ok2, r2 = pcall(function() return RS.Remotes.CommF_:InvokeServer("GetFruits", true) end)
            stock.n = ok1 and stockText(r1) or "Could not read the stock"
            stock.m = ok2 and stockText(r2) or "Unavailable (the Mirage Dealer is not open)"
            stock.busy = false
        end)
    end
    local MOON_FULL = "9709149431"
    task.spawn(function()
        while alive do
            pcall(function()
                local now = os.time()
                sUp.Text = fmt(workspace.DistributedGameTime)
                sPl.Text = string.format("%d / %d", #Players:GetPlayers(), Players.MaxPlayers)
                local ping = 0
                pcall(function() ping = LP:GetNetworkPing() * 1000 end)
                sNet.Text = string.format("%d ms  |  %d FPS", ping, fps)
                local clock = Lighting:GetMinutesAfterMidnight()
                sSea.Text = string.format("%s  |  %02d:%02d", SEAS[game.PlaceId] or ("PlaceId " .. tostring(game.PlaceId)), math.floor(clock / 60) % 24, math.floor(clock % 60))
                cUp.Text = fmt(now - scriptStart)
                cFirst.Text = fmt(now - firstRun)
                cExec.Text = exec
                local LVm = Core and Core.level
                cLv.Text = LVm and ((LVm.on and "ON" or "OFF") .. "  |  " .. tostring(LVm.text)) or "--"
                cDbg.Text = (LVm and tostring(LVm.dbg or "Turn on Auto Farm Level to see the details") or "--") .. (Core and Core.farmDbg and ("\n" .. Core.farmDbg) or "")
                local net = Core and Core.net
                local char = LP.Character
                local tool = char and char:FindFirstChildOfClass("Tool")
                cAtk.Text = string.format("Net: %s\nTool: %s  |  Method: %s  |  Attacking: %s", net and (net.ready and "ready" or tostring(net.err)) or "--",
                    tool and (tool.Name .. " [" .. tostring(tool.ToolTip) .. "]") or "none", tostring(cfg.method), (Core and Core.attacking) and "yes" or "no" .. "\nWhy: " .. tostring(Core and Core.why or "--") .. "\nAnti-stall level: " .. tostring(Core and Core.wd and Core.wd.lvl or 0) .. "  |  Game M1 fallback: " .. ((Core and Core.wd) and "armed" or "--"))
                local r1, r2 = 14400 - now % 14400, 7200 - now % 7200
                nTimer.Text = fmt(r1)
                mTimer.Text = fmt(r2)
                if os.clock() - stock.at > 30 or r1 > 14395 or r2 > 7195 then if os.clock() - stock.at > 5 then refreshStock() end end
                nSt.Text = stock.n or "Loading..."
                mSt.Text = stock.m or "Loading..."
                local map = workspace:FindFirstChild("Map")
                local mi = map and map:FindFirstChild("MirageIsland")
                local sky = Lighting:FindFirstChildOfClass("Sky")
                local moon = sky and tostring(sky.MoonTextureId) or ""
                mirage.Text = (mi and "Mirage Island: SPAWNED" or "Mirage Island: not spawned") .. "  |  " .. (string.find(moon, MOON_FULL, 1, true) and "Full Moon" or "Moon: not full")
            end)
            task.wait(0.5)
        end
    end)
end)()


-- ================================================================ aba Multi Account ====
-- "Moon Sync" - sincroniza varias contas que estao no MESMO servidor (igual ao recurso "Night Continuity"
-- de outro script, que a gente viu em video): cada conta que roda o Moon Hub avisa pra todo mundo (via
-- Attribute no proprio Player, que o Roblox ja replica de graca pra todo cliente - sem precisar de site/backend
-- proprio nem de codigo digitado), aparece numa lista pros outros, pede/aceita sincronia (com a animacao das
-- fotos dos dois perfis se juntando), e depois disso as contas sincronizadas EVITAM feder trabalho em cima do
-- mesmo mob comum quando estao fazendo a mesma farm por perto (nao duplica, nao copia a config uma da outra).
-- Importante: so funciona entre contas no MESMO servidor (nao tem como "colar um codigo" numa aba de OUTRO
-- servidor sem um site/backend rodando 24/7 pra guardar isso, que eu nao tenho como hospedar aqui).
local MoonSync = { synced = {}, pendingOut = nil, pendingOutAt = 0, pendingIncoming = {} }
getgenv().MoonHubSync = MoonSync
;(function()
    local tab = addTab("Multi Account", ICON.users)
    local B = tab.body
    local myId = LP.UserId
    local THUMB = Enum.ThumbnailType.HeadShot
    local THUMBSZ = Enum.ThumbnailSize.Size180x180
    local function thumbOf(uid)
        local ok, img = pcall(function() return Players:GetUserThumbnailAsync(uid, THUMB, THUMBSZ) end)
        return ok and img or "rbxasset://textures/ui/GuiImagePlaceholder.png"
    end
    local function isSynced(uid) return MoonSync.synced[uid] ~= nil end
    MoonSync.isSynced = isSynced
    function MoonSync.claim(m)
        pcall(function() m:SetAttribute("MHClaim", myId) end)
    end

    -- --------------------------------------------------- status/presenca (replica sozinho, sem servidor nenhum) ----
    local SEAS = { [2753915549] = "First Sea", [85211729168715] = "First Sea", [4442272183] = "Second Sea", [79091703265657] = "Second Sea", [7449423635] = "Third Sea", [100117331123089] = "Third Sea" }
    local function mySea() return SEAS[game.PlaceId] or "Sea ?" end
    local function myLevel()
        local d = LP:FindFirstChild("Data"); local l = d and d:FindFirstChild("Level")
        return (l and tonumber(l.Value)) or 0
    end
    local function myActivity()
        local Core = getgenv().MoonPremiumCore
        if Core and Core.attacking then return (tostring(cfg.tool or "Farm")) end
        return "Idle"
    end
    local function broadcastStatus()
        pcall(function()
            LP:SetAttribute("MHPresence", true)
            LP:SetAttribute("MHStatus", HttpService:JSONEncode({ lv = myLevel(), sea = mySea(), act = myActivity() }))
        end)
    end
    broadcastStatus()
    task.spawn(function()
        while alive do
            pcall(broadcastStatus)
            task.wait(3)
        end
    end)

    -- --------------------------------------------------- animacao de sincronia (fotos se juntando + certinho) ----
    local function playSyncAnim(otherId, otherName)
        pcall(function()
            local ov = new("Frame", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, ZIndex = 50 }, gui)
            local dim = new("Frame", { Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.new(0, 0, 0), BackgroundTransparency = 1, ZIndex = 50 }, ov)
            tween(dim, 0.25, { BackgroundTransparency = 0.55 })
            local a1 = new("ImageLabel", { Size = UDim2.fromOffset(84, 84), AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0.5, -34, 0.5, 0), Image = thumbOf(myId), BackgroundColor3 = Color3.fromRGB(26, 27, 33), ZIndex = 51 }, ov)
            corner(a1, 42); local s1 = stroke(a1, C.ok, 2.5, 0)
            local a2 = new("ImageLabel", { Size = UDim2.fromOffset(84, 84), AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0.5, 34, 0.5, 0), Image = thumbOf(otherId), BackgroundColor3 = Color3.fromRGB(26, 27, 33), ZIndex = 51 }, ov)
            corner(a2, 42); local s2 = stroke(a2, C.ok, 2.5, 0)
            a1.Position = UDim2.new(0.5, -120, 0.5, 0); a2.Position = UDim2.new(0.5, 120, 0.5, 0)
            tween(a1, 0.5, { Position = UDim2.new(0.5, -34, 0.5, 0) }, Enum.EasingStyle.Back)
            tween(a2, 0.5, { Position = UDim2.new(0.5, 34, 0.5, 0) }, Enum.EasingStyle.Back)
            local badge = new("Frame", { Size = UDim2.fromOffset(28, 28), AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0.5, 0, 0.5, 40), BackgroundColor3 = C.ok, BackgroundTransparency = 1 }, ov)
            corner(badge, 14)
            local chk = new("ImageLabel", { Size = UDim2.fromOffset(16, 16), AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Image = ICON.check, ImageColor3 = C.white, ImageTransparency = 1, ZIndex = 52 }, badge)
            local txt = new("TextLabel", { AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 0.5, 58), Size = UDim2.new(0, 320, 0, 44), BackgroundTransparency = 1, Text = "Moon Sync\nSincronizado com " .. otherName, Font = Enum.Font.GothamBold, TextSize = 14, TextColor3 = C.white, TextTransparency = 1, RichText = false, TextWrapped = true }, ov)
            task.delay(0.35, function()
                tween(badge, 0.25, { BackgroundTransparency = 0 })
                tween(chk, 0.25, { ImageTransparency = 0 })
                tween(txt, 0.3, { TextTransparency = 0 })
            end)
            task.delay(3.2, function()
                tween(ov, 0.4, {}); tween(dim, 0.35, { BackgroundTransparency = 1 })
                tween(a1, 0.3, { ImageTransparency = 1 }); tween(a2, 0.3, { ImageTransparency = 1 })
                tween(txt, 0.3, { TextTransparency = 1 }); tween(badge, 0.3, { BackgroundTransparency = 1 })
                tween(chk, 0.3, { ImageTransparency = 1 })
                tween(s1, 0.3, { Transparency = 1 }); tween(s2, 0.3, { Transparency = 1 })
                task.delay(0.45, function() ov:Destroy() end)
            end)
        end)
    end
    -- v93: exposta pra outros modulos (ex: Dungeons) poderem tocar a MESMA animacao quando duas contas
    -- sincronizadas se encontram pra fazer algo junto, sem precisar duplicar o codigo da animacao
    MoonSync.playAnim = playSyncAnim

    -- --------------------------------------------------- pedido / aceite (via Attribute - 2 contas, mesmo servidor) ----
    local function finalizeSync(p)
        if MoonSync.synced[p.UserId] then return end
        MoonSync.synced[p.UserId] = { name = p.Name, since = os.time() }
        playSyncAnim(p.UserId, p.Name)
        notify("Moon Sync", "Sincronizado com " .. p.Name .. ".", "ok", 4)
    end
    local function hookPlayer(p)
        if p == LP then return end
        pcall(function()
            table.insert(conns, p:GetAttributeChangedSignal("MHSyncReqTo"):Connect(function()
                local to = p:GetAttribute("MHSyncReqTo")
                if to == myId and not MoonSync.pendingIncoming[p.UserId] and not MoonSync.synced[p.UserId] then
                    MoonSync.pendingIncoming[p.UserId] = true
                    confirmToast("Pedido de Moon Sync", p.Name .. " quer sincronizar as contas com voce.", function()
                        pcall(function() LP:SetAttribute("MHSyncAcceptFrom", p.UserId) end)
                        finalizeSync(p)
                    end, 10)
                    task.delay(10.2, function() MoonSync.pendingIncoming[p.UserId] = nil end)
                end
            end))
            table.insert(conns, p:GetAttributeChangedSignal("MHSyncAcceptFrom"):Connect(function()
                local acc = p:GetAttribute("MHSyncAcceptFrom")
                if acc == myId and MoonSync.pendingOut == p.UserId then
                    MoonSync.pendingOut = nil
                    pcall(function() LP:SetAttribute("MHSyncReqTo", 0) end)
                    finalizeSync(p)
                end
            end))
        end)
    end
    for _, p in ipairs(Players:GetPlayers()) do hookPlayer(p) end
    table.insert(conns, Players.PlayerAdded:Connect(hookPlayer))
    table.insert(conns, Players.PlayerRemoving:Connect(function(p) MoonSync.synced[p.UserId] = nil end))
    local function sendRequest(p)
        if MoonSync.pendingOut == p.UserId or MoonSync.synced[p.UserId] then return end
        MoonSync.pendingOut = p.UserId
        MoonSync.pendingOutAt = os.clock()
        pcall(function() LP:SetAttribute("MHSyncReqTo", p.UserId) end)
        notify("Moon Sync", "Pedido enviado para " .. p.Name .. ".", "ok", 3)
        task.delay(10.5, function()
            if MoonSync.pendingOut == p.UserId then
                MoonSync.pendingOut = nil
                pcall(function() LP:SetAttribute("MHSyncReqTo", 0) end)
                notify("Moon Sync", p.Name .. " nao respondeu a tempo.", "warn", 3)
            end
        end)
    end

    -- --------------------------------------------------- UI: lista de usuarios Moon Hub no servidor ----
    section(B, "Multi Account (Moon Sync)", 1)
    new("TextLabel", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 34), Text = "Sincroniza com outras contas do Moon Hub no MESMO servidor: so a conexao/aceite e a coordenacao (cada uma fica com a sua propria config - nao copia nada). So funciona com as duas abas abertas no mesmo servidor.", Font = Enum.Font.Gotham, TextSize = 11, TextColor3 = C.dim, TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Left, LayoutOrder = 2 }, B)

    section(B, "Contas no servidor", 10)
    local listHolder = new("Frame", { Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1, LayoutOrder = 11 }, B)
    list(listHolder, 6)
    local emptyLbl = new("TextLabel", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 30), Text = "Nenhuma outra conta Moon Hub encontrada neste servidor ainda.", Font = Enum.Font.Gotham, TextSize = 12, TextColor3 = C.dim, TextXAlignment = Enum.TextXAlignment.Left }, listHolder)

    section(B, "Contas sincronizadas", 20)
    local syncHolder = new("Frame", { Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1, LayoutOrder = 21 }, B)
    list(syncHolder, 6)
    local emptySync = new("TextLabel", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 30), Text = "Nenhuma conta sincronizada ainda.", Font = Enum.Font.Gotham, TextSize = 12, TextColor3 = C.dim, TextXAlignment = Enum.TextXAlignment.Left }, syncHolder)

    local function userRow(parent, p, status, statusData)
        local r = new("Frame", { Size = UDim2.new(1, 0, 0, 58), BackgroundColor3 = GLASS, BackgroundTransparency = 0.5 }, parent)
        corner(r, 12); stroke(r, Color3.new(1, 1, 1), 1, 0.9)
        local pic = new("ImageLabel", { Size = UDim2.fromOffset(38, 38), Position = UDim2.fromOffset(10, 10), Image = thumbOf(p.UserId), BackgroundColor3 = Color3.fromRGB(26, 27, 33) }, r)
        corner(pic, 19)
        local sub = statusData and string.format("Lv %s | %s | %s", tostring(statusData.lv or "?"), tostring(statusData.sea or "?"), tostring(statusData.act or "?")) or "..."
        new("TextLabel", { BackgroundTransparency = 1, Position = UDim2.fromOffset(58, 9), Size = UDim2.new(1, -140, 0, 18), Text = p.Name, Font = Enum.Font.GothamBold, TextSize = 13, TextColor3 = C.white, TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd }, r)
        new("TextLabel", { BackgroundTransparency = 1, Position = UDim2.fromOffset(58, 28), Size = UDim2.new(1, -140, 0, 22), Text = sub, Font = Enum.Font.Gotham, TextSize = 11, TextColor3 = C.dim, TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd }, r)
        local btn = smallButton(r, status, 96, UDim2.new(1, -106, 0.5, -14), status ~= "Synced")
        return btn
    end

    local function refreshLists()
        for _, c in ipairs(listHolder:GetChildren()) do if c:IsA("Frame") then c:Destroy() end end
        for _, c in ipairs(syncHolder:GetChildren()) do if c:IsA("Frame") then c:Destroy() end end
        local any, anySync = false, false
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= LP and p:GetAttribute("MHPresence") then
                local raw = p:GetAttribute("MHStatus")
                local ok, data = pcall(function() return raw and HttpService:JSONDecode(raw) end)
                data = ok and data or nil
                if MoonSync.synced[p.UserId] then
                    anySync = true
                    userRow(syncHolder, p, "Synced", data).Active = false
                else
                    any = true
                    local label = (MoonSync.pendingOut == p.UserId) and "Pedido..." or "Sync"
                    local btn = userRow(listHolder, p, label, data)
                    btn.MouseButton1Click:Connect(function() sendRequest(p) end)
                end
            end
        end
        emptyLbl.Visible = not any
        emptySync.Visible = not anySync
    end
    refreshLists()
    task.spawn(function()
        while alive do
            task.wait(2)
            pcall(refreshLists)
        end
    end)
    tab.btn.MouseButton1Click:Connect(function() task.defer(refreshLists) end)
end)()

-- ============================================================ Build Your Theme! ====
-- Editor de tema ao vivo: cor de tudo, transparencia, degrades, borda, letras, contorno de letras, fonte e arredondamento.
-- Todo o hub muda enquanto voce mexe. Salva no config (cfg.custom), 3 slots, codigo para copiar/colar e tema aleatorio.
local BLD = { controls = {} }
;(function()
    local tab = addTab("Build Your Theme!", ICON.palette)
    BLD.tab = tab
    local B = tab.body
    local CUS = THEMES["Custom"]
    local DEFT = THEMES["Default"]
    local EXTRA = {
        winS1 = C.white, winS2 = C.blue, winSW = 1.5, winSTr = 0.45, winSpin = 30, tintRot = 35,
        tintA = Color3.fromRGB(70, 100, 220), tintB = Color3.fromRGB(20, 20, 60), tintT = 1,
        tStroke = Color3.new(0, 0, 0), tStrokeT = 1, round = 1, winR = 16, font = "Gotham", tsize = 1,
    }
    local function val(k)
        local v = TH.cur[k]
        if v == nil then v = EXTRA[k] end
        if v == nil then v = DEFT[k] end
        return v
    end
    BLD.val = val

    -- ---------------------------------------------------------- serializar ----
    local function ser(t)
        local o = {}
        for k, v in pairs(t) do
            if typeof(v) == "Color3" then o[k] = { math.floor(v.R * 255 + 0.5), math.floor(v.G * 255 + 0.5), math.floor(v.B * 255 + 0.5) }
            elseif type(v) == "number" or type(v) == "string" then o[k] = v end
        end
        o.image = nil
        return o
    end
    local function deser(into, d)
        for k, v in pairs(d) do
            if type(v) == "table" and #v == 3 then into[k] = Color3.fromRGB(v[1], v[2], v[3])
            elseif type(v) == "number" or type(v) == "string" then into[k] = v end
        end
        into.prev = into.win
    end
    local B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local function b64enc(s)
        local out = {}
        for i = 1, #s, 3 do
            local a, b, c = s:byte(i, i + 2)
            local n = a * 65536 + (b or 0) * 256 + (c or 0)
            local c1, c2, c3, c4 = math.floor(n / 262144) % 64, math.floor(n / 4096) % 64, math.floor(n / 64) % 64, n % 64
            out[#out + 1] = B64:sub(c1 + 1, c1 + 1) .. B64:sub(c2 + 1, c2 + 1) .. (b and B64:sub(c3 + 1, c3 + 1) or "=") .. (c and B64:sub(c4 + 1, c4 + 1) or "=")
        end
        return table.concat(out)
    end
    local function b64dec(s)
        s = s:gsub("[^%w%+/=]", "")
        local out = {}
        for i = 1, #s, 4 do
            local n, pad = 0, 0
            for j = 0, 3 do
                local ch = s:sub(i + j, i + j)
                local v = ch == "=" and 0 or ((B64:find(ch, 1, true) or 1) - 1)
                if ch == "=" then pad += 1 end
                n = n * 64 + v
            end
            local a, b, c = math.floor(n / 65536) % 256, math.floor(n / 256) % 256, n % 256
            out[#out + 1] = string.char(a) .. (pad < 2 and string.char(b) or "") .. (pad < 1 and string.char(c) or "")
        end
        return table.concat(out)
    end

    -- --------------------------------------------------------------- aplicar ----
    local function applyBinds(keys)       -- keys = so as chaves que mudaram (nil = todas)
        for _, b in ipairs(TH.binds) do
            if not keys or keys[b[3]] then
                local o = b[1]
                pcall(function() o[b[2]] = TH.cur[b[3]] end)
            end
        end
    end
    local function liveTint()             -- degrade da janela sem animar (resposta imediata ao arrastar)
        local t = TH.cur
        pcall(function()
            tintG.Color = ColorSequence.new(t.tintA or C.white, t.tintB or C.white)
            tintG.Rotation = t.tintRot or 35
            tintFrame.BackgroundTransparency = t.tintT or 1
        end)
    end
    function BLD.applyBorder()
        local t = TH.cur
        local c0, c1 = t.winS1 or C.white, t.winS2 or C.blue
        local seq = ColorSequence.new(c0, c1)
        pcall(function() winG.Color = seq; winStroke.Thickness = t.winSW or 1.5; winStroke.Transparency = t.winSTr or 0.45 end)
        for _, k in ipairs({ "ringG", "thxG", "cardG" }) do
            local g = ui[k]
            if g then pcall(function() g.Color = seq end) end
        end
    end
    local TXT = { TextLabel = true, TextButton = true, TextBox = true }
    local ORIGF = setmetatable({}, { __mode = "k" })
    local ORIGR = setmetatable({}, { __mode = "k" })
    local ORIGS = setmetatable({}, { __mode = "k" })
    local function F(n) local ok, v = pcall(function() return Enum.Font[n] end); return ok and v or nil end
    local FONTS = {
        ["Gotham"] = false,
        ["Source Sans"] = { "SourceSans", "SourceSansSemibold", "SourceSansBold" },
        ["Ubuntu"] = { "Ubuntu", "Ubuntu", "Ubuntu" },
        ["Arial"] = { "Arial", "Arial", "ArialBold" },
        ["Roboto"] = { "Roboto", "Roboto", "Roboto" },
        ["Nunito"] = { "Nunito", "Nunito", "Nunito" },
        ["Oswald"] = { "Oswald", "Oswald", "Oswald" },
        ["Code"] = { "Code", "Code", "Code" },
        ["Sci-Fi"] = { "SciFi", "SciFi", "SciFi" },
        ["Fantasy"] = { "Fantasy", "Fantasy", "Fantasy" },
        ["Bangers"] = { "Bangers", "Bangers", "Bangers" },
        ["Jura"] = { "Jura", "Jura", "Jura" },
    }
    local FONT_LIST = { "Gotham", "Source Sans", "Ubuntu", "Arial", "Roboto", "Nunito", "Oswald", "Code", "Sci-Fi", "Fantasy", "Bangers", "Jura" }
    local function weightOf(f)
        local n = tostring(f)
        if n:find("Bold") or n:find("Black") then return 3 elseif n:find("Semi") or n:find("Medium") then return 2 end
        return 1
    end
    local function applyOne(o, fam, sT, sC, sz)
        if not TXT[o.ClassName] then return end
        if fam then
            local f0 = ORIGF[o]
            if not f0 then f0 = o.Font; ORIGF[o] = f0 end
            local f = F(fam[weightOf(f0)])
            if f then o.Font = f end
        elseif ORIGF[o] then
            o.Font = ORIGF[o]
        end
        if sz ~= 1 or ORIGS[o] then
            local s0 = ORIGS[o]
            if not s0 then s0 = o.TextSize; ORIGS[o] = s0 end
            o.TextSize = math.max(8, math.floor(s0 * sz + 0.5))
        end
        if not o:FindFirstChildOfClass("UIStroke") then
            o.TextStrokeColor3 = sC; o.TextStrokeTransparency = sT
        end
    end
    local function roundOne(o, f)
        if SHAPE.set[o] then return end          -- cantos da janela seguem o slider "Window corners"
        if o.ClassName == "UICorner" and o.CornerRadius.Scale == 0 then
            local r0 = ORIGR[o]
            if not r0 then r0 = o.CornerRadius.Offset; ORIGR[o] = r0 end
            o.CornerRadius = UDim.new(0, math.floor(r0 * f + 0.5))
        end
    end
    -- objetos criados depois (listas que abrem, cartoes...) recebem o mesmo estilo
    local watch
    local function syncWatch()
        local need = BLD.textOn or BLD.roundOn
        if need and not watch then
            watch = gui.DescendantAdded:Connect(function(o)
                if (BLD.textOn and TXT[o.ClassName]) or (BLD.roundOn and o.ClassName == "UICorner") then
                    task.defer(function()
                        if BLD.textOn and TXT[o.ClassName] then pcall(applyOne, o, BLD.textFam, BLD.textST, BLD.textSC, BLD.textSZ) end
                        if BLD.roundOn then pcall(roundOne, o, BLD.roundF) end
                    end)
                end
            end)
            table.insert(conns, watch)
        elseif not need and watch then
            watch:Disconnect(); watch = nil
        end
    end
    function BLD.applyText()
        local t = TH.cur
        local fam = FONTS[t.font or "Gotham"] or nil
        local sT, sC, sz = t.tStrokeT or 1, t.tStroke or Color3.new(0, 0, 0), t.tsize or 1
        local on = (sT < 1) or (fam ~= nil) or (sz ~= 1)
        if not on and not BLD.textOn then return end
        BLD.textFam, BLD.textST, BLD.textSC, BLD.textSZ = fam, sT, sC, sz
        BLD.textOn = true
        for _, o in ipairs(gui:GetDescendants()) do pcall(applyOne, o, fam, sT, sC, sz) end
        BLD.textOn = on
        syncWatch()
    end
    function BLD.applyRound()
        local f = TH.cur.round or 1
        if f == 1 and not BLD.roundOn then return end
        BLD.roundF = f
        for _, o in ipairs(gui:GetDescendants()) do pcall(roundOne, o, f) end
        BLD.roundOn = (f ~= 1)
        syncWatch()
    end
    function BLD.applyShape()
        pcall(SHAPE.apply, TH.cur.winR or EXTRA.winR)
    end
    function BLD.applyExtras()
        BLD.applyShape(); BLD.applyBorder(); BLD.applyText(); BLD.applyRound()
    end
    table.insert(TH.hooks, function() BLD.applyExtras() end)

    -- uma unica tarefa "espera parar de mexer": redesenha cartoes/toggles e grava o config uma vez so
    local lastEdit, waiting = 0, false
    local function touch()
        lastEdit = os.clock()
        if waiting then return end
        waiting = true
        task.spawn(function()
            while os.clock() - lastEdit < 0.25 do task.wait(0.1) end
            waiting = false
            for _, f in ipairs(TH.hooks) do pcall(f) end
            cfg.custom = ser(CUS)
            persist()
        end)
    end
    local function saveSoon() cfg.custom = ser(CUS); touch() end
    local function ensureCustom()
        if TH.name == "Custom" then return end
        for k in pairs(CUS) do CUS[k] = nil end
        for k, v in pairs(TH.cur) do CUS[k] = v end
        CUS.image = nil
        for k, v in pairs(EXTRA) do if CUS[k] == nil then CUS[k] = v end end
        TH.cur, TH.name = CUS, "Custom"
        cfg.theme = "Custom"
        for _, f in ipairs(TH.hooks) do pcall(f) end
        for _, c in ipairs(BLD.controls) do pcall(c.refresh) end
    end
    -- varios eventos no mesmo quadro (arrastar) viram uma unica aplicacao
    local pend, pendKeys = false, {}
    local function flush()
        pend = false
        local keys = pendKeys; pendKeys = {}
        if keys.win then keys.prev = true end
        applyBinds(keys)
        if keys.tintA or keys.tintB or keys.tintT or keys.tintRot then liveTint() end
        if keys.winS1 or keys.winS2 or keys.winSW or keys.winSTr then BLD.applyBorder() end
        if keys.tStroke or keys.tStrokeT or keys.font or keys.tsize then BLD.applyText() end
        if keys.round then BLD.applyRound() end
        if keys.winR then BLD.applyShape() end
    end
    local function changed(key)
        ensureCustom()
        CUS.prev = CUS.win
        pendKeys[key] = true
        if not pend then pend = true; task.defer(flush) end
        saveSoon()
    end
    BLD.changed = changed
    local function setCustomFrom(tbl)
        for k in pairs(CUS) do CUS[k] = nil end
        for k, v in pairs(DEFT) do CUS[k] = v end
        for k, v in pairs(EXTRA) do CUS[k] = v end
        deser(CUS, tbl)
        TH.cur, TH.name = CUS, "Custom"; cfg.theme = "Custom"
        applyBinds(); liveTint()
        for _, f in ipairs(TH.hooks) do pcall(f) end
        for _, c in ipairs(BLD.controls) do pcall(c.refresh) end
        BLD.applyShape(); BLD.applyBorder(); BLD.applyText(); BLD.applyRound()
        saveSoon()
    end
    BLD.setCustomFrom = setCustomFrom

    -- -------------------------------------------------------------- controles ----
    local ord = 0
    local function nx() ord += 1; return ord end
    local function colorRow(label, key, sub)
        local c = UIX.color(B, ICON.palette, label, nx(), function() return val(key) end, function(col) ensureCustom(); CUS[key] = col; changed(key) end, sub)
        BLD.controls[#BLD.controls + 1] = c
    end
    -- inv = o slider mostra "forca" (0% = desligado) e o tema guarda a transparencia (1 = desligado)
    local function numRow(label, key, sub, mn, mx, dec, fmt, icn, inv)
        local c
        local function conv(v) return inv and (1 - v) or v end
        c = UIX.slider(B, icn or ICON.eye, label, sub, nx(), mn, mx, conv(val(key)), function(v) ensureCustom(); CUS[key] = conv(v); changed(key) end, fmt, dec)
        local obj = { row = c.row }
        function obj.refresh() c.set(conv(val(key)), true) end
        BLD.controls[#BLD.controls + 1] = obj
    end
    local strength = function(v) return v <= 0 and "Off" or string.format("%d%%", math.floor(v * 100 + 0.5)) end
    local pct = function(v) return string.format("%d%%", math.floor(v * 100 + 0.5)) end
    local d2 = function(v) return string.format("%.2f", v) end

    -- ---------- Presets / ferramentas ----------
    section(B, "Start", nx())
    do
        local names = {}
        for _, n in ipairs(THEME_ORDER) do if n ~= "Custom" then names[#names + 1] = n end end
        local pick
        pick = UIX.select(B, ICON.layers, "Start from a theme", "Copies a theme into the editor, then you change anything", nx(), names, "Default", false, function(v)
            local src = THEMES[v]
            if not src then return end
            local t = {}
            for k, vv in pairs(src) do t[k] = vv end
            setCustomFrom(ser(t))
            notify("Build Your Theme!", "Loaded " .. v .. ". Edit anything below.", "ok", 2.5)
        end)
        UIX.button(B, ICON.refresh, "Random Theme", "Makes a new palette for you", nx(), "Randomize", function()
            local h = math.random()
            local function hsv(hh, s, v) return Color3.fromHSV(hh % 1, s, v) end
            local light = math.random() < 0.12
            local t = {
                win = light and hsv(h, 0.06, 0.96) or hsv(h, 0.55, 0.12), winT = light and 0 or (0.08 + math.random() * 0.25),
                tintA = hsv(h, 0.65, light and 0.9 or 0.45), tintB = hsv(h + 0.1, 0.75, light and 0.8 or 0.18), tintT = 0.35 + math.random() * 0.35, tintRot = math.random(0, 360),
                row = light and Color3.new(1, 1, 1) or Color3.new(1, 1, 1), rowT = light and 0 or 0.9, rowS = hsv(h, 0.45, light and 0.7 or 1), rowST = 0.35 + math.random() * 0.3,
                text = light and hsv(h, 0.4, 0.12) or Color3.fromRGB(245, 246, 252), dim = light and hsv(h, 0.2, 0.45) or hsv(h, 0.15, 0.82), icon = light and hsv(h, 0.4, 0.3) or hsv(h, 0.15, 0.85),
                card = light and hsv(h, 0.05, 0.99) or hsv(h, 0.5, 0.14), cardT = 0.05, panel = light and hsv(h, 0.08, 0.9) or Color3.new(0, 0, 0), panelT = light and 0 or 0.55,
                line = hsv(h, 0.3, light and 0.7 or 1), lineT = 0.8, track = hsv(h, 0.3, light and 0.78 or 0.32), hl = hsv(h, 0.6, 1), hlT = 0.86,
                acc = hsv(h, 0.75, 1), title = light and Color3.new(0, 0, 0) or Color3.new(1, 1, 1), titleS = light and Color3.new(1, 1, 1) or Color3.new(0, 0, 0),
                winS1 = hsv(h, 0.35, 1), winS2 = hsv(h + 0.14, 0.85, 1), winSW = 1.5 + math.random() * 1.5, winSTr = 0.3 + math.random() * 0.3, winSpin = math.random(10, 70),
                tStroke = Color3.new(0, 0, 0), tStrokeT = 1, round = TH.cur.round or 1, winR = TH.cur.winR or 16, font = "Gotham", tsize = 1,
            }
            setCustomFrom(ser(t))
            notify("Build Your Theme!", "Random theme applied. Like it? Save it to a slot below.", "ok", 3)
        end)
        -- v63: preset de 1 clique pro contorno "modo luz" (borda brilhante girando rapido, tipo neon correndo) -
        -- ja existia o editor manual (Window Border: cor A/B, espessura, transparencia, velocidade de giro), mas
        -- pedir pra ajustar os 5 sliders na mao nao e tao direto quanto um botao
        UIX.button(B, ICON.flame, "Light Mode (glow border)", "Bright neon border, spinning fast like it's running", nx(), "Apply", function()
            local t = {}
            for k, vv in pairs(TH.cur) do t[k] = vv end
            local h = math.random()
            t.winS1 = Color3.fromHSV(h % 1, 0.85, 1)
            t.winS2 = Color3.fromHSV((h + 0.5) % 1, 0.85, 1)   -- cor oposta no circulo de cores: contraste maximo
            t.winSW = 3; t.winSTr = 0; t.winSpin = 140
            setCustomFrom(ser(t))
            notify("Build Your Theme!", "Light Mode applied - neon border spinning. Tweak colors/speed below if you want.", "ok", 3)
        end)
        UIX.button(B, ICON.power, "Reset Editor", "Back to the Default theme", nx(), "Reset", function()
            local t = {}
            for k, vv in pairs(DEFT) do t[k] = vv end
            setCustomFrom(ser(t))
            TH.apply("Default"); cfg.theme = "Default"; cfg.custom = {}; persist()
            notify("Build Your Theme!", "Back to the Default theme.", "ok", 2.5)
        end)
    end

    -- ---------- Window ----------
    section(B, "Window", nx())
    colorRow("Window color", "win", "Main background of the hub")
    numRow("Window transparency", "winT", "0 = solid, 1 = invisible", 0, 1, 2, pct)
    colorRow("Gradient color A", "tintA", "First color of the window gradient")
    colorRow("Gradient color B", "tintB", "Second color of the window gradient")
    numRow("Gradient strength", "tintT", "How visible the gradient is", 0, 1, 2, strength, ICON.layers, true)
    numRow("Gradient angle", "tintRot", "Direction of the gradient", 0, 360, 0, function(v) return tostring(v) .. "\u{b0}" end, ICON.repeatI)

    -- ---------- Window border ----------
    section(B, "Window Border", nx())
    colorRow("Border color A", "winS1", "Border gradient, start")
    colorRow("Border color B", "winS2", "Border gradient, end")
    numRow("Border thickness", "winSW", "In pixels", 0, 6, 1, function(v) return string.format("%.1f px", v) end, ICON.layers)
    numRow("Border transparency", "winSTr", "0 = solid, 1 = hidden", 0, 1, 2, pct)
    numRow("Border spin speed", "winSpin", "Degrees per second (negative = other way, 0 = still)", -180, 180, 0, function(v) return v == 0 and "Still" or tostring(v) .. "\u{b0}/s" end, ICON.repeatI)

    -- ---------- Rows / cards ----------
    section(B, "Rows, Cards and Panels", nx())
    colorRow("Row color", "row", "Background of each option")
    numRow("Row transparency", "rowT", "0 = solid, 1 = invisible", 0, 1, 2, pct)
    colorRow("Row border color", "rowS", "Outline of each option")
    numRow("Row border transparency", "rowST", "0 = solid, 1 = hidden", 0, 1, 2, pct)
    colorRow("Card color", "card", "Profile card, popups")
    numRow("Card transparency", "cardT", "0 = solid, 1 = invisible", 0, 1, 2, pct)
    colorRow("Panel color", "panel", "Dark boxes inside cards")
    numRow("Panel transparency", "panelT", "0 = solid, 1 = invisible", 0, 1, 2, pct)
    colorRow("Divider color", "line", "Lines between sections")
    numRow("Divider transparency", "lineT", "0 = solid, 1 = hidden", 0, 1, 2, pct)

    -- ---------- Sidebar ----------
    section(B, "Sidebar and Menus", nx())
    colorRow("Highlight color", "hl", "Selected tab and menu items")
    numRow("Highlight transparency", "hlT", "0 = solid, 1 = invisible", 0, 1, 2, pct)

    -- ---------- Text ----------
    section(B, "Text", nx())
    colorRow("Text color", "text", "Main text")
    colorRow("Secondary text color", "dim", "Descriptions and small text")
    colorRow("Icon color", "icon", "Icons of each option")
    colorRow("Title color", "title", "The words \"Moon Hub\"")
    colorRow("Title outline color", "titleS", "Outline of \"Moon Hub\"")
    colorRow("Text outline color", "tStroke", "Outline of every letter")
    numRow("Text outline strength", "tStrokeT", "How thick the outline looks", 0, 1, 2, strength, ICON.layers, true)
    do
        local sel
        sel = UIX.select(B, ICON.code, "Font", "Changes the font of the whole hub", nx(), FONT_LIST, val("font"), false, function(v)
            ensureCustom(); CUS.font = v; changed("font")
        end)
        BLD.controls[#BLD.controls + 1] = { row = sel.row, refresh = function() sel.set(val("font")) end }
    end

    numRow("Text size", "tsize", "Makes every letter bigger or smaller (x1 = normal)", 0.8, 1.3, 2, function(v) return string.format("x%.2f", v) end, ICON.eye)

    -- ---------- Accent ----------
    section(B, "Accent", nx())
    colorRow("Accent color", "acc", "Toggles ON, sliders, selected items")
    colorRow("Off / track color", "track", "Toggles OFF and slider track")

    -- ---------- Shape ----------
    section(B, "Shape and Icons", nx())
    numRow("Window corners", "winR", "How round the corners of the hub window are (0 = square)", 0, 48, 0, function(v) return v <= 0 and "Square" or (tostring(v) .. " px") end, ICON.layers)
    numRow("Element roundness", "round", "Rows, buttons, cards and toggles (x1 = normal, x0 = square, x4 = pill)", 0, 4, 2, function(v) return string.format("x%.2f", v) end, ICON.layers)
    do   -- mesmo glifo em todas as linhas (o estilo fica salvo e nao faz parte do tema)
        local pickI
        pickI = UIX.select(B, ICON.palette, "Row icons", "Same mark on every row. Classic = one icon per row, None = hidden",
            nx(), { "Dot", "Moon", "Classic", "None" }, cfg.rowIcons, false, function(v) ORG.setStyle(v); persist() end)
        BLD.rowIcons = pickI
    end

    -- ---------- Save / share ----------
    section(B, "Save and Share", nx())
    do
        cfg.slots = type(cfg.slots) == "table" and cfg.slots or {}
        local slotSel = UIX.select(B, ICON.save, "Slot", "Pick where to save or load", nx(), { "Slot 1", "Slot 2", "Slot 3" }, "Slot 1", false, nil)
        local function slotN() return tonumber(tostring(slotSel.value):match("%d")) or 1 end
        UIX.button(B, ICON.save, "Save to slot", "Stores the theme you see now", nx(), "Save", function()
            ensureCustom()
            cfg.slots[tostring(slotN())] = ser(CUS); persist()
            notify("Build Your Theme!", "Saved to Slot " .. slotN() .. ".", "ok", 2.5)
        end)
        UIX.button(B, ICON.refresh, "Load slot", "Brings a saved theme back", nx(), "Load", function()
            local d = cfg.slots[tostring(slotN())]
            if not d then notify("Build Your Theme!", "Slot " .. slotN() .. " is empty.", "warn", 2.5) return end
            setCustomFrom(d)
            notify("Build Your Theme!", "Loaded Slot " .. slotN() .. ".", "ok", 2.5)
        end)
        UIX.button(B, ICON.copy, "Copy Theme Code", "Share your theme with friends", nx(), "Copy", function()
            ensureCustom()
            local code = "MOONTHEME:" .. b64enc(HttpService:JSONEncode(ser(CUS)))
            local ok = pcall(function() setclipboard(code) end)
            notify("Build Your Theme!", ok and "Theme code copied." or "Your executor can't copy to the clipboard.", ok and "ok" or "warn", 3)
        end)
        UIX.input(B, ICON.link, "Paste Theme Code", "Paste a code and press Enter", nx(), "", "MOONTHEME:...", false, function(txt)
            local body = tostring(txt or ""):match("MOONTHEME:([%w%+/=]+)")
            if not body then return end
            local ok, d = pcall(function() return HttpService:JSONDecode(b64dec(body)) end)
            if ok and type(d) == "table" then
                setCustomFrom(d)
                notify("Build Your Theme!", "Theme code applied.", "ok", 2.5)
            else
                notify("Build Your Theme!", "That code is not valid.", "bad", 3)
            end
        end)
    end
    table.insert(TH.hooks, function() for _, c in ipairs(BLD.controls) do pcall(c.refresh) end end)
end)()

-- ============================================== Moon antigo (camada de compatibilidade) ====
-- Roda os modulos do Moon antigo (Races/Ghoul, Vulcan, Dungeons, Sub Farm/CDK, Raid, Sea Events...) em cima do motor Premium.
-- Os modulos so sao lidos/compilados quando a aba deles abre ou quando uma opcao deles esta ligada (script leve).
local PC = { loaded = {}, src = {}, mods = {}, unload = {}, order = {} }
;(function()
    local Core = getgenv().MoonPremiumCore
    local LV = Core.level
    local LVE = LV and LV.E
    local RS = game:GetService("ReplicatedStorage")
    local VIM = game:GetService("VirtualInputManager")
    local genv = getgenv()
    local Player = LP

    cfg.m = type(cfg.m) == "table" and cfg.m or {}
    local M = cfg.m
    local TR = {}                       -- opcoes passageiras (nao salvas)
    local ST = { Mode = "Idle", Text = "—", Busy = false, epoch = 1, loopAt = os.clock(), atkAt = os.clock(), bossAt = 0 }
    local Diag = {}
    local Connections = {}
    local AFL = { feat = {}, Hop = { active = false, activeAt = 0, gui = nil, serverAt = os.clock(), failAt = 0 }, Visited = {}, Mods = { ok = {}, fail = {} },
        Err = { list = {}, count = {}, quar = {} }, Wait = {} }
    PC.AFL, PC.State, PC.Diag, PC.Connections = AFL, ST, Diag, Connections
    PC.atkUntil = 0
    Core.AFL = AFL   -- v79: exposto global (getgenv().MoonPremiumCore.AFL) pro botao "Reset Farm Configs" (Farm Settings,
                      -- criado antes deste bloco existir) conseguir chamar AFL.resetFarmConfig() no clique, mesmo sem
                      -- "AFL"/"PC" serem upvalues la (sao locals declarados so aqui, mais abaixo no arquivo)
    -- v79: zera TODOS os toggles/sliders/selects das abas do Moon antigo (Races, Sub Farm, Vulcan, Raid, Fully...) -
    -- "M" e o mesmo "cfg.m" salvo em disco, entao limpar ele aqui tambem zera os valores de velocidade do Farm
    -- Settings (Tween/Island/Sea Speed etc, que moram no mesmo cfg.m) ao mesmo tempo. "TR" sao as opcoes que nao
    -- sao salvas (voltam ao padrao sozinhas a cada sessao nova, mas durante a sessao atual tambem precisam ser
    -- limpas pra nao ficar com um valor antigo na memoria). So apaga as entradas (nil) - o __index de Config
    -- (mais abaixo) ja recria o valor padrao de DEF na proxima leitura.
    function AFL.resetFarmConfig()
        for k in pairs(M) do M[k] = nil end
        for k in pairs(TR) do TR[k] = nil end
    end

    local function onUnload(f) PC.unload[#PC.unload + 1] = f end
    PC.onUnload = onUnload
    AFL.onUnload = onUnload
    table.insert(cleanups, function()
        for _, f in ipairs(PC.unload) do pcall(f) end
        for _, c in ipairs(Connections) do pcall(function() c:Disconnect() end) end
        Connections = {}
        if PC.atkOwned and Core.attacking then pcall(Core.setAttack, false) end
        PC.atkOwned = false
        Core.ov, Core.force = nil, nil
        pcall(function() local _, h = LP.Character, LP.Character and LP.Character:FindFirstChild("HumanoidRootPart"); local b = h and h:FindFirstChild("FarmHold"); if b then b:Destroy() end end)
    end)

    -- ------------------------------------------------------------------ Config ----
