    local Config = setmetatable({}, {
        __index = function(_, k)
            local g = GET[k]
            if g then return g() end
            if SAVED[k] then
                local v = M[k]
                if v == nil and DEF[k] ~= nil then v = dc(DEF[k]); M[k] = v end
                return v
            end
            local v = TR[k]
            if v == nil and DEF[k] ~= nil then v = dc(DEF[k]); TR[k] = v end
            return v
        end,
        __newindex = function(_, k, v)
            local s = SET[k]
            if s then s(v) return end
            if SAVED[k] then M[k] = v else TR[k] = v end
        end,
    })
    PC.Config = Config

    -- cfg.m e salvo em JSON junto com o resto: tira o que o JSON nao aceita (funcoes, Instances, chaves mistas)
    local function jsonSafe(v, depth)
        local t = type(v)
        if t == "string" or t == "boolean" then return v end
        if t == "number" then if v ~= v or v == math.huge or v == -math.huge then return nil end return v end
        if t ~= "table" or depth > 6 then return nil end
        local n, arr = 0, true
        for k in pairs(v) do n += 1; if type(k) ~= "number" then arr = false end end
        local o = {}
        if arr and n > 0 then
            for i = 1, #v do local x = jsonSafe(v[i], depth + 1); if x == nil then x = false end; o[i] = x end
        else
            for k, x in pairs(v) do
                if type(k) == "string" or type(k) == "number" then
                    local y = jsonSafe(x, depth + 1)
                    if y ~= nil then o[tostring(k)] = y end
                end
            end
        end
        return o
    end
    PC.jsonSafe = jsonSafe
    persistXform = function(c)
        local snap = {}
        for k, v in pairs(c) do snap[k] = v end
        snap.m = jsonSafe(M, 0) or {}
        return snap
    end

    -- ------------------------------------------------------------ helpers basicos ----
    local function canFile() return type(isfile) == "function" and type(readfile) == "function" and type(writefile) == "function" end
    local function getChar()
        local char = LP.Character
        if not char then return end
        local hrp = char:FindFirstChild("HumanoidRootPart")
        local hum = char:FindFirstChildOfClass("Humanoid")
        if hrp and hum and hum.Health > 0 then return char, hrp, hum end
    end
    local function getPlayerLevel()
        local ok, lvl = pcall(function() return LP.Data.Level.Value end)
        return ok and lvl or 1
    end
    -- v84: ground-truth de que o mapa carregado e o do Mar 3 (so existe workspace.Map.TikiOutpost la - mesmo
    -- lugar ja usado com sucesso no Auto Tyrant pros "olhos" das estatuas). Usado so pra CORRIGIR o palpite por
    -- nivel abaixo, nunca pra decidir por conta propria.
    local function hasTikiMap()
        local ok, has = pcall(function()
            local map = workspace:FindFirstChild("Map")
            return map and map:FindFirstChild("TikiOutpost") ~= nil
        end)
        return ok and has
    end
    local function getSea()
        if LVE then
            local ok, s = pcall(function() return LVE.seaId(LVE.myLevel()) end)
            if ok and s then return s end
        end
        local byPlace = ({ [2753915549] = 1, [85211729168715] = 1, [4442272183] = 2, [79091703265657] = 2, [7449423635] = 3, [100117331123089] = 3 })[game.PlaceId]
        if byPlace then return byPlace end
        local lvl = getPlayerLevel()
        -- v84 fix: nivel sozinho nao e confiavel aqui - jogador de nivel 1500+ "farmando parado" no Mar 2
        -- (muito comum) caia nesse "elseif" e o codigo achava que era Mar 3 so pelo nivel, mesmo o mapa
        -- carregado sendo o do Mar 2 (sem Tiki Outpost). Isso fazia o Sea Events usar as referencias/zonas do
        -- Mar 3 (Tiki) com o personagem fisicamente no Mar 2 - o "volta pra Tiki no nivel 2 do mar" relatado.
        -- Agora so aceita nivel>=1500 = Mar 3 se o mapa do Mar 3 realmente estiver carregado; senao cai pro Mar 2.
        if lvl >= 1500 then return hasTikiMap() and 3 or 2 elseif lvl >= 700 then return 2 end
        return 1
    end
    local function commF()
        local r = RS:FindFirstChild("Remotes")
        return r and r:FindFirstChild("CommF_")
    end
    -- Chama o CommF_ com limite de 8s (um remote sem resposta nao trava mais o loop). Retorna (ok, resposta)
    local function invoke(...)
        local rf = commF()
        if not rf then return false, "remote CommF_ not found" end
        local args = table.pack(...)
        local done, ok, res = false, false, nil
        task.spawn(function()
            ok, res = pcall(rf.InvokeServer, rf, table.unpack(args, 1, args.n))
            done = true
        end)
        local t0 = os.clock()
        while not done and os.clock() - t0 < 8 do task.wait(0.05) end
        if not done then return false, "no response from the server (8s)" end
        return ok, res
    end
    local function distanceTo(cf)
        local _, hrp = getChar()
        return hrp and (hrp.Position - cf.Position).Magnitude or math.huge
    end
    local function describe(v)
        local t = typeof(v)
        if t == "table" then
            local n, first = 0, nil
            for k, x in pairs(v) do
                n += 1
                if not first then first = tostring(k) .. "=" .. tostring(x) end
            end
            return string.format("table(%d)%s", n, first and (" {" .. first .. ", ...}") or "")
        end
        return tostring(v)
    end
    local function pressKey(code) Core.pressKey(code) end

    PC.getChar, PC.getSea, PC.invoke, PC.canFile, PC.distanceTo = getChar, getSea, invoke, canFile, distanceTo

    -- ---------------------------------------------------------------- inventario ----
    local InvCache = { at = 0, map = {} }
    local function invCount(name)
        local nk = string.lower(string.gsub(tostring(name), "[^%w]", ""))
        local mc = Core.inv and Core.inv.count(name) or 0
        if mc > 0 then return mc end
        if os.clock() - InvCache.at > 5 then
            InvCache.at = os.clock()
            local ok, inv = invoke("getInventory")
            if ok and type(inv) == "table" then
                local m = {}
                InvCache.raw = inv
                local function cntOf(it)
                    for _, k in ipairs({ "Count", "Amount", "Quantity", "Qty", "Stack", "Value", "count", "amount", "quantity" }) do
                        if tonumber(it[k]) then return tonumber(it[k]) end
                    end
                    for k, v in pairs(it) do
                        local kl = string.lower(tostring(k))
                        if type(v) == "number" and (string.find(kl, "count", 1, true) or string.find(kl, "amount", 1, true) or string.find(kl, "quant", 1, true)) then return v end
                    end
                    return 1
                end
                local function walk(t, depth)
                    for key, it in pairs(t) do
                        local nm, cnt
                        if type(it) == "table" then
                            local nmv = it.Name or it.name or it.ItemName or it.Item
                            if nmv ~= nil and type(nmv) ~= "table" then nm, cnt = tostring(nmv), cntOf(it)
                            elseif depth < 4 then walk(it, depth + 1) end
                        elseif type(it) == "number" and type(key) == "string" then nm, cnt = key, it
                        elseif type(it) == "string" and type(key) == "number" then nm, cnt = it, 1 end
                        if nm then
                            local nk2 = string.lower(string.gsub(nm, "[^%w]", ""))
                            m[nm] = (m[nm] or 0) + cnt
                            m["#" .. nk2] = (m["#" .. nk2] or 0) + cnt
                        end
                    end
                end
                walk(inv, 0)
                InvCache.map = m
            end
        end
        return InvCache.map[name] or InvCache.map["#" .. nk] or 0
    end
    local function hasItem(name)
        local nk = string.lower(string.gsub(tostring(name), "[^%w]", ""))
        for _, c in ipairs({ LP.Backpack, LP.Character }) do
            if c then
                if c:FindFirstChild(name) then return true end
                for _, ch in ipairs(c:GetChildren()) do
                    if string.lower(string.gsub(ch.Name, "[^%w]", "")) == nk then return true end
                end
            end
        end
        return invCount(name) > 0
    end

    -- ----------------------------------------------------------------- voo (v52) ----
    local Fly = { goal = nil, lastPos = nil, cruiseY = nil }
    local currentTween = { PlaybackState = Enum.PlaybackState.Completed }
    function currentTween:Cancel() Fly.goal = nil; self.PlaybackState = Enum.PlaybackState.Completed end
    local function flyTo(targetCF)
        -- v66: dentro do dominio do boss ninguem mais manda o personagem voar (outra funcao puxava para outra ilha durante a luta)
        local bossLock = getgenv().MoonBossLock
        if bossLock and os.clock() < bossLock then return end
        local _, hrp = getChar()
        if not hrp then return end
        if (hrp.Position - targetCF.Position).Magnitude < 3 then return end
        -- v148: mesmo destino de antes (CFrame "quase igual", ex.: recalculado a cada 0.1 s por quem chama) = nao recalcula nada,
        -- a viagem segue reta sem reiniciar rota/altitude/rotacao
        if Fly.goal and currentTween.PlaybackState == Enum.PlaybackState.Playing and (Fly.goal.Position - targetCF.Position).Magnitude <= 3 then return end
        if not Fly.goal or (Fly.goal.Position - targetCF.Position).Magnitude > 8 then
            local p = hrp.Position
            local h = Vector3.new(targetCF.X - p.X, 0, targetCF.Z - p.Z).Magnitude
            Fly.far = h > 1500
            if h > 220 and p.Y > -500 and targetCF.Y > -500 and os.clock() >= (Fly.boostUntil or 0) then
                -- v14: so define a altitude de cruzeiro UMA vez por viagem. Antes, um alvo que se move (boss voando, mob andando) trocava
                -- de objetivo toda hora e a altitude era recalculada a partir da posicao atual (+90 a cada vez): o personagem
                -- subia para sempre sem chegar ("fica indo pra cima ao inves de matar o boss").
                if not Fly.cruiseY then Fly.cruiseY = math.max(p.Y, targetCF.Y) + 90 end
            else
                Fly.cruiseY = nil
            end
        end
        Fly.goal = targetCF
        currentTween.PlaybackState = Enum.PlaybackState.Playing
    end
    local flySt = Core.newMover()
    table.insert(conns, RunService.Heartbeat:Connect(function(dt)
        local goal = Fly.goal
        if not goal then
            if Fly.phys and not Fly.settleCF then Fly.phys = false; Core.flightPhys(false) end   -- v149
            -- v55: chegou num lugar cujo mapa ainda nao carregou (streaming): segura no ar ate aparecer chao, senao cai no vazio/mar e morre
            local sc = Fly.settleCF
            if sc and alive then
                local now = os.clock()
                if now > (Fly.settleUntil or 0) then Fly.settleCF = nil return end
                local _, hr = getChar()
                if not hr then return end
                if now - (Fly.settleRay or 0) > 0.25 then
                    Fly.settleRay = now
                    if not Fly.streamBusy then
                        Fly.streamBusy = true
                        local sp = sc.Position
                        task.spawn(function() pcall(function() LP:RequestStreamAroundAsync(sp, 2) end); Fly.streamBusy = false end)
                    end
                    local ok, hit = pcall(function()
                        local rp = RaycastParams.new()
                        rp.FilterType = Enum.RaycastFilterType.Exclude
                        rp.FilterDescendantsInstances = { LP.Character }
                        return workspace:Raycast(hr.Position, Vector3.new(0, -14, 0), rp)
                    end)
                    if ok and hit then Fly.settleCF = nil return end
                end
                -- so age se estiver CAINDO de verdade (nao briga com farm/boss que ja segura o personagem)
                if hr.AssemblyLinearVelocity.Y < -15 and hr.Position.Y < sc.Position.Y - 3 then
                    hr.CFrame = sc
                    hr.AssemblyLinearVelocity = Vector3.zero
                end
            end
            return
        end
        if not alive then Fly.goal = nil return end
        local _, hrp = getChar()
        if not hrp then Fly.goal = nil return end
        local pos = hrp.Position
        local gpNow = goal.Position
        if not Fly.streamBusy and (os.clock() - (Fly.streamAt or 0) > 8 or not Fly.streamPos or (Fly.streamPos - gpNow).Magnitude > 150) then   -- v148: antes a cada 1.5 s (travadinha periodica)
            Fly.streamAt, Fly.streamBusy, Fly.streamPos = os.clock(), true, gpNow
            local gp = goal.Position
            task.spawn(function()      -- v59: RequestStreamAroundAsync YIELDS: dentro do Heartbeat ele fazia o personagem voltar a posicoes velhas
                pcall(function() LP:RequestStreamAroundAsync(gp, 2) end)
                Fly.streamBusy = false
            end)
        end
        local delta = goal.Position - pos
        local dist = delta.Magnitude
        local aim = delta
        if Fly.cruiseY then
            local hd = Vector3.new(delta.X, 0, delta.Z).Magnitude
            if hd > 150 then
                aim = Vector3.new(delta.X, math.max(Fly.cruiseY - pos.Y, 0), delta.Z)
            else
                Fly.cruiseY = nil
            end
        end
        if dist <= 2.5 then
            hrp.CFrame = goal
            hrp.AssemblyLinearVelocity = Vector3.zero
            Fly.goal = nil
            Fly.settleCF, Fly.settleUntil = goal, os.clock() + 4
            currentTween.PlaybackState = Enum.PlaybackState.Completed
            return
        end
        -- velocidade: Tween Speed (padrao 200); nas viagens longas entre ilhas vale a maior entre ela e a Island Speed
        local spd = Core.speed(Config.TweenSpeed)
        if Fly.boost and os.clock() < (Fly.boostUntil or 0) then spd = math.max(spd, Core.speed(Fly.boost)) end
        if Fly.far then   -- v147: viagem longa mantem a Island Speed ate chegar (antes voltava pra Tween Speed nos ultimos 400 studs)
            spd = math.max(spd, Core.speed(Config.IslandSpeed))
        end
        Fly.phys = true; Core.flightPhys(true)   -- v149
        local np = Core.moveStep(flySt, pos, aim, dist, dt, spd)
        local rot = hrp.CFrame.Rotation:Lerp(goal.Rotation, math.clamp(dt * 8, 0, 1))
        hrp.CFrame = CFrame.new(np) * rot
        hrp.AssemblyLinearVelocity = Vector3.zero
        hrp.AssemblyAngularVelocity = Vector3.zero
    end))
    -- v134: noclip do tween principal (flyTo) em TODO frame, durante a viagem E por 3s depois de chegar. Antes so valia com o
    -- farm ligado (ST.Busy) e a cada 0.35s: pegar fruta/item, subir no barco e ir nas engrenagens da Ilha da Miragem
    -- (que usam o mesmo flyTo) ficavam com colisao no personagem e ele esbarrava/travava em cima do alvo.
    local FlyNcUntil = 0
    table.insert(conns, RunService.Stepped:Connect(function()
        if not alive then return end
        local now = os.clock()
        if Fly.goal then FlyNcUntil = now + 3 end
        if now > FlyNcUntil then return end
        local char = LP.Character
        if not char then return end
        for _, p in ipairs(char:GetDescendants()) do
            if p:IsA("BasePart") and p.CanCollide then p.CanCollide = false end
        end
    end))
    -- noclip + flutuacao enquanto um recurso do Moon antigo controla o personagem
    local NoclipLast = 0
    table.insert(conns, RunService.Stepped:Connect(function()
        if not (alive and ST.Busy) or os.clock() < (TR.SeaSitUntil or 0) then return end
        local char, hrp = getChar()
        if not char then return end
        local now = os.clock()
        if now - NoclipLast > 0.35 then
            NoclipLast = now
            for _, p in ipairs(char:GetDescendants()) do
                if p:IsA("BasePart") then p.CanCollide = false end
            end
        end
        if not hrp:FindFirstChild("FarmHold") then
            local bv = Instance.new("BodyVelocity")
            bv.Name = "FarmHold"
            bv.MaxForce = Vector3.new(1e5, 1e5, 1e5)
            bv.Velocity = Vector3.zero
            bv.Parent = hrp
        end
    end))
    local function releaseChar()
        local _, hrp = getChar()
        if hrp and hrp:FindFirstChild("FarmHold") then hrp.FarmHold:Destroy() end
        currentTween:Cancel()
    end
    PC.Fly, PC.currentTween, PC.releaseChar = Fly, currentTween, releaseChar

    -- --------------------------------------------------------------------- armas ----
    local function findTool(tip)
        local function scan(container)
            if not container then return end
            for _, t in ipairs(container:GetChildren()) do
                if t:IsA("Tool") and t.ToolTip == tip then
                    if not (tip == "Blox Fruit" and string.find(t.Name, "Fruit")) then return t end
                end
            end
        end
        local eq = scan(LP.Character)
        if eq then return eq, true end
        local bp = scan(LP.Backpack)
        if bp then return bp, false end
    end
    local function findToolByName(sub)
        for _, container in ipairs({ LP.Character, LP.Backpack }) do
            if container then
                for _, t in ipairs(container:GetChildren()) do
                    if t:IsA("Tool") and string.find(string.lower(t.Name), sub, 1, true) then
                        return t, container == LP.Character
                    end
                end
            end
        end
    end
    -- escolhe a ferramenta (como o v52) e avisa o motor de ataque do Premium (Core.ov) quando e uma arma "especial"
    local function equipWeapon()
        local char, _, hum = getChar()
        if not char then return end
        if (TR.PayHoldUntil or 0) > os.clock() then return end -- pagando a raid com fruta: a fruta fica na mao
        local tool, equipped
        local spec = TR.SeaTool
        if TR.ForceTool and os.clock() < (TR.ForceUntil or 0) then
            tool, equipped = findToolByName(TR.ForceTool)
            Core.ov = { name = TR.ForceTool, untilT = os.clock() + 1.2 }
        elseif spec and os.clock() < (TR.SeaUntil or 0) then
            if spec.name then tool, equipped = findToolByName(spec.name); Core.ov = { name = spec.name, untilT = os.clock() + 1.2 }
            else tool, equipped = findTool(spec.tip); Core.ov = { tip = spec.tip, untilT = os.clock() + 1.2 } end
        elseif TR.MastName then
            tool, equipped = findToolByName(string.lower(TR.MastName))
            Core.ov = { name = string.lower(TR.MastName), untilT = os.clock() + 1.2 }
        elseif os.clock() < (TR.MastFinishUntil or 0) and TR.MastMethod then
            tool, equipped = findTool(TR.MastMethod)
            Core.ov = { tip = TR.MastMethod, untilT = os.clock() + 1.2 }
        else
            Core.ov = nil
            tool, equipped = findTool(Config.Weapon)
        end
        if tool and not equipped then hum:EquipTool(tool) end
    end
    PC.findTool, PC.findToolByName, PC.equipWeapon = findTool, findToolByName, equipWeapon

    -- ------------------------------------------------------------------ inimigos ----
    local function enemiesList()
        local f = workspace:FindFirstChild("Enemies")
        if not f then return {} end
        local all = f:GetChildren()
        if next(Core.ghosts) == nil then return all end
        local out = {}                                     -- mobs "fantasma" (ver pf1) ficam de fora por uns segundos
        for _, e in ipairs(all) do if not Core.isGhost(e) then out[#out + 1] = e end end
        return out
    end
    local function matchName(enemyName, names)
        for _, n in ipairs(names) do
            if enemyName == n or string.find(enemyName, n, 1, true) == 1 then return true end
        end
        return false
    end
    local function aliveParts(e)
        local eh, er = e:FindFirstChildOfClass("Humanoid"), e:FindFirstChild("HumanoidRootPart")
        if eh and er and eh.Health > 0 then return eh, er end
    end
    -- mesma coisa, mas ignora mob "fantasma" (puxado que o servidor nao reconhece): as farms soltam e seguem em frente
    local function realParts(e)
        if Core.isGhost(e) then return nil end
        return aliveParts(e)
    end
    local Fight = { active = false, expires = 0, standCF = nil, pullCF = nil, mobs = {}, inPos = false, pos = nil, enemy = nil }
    local Aim = { part = nil, on = false, level = false }
    local stickyEnemy = nil
    local function findEnemy(names)
        local _, hrp = getChar()
        if not hrp then return end
        -- v33: fica fixo no alvo que ja estava atacando em vez de trocar so porque surgiu outro mais perto (ex.: um NPC
        -- de quest nao deve "roubar" o foco de quem ja esta sendo batido) - so troca quando o atual morre, sai da lista
        -- de nomes aceitos (ex.: mudou de quest) ou fica absurdamente longe (sumiu/foi pra outro lugar)
        if stickyEnemy and stickyEnemy.Parent and matchName(stickyEnemy.Name, names) then
            local eh, er = realParts(stickyEnemy)
            if eh and (hrp.Position - er.Position).Magnitude <= 600 then
                return stickyEnemy
            end
        end
        stickyEnemy = nil
        if Fight.group and os.clock() < (Fight.groupUntil or 0) then
            local gb, gd = nil, math.huge
            for _, e in ipairs(Fight.group) do
                if e.Parent and matchName(e.Name, names) then
                    local eh, er = realParts(e)
                    if eh then
                        local d = (hrp.Position - er.Position).Magnitude
                        if d < gd then gb, gd = e, d end
                    end
                end
            end
            if gb then stickyEnemy = gb; return gb end
        end
        local best, bestDist = nil, math.huge
        for _, e in ipairs(enemiesList()) do
            if matchName(e.Name, names) then
                local eh, er = realParts(e)
                if eh then
                    local d = (hrp.Position - er.Position).Magnitude
                    if d < bestDist then best, bestDist = e, d end
                end
            end
        end
        stickyEnemy = best
        return best
    end
    local function findSpawn(names)
        local origin = workspace:FindFirstChild("_WorldOrigin")
        local folders = {}
        local f1 = origin and origin:FindFirstChild("EnemySpawns")
        local f2 = workspace:FindFirstChild("EnemySpawns")
        if f1 then table.insert(folders, f1) end
        if f2 then table.insert(folders, f2) end
        local best, bestDist = nil, math.huge
        for _, folder in ipairs(folders) do
            for _, sp in ipairs(folder:GetChildren()) do
                for _, n in ipairs(names) do
                    if string.find(sp.Name, n, 1, true) then
                        local d = distanceTo(sp.CFrame)
                        if d < bestDist then best, bestDist = sp, d end
                    end
                end
            end
        end
        return best
    end
    local function bossAlive(name) return findEnemy({ name }) end
    PC.findEnemy, PC.findSpawn, PC.Fight, PC.Aim = findEnemy, findSpawn, Fight, Aim
    Core.extra = function() return Aim.part end            -- o motor de ataque do Premium bate em Aim.part quando nao ha outro alvo

    -- -------------------------------------------------- luta: voo, mobs puxados, ataque ----
    local Orig = setmetatable({}, { __mode = "k" })
    Fight.WS = setmetatable({}, { __mode = "k" })
    function Fight.limit()
        local ov = Fight.bringMax and os.clock() < (Fight.bringUntil or 0)
        if ov then return math.clamp(math.floor(tonumber(Fight.bringMax) or 2), 1, 10) end
        -- v53: o Bring Mob respeita o numero escolhido em Farm Settings com QUALQUER arma. Antes (v31) com Melee/Sword ele
        -- puxava TODOS os NPCs do alcance de uma vez: o servidor nao acompanhava e eles viravam fantasma (juntava e voltava).
        -- O golpe de Melee/Sword continua acertando todos os NPCs do alcance, mesmo os que nao foram puxados.
        -- v60: "100% igual o bomba": o BringEnemy dele puxa TODOS os mobs no raio (sem limite de quantidade)
        return 40
    end
    function Fight.release(m)
        Core.freeMob(m)   -- v53: tira PlatformStand / V2 e devolve o WalkSpeed
        local eh = m and m.Parent and m:FindFirstChild("Humanoid")
        if eh and Fight.WS[m] then eh.WalkSpeed = Fight.WS[m] end
        -- v31: tira a BodyPosition do Bring Mob V2 geral quando o mob/NPC sai do grupo
        pcall(function()
            local er = m and (m:FindFirstChild("HumanoidRootPart") or m.PrimaryPart)
            local bp = er and er:FindFirstChild("MoonHubBringPos")
            if bp then bp:Destroy() end
        end)
    end
    local function collectBring(main, names, center)
        local list = { main }
        local ov = Fight.bringMax and os.clock() < (Fight.bringUntil or 0)
        local limit = Fight.limit()
        local range = ov and (Fight.bringRange or 350) or 300      -- v60: raio fixo 300 do bomba (a partir do ponto E do personagem)
        local cands = {}
        local _, myHrp = getChar()
        for _, e in ipairs(enemiesList()) do
            if e ~= main and (matchName(e.Name, names) or (Config.KillAll and not matchName(e.Name, Config.KillAllSkip or {}))) then
                local eh, er = realParts(e)
                -- v119: pedido do usuario - "bring mob 100% igual o bomba". O bomba.lua NUNCA agrupa boss (lista
                -- BOSS, ja tirada de la antes) - esse caminho (collectBring, o que REALMENTE roda o Bring Mob das
                -- farms) nao tinha essa trava, so o Core.bring() avulso (sem uso) tinha. Adicionado aqui tambem.
                -- v123: pedido do usuario - "puxando muito NPC fantasma, no bomba nao puxa nenhum". O bomba nao
                -- tem conceito de "fantasma" porque ele simplesmente nao existe la - mas aqui, quando um mob
                -- puxado fica 5s+ sem perder vida enquanto a gente bate (stallScan), ele vira fantasma por 10s
                -- (Core.markGhost). O problema: collectBring continuava ESCOLHENDO esses mesmos fantasmas de
                -- novo (nao tinha esse filtro, so os caminhos antigos/avulsos tinham), gastando as vagas do
                -- Bring Mob com mob que a gente ja sabe que nao vai bater - em vez de ir pro proximo mob valido.
                -- Filtrado aqui tambem, igual aos outros caminhos de puxar mob (linhas 3578/4492/4530/etc).
                if eh and not isBoss(e, eh) and not Core.isGhost(e) then
                    local d = (er.Position - center).Magnitude
                    if d < range and (ov or not myHrp or (er.Position - myHrp.Position).Magnitude <= range) then cands[#cands + 1] = { e, d, er } end
                end
            end
        end
        table.sort(cands, function(a, b) return a[2] < b[2] end)
        for _, c in ipairs(cands) do
            if #list >= limit then break end
            Orig[c[1]] = Orig[c[1]] or c[3].Position
            list[#list + 1] = c[1]
        end
        return list
    end
    local function effHover(canPull)
        local h = math.clamp(tonumber(Config.HoverHeight) or 15, 5, 60)
        if not canPull then h = math.min(h, 15) end
        if canPull and Core.shortTool() then h = math.min(h, 9) end   -- Soco/Espada: o grupo puxado fica a ~9 studs, dentro do alcance do golpe
        return h
    end
    -- liga o ataque do Premium (Core) por 1,5s; os alvos sao forcados para NPC/BOSS (e PLAYER quando o alvo e um jogador)
    local function wantAttack(player)
        PC.atkUntil = os.clock() + 1.5
        Core.force = { NPC = true, BOSS = true, PLAYER = player and true or false }
        Core.forceUntil = os.clock() + 2
        if not Core.attacking then Core.setAttack(true); PC.atkOwned = true end
    end
    PC.wantAttack = wantAttack
    local GUN_DIST = 9
    local function fightEnemy(enemy, names, canPull)
        local eh, er = aliveParts(enemy)
        if not eh then return end
        if cfg.bring == false then canPull = false end   -- v89: Bring Mob unificado
        equipWeapon()
        local isPlayer = Players:GetPlayerFromCharacter(enemy) ~= nil
        if not canPull then ST.bossAt = os.clock() end
        Orig[enemy] = Orig[enemy] or er.Position
        Fight.enemy = enemy
        Fight.names, Fight.namesUntil = names, os.clock() + 4
        local inGroup = false
        if Fight.group and os.clock() < (Fight.groupUntil or 0) and Fight.anchor then
            for _, g in ipairs(Fight.group) do if g == enemy then inGroup = true break end end
        end
        if not inGroup then Fight.anchor = Orig[enemy] end
        -- v73: Orig[enemy] e o lugar onde o alvo foi visto a PRIMEIRA vez (nunca atualiza depois) - se ele andar
        -- longe disso (fugindo, patrulhando, perseguindo o jogador), o personagem ficava flutuando pra sempre
        -- nesse ponto antigo e vazio, enquanto o alvo de verdade estava em outro lugar. Por fora isso aparecia
        -- como "nao acompanha o NPC" (quando o alvo tinha ido pra longe) ou "voa alto demais em cima do NPC"
        -- (quando o alvo tinha saido debaixo do ponto onde o personagem flutua). Agora o anchor acompanha o alvo
        -- quando ele se afasta demais do ponto atual (sem reancorar a cada frame, pra nao sacudir os mobs puxados
        -- com pequenos tremores de posicao).
        if canPull and Fight.anchor and (er.Position - Fight.anchor).Magnitude > 20 then
            Fight.anchor = er.Position
        end
        Fight.pos = Fight.anchor
        local base = canPull and Fight.pos or er.Position
        local h = effHover(canPull)
        local stand = CFrame.new(base + Vector3.new(0, h, 0)) * CFrame.Angles(0, 0, 0)
        -- v58: o grupo puxado fica a ~6 studs abaixo do personagem (antes ficava a 9-15 studs, no chao): mob longe do golpe
        -- era o que "ficava embaixo sem levar dano". So sobe o ponto de puxar; o personagem continua na mesma altura.
        local pullCF = canPull and CFrame.new(base) or nil
        if canPull and inGroup and Fight.fixStand and Fight.fixPull then
            stand, pullCF = Fight.fixStand, Fight.fixPull
        else
            Fight.fixStand, Fight.fixPull = stand, pullCF
        end
        Fight.standCF, Fight.pullCF = stand, pullCF
        local prevMobs = {}
        for _, g in ipairs(Fight.mobs or {}) do prevMobs[g] = true end
        if inGroup then
            local keep = {}
            for _, g in ipairs(Fight.group) do
                if aliveParts(g) then keep[#keep + 1] = g end
            end
            Fight.mobs = keep
            if canPull and #keep < Fight.limit() and os.clock() - (Fight.topAt or 0) > 0.15 then
                Fight.topAt = os.clock()
                local seen = {}
                for _, g in ipairs(keep) do seen[g] = true end
                for _, g in ipairs(collectBring(enemy, names, base)) do
                    if not seen[g] and #Fight.mobs < Fight.limit() then Fight.mobs[#Fight.mobs + 1] = g end
                end
            end
        else
            Fight.mobs = canPull and collectBring(enemy, names, base) or {}
        end
        do
            local lim = Fight.limit()
            local mobsL = Fight.mobs
            while #mobsL > lim and #mobsL > 1 do table.remove(mobsL) end
            local now = {}
            for _, g in ipairs(mobsL) do now[g] = true end
            for g in pairs(prevMobs) do if not now[g] then pcall(Fight.release, g) end end
        end
        Fight.group = canPull and Fight.mobs or nil
        Fight.groupUntil = os.clock() + 2
        Fight.active, Fight.expires = true, os.clock() + 1.0
        Aim.part = er
        local _, hrp = getChar()
        if hrp then
            Fight.inPos = (hrp.Position - stand.Position).Magnitude < 8
            if Fight.inPos then currentTween:Cancel() else flyTo(stand) end
        end
        wantAttack(isPlayer)
        ST.atkAt = os.clock()
        Diag.attack = string.format("fight | height=%s | pulled=%d | in position=%s", tostring(math.floor(h)), #Fight.mobs, tostring(Fight.inPos))
    end
    table.insert(conns, RunService.Heartbeat:Connect(function()
        if not (alive and Fight.active) then return end
        if os.clock() > Fight.expires then
            Fight.active, Fight.inPos = false, false
            -- v53: a luta acabou (ou outra funcao assumiu): solta os mobs puxados (antes ficavam parados no ar)
            for _, g in ipairs(Fight.mobs or {}) do pcall(Fight.release, g) end
            return
        end
        local _, hrp = getChar()
        if not hrp then return end
        if Fight.standCF and (hrp.Position - Fight.standCF.Position).Magnitude < 8 then
            hrp.CFrame = Fight.standCF
            hrp.AssemblyLinearVelocity = Vector3.zero
        end
        if Fight.pullCF and os.clock() - (Fight.simAt or 0) > 0.25 then
            Fight.simAt = os.clock()
            pcall(function() sethiddenproperty(LP, "SimulationRadius", 500) end)   -- v60: igual o bomba (500, nao infinito)
        end
        if Fight.pullCF then
            for _, m in ipairs(Fight.mobs) do
                local eh2, er2 = aliveParts(m)
                if eh2 and Core.pullOK(m, er2, Orig[m]) then
                    if Fight.WS[m] == nil and eh2.WalkSpeed > 0 then Fight.WS[m] = eh2.WalkSpeed end
                    -- v53: mesmo puxao do Core (V1 = teleporte, V2 = BodyPosition), que tambem sabe soltar depois
                    Core.pullMob(m, er2, eh2, Fight.pullCF)
                end
            end
        end
    end))
    -- v54: segura os mobs puxados tambem antes da fisica (Stepped)
    table.insert(conns, RunService.Stepped:Connect(function()
        if not (alive and Fight.active and Fight.pullCF) or os.clock() > Fight.expires then return end
        for _, m in ipairs(Fight.mobs) do
            local eh2, er2 = aliveParts(m)
            if eh2 and not Core.isGhost(m) then Core.pullMob(m, er2, eh2, Fight.pullCF) end
        end
    end))
    PC.fightEnemy = fightEnemy

    -- ------------------------------------------------------------------- quests ----
    local EliteNames = { "Deandre", "Urban", "Diablo" }
    local EliteS = { travelSince = 0, pauseUntil = 0 }
    local QuestGui
    local function findQuestGui()
        if QuestGui and QuestGui.Parent then return QuestGui end
        local pg = LP:FindFirstChild("PlayerGui")
        local main = pg and pg:FindFirstChild("Main")
        if main then QuestGui = main:FindFirstChild("Quest") or main:FindFirstChild("Quest", true) end
        return QuestGui
    end
    local function questVisible()
        local q = findQuestGui()
        if not q then return false, false end
        return q.Visible == true, true
    end
    local function activeQuestTitle()
        local q = findQuestGui()
        if not q then return nil end
        local t = q:FindFirstChild("QuestTitle", true)
        if not t then return nil end
        local label = t:FindFirstChild("Title") or t
        if label:IsA("TextLabel") then return label.Text end
    end
    local function isEliteTitle(title)
        if not title then return false end
        for _, n in ipairs(EliteNames) do
            if string.find(title, n, 1, true) then return true end
        end
        return false
    end

    -- --------------------------------------------------------------- Dough/Sub (v52) ----
    local DHF = {}
    function DHF.inSub() local _, hrp = getChar(); return hrp ~= nil and hrp.Position.Y <= -500 end
    function DHF.leaveSub()
        if not DHF.inSub() then
            if DHF.wasSub then                          -- acabou de sair: solta o personagem (o LV segurava ele)
                DHF.wasSub = false
                if LV and LV.release and not (Core.farms["Farm Level"] and Core.farms["Farm Level"].want()) then pcall(LV.release) end
            end
            return false
        end
        DHF.wasSub = true
        if LV and LV.leaveSub then pcall(LV.leaveSub); LV.active = true; return true end
        return false
    end

