    -- v26: entra direto num servidor listado pela API do Quantum (chave do boss em minusculo). Sem lista -> hop normal (mesmo sistema do Auto Bounty).
    local QAPI, QSECRET, QALPHA = "https://api.quantumonyx.cc", "QnTmOnyX", "kQ9mZ2xW7nR4vB1jY6tF3hD8pL5cG0sA"
    local function qDecode(arg)
        local s0 = tostring(arg):gsub("^%.", ""):gsub("%.$", "")
        local t, n = {}, 0
        for i = 1, #s0 do n += 1; if n % 5 ~= 0 then t[#t + 1] = s0:sub(i, i) end end
        local s2 = table.concat(t)
        local out, a, b = {}, 1, 1
        local function f3(x, y) return (x - QSECRET:byte((y - 1) % #QSECRET + 1) - y) % 32 end
        while a <= #s2 do
            local i1, i2 = QALPHA:find(s2:sub(a, a), 1, true), QALPHA:find(s2:sub(a + 1, a + 1), 1, true)
            if not i1 or not i2 then return "" end
            out[#out + 1] = string.char(f3(i1 - 1, b) + f3(i2 - 1, b + 100) * 32)
