        local QMo = AFL.QMoon
        local m = QMo.num(e, QMo.MIN)
        if not m then local sc = QMo.num(e, QMo.SEC); if sc then m = sc / 60 end end
        if not m then return nil end
        local ts = QMo.num(e, QMo.TS)
        if ts then
            if ts > 1e12 then ts = ts / 1000 end
            local age = os.time() - ts
            if age >= 0 and age < 7200 then m = m - age / 60 end
        end
        return m
    end
    -- mn/mx: janela em minutos | check(): true se ESTE servidor ja serve (para parar de procurar)
    function AFL.apiJoinMoon(mn, mx, check)
        local Q, M = AFL.QApi, AFL.QMoon
        if AFL.Hop.active or Q.joining or os.clock() - Q.last < 8 then return true end
        Q.joining, Q.last = true, os.clock()
        task.spawn(function()
            local cur = game.JobId
            local reqf = (syn and syn.request) or http_request or (http and http.request) or request or httprequest
            if reqf then
                pcall(function()
                    local tol = (mx - mn) < 2 and 1.5 or 0.5     -- o dado da API e antigo: tolerancia maior; o teste final e local
                    local ids = {}
                    for _, key in ipairs(M.goodKey and { M.goodKey } or M.keys) do
                        local done, res = false, nil
                        task.spawn(function()
                            local okR, r = pcall(function() return reqf({ Url = QAPI .. "/api/logs/" .. key:lower(), Method = "GET", Headers = { ["Content-Type"] = "application/json" } }) end)
                            if okR then res = r end
                            done = true
                        end)
                        local t0 = os.clock()
                        while not done and alive and os.clock() - t0 < 8 do task.wait(0.1) end
                        if res and res.StatusCode == 200 then
                            local okJ, dec = pcall(function() return HttpService:JSONDecode(res.Body) end)
                            local entries = okJ and type(dec) == "table" and (dec[key:lower()] or dec[key] or dec.data or dec.logs or (dec[1] ~= nil and dec)) or nil
                            if type(entries) == "table" and #entries > 0 then
                                M.goodKey, M.raw = key, tostring(res.Body):sub(1, 240)
                                for i = #entries, 1, -1 do   -- mais novo primeiro
                                    local e = entries[i]
                                    if type(e) == "table" and e.jobId and e.jobId ~= "" and (not e.placeId or tostring(e.placeId) == tostring(game.PlaceId)) then
                                        local j = qDecode(e.jobId)
                                        if j ~= "" and j ~= cur and not (AFL.Visited[j] and os.clock() - AFL.Visited[j] < 900) then
                                            local m = M.minutesNow(e)
                                            local score
                                            if m == nil then score = 500                                         -- v58: a lista da API so tem servidores de lua cheia ATIVA (sem tempo): serve! Entra em lua cheia ja ativa, nao so em near full moon
                                            elseif m <= 0 then score = 500   -- lua ja ativa (v58: sempre aceita)
                                            elseif m >= mn - tol and m <= mx + tol then score = math.abs(m - (mn + mx) / 2)
                                            end
                                            if score then ids[#ids + 1] = { id = j, score = score, n = i } end
                                        end
                                    end
                                end
                                break
                            end
                        end
                    end
                    table.sort(ids, function(a, b) if a.score ~= b.score then return a.score < b.score end return a.n > b.n end)
                    if #ids == 0 then error("none") end
                    pcall(persist); pcall(AFL.writeResume); pcall(AFL.queueReload)
                    local maxTry = math.min(#ids, 10)   -- v58: mais tentativas na lista da API (antes 5)
                    for i = 1, maxTry do
                        if not alive or game.JobId ~= cur or (check and check()) then break end
                        AFL.Visited[ids[i].id] = os.clock()
                        Q.msg = string.format("Joining a full moon server (%d/%d) [%s]", i, maxTry, tostring(M.goodKey))
                        Diag.fight = Q.msg
                        AFL.tpJob(ids[i].id, 5)
                    end
                end)
            end
            if not alive then Q.joining = false return end
            if game.JobId == cur and not (check and check()) then
                Q.msg = "No usable full moon server in the API list: normal server hop"
                if not AFL.Hop.active then AFL.hopRequest("Near full moon", check, 1) end
            end
            Q.joining = false
        end)
        return true
    end
    -- Elite Hunter + Hop: so troca de servidor quando o Elite NAO esta no servidor e nao falta pouco para ele nascer
    function AFL.eliteHopTick(force)
        if not ({ [7449423635] = true, [100117331123089] = true })[game.PlaceId] then Diag.elite = "Elite Hop: Third Sea only"; return end
        if not force and E.hasItem("God's Chalice") then Diag.elite = "has God's Chalice: not changing server"; return end
        local Es = AFL.EliteHopState
        if not Es then Es = { since = nil }; AFL.EliteHopState = Es end
        if AFL.Hop.active or os.clock() - AFL.Hop.serverAt < 20 then return end
        local present = E.findEnemy(E.EliteNames)
        if not present then
            for _, n in ipairs(E.EliteNames) do if RS:FindFirstChild(n) then present = true break end end
        end
        local visible, known = E.questVisible()
        if present or (known and visible and E.isEliteTitle(E.activeQuestTitle())) or not E.EliteS.unavailAt then
            Es.since = nil
            return
        end
        Es.since = Es.since or os.clock()
        local remain = E.EliteS.remain
        if remain and remain <= 120 then
            Diag.elite = string.format("Elite spawns in ~%ds: not changing server", remain)
            return
        end
        if not remain and os.clock() - E.EliteS.unavailAt < 150 then return end
        AFL.hopRequest("Elite Hunter", function()
            local pr = E.findEnemy(E.EliteNames)
            return pr ~= nil or (E.EliteS.remain ~= nil and E.EliteS.remain <= 120)
        end)
    end
    -- Collect Fruit + Hop: sem fruta no chao ha alguns segundos -> troca de servidor
    -- v27: so troca de servidor (mesmo AFL.hopRequest do Auto Bounty) depois de rodar o mapa inteiro sem achar fruta
    function AFL.fruitHopTick()
        if not Config.CollectHop or AFL.Hop.active or os.clock() - AFL.Hop.serverAt < 15 then return end
        AFL.hopRequest("no fruits in the whole map", function() return AFL.findGroundFruit and AFL.findGroundFruit() ~= nil end)
    end
    E.findGroundFruit = function() if AFL.findGroundFruit then return AFL.findGroundFruit() end end

    -- ------------------------------------------- mira das skills (Mouse.Hit) -------------------
    -- Os modulos (Mastery, Kitsune, Leviathan, Mirage...) apontam skills para AFL.TV.aimPos. O hook so e instalado quando alguem pede.
    AFL.TV = { aimPos = nil, aimPart = nil, hooked = false, done = 0 }
    function AFL.tvHook()
        local V = AFL.TV
        if V.hooked or not hookmetamethod then return end
        V.hooked = true
        local mouse = LP:GetMouse()
        local wrap = newcclosure or function(f) return f end
        local old
        local ok = pcall(function()
            old = hookmetamethod(game, "__index", wrap(function(self, key)
                if self == mouse and alive and V.aimPos and not (checkcaller and checkcaller()) then
                    if key == "Hit" then return CFrame.new(V.aimPos) end
                    if key == "Target" then return V.aimPart end
                end
                return old(self, key)
            end))
        end)
        if not ok then V.hooked = false end
    end

    -- v54: mira do clique de fruta. So mexe na mira quando ninguem mais esta usando (skills do Vulcan/Mastery/Sea tem prioridade)
    -- e solta sozinha 0,25 s depois do ultimo clique.
    -- v54: tiro de Gun por remote (RE/ShootGunEvent, mesmo do Sea Events) quando o modulo que sabe atirar ja esta carregado
    Core.gunShot = function(part)
        local f = rawget(PC.Config, "ShotFire") or PC.Config.ShotFire
        if type(f) == "function" then f({ kind = "gun", part = part }) end
    end
    Core.fruitAim = function(pos, part)
        local V = AFL.TV
        if V.aimPos ~= nil and V.aimPos ~= V.fruitPos then return end
        pcall(AFL.tvHook)
        V.aimPos, V.aimPart, V.fruitPos, V.fruitUntil = pos, part, pos, os.clock() + 0.25
    end
    table.insert(PC.Connections, RunService.Heartbeat:Connect(function()
        local V = AFL.TV
        if V.fruitPos and os.clock() > (V.fruitUntil or 0) then
            if V.aimPos == V.fruitPos then V.aimPos, V.aimPart = nil, nil end
            V.fruitPos = nil
        end
    end))
    -- eventos (Awakened boss, Mirage...) viram aviso no webhook pessoal, se o usuario configurou
    FX.uw = function(title, text)
        local uw = rawget(AFL, "UW")
        if uw then pcall(uw.event, title, text) end
    end

