    -- catalogo de prioridades: legados (ordem do v52) + farms nativas do Premium
    do
        local cat = Core.catalog
        local NEW = { "Auto Bounty" }
        for _, key in ipairs(FEATORDER) do NEW[#NEW + 1] = FEAT[key].label end
        for _, n in ipairs({ "Farm Level", "Farm Bones", "Cake Prince" }) do NEW[#NEW + 1] = n end
        for i = #cat, 1, -1 do cat[i] = nil end
        for i, n in ipairs(NEW) do cat[i] = n end
