            local f = FEAT[key]
            f.key = key
            AFL.feat[key] = f
            Core.farms[f.label] = { legacy = f, key = key, want = function() return Core.owner == f.label end }
        end
        if cfg.prioVer ~= 3 then cfg.prio = false; cfg.prioVer = 3 end     -- ordem nova (funcoes do Moon antigo na frente do Level Farm)
        -- v44: Core.ensurePrio() refaz o preenchimento automatico dos slots (cfg.prioAutoFilled) sozinho sempre que
        -- chamado de novo e o jogador ainda nao tiver mudado nada na UI - entao esta chamada, ja com o catalogo
        -- COMPLETO (FEATORDER + nativos), e o que garante que os slots padrao usem a lista final, nao so os 8 itens
        -- nativos que existiam quando pf1/pf2 chamaram isso durante a montagem da UI.
        Core.ensurePrio()
        if Core.renderPrio then pcall(Core.renderPrio) end
    end

    local function featOn(key, f)
        if (AFL.Err.quar[key] or 0) > os.clock() then return false end
        local ok, r = pcall(f.on)
        if not ok then AFL.logErr(key, "on(): " .. tostring(r)); return false end
        return r and true or false
    end
    local function featRun(key, f)
        local ok, r = pcall(f.run)
        if ok then AFL.Err.count[key] = 0; return r end
        local c = (AFL.Err.count[key] or 0) + 1
        AFL.Err.count[key] = c
        AFL.logErr(key, r)
        if c >= 3 then
            AFL.Err.quar[key] = os.clock() + 30
            AFL.Err.count[key] = 0
            AFL.logErr(key, "failed 3 times in a row: paused for 30s (the other functions keep running)")
        end
        return false
    end
    AFL.featOn, AFL.featRun = featOn, featRun
    Core.legacyOn = featOn   -- v54b: as prioridades usam isto pra saber o que esta ligado

    -- ---------------------------------------------------- "ir ate o NPC e fazer algo" ----
    -- AFL.goDo(nome, pos, acao): voa ate pos (Vector3 ou funcao que devolve Vector3), roda acao() la e solta o personagem.
    -- E uma funcao FIXA do arbitro (nao entra na lista de prioridade): passa na frente de tudo, menos do Safe Mode.
    -- Usada pela aba Shop (estilos de luta, Barista...) e pelo Draco/Dojo.
    local MAINP = { [2753915549] = true, [85211729168715] = true, [4442272183] = true, [79091703265657] = true, [7449423635] = true, [100117331123089] = true }
    local function goNotify(txt) pcall(function() E.Fluent:Notify({ Title = "Moon Hub", Content = txt, Duration = 4 }) end) end
    function AFL.goDo(name, pos, act, radius)
        if not MAINP[game.PlaceId] then goNotify("This only works in the three seas (you are somewhere else)") return false end
        Config.GoTask = { name = name, pos = pos, act = act, radius = radius }
        goNotify("Flying to " .. name .. "...")
        return true
    end
    function AFL.goStop()
        Config.GoTask = nil
        pcall(function() E.currentTween:Cancel() end)
    end
    local function goStep()
        local g = Config.GoTask
        if type(g) ~= "table" then return false end
        if not MAINP[game.PlaceId] then Config.GoTask = nil return false end
        local _, hrp = getChar()
        if not hrp then return false end
        local now = os.clock()
        ST.Mode = "Go To NPC"
        if g.acting then
            ST.Text = "At " .. g.name
            if now - g.acting > 14 then Config.GoTask = nil end
            return true
        end
        g.t0 = g.t0 or now
        if now - g.t0 > 100 then
            Config.GoTask = nil
            pcall(function() E.currentTween:Cancel() end)
            goNotify("Could not reach " .. g.name .. " (took too long)")
            return false
        end
        local pos = g.pos
        if type(pos) == "function" then
            local ok, p = pcall(pos)
            pos = ok and p or nil
        end
        if typeof(pos) ~= "Vector3" then
            Config.GoTask = nil
            goNotify(g.name .. ": not found in this server")
            return false
        end
        ST.Text = "Flying to " .. g.name
        if (hrp.Position - pos).Magnitude > (g.radius or 6) then
            E.flyTo(CFrame.new(pos))
            return true
        end
        pcall(function() E.currentTween:Cancel() end)
        g.acting = now
        ST.Text = "At " .. g.name
        task.spawn(function()
            local ok, e = pcall(g.act)
            if not ok then AFL.logErr("go " .. tostring(g.name), e) end
            if Config.GoTask == g then Config.GoTask = nil end
        end)
        return true
    end
    local GOFEAT = { label = "Go To NPC", on = function() return Config.GoTask ~= nil end, run = goStep }

    -- --------------------------------------------------------------------- arbitro ----
    Core.gtext = Core.gtext or {}
    Core.currentOld = Core.current
    function Core.current()
        if PC.arbOn then return Core.owner end
        return Core.currentOld()
    end
    local function stopAttackIfOwned()
        if PC.atkOwned and os.clock() > PC.atkUntil then
            PC.atkOwned = false
            if Core.attacking and not (LV and LV.attackOwned) then pcall(Core.setAttack, false) end
            Core.force, Core.ov = nil, nil
        end
    end
    -- o Level Farm do Premium precisa da Submerged Island? (nesse caso nenhuma funcao antiga tira o personagem de la)
    local function lvNeedsSub()
        local e = LV and LV.on and LV.entry
        return e and e.sp and e.sp[1] and tonumber(e.sp[1][2]) and e.sp[1][2] <= -500 or false
    end
    local function tick()
        local owner, legacy = nil, false
        if getChar() then
            ST.Busy = false
            local bossBusy = os.clock() - (ST.bossAt or 0) < 1.5
            local R = rawget(AFL, "Raid")
            local raidOwns = bossBusy and R and (os.clock() - (R.fightAt or 0) < 1.5)
            local order = Core.priorityOrder()
            -- Safe Mode vem sempre na frente (vida baixa = nada mexe no personagem)
            local safe = AFL.feat.Safe
            local HB = rawget(AFL, "HalEvent")
            local bossFirst = false
            if HB and HB.bossWants then local okB, wB = pcall(HB.bossWants); bossFirst = okB and wB or false end
            if safe and Config.SafeMode and featOn("Safe", safe) and featRun("Safe", safe) then
                ST.Busy, owner, legacy = true, "Safe Mode", true
            elseif bossFirst and featOn("HalEvent", FEAT.HalEvent) and featRun("HalEvent", FEAT.HalEvent) then
                -- Auto Kill Halloween Bosses: do portal ate o ultimo golpe, nada passa na frente
                ST.Busy, owner, legacy = true, FEAT.HalEvent.label, true
            elseif featOn("Go", GOFEAT) and featRun("Go", GOFEAT) then
                ST.Busy, owner, legacy = true, GOFEAT.label, true
            else
                -- com a ilha do Vulcan em andamento, o Vulcan passa na frente de tudo
                local V = PC.loaded.mv and rawget(AFL, "Vulc")
                local okE, eng = false, false
                if V and V.engaged then okE, eng = pcall(V.engaged) end
                if okE and eng then
                    for i, n in ipairs(order) do if n == FEAT.Vulcan.label then table.remove(order, i) break end end
                    table.insert(order, 1, FEAT.Vulcan.label)
                end
                -- Halloween (porta/boss/evento ativo) passa na frente das outras farms (Pirate Raid, Sea Events, Elite...), menos Dungeon/Raid em andamento
                local HE = rawget(AFL, "HalEvent")
                if HE and HE.wants and (Config.HalEvent or Config.HalBoss or Config.HalGreat) then
                    local okW, wants = pcall(HE.wants)
                    if okW and wants then
                        local lab = FEAT.HalEvent.label
                        for i, n in ipairs(order) do if n == lab then table.remove(order, i) break end end
                        local pos = (okE and eng) and 2 or 1
                        while order[pos] == FEAT.Dungeon.label or order[pos] == FEAT.Raid.label do pos += 1 end
                        table.insert(order, pos, lab)
                    end
                end
                -- v145: Farm Mastery (1 arma) passa na frente: o golpe final com Gun/Fruta so rodava quando "Auto Mastery 600" estava ACIMA da farm na
                -- lista de prioridade (senao a farm "ocupava" todo tick e a Mastery nunca atacava = "nao usa os ataques / nao mira no NPC").
                -- Ela so assume quando ha mob com pouca vida por perto (M.tick devolve false nos outros casos).
                local mastDone = false
                if Config.MastOn and FEAT.Mastery and featOn("Mastery", FEAT.Mastery) then
                    local okM, rM = pcall(function() return AFL.Mast and AFL.Mast.tick and AFL.Mast.tick() end)
                    if okM and rM then ST.Busy, owner, legacy, mastDone = true, FEAT.Mastery.label, true, true end
                end
                local inSub = E.DHF.inSub()
                for _, label in ipairs(mastDone and {} or order) do
                    local f = Core.farms[label]
                    if f then
                        if f.legacy then
                            local lf, key = f.legacy, f.key
                            if not (lf.boss and bossBusy and not (key == "Raid" and raidOwns)) and featOn(key, lf) then
                                -- na Submerged Island sem precisar dela: sai primeiro (como o Moon antigo)
                                if inSub and not lvNeedsSub() and E.DHF.leaveSub() then
                                    ST.Busy, owner, legacy = true, "Leaving the Submerged Island", true
                                    ST.Mode, ST.Text = "Leaving the Submerged Island", "Flying to the exit"
                                    break
                                end
                                if featRun(key, lf) then
                                    ST.Busy, owner, legacy = true, label, true
                                    break
                                end
                            end
                        elseif f.want and f.want() then
                            owner = label
                            break
                        end
                    end
                end
            end
        else
            ST.Busy = false
        end
        Core.owner = owner
        if owner and legacy then Core.gtext[owner] = { text = ST.Text } end
        -- uma farm nativa (Level/Bones/Cake Prince) assumiu: devolve o controle do ataque e das armas para ela
        if owner and not legacy and PC.atkOwned then
            PC.atkOwned = false
            Core.force, Core.ov = nil, nil
            if Core.attacking and not (LV and LV.attackOwned) then pcall(Core.setAttack, false) end
        end
        if not ST.Busy then
            ST.Mode, ST.Text = "Idle", "—"
            PC.Aim.part, PC.Fight.active, PC.Fight.inPos = nil, false, false
            PC.releaseChar()
        end
        if not Config.AutoGacha then
            local g = rawget(AFL, "Gacha")
            if g then g.phase = "idle" end
        end
        stopAttackIfOwned()
    end
    PC.arbOn = true
    local function runLoop(epoch)
        while alive and epoch == ST.epoch do
            task.wait(0.12)
            ST.loopAt = os.clock()
            local ok, err = pcall(tick)
            if not ok then
                warn("[Moon Hub] arbiter: " .. tostring(err))
                Diag.fight = "ERROR: " .. tostring(err)
            end
        end
    end
    task.spawn(runLoop, ST.epoch)
    -- supervisor: se o laco travar (remote sem resposta), inicia outro
    task.spawn(function()
        while alive do
            task.wait(4)
            if os.clock() - (ST.loopAt or os.clock()) > 15 then
                ST.epoch += 1
                ST.loopAt = os.clock()
                task.spawn(runLoop, ST.epoch)
                Diag.fight = "supervisor: the main loop froze; restarted"
            end
        end
    end)
    PC.onUnload(function() PC.arbOn = false; ST.epoch += 1 end)

    -- anti-AFK / reconexao ja existem no Script Settings do Premium (FX)
end)()


-- ================= adaptador de interface (Fluent -> Moon Hub Premium) + carregador de modulos sob demanda ====
-- Os modulos do Moon antigo montam a interface com Tabs.X:AddToggle / AddDropdown / AddSlider / AddInput / AddButton / AddParagraph.
-- Aqui esses metodos viram os componentes do Premium. Cada aba nova so monta o conteudo quando e aberta (ou quando algo dela
-- esta ligado na config salva), entao o script continua leve.
;(function()
    local Core, AFL, M = PC.Core, PC.AFL, PC.M
    local E = PC.env
    local Fluent = E.Fluent
    local Tabs = {}
    E.Tabs = Tabs
    PC.Tabs = Tabs

    -- ------------------------------------------------------------------ icones ----
    -- v92: lista bem mais detalhada, pra parar de repetir sempre os mesmos ~10 icones genericos (gauge/eye/check em
    -- tudo). Ordem importa (o primeiro que casar ganha), entao entradas mais especificas vem antes das mais genericas.
    -- Usa SO icones que ja existem e ja estao testados no ICON table - nunca um ID novo que eu nao tenha certeza que
    -- existe no Roblox (icone quebrado/em branco seria pior do que repetido).
    local KW = {
        -- redes/sincronia (novo, v92: Multi Account / webhook) - "wifi" tava sem uso nenhum
        { "sync", "wifi" }, { "multi account", "wifi" }, { "discord", "link" }, { "webhook", "link" }, { "url", "link" }, { "mention", "bell" }, { "ping", "bell" },
        { "hop", "repeatI" }, { "server", "wifi" }, { "network", "wifi" }, { "refresh", "refresh" }, { "reroll", "refresh" }, { "update", "refresh" }, { "re-run", "refresh" },
        -- movimento / velocidade
        { "teleport", "rocket" }, { "fly", "rocket" }, { "tween", "rocket" }, { "travel", "rocket" }, { "speed", "rocket" }, { "island", "rocket" }, { "launch", "rocket" },
        -- combate / chefes
        { "boss", "crown" }, { "kill", "crown" }, { "elite", "crown" }, { "tyrant", "crown" }, { "awak", "crown" }, { "draco", "crown" }, { "leviathan", "crown" },
        { "fruit", "flame" }, { "gacha", "flame" }, { "vulcan", "flame" }, { "volcano", "flame" }, { "fire", "flame" }, { "burn", "flame" },
        { "sword", "wrench" }, { "melee", "wrench" }, { "gun", "wrench" }, { "cdk", "wrench" }, { "ttk", "wrench" }, { "yama", "wrench" }, { "tushita", "wrench" }, { "weapon", "wrench" },
        -- interface / texto
        { "key", "keyboard" }, { "skill", "keyboard" }, { "name", "keyboard" }, { "rename", "keyboard" }, { "code", "code" }, { "redeem", "gift" }, { "gift", "gift" },
        -- progresso / numeros
        { "status", "gauge" }, { "quest", "gauge" }, { "mastery", "gauge" }, { "level", "gauge" }, { "health", "gauge" }, { "report", "gauge" }, { "summary", "gauge" }, { "progress", "gauge" }, { "ui scale", "gauge" },
        { "time", "clock" }, { "delay", "clock" }, { "wait", "clock" }, { "cooldown", "clock" }, { "interval", "clock" }, { "uptime", "hourglass" }, { "every", "hourglass" },
        -- visao / deteccao
        { "esp", "eye" }, { "visible", "eye" }, { "fov", "eye" }, { "highlight", "eye" }, { "range", "eye" }, { "distance", "eye" }, { "hide", "eyeoff" }, { "stealth", "eyeoff" },
        -- pessoas
        { "pvp", "users" }, { "player", "users" }, { "team", "users" }, { "friend", "users" }, { "join", "users" }, { "race", "users" }, { "account", "users" },
        -- seguranca
        { "safe", "shield" }, { "protect", "shield" }, { "dungeon", "shield" }, { "lock", "shield" }, { "anti", "power" }, { "afk", "power" },
        { "raid", "flask" }, { "chip", "flask" },
        { "boat", "fog" }, { "ship", "fog" }, { "sea", "fog" },
        { "chest", "star" }, { "secret", "star" }, { "mirage", "star" }, { "moon", "star" }, { "drop", "star" }, { "loot", "star" }, { "reward", "star" },
        { "notify", "bell" }, { "alert", "bell" }, { "message", "bell" }, { "error", "bug" }, { "bug", "bug" }, { "fail", "bug" }, { "crash", "bug" },
        -- script/performance
        { "mobile", "monitor" }, { "phone", "monitor" }, { "fps", "cpu" }, { "perf", "cpu" }, { "optimi", "cpu" }, { "lite", "cpu" }, { "light", "cpu" },
        { "theme", "palette" }, { "color", "palette" }, { "custom", "palette" },
        { "test", "finger" }, { "tap", "finger" }, { "click", "finger" },
        { "clear", "minus" }, { "remove", "minus" }, { "delete", "minus" }, { "stop", "minus" },
        { "profile", "save" }, { "save", "save" }, { "config", "save" }, { "copy", "copy" },
    }
    local function pickIcon(title, def)
        local low = string.lower(tostring(title))
        for _, kv in ipairs(KW) do
            if string.find(low, kv[1], 1, true) then return ICON[kv[2]] end
        end
        return ICON[def] or ICON.check
    end
    local BTN = { { "teleport", "Go" }, { "go to", "Go" }, { "refresh", "Refresh" }, { "reload", "Refresh" }, { "stop", "Stop" }, { "cancel", "Stop" }, { "start", "Start" },
        { "copy", "Copy" }, { "clear", "Clear" }, { "reset", "Reset" }, { "save", "Save" }, { "join", "Join" }, { "spawn", "Spawn" }, { "buy", "Buy" },
        { "test", "Test" }, { "send", "Send" }, { "scan", "Scan" } }
    local function btnLabel(title)
        local low = string.lower(tostring(title))
        for _, kv in ipairs(BTN) do
            if string.sub(low, 1, #kv[1]) == kv[1] then return kv[2] end
        end
        return "Run"
    end

    -- ------------------------------------------------------------------ objeto da aba ----
    local TabObj = {}
    TabObj.__index = TabObj

    local function fire(list, v, id)
        for i = 1, #list do
            local ok, e = pcall(list[i], v)
            if not ok then AFL.logErr("ui " .. tostring(id), e) end
        end
    end
    local function mkOpt(id, o, kind)
        local obj = { Value = nil, _cb = {}, Type = kind, Id = id }
        if type(o.Callback) == "function" then obj._cb[1] = o.Callback end
        function obj:OnChanged(f) if type(f) == "function" then self._cb[#self._cb + 1] = f end return self end
        function obj:SetTitle() end
        function obj:SetDesc() end
        function obj:Destroy() end
        if id then Fluent.Options[id] = obj end
        return obj
    end
    local function isVisible(tab)
        local ok, v = pcall(function() return tab.t.page.Visible end)
        return (not ok) or v
    end
    function TabObj:_next() self.n = self.n + 1; return self.n end
    function TabObj:_flush()
        local p = self.pend
        self.pend = {}
        for obj in pairs(p) do
            local ok, e = pcall(function()
                if obj._pt ~= nil then obj._para.setTitle(obj._pt); obj._pt = nil end
                if obj._pd ~= nil then obj._para.setDesc(obj._pd); obj._pd = nil end
                if obj._fl then obj._fl() end
            end)
            if not ok then AFL.logErr("ui paragraph", e) end
        end
    end
    -- a descricao cabe na linha (ate 2 linhas)? se nao, vai como legenda embaixo do controle (caixa que cresce sozinha)
    local function slot(self, desc, px)
        local order = self:_next()
        if desc and desc ~= "" and ORG.lines(desc, px + (54 - ORG.tx)) > 2 then
            local box = new("Frame", { Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1, BorderSizePixel = 0, LayoutOrder = order, ZIndex = 4 }, self.body)
            list(box, 4)
            local cap = text(box, { Size = UDim2.new(1, 0, 0, 14), AutomaticSize = Enum.AutomaticSize.Y, Text = desc, TextSize = 11, Font = Enum.Font.Gotham,
                TextColor3 = C.dim, TextWrapped = true, TextYAlignment = Enum.TextYAlignment.Top, LayoutOrder = 2, ZIndex = 5 })
            pad(cap, ORG.tx - 40, 0, 8, 2)
            return box, 1, nil
        end
        return self.body, order, desc
    end

    function TabObj:AddSection(title)
        local f = section(self.body, tostring(title or ""), self:_next())
        return { Frame = f, Destroy = function() pcall(function() f:Destroy() end) end }
    end

    -- sub-titulo pequeno dentro de uma secao (ex.: Sea Events -> Farm / Boat / Zones & Events). Nao dobra sozinho: fica dentro da secao.
    function TabObj:AddSubSection(title)
        local f = new("Frame", { Size = UDim2.new(1, 0, 0, 24), BackgroundTransparency = 1, LayoutOrder = self:_next(), ZIndex = 4 }, self.body)
        local mark = new("Frame", { Size = UDim2.fromOffset(3, 12), Position = UDim2.fromOffset(6, 7), BorderSizePixel = 0, ZIndex = 5 }, f)
        corner(mark, 2); bind(mark, "BackgroundColor3", "acc")
        text(f, { Position = UDim2.fromOffset(18, 0), Size = UDim2.new(1, -18, 1, 0), Text = tostring(title or ""), TextSize = 12, TextColor3 = C.dim, ZIndex = 5 })
        ORG.isSub[f] = true
        return { Frame = f, Destroy = function() pcall(function() f:Destroy() end) end }
    end

    function TabObj:AddParagraph(o)
        o = o or {}
        local para = UIX.para(self.body, tostring(o.Title or ""), tostring(o.Content or ""), self:_next())
        local tab, obj = self, { _para = para }
        function obj:SetDesc(t)
            if isVisible(tab) then para.setDesc(t); self._pd = nil
            else self._pd = tostring(t or ""); tab.pend[self] = true end
        end
        function obj:SetTitle(t)
            if isVisible(tab) then para.setTitle(t); self._pt = nil
            else self._pt = tostring(t or ""); tab.pend[self] = true end
        end
        function obj:Destroy() tab.pend[self] = nil; pcall(function() para.row:Destroy() end) end
        return obj
    end

    function TabObj:IsVisible() return isVisible(self) and true or false end

    -- v24: cartoes vivos. Set(...) so mexe na tela quando a aba esta aberta (se estiver fechada guarda o ultimo valor e aplica ao abrir)
    function TabObj:AddStatus(o)
        o = o or {}
        local ctl = UIX.status(self.body, tostring(o.Title or ""), tostring(o.Content or ""), self:_next(), o.Height)
        local tab, obj = self, { Row = ctl.row }
        function obj:Set(state, t, s, p)
            if isVisible(tab) then self._a = nil; ctl.set(state, t, s, p)
            else self._a = { state, t, s, p }; tab.pend[self] = true end
        end
        obj._fl = function() local a = obj._a; if a then obj._a = nil; ctl.set(a[1], a[2], a[3], a[4]) end end
        function obj:Destroy() tab.pend[self] = nil; pcall(function() ctl.row:Destroy() end) end
        return obj
    end
    function TabObj:AddProgress(o)
        o = o or {}
        local title = tostring(o.Title or "")
        local ctl = UIX.progress(self.body, pickIcon(title, "gauge"), title, o.Description and tostring(o.Description) or nil, self:_next())
        local tab, obj = self, { Row = ctl.row }
        function obj:Set(cur, max, s)
            if isVisible(tab) then self._a = nil; ctl.set(cur, max, s)
            else self._a = { cur, max, s }; tab.pend[self] = true end
        end
        obj._fl = function() local a = obj._a; if a then obj._a = nil; ctl.set(a[1], a[2], a[3]) end end
        function obj:Destroy() tab.pend[self] = nil; pcall(function() ctl.row:Destroy() end) end
        return obj
    end
    function TabObj:AddStats(o)
        o = o or {}
        local ctl = UIX.stats(self.body, o.Labels or {}, self:_next())
        local tab, obj = self, { Row = ctl.row }
        function obj:Set(list)
            if isVisible(tab) then self._a = nil; ctl.set(list)
            else self._a = list; tab.pend[self] = true end
        end
        obj._fl = function() local a = obj._a; if a then obj._a = nil; ctl.set(a) end end
        function obj:Destroy() tab.pend[self] = nil; pcall(function() ctl.row:Destroy() end) end
        return obj
    end

    -- v24: a MESMA opcao pode aparecer em mais de uma aba (ex.: Auto Fully Ghoul em Races e em Auto Fully): os botoes ficam em sincronia
    -- e ao mexer em um deles os callbacks de TODAS as copias rodam (cada uma so grava Config[id] e salva, entao repetir nao faz mal)
    local MIRROR = {}
    function TabObj:AddToggle(id, o)
        o = o or {}
        local title = tostring(o.Title or id)
        local parent, order, sub = slot(self, o.Description, 270)
        local obj = mkOpt(id, o, "Toggle")
        obj.Value = o.Default and true or false
        local ring = id and MIRROR[id]
        if id and not ring then ring = {}; MIRROR[id] = ring end
        local ctl = mkToggle(parent, pickIcon(title, "check"), title, sub, order, obj.Value, function(v)
            obj.Value = v
            if ring then
                for _, m in ipairs(ring) do
                    if m.obj ~= obj then
                        if m.obj.Value ~= v then m.obj.Value = v; pcall(m.ctl.set, v, true) end
                        fire(m.obj._cb, v, id)
                    end
                end
            end
            fire(obj._cb, v, id)
        end)
        if ring then ring[#ring + 1] = { obj = obj, ctl = ctl } end
        if o.NoBadge then local rec = ORG.of[ctl.row]; if rec then rec.noBadge = true end end       -- opcao (nao funcao): nao conta no selo da aba
        function obj:SetValue(v) ctl.set(v and true or false) end
        -- v24: texto "ao vivo" na legenda da linha (cor de destaque); vazio/nil volta para a descricao. So vale quando a descricao coube na linha.
        function obj:SetLive(txt)
            if sub == nil or sub == "" then return end
            local rec = ORG.of[ctl.row]
            if not rec or not rec.ss then return end
            txt = (txt ~= nil and txt ~= "") and tostring(txt) or nil
            local want = txt or sub
            if rec.sub == want then return end
            rec.sub = want
            rec.ss.Text = want
            tween(rec.ss, 0.25, { TextColor3 = txt and TH.cur.acc or TH.cur.dim })
            ORG.fit(rec)
        end
        obj.Row = ctl.row
        return obj
    end

    local function toSet(v)
        local set = {}
        if type(v) == "table" then
            for k, x in pairs(v) do
                if x == true then set[k] = true elseif type(x) == "string" then set[x] = true end
            end
        end
        return set
    end
    function TabObj:AddDropdown(id, o)
        o = o or {}
        local title = tostring(o.Title or id)
        local vals = o.Values or {}
        local multi = o.Multi and true or false
        local init
        if multi then
            init = toSet(o.Default)
        else
            local d = o.Default
            if type(d) == "number" then init = vals[d] elseif type(d) == "string" then init = d end
        end
        local parent, order, sub = slot(self, o.Description, 210)
        local obj = mkOpt(id, o, "Dropdown")
        obj.Values, obj.Value, obj.Multi = vals, init, multi
        local ctl = UIX.select(parent, pickIcon(title, "layers"), title, sub, order, vals, init, multi, function(v)
            obj.Value = v
            fire(obj._cb, v, id)
        end)
        function obj:SetValue(v)
            if multi then v = toSet(v) end
            ctl.set(v)
            obj.Value = v
            fire(obj._cb, v, id)
        end
        function obj:SetValues(l) obj.Values = l or {}; ctl.setOptions(obj.Values) end
        obj.Row = ctl.row
        return obj
    end

    function TabObj:AddSlider(id, o)
        o = o or {}
        local title = tostring(o.Title or id)
        local mn, mx = tonumber(o.Min) or 0, tonumber(o.Max) or 100
        local def = math.clamp(tonumber(o.Default) or mn, mn, mx)
        local parent, order, sub = slot(self, o.Description, 250)
        local obj = mkOpt(id, o, "Slider")
        obj.Value = def
        local ctl = UIX.slider(parent, pickIcon(title, "gauge"), title, sub, order, mn, mx, def, function(v) obj.Value = v; fire(obj._cb, v, id) end, nil, tonumber(o.Rounding) or 0)
        function obj:SetValue(v) ctl.set(v); obj.Value = ctl.value end
        obj.Row = ctl.row
        return obj
    end

    function TabObj:AddInput(id, o)
        o = o or {}
        local title = tostring(o.Title or id)
        local parent, order, sub = slot(self, o.Description, 170)
        local obj = mkOpt(id, o, "Input")
        obj.Value = tostring(o.Default or "")
        local ctl = UIX.input(parent, pickIcon(title, "keyboard"), title, sub, order, o.Default, o.Placeholder, o.Numeric and true or false, function(txt) obj.Value = txt; fire(obj._cb, txt, id) end)
        function obj:SetValue(v) ctl.set(v); obj.Value = tostring(v or ""); fire(obj._cb, obj.Value, id) end
        obj.Row = ctl.row
        return obj
    end

    function TabObj:AddButton(o)
        o = o or {}
        local title = tostring(o.Title or "Run")
        local label = o.Label or btnLabel(title)
        local w = math.clamp(measure(label, 11, Enum.Font.GothamBold) + 30, 70, 150)
        local parent, order, sub = slot(self, o.Description, 350 - w)
        local cb = o.Callback
        local ctl = UIX.button(parent, pickIcon(title, "power"), title, sub, order, label, function()
            if type(cb) == "function" then
                local ok, e = pcall(cb)
                if not ok then AFL.logErr("ui button " .. title, e) end
            end
        end)
        return { Row = ctl.row, SetTitle = function() end, SetDesc = function() end, Destroy = function() pcall(function() ctl.row:Destroy() end) end }
    end

    local function mkTabObj(t, start)
        local o = setmetatable({ t = t, body = t.body, n = start or 0, Container = Instance.new("Folder"), pend = {} }, TabObj)
        t.objs = t.objs or {}
        t.objs[#t.objs + 1] = o
        pcall(function() table.insert(PC.Connections, t.page:GetPropertyChangedSignal("Visible"):Connect(function() if t.page.Visible then o:_flush() end end)) end)
        return o
    end
    PC.mkTabObj = mkTabObj

    -- "Script" e a aba Script Settings (criada mais tarde): liga na primeira vez que alguem pede
    local function findTab(name)
        for _, t in ipairs(tabs) do if t.name == name then return t end end
    end
    setmetatable(Tabs, { __index = function(t, k)
        if k == "Script" then
            local st = findTab("Script Settings")
            if st then local o = mkTabObj(st, 5000); rawset(t, k, o); return o end
        end
        if k == "Normal" then
            local st = findTab("Normal Farm")
            if st then local o = mkTabObj(st, 5000); rawset(t, k, o); return o end
        end
        return nil
    end })

    -- ------------------------------------------------------------ abas novas ----
    -- chave usada pelos modulos, nome na barra lateral, icone, grupo
    local TABDEF = {
        { "Stack", "Stack Farm", "layers", "Farm" }, { "SubFarm", "Sub Farm", "key", "Farm" }, { "Mastery", "Farm Mastery", "star", "Farm" },
        { "Fruits", "Fruits", "heart", "Farm" }, { "Bosses", "Bosses", "crown", "Farm" }, { "Fish", "Fishing", "hourglass", "Farm" }, { "Halloween", "Halloween 2026", "flame", "Farm" },
        { "Fully", "Auto Fully", "inf", "Events" },
        { "Races", "Races", "users", "Events" }, { "Raid", "Raid", "repeatI", "Events" }, { "Dungeons", "Dungeons", "shield", "Events" },
        { "Sea", "Sea Events", "fog", "Events" }, { "Vulcan", "Vulcan", "sun", "Events" }, { "Secrets", "Secrets", "flask", "Events" },
        { "Teleport", "Teleport", "rocket", "Tools" }, { "ESP", "ESP", "eye", "Tools" }, { "PVP", "PVP", "flame", "Tools" },
        { "Aimbot", "Aimbot", "finger", "Tools" }, { "Macro", "Macro", "keyboard", "Tools" }, { "Webhook", "Webhook", "link", "Tools" },
        { "Shop", "Shop", "wrench", "Tools" }, { "Player", "Player", "user", "Tools" },
    }
    PC.tabMods = {}          -- chave da aba -> lista de modulos que montam o conteudo (preenchido em pmods)
    local bodyOf = {}
    for _, d in ipairs(TABDEF) do
        local t = addTab(d[2], ICON[d[3]], d[4])
        local o = mkTabObj(t, 0)
        rawset(Tabs, d[1], o)
        bodyOf[d[1]] = t
        t.lazy = function() PC.openTab(d[1]) end
    end

    -- ------------------------------------------------------------ carregador ----
    -- quando todos os modulos de uma aba terminam de carregar, reordena as secoes dela e refaz a lista (dobrar/busca)
    local function settleKey(key)
        local mods = PC.tabMods[key]
        if not mods then return end
        for _, m in ipairs(mods) do
            if PC.loaded[m] == nil or PC.loaded[m] == "loading" then return end
        end
        local to = Tabs[key]
        if to and to.t then pcall(ORG.settle, to.t) end
    end
    function PC.settleFor(name)
        for key, mods in pairs(PC.tabMods) do
            for _, m in ipairs(mods) do
                if m == name then settleKey(key) break end
            end
        end
    end
    PC.err, PC.loadingBy = {}, {}
    PC.order = PC.order or {}
    local function modLoad(name)
        local m = PC.mods[name]
        if not m then PC.err[name] = "unknown module"; return false end
        PC.loaded[name] = "loading"
        PC.loadingBy[name] = coroutine.running()
        for _, d in ipairs(m.deps or {}) do
            if PC.loaded[d] == nil then PC.need(d) end
        end
        local ok, err = pcall(function()
            local srcf = PC.src[name]
            if not srcf then error("source missing", 0) end
            local f, e = loadstring(srcf(), "=MoonHub." .. name)
            if not f then error(e, 0) end
            f(E)
        end)
        if ok then PC.src[name] = nil end      -- libera o texto do modulo (ja foi compilado); se falhou, fica para "Try again"
        PC.loaded[name] = ok and true or false
        PC.loadingBy[name] = nil
        if not ok then PC.err[name] = tostring(err) end
        AFL.modDone(name, ok, err)
        PC.settleFor(name)
        return ok
    end
    -- carrega um modulo (e as dependencias). Devolve true/false. Chamado de outra thread enquanto carrega: espera.
    function PC.need(name)
        local st = PC.loaded[name]
        if st == true then return true end
        if st == false then return false end
        if st == "loading" then
            if PC.loadingBy[name] == coroutine.running() then return false end       -- recursao: o proprio modulo se pedindo
            local t0 = os.clock()
            while PC.loaded[name] == "loading" and os.clock() - t0 < 20 do task.wait(0.05) end
            return PC.loaded[name] == true
        end
        return modLoad(name)
    end

    -- quadro de erro dentro da aba (com botao para tentar de novo)
    local function showError(key, name)
        local tab = Tabs[key]
        if not tab then return end
        local msg = tostring(PC.err[name] or "unknown error")
        if #msg > 420 then msg = string.sub(msg, 1, 420) .. "..." end
        local p = tab:AddParagraph({ Title = "Module '" .. name .. "' failed to load", Content = msg })
        tab:AddButton({ Title = "Try again", Description = "Reloads this module", Callback = function()
            PC.loaded[name], PC.err[name] = nil, nil
            if PC.shown then PC.shown[key .. name] = nil end
            pcall(function() p:Destroy() end)
            PC.openTab(key)
        end })
        warn("[Moon Hub] module " .. name .. ": " .. msg)
    end

    -- abre uma aba: carrega os modulos dela uma unica vez (mostra "Loading..." enquanto isso)
    function PC.openTab(key)
        local mods = PC.tabMods[key]
        local to = Tabs[key]
        if not mods or not to then return end
        local pending = false
        for _, m in ipairs(mods) do if PC.loaded[m] == nil or PC.loaded[m] == "loading" then pending = true end end
        if not pending then return end
        task.spawn(function()
            local ph
            pcall(function()
                ph = text(to.body, { Size = UDim2.new(1, 0, 0, 24), Text = "Loading module...", TextSize = 12, Font = Enum.Font.GothamMedium, TextColor3 = C.dim, LayoutOrder = 0, ZIndex = 5 })
            end)
            task.wait(0.05)
            -- v125: pedido do usuario - "no mobile, quando troca de aba, ele trava completamente". Cada modulo
            -- (loadstring do texto + execucao, que cria todos os toggles/sliders/dropdowns da aba de uma vez) e
            -- compilado e montado de uma vez so, sem nenhum respiro - numa aba com mais de 1 modulo (ex.: "Sea"),
            -- isso rodava tudo em sequencia, sem ceder o frame nenhuma vez entre um modulo e outro. Em celular (CPU
            -- bem mais fraca que PC pra compilar Lua e criar Instance), isso pode travar a tela por 1+ segundo -
            -- sem nenhum erro, so trava mesmo, exatamente o relatado. Dando um task.wait() entre cada modulo, pra
            -- cada um cair no PROPRIO frame em vez de empilhar tudo sem ceder o processador nenhuma vez.
            for _, m in ipairs(mods) do PC.need(m); task.wait() end
            if ph then pcall(function() ph:Destroy() end) end
            settleKey(key)
            PC.shown = PC.shown or {}
            for _, m in ipairs(mods) do
                if PC.loaded[m] == false and not PC.shown[key .. m] then
                    PC.shown[key .. m] = true
                    showError(key, m)
                end
            end
        end)
    end

    -- Script Settings / carregamento no inicio (chamado por p4c depois que todas as abas existem)
    local function trigOn(m)
        local ks = m.trig
        if type(ks) == "function" then
            local ok, r = pcall(ks)
            return ok and r and true or false
        end
        for _, k in ipairs(ks or {}) do
            local v = M[k]
            if v == true or (type(v) == "string" and v ~= "") then return true end
        end
        return false
    end
    PC.trigOn = trigOn
    function PC.finishTabs()
        -- aba Script Settings: o modulo "extras" acrescenta Safe Mode / Time Hop quando ela abre
        local st = findTab("Script Settings")
        if st then
            local old = st.lazy
            st.lazy = function()
                if old then pcall(old) end
                PC.openTab("Script")
            end
        end
        -- aba Normal Farm (nativa): os extras (Tyrant, Dough King, Soul Reaper, Bones) entram embaixo quando ela abre
        local nf = findTab("Normal Farm")
        if nf then
            local old = nf.lazy
            nf.lazy = function()
                if old then pcall(old) end
                PC.openTab("Normal")
            end
        end
        -- liga ja no inicio o que estava ligado na config salva (um por vez, sem travar a interface)
        task.spawn(function()
            task.wait(1.2)
            for _, name in ipairs(PC.order) do
                if not alive then return end
                local m = PC.mods[name]
                if m and PC.loaded[name] == nil and trigOn(m) then
                    PC.need(name)
                    task.wait(0.2)
                end
            end
        end)
    end
end)()

