local __E = ...
local AFL = __E.AFL
local Diag, Fluent, Player, State, Tabs, currentTween, flyTo = __E.Diag, __E.Fluent, __E.Player, __E.State, __E.Tabs, __E.currentTween, __E.flyTo
local getChar, getSea, invoke = __E.getChar, __E.getSea, __E.invoke
local Players = game:GetService("Players")
local function findGroundFruit(...) return AFL.findGroundFruit(...) end
local Alive = true
AFL.onUnload(function() Alive = false end);
-- ---------- Teleport (ilhas, NPCs, jogadores, frutas, mares) ----------
-- v49: reescrito. Voa (com noclip e segurando o personagem) ate o destino; segue o alvo se ele se mexe (jogador); a opcao
-- escolhida e lida da lista na hora de clicar (antes ficava vazia se voce nao mexesse na lista); botoes de mar; Stop cancela.
-- AFL.tpTravel(pos | funcao -> pos, rotulo) tambem e usado pelos botoes de teleporte das outras abas.
local TP = { token = nil }
function AFL.tpStop()
    TP.token = nil
    if currentTween then currentTween:Cancel() end
    local _, hrp = getChar()
    if hrp and not State.Busy and hrp:FindFirstChild("FarmHold") then hrp.FarmHold:Destroy() end
end
function AFL.tpTravel(target, label, quiet)
    local mine = {}
    TP.token = mine
    if not quiet then
        pcall(function() Fluent:Notify({ Title = "Moon Hub - Teleport", Content = "Flying to " .. tostring(label), Duration = 3 }) end)
    end
    task.spawn(function()
        local t0, lastClip, arrived, sentPos = os.clock(), 0, false, nil
        while Alive and TP.token == mine and os.clock() - t0 < 240 do
            local char, hrp = getChar()
            if not char then task.wait(0.5) else
                local pos = type(target) == "function" and target() or target
                if not pos then break end
                local hold = hrp:FindFirstChild("FarmHold")
                if not hold then
                    hold = Instance.new("BodyVelocity")
                    hold.Name, hold.MaxForce, hold.Velocity = "FarmHold", Vector3.new(1e5, 1e5, 1e5), Vector3.zero
                    hold.Parent = hrp
                end
                if os.clock() - lastClip > 0.25 then
                    lastClip = os.clock()
                    for _, p in ipairs(char:GetDescendants()) do
                        if p:IsA("BasePart") then p.CanCollide = false end
                    end
                end
                if (hrp.Position - pos).Magnitude < 6 then arrived = true break end
                -- v148: destino fixo (CFrame exato) enviado UMA vez; so reenvia se o alvo se mexeu (>8 studs) ou o voo foi cancelado
                if not sentPos or (sentPos - pos).Magnitude > 8 or currentTween.PlaybackState ~= Enum.PlaybackState.Playing then
                    sentPos = pos
                    flyTo(CFrame.new(pos))
                end
                task.wait(0.1)
            end
        end
        if TP.token == mine then
            TP.token = nil
            if currentTween then currentTween:Cancel() end
            local _, hrp = getChar()
            -- v83 fix: antes isso destruia o FarmHold (BodyVelocity que sustenta o personagem no ar) sempre que
            -- o loop acabava, mesmo quando NAO chegou no destino (timeout de 240s ou alvo que desapareceu no meio
            -- do caminho). currentTween:Cancel() ja zera Fly.goal, entao o motor de voo (Heartbeat) para de empurrar
            -- o personagem - sem o FarmHold tambem, nada sustenta ele contra a gravidade, e ele cai reto na agua se
            -- ainda estava sobrevoando o mar (exatamente "para de voar e cai na agua" no teleporte de ilha). Agora
            -- so remove o FarmHold quando realmente chegou (arrived); se nao chegou, mantem o personagem flutuando
            -- parado em vez de deixar ele cair, e avisa que a viagem nao completou.
            if arrived then
                if hrp and not State.Busy and hrp:FindFirstChild("FarmHold") then hrp.FarmHold:Destroy() end
                if not quiet then
                    pcall(function() Fluent:Notify({ Title = "Moon Hub - Teleport", Content = "Arrived: " .. tostring(label), Duration = 3 }) end)
                end
            elseif not quiet then
                pcall(function() Fluent:Notify({ Title = "Moon Hub - Teleport", Content = "Did not reach " .. tostring(label) .. " in time (holding position, not falling). Try again.", Duration = 5 }) end)
            end
        end
    end)
end
(function()
    local T = Tabs.Teleport
    local function posOf(inst)
        if not inst then return end
        if inst:IsA("BasePart") then return inst.Position end
        local ok, p = pcall(function() return inst:GetPivot().Position end)
        if ok then return p end
    end
    local function note(msg)
        pcall(function() Fluent:Notify({ Title = "Moon Hub - Teleport", Content = msg, Duration = 4 }) end)
    end
    local function islandNames()
        local out = {}
        local wo = workspace:FindFirstChild("_WorldOrigin")
        local loc = wo and wo:FindFirstChild("Locations")
        for _, c in ipairs(loc and loc:GetChildren() or {}) do
            if not string.match(c.Name, "^Island %d+$") then out[#out + 1] = c.Name end
        end
        table.sort(out)
        return out
    end
    local function npcNames()
        local out, seen = {}, {}
        local f = workspace:FindFirstChild("NPCs")
        for _, c in ipairs(f and f:GetChildren() or {}) do
            if not seen[c.Name] then seen[c.Name] = true; out[#out + 1] = c.Name end
        end
        table.sort(out)
        return out
    end
    local function playerNames()
        local out = {}
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= Player then out[#out + 1] = p.Name end
        end
        table.sort(out)
        return out
    end
    local function ph(list) return #list > 0 and list or { "(none found)" } end
    -- valor escolhido na lista (ou o primeiro se nunca mexeu)
    local function chosen(id, getList)
        local o = Fluent.Options[id]
        local v = o and o.Value
        if type(v) ~= "string" or v == "" or v == "(none found)" then v = getList()[1] end
        return v
    end
    local function locPos(name)
        local wo = workspace:FindFirstChild("_WorldOrigin")
        local loc = wo and wo:FindFirstChild("Locations")
        return posOf(loc and name and loc:FindFirstChild(name))
    end
    local function npcPos(name)
        local f = workspace:FindFirstChild("NPCs")
        return posOf(f and name and f:FindFirstChild(name))
    end
