        local pl = name and Players:FindFirstChild(name)
        return pl and pl.Character and pl.Character:FindFirstChild("HumanoidRootPart")
    end

    T:AddSection("Islands")
    local dIsl = T:AddDropdown("TpIsland", { Title = "Select Island", Description = "Islands and places of this sea", Values = ph(islandNames()), Default = 1 })
    T:AddButton({ Title = "Teleport To Island", Description = "Flies to the selected island", Callback = function()
        local n = chosen("TpIsland", islandNames())
        local p = n and locPos(n)
        if p then AFL.tpTravel(p + Vector3.new(0, 60, 0), n) else note("Island not found: press Refresh Lists and select one.") end
    end })
    T:AddSection("NPCs")
    local dNpc = T:AddDropdown("TpNpc", { Title = "Select NPC", Description = "NPCs that are loaded near you", Values = ph(npcNames()), Default = 1 })
    T:AddButton({ Title = "Teleport To NPC", Description = "Flies to the selected NPC", Callback = function()
        local n = chosen("TpNpc", npcNames())
        local p = n and npcPos(n)
        if p then AFL.tpTravel(p + Vector3.new(0, 4, 4), n) else note("NPC not loaded: get closer or press Refresh Lists.") end
    end })
    T:AddSection("Players & Fruits")
    local dPl = T:AddDropdown("TpPlayer", { Title = "Select Player", Description = "Players in this server", Values = ph(playerNames()), Default = 1 })
    T:AddButton({ Title = "Teleport To Player", Description = "Flies to the selected player (follows him until you arrive)", Callback = function()
        local n = chosen("TpPlayer", playerNames())
        if plrHrp(n) then
            AFL.tpTravel(function()
                local h = plrHrp(n)
                return h and (h.Position + Vector3.new(0, 4, 0)) or nil
            end, n)
        else note("Player not found or not loaded.") end
    end })
    T:AddButton({ Title = "Teleport To Fruit", Description = "Flies to the nearest fruit lying on the ground", Callback = function()
        local fr = findGroundFruit()
        local p = posOf(fr)
        if p then AFL.tpTravel(p, "the fruit") else note("No fruit on the ground in this server.") end
    end })
    T:AddSection("Seas")
    local seaCmd = { { "Sea 1 (First Sea)", "TravelMain" }, { "Sea 2 (Second Sea)", "TravelDressrosa" }, { "Sea 3 (Third Sea)", "TravelZou" } }
    for i, sc in ipairs(seaCmd) do
        T:AddButton({ Title = "Travel To " .. sc[1], Description = "Changes sea (needs the level of that sea)", Callback = function()
            if getSea() == i then note("You are already in this sea.") return end
            note("Traveling to " .. sc[1])
