-- ============ SEA EVENTS ============
-- Pilota o barco, sai dele quando aparece um evento selecionado, mata (por prioridade) e volta.
-- Tudo aqui depende de nomes/pastas do jogo que NÃO consegui verificar: ver Status > sea para o diagnóstico.
local Sea = {}
do
    local st = { wp = nil, origin = nil, heading = math.random() * math.pi * 2, waterY = nil,
        skillBusy = false, skip = setmetatable({}, { __mode = "k" }), buyAt = 0, resetAt = 0, dealer = nil, returning = false, cruise = nil, roughAt = 0,
        bad = setmetatable({}, { __mode = "k" }), track = nil, kills = { total = 0 }, skipped = 0, tgt = nil, tgtAt = 0, tgtDist = 0 }
    table.insert(Connections, Player.CharacterAdded:Connect(function() st.died = true end))
    local BoatNames = {
        ["Beast Hunter"] = { "Beast Hunter", "BeastHunter" }, Guardian = { "Guardian" }, Lantern = { "Lantern" },
        Sleigh = { "Sleigh" }, Brigade = { "PirateBrigade", "Brigade" }, ["Grand Brigade"] = { "PirateGrandBrigade", "GrandBrigade" },
    }
    local KEYS = { "Z", "X", "C", "V", "F" }
    -- Zonas do Mar 3 (coordenadas fornecidas pelo usuário); índice 7 = Infinite
    local ZONES = {
        Vector3.new(-21998.375, 30, -682.309), Vector3.new(-26779.5215, 30, -822.858),
        Vector3.new(-31171.957, 30, -2256.9377), Vector3.new(-34054.6875, 30, -2560.1201),
        Vector3.new(-38887.5547, 30, -2162.9902), Vector3.new(-44541.7617, 30, -1244.8584),
        Vector3.new(-10000000, 31, 37016.25),
    }
    -- Mar 3: Tiki Outpost | Mar 2: Docas (coordenadas aproximadas)
    local function SeaRef()
        return (getSea() == 3) and Vector3.new(-16224, 9, 439) or Vector3.new(-6500, 10, -4000)
    end
    local WEAPONS = { "Melee", "Blox Fruit", "Sword", "Gun" }

    local function classify(m)
        local n = string.lower(m.Name)
        if string.find(n, "terror", 1, true) then return "Terrorshark" end
        if string.find(n, "seabeast", 1, true) or string.find(n, "sea beast", 1, true) then return "Sea Beast" end
        if string.find(n, "piranha", 1, true) then return "Piranha" end
        if string.find(n, "shark", 1, true) then return "Shark" end
        if string.find(n, "brigade", 1, true) or string.find(n, "fishboat", 1, true) or string.find(n, "ship", 1, true) then return "Ship" end
    end
    local function partOf(m)
        return m:FindFirstChild("HumanoidRootPart") or m.PrimaryPart or m:FindFirstChildWhichIsA("BasePart", true)
    end
    -- v145: navio grande - o golpe de fruta errava porque a "parte" escolhida era qualquer uma (mastro/corda). Agora mira o CASCO: a maior peca do barco.
    local hullCache = setmetatable({}, { __mode = "k" })
    local function hullPart(m)
        local c = hullCache[m]
        if c and c.Parent then return c end
        local best, bv
        for _, d in ipairs(m:GetDescendants()) do
            if d:IsA("BasePart") then
                local v = d.Size.X * d.Size.Y * d.Size.Z
                if not bv or v > bv then best, bv = d, v end
            end
        end
        if best then hullCache[m] = best end
        return best
    end
    local function aliveM(m)
        local h = m:FindFirstChildOfClass("Humanoid")
        if h then return h.Health > 0 end
        local hv = m:FindFirstChild("Health")
        if hv and hv:IsA("ValueBase") then return hv.Value > 0 end
        return m.Parent ~= nil
    end
    local function isMine(b)
        local o = b:FindFirstChild("Owner")
        return o and (o.Value == Player or tostring(o.Value) == Player.Name)
    end

    local function scan(hrp, range)
        local out = {}
        local folders = { workspace:FindFirstChild("SeaBeasts"), workspace:FindFirstChild("Enemies"), workspace:FindFirstChild("Boats") }
        for fi, folder in ipairs(folders) do
            if folder then
                for _, m in ipairs(folder:GetChildren()) do
                    if m:IsA("Model") and not (fi == 3 and m:FindFirstChild("Owner")) then
                        local ty = classify(m)
                        if ty and (fi ~= 3 or ty == "Ship") and aliveM(m) and not ((st.bad[m] or 0) > os.clock()) then
                            local p = (ty == "Ship" and hullPart(m)) or partOf(m)
                            if p then
                                local d = (p.Position - hrp.Position).Magnitude
                                -- v28: prende o esquiva do Sea Beast assim que ele aparece no scan, nao so quando ja estamos lutando com ele
                                -- (senao o primeiro golpe dele acontece antes do hook e nunca e esquivado)
                                if ty == "Sea Beast" then st.hookBeast(p) end
                                if d <= range then out[#out + 1] = { m = m, type = ty, part = p, dist = d } end
                            end
                        end
                    end
                end
            end
        end
        return out
    end

    local function pickTarget(list)
        local sel = Config.SeaEvents
        local order, used = {}, {}
        for _, n in ipairs(Config.SeaPrio) do
            if sel[n] and not used[n] then order[#order + 1] = n; used[n] = true end
        end
        for _, n in ipairs({ "Terrorshark", "Sea Beast", "Ship", "Shark", "Piranha" }) do
            if sel[n] and not used[n] then order[#order + 1] = n end
        end
        -- v29: fica no mesmo alvo que ja esta sendo atacado em vez de trocar so porque a distancia mudou um pouco entre dois
        -- bichos do mesmo tipo/prioridade - isso tava resetando o anti-travamento (stallCheck) e o progresso do kill toda hora.
        -- So troca na hora se aparecer algo de prioridade MAIOR que o alvo atual (ex: larga um Shark pra pegar um Terrorshark).
        local tr = st.track
        if tr and tr.m then
            local curRank
            for i, n in ipairs(order) do if n == tr.ty then curRank = i; break end end
            if curRank then
                for i = 1, curRank - 1 do
                    for _, t2 in ipairs(list) do if t2.type == order[i] then return t2 end end
                end
                for _, t in ipairs(list) do if t.m == tr.m then return t end end
            end
        end
        for _, want in ipairs(order) do
            local best
            for _, t in ipairs(list) do
                if t.type == want and (not best or t.dist < best.dist) then best = t end
            end
            if best then return best end
        end
    end

    local function pressKey(name)
        local kc = Enum.KeyCode[name]
        if not kc then return end
        pcall(function()
            VirtualInputManager:SendKeyEvent(true, kc, false, game)
            task.wait(0.12)
            VirtualInputManager:SendKeyEvent(false, kc, false, game)
        end)
    end

    -- arma de M1 escolhida pelas opções (nil = usar as skills)
    local function m1Weapon(ty)
        local o = Config.SeaOpt
        local ds, sg = findToolByName("dragonstorm"), findToolByName("skull guitar")
        if o.AutoChangeDS and ds and sg then return { name = (ty == "Sea Beast") and "skull guitar" or "dragonstorm" } end
        if o.UseDS and ty ~= "Sea Beast" and ds then return { name = "dragonstorm" } end
        if o.ChangeDSBoat and ty == "Ship" and ds then return { name = "dragonstorm" } end
        if o.UseSG and (ty == "Ship" or ty == "Sea Beast") and sg then return { name = "skull guitar" } end
        if o.UseM1Fruit then return { tip = "Blox Fruit" } end
    end

    local function skillWorker()
        if st.skillBusy then return end
        st.skillBusy = true
        task.spawn(function()
            for _, tip in ipairs(WEAPONS) do
                if Alive and Config.SeaWeapons[tip] then
                    Config.SeaTool = { tip = tip }
                    pcall(equipWeapon)
                    task.wait(0.25)
                    for _, k in ipairs(KEYS) do
                        if Alive and Config.SeaSkills[tip][k] then
                            Config.SeaUntil = os.clock() + 1.2
                            pressKey(k)
                            task.wait(0.2)
                        end
                    end
                end
            end
            st.skillBusy = false
        end)
    end

    -- AUTO DODGE (lógica do Banana Hub)
    -- Terrorshark: o ataque cria a parte "ChargeUp" em workspace._WorldOrigin; sobe 200 studs até ela sumir.
    -- Sea Beast: ao tocar uma animação que não é loop (ataque/raio) no Animator dele, sobe 200 studs pela duração.
    function st.dodge(sec) st.dodgeUntil = math.max(st.dodgeUntil or 0, os.clock() + sec) end
    st.hooked = setmetatable({}, { __mode = "k" })
    function st.hookBeast(part)
        local m = part and part:FindFirstAncestorOfClass("Model")
        if not m or st.hooked[m] then return end
        st.hooked[m] = true
        pcall(function()
            local an = m:FindFirstChildWhichIsA("Animator", true)
            if not an then return end
            table.insert(Connections, an.AnimationPlayed:Connect(function(track)
                if not Config.SeaOpt.DodgeBeast then return end
                local len = 2
                pcall(function() if track.Length and track.Length > 0 then len = track.Length end end)
                if track.Looped then return end
                st.dodge(math.min(len, 6) + 0.7)
            end))
        end)
    end
    task.spawn(function()
        local wo = workspace:WaitForChild("_WorldOrigin", 60)
        if not wo then return end
        local function onPart(p)
            if p.Name ~= "ChargeUp" or not Config.SeaOpt.DodgeShark then return end
            local c = Player.Character
            local hrp = c and c:FindFirstChild("HumanoidRootPart")
            if not (hrp and p:IsA("BasePart")) or (p.Position - hrp.Position).Magnitude > 250 then return end
            local born = os.clock()
            st.dodgeUntil = os.clock() + 14
            local conn
            conn = p.AncestryChanged:Connect(function()
                if p.Parent then return end
                conn:Disconnect()
                st.dodgeUntil = (os.clock() - born < 1) and (os.clock() + 2.5) or os.clock()
            end)
        end
        table.insert(Connections, wo.ChildAdded:Connect(function(p) pcall(onPart, p) end))
    end)
    local function hpOf(m)
        local h = m:FindFirstChildOfClass("Humanoid")
        if h then return h.Health end
        local hv = m:FindFirstChild("Health")
        if hv and hv:IsA("ValueBase") then return tonumber(hv.Value) end
    end
    -- conta a kill quando o alvo acompanhado some ou morre
    local function settleTrack()
        local tr = st.track
        if tr and tr.m and (not tr.m.Parent or not aliveM(tr.m)) and not ((st.bad[tr.m] or 0) > os.clock()) then
            st.kills.total = st.kills.total + 1
            st.kills[tr.ty] = (st.kills[tr.ty] or 0) + 1
            st.track = nil
        end
    end
    -- Anti-travamento: perto do alvo ha 25s sem ele perder vida (inalcancavel / invulneravel) -> pula por 90s
    local function stallCheck(t)
        local now = os.clock()
        local hp = hpOf(t.m)
        local tr = st.track
        if not tr or tr.m ~= t.m then settleTrack(); tr = { m = t.m, ty = t.type, hp = hp, since = now }; st.track = tr end
        if hp and tr.hp and hp < tr.hp - 0.01 then tr.hp, tr.since = hp, now
        elseif hp and (not tr.hp or hp > tr.hp) then tr.hp = hp end
        if t.dist >= 150 then tr.since = now end
        if now - tr.since > 25 then
            st.bad[t.m] = now + 90; st.skipped = st.skipped + 1; st.track = nil
            Diag.sea = "skipping " .. t.type .. " (it does not lose health for 25s)"
            return true
        end
        return false
    end
    local function combat(t, hrp, hum)
        local o = Config.SeaOpt
        if stallCheck(t) then return end
        st.tgt, st.tgtAt, st.tgtDist = t.type, os.clock(), t.dist
        st.patrol, st.idleAt = nil, nil
        pcall(function() Core.force = { NPC = true, BOSS = true }; Core.forceUntil = os.clock() + 1.5 end)   -- bate no alvo do mar mesmo que o Farm Settings so tenha NPC
        -- v28: alvo forcado com prioridade MAXIMA no motor de ataque (antes dependia da lista de NPCs estar vazia -> golpes nao acertavam com NPC perto)
        pcall(function() Core.seaTarget = { m = t.m, part = t.part }; Core.seaTargetUntil = os.clock() + 1.5 end)
        if t.type == "Sea Beast" then st.hookBeast(t.part) end
        Config.SeaUntil = os.clock() + 1.2
        st.cruise = nil
        if hum.Sit then hum.Sit = false end
        local h = 20
        local mw = m1Weapon(t.type)
        if mw and (mw.tip == "Blox Fruit" or mw.name) then h = 14 end -- M1: mais perto, acerta mais
        if t.type == "Ship" then
            -- barco: logo acima do CASCO (o golpe de fruta sai pra baixo/na frente; de cima do casco ele acerta o barco)
            h = math.clamp((t.part.Size.Y / 2) + 4, 4, 40)
        end
        if t.type == "Sea Beast" then h = h + 40 end -- +40 studs só no Sea Beast
        -- v42: o Terrorshark pode disparar um novo ChargeUp antes do anterior ser detectado como "removido" (ver o hook
        -- em workspace._WorldOrigin.ChildAdded), e cada um rearma o teto de seguranca do dodge (14s). Se os ataques dele
        -- vierem mais rapido que isso, o personagem fica preso voando a 200 studs quase o tempo todo e nunca acerta
        -- nada. Depois de 6s ESQUIVANDO SEM PARAR, forca uma janela de ataque na altura normal mesmo que o jogo ainda
        -- ache que tem um golpe "carregando"; se um ChargeUp de verdade aparecer de novo, o dodge volta a funcionar.
        local dodging = st.dodgeUntil and os.clock() < st.dodgeUntil and (t.type == "Terrorshark" or t.type == "Sea Beast")
        if dodging then
            st.dodgeSince = st.dodgeSince or os.clock()
            if os.clock() - st.dodgeSince > 6 then
                dodging, st.dodgeUntil, st.dodgeSince = false, os.clock(), nil
            end
        else
            st.dodgeSince = nil
        end
        if dodging then h = 200 end -- auto dodge (estilo Banana): sobe 200 studs
        local stand = t.part.Position + Vector3.new(0, h, 0)
        do
            local wy = st.waterY
            pcall(function()
                local pl = workspace:FindFirstChild("Map") and workspace.Map:FindFirstChild("WaterBase-Plane")
                if pl and pl:IsA("BasePart") then wy = pl.Position.Y + pl.Size.Y / 2 end
            end)
            -- v42: sem a WaterBase-Plane, o fallback usava a altura ATUAL do personagem (hrp.Position.Y) como "nivel do
            -- mar". Isso criava um degrau permanente: depois de esquivar (subir 200 studs), a propria altura do dodge
            -- virava o novo "piso" na proxima vez que este calculo rodasse, e o personagem nunca mais descia pra
            -- atacar. O alvo (Terrorshark/Ship/etc.) esta na superficie do mar, entao a altura DELE e uma referencia
            -- muito mais estavel do que a altura (possivelmente ja elevada) do proprio personagem.
            wy = wy or (t.part.Position.Y - 5)
            if t.type ~= "Ship" and stand.Y < wy + 20 then stand = Vector3.new(stand.X, wy + 20, stand.Z) end
        end
        Aim.part, Aim.level = t.part, false
        if (hrp.Position - stand).Magnitude > 10 then
            flyTo(CFrame.new(stand))
        else
            if currentTween then currentTween:Cancel() end
            hrp.CFrame = CFrame.lookAt(stand, t.part.Position)
            hrp.AssemblyLinearVelocity = Vector3.zero
        end
        local w = m1Weapon(t.type)
        Config.SeaClick = w and { kind = (w.name == "dragonstorm" and "ds") or (w.name == "skull guitar" and "sg") or "fruit", part = t.part, untilT = os.clock() + 0.8 } or nil
        if w and not st.skillBusy then
            Config.SeaTool = w
            pcall(equipWeapon)
            -- v82 fix: Config.SeaClick ficava gravado aqui mas NUNCA era lido em lugar nenhum do codigo - o disparo de
            -- verdade do Dragonstorm/Skull Guitar por remote (AFL.Shot/Config.ShotFire, feito pra mirar e atirar
            -- sozinho sem clicar na tela) ficava morto. Isso nao aparecia no Dragonstorm porque o ToolTip dele cai no
            -- caminho generico de Gun do motor principal (tool:Activate() ja faz alguma coisa); no Skull Guitar o
            -- ToolTip generico e "Melee", entao o motor so dava um soco comum (meleeSwordClick) em vez do "TAP" certo
            -- da guitarra - exatamente o "usa Melee no Sea Beast" relatado. Chamando o disparo dedicado aqui tambem
            -- (ele mesmo se limita a 1 tiro por 0,1s, Shot.last) resolve os dois: reforca o Dragonstorm e liga o
            -- Skull Guitar de vez.
            if Config.SeaClick and Config.ShotFire then pcall(Config.ShotFire, Config.SeaClick) end
        end
        -- v145: relato - "no Sea Events ele nao troca de arma nem usa as skills". As skills so rodavam quando NAO havia arma de M1 (UseM1Fruit etc.);
        -- agora rodam sempre que alguma arma/skill estiver marcada em Sea Events (o M1 espera enquanto o rodizio de skills esta ativo).
        do
            local sel = false
            for _, tip in ipairs(WEAPONS) do
                if Config.SeaWeapons[tip] then
                    for _, k in ipairs(KEYS) do if Config.SeaSkills[tip] and Config.SeaSkills[tip][k] then sel = true end end
                end
            end
            if sel or not w then skillWorker() end
        end
        Config.AttackUntil = os.clock() + 0.8
        Diag.sea = string.format("killing %s (%d studs) | %s", t.type, math.floor(t.dist), w and "M1" or "skills")
    end

    local function myBoat(hum, hrp)
        local sp = hum.SeatPart
        if sp and sp:IsA("VehicleSeat") then
            local b = sp:FindFirstAncestorOfClass("Model")
            if b then return b, sp end
        end
        local folder = workspace:FindFirstChild("Boats")
        if not folder then return end
        local nearest, nd
        for _, b in ipairs(folder:GetChildren()) do
            if b:IsA("Model") then
                local seat = b:FindFirstChildWhichIsA("VehicleSeat", true)
                if seat then
                    if isMine(b) and not st.skip[b] then return b, seat end
                    -- barco recém-comprado: o mais próximo sem dono diferente
                    if os.clock() - st.buyAt < 60 and not b:FindFirstChild("Owner") then
                        local d = (seat.Position - hrp.Position).Magnitude
                        if d < 250 and (not nd or d < nd) then nearest, nd = { b, seat }, d end
                    end
                end
            end
        end
        if nearest then return nearest[1], nearest[2] end
    end

    local function findDealer()
        local npcs = workspace:FindFirstChild("NPCs")
        if not npcs then return end
        local lux = (Config.SeaBoat ~= "Brigade" and Config.SeaBoat ~= "Grand Brigade")
        -- Mar 3: só no Tiki Outpost | Mar 2: só nas Docas (pontos de referência aproximados: pega o vendedor mais perto deles)
        local ref = SeaRef()
        local best, bd, any, ad
        for _, n in ipairs(npcs:GetChildren()) do
            local nm = string.lower(n.Name)
            if string.find(nm, "boat dealer", 1, true) then
                local d = (n:GetPivot().Position - ref).Magnitude
                if (string.find(nm, "luxury", 1, true) ~= nil) == lux then
                    if not bd or d < bd then best, bd = n, d end
                end
                if not ad or d < ad then any, ad = n, d end
            end
        end
        return best or any
    end

    local function buyBoat(hrp, hum)
        local now = os.clock()
        if getSea() == 3 and (hrp.Position - SeaRef()).Magnitude > 220 then
            Diag.sea = "flying to the Tiki Outpost to buy the boat"
            st.dealer = nil
            flyTo(CFrame.new(SeaRef() + Vector3.new(0, 40, 0)))
            return true
        end
        if not (st.dealer and st.dealer.Parent) then st.dealer = findDealer() end
        if st.dealer then
            local pos = st.dealer:GetPivot().Position
            if (hrp.Position - pos).Magnitude > 35 then
                Diag.sea = "going to the boat dealer"
                flyTo(CFrame.new(pos + Vector3.new(0, 4, 0)))
                return true
            end
        elseif (hrp.Position - SeaRef()).Magnitude > 150 then
            -- vendedor ainda não carregou (longe): vai até o Tiki/Docas, de qualquer lugar do mapa
            Diag.sea = (getSea() == 3) and "going to the Tiki Outpost to buy the boat" or "going to the Docks to buy the boat"
            flyTo(CFrame.new(SeaRef() + Vector3.new(0, 40, 0)))
            return true
        end
        if now - st.buyAt < (st.buyOk and 3 or 1) then Diag.sea = "waiting for the boat to appear"; return true end
        st.buyAt = now
        local ok, r
        for _, nm in ipairs(BoatNames[Config.SeaBoat] or BoatNames["Beast Hunter"]) do
            ok, r = invoke("BuyBoat", nm)
            if ok and r then break end
        end
        st.buyOk = (ok and r) and true or false
        Diag.sea = "buy boat " .. tostring(Config.SeaBoat) .. ": " .. (ok and "" or "error ") .. tostring(r)
        if not (ok and r) and Config.SeaOpt.ResetBuy and now - st.resetAt > 60 and now - (st.noBoatAt or now) > 12 then
            st.resetAt = now
            pcall(function() hum.Health = 0 end)
        end
        return true
    end

    function Sea.report()
        local now = os.clock()
        return { on = Config.SeaOn and true or false, diag = Diag.sea, kills = st.kills, skipped = st.skipped,
            target = (now - st.tgtAt < 3) and st.tgt or nil, dist = st.tgtDist, sailing = st.cruise ~= nil,
            zone = Sea.zone or Config.SeaZone, boat = Config.SeaBoat, sea = getSea() }
    end

    -- v139: relato de comprador - "Sea Events fica parado a toa". Na zona escolhida o barco PARAVA e esperava para sempre.
    -- Agora espera 20 s e, se nenhum evento aparecer, patrulha dentro da zona (ponto a ate 900 studs do centro, troca a
    -- cada 40 s ou ao chegar). Achou um bicho (combat) = zera tudo e luta normal. Sem zona escolhida nada muda.
    local function zoneWp(pos, zc, flat)
        local nowZ = os.clock()
        local inZone = flat(pos, zc) < 150 or (st.patrol ~= nil and flat(pos, zc) < 1500)
        if not inZone then st.patrol, st.idleAt = nil, nil; return zc end
        st.idleAt = st.idleAt or nowZ
        if not st.patrol and nowZ - st.idleAt < 20 then return nil end
        local pt = st.patrol
        if not pt or nowZ > pt.untilT or flat(pos, pt.pt) < 80 then
            local ang = math.random() * math.pi * 2
            pt = { pt = Vector3.new(zc.X + math.cos(ang) * 900, zc.Y, zc.Z + math.sin(ang) * 900), untilT = nowZ + 40 }
            st.patrol = pt
        end
        return pt.pt
    end
    Sea.step = function(force)
        Sea.st = st
        -- v54d: Fully Vulcan ligado no Mar 3 = nunca ataca sea event (so navega, igual o MV.sail)
        -- v55 fix: antes so olhava VulcFull; Auto Find Vulcan e os outros toggles (Magnet/Start/Egg/Bone/Ember)
        -- tambem paravam o barco no sea event. (sea.lua eh um modulo separado, sem acesso ao K() do pcompat2,
        -- entao checa os mesmos toggles direto aqui.)
        local vulcAtivo = Config.VulcFull or Config.VulcMagnet or Config.VulcFind or Config.VulcStart or Config.VulcEgg or Config.VulcBone or Config.VulcEmber
        if not force and vulcAtivo and getSea() == 3 then force = true end
        local o = Config.SeaOpt
        if force then Sea.forceUntil = os.clock() + 1.5 end
        if not (Config.SeaOn or force) then st.cruise = nil; return false end
        if getSea() < 2 then Diag.sea = "Sea Events: Sea 1 does not work (use Sea 2 or 3)"; return false end
        local char, hrp, hum = getChar()
        if not char then return false end

        local t = (not force) and pickTarget(scan(hrp, o.TweenUntil and 3000 or 450)) or nil
        if t then combat(t, hrp, hum); return true end
        settleTrack()
        Aim.part = nil
        Core.seaTarget = nil

        local boat, seat = myBoat(hum, hrp)
        if boat then st.hadBoat, st.noBoatAt = true, nil end
        if not boat then
            st.cruise = nil
            -- barco destruído e nenhum bicho para matar: reseta o personagem para comprar outro
            st.noBoatAt = st.noBoatAt or os.clock()
            if st.hadBoat and o.ResetBuy and os.clock() - st.resetAt > 20 and os.clock() - st.noBoatAt > 12 then
                st.hadBoat, st.resetAt = false, os.clock()
                Diag.sea = "boat destroyed: resetting character"
                pcall(function() hum.Health = 0 end)
                return true
            end
            return buyBoat(hrp, hum)
        end
        if hum.SeatPart ~= seat then
            st.cruise = nil
            local d = (hrp.Position - seat.Position).Magnitude
            if d > 150 and st.died then
                st.skip[boat] = true
                Diag.sea = "boat far away: buying another"
                return buyBoat(hrp, hum)
            end
            if d > 12 then
                Diag.sea = "going back to the boat"
                flyTo(seat.CFrame * CFrame.new(0, 3, 0))
            else
                if currentTween then currentTween:Cancel() end
                hrp.CFrame = seat.CFrame * CFrame.new(0, 2, 0)
                pcall(seat.Sit, seat, hum)
            end
            return true
        end

        -- pilotando
        st.died, st.noBoatAt = false, nil
        Config.SeaSitUntil = os.clock() + 0.6
        local pos = seat.Position
        st.waterY = st.waterY or pos.Y
        -- origem fixa: o vendedor de barcos (Mar 3 = Tiki Outpost, Mar 2 = Docas); as zonas contam a partir dele
        if not st.origin or st.originSea ~= getSea() then
            local dl = findDealer()
            st.origin = dl and dl:GetPivot().Position or pos
            st.originSea, st.wp, st.returning = getSea(), nil, false
        end
        local flat = function(a, b) return Vector3.new(a.X - b.X, 0, a.Z - b.Z).Magnitude end
        if o.Back10k and flat(pos, st.origin) > 10000 then st.returning = true end
        if st.returning then
            st.wp = st.origin
            if flat(pos, st.origin) < 300 then st.returning = false; st.wp = nil end
        else
            -- direção "para o mar": do centro do mapa para fora, passando pela origem
            local out = Vector3.new(st.origin.X, 0, st.origin.Z)
            out = (out.Magnitude > 1) and out.Unit or Vector3.new(-1, 0, 0)
            if getSea() == 3 then
                -- Mar 3: vai para a zona escolhida (1-6) e PARA nela; sem zona = Infinite (segue para sempre)
                st.wp = ((Sea.zone or Config.SeaZone) > 0) and ZONES[(Sea.zone or Config.SeaZone)] or ZONES[7]
                if (Sea.zone or Config.SeaZone) > 0 then
                    local zw = zoneWp(pos, st.wp, flat)
                    if not zw then
                        st.cruise = nil
                        Diag.sea = "stopped in zone " .. (Sea.zone or Config.SeaZone) .. " | waiting for events"
                        return true
                    end
                    st.wp = zw
                end
            elseif (Sea.zone or Config.SeaZone) > 0 then
                -- zona N = N*2000 studs a partir da origem; chegando lá, o barco PARA e espera os eventos
                st.wp = st.origin + out * ((Sea.zone or Config.SeaZone) * 2000)
                local zw = zoneWp(pos, st.wp, flat)
                if not zw then
                    st.cruise = nil
                    Diag.sea = "stopped in zone " .. (Sea.zone or Config.SeaZone) .. " | waiting for events"
                    return true
                end
                st.wp = zw
            else
                -- sem zona: segue em linha reta, infinitamente
                st.wp = pos + out * 3000
            end
        end
        if o.RoughTp and os.clock() - st.roughAt > 20
            and (workspace:FindFirstChild("RoughSea") or game:GetService("Lighting"):FindFirstChild("RoughSea")) then
            st.roughAt = os.clock()
            pcall(function() boat:PivotTo(boat:GetPivot() + Vector3.new(math.cos(st.heading) * 1500, 0, math.sin(st.heading) * 1500)) end)
        end
        -- v29: enquanto navega (sem bicho no alcance de ataque), olha mais longe (so pra NAVEGACAO, nao pra atacar) e mira
        -- o barco num evento que ja esta visivel - chega nos eventos muito mais rapido do que seguindo cego pra zona/linha reta
        -- v54c: buscando ilha (Vulcan / Mirage / Kitsune = force) o barco NAO vira na direcao de Terrorshark, navio pirata etc.
        -- (ele nem ataca nesse modo; antes ficava rodando em volta do evento, apanhando, e a busca "bugava")
        local seen = (not force) and pickTarget(scan(hrp, 2500)) or nil
        if seen then st.wp = Vector3.new(seen.part.Position.X, st.wp.Y, seen.part.Position.Z) end
        st.cruise = { boat = boat, seat = seat, target = st.wp, fly = Config.SeaFly,
            speed = Config.SeaFly and Config.SeaFlySpeed or Config.SeaSpeed }
        Diag.sea = seen and string.format("sailing towards %s (%d studs)", seen.type, math.floor(seen.dist))
            or string.format("sailing (%s, %d studs/s) | no event", Config.SeaFly and "flying" or "on the sea", st.cruise.speed)
        return true
    end

    -- Sem colisão total enquanto estiver no barco: roda a cada passo de física (Stepped), com a lista de peças em cache
    local ncParts, ncAt = {}, 0
    table.insert(Connections, RunService.Stepped:Connect(function()
        if not (Alive and (Config.SeaOn or os.clock() < (Sea.forceUntil or 0))) then return end
        local char, hrpN, hum = getChar()
        if not (char and hum) then return end
        -- v140: relato - "o barco bate nas pedras". O barco so ficava sem colisao com o personagem SENTADO; fora disso (indo ate o
        -- barco, voltando pra ele, depois de cair) ele voltava a colidir com pedras/ilhas. Agora vale pro SEU barco mesmo sem
        -- estar sentado (procura o barco a cada 0,5 s).
        local boat
        if hum.SeatPart then boat = hum.SeatPart:FindFirstAncestorOfClass("Model") end
        if not boat then
            if os.clock() - (st.ncFindAt or 0) > 0.5 then
                st.ncFindAt = os.clock()
                local okB, bb = pcall(myBoat, hum, hrpN)
                st.ncBoat = okB and bb or nil
            end
            boat = st.ncBoat
        end
        if not (boat and boat.Parent) then return end
        if os.clock() - ncAt > 1 or ncParts.boat ~= boat then
            ncAt = os.clock()
            ncParts = { boat = boat }
            for _, d in ipairs(boat:GetDescendants()) do
                if d:IsA("BasePart") then ncParts[#ncParts + 1] = d end
            end
            for _, d in ipairs(char:GetDescendants()) do
                if d:IsA("BasePart") then ncParts[#ncParts + 1] = d end
            end
        end
        for _, d in ipairs(ncParts) do
            if d.Parent then d.CanCollide = false end
        end
    end))

    table.insert(Connections, RunService.Heartbeat:Connect(function(dt)
        local c = st.cruise
        if not (Alive and c) then return end
        if not ((Config.SeaOn or os.clock() < (Sea.forceUntil or 0)) and c.boat and c.boat.Parent) then st.cruise = nil; return end
        pcall(function()
            local pos = c.boat:GetPivot().Position
            local dir = Vector3.new(c.target.X - pos.X, 0, c.target.Z - pos.Z)
            -- barco sem colisão: atravessa paredes/ilhas (throttle de 0,5s)
            if os.clock() - (c.nc or 0) > 0.5 then
                c.nc = os.clock()
                for _, d in ipairs(c.boat:GetDescendants()) do
                    if d:IsA("BasePart") then d.CanCollide = false end
                end
            end
            if dir.Magnitude < 20 then return end
            dir = dir.Unit
            local y = c.fly and (st.waterY + 30) or pos.Y
            local np = Vector3.new(pos.X + dir.X * c.speed * dt, y, pos.Z + dir.Z * c.speed * dt)
            c.boat:PivotTo(CFrame.lookAt(np, np + dir))
            -- velocidade na direção do destino (o servidor não "puxa de volta" o barco para trás)
            local vel = dir * c.speed
            if c.fly then vel = Vector3.new(vel.X, 0, vel.Z) end
            local pp = c.seat or c.boat.PrimaryPart
            if pp then pp.AssemblyLinearVelocity = vel end
        end)
    end))
end


AFL.Sea = Sea
]===] end
    PC.src["mv"] = function() return [===[
local __E = ...
local AFL = __E.AFL
local Aim, Config, Core, Diag, Fight, Fluent, FruitM1 = __E.Aim, __E.Config, __E.Core, __E.Diag, __E.Fight, __E.Fluent, __E.FruitM1
local InvCache, Player, State, Tabs, aliveParts, cfAttack, enemiesList = __E.InvCache, __E.Player, __E.State, __E.Tabs, __E.aliveParts, __E.cfAttack, __E.enemiesList
local equipWeapon, fightEnemy, findEnemy, findTool, findToolByName, flyTo, getChar = __E.equipWeapon, __E.fightEnemy, __E.findEnemy, __E.findTool, __E.findToolByName, __E.flyTo, __E.getChar
local getSea, hasItem, invCount, invoke, persist, pressKey = __E.getSea, __E.hasItem, __E.invCount, __E.invoke, __E.persist, __E.pressKey
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local VirtualInputManager = game:GetService("VirtualInputManager")
local Sea = AFL.Sea
local Alive = true
AFL.onUnload(function() Alive = false end);
-- ============ MIRAGE + VULCAN (guesses: object names come from memory of other hubs, not verified in game) ============
AFL.MV = {}
do
    local MV = AFL.MV
    local Lighting = game:GetService("Lighting")
    function MV.mapChild(pattern)
        local map = workspace:FindFirstChild("Map")
        if not map then return nil end
        for _, c in ipairs(map:GetChildren()) do
            if string.find(string.lower(c.Name), pattern, 1, true) then return c end
        end
    end
    function MV.trigger(obj)
        if obj:IsA("ProximityPrompt") then
            if fireproximityprompt then pcall(fireproximityprompt, obj) end
        elseif obj:IsA("ClickDetector") then
            if fireclickdetector then pcall(fireclickdetector, obj) end
        end
    end
    function MV.touch(part)
        local _, hrp = getChar()
        if hrp and firetouchinterest then
            pcall(function()
                firetouchinterest(hrp, part, 0)
                task.wait()
                firetouchinterest(hrp, part, 1)
            end)
        end
    end
    function MV.hold()
        if Sea.st then Sea.st.cruise = nil end
    end
    function MV.sail(zone)
        Sea.zone = zone
        local r = Sea.step and Sea.step(true)
        Sea.zone = nil
        return r
    end
    function MV.pressKey(name)
        local kc = Enum.KeyCode[name]
        if not kc then return end
        pcall(function()
            VirtualInputManager:SendKeyEvent(true, kc, false, game)
            task.wait(0.1)
            VirtualInputManager:SendKeyEvent(false, kc, false, game)
        end)
    end
    function MV.equip(sub)
        local tool = findToolByName(sub)
        local ch = Player.Character
        local hum = ch and ch:FindFirstChildOfClass("Humanoid")
        if tool and hum and tool.Parent ~= ch then pcall(function() hum:EquipTool(tool) end) end
        return tool ~= nil
    end
    function MV.islandTop(isl)
        local ok, cf, size = pcall(function() return isl:GetBoundingBox() end)
        if ok then return cf.Position + Vector3.new(0, size.Y / 2 + 30, 0) end
        local p = isl:FindFirstChildWhichIsA("BasePart", true)
        return p and (p.Position + Vector3.new(0, 150, 0))
    end
end

-- ---- Mirage Island (Sea 3) ----
AFL.Mirage = { gearAt = 0, leverDone = false, lookAt = 0, gearTouches = 0 }
do
    local M, MV = AFL.Mirage, AFL.MV
    local Lighting = game:GetService("Lighting") -- v31 fix: was only declared in the MV block above, so the "look at the moon" step crashed (nil index)
    local TEMPLE = Vector3.new(28286, 14897, 103) -- Temple of Time (from other hubs)
    function M.island() return MV.mapChild("mysticisland") or MV.mapChild("mirage") end
    function M.findGear(isl)
        local best, bd
        local _, hrp = getChar()
        for _, d in ipairs(isl:GetDescendants()) do
            if d:IsA("BasePart") and d.Material == Enum.Material.Neon and (d.Name:lower():find("gear", 1, true) or d:IsA("MeshPart")) then
                local dist = hrp and (d.Position - hrp.Position).Magnitude or 0
                if not bd or dist < bd then best, bd = d, dist end
            end
        end
        return best
    end
    function M.step()
        if not Config.MirageOn then return false end
        if getSea() ~= 3 then Diag.mirage = "Mirage only works in Sea 3"; return false end
        local char, hrp, hum = getChar()
        if not char then return false end
        local isl = M.island()
        if not isl then
            M.gearTouches, M.leverDone = 0, false
            State.Mode = "Auto Mirage"
            Diag.mirage = "sailing, ignoring sea events"
            return MV.sail(Config.SeaZone > 0 and Config.SeaZone or nil)
        end
        MV.hold()
        State.Mode = "Auto Mirage"
        if not Config.PullLever then
            State.Text = "Mirage Island found"
            Diag.mirage = "Mirage Island found (Auto Pull Lever is off)"
            return false
        end
        if M.leverDone then Diag.mirage = "lever already pulled on this island"; return false end
        -- 1) blue gear
        local gear = (M.gearTouches < 6) and M.findGear(isl)
        if gear then
            State.Text = "Getting the Blue Gear"
            Diag.mirage = "touching the gear"
            hrp.CFrame = CFrame.new(gear.Position + Vector3.new(0, 3, 0))
            MV.touch(gear)
            MV.trigger(gear:FindFirstChildWhichIsA("ProximityPrompt", true) or gear:FindFirstChildWhichIsA("ClickDetector", true) or gear)
            M.gearTouches += 1
            task.wait(0.4)
            return true
        end
        -- 2) no gear yet: go up, look at the moon and use the race ability (key T) during the night
        if M.gearTouches == 0 then
            local top = MV.islandTop(isl)
            local t = Lighting.ClockTime
            local night = t >= 18 or t <= 5
            if top then flyTo(CFrame.new(top)) end
            if night then
                State.Text = "Looking at the moon (race ability)"
                Diag.mirage = "night: looking at the moon + race ability"
                local cam = workspace.CurrentCamera
                pcall(function()
                    local dir = Lighting:GetMoonDirection()
                    cam.CFrame = CFrame.lookAt(cam.CFrame.Position, cam.CFrame.Position + dir * 1000)
                end)
                if os.clock() - M.lookAt > 1.5 then M.lookAt = os.clock(); MV.pressKey("T") end
            else
                Diag.mirage = "waiting for the night to find the gear"
            end
            return true
        end
        -- 3) gear touched: Temple of Time lever
        State.Text = "Temple of Time: lever"
        if (hrp.Position - TEMPLE).Magnitude > 150 then
            hrp.CFrame = CFrame.new(TEMPLE + Vector3.new(0, 5, 0))
            task.wait(0.5)
            return true
        end
        local found
        for _, d in ipairs(workspace:GetDescendants()) do
            if (d:IsA("ProximityPrompt") or d:IsA("ClickDetector")) and d.Parent then
                local nm = (d.Parent.Name .. " " .. (d:IsA("ProximityPrompt") and tostring(d.ActionText) or "")):lower()
                local pp = d.Parent:IsA("BasePart") and d.Parent.Position or nil
                if pp and (pp - hrp.Position).Magnitude < 200 and (nm:find("lever", 1, true) or nm:find("pull", 1, true)) then
                    found = d
                    hrp.CFrame = CFrame.new(pp + Vector3.new(0, 4, 4))
                    task.wait(0.3)
                    MV.trigger(d)
                    break
                end
            end
        end
        if found then M.leverDone = true; Diag.mirage = "lever pulled" else Diag.mirage = "lever not found near the Temple of Time" end
        return true
    end
end

-- ---- Inventory read straight from the game's client data (same method as the Banana hub) ----
-- Finds, at runtime, the store (GetItems/ReadItem), the KEYS table (QUANTITY/MASTERY) and ReplicatedStorage.ItemConfig.
AFL.Inv = { map = {}, at = 0, tries = 0, state = "not started" }
do
    local I = AFL.Inv
    local RS = game:GetService("ReplicatedStorage")
    local store, keys, cfg
    local function try(f) local ok, v = pcall(f); if ok then return v end end
    local function discover()
        if store and keys and cfg then return true end
        if not cfg then
            local ms = RS:FindFirstChild("ItemConfig")
            cfg = ms and try(function() return require(ms) end)
        end
        if (not store or not keys) and getgc and os.clock() - (I.lastScan or -99) > 20 then
            I.lastScan = os.clock()
            I.tries += 1
            for _, v in ipairs(getgc(true)) do
                if type(v) == "table" then
                    if not keys and try(function() return rawget(v, "QUANTITY") end) ~= nil and try(function() return rawget(v, "MASTERY") end) ~= nil then keys = v end
                    if not store and type(try(function() return v.GetItems end)) == "function" and type(try(function() return v.ReadItem end)) == "function" then store = v end
                    if store and keys then break end
                end
            end
        end
        return (store and keys and cfg) and true or false
    end
    -- Método principal (Quantum Onyx): remote GetAllItemValues devolve {ItemId, NetworkedUID, Key, Value}; o nome vem do ItemConfig
    local netMod
    local function viaRemote()
        if not netMod then
            local mods = RS:FindFirstChild("Modules")
            local nf = mods and mods:FindFirstChild("Net")
            netMod = nf and try(function() return require(nf) end)
        end
        local cfg2 = cfg
        if not cfg2 then
            local ms = RS:FindFirstChild("ItemConfig")
            cfg2 = ms and try(function() return require(ms) end)
            cfg = cfg2 or cfg
        end
        if not (netMod and cfg2) then return nil, "Net/ItemConfig missing" end
        local ok, res = pcall(function() return netMod:RemoteFunction("GetAllItemValues"):InvokeServer() end)
        if not ok or type(res) ~= "table" then return nil, "GetAllItemValues failed: " .. tostring(res) end
        local by, rows = {}, 0
        for _, r in next, res do
            rows += 1
            local k = tostring(r.ItemId) .. "_" .. tostring(r.NetworkedUID)
            by[k] = by[k] or { id = r.ItemId, at = {} }
            if r.Value ~= nil then by[k].at[r.Key] = r.Value end
        end
        local m, n, mast = {}, 0, {}
        for _, it in next, by do
            local okc, conf = pcall(function() return cfg2.match(it.id):unwrap() end)
            local names = {}
            if okc and conf then
                local dl = conf.Index and conf.Index.DebugLabel
                if dl then dl = tostring(dl); names[#names + 1] = dl:match("^(.-)%s*%[") or dl end
                local d = conf.Display and conf.Display.Name
                if d then names[#names + 1] = tostring(d) end
                local sk = conf.Index and conf.Index.StorageKey
                if sk then names[#names + 1] = tostring(sk) end
            end
            local mv = tonumber(it.at.Mastery)
            if mv and it.at.IsOwned == true then for _, nm in ipairs(names) do mast[nm] = math.max(mast[nm] or 0, mv) end end
            local q = tonumber(it.at.Quantity) -- só Quantity conta (IsOwned também vale para receitas/itens desbloqueados e dava falso positivo)
            if q and q > 0 and #names > 0 then
                n += 1
                for _, nm in ipairs(names) do
                    m[nm] = math.max(m[nm] or 0, q)
                    local nk = "#" .. string.lower(string.gsub(nm, "[^%w]", ""))
                    m[nk] = math.max(m[nk] or 0, q)
                end
            end
        end
        if n == 0 then return nil, "GetAllItemValues returned " .. rows .. " rows but no item matched" end
        I.mast = mast
        return m, n .. " items read (GetAllItemValues)"
    end
    function I.refresh()
        if os.clock() - I.at < 4 then return end
        I.at = os.clock()
        local m0, st0 = viaRemote()
        if m0 then I.map, I.state = m0, st0 return end
        I.remoteErr = st0
        if not discover() then
            I.state = string.format("module not found (store=%s keys=%s config=%s) | remote: %s", tostring(store ~= nil), tostring(keys ~= nil), tostring(cfg ~= nil), tostring(I.remoteErr))
            return
        end
        local m, n, mast = {}, 0, {}
        local ok, err = pcall(function()
            local a, b, c = store:GetItems(keys.QUANTITY)
            local function each(fn)
                if type(a) == "function" then for k, v in a, b, c do fn(k, v) end
                elseif type(a) == "table" then for k, v in pairs(a) do fn(k, v) end end
            end
            each(function(_, it)
                local q = type(it) == "table" and tonumber(it.Value)
                if q and q > 0 then
                    local okc, conf = pcall(function() return cfg.match(it.ItemId):unwrap() end)
                    local name
                    if okc and conf then
                        local d = conf.Display
                        name = (d and d.Name) or (conf.Index and conf.Index.StorageKey)
                    end
                    name = tostring(name or ("ItemId_" .. tostring(it.ItemId)))
                    n += 1
                    m[name] = (m[name] or 0) + q
                    local nk = "#" .. string.lower(string.gsub(name, "[^%w]", ""))
                    m[nk] = (m[nk] or 0) + q
                    -- v85 fix: esse fallback (quando o remote "GetAllItemValues" do viaRemote() nao existe/muda de nome
                    -- na build atual do jogo) so lia Quantity - NUNCA lia a Mastery, entao I.mast ficava sempre vazio e
                    -- TODA arma virava "mastery nao pode ser ler" pro Auto Mastery/Auto 600 (ele so fica parado sem
                    -- treinar nada). Igual o VX Hub faz (ReadItem direto pelo ItemId+NetworkedUID do proprio item, sem
                    -- depender do remote que pode ter mudado de nome): le a mastery de cada item aqui tambem.
                    local okm, mv = pcall(function() return store:ReadItem(keys.MASTERY, it.ItemId, it.NetworkedUID) end)
                    mv = okm and tonumber(mv)
                    if mv then
                        mast[name] = math.max(mast[name] or 0, mv)
                        mast[nk] = math.max(mast[nk] or 0, mv)
                    end
                end
            end)
        end)
        if ok and next(mast) then I.mast = mast end
        if ok then I.map, I.state = m, n .. " item types read from the game data"
        else I.state = "read error: " .. tostring(err) end
    end
    function I.mastery(name) return I.mast and I.mast[name] or nil end
    function I.count(name)
        pcall(I.refresh)
        local nk = "#" .. string.lower(string.gsub(tostring(name), "[^%w]", ""))
        return I.map[name] or I.map[nk] or 0
    end
end


-- ---- Tiro por remote (Dragonstorm / Skull Guitar): mira sozinho no alvo, sem clicar na tela e sem mexer na câmera ----
-- Base: Quantum Onyx (RE/ShootGunEvent + Validator2 com o contador do CombatController) e Banana (SpamGunDragonStorm / Skull Guitar "TAP").
AFL.Shot = { last = 0, state = "not started" }
do
    local S = AFL.Shot
    local RS = game:GetService("ReplicatedStorage")
    local getup = getupvalue or (debug and debug.getupvalue)
    local setup = setupvalue or (debug and debug.setupvalue)
    local ctrlFn, shootEv, validator
    local function init()
        if shootEv and validator then return true end
        pcall(function()
            local mods = RS:FindFirstChild("Modules")
            local net = mods and mods:FindFirstChild("Net")
            shootEv = shootEv or (net and net:FindFirstChild("RE/ShootGunEvent"))
            local rem = RS:FindFirstChild("Remotes")
            validator = validator or (rem and rem:FindFirstChild("Validator2"))
        end)
        return shootEv ~= nil
    end
    -- contador que o servidor confere (mesma conta do CombatController)
    local function sig()
        if not ctrlFn and getup then
            pcall(function()
                local cc = require(RS.Controllers.CombatController)
                ctrlFn = getup(cc.Attack, 9)
            end)
        end
        if not (ctrlFn and getup and setup) then return 0, 0 end
        local ok, a, b = pcall(function()
            local v19, v20, v21, v22 = getup(ctrlFn, 15), getup(ctrlFn, 13), getup(ctrlFn, 16), getup(ctrlFn, 17)
            local v23, v24, v25 = getup(ctrlFn, 14), getup(ctrlFn, 18), getup(ctrlFn, 19)
            if not (v19 and v20 and v21 and v22 and v23 and v24 and v25) then return 0, 0 end
            local n = ((v19 * v23 + v20 * v21) % v22 * v22 + v20 * v23) % v24
            local n2 = math.floor(n / v22)
            local n3 = n - n2 * v22
            local n4 = v25 + 1
            setup(ctrlFn, 15, n2); setup(ctrlFn, 13, n3); setup(ctrlFn, 19, n4)
            return math.floor(n / v24 * 16777215), n4
        end)
        if ok then return a, b end
        return 0, 0
    end
    function S.fire(sc)
        local char = Player.Character
        local tool = char and char:FindFirstChildOfClass("Tool")
        local part = sc.part
        if not (tool and part and part.Parent) then return end
        local name = string.lower(tool.Name)
        local pos = part.Position
        if os.clock() - S.last < 0.1 then return end
        if sc.kind == "sg" and string.find(name, "skull guitar", 1, true) then
            S.last = os.clock()
            local re = tool:FindFirstChild("RemoteEvent")
            if re then re:FireServer("TAP", pos); S.state = "Skull Guitar: TAP" end
        elseif sc.kind == "gun" and tool.ToolTip == "Gun" then
            S.last = os.clock()
            local re = tool:FindFirstChild("RemoteEvent")
            if re and string.find(name, "skull guitar", 1, true) then re:FireServer("TAP", pos); S.state = "Skull Guitar: TAP"; return end
            if not init() then S.state = "RE/ShootGunEvent not found"; return end
            pcall(function()
                tool:SetAttribute("IsReloading_Client", false)
                tool:SetAttribute("LocalShotsLeft", 100)
                tool:SetAttribute("LocalTotalShots", (tool:GetAttribute("LocalTotalShots") or 0) + 1)
            end)
            local a, b = sig()
            if validator then pcall(function() validator:FireServer(a, b) end) end
            pcall(function() shootEv:FireServer(pos, { part }) end)
            S.state = "Gun " .. tool.Name .. ": shot at " .. tostring(part.Name)
        elseif sc.kind == "ds" and string.find(name, "dragonstorm", 1, true) then
            if not init() then S.state = "RE/ShootGunEvent not found"; return end
            S.last = os.clock()
            pcall(function()
                tool:SetAttribute("IsReloading_Client", false)
                tool:SetAttribute("LocalShotsLeft", 100)
                tool:SetAttribute("LocalTotalShots", (tool:GetAttribute("LocalTotalShots") or 0) + 1)
            end)
            local a, b = sig()
            if validator then pcall(function() validator:FireServer(a, b) end) end
            pcall(function() shootEv:FireServer(pos, { part }) end)
            S.state = "Dragonstorm: shot at " .. tostring(part.Name)
        end
    end
    Config.ShotFire = S.fire
end

function AFL.invDebug()
    local raw = InvCache.raw
    if type(raw) ~= "table" then return "game data: " .. tostring(AFL.Inv.state) .. " | remote: no data" end
    local n, hits = 0, {}
    for _, it in pairs(raw) do
        n += 1
        local nm = type(it) == "table" and tostring(it.Name) or tostring(_)
        local l = string.lower(nm)
        if string.find(l, "scrap", 1, true) or string.find(l, "ember", 1, true) or string.find(l, "magnet", 1, true) then
            local f = {}
            if type(it) == "table" then for k, v in pairs(it) do if type(v) ~= "table" then f[#f + 1] = tostring(k) .. "=" .. tostring(v) end end
            else f[1] = tostring(it) end
            hits[#hits + 1] = nm .. "{" .. table.concat(f, ",") .. "}"
        end
    end
    return "game data: " .. tostring(AFL.Inv.state) .. " | remote: " .. n .. " entries | " .. (#hits > 0 and table.concat(hits, " ") or "no scrap/ember/magnet entry")
end

-- ---- Vulcan (Prehistoric Island, Sea 3, Sea Danger Level 6) ----
AFL.Vulc = { scrapAt = 0, last = 0 }
do
    local V, MV = AFL.Vulc, AFL.MV
    -- Real names taken from the Banana hub code: workspace.Map.PrehistoricIsland, Core.ActivationPrompt, Core.PrehistoricRelic.Skull,
    -- Core.VolcanoRocks.Rock (VFXLayer.Specs.Enabled), Core.SpawnedDragonEggs.DragonEgg.Molten, workspace.DinoBone, HUD timers.
    function V.island()
        local map = workspace:FindFirstChild("Map")
        return (map and map:FindFirstChild("PrehistoricIsland")) or MV.mapChild("prehistor")
    end
    -- v24: marcador GLOBAL da ilha (_WorldOrigin.Locations["Prehistoric Island"], como o Quantum/Banana): existe assim que o
    -- evento nasce no servidor, mesmo quando o modelo do mapa ainda nao carregou (ilha longe). Devolve (objeto, Vector3).
    function V.marker()
        local ok, m = pcall(function()
            local wo = workspace:FindFirstChild("_WorldOrigin")
            local locs = wo and wo:FindFirstChild("Locations")
            return locs and locs:FindFirstChild("Prehistoric Island")
        end)
        if not (ok and m) then return nil end
        local okP, p = pcall(function() return m:IsA("BasePart") and m.Position or m:GetPivot().Position end)
        return m, okP and p or nil
    end
    -- posicao da ilha: do modelo carregado ou do marcador. Devolve (Vector3, "map"|"marker")
    function V.islandPos()
        local isl = V.island()
        if isl then
            local ok, p = pcall(function() return isl:GetPivot().Position end)
            if ok then return p, "map" end
        end
        local _, mp = V.marker()
        if mp then return mp, "marker" end
    end
    -- contadores da sessao (aparecem na aba Vulcan)
    V.stats = { islands = 0, golems = 0, rocks = 0, eggs = 0, bones = 0, resets = 0, crafts = 0, since = os.clock() }
    V.golemSeen = setmetatable({}, { __mode = "k" })
    V.act, V.actT = nil, 0                                     -- o que o motor esta fazendo agora (para o painel de status). NAO usar V.actAt: ele e o horario da ativacao do evento
    local function setAct(a) V.act, V.actT = a, os.clock() end
    local function vnotify(text, secs)
        pcall(function() Fluent:Notify({ Title = "Vulcan", Content = text, Duration = secs or 4 }) end)
    end
    local function flag(k) return Config.VulcFull or Config[k] end
    local function hud(name)
        local ok, v = pcall(function() return Player.PlayerGui.Main.TopHUDList[name].Visible end)
        return ok and v == true
    end
    local function netCall(name, ...)
        local m = ReplicatedStorage:FindFirstChild("Modules")
        local n = m and m:FindFirstChild("Net")
        local r = n and n:FindFirstChild(name)
        if not r then return false, "remote " .. name .. " not found" end
        local args, done, ok, res = table.pack(...), false, false, nil
        task.spawn(function() ok, res = pcall(r.InvokeServer, r, table.unpack(args, 1, args.n)); done = true end)
        local t0 = os.clock()
        while not done and os.clock() - t0 < 8 do task.wait(0.05) end
        if not done then return false, "no response (8s)" end
        return ok, res
    end
    local function npcCF(name)
        for _, holder in ipairs({ workspace:FindFirstChild("NPCs"), ReplicatedStorage:FindFirstChild("NPCs") }) do
            local n = holder and holder:FindFirstChild(name)
            local p = n and (n:FindFirstChild("HumanoidRootPart") or n.PrimaryPart or n:FindFirstChildWhichIsA("BasePart", true))
            if p then return p.CFrame end
        end
    end
    local function spawnOf(name)
        local wo = workspace:FindFirstChild("_WorldOrigin")
        local es = wo and wo:FindFirstChild("EnemySpawns")
        for _, p in ipairs(es and es:GetChildren() or {}) do
            if p:IsA("BasePart") and string.find(p.Name, name, 1, true) then return p end
        end
    end
    local function killMob(name, why)
        local e = findEnemy({ name })
        State.Mode = "Auto Volcanic Magnet"
        -- v42: findEnemy acha o mob mais proximo em QUALQUER lugar do mapa, sem limite de distancia. Sem este teto, um
        -- Jungle Pirate / Hydra Enforcer / Venomous Assailant que spawna longe (ex.: perto de outro jogador, outra ilha)
        -- "sequestrava" o Fully Vulcan: o motor parava de chamar MV.sail() para tentar chegar nele, e o barco (que so
        -- anda enquanto o sail e chamado a cada tick) ficava parado no meio do mar ate o mob sumir ou morrer.
        if e then
            local _, hrp = getChar()
            local eh, er = aliveParts(e)
            local d = (hrp and er) and (hrp.Position - er.Position).Magnitude or math.huge
            if d > 2000 then e = nil end
        end
        if e then
            -- v24: puxa varios mobs juntos (Jungle Pirate / Hydra Enforcer / Venomous Assailant) para o Scrap Metal e a missao do Dragon Hunter sairem bem mais rapido
            local n = math.clamp(math.floor(tonumber(Config.VulcMobPull) or 5), 1, 10)
            if n > 1 then Fight.bringMax, Fight.bringRange, Fight.bringUntil = n, 350, os.clock() + 1.5 end
            State.Text = why
            fightEnemy(e, { name }, true)
            return true
        end
        -- v145: sem mob carregado: visita os pontos de spawn UM POR UM (antes ia sempre ao mesmo e ficava parado la se nao tinha mob).
        -- Pontos = pecas de _WorldOrigin.EnemySpawns com o nome do mob + os spawns da tabela do Level Farm (Deep Forest) como reserva.
        local _, hrp0 = getChar()
        if hrp0 then
            V.spVisit = V.spVisit or setmetatable({}, { __mode = "k" })
            V.spVisitP = V.spVisitP or {}
            local now = os.clock()
            local cands = {}
            local wo = workspace:FindFirstChild("_WorldOrigin")
            local es = wo and wo:FindFirstChild("EnemySpawns")
            for _, pt in ipairs(es and es:GetChildren() or {}) do
                if pt:IsA("BasePart") and string.find(pt.Name, name, 1, true) then cands[#cands + 1] = { key = pt, pos = pt.Position } end
            end
            pcall(function()
                for _, ent in ipairs(Core.level.DATA[3] or {}) do
                    if ent.mob == name then
                        for _, q in ipairs(ent.sp or {}) do cands[#cands + 1] = { key = "d" .. q[1] .. "_" .. q[3], pos = Vector3.new(q[1], q[2], q[3]) } end
                    end
                end
            end)
            local pick, pd
            for _, c in ipairs(cands) do
                local seen = V.spVisitP[c.key]
                if not seen or now - seen > 45 then
                    local d = (c.pos - hrp0.Position).Magnitude
                    if not pd or d < pd then pick, pd = c, d end
                end
            end
            if pick then
                local goal = pick.pos + Vector3.new(0, 30, 0)
                if (hrp0.Position - goal).Magnitude > 60 then
                    V.spArrive = nil
                    State.Text = why .. " (going to the spawn)"
                    flyTo(CFrame.new(goal))
                    return true
                end
                V.spArrive = V.spArrive or now
                State.Text = why .. " (waiting for the enemies to load)"
                if now - V.spArrive > 3 then V.spVisitP[pick.key] = now; V.spArrive = nil end
                return true
            end
        end
        return false
    end
    local function skills()
        pcall(equipWeapon)
        for _, k in ipairs({ Enum.KeyCode.Z, Enum.KeyCode.X, Enum.KeyCode.C, Enum.KeyCode.V }) do
            pressKey(k)
            task.wait(0.15)
        end
    end
    -- ===== v30: usa as armas e ataques escolhidos (Melee / Blox Fruit / Sword / Gun; M1 e teclas) contra uma parte =====
    local VWEAPONS = { "Melee", "Blox Fruit", "Sword", "Gun" }
    local VKEYS = { "Z", "X", "C", "V", "F" }
    local function needClose(wset)
        return wset and (wset.Melee or wset.Sword) and true or false -- Melee/Sword só alcançam de perto
    end
    -- v53: clique bem mais rapido (1 por frame em vez de 1 a cada 0,05 s; a fruta clica 2x por frame e mira na parte)
    -- v55 fix: Melee usava so o golpe do jogo (cfAttack) e Sword nao tinha NENHUM golpe aqui (so o Activate generico
    -- la embaixo) - Sword praticamente nao batia nos golens. Agora os dois usam o MESMO click do motor principal
    -- (Core.meleeSwordClick: golpe do jogo + registro de hit pelo remote + anti-travada), igual ao resto do hub.
    local function m1Burst(tip, part)
        local t0 = os.clock()
        while Alive and part.Parent and os.clock() - t0 < 0.9 do
            Aim.part = part
            if tip == "Melee" or tip == "Sword" then pcall(Core.meleeSwordClick, tip)
            elseif tip == "Blox Fruit" then pcall(FruitM1.tick); pcall(FruitM1.tick)
            elseif tip == "Gun" and Config.ShotFire then pcall(Config.ShotFire, { kind = "gun", part = part }) end
            pcall(function()
                local tool = Player.Character and Player.Character:FindFirstChildOfClass("Tool")
                if tool and tip ~= "Melee" and tip ~= "Sword" then tool:Activate() end
            end)
            if tip == "Gun" then task.wait(0.05) else task.wait() end
        end
    end
    -- devolve true se pelo menos uma arma escolhida foi usada
    function V.useSet(wkey, kkey, part)
        local used = false
        local wset, kset = Config[wkey] or {}, Config[kkey] or {}
        for _, tip in ipairs(VWEAPONS) do
            if Alive and wset[tip] and part and part.Parent then
                Config.SeaTool, Config.SeaUntil = { tip = tip }, os.clock() + 1.5
                pcall(equipWeapon)
                local tool = findTool(tip)
                if tool then
                    used = true
                    task.wait(0.2)
                    local ks = kset[tip] or {}
                    Aim.part = part
                    if ks.M1 then m1Burst(tip, part) end
                    for _, k in ipairs(VKEYS) do
                        if ks[k] and Alive and part.Parent then
                            local kc = Enum.KeyCode[k]
                            if kc then
                                Config.SeaUntil = os.clock() + 1.5
                                pcall(AFL.tvHook)
                                AFL.TV.aimPos, AFL.TV.aimPart = part.Position, part
                                VirtualInputManager:SendKeyEvent(true, kc, false, game)
                                task.wait(0.15)
                                VirtualInputManager:SendKeyEvent(false, kc, false, game)
                                task.wait(0.06)
                            end
                        end
                    end
                end
            end
        end
        Config.SeaUntil = 0
        AFL.TV.aimPos, AFL.TV.aimPart = nil, nil
        return used
    end
    -- árvores / plantas da missão (v41): SÓ as plantas quebráveis do jogo ("Meshes/plant1_Icosphere") perto do platô da missão.
    -- Antes aceitava qualquer "tree"/"meshes/" num raio de 900 studs: o personagem ficava batendo em árvore decorativa que não quebra.
    -- Varredura leve: só o Map, no máximo 1x a cada 12s (3s quando acabaram as plantas).
    V.badPlant, V.plantTry = setmetatable({}, { __mode = "k" }), setmetatable({}, { __mode = "k" })
    V.plants, V.plantsAt, V.plantsDry = {}, 0, false
    local PLANT_CENTER = Vector3.new(5290, 1000, 390)
    local PLANT_NAME = "meshes/plant1_icosphere"
    local function plantNear(p, r, ry) -- horizontal <= r e vertical <= ry em relação ao platô da missão
        local d = p - PLANT_CENTER
        return math.sqrt(d.X * d.X + d.Z * d.Z) <= r and math.abs(d.Y) <= ry
    end
    local function plantAlive(d)
        if not d.Parent or V.badPlant[d] then return false end
        local m = d:FindFirstAncestorWhichIsA("Model")
        return not (m and m:GetAttribute("AlreadyDestroyedClient"))
    end
    local function nearestPlant(hrp)
        local now = os.clock()
        if now - V.plantsAt > (V.plantsDry and 3 or 12) then
            V.plantsAt = now
            local area, wide = {}, {}
            -- 1) consulta espacial (rápida) só no platô; 2) se não achar nada, varre o Map inteiro (mais pesado)
            local okQ, near = pcall(function() return workspace:GetPartBoundsInRadius(PLANT_CENTER, 450, OverlapParams.new()) end)
            if okQ and type(near) == "table" then
                for _, d in ipairs(near) do
                    if string.lower(d.Name) == PLANT_NAME and plantNear(d.Position, 450, 250) and plantAlive(d) then area[#area + 1] = d end
                end
            end
            if #area == 0 then
                for _, d in ipairs((workspace:FindFirstChild("Map") or workspace):GetDescendants()) do
                    if d:IsA("BasePart") and string.lower(d.Name) == PLANT_NAME and plantAlive(d) then
                        if plantNear(d.Position, 450, 250) then area[#area + 1] = d
                        elseif plantNear(d.Position, 1200, 450) then wide[#wide + 1] = d end
                    end
                end
            end
            V.plants = { area, wide }
        end
        for _, list in ipairs(V.plants) do
            local best, bd
            for _, d in ipairs(list) do
                if plantAlive(d) then
                    local dist = (d.Position - hrp.Position).Magnitude
                    if not bd or dist < bd then best, bd = d, dist end
                end
            end
            if best then V.plantsDry = false; return best end
        end
        V.plantsDry = true
    end
    -- toca na caveira da relíquia (voa até ela, firetouchinterest + prompt/click se houver)
    local function touchSkull(skull, hrp)
        if (hrp.Position - skull.Position).Magnitude > 9 then
            flyTo(skull.CFrame * CFrame.new(0, 3, 0))
            return false
        end
        pcall(function()
            if firetouchinterest then
                firetouchinterest(hrp, skull, 0)
                task.wait()
                firetouchinterest(hrp, skull, 1)
            end
        end)
        for _, o in ipairs({ skull, skull.Parent }) do
            if o then
                for _, dsc in ipairs(o:GetDescendants()) do
                    if dsc:IsA("ProximityPrompt") or dsc:IsA("ClickDetector") then MV.trigger(dsc) end
                end
            end
        end
        return true
    end
    local function ember()
        for _, d in ipairs(workspace:GetChildren()) do
            if d.Name == "EmberTemplate" and not V.badEmber[d] then
                local p = d:FindFirstChild("Part")
                if p and p.Position.Y > -100 then return d, p end
            end
        end
    end
    V.badEmber = setmetatable({}, { __mode = "k" })

    -- Blaze Ember (lógica do Quantum Onyx + Banana): Dragon Hunter fica no Dojo (5864, 1209, 808).
    -- RequestQuest + Check devolvem o texto da missão (Defeat Hydra Enforcers / Venomous Assailants, ou Destroy trees).
    -- Ao terminar aparece "Task completed!" -> pede a próxima. Os Blaze Ember caem como EmberTemplate (Part com Y > 10).
    local DH_CF = CFrame.new(5864, 1209, 808)
    local function taskDone()
        local ok, r = pcall(function()
            local n = Player.PlayerGui:FindFirstChild("Notifications")
            if not n then return false end
            for _, d in ipairs(n:GetDescendants()) do
                if d:IsA("TextLabel") and (string.find(d.Text, "Task completed!", 1, true) or string.find(d.Text, "Head back to the Dojo", 1, true)) then return true end
            end
            return false
        end)
        return ok and r
    end
    function V.checkQuest()
        netCall("RF/DragonHunter", { Context = "RequestQuest" })
        local ok, r = netCall("RF/DragonHunter", { Context = "Check" })
        if not (ok and type(r) == "table" and r.Text) then return nil, tostring(r) end
        local t = tostring(r.Text)
        if string.find(t, "Destroy", 1, true) or string.find(t, "Tree", 1, true) or string.find(t, "tree", 1, true) then return { kind = "tree", text = t } end
        if string.find(t, "Venomous", 1, true) or string.find(t, "Assailant", 1, true) then return { kind = "kill", mob = "Venomous Assailant", text = t } end
        if string.find(t, "Hydra", 1, true) or string.find(t, "Enforcer", 1, true) or string.find(t, "Defeat", 1, true) then return { kind = "kill", mob = "Hydra Enforcer", text = t } end
        return { kind = "unknown", text = t }
    end
    V.treePts = { Vector3.new(5326, 1000.5, 441.52), Vector3.new(5344.88, 1000.5, 359.94), Vector3.new(5260.73, 1000.5, 345.5), Vector3.new(5237.99, 1000.5, 429.64) }

    function V.emberStep()
        setAct("ember")
        State.Mode = Config.VulcEmber and not Config.VulcFull and not Config.VulcMagnet and "Auto Blaze Ember" or "Auto Volcanic Magnet"
        local e, part = ember()
        if e then
            V.emberSince = V.emberSince or os.clock()
            State.Text = "Collecting Blaze Ember"
            Diag.vulc = "Blaze Ember " .. invCount("Blaze Ember") .. "/15: collecting the drop"
            if os.clock() - V.emberSince > 15 then V.badEmber[e] = true; V.emberSince = nil; return true end
            flyTo(part.CFrame * CFrame.new(0, 3, 0))
            return true
        end
        if V.emberSince then V.emberSince, V.cur = nil, nil end -- ember collected: next task
        if V.cur and os.clock() - (V.curAt or 0) > 4 and taskDone() then V.cur = nil end
        local _, hrp = getChar()
        if not V.cur or os.clock() - (V.curAt or 0) > 180 then
            local cf = npcCF("Dragon Hunter") or DH_CF
            if hrp and (hrp.Position - cf.Position).Magnitude > 12 then
                State.Text = "Going to the Dragon Hunter"
                Diag.vulc = "going to the Dragon Hunter (Dojo)"
                flyTo(cf * CFrame.new(0, 4, 4))
                return true
            end
            local q, err = V.checkQuest()
            if q then
                V.cur, V.curAt, V.unk = q, os.clock(), 0
                V.plantsAt, V.plantsDry = 0, false -- missão nova: varre as plantas de novo
                Diag.vulc = "Dragon Hunter task: " .. q.text
            else
                Diag.vulc = "Dragon Hunter gave no task: " .. tostring(err)
                task.wait(2)
            end
            return true
        end
        local q = V.cur
        Diag.vulc = "Blaze Ember " .. invCount("Blaze Ember") .. "/15 | task: " .. q.text
        if q.kind == "kill" then
            if killMob(q.mob, q.mob) then return true end
            State.Text = "Looking for " .. q.mob
            flyTo(CFrame.new(5251.9, 60, 453.6))
            return true
        elseif q.kind == "tree" then
            State.Text = "Breaking trees / plants"
            local tree = nearestPlant(hrp)
            if tree then
                local close = needClose(Config.VulcTreeW)
                local goal = tree.Position + Vector3.new(0, close and 8 or 25, 0)
                if (hrp.Position - goal).Magnitude > 12 then flyTo(CFrame.new(goal)); return true end
                V.plantTry[tree] = (V.plantTry[tree] or 0) + 1
                if V.plantTry[tree] > 6 then V.badPlant[tree] = true end -- não quebrou depois de 6 rodadas: pula para a próxima
                if not V.useSet("VulcTreeW", "VulcTreeK", tree) then
                    Aim.part, Aim.level = tree, false
                    skills()
                end
                return true
            end
            -- sem árvore carregada: patrulha os 4 pontos soltando as skills
            V.pi = ((math.floor(os.clock() / 2)) % #V.treePts) + 1
            local p = V.treePts[V.pi]
            flyTo(CFrame.new(p))
            return true
        end
        V.unk = (V.unk or 0) + 1
        if V.unk > 20 then V.cur = nil end
        return true
    end

    -- Volcanic Magnet: 10 Scrap Metal (kill Jungle Pirates) + 15 Blaze Ember (Dragon Hunter) -> craft with RF/Craft
    function V.hasMagnet()
        for _, c in ipairs({ Player.Backpack, Player.Character }) do
            if c then for _, t in ipairs(c:GetChildren()) do
                if t:IsA("Tool") and string.find(string.lower(t.Name), "volcanic magnet", 1, true) then return true end
            end end
        end
        local ok, has = pcall(function()
            return hasItem("Volcanic Magnet") or invCount("Volcanic Magnet") > 0 or (AFL.Inv and AFL.Inv.count and AFL.Inv.count("Volcanic Magnet") > 0)
        end)
        return ok and has and true or false
    end
    -- crafta um item da ilha pre-historica (RF/Craft "Craft" <nome> 1 {}); devolve (ok, resposta)
    function V.craft(name)
        local ok, r = netCall("RF/Craft", "Craft", name, 1, {})
        if not ok or r == false then                            -- plano B: o remote antigo (CommF_ "CraftItem"), igual ao da aba Shop
            local ok2, r2 = invoke("CraftItem", "Craft", name)
            if ok2 and r2 ~= false then ok, r = ok2, r2 end
        end
        pcall(function() InvCache.at = 0 end)                   -- forca a leitura nova do inventario
        return ok, r
    end
    -- posicao de um NPC (Vector3) para os botoes de atalho; "Dragon Hunter" tem posicao fixa de reserva
    function V.npcPos(name)
        local cf = npcCF(name) or (name == "Dragon Hunter" and DH_CF) or nil
        return cf and cf.Position or nil
    end
    function V.magnetStep()
        if V.hasMagnet() then Diag.vulc = "already has the Volcanic Magnet"; return false end
        local scrap, ember = invCount("Scrap Metal"), invCount("Blaze Ember")
        if scrap >= 10 and ember >= 15 then
            setAct("magnet")
            State.Mode, State.Text = "Auto Volcanic Magnet", "Crafting the Volcanic Magnet"
            if os.clock() - V.last > 5 then
                V.last = os.clock()
                local ok, r = V.craft("Volcanic Magnet")
                Diag.vulc = "craft: " .. tostring(ok) .. " / " .. tostring(r)
                if ok and V.hasMagnet() then V.stats.crafts += 1; vnotify("Volcanic Magnet crafted!", 5) end
            end
            return true
        end
        if scrap < 10 then
            setAct("magnet")
            Diag.vulc = "farming Scrap Metal " .. scrap .. "/10 (Jungle Pirate)"
            State.Text = "Scrap Metal " .. scrap .. "/10"
            if killMob("Jungle Pirate", "Scrap Metal " .. scrap .. "/10") then return true end
            Diag.vulc = "Jungle Pirate spawn not found (Sea 3, Deep Forest / Jungle)"
            return true -- fica no passo do magnet em vez de sair navegando sem o magnet
        end
        return V.emberStep()
    end

    -- ===== ovos e ossos (v24: varios de uma vez, o mais perto primeiro, sem travar num que nao da para pegar) =====
    -- ovos: Core.SpawnedDragonEggs.DragonEgg.Molten (ProximityPrompt) | ossos: workspace.DinoBone
    V.badEgg, V.eggTry, V.eggSeen = setmetatable({}, { __mode = "k" }), setmetatable({}, { __mode = "k" }), setmetatable({}, { __mode = "k" })
    V.badBone, V.boneSeen = setmetatable({}, { __mode = "k" }), setmetatable({}, { __mode = "k" })
    local function posOfAny(o)
        if not o then return nil end
        if o:IsA("BasePart") then return o.Position end
        local ok, p = pcall(function() return o:GetPivot().Position end)
        return ok and p or nil
    end
    local function distP(p)
        local _, hrp = getChar()
        return (hrp and p) and (hrp.Position - p).Magnitude or math.huge
    end
    -- lista de ovos { e, m, pp, pos, d }: os que ja podem ser pegos primeiro, depois o mais perto
    function V.eggs(isl)
        local out = {}
        local core = isl and isl:FindFirstChild("Core")
        local f = core and core:FindFirstChild("SpawnedDragonEggs")
        for _, e in ipairs(f and f:GetChildren() or {}) do
            if e.Name == "DragonEgg" and not V.badEgg[e] then
                local m = e:FindFirstChild("Molten")
                local pp = m and m:FindFirstChildOfClass("ProximityPrompt")
                local p = posOfAny(m)
                if pp and p then out[#out + 1] = { e = e, m = m, pp = pp, pos = p, d = distP(p) } end
            end
        end
        table.sort(out, function(a, b)
            local ea, eb = a.pp.Enabled ~= false, b.pp.Enabled ~= false
            if ea ~= eb then return ea end
            return a.d < b.d
        end)
        return out
    end
    function V.egg(isl)                                       -- (compatibilidade com o v23)
        local t = V.eggs(isl)[1]
        if t then return t.m, t.pp end
    end
    function V.collectEgg(isl)
        local list = V.eggs(isl)
        local t = list[1]
        if not t then return false end
        local now = os.clock()
        V.eggSeen[t.e] = V.eggSeen[t.e] or now
        if now - V.eggSeen[t.e] > 120 then V.badEgg[t.e] = true; return false end     -- 2 min no mesmo ovo: desiste dele
        setAct("egg")
        State.Mode, State.Text = "Auto Collect Egg", "Collecting a Dragon Egg (" .. #list .. " on the island)"
        Diag.vulc = "Dragon Egg: " .. #list .. " on the island"
        local _, hrp = getChar()
        if hrp and (hrp.Position - t.pos).Magnitude > 8 then
            flyTo(t.m:IsA("BasePart") and t.m.CFrame or CFrame.new(t.pos))
        elseif now - (V.eggFireAt or 0) > 0.3 then
            V.eggFireAt, V.eggTarget = now, t.e
            if t.pp.Enabled ~= false then
                V.eggTry[t.e] = (V.eggTry[t.e] or 0) + 1
                if V.eggTry[t.e] > 25 then V.badEgg[t.e] = true end                    -- 25 tentativas sem sumir: pula para o proximo
            end
            pcall(fireproximityprompt, t.pp)
        end
        return true
    end
    function V.bones()
        local out = {}
        for _, c in ipairs(workspace:GetChildren()) do
            if c.Name == "DinoBone" and not V.badBone[c] then
                local p = posOfAny(c)
                if p then out[#out + 1] = { b = c, pos = p, d = distP(p) } end
            end
        end
        table.sort(out, function(a, b) return a.d < b.d end)
        return out
    end
    function V.collectBone()
        local list = V.bones()
        local t = list[1]
        if not t then return false end
        local now = os.clock()
        V.boneSeen[t.b] = V.boneSeen[t.b] or now
        if now - V.boneSeen[t.b] > 40 then V.badBone[t.b] = true; return false end    -- 40 s atras do mesmo osso: pula
        setAct("bone")
        V.boneTarget = t.b
        State.Mode, State.Text = "Auto Collect Bone", "Collecting a Dino Bone (" .. #list .. " in the world)"
        Diag.vulc = "Dino Bone: " .. #list .. " in the world"
        local part = t.b:IsA("BasePart") and t.b or t.b:FindFirstChildWhichIsA("BasePart", true)
        flyTo(part and part.CFrame or CFrame.new(t.pos))
        if part and t.d < 12 and now - (V.boneTouchAt or 0) > 0.4 then V.boneTouchAt = now; pcall(MV.touch, part) end
        return true
    end
    -- 10 segundos depois da ilha terminar (ou sumir), reseta o personagem para recomeçar o ciclo.
    -- v41: só reseta com o evento DE VERDADE encerrado (V.evtHold = tempo sem nenhum sinal do evento) e no máximo 1x por ilha
    -- (antes resetava em loop enquanto a ilha existia, e resetava no meio do evento quando o timer da HUD não era lido).
    function V.finish(why, force)
        local now = os.clock()
        local hold = force and 0 or ((V.evtHold or 0) - now)
        if hold > 0 then
            V.doneAt = nil
            Diag.vulc = why .. " | making sure the event ended (" .. math.ceil(hold) .. "s)"
            State.Mode, State.Text = Config.VulcFull and "Auto Fully Vulcan" or "Auto Reset Vulcan", "Waiting for the event to end (" .. math.ceil(hold) .. "s)"
            return true
        end
        if V.resetDone then
            Diag.vulc = why .. " | already reset on this island: waiting for it to disappear"
            return false
        end
        V.doneAt = V.doneAt or now
        local left = 10 - (now - V.doneAt)
        Diag.vulc = why .. " | reset in " .. math.max(0, math.ceil(left)) .. "s"
        if left <= 0 then
            V.doneAt, V.seen, V.resetDone = nil, false, true
            V.stats.resets += 1
            local _, _, hum = getChar()
            if hum then pcall(function() hum.Health = 0 end) end
            return false
        end
        State.Mode, State.Text = Config.VulcFull and "Auto Fully Vulcan" or "Auto Reset Vulcan", why .. " (reset in " .. math.max(0, math.ceil(left)) .. "s)"
        return true
    end
    -- true while an island is being worked on: the scheduler puts Vulcan first so nothing else steals the character
    function V.engaged() return os.clock() - (V.activeAt or -1e9) < 3 end
    -- devolve o golem mais perto e quantos existem
    local function golem()
        local _, hrp = getChar()
        local best, bd, n = nil, 1e9, 0
        for _, e in ipairs(enemiesList()) do
            if e.Name == "Lava Golem" then
                local eh, er = aliveParts(e)
                if eh and hrp then
                    local d = (hrp.Position - er.Position).Magnitude
                    V.golemSeen[e] = d                                    -- guarda a ultima distancia (para contar a morte mesmo se o modelo sumir de uma vez)
                    if d <= 1500 then
                        n += 1
                        if d < bd then best, bd = e, d end
                    end
                end
            end
        end
        return best, n
    end
    -- v24: a pedra "acesa" tem VFXLayer.Specs.Enabled (Banana). Se a pedra nao tiver "Specs" (outra versao do jogo), confere
    -- VFXLayer.At0.Glow.Enabled (Quantum). Com "Specs" presente o comportamento e exatamente o do v23.
    local function rockOn(r)
        local ok, on = pcall(function()
            local vfx = r:FindFirstChild("VFXLayer")
            if not vfx then return false end
            local sp = vfx:FindFirstChild("Specs")
            if sp then return sp.Enabled == true end
            local at = vfx:FindFirstChild("At0")
            local gl = at and at:FindFirstChild("Glow")
            return gl ~= nil and gl.Enabled == true
        end)
        return ok and on == true
    end
    V.rocksSeen = setmetatable({}, { __mode = "k" })
    local function activeRock(isl)
        local core = isl and isl:FindFirstChild("Core")
        local f = core and core:FindFirstChild("VolcanoRocks")
        local best, bd, _, hrp = nil, 1e9, getChar()
        for _, r in ipairs(f and f:GetChildren() or {}) do
            if string.find(string.lower(r.Name), "rock", 1, true) then
                local on = rockOn(r)
                if on then V.rocksSeen[r] = true
                elseif V.rocksSeen[r] then V.rocksSeen[r] = nil; V.stats.rocks += 1 end      -- apagou: pedra quebrada
                if on and hrp then
                    local d = (hrp.Position - r:GetPivot().Position).Magnitude
                    if d < bd then best, bd = r, d end
                end
            end
        end
        return best
    end
    -- conta golens mortos (so quando o Humanoid chegou a vida 0); V.golemSeen e alimentado por golem()
    -- (morreu = vida 0, ou o modelo sumiu estando perto de voce; um golem que some LONGE e so o jogo descarregando)
    local function trackGolems()
        for g, lastD in pairs(V.golemSeen) do
            local hm = g.Parent and g:FindFirstChildOfClass("Humanoid")
            if not hm then
                V.golemSeen[g] = nil
                if type(lastD) == "number" and lastD < 400 then V.stats.golems += 1 end
            elseif hm.Health <= 0 then
                V.golemSeen[g] = nil
                V.stats.golems += 1
            end
        end
    end
    -- touching lava hurts: remove the TouchInterest of the island and the interior lava (same as Banana)
    -- v41: a relíquia (caveira) fica de fora: é ela que precisa ser tocada para encerrar o evento
    local function cleanLava(isl)
        if V.cleaned == isl then return end
        V.cleaned = isl
        pcall(function()
            local relic = isl.Core:FindFirstChild("PrehistoricRelic")
            for _, d in ipairs(isl:GetDescendants()) do
                if d.Name == "TouchInterest" and d.Parent and d.Parent.Name ~= "TrialTeleport" and not (relic and d:IsDescendantOf(relic)) then d:Destroy() end
            end
            local il = isl.Core:FindFirstChild("InteriorLava")
            if il then for _, c in ipairs(il:GetChildren()) do c:Destroy() end end
        end)
    end

    -- v41: o evento conta como "rodando" por QUALQUER um destes sinais. Antes dependia só do timer da HUD: se ele não fosse lido
    -- (nome diferente, some entre as fases...), o Fully achava que a ilha já tinha acabado e resetava o personagem no meio do evento.
    local function hudRunning()
        local ok, v = pcall(function()
            local list = Player.PlayerGui.Main.TopHUDList
            local t = list:FindFirstChild("PrehistoricRaidTimer")
            if t and t:IsA("GuiObject") and t.Visible then return true end
            for _, c in ipairs(list:GetChildren()) do
                if c:IsA("GuiObject") and c.Visible and string.find(string.lower(c.Name), "prehistoric", 1, true) then return true end
            end
            return false
        end)
        return ok and v == true
    end
    local function eventSignals(isl)
        local _, n = golem()
        local s = { timer = hudRunning(), golems = n, rock = activeRock(isl) ~= nil }
        -- timer da HUD "preso" depois que a caveira foi tocada e não sobrou golem nem pedra: não conta mais
        if s.timer and n == 0 and not s.rock and V.skullDone and os.clock() - (V.skullAt or 0) > 45 then s.timer = false end
        s.any = s.timer or n > 0 or s.rock
        return s
    end

    -- ================================================================ funcoes ligadas (v24) ====
    -- O Fully liga todas. Cada uma funciona SOZINHA:
    --   magnet = Scrap Metal + Blaze Ember + craft | ember = so as missoes do Dragon Hunter (Blaze Ember) | find = navegar ate achar a ilha
    --   start = ativar, golens, pedras, caveira   | egg / bone = coletar                    | reset = reseta 10 s depois do evento
    function V.want()
        local full = Config.VulcFull and true or false
        local function f(k) return (full or Config[k]) and true or false end
        local w = { full = full, magnet = f("VulcMagnet"), find = f("VulcFind"), start = f("VulcStart"), egg = f("VulcEgg"), bone = f("VulcBone"), reset = f("VulcReset"),
            ember = (not full) and Config.VulcEmber and true or false }
        w.act = w.start or w.egg or w.bone
        w.any = w.magnet or w.ember or w.find or w.act
        return w
    end
    local function unseat(hum, now)
        if hum and hum.SeatPart and now - (V.unseatAt or 0) > 1 then V.unseatAt = now; pcall(function() hum.Sit = false end) end
    end
    -- a ilha existe no servidor mas o modelo ainda nao carregou (longe): voa ate o marcador para ele carregar
    local function approachMarker(mpos, hrp, hum, now)
        local d = (hrp.Position - mpos).Magnitude
        if d < 450 then
            V.mkNear = V.mkNear or now
            if now - V.mkNear > 25 then
                Diag.vulc = "island marker reached, but the island model did not load (waiting)"
                return false
            end
        else
            V.mkNear = nil
        end
        V.activeAt = now
        MV.hold()
        unseat(hum, now)
        setAct("go")
        State.Mode, State.Text = "Auto Vulcan", "Flying to the Prehistoric Island (" .. math.floor(d) .. " studs)"
        Diag.vulc = "island marker found " .. math.floor(d) .. " studs away: flying closer so it loads"
        flyTo(CFrame.new(mpos + Vector3.new(0, 150, 0)))
        return true
    end
    -- Auto Find sozinho: achou a ilha -> para o barco e (opcional) voa ate ela UMA vez; depois solta o personagem
    local function goFind(hrp, hum, now)
        local p = V.islandPos()
        local d = p and (hrp.Position - p).Magnitude or 0
        MV.hold()
        setAct("find")
        if Config.VulcGo ~= false and p and not V.goArrived then
            if d > 350 then
                V.activeAt = now
                unseat(hum, now)
                State.Mode, State.Text = "Auto Find Vulcan", "Island found: flying to it (" .. math.floor(d) .. " studs)"
                Diag.vulc = "Prehistoric Island found " .. math.floor(d) .. " studs away: flying to it"
                flyTo(CFrame.new(p + Vector3.new(0, 200, 0)))
                return true
            end
            V.goArrived = true
        end
        Diag.vulc = "Prehistoric Island found" .. (p and (" (" .. math.floor(d) .. " studs away)") or "")
        return false
    end

    -- ======================================================================== a ilha ====
    -- (mesma logica do v23, com as funcoes lidas de w.*). true = esta usando o personagem | false = nada a fazer agora
    local function islandFlow(isl, w, hrp, hum, now)
        V.seen = true
        if V.islObj ~= isl then -- ilha nova (modelo diferente do ultimo visto): comeca uma "visita" nova, sem sobras da ilha anterior
            V.islAt, V.sigAt, V.actAt, V.resetDone, V.doneAt, V.skullDone, V.skullAt = now, now, nil, false, nil, false, nil
            V.started, V.cleaned, V.entered, V.skullGo, V.noRockAt, V.evtHold = nil, nil, nil, nil, nil, nil
            V.ran, V.waitSince = nil, nil
        end
        V.islObj = isl
        MV.hold()
        local core = isl:FindFirstChild("Core")
        unseat(hum, now) -- v41: na ilha o personagem nao pode continuar sentado no barco (voava arrastando o barco)
        -- 1) ainda nao esta dentro da ilha: o Fossil Expert fica na entrada
        V.activeAt = now
        if Player:GetAttribute("CurrentLocation") == "Prehistoric Island" then V.entered = true end
        if not V.entered then
            local cf = npcCF("Fossil Expert") or (core and core:GetPivot())
            if cf and (hrp.Position - cf.Position).Magnitude > 12 then
                setAct("enter")
                State.Mode, State.Text = "Auto Vulcan", "Going to the Fossil Expert"
                Diag.vulc = "phase: entering the island"
                flyTo(cf * CFrame.new(0, 4, 4))
                return true
            end
            V.entered = true -- chegou na entrada: nunca mais volta para ela durante esta visita (evitava vai-e-vem)
        end
        cleanLava(isl)
        -- v41: varios sinais (timer, golens, pedras) + a ativacao recente; "V.evtHold" = ate quando ainda NAO se pode dar a ilha por terminada
        local sig = eventSignals(isl)
        -- v53: V.ran = o evento RODOU de verdade nesta visita (golem / pedra / timer). So depois disso o reset pode acontecer.
        -- v74 fix: "V.actAt" (ativou o evento) so era marcado quando o PROPRIO script apertava o ActivationPrompt - se o
        -- jogador chegasse numa ilha onde o evento JA estava rodando (outro jogador ativou antes, ou o script detectou
        -- o evento por um sinal qualquer sem nunca ter apertado o prompt), V.actAt ficava nil pra sempre nessa visita,
        -- e so a folga curta (45s desde o ultimo sinal) valia - entao uma pausa normal entre fases (golens acabaram,
        -- ainda sem pedra, timer da HUD "preso" um instante) conseguia ULTRAPASSAR esses 45s e resetar o personagem
        -- NO MEIO do evento, sem ele ter de fato terminado ("reset do nada"). Agora qualquer sinal confirmado de
        -- evento rodando tambem conta como "ativado" pra folga de 120s valer, tenha sido o script quem ativou ou nao.
        if sig.any then
            V.sigAt, V.resetDone, V.ran = now, false, true
            V.actAt = V.actAt or now
        end
        if V.skullDone then V.ran = true end
        -- v53: mais folga entre as fases (golens -> pedras -> caveira -> ovos) antes de dar o evento por terminado
        local hold = V.sigAt + (V.skullDone and 20 or 45)
        if V.actAt and not V.skullDone then hold = math.max(hold, V.actAt + 120) end
        if V.skullAt then hold = math.max(hold, V.skullAt + 25) end
        V.evtHold = math.max(hold, V.islAt + 45)
        local running = sig.any or (V.actAt ~= nil and now - V.actAt < 45)
        local why = "timer " .. (sig.timer and "yes" or "no") .. ", golems " .. sig.golems .. ", rock " .. (sig.rock and "yes" or "no")
        -- 2) evento rodando: golens -> pedras -> caveira
        if running and w.start then
            V.doneAt = nil
            State.bossAt = os.clock() -- evento rodando: coleta de fruta, dungeon, gacha e raid esperam
            local g, gn = golem()
            if g then
                -- 2 ou mais golens: puxa todos para o mesmo ponto e bate neles juntos (ate o limite escolhido)
                if Config.VulcPull ~= false and gn > 1 then
                    Fight.bringMax = math.clamp(math.min(gn, tonumber(Config.VulcPullMax) or 6), 2, 10)
                    Fight.bringRange, Fight.bringUntil = 1100, os.clock() + 1.5
                end
                V.noRockAt = nil
                setAct("golem")
                State.Mode, State.Text = "Auto Start Vulcan", "Killing " .. gn .. " Lava Golem" .. (gn > 1 and "s" or "")
                Diag.vulc = "Lava Golems alive: " .. gn .. (Fight.bringMax and (" | pulling up to " .. Fight.bringMax) or "")
                fightEnemy(g, { "Lava Golem" }, true)
                return true
            end
            local rock = activeRock(isl)
            if rock then
                setAct("rock")
                State.Mode, State.Text = "Auto Start Vulcan", "Breaking the volcano rock"
                local pv = rock:GetPivot()
                local up = needClose(Config.VulcRockW) and 10 or 45
                -- v139: relato de comprador - "morre atoa porque entra dentro do vulcao" e "erra os ataques nas pedras".
                -- (1) a altura era pv * CFrame.new(0, up, 0): o "pra cima" LOCAL da pedra - pedra inclinada/de lado jogava o
                --     personagem pra dentro do vulcao/lava. Agora e o "pra cima" do MUNDO.
                -- (2) o voo ia em linha reta ate la, atravessando o corpo do vulcao: agora sobe primeiro e so depois vai ate a pedra.
                -- (3) a mira ia na primeira parte qualquer achada dentro da pedra (podia ser um detalhe pequeno fora do centro):
                --     agora mira na MAIOR parte dela.
                local gpos = pv.Position + Vector3.new(0, up, 0)
                local hp0 = hrp.Position
                if (hp0 - gpos).Magnitude > 14 then
                    local hd0 = Vector3.new(gpos.X - hp0.X, 0, gpos.Z - hp0.Z).Magnitude
                    local safeY = gpos.Y + 30
                    if hd0 > 14 and hp0.Y < safeY - 8 then
                        flyTo(CFrame.new(hp0.X, safeY, hp0.Z))
                    else
                        flyTo(CFrame.new(gpos))
                    end
                    return true
                end
                V.rockAim = V.rockAim or setmetatable({}, { __mode = "k" })
                local part = V.rockAim[rock]
                if not (part and part.Parent) then
                    part = rock:IsA("BasePart") and rock or nil
                    local bv = part and (part.Size.X * part.Size.Y * part.Size.Z) or -1
                    for _, d in ipairs(rock:GetDescendants()) do
                        if d:IsA("BasePart") then
                            local vv = d.Size.X * d.Size.Y * d.Size.Z
                            if vv > bv then part, bv = d, vv end
                        end
                    end
                    V.rockAim[rock] = part
                end
                if part then
                    Aim.part, Aim.level = part, false
                    if not V.useSet("VulcRockW", "VulcRockK", part) then skills() end
                end
                V.skullGo, V.noRockAt = true, nil
                return true
            end
            V.noRockAt = V.noRockAt or os.clock()
            local skull
            pcall(function() skull = core.PrehistoricRelic.Skull end)
            if V.skullGo and skull and os.clock() - V.noRockAt > 2 then
                setAct("skull")
                State.Mode, State.Text = "Auto Start Vulcan", "Going to the Relic Skull"
                if touchSkull(skull, hrp) then
                    V.skullGo, V.skullDone, V.skullAt = false, true, os.clock()
                    Diag.vulc = "Relic Skull touched"
                end
                return true
            end
            -- sem golem, pedra nem caveira pendente: os ovos que ja apareceram sao coletados mesmo com o timer ainda na tela
            if w.egg and V.collectEgg(isl) then return true end
            -- longe da ilha (ex.: morreu e renasceu longe): volta para ela em vez de ficar parado esperando
            local apF = core and core:FindFirstChild("ActivationPrompt")
            if apF and (hrp.Position - apF.Position).Magnitude > 1000 then
                setAct("go")
                State.Mode, State.Text = "Auto Start Vulcan", "Returning to the island"
                Diag.vulc = "far from the island: flying back (" .. why .. ")"
                flyTo(apF.CFrame * CFrame.new(0, 40, 0))
                return true
            end
            setAct("wait")
            Diag.vulc = "event running (" .. why .. ")"
            return true
        end
        -- 3) nao comecou: ActivationPrompt
        if not running and not hud("RaidTimer") and w.start then
            local ap = core and core:FindFirstChild("ActivationPrompt")
            local pp = ap and ap:FindFirstChildOfClass("ProximityPrompt")
            if pp and pp.Enabled then
                setAct("activate")
                State.Mode, State.Text = "Auto Start Vulcan", "Activating the event"
                if (hrp.Position - ap.Position).Magnitude > 8 then flyTo(ap.CFrame) else pcall(fireproximityprompt, pp, 1); V.actAt = os.clock(); task.wait(3) end
                return true
            end
        end
        -- 4) coleta (ossos so enquanto nenhum timer esta rodando)
        if w.egg and V.collectEgg(isl) then V.doneAt = nil; return true end
        if w.bone and not running and not hud("RaidTimer") and V.collectBone() then V.doneAt = nil; return true end
        if w.reset and V.ran then return V.finish("island finished (" .. why .. ")") end
        -- v53: a ilha apareceu mas o evento ainda NAO rodou nesta visita: nao reseta. Antes o Fully achava a ilha e resetava
        -- uns 45 s depois, antes de terminar (ou sem nem comecar). Agora espera perto do ActivationPrompt (ate 5 min).
        V.doneAt = nil
        if w.start and not V.ran then
            V.waitSince = V.waitSince or now
            local apW = core and core:FindFirstChild("ActivationPrompt")
            if apW and now - V.waitSince < 300 then
                setAct("wait")
                State.Mode = w.full and "Auto Fully Vulcan" or "Auto Start Vulcan"
                State.Text = "Waiting for the event to be ready (" .. math.floor(now - V.waitSince) .. "s)"
                Diag.vulc = "island found, event not started yet - waiting at the activation point (no reset)"
                if (hrp.Position - apW.Position).Magnitude > 30 then flyTo(apW.CFrame * CFrame.new(0, 15, 0)) end
                return true
            end
        end
        Diag.vulc = "Prehistoric Island found" .. (V.ran and "" or " (event did not run here: no reset)")
        return false
    end

    function V.step()
        local w = V.want()
        if not w.any then return false end
        if getSea() ~= 3 then Diag.vulc = "Vulcan only works in Sea 3"; return false end
        Fight.bringMax, Fight.bringRange = nil, nil -- so vale durante a luta contra os golens
        local char, hrp, hum = getChar()
        if not char then return false end
        local now = os.clock()
        -- contadores da sessao (o alvo sumiu = coletado)
        if V.eggTarget and not V.eggTarget.Parent then V.stats.eggs += 1; V.eggTarget = nil end
        if V.boneTarget and not V.boneTarget.Parent then V.stats.bones += 1; V.boneTarget = nil end
        local isl = V.island()
        local mobj, mpos = V.marker()
        if isl then trackGolems() end
        if isl or mpos then
            V.nilAt = nil
            local key = mobj or isl                  -- o marcador global dura o evento inteiro (o modelo pode carregar/descarregar)
            if V.knownKey ~= key then -- ilha nova neste servidor
                V.knownKey, V.known, V.foundNote, V.goArrived = key, now, false, false
                V.stats.islands += 1
            end
            if not V.foundNote and (w.find or w.act) then
                V.foundNote = true
                local p = V.islandPos()
                vnotify("Prehistoric Island found" .. (p and (" - " .. math.floor((hrp.Position - p).Magnitude) .. " studs away") or ""))
            end
            if isl and w.act then
                if islandFlow(isl, w, hrp, hum, now) then return true end
            elseif mpos and w.act then
                if approachMarker(mpos, hrp, hum, now) then return true end
            elseif w.find and not w.act then
                if goFind(hrp, hum, now) then return true end
            end
        else
            -- sem ilha. v41: a ilha pode sumir por um instante (streaming / troca de modelo): espera 6s PARADO, sem navegar e sem resetar
            V.known, V.knownKey, V.foundNote, V.goArrived, V.mkNear = nil, nil, false, false, nil
            if V.seen and (w.act or w.reset) then
                V.nilAt = V.nilAt or now
                local gone = now - V.nilAt
                if gone < 6 then
                    MV.hold()
                    Diag.vulc = "island not visible for " .. math.floor(gone) .. "s: waiting (no boat, no reset)"
                    State.Mode, State.Text = w.full and "Auto Fully Vulcan" or "Auto Vulcan", "Island not visible: waiting"
                    return true
                end
                V.islObj = nil
                -- v53: so reseta se o evento rodou nesta ilha (antes resetava mesmo sem ter feito nada nela)
                if w.reset and not V.resetDone and V.ran then
                    if V.finish("island gone", true) then return true end
                end
            end
            V.seen, V.nilAt, V.doneAt, V.resetDone = false, nil, nil, false
            V.started, V.cleaned, V.entered, V.skullGo, V.noRockAt, V.islObj, V.skullDone = nil, nil, nil, nil, nil, nil, nil
            V.ran, V.waitSince = nil, nil
        end
        -- materiais do Imã e missoes do Dragon Hunter funcionam com ou sem ilha no servidor
        if w.magnet and V.magnetStep() then return true end
        if w.ember and V.emberStep() then return true end
        if w.find and not (isl or mpos) then
            setAct("sail")
            State.Mode = "Auto Find Vulcan"
            Diag.vulc = "sailing to Sea Danger Level 6, ignoring sea events"
            MV.equip("volcanic magnet")
            return MV.sail(0) -- sem trava na zona 6
        end
        return false
    end


    -- ================================================================ painel de status ====
    -- Le o mundo (sem mexer em nada) e devolve o que cada funcao esta fazendo. A aba Vulcan chama isto a cada ~1,2 s.
    function V.report()
        local now = os.clock()
        local w = V.want()
        local rep = { w = w, stats = V.stats, fs = {} }
        local sea = getSea()
        local _, hrp = getChar()
        local isl = V.island()
        local _, mpos = V.marker()
        local ipos = V.islandPos()
        rep.sea, rep.isl, rep.mpos = sea, isl, mpos
        rep.found = (isl ~= nil) or (mpos ~= nil)
        rep.dist = (ipos and hrp) and math.floor((hrp.Position - ipos).Magnitude) or nil
        rep.have = V.hasMagnet()
        rep.scrap, rep.ember = invCount("Scrap Metal"), invCount("Blaze Ember")
        local timer, gn, rock, eggs, bones, promptOn = false, 0, false, 0, #V.bones(), false
        if isl then
            timer = hudRunning()
            local _, n = golem()
            gn = n
            rock = activeRock(isl) ~= nil
            eggs = #V.eggs(isl)
            pcall(function()
                local pp = isl.Core.ActivationPrompt:FindFirstChildOfClass("ProximityPrompt")
                promptOn = pp ~= nil and pp.Enabled == true
            end)
        end
        rep.timer, rep.golems, rep.rock, rep.eggs, rep.bones, rep.prompt = timer, gn, rock, eggs, bones, promptOn
        local running = timer or gn > 0 or rock
        rep.running = running
        local function acting(...)
            if now - (V.actT or 0) > 3 then return false end
            for _, k in ipairs({ ... }) do if V.act == k then return true end end
            return false
        end
        local fs = rep.fs
        local function off(k) return not w[k] end
        if sea ~= 3 then
            for _, k in ipairs({ "magnet", "ember", "find", "start", "egg", "bone", "reset" }) do fs[k] = off(k) and "Off" or "Waiting: Vulcan only works in Sea 3" end
            return rep
        end
        -- Volcanic Magnet
        if off("magnet") then fs.magnet = "Off"
        elseif rep.have then fs.magnet = "Done: you have the Volcanic Magnet"
        elseif rep.scrap >= 10 and rep.ember >= 15 then fs.magnet = "Materials ready: crafting" .. (acting("magnet") and " (working)" or "")
        elseif rep.scrap < 10 then fs.magnet = string.format("Scrap Metal %d/10 (Jungle Pirates)%s", rep.scrap, acting("magnet") and " - working" or "")
        else fs.magnet = string.format("Blaze Ember %d/15 (Dragon Hunter)%s", rep.ember, acting("ember") and " - working" or "") end
        -- Blaze Ember sozinho
        if off("ember") then fs.ember = "Off"
        else fs.ember = string.format("Blaze Ember in bag: %d%s", rep.ember, acting("ember") and (V.cur and (" | task: " .. tostring(V.cur.text)) or " - working") or "") end
        -- Find
        if off("find") then fs.find = "Off"
        elseif rep.found then
            fs.find = "Island found" .. (rep.dist and (" - " .. rep.dist .. " studs away") or "") .. (isl and "" or " (not loaded yet)")
        else fs.find = (acting("sail") and "Sailing" or "Searching") .. " for the island" .. (rep.have and "" or " (no Volcanic Magnet yet)") end
        -- Start
        if off("start") then fs.start = "Off"
        elseif not rep.found then fs.start = "Waiting for the island to spawn"
        elseif not isl then fs.start = "Island is far away - flying closer"
        elseif running then
            fs.start = string.format("Event running - %d golem%s, rock %s, timer %s", gn, gn == 1 and "" or "s", rock and "active" or "no", timer and "on" or "off")
        elseif promptOn then fs.start = "Ready: will activate the event"
        elseif V.skullDone then fs.start = "Event finished"
        else fs.start = "Nothing to do on this island right now" end
        -- Egg
        if off("egg") then fs.egg = "Off"
        elseif not isl then fs.egg = rep.found and "Island not loaded yet" or "Waiting for the island"
        elseif eggs > 0 then fs.egg = eggs .. " egg" .. (eggs == 1 and "" or "s") .. " on the island" .. (acting("egg") and " - collecting" or "")
        else fs.egg = "No eggs right now" end
        -- Bone
        if off("bone") then fs.bone = "Off"
        elseif bones > 0 then
            fs.bone = bones .. " bone" .. (bones == 1 and "" or "s") .. " in the world" .. ((timer or hud("RaidTimer")) and " - waiting for the event timer to end" or (acting("bone") and " - collecting" or ""))
        else fs.bone = "No bones right now" end
        -- Reset
        if off("reset") then fs.reset = "Off"
        elseif V.doneAt then fs.reset = "Resetting in " .. math.max(0, math.ceil(10 - (now - V.doneAt))) .. "s"
        elseif V.resetDone then fs.reset = "Already reset on this island"
        else fs.reset = "Resets 10 s after the event ends (only if the event ran on this island)" end
        return rep
    end
end

-- ================================================================ aba Vulcan (v24) ====
-- Cartoes de estado ao vivo (motor + ilha), contadores da sessao, progresso do Volcanic Magnet, cada funcao com o seu proprio interruptor
-- (e uma linha "ao vivo" dizendo o que ela esta fazendo), opcoes, armas para as pedras/arvores e atalhos (voar / craft).
do
    local T = Tabs.Vulcan
    local V = AFL.Vulc
    local TG = {}                                               -- interruptores (para o texto "ao vivo")
    local function note(text, secs)
        pcall(function() Fluent:Notify({ Title = "Vulcan", Content = text, Duration = secs or 4 }) end)
    end
    local function tg(id, title, desc)
        local o = T:AddToggle(id, { Title = title, Description = desc, Default = Config[id] and true or false })
        o:OnChanged(function(v) Config[id] = v; persist() end)
        TG[id] = o
        return o
    end

    -- ------------------------------------------------------------------ estado ao vivo ----
    T:AddSection("Live Status")
    local sEngine = T:AddStatus({ Title = "Vulcan Engine", Content = "Checking..." })
    local sIsland = T:AddStatus({ Title = "Prehistoric Island", Content = "Checking..." })
    local sStats = T:AddStats({ Labels = { "Islands", "Golems", "Rocks", "Eggs", "Bones", "Resets" } })

    -- ----------------------------------------------------------------------- fully ----
    T:AddSection("Auto Fully")
    tg("VulcFull", "Auto Fully Vulcan", "Magnet items > sail > find the island > start it > eggs & bones > repeat")
    -- v54b: o "so quando aparecer" agora vale pra tudo e fica em Farm Settings > Events Only When They Spawn

    -- ------------------------------------------------------------------------ imã ----
    T:AddSection("Volcanic Magnet")
    local sMagnet = T:AddStatus({ Title = "Volcanic Magnet", Content = "Checking...", Height = 58 })
    local pScrap = T:AddProgress({ Title = "Scrap Metal", Description = "Dropped by Jungle Pirates (needs 10)" })
    local pEmber = T:AddProgress({ Title = "Blaze Ember", Description = "Dragon Hunter tasks (needs 15)" })
    tg("VulcMagnet", "Auto Volcanic Magnet", "Farms 10 Scrap Metal + 15 Blaze Ember and crafts the Volcanic Magnet")
    tg("VulcEmber", "Auto Blaze Ember", "Only the Dragon Hunter tasks (Blaze Ember), without crafting the magnet")
    T:AddSlider("VulcMobPull", { Title = "Mob Pull", Description = "How many Jungle Pirates / Hydra Enforcers / Assailants are pulled together",
        Min = 1, Max = 10, Default = math.clamp(tonumber(Config.VulcMobPull) or 5, 1, 10), Rounding = 0 })
        :OnChanged(function(v) Config.VulcMobPull = v; persist() end)
    local crafting = false
    local function craft(item, nice)
        if crafting then return end
        crafting = true
        task.spawn(function()
            local ok, r = V.craft(item)
            crafting = false
            if not ok then note(nice .. ": the craft request failed (" .. tostring(r) .. ")", 5)
            elseif r == false then note(nice .. ": the server refused (missing materials?)", 5)
            else note(nice .. ": craft requested", 4) end
        end)
    end
    T:AddButton({ Title = "Craft Volcanic Magnet", Description = "Needs 10 Scrap Metal and 15 Blaze Ember", Label = "Craft", Callback = function() craft("Volcanic Magnet", "Volcanic Magnet") end })

    -- ------------------------------------------------------------------------ ilha ----
    T:AddSection("Prehistoric Island")
    T:AddSubSection("1. Find")
    tg("VulcFind", "Auto Find Vulcan", "Sails to Danger Level 6 with the magnet until the island shows up")
    tg("VulcGo", "Fly To The Island", "After finding it, flies to the island once and lets go of the character")
    T:AddSubSection("2. Event")
    tg("VulcStart", "Auto Start Vulcan", "Activates the event, kills the golems, breaks the rocks, touches the skull")
    T:AddSubSection("3. Loot")
    tg("VulcEgg", "Auto Collect Egg", "Picks up every Dragon Egg on the island, nearest first")
    tg("VulcBone", "Auto Collect Bone", "Picks up the Dino Bones that drop after the event timers end")
    T:AddSubSection("4. After")
    tg("VulcReset", "Auto Reset Vulcan", "Resets your character 10 s after the event ends (use with Start / Egg / Bone)")

    -- ----------------------------------------------------------------------- golens ----
    T:AddSection("Lava Golems")
    T:AddToggle("VulcPull", { Title = "Pull All Golems", Description = "With 2+ Lava Golems alive, pulls them together and hits them all at once", Default = Config.VulcPull ~= false })
        :OnChanged(function(v) Config.VulcPull = v; persist() end)
    T:AddSlider("VulcPullMax", { Title = "Max Golems Pulled", Description = "How many golems are pulled together", Min = 2, Max = 10, Default = math.clamp(tonumber(Config.VulcPullMax) or 6, 2, 10), Rounding = 0 })
        :OnChanged(function(v) Config.VulcPullMax = v; persist() end)

    -- ------------------------------------------- armas para as pedras e as arvores (v30) ----
    local function multi(v)
        local set = {}
        if type(v) == "table" then
            for k, val in pairs(v) do
                if val == true then set[k] = true elseif type(val) == "string" then set[val] = true end
            end
        end
        return set
    end
    local function copySet(t)
        local o = {}
        for k, v in pairs(t or {}) do if v == true then o[k] = true end end
        return o
    end
    local VKEYS = {
        Melee = { "M1", "Z", "X", "C", "V" }, ["Blox Fruit"] = { "M1", "Z", "X", "C", "V", "F" },
        Sword = { "M1", "Z", "X", "V" }, Gun = { "M1", "Z", "X" },
    }
    local function weaponBlock(title, hint, wkey, kkey)
        T:AddSection(title)
        local wd = T:AddDropdown(wkey .. "DD", {
            Title = "Items to use", Description = hint, Values = { "Melee", "Blox Fruit", "Sword", "Gun" }, Multi = true, Default = copySet(Config[wkey]),
        })
        wd:OnChanged(function(v) Config[wkey] = multi(v); persist() end)
        for _, tip in ipairs({ "Melee", "Blox Fruit", "Sword", "Gun" }) do
            Config[kkey] = Config[kkey] or {}
            Config[kkey][tip] = Config[kkey][tip] or {}
            T:AddDropdown(kkey .. string.gsub(tip, " ", ""), {
                Title = "Attacks: " .. tip, Description = "M1 = basic click attack. Used only if " .. tip .. " is selected above",
                Values = VKEYS[tip], Multi = true, Default = copySet(Config[kkey][tip]),
            }):OnChanged(function(v) Config[kkey][tip] = multi(v); persist() end)
        end
    end
    weaponBlock("Volcano Pressure (break the rocks)", "Items used to break the glowing rocks and LOWER THE VOLCANO PRESSURE. Pick one or more; each one uses its own attacks below, one after the other", "VulcRockW", "VulcRockK")
    weaponBlock("Trees & Plants (Dragon Hunter task)", "Items used to destroy the trees and plants of the Blaze Ember task", "VulcTreeW", "VulcTreeK")

    -- --------------------------------------------------------------------- atalhos ----
    T:AddSection("Shortcuts")
    local function fly(name, getPos, radius, up)
        AFL.goDo(name, function()
            local p = getPos()
            return p and (p + Vector3.new(0, up or 0, 0)) or nil
        end, function() task.wait(0.3) end, radius or 12)
    end
    T:AddButton({ Title = "Fly To The Island", Description = "Flies above the Prehistoric Island (it has to exist in this server)", Label = "Go", Callback = function()
        fly("Prehistoric Island", V.islandPos, 40, 90)
    end })
    T:AddButton({ Title = "Go To Fossil Expert", Description = "The NPC at the entrance of the island", Label = "Go", Callback = function()
        fly("Fossil Expert", function() return V.npcPos("Fossil Expert") end, 14, 4)
    end })
    T:AddButton({ Title = "Go To Dragon Hunter", Description = "The Dojo NPC that gives the Blaze Ember tasks", Label = "Go", Callback = function()
        fly("Dragon Hunter", function() return V.npcPos("Dragon Hunter") end, 14, 4)
    end })
    T:AddButton({ Title = "Stop Flying", Description = "Cancels a shortcut that is still flying", Label = "Stop", Callback = function() AFL.goStop() end })
    for _, c in ipairs({ { "Dragonheart", "Dragonheart" }, { "Dragonstorm", "Dragonstorm" }, { "DinoHood", "Dino Hood" }, { "TRexSkull", "T-Rex Skull" } }) do
        T:AddButton({ Title = "Craft " .. c[2], Description = "Crafts the " .. c[2] .. " (needs the materials from the island)", Label = "Craft", Callback = function() craft(c[1], c[2]) end })
    end

    -- ------------------------------------------------------------------- detalhes ----
    T:AddSection("Details")
    local info = T:AddParagraph({ Title = "Detection", Content = "Checking..." })

    -- ------------------------------------------------------------ atualizacao ao vivo ----
    local ACT = {
        magnet = "Farming Scrap Metal / crafting the magnet", ember = "Dragon Hunter task (Blaze Ember)", sail = "Sailing to find the island",
        find = "Heading to the island", go = "Flying to the island", enter = "Going to the Fossil Expert", activate = "Activating the event",
        golem = "Killing Lava Golems", rock = "Breaking the volcano rocks", skull = "Touching the Relic Skull", egg = "Collecting Dragon Eggs",
        bone = "Collecting Dino Bones", wait = "Waiting for the event",
    }
    -- devolve (estado, "o que esta fazendo", "detalhe", selo)
    local function engineOf(rep)
        local w = rep.w
        if not w.any then return "off", "Idle", "Turn on Auto Fully Vulcan or any step below", "IDLE" end
        if rep.sea ~= 3 then return "bad", "Wrong sea", "Vulcan only works in the Third Sea (you are in Sea " .. tostring(rep.sea) .. ")", "SEA " .. tostring(rep.sea) end
        local owner = Core.owner
        local diag = tostring(Diag.vulc or "")
        if owner == "Auto Vulcan" then
            local what = (os.clock() - (V.actT or 0) < 4 and ACT[V.act]) or tostring(State.Text or "Working")
            return "ok", what, diag, w.full and "FULLY" or "WORKING"
        elseif owner then
            return "info", "Standing by", tostring(owner) .. " has the character right now. Vulcan takes over when it has something to do", "STANDBY"
        end
        return "info", "Ready", diag ~= "" and diag or "Waiting for something to do", "READY"
    end
    -- devolve (estado, nil, detalhe, selo)
    local function islandOf(rep)
        if rep.sea ~= 3 then return "off", nil, "It only exists in the Third Sea", "N/A" end
        local d = rep.dist and (rep.dist .. " studs away") or nil
        if rep.isl then
            local state = rep.running and "Event running" or (rep.prompt and "Ready to start" or (V.skullDone and "Event finished" or "Loaded"))
            local sub = string.format("%s%s | Golems %d | Rock %s | Timer %s | Eggs %d | Bones %d", state, d and (" | " .. d) or "", rep.golems, rep.rock and "on" or "off", rep.timer and "on" or "off", rep.eggs, rep.bones)
            return rep.running and "ok" or "info", nil, sub, rep.running and "EVENT" or (rep.prompt and "READY" or "FOUND")
        elseif rep.mpos then
            return "info", nil, "Exists in this server" .. (d and (", " .. d) or "") .. " but is not loaded yet. Fly closer so it loads", "FAR"
        end
        return "off", nil, "Not found. Sail with the Volcanic Magnet (Auto Find Vulcan) or look in another server", "NOT FOUND"
    end
    local LIVE = { VulcMagnet = "magnet", VulcEmber = "ember", VulcFind = "find", VulcStart = "start", VulcEgg = "egg", VulcBone = "bone", VulcReset = "reset" }
    local function refresh()
        local rep = V.report()
        local es, what, diag, ep = engineOf(rep)
        sEngine:Set(es, nil, (diag ~= "" and diag ~= what) and (what .. " | " .. diag) or what, ep)
        sIsland:Set(islandOf(rep))
        local s = rep.stats
        sStats:Set({ s.islands, s.golems, s.rocks, s.eggs, s.bones, s.resets })
        pScrap:Set(math.min(rep.scrap, 10), 10)
        pEmber:Set(math.min(rep.ember, 15), 15)
        if rep.have then sMagnet:Set("ok", nil, "You have it. Auto Find Vulcan uses it to locate the island", "OWNED")
        elseif rep.scrap >= 10 and rep.ember >= 15 then sMagnet:Set("info", nil, "Materials ready. Press Craft below or turn on Auto Volcanic Magnet", "READY")
        else sMagnet:Set("warn", nil, string.format("Missing materials: Scrap Metal %d/10 | Blaze Ember %d/15", math.min(rep.scrap, 10), math.min(rep.ember, 15)), "MISSING") end
        TG.VulcFull:SetLive(Config.VulcFull and (es == "ok" and what or diag) or nil)
        for id, k in pairs(LIVE) do
            local o = TG[id]
            if o then o:SetLive(Config[id] and rep.fs[k] or nil) end
        end
        -- secao "Details" (dobrada por padrao): o mesmo texto de depuracao do Vulcan de antes
        local lines = {}
        lines[#lines + 1] = "Volcanic Magnet: " .. (rep.have and "YES" or "no")
        lines[#lines + 1] = "Scrap Metal: " .. rep.scrap .. "/10 | Blaze Ember: " .. rep.ember .. "/15"
        lines[#lines + 1] = "Prehistoric Island: " .. (rep.isl and "LOADED" or (rep.mpos and "far (marker)" or "not found"))
        lines[#lines + 1] = "Mirage Island: " .. ((AFL.Mirage and AFL.Mirage.island and AFL.Mirage.island()) and "FOUND" or "not found")
        lines[#lines + 1] = "Inventory: " .. tostring(AFL.invDebug and AFL.invDebug() or "?")
        lines[#lines + 1] = "Status: " .. tostring(Diag.vulc or "idle")
        info:SetDesc(table.concat(lines, "\n"))
    end
    local warned = false
    task.spawn(function()
        task.wait(0.5)
        while Alive do
            local vis = T:IsVisible()
            if vis then
                local ok, e = pcall(refresh)
                if not ok and not warned then warned = true; AFL.logErr("vulcan ui", e) end
            end
            task.wait(vis and 1.2 or 0.6)
        end
    end)
end



]===] end
    PC.src["kitlev"] = function() return [===[
local __E = ...
local AFL = __E.AFL
local Aim, Config, Diag, Player, State, Tabs, currentTween = __E.Aim, __E.Config, __E.Diag, __E.Player, __E.State, __E.Tabs, __E.currentTween
local equipWeapon, flyTo, getChar, getPlayerLevel, getSea, invoke, persist = __E.equipWeapon, __E.flyTo, __E.getChar, __E.getPlayerLevel, __E.getSea, __E.invoke, __E.persist
local TweenService = game:GetService("TweenService")
local VirtualInputManager = game:GetService("VirtualInputManager")
local Sea = AFL.Sea
local Alive = true
AFL.onUnload(function() Alive = false end);
do
    local T = Tabs.Sea
    -- sub-titulos pequenos dentro da secao (como no Moon antigo): Farm / Boat / Zones & Events / Weapons & Skills / Options
    local function sub(text) T:AddSubSection(text) end
    local function multiToSet(v)
        local set = {}
        if type(v) == "table" then
            for k, val in pairs(v) do
                if val == true then set[k] = true elseif type(val) == "string" then set[val] = true end
            end
        end
        return set
    end
    local function sync(dd, set)
        pcall(function()
            local m = {}
            for k, val in pairs(set) do if val == true then m[k] = true end end
            dd:SetValue(m)
        end)
    end
    local function indexOf(list, value, fallback)
        for k, n in ipairs(list) do if n == value then return k end end
        return fallback
    end

    T:AddSection("Sea Events")

    -- ===== Estado ao vivo =====
    sub("Live Status")
    local sSea = T:AddStatus({ Title = "Sea Events Engine", Content = "Checking..." })
    local sKills = T:AddStats({ Labels = { "Kills", "Sea Beast", "Terrorshark", "Ships", "Sharks", "Skipped" } })
    task.spawn(function()
        while Alive do
            pcall(function()
                local r = Sea.report()
                local state, sub2, pill = "info", tostring(r.diag or "Working"), "BUSY"
                if not r.on then state, sub2, pill = "off", "Turn on Auto Sea Events to start", "OFF"
                elseif r.sea < 2 then state, sub2, pill = "warn", "Sea 1 has no sea events. Use Sea 2 or 3", "SEA 1"
                elseif r.target then state, sub2, pill = "ok", string.format("Killing %s (%d studs) | %s", r.target, math.floor(r.dist or 0), tostring(r.diag or "")), "FIGHTING"
                elseif r.sailing then pill = "SAILING" end
                sSea:Set(state, nil, sub2, pill)
                local k = r.kills
                sKills:Set({ k.total or 0, k["Sea Beast"] or 0, k["Terrorshark"] or 0, k["Ship"] or 0, (k["Shark"] or 0) + (k["Piranha"] or 0), r.skipped or 0 })
            end)
            task.wait(1)
        end
    end)

    -- ===== Farm =====
    sub("Farm")
    T:AddToggle("SeaOn", { Title = "Auto Sea Events", Default = Config.SeaOn and true or false,
        Description = "Drives the boat, leaves it when a selected event appears, kills it and goes back to the boat" })
        :OnChanged(function(v) Config.SeaOn = v; if not v then Config.SeaUntil = 0 end; persist() end)

    -- ===== Barco =====
    sub("Boat")
    local boatNames = { "Beast Hunter", "Guardian", "Lantern", "Sleigh", "Brigade", "Grand Brigade" }
    local boatValues = { "Beast Hunter (5,000)", "Guardian (5,000)", "Lantern (5,000)", "Sleigh (5,000)", "Brigade (1,000)", "Grand Brigade (4,000)" }
    T:AddDropdown("SeaBoat", {
        Title = "Select Boat", Values = boatValues, Default = indexOf(boatNames, Config.SeaBoat, 1),
        Description = "Prices from the Blox Fruits wiki (Beli). Sea 3 buys at the Tiki Outpost, Sea 2 at the Docks.",
    }):OnChanged(function(v) Config.SeaBoat = string.gsub(v, " %(.*", ""); persist() end)
    T:AddToggle("SeaFly", { Title = "Fly Boat", Description = "The boat flies away", Default = Config.SeaFly and true or false })
        :OnChanged(function(v) Config.SeaFly = v; persist() end)
    T:AddSlider("SeaFlySpeed", { Title = "Speed Fly Boat", Min = 100, Max = 450, Default = math.clamp(Config.SeaFlySpeed or 200, 100, 450), Rounding = 0,
        Callback = function(v) Config.SeaFlySpeed = v; persist() end })
    T:AddSlider("SeaSpeed", { Title = "Speed Boat", Description = "Boat sails on the sea (no flying)", Min = 50, Max = 300,
        Default = math.clamp(Config.SeaSpeed or 200, 50, 300), Rounding = 0,
        Callback = function(v) Config.SeaSpeed = v; persist() end })

    -- ===== Zonas e eventos =====
    sub("Zones & Events")
    local zoneValues = { "1", "2", "3", "4", "5", "6", "No Zones" }
    T:AddDropdown("SeaZone", {
        Title = "Select Zones", Values = zoneValues, Default = ((Config.SeaZone or 0) >= 1 and (Config.SeaZone or 0) <= 6) and Config.SeaZone or 7,
        Description = "No Zones keeps going without stopping, past zone 6.",
    }):OnChanged(function(v) Config.SeaZone = tonumber(v) or 0; persist() end)
    local evNames = { "Sea Beast", "Terrorshark", "Ship", "Shark", "Piranha" }
    local ev = T:AddDropdown("SeaEvents", {
        Title = "Select Sea Events", Values = evNames, Multi = true, Default = {},
        Description = "Which events the script hunts",
    })
    ev:OnChanged(function(v) Config.SeaEvents = multiToSet(v); persist() end)
    sync(ev, Config.SeaEvents)
    local prioValues = { "None", "Terrorshark", "Sea Beast", "Ship", "Shark", "Piranha" }
    for i = 1, 5 do
        T:AddDropdown("SeaPrio" .. i, {
            Title = "Priority " .. i, Values = prioValues, Default = indexOf(prioValues, Config.SeaPrio[i], 1),
            Description = (i == 1) and "With more than one event at the same time, it kills priority 1 first, then 2, and so on." or nil,
        }):OnChanged(function(v) Config.SeaPrio[i] = v; persist() end)
    end

    -- ===== Armas e skills =====
    sub("Weapons & Skills")
