    end

    -- ===== Opções =====
    sub("Options")
    local function opt(id, title, desc, key, default)
        if Config.SeaOpt[key] == nil and default then Config.SeaOpt[key] = true end
        T:AddToggle("SeaOpt" .. id, { Title = title, Description = desc, Default = Config.SeaOpt[key] and true or false })
            :OnChanged(function(v) Config.SeaOpt[key] = v; persist() end)
