    opt("DodgeShark", "Auto Dodge Skill Terrorshark", "Moves up 200 studs when the Terrorshark charges its attack (ChargeUp)", "DodgeShark", true)
    opt("DodgeBeast", "Auto Dodge Skill Seabeast", "Moves up 200 studs when the Sea Beast starts an attack (animation)", "DodgeBeast", true)
    opt("RoughTp", "Teleport Boat Other CFrame if Rough Sea", "If Rough Sea is detected, teleports the boat to another spot", "RoughTp")
