    opt("Back10k", "Will Back When over 10km", "Goes back to the starting point after 10,000 studs", "Back10k")
    opt("UseDS", "Use Dragonstorm For Sea Event", "Ship, Shark, Piranha and Terrorshark: the Dragonstorm fires by itself, aiming at the target (no screen tap needed), even with Melee selected", "UseDS")
    opt("UseSG", "Use Click M1 Skull Guitar For Sea Event", "Ship and Sea Beast: the Skull Guitar fires by itself at the target, even with Melee selected", "UseSG")
    opt("AutoChangeDS", "Auto Change Dragonstorm With Skull Guitar", "Dragonstorm on boats/fish/Terrorshark and Skull Guitar on the Sea Beast", "AutoChangeDS")
    opt("ChangeDSBoat", "Auto Change Dragonstorm When Kill Boat", "Uses the Dragonstorm only when killing boats (Ship); everything else follows the other options", "ChangeDSBoat")
    opt("UseM1Fruit", "Use Click M1 Fruit For Sea Event", "Attacks with the fruit's M1 aimed at the target, even with Melee selected; ignores the chosen skills", "UseM1Fruit")
    opt("ResetBuy", "Reset Character Buy Boat", "Resets the character when the boat dies (no creature to kill) or the purchase fails", "ResetBuy", true)

    -- ===== Mirage =====
    T:AddSection("Mirage")
    T:AddToggle("MirageOn", { Title = "Auto Mirage",
        Description = "Uses the selected boat and sails ignoring ALL sea events until Mirage Island shows up (Sea 3, night + Mirror Fractal needed for the gear)",
        Default = Config.MirageOn and true or false })
        :OnChanged(function(v) Config.MirageOn = v; persist() end)
    T:AddToggle("PullLever", { Title = "Auto Pull Lever",
        Description = "On Mirage Island: Blue Gear (looks at the moon + race ability), then the lever at the Temple of Time",
        Default = Config.PullLever and true or false })
