-- ---------- Sea Events extras: Kitsune Island + Leviathan (base: Banana Hub) ----------
(function()
    local T = Tabs.Sea
    local SE = {}
    AFL.SeaEv = SE
    local RS = game:GetService("ReplicatedStorage")
    local function d(k, v) if Config[k] == nil then Config[k] = v end end
    d("KitTP", false); d("KitSpawn", false); d("KitDrive", false); d("KitSummon", false); d("KitCollect", false); d("KitTrade", false); d("KitAzure", 10); d("FullKitsune", false); d("KitSpeed", 200); d("KitBoat", "Guardian")
    Config.KitJoinActive = false   -- near-full-moon mode: never joins servers where the full moon is already active (no Min/Max sliders anymore)
    Config.KitSpeed = math.clamp(tonumber(Config.KitSpeed) or 200, 100, 500)
    -- v57: estes 6 viraram internos do Auto Fully Kitsune (sem toggle na UI): zera valores antigos salvos para nao ficarem presos ligados
    Config.KitTP, Config.KitSpawn, Config.KitDrive, Config.KitSummon, Config.KitCollect, Config.KitTrade = false, false, false, false, false, false
    d("LevSpy", false); d("LevFind", false); d("LevSpeed", 200); d("LevBack", true); d("LevStart", false); d("LevTP", false); d("LevBoatTo", false)
    d("LevAttack", false); d("LevFruit", true); d("LevDragon", false); d("LevGuitar", false); d("LevSkills", false); d("LevHeart", false)
    d("LevFast", true); d("LevHold", 0.3); d("LevWeapons", { ["Blox Fruit"] = true })
    d("LevKeys", { Melee = { Z = true, X = true, C = true }, ["Blox Fruit"] = { Z = true, X = true, C = true, V = true, F = true }, Sword = { Z = true, X = true }, Gun = { Z = true, X = true } })
    SE.kit, SE.lev = "idle", "idle"

    -- ===== helpers =====
    local function commF() local r = RS:FindFirstChild("Remotes"); return r and r:FindFirstChild("CommF_") end
    local function net(name)
        local m = RS:FindFirstChild("Modules"); local n = m and m:FindFirstChild("Net")
        return n and n:FindFirstChild(name)
    end
    local function raidTimer()
        local ok, v = pcall(function() return Player.PlayerGui.Main.TopHUDList.RaidTimer.Visible end)
        return ok and v
    end
    local function loc(name)
        local w = workspace:FindFirstChild("_WorldOrigin")
        local l = w and w:FindFirstChild("Locations")
        return l and l:FindFirstChild(name)
    end
    local function busy(text)
        State.Mode, State.Text = "Sea Event", text
    end
    local function near(a, b) return (a - b).Magnitude end
    local function isMine(b)
        local o = b:FindFirstChild("Owner")
        return o and (o.Value == Player or tostring(o.Value) == Player.Name)
    end
    local function myBoat()
        local _, hrp, hum = getChar()
        if not hum then return end
        local sp = hum.SeatPart
        if sp and sp:IsA("VehicleSeat") then
            local b = sp:FindFirstAncestorOfClass("Model")
            if b then return b, sp end
        end
        local f = workspace:FindFirstChild("Boats")
        if f then
            for _, b in ipairs(f:GetChildren()) do
                if b:IsA("Model") and isMine(b) then
                    local seat = b:FindFirstChild("VehicleSeat") or b:FindFirstChildWhichIsA("VehicleSeat", true)
                    if seat then return b, seat end
                end
            end
        end
    end
    local BUY = { ["Beast Hunter"] = "BeastHunter", Guardian = "Guardian", Lantern = "Lantern", Sleigh = "Sleigh", Brigade = "PirateBrigade", ["Grand Brigade"] = "PirateGrandBrigade" }
    local buyAt = 0
    local function buyBoat()
        local _, hrp = getChar()
        if not hrp then return false end
        local dealer = Vector3.new(-13.488, 10.31, 2927.692)
        if near(hrp.Position, dealer) > 8 then flyTo(CFrame.new(dealer)); return true end
        if os.clock() - buyAt > 5 then
            buyAt = os.clock()
            local cf = commF()
            if cf then pcall(function() cf:InvokeServer("BuyBoat", BUY[Config.SeaBoat or "Brigade"] or "PirateBrigade") end) end
        end
        return true
    end
    -- barco: tween do VehicleSeat (como o Banana)
    local btw, btarget
    local function stopBoat() if btw then pcall(function() btw:Cancel() end); btw = nil; btarget = nil end end
    local function boatTo(seat, pos, speed)
        Config.SeaSitUntil = os.clock() + 1.5
        if btw and btarget and near(btarget, pos) < 40 and btw.PlaybackState == Enum.PlaybackState.Playing then return end
        stopBoat()
        local dist = near(seat.Position, pos)
        if dist < 5 then return end
        local look = CFrame.lookAt(seat.Position, Vector3.new(pos.X, seat.Position.Y, pos.Z))
        btarget = pos
        btw = TweenService:Create(seat, TweenInfo.new(dist / math.max(speed, 50), Enum.EasingStyle.Linear), { CFrame = CFrame.new(pos) * (look - look.Position) })
        btw:Play()
    end
    -- senta no barco (vai até o assento)
    local function seatUp(boat, seat)
        local _, hrp, hum = getChar()
        if not hrp then return false end
        if hum.SeatPart == seat then Config.SeaSitUntil = os.clock() + 1.5; return true end
        local dist = near(hrp.Position, seat.Position)
        if dist > 15 then flyTo(seat.CFrame + Vector3.new(0, 3, 0)) else hrp.CFrame = seat.CFrame + Vector3.new(0, 2, 0) end
        return false
    end
    local function stepBoatNoclip(boat)
        pcall(function()
            for _, p in ipairs(boat:GetDescendants()) do if p:IsA("BasePart") and p.CanCollide then p.CanCollide = false end end
        end)
    end

    -- ===================== KITSUNE ISLAND =====================
    local function kitIsland()
        local map = workspace:FindFirstChild("Map")
        local k = map and map:FindFirstChild("KitsuneIsland")
        if not k then return end
        -- v57: modelo sem santuario = ilha ainda nao existe de verdade (antes isso impedia o script de comprar o barco e procurar)
        if not (k:FindFirstChild("ShrineDialogPart") or k:FindFirstChild("ShrineInactive") or k:FindFirstChild("ShrineActive")) then return end
        local ok, en = pcall(function() return k.ShrineDialogPart.ProximityPrompt.Enabled end)
        return k, ok and en
    end
    local function shrinePos(k)
        local s = k:FindFirstChild("ShrineInactive") or k:FindFirstChild("ShrineActive")
        if s then local ok, p = pcall(function() return s:GetPivot().Position end); if ok then return p end end
        local p = k:FindFirstChild("ShrineDialogPart"); return p and p.Position
    end
    local function ember()
        for _, m in ipairs(workspace:GetChildren()) do
            if m.Name == "EmberTemplate" then
                local p = m:FindFirstChild("Part")
                if p then return p end
            end
        end
    end
    local function night() local t = game:GetService("Lighting").ClockTime; return t >= 18 or t < 5.5 end
    -- v29: lua cheia (mesma checagem usada em Status > Sky & Moon e no Auto Soul Guitar: textura da lua / atributo MoonPhase)
    local LightingSvc = game:GetService("Lighting")
    local function moonFull()
        local ok, tex = pcall(function() return LightingSvc.Sky.MoonTextureId end)
        if ok and tex == "http://www.roblox.com/asset/?id=9709149431" then return true end
        local ok2, phase = pcall(function() return LightingSvc:GetAttribute("MoonPhase") end)
        return ok2 and tonumber(phase) == 5
    end
    -- fase vizinha a cheia (5): nao sabemos a duracao exata de cada fase, entao isto e uma aproximacao de "faltando pouco" (nao exatamente 5 min)
    local function moonNear()
        local ok, phase = pcall(function() return LightingSvc:GetAttribute("MoonPhase") end)
        return ok and (tonumber(phase) == 4 or tonumber(phase) == 6)
    end
    local kitAt = 0
    local kitTradeActive = false -- v108: fica "em sequencia de trade" ate acabar o Azure Ember, nao so ate cruzar o limite de novo
    local KITSEACMD = { "TravelMain", "TravelDressrosa", "TravelZou" }
    local kitTravelAt, kitTravelN = 0, 0
    local kitSaved
    -- v55: Auto Fully Kitsune Island com JANELA DE TEMPO. Faz hop ate achar um servidor onde a lua cheia comeca daqui a
    -- KitMinMin..KitMaxMin minutos (ou ja esta ativa, se KitJoinActive). Ai garante o Mar 3, liga Spawn/Summon/Collect/Trade/TP
    -- sozinho e deixa o kitStep fazer o resto. O servidor aceito fica "travado" ate o evento acabar (nao sai quando o relogio
    -- passa de 15 para 5 min). Nada e inventado: sem medida confiavel o tempo fica "unknown" e o servidor e recusado.
    --   Medida: a velocidade real do Lighting.ClockTime (segundos reais por hora do jogo) e medida duas vezes e so e usada
    --   se as duas concordarem. Premissa (confira no jogo): fase 4 (3/4) vira fase 5 (cheia) quando a noite comeca (ClockTime 18).
    local function moonPhase()
        -- v57: textura de lua cheia = lua cheia (e o que o jogador ve); vence um atributo MoonPhase diferente/atrasado
        local okT, texF = pcall(function() return tostring(LightingSvc:FindFirstChildOfClass("Sky").MoonTextureId):find("9709149431", 1, true) ~= nil end)
        if okT and texF then return 5 end
        local ok, ph = pcall(function() return LightingSvc:GetAttribute("MoonPhase") end)
        ph = ok and tonumber(ph) or nil
        if ph then return ph end
        -- v56 fallback: when the attribute is missing only the full-moon texture is known (same id as Status > Sky & Moon)
        local ok2, tex = pcall(function() return LightingSvc:FindFirstChildOfClass("Sky").MoonTextureId end)
        if ok2 and tostring(tex):find("9709149431", 1, true) then return 5 end
        return nil
    end
    local KIT_DUSK = 18
    local KIT_NEAR_MAX = 10   -- "near full moon" = phase before the full moon AND at most this many minutes left (internal, no slider)
    local KIT_Z6 = Vector3.new(-44541.7617, 30, -1244.8584)   -- zone 6 of Sea 3
    local kitJob, kitCommit, kitSince, kitSample, kitRate = nil, false, 0, nil, nil
    local kitMeasJob, kitWP, kitWPAt, kitLeaveAt
    local kitTradeBefore
    local function kitMeasure()
        if kitMeasJob ~= game.JobId then kitMeasJob, kitSample, kitRate = game.JobId, nil, nil end
        local now, c = os.clock(), LightingSvc.ClockTime
        if not kitSample then kitSample = { c = c, t = now }; return end
        local dt = now - kitSample.t
        if dt < 6 then return end
        local dh = (c - kitSample.c) % 24
        if dh > 0.002 and dh < 6 then
            local r = dt / dh
            if kitRate and kitRate.n >= 2 then
                -- v56: once two samples agree the rate is kept (it used to fall back to n=1 and flip the status to "measuring" again)
                if math.abs(r - kitRate.v) / kitRate.v < 0.25 then kitRate = { v = (kitRate.v * 3 + r) / 4, n = kitRate.n + 1 } end
            elseif kitRate and kitRate.n == 1 and math.abs(r - kitRate.v) / kitRate.v < 0.25 then kitRate = { v = (r + kitRate.v) / 2, n = 2 }
            else kitRate = { v = r, n = 1 } end
        end
        kitSample = { c = c, t = now }
    end
    -- true = aceita | false = recusa | nil = ainda medindo
    local function kitServerOk()
        local ph = moonPhase()
        if ph == nil then
            if os.clock() - kitSince < 10 then SE.kitMoon = "waiting for the moon phase..."; return nil, "waiting for the moon phase" end
            SE.kitMoon = "moon phase unknown (Lighting attribute MoonPhase not found)"
            return false, "moon phase unknown"
        end
        if ph == 5 and night() then
            -- full moon already active: can stay (avoids hopping all the time) unless the Kitsune event here already finished
            if SE.kitDone then
                SE.kitMoon = "full moon active but the event here is finished: next server"
                return false, "event finished in this server"
            end
            SE.kitMoon = "full moon active now"
            return true, "full moon already active"
        end
        if not game:IsLoaded() or not LightingSvc:FindFirstChildOfClass("Sky") then kitSince = os.clock() end
        if os.clock() - kitSince < 6 then
            SE.kitMoon = string.format("reading the moon phase... (hop check in %d s)", math.ceil(6 - (os.clock() - kitSince)))
            return nil, "reading the moon phase"
        end
        if ph ~= 4 then
            SE.kitMoon = string.format("moon phase %s, clock %.1f: full moon is not next", tostring(ph or "?"), LightingSvc.ClockTime)
            return false, "full moon is not the next phase"
        end
        kitMeasure()
        if not (kitRate and kitRate.n >= 2) then SE.kitMoon = "measuring the day cycle..."; return nil, "measuring the day cycle" end
        local m = ((KIT_DUSK - LightingSvc.ClockTime) % 24) * kitRate.v / 60
        SE.kitMoon = string.format("near full moon: ~%.1f min left", m)
        if m > KIT_NEAR_MAX then return false, string.format("%.1f min left (> %d, not near)", m, KIT_NEAR_MAX) end
        return true, string.format("near full moon (~%.1f min left)", m)
    end
    -- minutos ate a lua cheia (para o painel Kitsune Status): number | nil, texto
    function SE.moonRemain()
        pcall(kitMeasure)
        local ph = moonPhase()
        if ph == nil then return nil, "reading the moon..." end
        if ph == 5 and night() then return 0, "ACTIVE NOW" end
        if ph ~= 4 then return nil, string.format("not near (moon phase %s)", tostring(ph)) end
        if not (kitRate and kitRate.n >= 2) then return nil, "measuring the day cycle..." end
        local m = ((KIT_DUSK - LightingSvc.ClockTime) % 24) * kitRate.v / 60
        return m, string.format("in %d:%02d", math.floor(m), math.floor((m % 1) * 60))
    end
    local function kitRestore()
        if kitSaved then
            Config.KitSpawn, Config.KitSummon, Config.KitCollect, Config.KitTrade, Config.KitTP, Config.KitDrive = kitSaved[1], kitSaved[2], kitSaved[3], kitSaved[4], kitSaved[5], kitSaved[6]
            kitSaved = nil
        end
    end
    local function kitFlat(a, b) return Vector3.new(a.X - b.X, 0, a.Z - b.Z).Magnitude end
    local function kitSpeed() return math.clamp(tonumber(Config.KitSpeed) or 200, 100, 500) end
    -- Sea Events engine (the tested one): flies to the Tiki Outpost dealer, buys the boat, gets on it and can sail to zone 6
    local function kitSeaStep()
        local prevBoat, prevSpd, prevZone = Config.SeaBoat, Config.SeaSpeed, Sea.zone
        Config.SeaBoat = Config.KitBoat or "Guardian"
        Config.SeaSpeed = kitSpeed()
        Sea.zone = 6
        local okS, sr = pcall(Sea.step, true)
        Config.SeaBoat, Config.SeaSpeed, Sea.zone = prevBoat, prevSpd, prevZone
        return okS and sr
    end
    -- moves the boat with the Sea Events cruise mover (PivotTo every frame at KitSpeed studs/s): the same one that works at Speed Boat
    local function kitCruise(boat, seat, target)
        local st = Sea.st
        if not st then kitSeaStep(); return end
        Sea.forceUntil = os.clock() + 1.5
        Config.SeaSitUntil = os.clock() + 1.5
        st.cruise = { boat = boat, seat = seat, target = target, fly = false, speed = kitSpeed() }
    end
    local function kitStopBoat()
        stopBoat()
        if Sea.st then Sea.st.cruise = nil end
    end
    -- returns boat, seat when we are sitting on OUR boat; otherwise lets the Sea Events engine buy it / get on it and returns nil
    local function kitBoat(hum, label)
        local boat, seat = myBoat()
        if boat and hum.SeatPart == seat then
            if Sea.st then Sea.st.cruise = nil end   -- from here our own tween drives the boat
            stepBoatNoclip(boat)
            return boat, seat
        end
        kitStopBoat()
        busy(label .. ": getting the boat")
        kitSeaStep()
        SE.kit = label .. ": getting the boat (" .. tostring(Config.KitBoat or "Guardian") .. ") | " .. tostring(Diag.sea)
        return nil
    end
    -- near full moon accepted: go to zone 6 by boat and keep sailing in random directions (no hop) until the moon / island shows up
    local function kitWander(hum)
        local boat, seat = kitBoat(hum, "Waiting for the full moon")
        if not boat then return true end
        local spd = kitSpeed()
        local dz = kitFlat(seat.Position, KIT_Z6)
        if dz > 1800 then
            busy("Waiting for the full moon: sailing to zone 6")
            kitSeaStep()
            SE.kit = string.format("waiting for the full moon: sailing to zone 6 (%d studs)", dz)
            return true
        end
        if not kitWP or kitFlat(seat.Position, kitWP) < 80 or os.clock() - (kitWPAt or 0) > 45 then
            local ang, rad = math.random() * math.pi * 2, math.random(300, 1400)
            kitWP = Vector3.new(KIT_Z6.X + math.cos(ang) * rad, seat.Position.Y, KIT_Z6.Z + math.sin(ang) * rad)
            kitWPAt = os.clock()
        end
        busy("Waiting for the full moon: sailing around zone 6")
        SE.kit = "waiting for the full moon: sailing around zone 6 (random heading, no hop)"
        kitCruise(boat, seat, kitWP)
        return true
    end
    function SE.fullKitsuneStep()
        if not Config.FullKitsune then kitRestore(); kitCommit = false; AFL.kitLocked = false; return false end
        if getSea() ~= 3 then
            if getPlayerLevel() < 1500 then busy("Fully Kitsune: needs Sea 3 (level 1500+)"); SE.kit = "needs level 1500 for Sea 3"; return true end
            if not Config.FullTravel then
                busy("Fully Kitsune: go to Sea 3 yourself (Auto Travel is off in Auto Fully)")
                SE.kit = "waiting for you to reach Sea 3"
                return true
            end
            if os.clock() - kitTravelAt > 25 then
                kitTravelAt = os.clock()
                kitTravelN += 1
                if kitTravelN <= 4 then invoke(KITSEACMD[3]) end
            end
            busy("Fully Kitsune: travelling to Sea 3")
            SE.kit = "travelling to Sea 3"
            return true
        end
        if kitJob ~= game.JobId then kitJob, kitCommit, kitSince, kitSample, kitRate = game.JobId, false, os.clock(), nil, nil; SE.kitRejectAt, SE.kitZ6At, SE.kitOverAt = nil, nil, nil; SE.kitIslandSeen, SE.kitTimerSeen, SE.kitEndAt, SE.kitDone = nil, nil, nil, nil; kitWP = nil; AFL.kitLocked = false end
        -- servidor aceito (near full moon): fica ate o EVENTO acabar. Acabou o evento da Kitsune = hop na hora (nao espera a lua cheia terminar)
        if kitCommit then
            local ph = moonPhase()
            local k = kitIsland()
            local timerOn = raidTimer() and true or false
            local emb = ember()
            if k then SE.kitIslandSeen = true end
            if timerOn then SE.kitTimerSeen = true end
            local goalNow = Config.KitTrade and k and AFL.Inv.count("Azure Ember") >= math.max(1, tonumber(Config.KitAzure) or 10)
            -- (a) o evento ja rodou e terminou (timer sumiu e sem ember no chao, ou a ilha sumiu): sai em 4 s (espera so uma troca pendente, ate 2 min)
            local evOver = (SE.kitTimerSeen and not timerOn and not emb) or (SE.kitIslandSeen and not k)
            if evOver then
                SE.kitEndAt = SE.kitEndAt or os.clock()
                local waited = os.clock() - SE.kitEndAt
                if goalNow and waited < 120 then
                    SE.kitMoon = "event over: finishing the trade before leaving"
                elseif waited > 4 then
                    kitCommit = false
                    SE.kitDone = true
                    SE.kitEndAt = nil
                    kitRestore()
                    SE.kitMoon = "event finished: hopping to the next near full moon server"
                else
                    SE.kitMoon = string.format("event over: leaving in %ds", math.ceil(4 - waited))
                end
            else
                SE.kitEndAt = nil
                -- (b) fallback: a lua passou (nem fase 4 nem lua cheia ativa) sem o evento acontecer: sai depois de 20 s seguidos
                local fullNow = (ph == 5) and night()
                local over = ph ~= nil and ph ~= 4 and not fullNow
                if over then SE.kitOverAt = SE.kitOverAt or os.clock() else SE.kitOverAt = nil end
                local waited = SE.kitOverAt and (os.clock() - SE.kitOverAt) or 0
                local holdEvent = (timerOn and emb) and true or false
                local holdTrade = goalNow and waited < 120
                if over and not holdEvent and not holdTrade then
                    if waited > 20 then
                        kitCommit = false
                        SE.kitOverAt = nil
                        kitRestore()
                        SE.kitMoon = "moon ended: looking for the next server"
                    else
                        SE.kitMoon = string.format("moon ended: leaving in %ds", math.ceil(20 - waited))
                    end
                elseif over then
                    SE.kitMoon = "moon ended: finishing the event / trade before leaving"
                end
            end
        end
        -- v57: servidor aceito = TRAVADO. Nenhum hop (de qualquer funcao do hub) enquanto a lua nao acabar
        AFL.kitLocked = kitCommit and true or false
        if not kitCommit then
            local ok, why = kitServerOk()
            if ok == nil and os.clock() - kitSince > 45 then ok, why = false, "time until full moon unknown" end
            if ok == nil then
                busy("Fully Kitsune: measuring the moon timer")
                SE.kit = "measuring the moon timer"
                return true
            end
            if ok then
                kitCommit = true
                SE.kitRejectAt = nil
                SE.kit = "server accepted: " .. tostring(why)
            else
                kitRestore()
                busy("Fully Kitsune: " .. tostring(why) .. " - hopping")
                SE.kit = "rejected: " .. tostring(why) .. " - hopping"
                local mnK, mxK = 0, KIT_NEAR_MAX
                -- v57 watchdog: se 40 s depois de recusar o servidor ainda estamos nele, o hop travou: destrava e tenta de novo
                SE.kitRejectAt = SE.kitRejectAt or os.clock()
                if os.clock() - SE.kitRejectAt > 40 and not (AFL.Hop.running and os.clock() - AFL.Hop.running < 180) then
                    SE.kitRejectAt = os.clock()
                    AFL.Hop.active, AFL.Hop.failAt = false, 0
                    if AFL.QApi then AFL.QApi.joining, AFL.QApi.last = false, 0 end
                    SE.kit = "hop was stuck: trying again"
                end
                local chk = function() return kitServerOk() == true end
                -- v57: primeiro a lista da API (servidores perto da lua cheia); se ela nao servir, cai no hop normal
                if AFL.apiJoinMoon then AFL.apiJoinMoon(mnK, mxK, chk)
                else AFL.hopRequest("Near full moon (0-" .. mxK .. " min)", chk, 1) end
                return true
            end
        end
        if not kitSaved then
            kitSaved = { Config.KitSpawn, Config.KitSummon, Config.KitCollect, Config.KitTrade, Config.KitTP, Config.KitDrive }
            Config.KitSpawn, Config.KitSummon, Config.KitCollect, Config.KitTrade, Config.KitTP, Config.KitDrive = true, true, true, true, true, true
        end
        return SE.kitStep()
    end
    function SE.kitStep()
        if not (Config.KitTP or Config.KitSpawn or Config.KitDrive or Config.KitSummon or Config.KitCollect or Config.KitTrade) then return false end
        if getSea() ~= 3 then
            if getPlayerLevel() < 1500 then SE.kit = "Kitsune needs Sea 3 (level 1500+)"; return false end
            if Config.FullTravel == false then SE.kit = "Kitsune only works in Sea 3 (Auto Travel is off)"; return false end
            if os.clock() - kitTravelAt > 25 then
                kitTravelAt = os.clock()
                kitTravelN += 1
                if kitTravelN <= 4 then invoke(KITSEACMD[3]) end
            end
            busy("Kitsune: travelling to Sea 3")
            SE.kit = "travelling to Sea 3"
            return true
        end
        local char, hrp, hum = getChar()
        if not hrp or hum.Health <= 0 then return false end
        local timer = raidTimer()
        local k, active = kitIsland()
        local L = loc("Kitsune Island")
        -- 0) lua azul / ilha ja spawnada: compra o barco e VAI DE BARCO ate la (a ilha fica grudada no chao do mar e, sem Shark V2, a agua da dano:
        -- nunca voa/teleporta por cima da agua ate a ilha)
        local isl = (k and shrinePos(k)) or (L and L.Position) or nil
        if Config.FullKitsune and isl and kitFlat(hrp.Position, isl) > 650 then
            local boat, seat = kitBoat(hum, "Kitsune Island")
            if not boat then return true end
            busy("Sailing to Kitsune Island")
            SE.kit = string.format("sailing to Kitsune Island (%d studs)", kitFlat(seat.Position, isl))
            kitCruise(boat, seat, Vector3.new(isl.X, seat.Position.Y, isl.Z))
            return true
        elseif Config.FullKitsune and isl then
            kitStopBoat()
            -- chegou: SAI DO BARCO (sentado o personagem fica preso no assento e nao consegue ativar o santuario)
            if hum.SeatPart then
                Config.SeaSitUntil = 0
                busy("Kitsune Island: leaving the boat")
                SE.kit = "leaving the boat"
                pcall(function() hum.Sit = false; hum:ChangeState(Enum.HumanoidStateType.Jumping) end)
                if kitLeaveAt == nil or os.clock() - kitLeaveAt > 1.5 then
                    kitLeaveAt = os.clock()
                    flyTo(CFrame.new(hrp.Position + Vector3.new(0, 25, 0)))
                end
                return true
            end
        end
        -- 0b) servidor near full moon aceito, ainda sem ilha e sem lua cheia: vai ao mar 6 e anda em rumo aleatorio (sem hop)
        if Config.FullKitsune and kitCommit and not k and not L and not timer and not (moonPhase() == 5 and night()) then
            return kitWander(hum)
        end
        -- 1) coletar Soul Ember durante o evento
        -- v108: antes o goalMet exigia bater o limite (ex: 10) EM TODO frame - o Pray costuma gastar o Azure Ember
        -- todo de uma vez, entao no frame seguinte a contagem cai pra 0/poucos, fica abaixo do limite e o trade
        -- para depois de 1 unico invoke, mesmo com o evento ainda rolando ("so da 1 click e para"). Agora, uma vez
        -- que a sequencia de trade comeca (bateu o limite 1 vez), ela continua enquanto houver PELO MENOS 1 Azure
        -- Ember - so volta a exigir o limite cheio depois que esvaziar e precisar juntar de novo.
        local haveAzure = AFL.Inv.count("Azure Ember")
        local azureGoal = math.max(1, tonumber(Config.KitAzure) or 10)
        if Config.KitTrade and k and timer then
            if not kitTradeActive and haveAzure >= azureGoal then kitTradeActive = true
            elseif kitTradeActive and haveAzure < 1 then kitTradeActive = false end
        else
            kitTradeActive = false
        end
        local goalMet = Config.KitTrade and k and timer and kitTradeActive
        local emb = Config.KitCollect and not goalMet and ember() or nil
        if Config.KitCollect and not goalMet and ((timer and (emb or L)) or emb) then
            local e = emb
            busy("Collecting Soul Ember")
            if e then
                SE.kit = "collecting an ember"
                if near(hrp.Position, e.Position) > 100 then flyTo(e.CFrame) else hrp.CFrame = e.CFrame end
            elseif L then
                SE.kit = "no ember visible: going to the island"
                flyTo(L.CFrame + Vector3.new(0, 30, 0))
            end
            return true
        end
        -- 2) trocar Azure Ember
        if kitTradeBefore and os.clock() - kitAt > 2.5 then
            local nowN = AFL.Inv.count("Azure Ember")
            if nowN < kitTradeBefore then
                SE.kitTraded = (SE.kitTraded or 0) + (kitTradeBefore - nowN)
                SE.kitLastTrade = "traded " .. (kitTradeBefore - nowN) .. " Azure Ember (confirmed)"
            else
                SE.kitLastTrade = "trade not confirmed (count did not drop)"
            end
            kitTradeBefore = nil
        end
        if goalMet then
            local sp = shrinePos(k)
            if sp then
                busy("Trading Azure Ember")
                if near(hrp.Position, sp) > 12 then flyTo(CFrame.new(sp + Vector3.new(0, 3, 0))); SE.kit = "going to the shrine to trade" return true end
                if os.clock() - kitAt > 5 then
                    kitAt = os.clock()
                    kitTradeBefore = AFL.Inv.count("Azure Ember")
                    local r = net("RF/KitsuneStatuePray")
                    if r then pcall(function() r:InvokeServer() end) end
                end
                SE.kit = "trading Azure Ember"
                return true
            end
        end
        -- 3) acender o santuário (Summon Soul Ember)
        if Config.KitSummon and k and active and not timer and not SE.kitDone then
            local sp = shrinePos(k)
            if sp then
                busy("Summoning Soul Ember")
                if near(hrp.Position, sp) >= 10 then flyTo(CFrame.new(sp + Vector3.new(0, 3, 0))); SE.kit = "going to the shrine" return true end
                if os.clock() - kitAt > 5 then
                    kitAt = os.clock()
                    local r = net("RE/TouchKitsuneStatue")
                    if r then pcall(function() r:FireServer() end) end
                end
                SE.kit = "touching the statue"
                return true
            end
        end
        -- 4) teleportar até a ilha
        if Config.KitTP and L and kitFlat(hrp.Position, L.Position) <= 700 then
            busy("Going to Kitsune Island")
            SE.kit = "teleporting to the island"
            if near(hrp.Position, L.Position) > 60 then flyTo(L.CFrame + Vector3.new(0, 30, 0)) end
            return true
        end
        -- 5) criar a ilha: mesma lógica do Auto Sea Events (Select Zones): navega até a zona e espera lá
        if Config.KitSpawn and not k and not (L and kitFlat(hrp.Position, L.Position) <= 650) then
            busy("Looking for Kitsune Island")
            SE.kit = "Tiki Outpost > buy boat > sail to the island | " .. tostring(Diag.sea)
            Sea.zone = 6 -- Kitsune: única que trava na zona 6
            local prevBoat, prevSpd = Config.SeaBoat, Config.SeaSpeed
            Config.SeaBoat = Config.KitBoat or "Guardian"       -- v57: barco escolhido para a Kitsune (padrao Guardian)
            Config.SeaSpeed = kitSpeed()                         -- Kitsune: Tween Speed (Boat)
            local okS, sr = pcall(Sea.step, not Config.SeaOn)
            Config.SeaBoat, Config.SeaSpeed = prevBoat, prevSpd
            Sea.zone = nil
            if not okS then error(sr, 0) end
            if sr then return true end
        end
        if not k and (Config.KitSummon or Config.KitCollect or Config.KitTrade or Config.KitTP) and not Config.KitSpawn then
            SE.kit = "no island yet: turn on Auto Spawn Island to buy a boat and sail to it"
        else
            SE.kit = "idle"
        end
        return false
    end

    -- ===================== LEVIATHAN =====================
    local START = Vector3.new(-32975.99, 160, 25963.71)
    local HEADING = (Vector3.new(-118834.5, 160, 1e8) - START).Unit
    local backing = false
    local levAt, spyAt = 0, 0
    local function levTarget()
        local f = workspace:FindFirstChild("SeaBeasts")
        if not f then return end
        local function hp(m) local h = m:FindFirstChild("Health"); return h and tonumber(h.Value) or 0 end
        for _, m in ipairs(f:GetChildren()) do
            if m.Name == "Leviathan Tail" and m:GetAttribute("HealthEnabled") and hp(m) > 0 then return m end
        end
        for _, m in ipairs(f:GetChildren()) do
            if m.Name == "Leviathan" and not m:GetAttribute("Armored") and hp(m) > 0 then return m end
        end
        for _, m in ipairs(f:GetChildren()) do
            if m.Name == "Leviathan Segment" and hp(m) > 0 then return m end
        end
    end
    local function watcher()
        for _, root in ipairs({ workspace:FindFirstChild("NPCs"), RS:FindFirstChild("NPCs") }) do
            local n = root and root:FindFirstChild("Frozen Watcher")
            if n and n:FindFirstChild("HumanoidRootPart") then return n end
        end
    end
    local WEAPONS, SKEYS = { "Melee", "Blox Fruit", "Sword", "Gun" }, { "Z", "X", "C", "V", "F" }
    local skillBusy = false
    -- skills: equipa cada arma escolhida e aperta as teclas dela, com a mira (Mouse.Hit) cravada no alvo
    local function skillWorker(hit)
        if skillBusy then return end
        skillBusy = true
        task.spawn(function()
            pcall(function()
                for _, tip in ipairs(WEAPONS) do
                    if Alive and Config.LevWeapons[tip] and hit and hit.Parent then
                        Config.SeaTool = { tip = tip }
                        Config.SeaUntil = os.clock() + 1.5
                        pcall(equipWeapon)
                        task.wait(0.25)
                        for _, k in ipairs(SKEYS) do
                            local ks = Config.LevKeys[tip]
                            if Alive and ks and ks[k] and hit.Parent then
                                Config.SeaUntil = os.clock() + 1.5
                                pcall(AFL.tvHook)
                                AFL.TV.aimPos, AFL.TV.aimPart = hit.Position, hit
                                local kc = Enum.KeyCode[k]
                                VirtualInputManager:SendKeyEvent(true, kc, false, game)
                                task.wait(Config.LevFast and 0.05 or (tonumber(Config.LevHold) or 0.3))
                                VirtualInputManager:SendKeyEvent(false, kc, false, game)
                                task.wait(0.15)
                            end
                        end
                    end
                end
            end)
            AFL.TV.aimPos, AFL.TV.aimPart = nil, nil
            skillBusy = false
        end)
    end
    local function attackLev(t)
        local char, hrp, hum = getChar()
        local root = t:FindFirstChild("HumanoidRootPart") or t.PrimaryPart
        local hit = t:FindFirstChild("Hitbox11") or root
        if not (root and hit) then return false end
        busy("Leviathan: " .. t.Name)
        SE.lev = "attacking " .. t.Name
        if hum.Sit then hum.Sit = false end
        local stand = Vector3.new(root.Position.X, 142, root.Position.Z)
        if near(hrp.Position, stand) > 12 then flyTo(CFrame.new(stand)) else
            if currentTween then currentTween:Cancel() end
            hrp.CFrame = CFrame.lookAt(stand, hit.Position)
            hrp.AssemblyLinearVelocity = Vector3.zero
        end
        Aim.part, Aim.level = hit, false
        Config.AttackUntil = os.clock() + 0.8
        if Config.LevFruit then
            Config.SeaTool = { tip = "Blox Fruit" }
            Config.SeaClick = { kind = "fruit", part = hit, untilT = os.clock() + 0.8 }
            pcall(equipWeapon)
        elseif Config.LevDragon then
            Config.SeaTool = { name = "dragonstorm" }
            Config.SeaClick = { kind = "ds", part = hit, untilT = os.clock() + 0.8 }
            pcall(equipWeapon)
        elseif Config.LevGuitar then
            Config.SeaTool = { name = "skull guitar" }
            Config.SeaClick = { kind = "sg", part = hit, untilT = os.clock() + 0.8 }
            pcall(equipWeapon)
        elseif Config.LevSkills then
            Config.SeaClick = nil
            skillWorker(hit)
        end
        return true
    end
    local function heartStep(boat, seat)
        local map = workspace:FindFirstChild("Map")
        local heart = map and map:FindFirstChild("FrozenHeart")
        if not heart then return false end
        local ins = heart:FindFirstChild("Inside")
        if ins and ins:GetAttribute("Harpooned") then SE.lev = "the heart was already harpooned"; return false end
        local cube = heart:FindFirstChild("Cube")
        if not (cube and boat and seat and boat:FindFirstChild("Harpoon")) then SE.lev = "heart: needs your Beast Hunter boat"; return false end
        busy("Shooting the Frozen Heart")
        local _, hrp, hum = getChar()
        stepBoatNoclip(boat)
        local spot = Vector3.new(cube.Position.X, seat.Position.Y, cube.Position.Z + 300)
        if near(seat.Position, spot) > 5 and not (hum.SeatPart and hum.SeatPart.Name == "Seat") then
            if hum.SeatPart ~= seat then seatUp(boat, seat); SE.lev = "heart: getting on the boat"; return true end
            SE.lev = "heart: sailing to the heart"
            boatTo(seat, spot, 150)
            return true
        end
        stopBoat()
        pcall(function() boat:PivotTo(CFrame.lookAt(boat:GetPivot().Position, Vector3.new((ins or cube).Position.X, boat:GetPivot().Position.Y, (ins or cube).Position.Z))) end)
        local hs = boat.Harpoon:FindFirstChild("Seat")
        if hs and hum.SeatPart ~= hs then flyTo(hs.CFrame + Vector3.new(0, 2, 0)); if near(hrp.Position, hs.Position) < 15 then hrp.CFrame = hs.CFrame + Vector3.new(0, 2, 0) end; SE.lev = "heart: going to the harpoon"; return true end
        if os.clock() - levAt > 1.5 then
            levAt = os.clock()
            local cf = commF()
            if cf then pcall(function() cf:InvokeServer("FireHarpoon", 0.7853981633974483, 0.00044342573293783646, boat.Harpoon, workspace:GetServerTimeNow()) end) end
        end
        SE.lev = "heart: firing the harpoon"
        return true
    end
    function SE.levStep()
        if not (Config.LevSpy or Config.LevFind or Config.LevStart or Config.LevTP or Config.LevBoatTo or Config.LevAttack or Config.LevHeart) then return false end
        if getSea() ~= 3 then SE.lev = "Leviathan only works in Sea 3"; return false end
        local char, hrp, hum = getChar()
        if not hrp or hum.Health <= 0 then return false end
        local FD = loc("Frozen Dimension")
        -- espião: libera a informação do Leviathan
        if Config.LevSpy and not FD and os.clock() - spyAt > 25 then
            spyAt = os.clock()
            local cf = commF()
            if cf then task.spawn(function() pcall(function() cf:InvokeServer("InfoLeviathan", "1"); cf:InvokeServer("InfoLeviathan", "2") end) end) end
        end
        -- 1) atacar
        if Config.LevAttack then
            local t = levTarget()
            if t and attackLev(t) then return true end
        end
        -- 2) arpão no coração
        if Config.LevHeart then
            local boat, seat = myBoat()
            if heartStep(boat, seat) then return true end
        end
        -- 3) Frozen Watcher: abrir o portão / teleportar
        if FD and (Config.LevStart or Config.LevTP) then
            local w = watcher()
            if w then
                busy("Frozen Watcher")
                local p = w.HumanoidRootPart.Position
                if near(hrp.Position, p) >= 8 then SE.lev = "going to the Frozen Watcher"; flyTo(w.HumanoidRootPart.CFrame) return true end
                if Config.LevStart and os.clock() - levAt > 3 then
                    levAt = os.clock()
                    local cf = commF()
                    if cf then pcall(function() cf:InvokeServer("OpenLeviathanGate") end) end
                    SE.lev = "opening the gate"
                end
                return true
            end
        end
        -- 4) levar o barco até a Frozen Dimension
        if FD and Config.LevBoatTo then
            local boat, seat = myBoat()
            if boat and near(seat.Position, FD.Position) > 400 then
                busy("Sailing to the Frozen Dimension")
                if not seatUp(boat, seat) then SE.lev = "getting on the boat"; return true end
                stepBoatNoclip(boat)
                SE.lev = "sailing to the Frozen Dimension"
                boatTo(seat, Vector3.new(FD.Position.X, seat.Position.Y, FD.Position.Z), tonumber(Config.LevSpeed) or 200)
                return true
            end
        end
        -- 5) procurar: mesma lógica do Auto Sea Events (Select Zones, Fly Boat, Speed, Back 10k)
        if Config.LevFind and not FD then
            busy("Looking for the Frozen Dimension")
            SE.lev = "sailing like Sea Events (zone " .. tostring(Config.SeaZone) .. ") | " .. tostring(Diag.sea)
            Sea.zone = 0 -- Leviathan: sem trava de zona
            local sr = Sea.step(not Config.SeaOn)
            Sea.zone = nil
            if sr then return true end
        end
        if FD then SE.lev = "Frozen Dimension is open" else SE.lev = "idle" end
        return false
    end

    -- ===== UI =====
    local function tg(id, title, desc)
        T:AddToggle(id, { Title = title, Description = desc, Default = Config[id] and true or false }):OnChanged(function(v)
            Config[id] = v
            if not v then stopBoat() end
            persist()
        end)
    end
    local ki = { SetDesc = function() end }   -- o painel do Kitsune agora fica na aba Auto Fully
    T:AddSection("Leviathan")
    tg("LevSpy", "Auto Buy Spy", "Asks the spy for the Leviathan info now and then while the Frozen Dimension is not open")
    tg("LevFind", "Auto Find Leviathan", "Sails exactly like Auto Sea Events: uses Select Zones, Fly Boat, Speed Boat and the Sea options above (buys the boat if needed)")
    T:AddSlider("LevSpeed", { Title = "Speed Boat To Frozen Dimension", Description = "Only for the Tween Boat / Heart steps", Min = 50, Max = 500, Default = math.clamp(tonumber(Config.LevSpeed) or 200, 50, 500), Rounding = 0 })
        :OnChanged(function(v) Config.LevSpeed = math.floor(v); persist() end)
    tg("LevBoatTo", "Tween Boat To Frozen Dimension", "Sails the boat to the Frozen Dimension once it exists")
    tg("LevTP", "Teleport Frozen Dimension", "Goes to the Frozen Watcher")
    tg("LevStart", "Auto Start Leviathan", "At the Frozen Watcher, opens the Leviathan gate")
    tg("LevAttack", "Auto Attack Leviathan", "Kills the tail first, then the body, then the segments, from 142 studs above, with the attack chosen below")
    tg("LevFruit", "Attack Leviathan (M1 Fruit)", "Fruit M1, auto-aimed. Priority: M1 Fruit > Dragonstorm > Skull Guitar > Skills")
    tg("LevDragon", "Attack Leviathan Dragonstorm", "Dragonstorm remote shot, auto-aimed (no clicking on the screen)")
    tg("LevGuitar", "Attack Leviathan Skull Guitar", "Skull Guitar remote shot, auto-aimed")
    tg("LevSkills", "Attack Leviathan Skills", "Used when no M1 above is on: equips each weapon below and presses its skills on the target")
    T:AddSection("Leviathan Skills")
    local function multi(v)
        local set = {}
        if type(v) == "table" then for k, val in pairs(v) do if val == true then set[k] = true elseif type(val) == "string" then set[val] = true end end end
        return set
    end
    local wd = T:AddDropdown("LevWeaponsDD", { Title = "Select Weapons Use Skills", Values = WEAPONS, Multi = true, Default = { ["Blox Fruit"] = true } })
    wd:OnChanged(function(v) Config.LevWeapons = multi(v); persist() end)
    for _, tip in ipairs(WEAPONS) do
        local def = {}
        for k in pairs(Config.LevKeys[tip] or {}) do def[k] = true end
        T:AddDropdown("LevKeys" .. tip, { Title = "Skills: " .. tip, Description = "Keys pressed with this weapon", Values = (tip == "Blox Fruit") and SKEYS or { "Z", "X", "C", "V" }, Multi = true, Default = def })
            :OnChanged(function(v) Config.LevKeys[tip] = multi(v); persist() end)
    end
    tg("LevFast", "Use skill fast (don't hold)", "Taps each key quickly. Off: holds it for the time below")
    T:AddSlider("LevHold", { Title = "Skill Hold Time (s)", Min = 0, Max = 3, Default = tonumber(Config.LevHold) or 0.3, Rounding = 1 })
        :OnChanged(function(v) Config.LevHold = v; persist() end)
    T:AddSection("Leviathan Heart")
    tg("LevHeart", "Auto Fire Shoot Heart Leviathan", "Uses your Beast Hunter boat harpoon on the Frozen Heart")
    local li = T:AddParagraph({ Title = "Leviathan", Content = "..." })
    task.spawn(function()
        while Alive do
            pcall(function()
                local k, active = kitIsland()
                local kiP = AFL.kiPara or ki   -- v56: a line starting with "(" after kitIsland() was parsed as kitIsland()(...) and threw, so this panel never updated
                local mRem, mTxt = SE.moonRemain()
                kiP:SetDesc("Now: " .. tostring(SE.kit) .. "\nFull moon: " .. tostring(mTxt) .. "\nIsland: " .. (k and (active and "ready" or "found (shrine busy)") or "not found") .. " | Azure Ember: " .. tostring(AFL.Inv.count("Azure Ember")) .. " | Event: " .. (raidTimer() and "running" or "off") .. (Config.FullKitsune and ("\nMoon: " .. tostring(SE.kitMoon or "-") .. (AFL.hopLast and ("\nHop: " .. tostring(AFL.hopLast) .. (AFL.noDirect and " [direct teleport blocked]" or "")) or "")) or "") .. (Config.FullKitsune and AFL.QApi and AFL.QApi.msg ~= "" and ("\nAPI: " .. tostring(AFL.QApi.msg)) or "") .. ((SE.kitTraded or SE.kitLastTrade) and ("\nTrade: " .. tostring(SE.kitLastTrade or "-") .. " | total traded: " .. tostring(SE.kitTraded or 0)) or ""))
                li:SetDesc("Now: " .. tostring(SE.lev) .. "\nFrozen Dimension: " .. (loc("Frozen Dimension") and "open" or "not found") .. " | Leviathan: " .. (levTarget() and "alive" or "none"))
            end)
            task.wait(1.5)
        end
    end)
end)()





