    PC.src["fruits"] = function() return [===[
local __E = ...
local AFL = __E.AFL
local Aim, Config, Connections, Diag, Fluent, Player, State = __E.Aim, __E.Config, __E.Connections, __E.Diag, __E.Fluent, __E.Player, __E.State
local Tabs, Window, canFile, distanceTo, flyTo, getChar, getPlayerLevel = __E.Tabs, __E.Window, __E.canFile, __E.distanceTo, __E.flyTo, __E.getChar, __E.getPlayerLevel
local getSea, invCount, invoke, persist = __E.getSea, __E.invCount, __E.invoke, __E.persist
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")
local Alive = true
AFL.onUnload(function() Alive = false end);
-- ============ FRUITS ============
-- Contagem de frutas físicas (nome contém "Fruit")
local function countFruits()
    local n = 0
    for _, c in ipairs({ Player.Backpack, Player.Character }) do
        if c then
            for _, t in ipairs(c:GetChildren()) do
                if t:IsA("Tool") and string.find(t.Name, "Fruit") then n += 1 end
            end
        end
    end
    return n
end

-- Auto Store: no máximo 2 tentativas por fruta (fruta nova = tentativas novas)
local StoreTries = setmetatable({}, { __mode = "k" })
local function storeStep()
    if (Config.PayHoldUntil or 0) > os.clock() then return end -- pagando a raid com fruta: não guarda
    for _, c in ipairs({ Player.Backpack, Player.Character }) do
        if c then
            for _, t in ipairs(c:GetChildren()) do
                if t:IsA("Tool") and string.find(t.Name, "Fruit") and (StoreTries[t] or 0) < 2 then
                    StoreTries[t] = (StoreTries[t] or 0) + 1
                    invoke("StoreFruit", t:GetAttribute("OriginalName") or t.Name, t)
                    task.wait(0.3)
                end
            end
        end
    end
end

-- Auto Random Fruit (gacha). Cooldown de 2h compartilhado entre os mares.
-- 1) tenta o remote de onde estiver; 2) se não vier fruta, voa até o NPC e tenta de novo
--    (remote, ProximityPrompt e botão da janela do gacha). O resultado fica em Status > Diagnóstico.
local Gacha = { nextAt = 0, last = "has not spun yet", tries = 0, phase = "idle", travelSince = 0, pauseUntil = 0 }
pcall(function()
    if canFile() and isfile("MoonHub_gacha.txt") then
        Gacha.nextAt = tonumber(readfile("MoonHub_gacha.txt")) or 0
    end
end)
local function saveGacha()
    pcall(function()
        if canFile() then writefile("MoonHub_gacha.txt", tostring(Gacha.nextAt)) end
    end)
end

local function describe(v)
    if type(v) == "table" then
        local parts, n = {}, 0
        for k, x in pairs(v) do
            n += 1
            if n > 5 then break end
            parts[#parts + 1] = tostring(k) .. "=" .. tostring(x)
        end
        return "{" .. table.concat(parts, ", ") .. "}"
    end
    return tostring(v)
end

local function npcPart(m)
    return m:FindFirstChild("HumanoidRootPart") or m.PrimaryPart or m:FindFirstChildWhichIsA("BasePart")
end

-- Nomes de NPCs por perto (ajuda a achar o NPC certo se o gacha mudar de nome)
local function nearbyNpcNames()
    local names, seen = {}, {}
    local _, hrp = getChar()
    local npcs = workspace:FindFirstChild("NPCs")
    if npcs and hrp then
        for _, m in ipairs(npcs:GetChildren()) do
            local part = npcPart(m)
            if part and not seen[m.Name] and (part.Position - hrp.Position).Magnitude < 400 then
                seen[m.Name] = true
                names[#names + 1] = m.Name
                if #names >= 8 then break end
            end
        end
    end
    return #names > 0 and table.concat(names, ", ") or "none"
end

local ZiolesCache, ZiolesLast = nil, 0
local function findGachaNpc()
    local _, hrp = getChar()
    -- NPC "Zioles": primeiro em workspace.NPCs, depois uma busca geral (no máx. a cada 5s)
    if ZiolesCache and ZiolesCache.Parent then return ZiolesCache end
    local z = workspace:FindFirstChild("NPCs") and workspace.NPCs:FindFirstChild("Zioles")
    if not z and os.clock() - ZiolesLast > 5 then
        ZiolesLast = os.clock()
        z = workspace:FindFirstChild("Zioles", true)
    end
    if z and z:IsA("Model") and npcPart(z) then
        ZiolesCache = z
        return z
    end
    local npcs = workspace:FindFirstChild("NPCs")
    if not npcs then return end
    local best, bestD = nil, math.huge
    for _, m in ipairs(npcs:GetChildren()) do
        local n = string.lower(m.Name)
        if string.find(n, "cousin", 1, true) or string.find(n, "gacha", 1, true) or string.find(n, "zioles", 1, true) then
            local part = npcPart(m)
            if part then
                local d = hrp and (hrp.Position - part.Position).Magnitude or 0
                if d < bestD then best, bestD = m, d end
            end
        end
    end
    return best
end

-- Chama o remote e confere se veio fruta (ou se a resposta parece o tempo restante do cooldown)
-- Quantas frutas estão GUARDADAS no inventário (o gacha pode mandar a fruta direto para lá)
local function invFruitCount()
    local ok, inv = invoke("getInventoryFruits")
    if ok and type(inv) == "table" then
        local n = 0
        for _ in pairs(inv) do n += 1 end
        return n
    end
end

-- Recebeu fruta? (mochila OU inventário)
local function gotFruit(beforeBag, beforeInv)
    if countFruits() > beforeBag then return true end
    local now = invFruitCount()
    return beforeInv ~= nil and now ~= nil and now > beforeInv
end

local function tryRoll()
    local before, beforeInv = countFruits(), invFruitCount()
    Gacha.rollClock = os.clock()
    local ok, r
    local net = ReplicatedStorage:FindFirstChild("Modules") and ReplicatedStorage.Modules:FindFirstChild("Net")
    local rf = net and net:FindFirstChild("RF/GachaNetworkRF")
    if rf then
        ok, r = pcall(function()
            return rf:InvokeServer({ Context = "Purchase", BoxName = "ZiolesGacha" })
        end)
    else
        ok, r = invoke("Cousin", "Buy") -- plano B (remote antigo)
    end
    Gacha.tries += 1
    Gacha.last = (ok and "reply: " or "error: ") .. describe(r)
    task.wait(1.5)
    if gotFruit(before, beforeInv) then return true, "fruit received" end
    if ok and type(r) == "string" then
        local l = string.lower(r)
        if string.find(l, "cooldown", 1, true) or string.find(l, "wait", 1, true)
            or string.find(l, "hour", 1, true) or string.find(l, "minute", 1, true) then
            return true, "on cooldown (game text)", 1800
        end
    end
    if ok and type(r) == "number" and r >= 30 and r <= 7200 then
        return true, "on cooldown", math.floor(r)
    end
    if ok and type(r) == "table" then
        if r.Success == true or r.success == true then return true, "gacha accepted" end
        for k, v in pairs(r) do
            local key = string.lower(tostring(k))
            if type(v) == "number" and v >= 30 and v <= 7200
                and (string.find(key, "cool", 1, true) or string.find(key, "remain", 1, true) or string.find(key, "time", 1, true)) then
                return true, "on cooldown (" .. tostring(k) .. ")", math.floor(v)
            end
        end
    end
    return false
end

-- Plano B: ProximityPrompt do NPC e botão de girar dentro de uma janela de gacha
local function pressGachaUi(npc)
    pcall(function()
        for _, d in ipairs(npc:GetDescendants()) do
            if d:IsA("ProximityPrompt") then
                fireproximityprompt(d)
                break
            elseif d:IsA("ClickDetector") and fireclickdetector then
                fireclickdetector(d)
            end
        end
    end)
    task.wait(1.2)
    pcall(function()
        local pg = Player:FindFirstChild("PlayerGui")
        if not pg or not firesignal then return end
        for _, b in ipairs(pg:GetDescendants()) do
            if (b:IsA("TextButton") or b:IsA("ImageButton")) and b.Visible then
                local inGacha, a = false, b.Parent
                while a and a ~= pg do
                    local n = string.lower(a.Name)
                    if string.find(n, "gacha", 1, true) or string.find(n, "cousin", 1, true) then
                        inGacha = true
                        break
                    end
                    a = a.Parent
                end
                if inGacha then
                    local label = string.lower(b.Name .. " " .. (b:IsA("TextButton") and b.Text or ""))
                    if string.find(label, "roll", 1, true) or string.find(label, "spin", 1, true)
                        or string.find(label, "buy", 1, true) or string.find(label, "open", 1, true)
                        or string.find(label, "girar", 1, true) then
                        firesignal(b.MouseButton1Click)
                        Gacha.last = "clicked: " .. b:GetFullName()
                        return
                    end
                end
            end
        end
    end)
end

-- Retorna true enquanto estiver usando o personagem (voando até o NPC)
local function gachaMission()
    local now = os.time()
    if now < Gacha.nextAt or now < Gacha.pauseUntil then return false end
    if getPlayerLevel() < 50 then
        Diag.gacha = "minimum level 50 for the gacha"
        return false
    end

    pcall(function()
        local Spinner = require(game:GetService("ReplicatedStorage").Controllers.UI.Spinner)
        local SharedGachaUtil = require(game.ReplicatedStorage.Modules.Gacha.SharedGachaUtil)
        local pg = game:GetService("Players").LocalPlayer:FindFirstChild("PlayerGui")
        
        if pg then
            local spinnerWindow = pg:FindFirstChild("SpinnerWindow")
            if not spinnerWindow or not spinnerWindow.Enabled then
                if typeof(RandomFruit) == "function" then
                    RandomFruit()
                end
            elseif spinnerWindow.Enabled and spinnerWindow:FindFirstChild("AboveSpinner") 
               and spinnerWindow.AboveSpinner:FindFirstChild("Navigation") 
               and spinnerWindow.AboveSpinner.Navigation:FindFirstChild("CloseButton") 
               and spinnerWindow.AboveSpinner.Navigation.CloseButton.Visible then
                Spinner:Close()
            end
        end
    end)

    local done, why, secs
    for _ = 1, 3 do
        done, why, secs = tryRoll()
        if done then break end
        task.wait(1)
    end
    local npc
    if not done then
        npc = findGachaNpc()
        local part = npc and npcPart(npc)
        if part and distanceTo(part.CFrame) <= 60 then
            local before, beforeInv = countFruits(), invFruitCount()
            pressGachaUi(npc)
            task.wait(2)
            if gotFruit(before, beforeInv) then done, why = true, "fruit received (NPC/window, nearby)" end
        end
    end
    Gacha.phase = "idle"
    if done then
        Gacha.nextAt = os.time() + (secs or 7200)
        Gacha.tries = 0
        saveGacha()
        Diag.gacha = "ok (" .. why .. ") | " .. Gacha.last
        return false
    end
    Gacha.pauseUntil = os.time() + ((Gacha.tries < 6) and 120 or 900)
    Diag.gacha = string.format("could not spin from here (%d attempts) | %s | if the server only accepts spins next to Zioles this cannot work from afar",
        Gacha.tries, Gacha.last)
    return false
end

-- v31: Remove Gacha Effect esconde a roleta/animacao E a janela de resultado (a janela de resultado no fim do giro
-- nem sempre tem "gacha"/"roleta" no nome, entao alem do nome tambem conta qualquer GuiObject novo que apareceu
-- pouco depois de um giro de verdade - Gacha.rollClock e marcado em tryRoll()). Alem disso, fecha essa janela de
-- resultado sozinho (acha o botao de fechar - "X"/"Close"/"Exit" - e clica) mesmo com o Remove Gacha Effect
-- desligado, pra nao ficar travada na tela depois do giro (o bug reportado).
local function nameLooksGacha(n)
    n = string.lower(n)
    return string.find(n, "gacha", 1, true) or string.find(n, "roulette", 1, true)
        or string.find(n, "roleta", 1, true) or string.find(n, "ziole", 1, true)
end
local function hideGachaUi(inst)
    pcall(function()
        local recent = Gacha.rollClock and (os.clock() - Gacha.rollClock < 6)
        if not (nameLooksGacha(inst.Name) or recent) then return end
        if inst:IsA("ScreenGui") then
            inst.Enabled = false
        elseif inst:IsA("GuiObject") then
            inst.Visible = false
        end
    end)
end
local function closeButtonIn(root)
    local found
    pcall(function()
        for _, b in ipairs(root:GetDescendants()) do
            if (b:IsA("TextButton") or b:IsA("ImageButton")) and b.Visible then
                local txt = b:IsA("TextButton") and tostring(b.Text) or ""
                local nm = string.lower(b.Name)
                if txt == "X" or txt == "x" or nm == "close" or nm == "closebutton" or nm == "exitbutton" or nm == "exit"
                    or string.find(nm, "close", 1, true) or string.find(nm, "exitbtn", 1, true) then
                    found = b
                    break
                end
            end
        end
    end)
    return found
end
Gacha.recentUi = {} -- {inst=GuiObject, at=os.clock()} - janelas que apareceram perto de um giro, candidatas a serem a janela de resultado
local function closeGachaPopups()
    for i = #Gacha.recentUi, 1, -1 do
        local e = Gacha.recentUi[i]
        if not (e.inst and e.inst.Parent) or os.clock() - e.at > 8 then
            table.remove(Gacha.recentUi, i)
        elseif os.clock() - e.at >= 0.4 then -- da um tempinho pra janela terminar de montar antes de procurar o botao
            local b = closeButtonIn(e.inst)
            if b then
                pcall(function() if firesignal then firesignal(b.MouseButton1Click) end end)
                table.remove(Gacha.recentUi, i)
            end
        end
    end
end
task.spawn(function()
    local pg = Player:WaitForChild("PlayerGui", 10)
    if pg then
        table.insert(Connections, pg.DescendantAdded:Connect(function(d)
            if Config.RemoveGachaEffect then task.defer(hideGachaUi, d) end
            if (d:IsA("ScreenGui") or d:IsA("Frame") or d:IsA("ImageLabel") or d:IsA("CanvasGroup"))
                and Gacha.rollClock and os.clock() - Gacha.rollClock < 6 then
                Gacha.recentUi[#Gacha.recentUi + 1] = { inst = d, at = os.clock() }
            end
        end))
        table.insert(Connections, RunService.Heartbeat:Connect(function()
            if #Gacha.recentUi > 0 then closeGachaPopups() end
        end))
    end
end)

local SpinnerMod
pcall(function()
    SpinnerMod = require(game:GetService("ReplicatedStorage").Controllers.UI.Spinner)
end)
local function closeSpinner()
    pcall(function()
        local pg = Player:FindFirstChild("PlayerGui")
        local w = pg and pg:FindFirstChild("SpinnerWindow")
        if SpinnerMod and w and w.AboveSpinner.Navigation.CloseButton.Visible then
            SpinnerMod:Close()
        end
    end)
end
task.spawn(function()
    while true do
        task.wait(0.3)
        if Gacha.rollClock and os.clock() - Gacha.rollClock < 20 then
            closeSpinner()
        end
    end
end)


-- v27: sem fruta carregada por perto -> visita cada ilha do mapa (a fruta so existe no cliente perto de voce,
-- igual ao Auto Farm Chest). So depois de rodar o mapa inteiro sem achar nada e que entra o hop (mesmo AFL.hopRequest de sempre).
AFL.FruitTour = { tour = nil, tourI = 1, tourAt = 0, dwell = nil, restUntil = 0, noneSince = nil }
local function fruitTourBuild(from)
    local list = {}
    local map = workspace:FindFirstChild("Map")
    if map then
        for _, m in ipairs(map:GetChildren()) do
            if m:IsA("Model") then
                local ok, sz = pcall(function() return m:GetExtentsSize() end)
                if ok and sz.Magnitude > 150 then
                    local ok2, cf = pcall(function() return m:GetPivot() end)
                    -- v76: ignora modelos de agua/limite do mar e pivos no nivel do mar ou abaixo (o hub voava para a agua no Sea 2)
                    local nm = m.Name:lower()
                    local bad = nm:find("water", 1, true) or nm:find("ocean", 1, true) or nm:find("sea", 1, true) or nm:find("fog", 1, true)
                        or nm:find("border", 1, true) or nm:find("barrier", 1, true) or nm:find("boundary", 1, true) or nm:find("skybox", 1, true)
                    if ok2 and not bad and cf.Position.Y > 3 then list[#list + 1] = cf.Position end
                end
            end
        end
    end
    local out, cur = {}, from
    while #list > 0 do
        local bi, bd = 1, math.huge
        for i, p in ipairs(list) do
            local d = (p - cur).Magnitude
            if d < bd then bi, bd = i, d end
        end
        cur = table.remove(list, bi)
        out[#out + 1] = cur
    end
    return out
end
function AFL.fruitSearchStep()
    local _, hrp = getChar()
    if not hrp then return false end
    local FT = AFL.FruitTour
    if os.clock() < FT.restUntil then return false end
    if not FT.tour then FT.tour, FT.tourI, FT.tourAt, FT.dwell = fruitTourBuild(hrp.Position), 1, os.clock(), nil end
    local tgt = FT.tour[FT.tourI]
    if not tgt then
        FT.tour, FT.restUntil = nil, os.clock() + 20
        FT.noneSince = FT.noneSince or os.clock()
        return false
    end
    State.Mode = "Auto Collect Fruit"
    State.Text = string.format("Searching the whole map for fruits (island %d/%d)", FT.tourI, #FT.tour)
    local goal = tgt + Vector3.new(0, 80, 0)
    local _, hrpNow = getChar()
    if hrpNow and (hrpNow.Position - goal).Magnitude > 60 and os.clock() - FT.tourAt < 35 then
        flyTo(CFrame.new(goal))
        return true
    end
    FT.dwell = FT.dwell or (os.clock() + 1)
    if os.clock() < FT.dwell then return true end
    FT.tourI, FT.tourAt, FT.dwell = FT.tourI + 1, os.clock(), nil
    return true
end

-- Auto Collect: frutas no chão (inclusive as que acabaram de nascer)
local FruitBlacklist = setmetatable({}, { __mode = "k" })
local CollectTarget, CollectStart = nil, 0

local function findGroundFruit()
    local _, hrp = getChar()
    if not hrp then return end
    local best, bestDist = nil, math.huge
    local SKIP = { Map = true, Enemies = true, NPCs = true, _WorldOrigin = true, Characters = true, Boats = true, SeaBeasts = true, Camera = true }
    local function consider(v)
        if v:IsA("Tool") and string.find(v.Name, "Fruit") and (FruitBlacklist[v] or 0) < os.clock() then
            local handle = v:FindFirstChild("Handle")
            if handle then
                local d = (hrp.Position - handle.Position).Magnitude
                if d < bestDist then best, bestDist = v, d end
            end
        end
    end
    for _, v in ipairs(workspace:GetChildren()) do
        consider(v)
        if (v:IsA("Folder") or v:IsA("Model")) and not SKIP[v.Name] and not Players:GetPlayerFromCharacter(v) then
            for _, w in ipairs(v:GetChildren()) do consider(w) end
        end
    end
    return best
end

local function collectStep(fruit)
    local handle = fruit:FindFirstChild("Handle")
    if not handle then return end
    local _, hrp0 = getChar()
    local dist0 = hrp0 and (hrp0.Position - handle.Position).Magnitude or math.huge
    if CollectTarget ~= fruit then CollectTarget, CollectStart, State.collectBest = fruit, os.clock(), math.huge end
    -- sem limite de distancia: so conta como travado se ficar 45s sem chegar mais perto
    if dist0 < (State.collectBest or math.huge) - 5 then State.collectBest, CollectStart = dist0, os.clock() end
    if os.clock() - CollectStart > 45 then
        FruitBlacklist[fruit] = os.clock() + 60
        CollectTarget = nil
        return
    end
    State.Mode = "Auto Collect Fruit"
    State.Text = "Collecting " .. fruit.Name
    flyTo(handle.CFrame)
    local _, hrp = getChar()
    if hrp and (hrp.Position - handle.Position).Magnitude < 15 then
        pcall(function()
            firetouchinterest(hrp, handle, 0)
            firetouchinterest(hrp, handle, 1)
        end)
    end
end

-- ============ AUTO BUY FRUITS (stock normal) ============
-- Uma única tentativa por stock (o stock normal reseta a cada 4h). Ordem de prioridade: compra a PRIMEIRA
-- fruta da lista que estiver à venda e para ali, sem tentar as de prioridade menor.
local FruitNames = { "Rocket-Rocket", "Spin-Spin", "Blade-Blade", "Spring-Spring", "Bomb-Bomb", "Smoke-Smoke",
    "Spike-Spike", "Flame-Flame", "Falcon-Falcon", "Ice-Ice", "Sand-Sand", "Dark-Dark", "Diamond-Diamond",
    "Light-Light", "Rubber-Rubber", "Ghost-Ghost", "Magma-Magma", "Quake-Quake", "Buddha-Buddha", "Love-Love",
    "Creation-Creation", "Spider-Spider", "Sound-Sound", "Phoenix-Phoenix", "Portal-Portal", "Rumble-Rumble",
    "Pain-Pain", "Blizzard-Blizzard", "Gravity-Gravity", "Mammoth-Mammoth", "T-Rex-T-Rex", "Dough-Dough",
    "Shadow-Shadow", "Venom-Venom", "Gas-Gas", "Control-Control", "Spirit-Spirit", "Dragon-Dragon",
    "Leopard-Leopard", "Yeti-Yeti", "Kitsune-Kitsune",
    "Kilo-Kilo", "Chop-Chop", "Revive-Revive", "Paw-Paw", "Magnet-Magnet", "Dragon East-Dragon East", "Dragon West-Dragon West" }

-- Tenta comprar SEMPRE que o stock normal resetar (mudança de época de 4h OU mudança no conteúdo do stock).
-- Só considera frutas de prioridade MAIOR que a melhor que você já tem; compra a primeira à venda e não repete a compra.
local Buy = { epoch = nil, sig = nil, reads = 0, bought = {} }
-- v30: compara nomes de fruta de forma tolerante ("Dragon East-Dragon East", "Dragon (East)-Dragon (East)", "Dragon East" -> "dragoneast")
local function normFruit(n)
    n = string.lower(tostring(n))
    local half = string.match(n, "^(.+)%-%1$")
    if half then n = half end
    return (string.gsub(n, "[^%w]", ""))
end
local function ownsFruit(name)
    local short = string.lower(string.sub(name, 1, math.floor((#name - 1) / 2))) -- "Dragon-Dragon" -> "dragon", "T-Rex-T-Rex" -> "t-rex"
    local function match(n) return n and string.find(string.lower(n), short, 1, true) end
    for _, c in ipairs({ Player.Backpack, Player.Character }) do
        if c then
            for _, t in ipairs(c:GetChildren()) do
                if t:IsA("Tool") and string.find(t.Name, "Fruit", 1, true) == nil and match(t.Name) and t.ToolTip == "Blox Fruit" then return true end
            end
        end
    end
    local okD, eaten = pcall(function() return Player.Data.DevilFruit.Value end)
    if okD and type(eaten) == "string" and eaten ~= "" and match(eaten) then return true end
    return invCount(name) > 0
end
local function buyStep()
    local prios = {}
    for _, f in ipairs(Config.BuyPrio) do
        if f and f ~= "None" then prios[#prios + 1] = f end
    end
    if #prios == 0 then
        Diag.buy = "choose at least 1 fruit in the priorities"
        return
    end
    local ok, stock = invoke("GetFruits")
    if not ok or type(stock) ~= "table" then
        Buy.reads += 1
        Diag.buy = "could not read the stock: " .. tostring(stock)
        return
    end
    Buy.reads = 0
    local hasFlag, onSale, names = false, {}, {}
    for _, v in pairs(stock) do
        if type(v) == "table" and v.Name and v.OnSale ~= nil then hasFlag = true end
    end
    for _, v in pairs(stock) do
        if type(v) == "table" and v.Name and ((not hasFlag) or v.OnSale == true) then
            onSale[normFruit(v.Name)] = v.Name
            names[#names + 1] = v.Name
        end
    end
    table.sort(names)
    local epoch, sig = math.floor(os.time() / 14400), table.concat(names, ",")
    if Buy.epoch == epoch and Buy.sig == sig then return end -- mesmo stock: nada novo para tentar
    if Buy.epoch ~= epoch or Buy.sig ~= sig then Buy.bought = {} end -- stock novo: libera novas compras
    Buy.epoch, Buy.sig = epoch, sig
    -- a melhor fruta (menor número) que você já possui: só vale comprar as de prioridade MAIOR que ela
    local ownedIdx = #prios + 1
    for i, want in ipairs(prios) do
        if ownsFruit(want) then ownedIdx = i break end
    end
    for i = 1, ownedIdx - 1 do
        local want = prios[i]
        local real = onSale[normFruit(want)]
        if real and not Buy.bought[real] then
            Buy.bought[real] = true -- uma única tentativa por fruta neste stock
            local ok2, r = invoke("PurchaseRawFruit", real)
            Diag.buy = string.format("priority %d (%s): %s -> %s", i, real, ok2 and "tried to buy" or "error", tostring(r))
            return
        end
    end
    if ownedIdx <= #prios then
        Diag.buy = "you already have " .. prios[ownedIdx] .. " (priority " .. ownedIdx .. "): I won't buy the lower priority ones"
    else
        Diag.buy = "no fruit from your list is in the normal stock right now"
    end
end


-- ===== rotina de fundo (v52): Auto Store, Auto Buy e Remove Gacha Effect =====
do
    local Timers = {}
    local function due(key, interval)
        local now = os.clock()
        if (Timers[key] or 0) <= now then Timers[key] = now + interval; return true end
        return false
    end
    task.spawn(function()
        while Alive do
            task.wait(0.5)
            pcall(function()
                if Config.AutoStore and due("store", 1) then storeStep() end
                if Config.AutoBuy and due("buy", 20) then buyStep() end
                if Config.RemoveGachaEffect and due("nogfx", 0.3) then
                    local pg = Player:FindFirstChild("PlayerGui")
                    if pg then
                        for _, c in ipairs(pg:GetChildren()) do hideGachaUi(c) end
                        local main = pg:FindFirstChild("Main")
                        if main then
                            for _, c in ipairs(main:GetChildren()) do hideGachaUi(c) end
                        end
                    end
                    local cam = workspace.CurrentCamera
                    if cam and not Aim.camChanged and os.clock() - (Gacha.rollClock or 0) < 12 and cam.CameraType == Enum.CameraType.Scriptable then
                        cam.CameraType = Enum.CameraType.Custom
                        local _, _, hum = getChar()
                        if hum then cam.CameraSubject = hum end
                    end
                end
            end)
        end
    end)
end

do
    local function sub(tab, text)
        local seen = {}
        local scanRoot = tab.Container or Window.Root
        for _, d in ipairs(scanRoot:GetDescendants()) do
            if d:IsA("TextLabel") then seen[d] = true end
        end
        pcall(function() tab:AddSection(text) end)
        for _, d in ipairs(scanRoot:GetDescendants()) do
            if d:IsA("TextLabel") and not seen[d] and d.Text == text then
                pcall(function() d.TextSize = 12; d.TextTransparency = 0.15 end)
                break
            end
        end
    end
    local function seaToggle(tab, id, title, key, sea, desc)
        local t = tab:AddToggle(id, { Title = title, Description = desc, Default = Config[key] and true or false })
        t:OnChanged(function(v)
            if v and sea and getSea() ~= sea then
                Fluent:Notify({ Title = "Moon Hub", Content = title .. " only works in Sea " .. sea .. ".", Duration = 5 })
                t:SetValue(false)
                return
            end
            Config[key] = v
            persist()
        end)
    end
    Tabs.Fruits:AddSection("Fruits")
    sub(Tabs.Fruits, "Random Fruit")
    Tabs.Fruits:AddToggle("AutoGacha", { Title = "Auto Random Fruit",
        Description = "Spins the fruit gacha from wherever you are (2h cooldown). It does not fly to Zioles", Default = Config.AutoGacha and true or false })
        :OnChanged(function(v) Config.AutoGacha = v; persist() end)
    Tabs.Fruits:AddToggle("AutoStore", { Title = "Auto Store",
        Description = "Tries to store each new fruit at most 2 times", Default = Config.AutoStore and true or false })
        :OnChanged(function(v) Config.AutoStore = v; persist() end)
    Tabs.Fruits:AddToggle("NoGachaFx", { Title = "Remove Gacha Effect",
        Description = "Disables the gacha UI when it spins", Default = Config.RemoveGachaEffect and true or false })
        :OnChanged(function(v) Config.RemoveGachaEffect = v; persist() end)
    sub(Tabs.Fruits, "Collect Fruit")
    Tabs.Fruits:AddToggle("CollectFruit", { Title = "Auto Collect Fruit",
        Description = "Has priority over any farm: pauses, picks up the fruit and goes back. With none nearby, visits every island of the map looking for one", Default = Config.CollectFruits and true or false })
        :OnChanged(function(v) Config.CollectFruits = v; persist() end)
    Tabs.Fruits:AddToggle("CollectHop", { Title = "Auto Collect Fruit Hop",
        Description = "After visiting the whole map with no fruit found, changes server (same hop as Auto Bounty). Needs Auto Collect Fruit on", Default = Config.CollectHop and true or false })
        :OnChanged(function(v) Config.CollectHop = v; persist() end)
    sub(Tabs.Fruits, "Auto Buy Fruits (Normal Stock)")
    local values = { "None" }
    for _, n in ipairs(FruitNames) do values[#values + 1] = n end
    for i = 1, 5 do
        local def = 1
        for k, n in ipairs(values) do if n == Config.BuyPrio[i] then def = k end end
        Tabs.Fruits:AddDropdown("BuyPrio" .. i, {
            Title = "Priority " .. i,
            Description = (i == 1) and "Tries to buy when the stock resets. If you already have a higher priority fruit, it does not buy the lower priority ones, and does not repeat the same purchase." or nil,
            Values = values, Default = def,
        }):OnChanged(function(v) Config.BuyPrio[i] = v; persist() end)
    end
    Tabs.Fruits:AddToggle("AutoBuy", { Title = "Auto Buy",
        Description = "Tries to buy every time the normal stock resets", Default = Config.AutoBuy and true or false })
        :OnChanged(function(v) Config.AutoBuy = v; persist() end)
end


AFL.findGroundFruit, AFL.collectStep, AFL.gachaMission, AFL.Gacha, AFL.countFruits, AFL.storeStep, AFL.buyStep, AFL.hideGachaUi, AFL.FruitNames = findGroundFruit, collectStep, gachaMission, Gacha, countFruits, storeStep, buyStep, hideGachaUi, FruitNames
]===] end
    PC.src["races"] = function() return [===[
local __E = ...
local AFL = __E.AFL
local Config, Diag, Player, State, Tabs, fightEnemy, findEnemy = __E.Config, __E.Diag, __E.Player, __E.State, __E.Tabs, __E.fightEnemy, __E.findEnemy
local findToolByName, flyTo, getChar, getSea, invCount, invoke, persist = __E.findToolByName, __E.flyTo, __E.getChar, __E.getSea, __E.invCount, __E.invoke, __E.persist
local Alive = true
AFL.onUnload(function() Alive = false end);
-- ---------- Races ----------
-- Bases: Banana + Quantum Onyx (Ghoul/Cyborg/V2/V3/V4) + NightRace (Ectoplasm, Fist of Darkness, Ghost Ship) + 6V3PullLever
-- + Conte_do_colado (Cursed Captain join API). Um recurso por vez, em ordem: Reroll > Ghoul > Cyborg > V2 > V3 > V4 Lever.
(function()
    local T = Tabs.Races
    local RS = game:GetService("ReplicatedStorage")
    local HttpSvc = game:GetService("HttpService")
    local TeleportSvc = game:GetService("TeleportService")
    local PlayersSvc = game:GetService("Players")
    local R = {}
    AFL.Race = R
    R.status = "Idle"
    local function cfgv(k, d) if Config[k] == nil then Config[k] = d end end
    cfgv("RaceReroll", false); cfgv("RaceTarget", "Ghoul"); cfgv("RaceGhoul", false); cfgv("RaceGhoulHop", true)
    cfgv("RaceCyborg", false); cfgv("RaceCyborgHop", true); cfgv("RaceV2", false); cfgv("RaceV3", false); cfgv("RaceV3Pvp", false)
    cfgv("RaceLever", false); cfgv("RaceGear", false); cfgv("RaceV4Auto", false)

    local function note(t) R.status = t; State.Mode, State.Text = "Races", t; Diag.race = t end
    local function inv(...) local ok, res = invoke(...); if ok then return res end return nil end
    local function pdata() return Player:FindFirstChild("Data") end
    local function raceVal() local d = pdata(); local r = d and d:FindFirstChild("Race"); return r and tostring(r.Value) or "?" end
    local function dval(n) local d = pdata(); local v = d and d:FindFirstChild(n); return v and tonumber(v.Value) or 0 end
    local function evolved() local d = pdata(); local r = d and d:FindFirstChild("Race"); return r ~= nil and r:FindFirstChild("Evolved") ~= nil end
    local function pos3(x, y, z) return Vector3.new(x, y, z) end
    local function near(v, r) local _, hrp = getChar(); return hrp and (hrp.Position - v).Magnitude <= (r or 8) end
    local function goTo(v, up) flyTo(CFrame.new(v.X, v.Y + (up or 0), v.Z)) end
    local function hasTool(n) return findToolByName(string.lower(n)) ~= nil end
    local function equipByName(n)
        local t, eq = findToolByName(string.lower(n))
        if t and not eq then local _, _, hum = getChar(); if hum then hum:EquipTool(t) end end
        return t
    end
    local function fire(cd) if cd and type(fireclickdetector) == "function" then pcall(fireclickdetector, cd) end end

    -- ===== servidor com Cursed Captain (API do Conte_do_colado) =====
    local API_URL, SECRET = "https://api.quantumonyx.cc", "QnTmOnyX"
    local ALPHA = "kQ9mZ2xW7nR4vB1jY6tF3hD8pL5cG0sA"
    local function decodeJobId(arg)
        local s = arg:gsub("^%.", ""):gsub("%.$", "")
        local t, n = {}, 0
        for i = 1, #s do n += 1; if n % 5 ~= 0 then t[#t + 1] = s:sub(i, i) end end
        local s2 = table.concat(t)
        local out, a, b = {}, 1, 1
        local function f3(x, y) return (x - SECRET:byte((y - 1) % #SECRET + 1) - y) % 32 end
        while a <= #s2 do
            local i1, i2 = ALPHA:find(s2:sub(a, a), 1, true), ALPHA:find(s2:sub(a + 1, a + 1), 1, true)
            if not i1 or not i2 then return "" end
            out[#out + 1] = string.char(f3(i1 - 1, b) + f3(i2 - 1, b + 100) * 32)
            a += 2; b += 1
        end
        return table.concat(out)
    end
    local reqf = (syn and syn.request) or http_request or (http and http.request) or request or httprequest
    local joining, lastJoin = false, 0
    -- v51: nao trava mais parado. Pedido HTTP com limite de tempo, no maximo 3 tentativas da lista da API, e depois troca de servidor direto.
    local function bossHere(bossName)
        return findEnemy({ (bossName:gsub("(%l)(%u)", "%1 %2")) }) ~= nil
    end
    function R.joinBoss(bossName)
        return AFL.apiJoin(bossName, function() return bossHere(bossName) end, bossName)
    end

    -- ===== Ghost Ship =====
    local SHIP = pos3(923.213, 125.39765, 32852.832)
    local SHIP_MOBS = { "Ship Deckhand", "Ship Engineer", "Ship Steward", "Ship Officer" }
    local enterAt = 0
    local function insideShip() local _, hrp = getChar(); return hrp and (hrp.Position - SHIP).Magnitude <= 1000 end
    local function enterShip()
        if insideShip() then return true end
        if os.clock() - enterAt > 4 then enterAt = os.clock(); inv("requestEntrance", SHIP) end
        return false
    end
    local function fightNames(names, label)
        local e = findEnemy(names)
        if e then note(label .. ": " .. e.Name); fightEnemy(e, { e.Name }, true); return true end
        return false
    end

    -- ===== Reroll (Banana/NightRace): BlackbeardReward Reroll 1 -> 2 (3000 fragments) =====
    local lastReroll = 0
    local function stepReroll()
        if not Config.RaceReroll then return false end
        local want = tostring(Config.RaceTarget)
        if raceVal() == want then note("Reroll: already " .. want); return false end
        if dval("Fragments") < 3000 then note("Reroll: need 3000 fragments"); return false end
        if os.clock() - lastReroll < 3 then return true end
        lastReroll = os.clock()
        note("Rerolling race (now " .. raceVal() .. " -> " .. want .. ")")
        inv("BlackbeardReward", "Reroll", "1")
        inv("BlackbeardReward", "Reroll", "2")
        return true
    end

    local function toSea2()
        if getSea() == 2 then return true end
        note("Traveling to the Second Sea")
        if os.clock() - (R.travelAt or 0) > 15 then R.travelAt = os.clock(); inv("TravelDressrosa") end
        return false
    end

    -- ===== Auto Fully Ghoul: 100 Ectoplasm + Hellfire Torch (Cursed Captain) -> Ectoplasm Buy 4 =====
    -- v24: cada etapa vira texto no cartao da aba Auto Fully (R.st.ghoul) e a troca de servidor e o padrao
    R.st = {}
    local function gnote(state, txt, pill)
        R.st.ghoul = { state = state, msg = txt, pill = pill or "WORKING" }
        note("Ghoul: " .. txt)
    end
    local BUY_POS = pos3(921, 125, 33453)
    local lastChange = 0
    local function stepGhoul()
        if not Config.RaceGhoul then return false end
        if raceVal() == "Ghoul" then gnote("ok", "You are a Ghoul already", "DONE"); return false end
        if not toSea2() then gnote("info", "Travelling to the Second Sea", "TRAVEL"); return true end
        if os.clock() - lastChange > 12 then lastChange = os.clock(); inv("Ectoplasm", "Change", 4) end
        local ecto = invCount("Ectoplasm")
        if ecto < 100 then
            if not enterShip() then gnote("info", "Entering the Ghost Ship", "SHIP"); return true end
            gnote("info", string.format("Ectoplasm %d/100 (Ghost Ship mobs)", ecto), "ECTOPLASM")
            if fightNames(SHIP_MOBS, string.format("Ghoul: Ectoplasm %d/100", ecto)) then R.noMobsAt = nil; return true end
            gnote("warn", string.format("Ectoplasm %d/100: waiting for ship mobs", ecto), "WAITING")
            goTo(SHIP, 30)
            -- sem mobs do navio por ~25s e Server Hop ligado: troca de servidor (antes ficava parado para sempre)
            R.noMobsAt = R.noMobsAt or os.clock()
            if Config.RaceGhoulHop and getSea() == 2 and os.clock() - R.noMobsAt > 25 and not AFL.Hop.active then
                gnote("info", "No ship mobs here: changing server", "HOP")
                AFL.hopRequest("no ship mobs", function() return findEnemy(SHIP_MOBS) ~= nil end)
            end
            return true
        end
        R.noMobsAt = nil
        if hasTool("Hellfire Torch") then
            if near(BUY_POS, 10) then
                gnote("ok", "Buying the race with the Hellfire Torch", "BUYING")
                inv("Ectoplasm", "BuyCheck", 4); task.wait(0.2); inv("Ectoplasm", "Buy", 4)
            else
                gnote("info", "Going to the Ectoplasm shop", "TORCH")
                goTo(BUY_POS)
            end
            return true
        end
        local cap = findEnemy({ "Cursed Captain" })
        if cap then
            if not insideShip() and not enterShip() then gnote("info", "Entering the Ghost Ship", "SHIP"); return true end
            gnote("ok", "Killing the Cursed Captain (Hellfire Torch)", "BOSS"); fightEnemy(cap, { cap.Name }, false); return true
        end
        if Config.RaceGhoulHop then
            gnote("info", "No Cursed Captain here: searching a server that has one", "HOP")
            if not insideShip() then enterShip() end
            R.joinBoss("CursedCaptain")
            return true
        end
        gnote("warn", "The Cursed Captain is not in this server (turn on Ghoul: Server Hop)", "WAITING")
        return false
    end

    -- ===== Auto Fully Cyborg: 2500 frags, Fist of Darkness / Core Brain / Microchip / Order =====
    local MACHINE = pos3(-5544, 229, -5938)
    local function machine()
        local m = workspace:FindFirstChild("Map"); local ci = m and m:FindFirstChild("CircleIsland")
        local rs = ci and ci:FindFirstChild("RaidSummon"); local b = rs and rs:FindFirstChild("Button")
        local mn = b and b:FindFirstChild("Main")
        return mn, mn and mn:FindFirstChildOfClass("ClickDetector"), ci
    end
    local function useMachine(label)
        local _, cd = machine()
        if not near(MACHINE, 8) then note(label .. ": going to the machine"); goTo(MACHINE); return true end
        fire(cd); task.wait(0.6); return true
    end
    local function labUnlocked(ci)
        local d = ci and ci:FindFirstChild("SecretLabDoors"); local c = d and d:FindFirstChild("colormodel")
        return c and c.Color.G > c.Color.R
    end
    local ORDER_AT = pos3(-6300, 16, -4997)
    local chipAt = 0
    local function cnote(state, txt, pill)
        R.st.cyborg = { state = state, msg = txt, pill = pill or "WORKING" }
        note("Cyborg: " .. txt)
    end
    local function stepCyborg()
        if not Config.RaceCyborg then return false end
        if raceVal() == "Cyborg" then cnote("ok", "You are a Cyborg already", "DONE"); return false end
        if not toSea2() then cnote("info", "Travelling to the Second Sea", "TRAVEL"); return true end
        local chk = inv("CyborgTrainer", "Check")
        local mn, _, ci = machine()
        if chk == 1 or chk == true or (mn and not mn.CanCollide) then
            if dval("Fragments") >= 2500 then
                cnote("ok", "Buying the race (2500 fragments)", "BUYING"); inv("CyborgTrainer", "Buy"); task.wait(1); return true
            end
            cnote("warn", string.format("Need 2500 fragments (you have %d)", dval("Fragments")), "FRAGMENTS")
            return false
        end
        if hasTool("Core Brain") then equipByName("Core Brain"); cnote("ok", "Putting the Core Brain in the machine", "CORE BRAIN"); return useMachine("Cyborg (Core Brain)") end
        local order = findEnemy({ "Order" })
        if order then chipAt = os.clock(); cnote("ok", "Killing Order (drops the Core Brain)", "BOSS"); fightEnemy(order, { "Order" }, false); return true end
        if os.clock() - chipAt < 25 then
            cnote("info", "Microchip used: waiting for Order to spawn", "WAITING")
            goTo(ORDER_AT, 40)
            return true
        end
        if hasTool("Microchip") then
            equipByName("Microchip"); chipAt = os.clock()
            cnote("ok", "Putting the Microchip in the machine", "MICROCHIP"); return useMachine("Cyborg (Microchip)")
        end
        if not labUnlocked(ci) then
            if hasTool("Fist of Darkness") then equipByName("Fist of Darkness"); cnote("ok", "Opening the lab with the Fist of Darkness", "FIST"); return useMachine("Cyborg (Fist of Darkness)") end
            -- v78: pedido do usuario - antes de catar bau, se "Cyborg: Chest Server Hop" estiver ligado, so farma
            -- bau num servidor com 4h+ de uptime (servidor "velho" = mais tempo acumulando baus sem terem sido
            -- catados por ninguem, ent mais chance de achar o Fist of Darkness rapido). workspace.DistributedGameTime
            -- e o mesmo valor que ja aparece em "Server Uptime" no painel Diagnostics - se o servidor atual for mais
            -- novo que isso, pede hop (AFL.hopRequest, mesmo sistema do Auto Bounty) em vez de catar bau nesse servidor
            -- "novo"; so entra no loop normal de baus quando o servidor atual ja tiver 4h+.
            if Config.RaceCyborgHop and workspace.DistributedGameTime < 4 * 3600 then
                cnote("info", "Server with less than 4h uptime: hopping for an older server (more chests)", "HOP 4H+")
                AFL.hopRequest("Cyborg: server com menos de 4h de uptime", function() return not (Config.RaceCyborg and Config.RaceCyborgHop) end)
                return true
            end
            cnote("info", "Collecting chests for the Fist of Darkness", "CHESTS")
            local ok, busy = pcall(AFL.chestStep, { hop = Config.RaceCyborgHop and true or false, count = tonumber(Config.FullChestCount) or 20 })
            if not ok then AFL.logErr("Races chest", busy); return false end
            return busy and true or false
        end
        if dval("Fragments") >= 1000 then
            cnote("ok", "Buying a Microchip (1000 fragments)", "BUYING"); inv("BlackbeardReward", "Microchip", "2"); task.wait(1); return true
        end
        cnote("warn", string.format("Need 1000 fragments for the Microchip (you have %d)", dval("Fragments")), "FRAGMENTS")
        return false
    end

    -- ===== V2 (Alchemist, Second Sea) =====
    local ALCH = pos3(-2777, 73, -3570)
    local function flowerPart(n) local p = workspace:FindFirstChild(n); return (p and p:IsA("BasePart") and p.Transparency ~= 1) and p or nil end
    local function stepV2()
        if not Config.RaceV2 or evolved() then return false end
        if raceVal() == "Draco" then note("V2: Draco cannot use the Alchemist"); return false end
        if not toSea2() then return true end
        if dval("Beli") < 500000 then note("V2: need 500,000 Beli"); return false end
        local a = inv("Alchemist", "1")
        if a == 0 or a == 2 then
            if near(ALCH, 6) then note("V2: talking to the Alchemist"); inv("Alchemist", a == 0 and "2" or "3"); task.wait(1)
            else note("V2: going to the Alchemist"); goTo(ALCH) end
            return true
        elseif a == 1 then
            for i = 1, 2 do
                local n = "Flower " .. i
                if not hasTool(n) then
                    local p = flowerPart("Flower" .. i)
                    if p then note("V2: collecting " .. n); flyTo(p.CFrame); return true end
                end
            end
            if not hasTool("Flower 3") then
                if not insideShip() and not enterShip() then note("V2: entering the Ghost Ship (yellow flower)"); return true end
                if fightNames(SHIP_MOBS, "V2: yellow flower") then return true end
            end
            if not (hasTool("Flower 1") and hasTool("Flower 2") and hasTool("Flower 3")) then
                note("V2: waiting for night (flowers)"); goTo(pos3(-382, 73, 290)); return true
            end
        end
        return false
    end

    -- ===== V3 (Wenlocktoad) =====
    local WEN = pos3(-1992, 125, -73)
    local function pvpTarget()
        local _, hrp = getChar(); if not hrp then return end
        local best, bd, mylvl = nil, math.huge, dval("Level")
        local sky = raceVal() == "Skypiea"
        for _, pl in ipairs(PlayersSvc:GetPlayers()) do
            if pl ~= Player and not pl:GetAttribute("IslandRaiding") and not pl:GetAttribute("PvpDisabled") then
                local pd = pl:FindFirstChild("Data")
                local ok = true
                if sky then local r = pd and pd:FindFirstChild("Race"); ok = r and tostring(r.Value) == "Skypiea" end
                local lv = pd and pd:FindFirstChild("Level")
                if ok and lv and math.abs(lv.Value - mylvl) < 500 then
                    local c = pl.Character; local h = c and c:FindFirstChild("HumanoidRootPart"); local hu = c and c:FindFirstChildOfClass("Humanoid")
                    if h and hu and hu.Health > 0 then
                        local d = (h.Position - hrp.Position).Magnitude
                        if d < bd then best, bd = c, d end
                    end
                end
            end
        end
        return best
    end
    local function stepV3()
        if not Config.RaceV3 or not evolved() then return false end
        if inv("Wenlocktoad") ~= nil then note("V3: already unlocked"); return false end
        if dval("Level") < 1000 then note("V3: need level 1000"); return false end
        if dval("Beli") < 2000000 then note("V3: need 2,000,000 Beli"); return false end
        if not toSea2() then return true end
        local w = inv("Wenlocktoad", "1")
        if w == 0 or w == 2 then
            if near(WEN, 6) then note("V3: talking to Wenlocktoad"); inv("Wenlocktoad", w == 0 and "2" or "3"); task.wait(1)
            else note("V3: going to Wenlocktoad"); goTo(WEN) end
            return true
        elseif w == 1 then
            local race = raceVal()
            if race == "Mink" then
                local e = AFL.feat and AFL.feat.Chest
                if e then
                    note("V3 (Mink): opening chests")
                    local ok, busy = pcall(e.run)
                    return (ok and busy) and true or false
                end
            elseif race == "Human" then
                if fightNames({ "Diamond", "Orbitus", "Jeremy" }, "V3 (Human)") then return true end
                note("V3 (Human): Diamond / Orbitus / Jeremy not spawned"); goTo(pos3(-382, 73, 290)); return true
            elseif race == "Ghoul" or race == "Skypiea" then
                if not Config.RaceV3Pvp then note("V3 (" .. race .. "): needs PvP, turn on 'Allow PvP for V3'"); return false end
                local c = pvpTarget()
                if c then note("V3 (" .. race .. "): hunting " .. c.Name); fightEnemy(c, { c.Name }, false); return true end
                note("V3 (" .. race .. "): no valid player found"); return false
            else
                note("V3 (" .. race .. "): no automation for this race yet"); return false
            end
        end
        return false
    end

    -- ===== V4: Pull Lever (Fully) + Gear + Activate =====
    local LEVER, LDOOR, GREAT = pos3(28575, 14937, 72), pos3(28610, 14897, 106), pos3(2956, 2282, -7216)
    local function stepLever()
        if not Config.RaceLever then return false end
        local p = inv("RaceV4Progress", "Check")
        if p == 1 then note("V4: beginning"); inv("RaceV4Progress", "Begin"); return true end
        if p == 2 then
            if not near(LDOOR, 500) then note("V4: entering the temple"); inv("requestEntrance", pos3(28283, 14897, 105)); goTo(LDOOR); return true end
            if near(LDOOR, 20) then
                task.wait(1); inv("RaceV4Progress", "TeleportBack"); task.wait(0.5); goTo(GREAT); inv("RaceV4Progress", "Teleport")
            else goTo(LDOOR) end
            note("V4: progressing"); return true
        end
        if p == 3 then note("V4: continuing"); inv("RaceV4Progress", "Continue"); return true end
        local map = workspace:FindFirstChild("Map")
        local mystic = map and map:FindFirstChild("MysticIsland")
        local door = inv("CheckTempleDoor")
        local light = game:GetService("Lighting")
        if mystic and not door then
            local ct = light.ClockTime
            if ct > 16 or ct < 5 then
                local c = mystic:FindFirstChild("Center")
                if c then
                    local top = pos3(c.Position.X, 500, c.Position.Z)
                    local gear
                    for _, ch in ipairs(mystic:GetChildren()) do if ch.Name == "Part" and ch:IsA("MeshPart") and ch.Transparency == 0 then gear = ch end end
                    if gear then note("V4: going to the Blue Gear"); flyTo(gear.CFrame)
                    else
                        note("V4: looking at the moon"); goTo(top)
                        if near(top, 200) then
                            pcall(function()
                                local cam = workspace.CurrentCamera
                                cam.CFrame = CFrame.lookAt(cam.CFrame.Position, cam.CFrame.Position + light:GetMoonDirection() * 100)
                            end)
                            task.wait(0.5)
                            pcall(function() RS.Remotes.CommE:FireServer("ActivateAbility") end)
                        end
                    end
                    return true
                end
            end
            note("V4: waiting for night (Mirage)"); return false
        elseif door then
            if not near(LEVER, 10) then note("V4: going to the lever"); goTo(LEVER); return true end
            pcall(function() fireproximityprompt(map["Temple of Time"].Lever.Prompt.ProximityPrompt, math.huge) end)
            note("V4: pulling the lever"); return true
        end
        note("V4: Mirage Island not found"); return false
    end

    -- ===== Gear automático (Ancient Clock) =====
    local gearAt = 0
    local GEARS = { {}, { "Gear1" }, { "Gear2", "Omega" }, { "Gear2", "Alpha" }, { "Gear2", true }, { "Gear2", false }, { "Gear3", "Alpha" }, { "Gear3", "Omega" },
        { "Gear3", true }, { "Gear3", false }, { "Gear4", "Alpha" }, { "Gear4", true }, { "Gear4", false }, { "Gear5", "Default" }, { "Gear5", true }, { "Gear5", false } }
    local function chooseGear()
        if os.clock() - gearAt < 20 then return end
        gearAt = os.clock()
        local res = inv("TempleClock", "Check")
        if type(res) == "table" and res.HadPoint ~= true then return end
        local g4 = (type(res) == "table" and res.RaceDetails and res.RaceDetails.B == 2) and "Omega" or "Alpha"
        for _, a in ipairs(GEARS) do
            local args = { "TempleClock", "SpendPoint", table.unpack(a) }
            if a[1] == "Gear4" and a[2] == "Alpha" then args[4] = g4 end
            pcall(invoke, table.unpack(args))
        end
    end
    -- ativa a V4 quando a energia está cheia (Quantum)
    local function activateV4()
        local c = Player.Character
        local en, tr = c and c:FindFirstChild("RaceEnergy"), c and c:FindFirstChild("RaceTransformed")
        if en and tr and en.Value >= 1 and not tr.Value then
            pcall(function() Player.Backpack.Awakening.RemoteFunction:InvokeServer({ true }) end)
            return true
        end
    end
    function R.activateNow() return activateV4() end

    -- ===== passo principal (chamado pelo loop em ordem de prioridade) =====
    function R.step()
        if getChar() == nil then return false end
        local order = { stepReroll, stepGhoul, stepCyborg, stepV2, stepV3, stepLever }
        for _, f in ipairs(order) do
            local ok, busy = pcall(f)
            if not ok then AFL.logErr("Races", busy)
            elseif busy then return true end
        end
        return false
    end
    function R.listed()
        return Config.RaceReroll or Config.RaceGhoul or Config.RaceCyborg or Config.RaceV2 or Config.RaceV3 or Config.RaceLever
    end
    task.spawn(function()
        while Alive do
            task.wait(2)
            if Config.RaceGear then pcall(chooseGear) end
            if Config.RaceV4Auto then pcall(activateV4) end
        end
    end)

    -- ===== UI =====
    local function tog(id, title, desc)
        T:AddToggle(id, { Title = title, Description = desc, Default = Config[id] and true or false, NoBadge = string.find(id, "Hop$") ~= nil }):OnChanged(function(v) Config[id] = v; persist() end)
    end
    T:AddSection("Race Info")
    local info = T:AddParagraph({ Title = "Race", Content = "Checking..." })
    local info2 = T:AddParagraph({ Title = "Resources", Content = "Checking..." })
    task.spawn(function()
        while Alive do
            pcall(function()
                local c = Player.Character
                local en, tr = c and c:FindFirstChild("RaceEnergy"), c and c:FindFirstChild("RaceTransformed")
                info:SetDesc(string.format("%s (%s) | V4 energy: %s | Transformed: %s\nStatus: %s", raceVal(), evolved() and "V2+" or "V1",
                    en and string.format("%d%%", math.floor(en.Value * 100)) or "-", tr and tostring(tr.Value) or "-", R.status))
                info2:SetDesc(string.format("Fragments: %d | Beli: %d | Level: %d | Ectoplasm: %d", dval("Fragments"), dval("Beli"), dval("Level"), invCount("Ectoplasm")))
            end)
            task.wait(1.5)
        end
    end)

    T:AddSection("Ghoul")
    local gCard = T:AddStatus({ Title = "Ghoul Progress", Content = "Checking...", Height = 58 })
    tog("RaceGhoul", "Auto Fully Ghoul", "Ectoplasm > Cursed Captain > Hellfire Torch > buys Ghoul")
    tog("RaceGhoulHop", "")

    T:AddSection("Cyborg")
    local cCard = T:AddStatus({ Title = "Cyborg Progress", Content = "Checking...", Height = 58 })
    tog("RaceCyborg", "Auto Fully Cyborg", "20 chests on every Sea 2 island > Fist of Darkness > Law raid > Core Brain > buys")
    tog("RaceCyborgHop", "Cyborg: Chest Server Hop", "Hops to servers with 4h+ uptime (more chests) and keeps hopping on empty chests, until the Fist of Darkness drops")
    task.spawn(function()
        task.wait(0.6)
        while Alive do
            if T:IsVisible() then
                pcall(function()
                    for _, c in ipairs({ { gCard, "ghoul", "RaceGhoul" }, { cCard, "cyborg", "RaceCyborg" } }) do
                        local st = R.st[c[2]]
                        if not Config[c[3]] then c[1]:Set("off", nil, "Off. Turn it on below and it does everything by itself", "OFF")
                        elseif not st then c[1]:Set("info", nil, "Waiting for its turn", "READY")
                        else c[1]:Set(st.state, nil, st.msg, st.pill) end
                    end
                end)
            end
            task.wait(1.2)
        end
    end)

    T:AddSection("Upgrade Race")
    tog("RaceV2", "Auto Upgrade Race V2", "Alchemist quest: 3 flowers (night), needs 500k Beli. Second Sea")
    tog("RaceV3", "Auto Upgrade Race V3", "Wenlocktoad quest (level 1000, 2M Beli). Mink/Human automatic; Ghoul/Sky need PvP")
    tog("RaceV3Pvp", "Allow PvP for V3", "Ghoul / Skypiea V3 require hunting players")

    T:AddSection("Reroll Race")
    local RACES = { "Human", "Skypiea", "Fishman", "Mink", "Cyborg", "Ghoul" }
    local ri = 1; for i, n in ipairs(RACES) do if n == Config.RaceTarget then ri = i end end
    T:AddDropdown("RaceTarget", { Title = "Select Race", Description = "Race you want (each reroll costs 3000 fragments)", Values = RACES, Default = ri })
        :OnChanged(function(v) Config.RaceTarget = v; persist() end)
    tog("RaceReroll", "Auto Reroll Race", "Rerolls until you get the selected race")

    T:AddSection("Race V4")
    T:AddToggle("AutoV3", { Title = "Auto Activate Race V3", Default = Config.AutoV3 }):OnChanged(function(v) Config.AutoV3 = v; persist() end)
    T:AddToggle("AutoV4", { Title = "Auto Activate Race V4", Default = Config.AutoV4 }):OnChanged(function(v) Config.AutoV4 = v; persist() end)
    tog("RaceV4Auto", "Auto Activate V4 (energy full)", "Uses the awakening as soon as the race energy is full")
    tog("RaceLever", "Auto Fully V4 (Pull Lever)", "Finds the Blue Gear on Mirage, opens the temple and pulls the lever")
    tog("RaceGear", "Auto Choose Gear", "Spends the gear point in the Ancient Clock after the trial")
    T:AddButton({ Title = "Activate V4 Now", Description = "Only works with the energy full", Callback = function() R.activateNow() end })
    local AREAS = {
        { "Race Door", nil }, { "Top of Great Tree", pos3(2948, 2282, -7214) }, { "Temple of Time", pos3(28286, 14895, 103) },
        { "Ancient One", pos3(28982, 14888, -120) }, { "Lever Pull", LEVER }, { "Safe Zone", pos3(28273, 14897, 157) },
        { "PvP Zone", pos3(28767, 14967, -164) }, { "Clock", pos3(29552, 15069, -86) } }
    local DOORS = { Fishman = pos3(28224, 14889, -210), Human = pos3(29237, 14889, -207), Cyborg = pos3(28492, 14901, -426),
        Skypiea = pos3(28967, 14918, 234), Ghoul = pos3(28672, 14889, 454), Mink = pos3(29020, 14889, -379) }
    T:AddSection("Trial Areas")
    for _, a in ipairs(AREAS) do
        T:AddButton({ Title = "Teleport: " .. a[1], Callback = function()
            local p = a[2] or DOORS[raceVal()]
            if p then AFL.tpTravel(p, a[1]) end
        end })
    end
end)()




]===] end
    PC.src["dungeon"] = function() return [===[
local __E = ...
local AFL = __E.AFL
local Config, Connections, Core, Diag, Player, State, Tabs = __E.Config, __E.Connections, __E.Core, __E.Diag, __E.Player, __E.State, __E.Tabs
local persist = __E.persist
local Players = game:GetService("Players")
local Alive = true
AFL.onUnload(function() Alive = false end);
-- ---------- Dungeons ----------
-- Base: NightDungeon (andar/lutar/escolher cartas dentro da dungeon) + Banana Hub (entrar no pad, dificuldade, min. de jogadores, conta que inicia).
(function()
    local T = Tabs.Dungeons
    local RS = game:GetService("ReplicatedStorage")
    local TweenSvc = game:GetService("TweenService")
    local PlayersSvc = game:GetService("Players")
    local RunSvc = game:GetService("RunService")
    local D = {}
    AFL.Dun = D
    local S = { stage = "Idle", floor = 0, maxFloor = 0, dead = 0, total = 0, left = 0, runs = 0, kills = 0, energy = 0, target = "-", buffs = {} }
    D.s = S
    local CFG = { hover = 60, kill = 20, bossKill = 24, speed = 200, arrive = 14, jump = 400, rescue = 6000, hit = 60,
        atkDelay = 0.07, buffDelay = 0.45, floorH = 90, door = 30, propHP = 5000, propR = 700, stall = 5 }
    local function cfgv(k, d) if Config[k] == nil then Config[k] = d end end
    cfgv("DunDiff", "Normal"); cfgv("DunMin", 1); cfgv("DunWeapon", "Melee"); cfgv("DunCost", 10); cfgv("DunBring", true); cfgv("DunBringN", 6)
    cfgv("DunCardBlock", {})   -- v64: cartas que o Auto Pick Card nunca deve escolher

    local function char() local c = Player.Character; return (c and c.Parent and c:FindFirstChild("HumanoidRootPart")) and c or nil end
    local function hrpf() local c = char(); return c and c:FindFirstChild("HumanoidRootPart") end
    local function humf() local c = char(); return c and c:FindFirstChildOfClass("Humanoid") end
    local function inHub() return workspace:GetAttribute("IsDungeonHub") == true or D.padsFolder() ~= nil end
    local function inRun() return workspace:GetAttribute("IsDungeonInstance") == true or Player:GetAttribute("ExplorerGUID") ~= nil end
    function D.padsFolder()
        local map = workspace:FindFirstChild("Map")
        if not map then return nil end
        local hub = map:FindFirstChild("Simulation Hub")
        return (hub and hub:FindFirstChild("Pads")) or map:FindFirstChild("Pads")
    end
    local function stage(t) S.stage = t; State.Mode, State.Text = "Auto Dungeon", t; Diag.dungeon = t end

    -- v42: acha o Dungeon Hub no mapa (mesmo longe/streamed) para voar ate ele
    local hubCache, hubAt = nil, 0
    function D.hubTarget()
        if hubCache and hubCache.Parent and os.clock() - hubAt < 8 then return hubCache end
        hubAt = os.clock(); hubCache = nil
        local map = workspace:FindFirstChild("Map")
        local m = map and map:FindFirstChild("Simulation Hub")
        if m then hubCache = m; return m end
        local best
        for _, o in ipairs(workspace:GetDescendants()) do
            if (o:IsA("Model") or o:IsA("BasePart")) and not (Player.Character and o:IsDescendantOf(Player.Character)) then
                local n = o.Name:lower()
                if (n:find("dungeon") and (n:find("hub") or n:find("entrance") or n:find("portal") or n:find("teleport")))
                    or n:find("simulation hub") then
                    if not (map and map:FindFirstChild("Dungeon") and o:IsDescendantOf(map.Dungeon)) then best = o; break end
                end
            end
        end
        hubCache = best
        return best
    end
    local function hubPos(o)
        if not o then return nil end
        local ok, cf = pcall(function() return o:IsA("Model") and o:GetPivot() or o.CFrame end)
        return ok and cf or nil
    end

    -- ===== movimento (hover alto + tween), igual ao NightDungeon =====
    local target, tween, tgoal, hb, nc, lastPos, rescueUntil, hover = nil, nil, nil, nil, nil, nil, 0, false
    local function cancelTween() if tween then pcall(function() tween:Cancel() end); tween = nil end end
    local function velocity(on)
        local c = char(); if not c then return end
        local head = c:FindFirstChild("Head") or c:FindFirstChild("HumanoidRootPart")
        if not head then return end
        local bv = head:FindFirstChild("MHDunVel")
        if on and not bv then
            bv = Instance.new("BodyVelocity")
            bv.Name, bv.MaxForce, bv.Velocity, bv.P = "MHDunVel", Vector3.new(40000, 40000, 40000), Vector3.zero, 1500
            bv.Parent = head
        elseif not on and bv then bv:Destroy() end
    end
    local function noclip(on)
        if on and not nc then
            nc = RunSvc.Stepped:Connect(function()
                local c = char(); if not c then return end
                for _, p in ipairs(c:GetDescendants()) do if p:IsA("BasePart") and p.CanCollide then p.CanCollide = false end end
            end)
        elseif not on and nc then nc:Disconnect(); nc = nil end
    end
    local function stepTo(cf)
        local hrp, hum = hrpf(), humf()
        if not hrp or not hum or hum.Health <= 0 then cancelTween(); return false end
        if hum.Sit then hum.Sit = false end
        local dist = (cf.Position - hrp.Position).Magnitude
        if dist <= CFG.arrive then cancelTween(); return true end
        if tween and tgoal and (tgoal.Position - cf.Position).Magnitude < 6 and tween.PlaybackState == Enum.PlaybackState.Playing then return false end
        local sp = os.clock() < rescueUntil and CFG.rescue or (tonumber(Config.TweenSpeed) or CFG.speed)
        cancelTween()
        tgoal = cf
        tween = TweenSvc:Create(hrp, TweenInfo.new(math.max(dist / sp, 0.05), Enum.EasingStyle.Linear), { CFrame = cf })
        tween:Play()
        return false
    end
    local function heartbeat(on)
        if on and not hb then
            lastPos = nil
            hb = RunSvc.Heartbeat:Connect(function()
                if not target then return end
                local hrp, hum = hrpf(), humf()
                if not hrp or not hum or hum.Health <= 0 then lastPos = nil; return end
                local pos = hrp.Position
                if lastPos and (pos - lastPos).Magnitude > CFG.jump then
                    cancelTween()
                    target = CFrame.new(pos.X, pos.Y + CFG.hover, pos.Z)
                    lastPos = pos
                    return
                end
                lastPos = pos
                if hrp.AssemblyAngularVelocity.Magnitude > 0.05 then hrp.AssemblyAngularVelocity = Vector3.zero end
                if hum:GetState() ~= Enum.HumanoidStateType.Physics then hum:ChangeState(Enum.HumanoidStateType.Physics) end
                if hum.PlatformStand then hum.PlatformStand = false end
                velocity(true)
                stepTo(target)
            end)
        elseif not on and hb then hb:Disconnect(); hb = nil; cancelTween(); lastPos = nil end
    end
    local function goto_(cf)
        local hrp, hum = hrpf(), humf()
        if not hrp or not hum or hum.Health <= 0 then cancelTween(); return false end
        noclip(true); velocity(true); hover = false
        if not target or (target.Position - cf.Position).Magnitude > 1 then target = cf end
        heartbeat(true)
        return (cf.Position - hrp.Position).Magnitude <= CFG.arrive
    end
    local function hoverHigh(force)
        local hrp = hrpf(); if not hrp then return end
        if hover and target and hb and not force then noclip(true); velocity(true); return end
        cancelTween()
        local p = hrp.Position
        if p.Y < -100 then p = D.lastGood or p end
        target = CFrame.new(p.X, p.Y + CFG.hover, p.Z)
        noclip(true); velocity(true); heartbeat(true)
        hover = true
        stage("Hovering up high")
    end
    function D.halt()
        heartbeat(false); noclip(false); velocity(false)
        target, hover, D.active, D.atk = nil, false, false, false
    end

    -- ===== inimigos =====
    local folders, foldersAt, deepAt = {}, 0, 0
    local function scanFolders()
        if os.clock() - foldersAt < 3 and #folders > 0 then return end
        foldersAt = os.clock()
        local list, seen = {}, {}
        local function add(f) if f and f.Parent and not seen[f] then seen[f] = true; list[#list + 1] = f end end
        add(workspace:FindFirstChild("Enemies"))
        for _, ch in ipairs(workspace:GetChildren()) do
            if ch:IsA("Folder") or ch:IsA("Model") then
                local n = ch.Name
                if n:find("Enem") or n:find("Mob") or n:find("Monster") then add(ch) end
            end
        end
        for _, f in ipairs(folders) do add(f) end
        if os.clock() - deepAt > 12 then
            deepAt = os.clock()
            local map = workspace:FindFirstChild("Map")
            local dg = map and map:FindFirstChild("Dungeon")
            if dg then
                for _, fl in ipairs(dg:GetChildren()) do
                    for _, d in ipairs(fl:GetDescendants()) do
                        if d:IsA("Humanoid") and d.Parent and d.Parent:IsA("Model") then add(d.Parent.Parent) end
                    end
                end
            end
        end
        folders = list
    end
    local function alive(m)
        if not m or not m.Parent or m:FindFirstChild("VehicleSeat") then return false end
        local h = m:FindFirstChild("Humanoid")
        return h and h.Health > 0 and m:FindFirstChild("HumanoidRootPart") ~= nil
    end
    local ALLYATTR = { "Ally", "IsAlly", "Friendly", "IsFriendly", "Summoned", "IsSummon", "IsSummoned", "PlayerOwned", "IsPlayerOwned", "Minion", "IsMinion", "IsShadow" }
    local OWNKEYS = { "Owner", "OwnerId", "OwnerUserId", "OwnerName", "Master", "Summoner", "SummonedBy" }
    -- aliado do jogador (ex.: o Shadow que a carta da dungeon invoca): nunca e alvo nem e puxado
    -- v60 fix: so comparava com o NOME DO JOGADOR LOCAL (me) - a sombra de um ALIADO (outro player na sala) tinha nome
    -- diferente do seu e passava reto por essas checagens (so os padroes genericos "shadow"/"ally"/"summon" pegavam ela
    -- as vezes). Agora compara contra TODOS os jogadores da sala, nao so voce.
    local function isAllyModel(m, me)
        local n = string.lower(m.Name)
        if n == "shadow" or string.find(n, "^shadow ?ally") or string.find(n, "^shadow ?clone") or string.find(n, "shadowally", 1, true)
            or string.find(n, "%f[%a]ally%f[%A]") or string.find(n, "%f[%a]summon") then return true end
        for _, p in ipairs(PlayersSvc:GetPlayers()) do
            local ln = string.lower(p.Name)
            if n == ln or (#ln >= 5 and string.find(n, ln, 1, true)) then return true end
            local ldn = p.DisplayName ~= "" and string.lower(p.DisplayName) or nil
            if ldn and (#ldn >= 5 and string.find(n, ldn, 1, true)) then return true end
        end
        for _, a in ipairs(ALLYATTR) do if m:GetAttribute(a) == true then return true end end
        for _, a in ipairs(OWNKEYS) do
            local v = m:GetAttribute(a)
            if v ~= nil then
                for _, p in ipairs(PlayersSvc:GetPlayers()) do
                    if v == p.UserId or v == p.Name or v == p.DisplayName then return true end
                end
            end
            local o = m:FindFirstChild(a)
            if o and o:IsA("ObjectValue") then
                for _, p in ipairs(PlayersSvc:GetPlayers()) do
                    if o.Value == p or (p.Character ~= nil and o.Value == p.Character) then return true end
                end
            end
        end
        return false
    end
    local mobCache, mobAt = {}, 0
    local function mobs()
        if os.clock() - mobAt < 0.3 then return mobCache end
        mobAt = os.clock()
        scanFolders()
        local out, seen = {}, {}
        for _, f in ipairs(folders) do
            if f.Parent then
                for _, m in ipairs(f:GetChildren()) do
                    if m:IsA("Model") and not seen[m] and alive(m) and not PlayersSvc:GetPlayerFromCharacter(m) and not isAllyModel(m, Player) then seen[m] = true; out[#out + 1] = m end
                end
            end
        end
        mobCache = out
        return out
    end
    local function isBoss(m)
        if m:GetAttribute("IsBoss") or m:GetAttribute("Boss") or m.Name:find("Boss") or m.Name:find("Zero") then return true end
        local h = m:FindFirstChild("Humanoid")
        return h ~= nil and h.MaxHealth >= 250000
    end
    local function isProp(m)
        if m.Name == "PropHitboxPlaceholder" then return true end
        local hd, rt = m:FindFirstChild("Head"), m:FindFirstChild("HumanoidRootPart")
        if hd and rt and hd:IsA("BasePart") and rt:IsA("BasePart") and hd.Size.Y <= 0.5 and rt.Size.X >= 6 then
            local h = m:FindFirstChild("Humanoid")
            return h ~= nil and h.MaxHealth > 0 and h.MaxHealth <= CFG.propHP
        end
        return false
    end
    local stuckM, stuckHP, stuckAt = nil, 0, 0
    local function stalled(m)
        local h = m and m.Parent and m:FindFirstChild("Humanoid")
        if not h then stuckM = nil; return false end
        if m ~= stuckM then stuckM, stuckHP, stuckAt = m, h.Health, os.clock(); return false end
        if h.Health < stuckHP - 1 then stuckHP, stuckAt = h.Health, os.clock(); return false end
        return os.clock() - stuckAt > CFG.stall
    end
    -- v63: antes, quando "stalled(bn)" dava true (5s tentando sem tirar vida dele - sombra/clone de aliado que o
    -- jogo nao deixa morrer, prop travado, mob fantasma puxado etc.) e nao tinha PROP por perto pra trocar, a funcao
    -- simplesmente devolvia o MESMO bn de novo (nunca soltava). Era por isso que a Dungeon "ficava so tentando matar
    -- esse NPC" (pedido do usuario: carta Shadow) e nao soltava NPC fantasma. Agora: apos 5s sem dano, o alvo entra
    -- numa lista negra temporaria (8s) e e ignorado na proxima varredura, liberando a farm pra ir em outro mob/prop
    -- ou seguir pra porta do andar.
    local DGH = setmetatable({}, { __mode = "k" })   -- modelo -> até quando ignorar (lista negra de "travado")
    local function pickTarget()
        local hrp = hrpf(); if not hrp then return end
        local list = mobs()
        local now = os.clock()
        local bp, bpd, bb, bbd, bn, bnd = nil, math.huge, nil, math.huge, nil, math.huge
        for _, m in ipairs(list) do
            if not (DGH[m] and DGH[m] > now) then
                local r = m.Parent and m:FindFirstChild("HumanoidRootPart")
                if r then
                    local d = (r.Position - hrp.Position).Magnitude
                    if isProp(m) then if d < bpd then bpd, bp = d, m end
                    elseif isBoss(m) then if d < bbd then bbd, bb = d, m end
                    elseif d < bnd then bnd, bn = d, m end
                end
            end
        end
        local isB = false
        if not (bn and bnd <= CFG.hit) and bb then isB = true; bn = bb end
        if bn and not isB and stalled(bn) then
            DGH[bn] = now + 8
            bn = nil
        end
        if bp and bpd <= CFG.propR and bn == nil then return bp, false, true end
        return bn, isB, false
    end

    -- ===== arma / ataque =====
    local function toolByTip(tip)
        for _, c in ipairs({ Player.Backpack, char() }) do
            if c then for _, t in ipairs(c:GetChildren()) do if t:IsA("Tool") and t.ToolTip == tip then return t.Name end end end
        end
    end
    local function wantedTool()
        local n = toolByTip(Config.DunWeapon)
        if n then return n, Config.DunWeapon end
        for _, tip in ipairs({ "Melee", "Sword", "Blox Fruit", "Gun" }) do
            n = toolByTip(tip); if n then return n, tip end
        end
    end
    local function equip()
        local c, hum = char(), humf()
        if not c or not hum then return end
        local name = wantedTool(); if not name then return end
        local cur = c:FindFirstChildOfClass("Tool")
        if cur and cur.Name == name then return end
        local t = Player.Backpack:FindFirstChild(name)
        if t then hum:EquipTool(t) end
    end
    local busoAt = 0
    local function buso()
        local c = char()
        if not c or c:FindFirstChild("HasBuso") or os.clock() - busoAt < 4 then return end
        busoAt = os.clock()
        pcall(function() RS.Remotes.CommF_:InvokeServer("Buso") end)
    end
    local atkFlag, atkAt = false, 0
    local function attackOnce()
        local c = char(); if not c then return end
        local tool = c:FindFirstChildOfClass("Tool"); if not tool then return end
        local hrp = c:FindFirstChild("HumanoidRootPart"); if not hrp then return end
        local stun = c:FindFirstChild("Stun")
        if stun and stun.Value ~= 0 then return end
        local hits = {}
        for _, m in ipairs(mobs()) do
            local r = m.Parent and m:FindFirstChild("HumanoidRootPart")
            if r and (r.Position - hrp.Position).Magnitude <= CFG.hit then hits[#hits + 1] = { m, r } end
        end
        if #hits == 0 then return end
        -- v111: tool.ToolTip -> Core.wtip (ToolTip com fallback pra GetAttribute("WeaponType")), mesmo motivo do
        -- fix no engine principal (click normal de espada/estilo de luta parando de ser reconhecido)
        local wt = (Core.wtip and Core.wtip(tool)) or tool.ToolTip
        if wt == "Blox Fruit" then
            local rem = tool:FindFirstChild("LeftClickRemote")
            if rem and rem:IsA("RemoteEvent") then
                rem:FireServer(Vector3.new(0, -500, 0), math.random(1, 4), true)
                task.wait(0.01)
                rem:FireServer(false)
            end
            return
        end
        if wt == "Melee" or wt == "Sword" then
            -- v61 fix: a Dungeon tinha seu PROPRIO click de Melee/Sword, mais simples que o do resto do hub (Farm
            -- normal/Sea/Vulcan/Mastery) - sem o reforco do golpe do proprio jogo (CombatFramework). Agora usa o
            -- MESMO reforco (Core.cfAttack) que faz o golpe de verdade do jogo acontecer junto com o RegisterHit.
            if Core.cfAttack and os.clock() - (D.cfAt or 0) > 0.2 then D.cfAt = os.clock(); pcall(Core.cfAttack) end
            local net = RS:FindFirstChild("Modules") and RS.Modules:FindFirstChild("Net")
            local ra, rh = net and net:FindFirstChild("RE/RegisterAttack"), net and net:FindFirstChild("RE/RegisterHit")
            if ra and rh then
                -- v26: formato do script do usuario: UM pacote com todas as partes de todos os alvos no alcance
                local list, head = {}, nil
                for i = 1, #hits do
                    local mm = hits[i][1]
                    local n0 = #list
                    for _, pt in ipairs(mm:GetChildren()) do
                        if pt:IsA("BasePart") then list[#list + 1] = { mm, pt } end
                    end
                    if #list == n0 then list[#list + 1] = { mm, hits[i][2] } end
                    head = head or mm:FindFirstChild("Head") or hits[i][2]
                    if #list >= 160 then break end
                end
                local hash = tostring(Player.UserId):sub(2, 4) .. tostring(coroutine.running()):sub(11, 15)
                ra:FireServer()
                rh:FireServer(head, list, {}, hash)
                pcall(function() Core.secureHit(head, list) end)
            end
        end
    end
    task.spawn(function()
        while Alive do
            if atkFlag and D.active then
                if os.clock() - atkAt > 1.2 then atkFlag = false; task.wait(0.25)
                else pcall(attackOnce); task.wait(CFG.atkDelay) end
            else task.wait(0.25) end
        end
    end)
    local hooked = setmetatable({}, { __mode = "k" })
    local function watchKill(m)
        if hooked[m] then return end
        hooked[m] = true
        local h = m:FindFirstChild("Humanoid")
        if h then local c; c = h.Died:Connect(function() S.kills += 1; c:Disconnect() end) end
    end
    local bringAt = 0
    -- Bring Mob Dungeons: junta os outros inimigos (sem chefe/prop/aliado) em cima do alvo para bater em todos de uma vez.
    -- v97: Bring Mob refeito do zero, de um jeito so (sem nenhum "V2" junto). Antes existiam DOIS caminhos aqui: um
    -- "V1" que so fazia um CFrame pontual a cada 0,25s SEM nenhuma trava (o mob conseguia andar/fugir entre um puxao
    -- e outro) e um "V2" (BodyPosition fisica + CollectionService) que nunca rodava de verdade (Config.BringMobV2
    -- sempre devolvia false - ve o GET/SET em pcompat, so existe pra nao quebrar quem le essa prop por fora) e so
    -- ficava morto, confuso, no meio do codigo. Agora usa o MESMO motor forte do Bring Mob principal
    -- (Core.pullMob/freeMob): colisao desligada em TODA parte do corpo, Animator apagado, ChangeState(Physics),
    -- BodyVelocity "BatmanLock" com forca infinita e CFrame todo frame (dead-zone de 5 studs) - o mob fica
    -- realmente travado no lugar, nao so teleportado de vez em quando. (Core ja vem do ambiente do modulo, __E.Core -
    -- mesma tabela que getgenv().MoonPremiumCore - nao precisa buscar de novo.)
    local bringHeld = setmetatable({}, { __mode = "k" })   -- mob -> true enquanto estiver preso no grupo atual
    local function bringClear()
        for m in pairs(bringHeld) do
            bringHeld[m] = nil
            if Core then pcall(Core.freeMob, m) end
        end
    end
    local function bringMobs(target)
        if not Config.DunBring then bringClear(); return end
        if os.clock() - bringAt < 0.25 then return end
        bringAt = os.clock()
        local tr = target.Parent and target:FindFirstChild("HumanoidRootPart"); if not tr then return end
        local center = tr.Position
        local lim = math.clamp(tonumber(Config.DunBringN) or 6, 2, 12)
        local now = os.clock()
        local list = {}
        for _, o in ipairs(mobs()) do
            -- v63: nao puxa quem ja foi marcado como "travado"/fantasma (pickTarget/DGH) - evita ficar puxando
            -- NPC fantasma (ou a sombra/aliado que nunca morre) de novo pro grupo
            if o ~= target and not isBoss(o) and not isProp(o) and not (DGH[o] and DGH[o] > now) then
                local r = o:FindFirstChild("HumanoidRootPart")
                local h = o:FindFirstChildOfClass("Humanoid")
                if r and h and h.Health > 0 then
                    local d = (r.Position - center).Magnitude
                    if d <= 120 then list[#list + 1] = { r, d, h, o } end
                end
            end
        end
        table.sort(list, function(a, b) return a[2] < b[2] end)
        local cf, keep = CFrame.new(center), {}
        for i = 1, math.min(lim, #list) do
            local r, h, o = list[i][1], list[i][3], list[i][4]
            keep[o] = true
            if Core then pcall(Core.pullMob, o, r, h, cf) else pcall(function() r.CFrame = cf; r.CanCollide = false end) end
        end
        for m in pairs(bringHeld) do
            if not keep[m] then bringHeld[m] = nil; if Core then pcall(Core.freeMob, m) end end
        end
        for m in pairs(keep) do bringHeld[m] = true end
        pcall(function() sethiddenproperty(Player, "SimulationRadius", math.huge) end)
    end
    local function fight(m, boss)
        if not alive(m) then return false end
        watchKill(m)
        local hum = humf(); if not hum then return false end
        if hum.Sit then hum.Sit = false end
        local h = boss and CFG.bossKill or CFG.kill
        local c = char()
        local tool = c and c:FindFirstChildOfClass("Tool")
        if tool and tool.ToolTip == "Blox Fruit" then h = 15 end
        if h > 30 then h = 20 end
        goto_(m.HumanoidRootPart.CFrame * CFrame.new(-3, h, 0))
        if not boss and not isProp(m) then
            bringMobs(m)
        end
        equip(); buso()
        atkFlag, atkAt = true, os.clock()
        return true
    end

    -- ===== cartas (buffs) =====
    local BUFFS = { "AttackSpeedMultiplier", "Overflow", "Lifesteal", "AllCooldown", "Unbreakable", "Fortress", "Shadow", "FruitTAPCooldown", "Armor", "Defense", "Skyjumps", "RageGain", "RaceEnergy", "Sniper", "Size" }
    local WBUFF = { Melee = { "Melee", "MeleeCooldown", "MeleeZCooldown", "MeleeXCooldown", "MeleeCCooldown" }, Sword = { "Sword", "SwordCooldown", "SwordZCooldown", "SwordXCooldown" },
        ["Blox Fruit"] = { "Fruit", "FruitCooldown", "FruitZCooldown", "FruitXCooldown", "FruitVCooldown", "FruitCCooldown" }, Gun = { "Gun", "GunCooldown", "GunZCooldown", "GunXCooldown" } }
    local function rank(name)
        -- v64: carta que o usuario marcou pra nunca escolher (ex.: "Shadow", que causava o bug de ficar preso
        -- tentando matar o aliado/clone) vira a PIOR prioridade - so e escolhida se for a UNICA opcao na tela.
        if type(Config.DunCardBlock) == "table" then
            for _, b in ipairs(Config.DunCardBlock) do if b == name then return 1000 end end
        end
        for i, b in ipairs(BUFFS) do if b == name then return i end end
        local _, tip = wantedTool()
        for i, b in ipairs(WBUFF[tip or Config.DunWeapon] or {}) do if b == name then return #BUFFS + i end end
        return 999
    end
    local cardAt = 0
    local function hookCards()
        if os.clock() - cardAt < 1 then return end
        cardAt = os.clock()
        local sh = RS:FindFirstChild("DungeonShared")
        local sel = sh and sh:FindFirstChild("BuffSelector")
        if sel and sel:IsA("RemoteFunction") then
            sel.OnClientInvoke = function(list)
                if not Config.DunCard or type(list) ~= "table" then return nil end
                local best, br = nil, math.huge
                for _, c in ipairs(list) do
                    local n = type(c) == "table" and c.buffName
                    if n then local r = rank(n); if r < br then br, best = r, n end end
                end
                best = best or (list[1] and list[1].buffName)
                if not best then return nil end
                task.wait(CFG.buffDelay)
                return best
            end
        end
        local rep = sh and sh:FindFirstChild("BuffReplicator")
        if rep and rep:IsA("RemoteEvent") and not D.repConn then
            D.repConn = rep.OnClientEvent:Connect(function(b) if type(b) == "table" then S.buffs = b end end)
        end
        for _, nm in ipairs({ "ResultsScreen", "ReturnToHub" }) do
            local ev = sh and sh:FindFirstChild(nm)
            if ev and ev:IsA("RemoteEvent") and not (D.endConn and D.endConn[nm]) then
                D.endConn = D.endConn or {}
                D.endConn[nm] = ev.OnClientEvent:Connect(function() D.finished = true; atkFlag = false end)
            end
        end
    end

    -- ===== andares =====
    local function dungeonFolder() local m = workspace:FindFirstChild("Map"); return m and m:FindFirstChild("Dungeon") end
    local function floorModel(n) local d = dungeonFolder(); return d and n and d:FindFirstChild(tostring(n)) end
    local function floorCF(m)
        if not m then return nil end
        local at = m:GetAttribute("BoundingCF")
        local p = at and at.Position
        if not p then local ok, pv = pcall(function() return m:GetPivot().Position end); if not ok then return nil end; p = pv end
        return CFrame.new(p.X, p.Y + CFG.floorH, p.Z)
    end
    local function inside(m, pos)
        local cf, sz = m:GetAttribute("BoundingCF"), m:GetAttribute("BoundingSize")
        if not cf or not sz then return false end
        local o = cf:PointToObjectSpace(pos)
        return math.abs(o.X) <= sz.X * 0.5 and math.abs(o.Y) <= sz.Y * 0.5 and math.abs(o.Z) <= sz.Z * 0.5
    end
    local function currentFloor()
        local hrp, d = hrpf(), dungeonFolder()
        if not hrp or not d then return nil end
        local near, nd
        for _, f in ipairs(d:GetChildren()) do
            local n = tonumber(f.Name)
            if n then
                if inside(f, hrp.Position) then return n end
                local at = f:GetAttribute("BoundingCF")
                if at then local m = (at.Position - hrp.Position).Magnitude; if not nd or m < nd then nd, near = m, n end end
            end
        end
        return near
    end
    local function highestFloor()
        local d, hi = dungeonFolder(), nil
        if not d then return nil end
        for _, f in ipairs(d:GetChildren()) do local n = tonumber(f.Name); if n and (not hi or n > hi) then hi = n end end
        return hi
    end
    local function rootOf(fl, nm)
        local m = floorModel(fl); m = m and m:FindFirstChild(nm)
        return m and m:FindFirstChild("Root")
    end
    local lastTouch = 0
    local function touch(part)
        if os.clock() - lastTouch < 0.6 then return end
        lastTouch = os.clock()
        local hrp = hrpf()
        if hrp and part and type(firetouchinterest) == "function" then
            pcall(firetouchinterest, hrp, part, 0); task.wait(); pcall(firetouchinterest, hrp, part, 1)
        end
    end
    local runInfo, runAt = nil, 0
    local function findRun()
        if runInfo and runInfo.Parent and runInfo:GetAttribute("CurrentExploredLevel") ~= nil then return runInfo end
        runInfo = nil
        if not inRun() or os.clock() - runAt < 3 then return nil end
        runAt = os.clock()
        local function look(root, depth)
            for _, c in ipairs(root:GetChildren()) do if c:GetAttribute("CurrentExploredLevel") ~= nil then return c end end
            if depth <= 0 then return nil end
            for _, c in ipairs(root:GetChildren()) do
                if (c:IsA("Folder") or c:IsA("Configuration")) and not ({ Map = 1, Camera = 1, Terrain = 1, Enemies = 1, Characters = 1, Debris = 1, Effect = 1, Sounds = 1 })[c.Name] then
                    local r = look(c, depth - 1); if r then return r end
                end
            end
        end
        runInfo = look(workspace, 2) or look(RS, 2)
        return runInfo
    end
    local function runStep()
        local info = findRun()
        hookCards()
        if info then
            S.floor = info:GetAttribute("CurrentExploredLevel") or 0
            S.dead, S.total, S.left = info:GetAttribute("DeadEnemies") or 0, info:GetAttribute("TotalEnemies") or 0, info:GetAttribute("TimeLeft") or 0
            local fl = info:FindFirstChild("Floors")
            if fl then local hi = 0; for _, c in ipairs(fl:GetChildren()) do local n = tonumber(c.Name); if n and n > hi then hi = n end end; S.maxFloor = hi end
        end
        if D.finished then stage("Finished: waiting to return to the hub"); hoverHigh(); return end
        local hum = humf()
        if not hum or hum.Health <= 0 then stage("Waiting to respawn"); return end
        local m, boss, prop = pickTarget()
        if m then
            local hrp, rt = hrpf(), m:FindFirstChild("HumanoidRootPart")
            S.target = (prop and "PROP " or boss and "BOSS " or "") .. m.Name
            stage((prop and "Breaking blocking prop: " or boss and "Fighting boss " or "Fighting ") .. m.Name)
            if fight(m, boss) then return end
        end
        atkFlag, S.target = false, "-"
        local here = currentFloor()
        if here then
            local ex = rootOf(here, "ExitTeleporter")
            if ex and ex.Parent and ex:FindFirstChild("TouchInterest") then
                local hrp = hrpf()
                local d = hrp and (ex.Position - hrp.Position).Magnitude or 9999
                stage("Going through the door of floor " .. here .. " -> " .. (here + 1))
                if d <= CFG.door then touch(ex) end
                goto_(ex.CFrame)
                return
            end
            if S.floor > here then
                local en = rootOf(here + 1, "EntranceTeleporter")
                if en then stage("Following the door to floor " .. (here + 1)); goto_(en.CFrame * CFrame.new(0, 10, 0)); return end
            end
        end
        local fm = floorModel(here) or floorModel(S.floor) or floorModel(highestFloor())
        local cf = floorCF(fm)
        if cf then stage("Scanning floor " .. tostring(here or S.floor)); goto_(cf); return end
        stage("Waiting for the new floor to load")
        hoverHigh()
    end

    -- ===== lobby (pads) =====
    local function pads()
        local f = D.padsFolder(); local out = {}
        if f then for _, c in ipairs(f:GetChildren()) do if c:FindFirstChild("DungeonSettingsChanged") and c:FindFirstChild("Pad") then out[#out + 1] = c end end end
        table.sort(out, function(a, b) return a.Name < b.Name end)
        return out
    end
    local function energy()
        local ok, r = pcall(function() return require(RS.DungeonClient.ReplicatedPlayerData).get() end)
        if ok and type(r) == "table" and tonumber(r.CurrentEnergy) then return math.floor(tonumber(r.CurrentEnergy)) end
        return nil -- v43: nao conseguiu ler: nao bloqueia o Start
    end
    local chosen, setAt, startAt = nil, 0, 0
    local function pickPad()
        local list = pads(); if #list == 0 then return nil end
        local best, bs
        for _, p in ipairs(list) do
            local n, mx, who = p:GetAttribute("NumPlayersOnPad") or 0, p:GetAttribute("MaxPlayers") or 4, p:GetAttribute("Initiator")
            if n < mx then
                local sc = n * 4 + ((who == Player.UserId) and 2 or (who == nil and 1 or 0))
                if not bs or sc > bs then bs, best = sc, p end
            end
        end
        if chosen and chosen.Parent then
            local n, mx = chosen:GetAttribute("NumPlayersOnPad") or 0, chosen:GetAttribute("MaxPlayers") or 4
            if n < mx then return chosen end
        end
        chosen = best or list[1]
        return chosen
    end
    -- v93: Moon Sync - toca a animacao de sincronia (a mesma do Multi Account) so UMA vez por "ida" ao pad, quando a
    -- conta que esta seguindo e uma conta sincronizada - reseta sozinho quando o alvo de follow muda ou some
    local animedWith, animedAt
    local function lobbyStep()
        S.energy = energy() or S.energy or 0
        local hrp = hrpf(); if not hrp then return end
        local follow = Config.DunFollow
        local followName = followPlayerName()
        if follow ~= animedAt then animedWith, animedAt = nil, follow end
        if not Config.DunStart and follow and follow ~= "" and follow ~= "None" then
            local pl = PlayersSvc:FindFirstChild(followName)
            local tr = pl and pl.Character and pl.Character:FindFirstChild("HumanoidRootPart")
            if tr then
                stage("Joining " .. followName)
                pcall(function()
                    local MS = getgenv().MoonHubSync
                    if MS and MS.playAnim and MS.synced and MS.synced[pl.UserId] and animedWith ~= pl.UserId then
                        animedWith = pl.UserId
                        MS.playAnim(pl.UserId, pl.Name)
                    end
                end)
                goto_(tr.CFrame * CFrame.new(0, 3, 0)); return
            end
            stage("Waiting for " .. followName .. " to appear"); hoverHigh(); return
        end
        local padM = pickPad()
        if not padM then stage("No pad found"); hoverHigh(); return end
        local pad = padM:FindFirstChild("Pad")
        if not Player:FindFirstChild("TeleporterPadObjectReference") then
            stage("Going to pad " .. padM.Name .. " (" .. (padM:GetAttribute("NumPlayersOnPad") or 0) .. "/" .. (padM:GetAttribute("MaxPlayers") or 4) .. ")")
            goto_(pad.CFrame * CFrame.new(0, 4, 0))
            return
        end
        goto_(pad.CFrame * CFrame.new(0, 4, 0))
        if Player:GetAttribute("IsTeleporting") or padM:GetAttribute("PreparingToTeleport") then stage("Entering the dungeon..."); return end
        if not Config.DunStart then stage("On the pad: waiting for the other account to start"); return end
        local dsc = padM:FindFirstChild("DungeonSettingsChanged")
        local who = padM:GetAttribute("Initiator")
        if (who == Player.UserId or who == nil) and padM:GetAttribute("Difficulty") ~= Config.DunDiff then
            if os.clock() - setAt > 2 then setAt = os.clock(); dsc:FireServer("Difficulty", Config.DunDiff) end
            if who == Player.UserId then return end
        end
        -- v43: estando em cima do pad voce conta como 1 jogador (o atributo pode demorar/faltar)
        local n = math.max(padM:GetAttribute("NumPlayersOnPad") or 0, 1)
        local need = math.max(Config.DunMin or 1, padM:GetAttribute("MinPlayers") or 1)
        if n < need then stage(string.format("Waiting for players %d/%d", n, need)); return end
        -- v93: pad completo e a conta configurada pra se juntar e uma conta sincronizada -> toca a animacao do Moon
        -- Sync (uma vez so, por pad) pra confirmar visualmente que o grupo tah pronto
        pcall(function()
            local MS = getgenv().MoonHubSync
            local pl = followName ~= "" and followName ~= "None" and PlayersSvc:FindFirstChild(followName)
            if MS and MS.playAnim and pl and MS.synced and MS.synced[pl.UserId] and animedWith ~= pl.UserId then
                animedWith = pl.UserId
                MS.playAnim(pl.UserId, pl.Name)
            end
        end)
        local cost = tonumber(Config.DunCost) or 0
        local en = energy()
        if cost > 0 and en and en < cost then stage("No energy " .. en .. "/" .. cost); return end
        if who ~= nil and who ~= Player.UserId then stage("Another player is the starter of this pad"); return end
        if os.clock() - startAt > 3 then startAt = os.clock(); stage("Starting the dungeon"); dsc:FireServer("Start") end
    end

    -- ===== passo principal (chamado pelo loop de prioridades) =====
    local wasRun = false
    function D.step()
        if not (Config.DunFarm or Config.DunJoin) then
            if D.active then D.halt() end
            return false
        end
        local hrp = hrpf()
        if hrp and hrp.Position.Y > -100 then D.lastGood = hrp.Position end
        if inRun() then
            if not Config.DunFarm then return false end
            D.active = true
            if not wasRun then wasRun, D.finished = true, false; S.runs += 1; S.dead = 0; cardAt = 0 end
            pcall(runStep)
            return true
        end
        if wasRun then
            wasRun, D.finished, S.buffs = false, false, {}
            atkFlag = false
            bringClear()
        end
        if inHub() and Config.DunJoin then
            D.active = true
            pcall(lobbyStep)
            return true
        end
        -- v42: Auto Join ligado mas fora do Hub: voa ate o Hub (carrega os pads) em vez de ignorar
        if Config.DunJoin and hrp then
            local hub = D.hubTarget()
            local cf = hubPos(hub)
            if cf then
                D.active = true
                local dist = (cf.Position - hrp.Position).Magnitude
                stage("Flying to the Dungeon Hub (" .. math.floor(dist) .. " studs)")
                if goto_(cf * CFrame.new(0, 60, 0)) or dist < 120 then
                    pcall(function()
                        for _, d in ipairs(hub:GetDescendants()) do
                            if d:IsA("ProximityPrompt") and fireproximityprompt then fireproximityprompt(d) end
                        end
                    end)
                end
                return true
            end
            if D.active then D.halt() end
            Diag.dungeon = "Dungeon Hub not found in this sea/place. Go to the Dungeon Hub once (Auto Join then takes over)"
            return false
        end
        if D.active then D.halt() end
        Diag.dungeon = "Not in the Dungeon Hub or a dungeon (go to the Dungeon Hub to start)"
        return false
    end
    table.insert(Connections, Player.CharacterAdded:Connect(function() atkFlag = false; cancelTween(); lastPos = nil end))

    -- ===== UI =====
    local function tg(id, title, desc)
        T:AddToggle(id, { Title = title, Description = desc, Default = Config[id] and true or false }):OnChanged(function(v) Config[id] = v; persist() end)
    end
    T:AddSection("Join Dungeon")
    local DIFFS = { "Normal", "Hard", "Challenge" }
    local di = 1
    for i, n in ipairs(DIFFS) do if n == Config.DunDiff then di = i end end
    T:AddDropdown("DunDiff", { Title = "Select Difficulty", Description = "Difficulty set on the pad (Hard/Challenge must be unlocked)", Values = DIFFS, Default = di })
        :OnChanged(function(v) Config.DunDiff = v; persist() end)
    T:AddSlider("DunMin", { Title = "Min Player Join Dungeon", Description = "The starter waits until the pad has this many players", Min = 1, Max = 4, Default = tonumber(Config.DunMin) or 1, Rounding = 0 })
        :OnChanged(function(v) Config.DunMin = math.floor(v); persist() end)
    tg("DunStart", "Account Start Dungeon", "This account sets the difficulty and presses Start. Leave off on the accounts that only join")
    -- v93: contas sincronizadas (Multi Account / Moon Sync) aparecem primeiro na lista, marcadas com "(Synced)" -
    -- assim fica facil de ver quais contas sao suas (ligadas via Moon Sync) e nao so outro jogador qualquer no server
    local function names()
        local MS = getgenv().MoonHubSync
        local synced, other = {}, {}
        for _, p in ipairs(PlayersSvc:GetPlayers()) do
            if p ~= Player then
                if MS and MS.synced and MS.synced[p.UserId] then synced[#synced + 1] = p.Name .. " (Synced)"
                else other[#other + 1] = p.Name end
            end
        end
        local o = { "None" }
        for _, n in ipairs(synced) do o[#o + 1] = n end
        for _, n in ipairs(other) do o[#o + 1] = n end
        return o
    end
    local function followPlayerName() return (tostring(Config.DunFollow or "")):gsub(" %(Synced%)$", "") end
    local fd = T:AddDropdown("DunFollow", { Title = "Select Account Join", Description = "Account that does not start: walks to this player's pad. Accounts synced via Multi Account show up marked (Synced) and play the Moon Sync animation when they meet on the pad", Values = names(), Default = 1 })
    fd:OnChanged(function(v) Config.DunFollow = v; persist() end)
    T:AddButton({ Title = "Refresh Player", Description = "Reloads the player list", Callback = function() pcall(function() fd:SetValues(names()) end) end })
    tg("DunJoin", "Auto Join Dungeon", "Flies to the Dungeon Hub, goes to a pad, sets the difficulty and starts (needs the energy cost)")
    T:AddSection("Dungeon")
    local WV = { "Melee", "Sword", "Blox Fruit", "Gun" }
    local wi = 1
    for i, n in ipairs(WV) do if n == Config.DunWeapon then wi = i end end
    T:AddDropdown("DunWeapon", { Title = "Select Weapon Dungeon", Description = "Weapon type used inside the dungeon (falls back to any weapon you have)", Values = WV, Default = wi })
        :OnChanged(function(v) Config.DunWeapon = v; persist() end)
    tg("DunFarm", "Auto Attack Dungeon", "Inside a dungeon: hovers high, kills every enemy, breaks blocking props, fights bosses and goes through the doors floor by floor")
    tg("DunBring", "Bring Mob Dungeons", "Pulls the nearby enemies onto the one you are hitting (never bosses, props or your Shadow ally) so you kill them together")
    T:AddSlider("DunBringN", { Title = "Bring Mob Dungeons (Select Number)", Description = "How many enemies are pulled together", Min = 2, Max = 12, Default = tonumber(Config.DunBringN) or 6, Rounding = 0 })
        :OnChanged(function(v) Config.DunBringN = math.floor(v); persist() end)
    tg("DunCard", "Auto Pick Card Dungeon", "Picks the card (buff) automatically: attack speed, lifesteal, cooldowns and your weapon's buffs first")
    -- v64: lista pra NUNCA escolher uma carta especifica (ex.: "Shadow", que no passado deixava a farm presa
    -- tentando matar o aliado/clone que ela cria) - so entra se for a unica opcao na tela, senao e sempre a ultima escolha
    T:AddDropdown("DunCardBlock", { Title = "Never Pick These Cards", Description = "Cards checked here are the LAST choice for Auto Pick Card (only picked if nothing else is on screen)", Values = BUFFS, Multi = true, Default = Config.DunCardBlock })
        :OnChanged(function(v)
            local list = {}
            for _, n in ipairs(BUFFS) do if type(v) == "table" and v[n] then list[#list + 1] = n end end
            Config.DunCardBlock = list; persist()
        end)
    T:AddSection("Dungeon Status")
    local info = T:AddParagraph({ Title = "Dungeon", Content = "Checking..." })
    task.spawn(function()
        while Alive do
            pcall(function()
                local nb = 0
                for _ in pairs(S.buffs) do nb += 1 end
                info:SetDesc(table.concat({
                    "Where: " .. (inRun() and "inside a dungeon" or (inHub() and "Dungeon Hub" or "other area")),
                    "Stage: " .. S.stage,
                    string.format("Floor %d/%d | enemies %d/%d | time left %ds", S.floor, S.maxFloor, S.dead, S.total, math.floor(S.left)),
                    "Target: " .. S.target .. " | kills: " .. S.kills .. " | runs: " .. S.runs,
                    "Energy: " .. tostring(energy() or "?") .. " (cost " .. (Config.DunCost or 10) .. ") | cards picked: " .. nb,
                    "Diag: " .. tostring(Diag.dungeon or "idle"),
                }, "\n"))
            end)
            task.wait(1)
        end
    end)
end)()





