    PC.src["raids"] = function() return [===[
local __E = ...
local AFL = __E.AFL
local Config, Connections, Diag, Fluent, Fly, Player, State = __E.Config, __E.Connections, __E.Diag, __E.Fluent, __E.Fly, __E.Player, __E.State
local Tabs, aliveParts, describe, distanceTo, enemiesList, fightEnemy, flyTo = __E.Tabs, __E.aliveParts, __E.describe, __E.distanceTo, __E.enemiesList, __E.fightEnemy, __E.flyTo
local getChar, getPlayerLevel, getSea, invoke, persist = __E.getChar, __E.getPlayerLevel, __E.getSea, __E.invoke, __E.persist
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Alive = true
AFL.onUnload(function() Alive = false end);
-- ============ RAIDS ============
-- Fruit table: { name, price, rarity } (C common, U uncommon, R rare, L legendary, M mythical)
-- Used to NEVER spend a Mythical fruit (nor Legendary in -1M mode). Unknown fruit / skin = forbidden.
local raidStep
AFL.Raid = { payAt = 0, fails = 0, pressAt = 0, moneyAt = 0, doneAt = 0, wasActive = false,
    bad = setmetatable({}, { __mode = "k" }), track = nil, bringAt = 0 }
do
    local R = AFL.Raid
    R.ok = setmetatable({}, { __mode = "k" })
    R.extra = setmetatable({}, { __mode = "k" }) -- ferramentas que sairam do inventario (LoadFruit) com nome sem "Fruit"
    local FruitTable = {
        { "kilo", 5000, "C" }, { "rocket", 5000, "C" }, { "revive", 550000, "R" }, { "paw", 2300000, "L" }, { "magnet", 6000000, "M" }, { "dragon east", 3500000, "M" }, { "dragon west", 3500000, "M" }, { "spin", 7500, "C" }, { "blade", 30000, "C" }, { "chop", 30000, "C" }, { "spring", 60000, "C" },
        { "bomb", 80000, "C" }, { "smoke", 100000, "C" }, { "spike", 180000, "C" },
        { "flame", 250000, "U" }, { "falcon", 300000, "U" }, { "ice", 350000, "U" }, { "sand", 420000, "U" },
        { "dark", 500000, "U" }, { "diamond", 600000, "R" },
        { "light", 650000, "R" }, { "rubber", 750000, "R" }, { "barrier", 800000, "R" }, { "ghost", 940000, "R" }, { "magma", 960000, "R" },
        { "quake", 1000000, "L" }, { "buddha", 1200000, "L" }, { "love", 1300000, "L" },
        { "spider", 1500000, "L" }, { "sound", 1700000, "L" }, { "soul", 3300000, "L" }, { "phoenix", 1800000, "L" }, { "portal", 1900000, "L" },
        { "rumble", 2100000, "L" }, { "pain", 2300000, "L" }, { "blizzard", 2400000, "L" }, { "gravity", 2500000, "L" },
        { "creation", 1400000, "M" }, { "mammoth", 2700000, "M" }, { "t-rex", 2700000, "M" }, { "trex", 2700000, "M" },
        { "dough", 2800000, "M" }, { "shadow", 2900000, "M" }, { "venom", 3000000, "M" }, { "gas", 3200000, "M" },
        { "control", 3200000, "M" }, { "spirit", 3400000, "M" }, { "dragon", 3500000, "M" }, { "yeti", 3500000, "M" },
        { "leopard", 5000000, "M" }, { "kitsune", 8000000, "M" },
    }
    local ADVANCED = { Dough = true, Phoenix = true }

    -- fruit info from a name ("Flame Fruit", "Flame-Flame", "Light"...). Skin / unknown -> nil
    local function infoOf(raw)
        raw = string.lower(tostring(raw))
        if string.find(raw, "skin", 1, true) then return nil end
        -- v37: nomes internos do jogo: "Bird-Bird: Falcon", "Bird-Bird: Phoenix", "Human-Human: Buddha"
        local sub = string.match(raw, "^bird%-bird:%s*(%a+)") or string.match(raw, "^human%-human:%s*(%a+)")
        if sub then raw = sub end
        for _, f in ipairs(FruitTable) do
            local b = f[1]
            if string.sub(raw, 1, #b) == b then
                local nx = string.sub(raw, #b + 1, #b + 1)
                if nx == "" or nx == "-" or nx == " " then return f end
            end
        end
    end
    local function toolInfo(tool) return infoOf(tool:GetAttribute("OriginalName") or tool.Name) end

    -- allowed to be spent? (never Mythical; -1M mode also bans Legendary and anything >= 1M; Advanced needs >= 1M)
    local function eligible(f, only1M, needMin)
        if not f then return false end
        if only1M then
            -- "Pay With -1M Fruit": so comum, incomum e rara abaixo de 1M
            if not (f[3] == "C" or f[3] == "U" or f[3] == "R") or f[2] >= 1000000 then return false end
        elseif f[3] == "M" and f[2] > 2500000 then
            return false -- sem a opcao: usa todas as frutas, menos miticas acima de 2.5M
        end
        if needMin and f[2] < needMin then return false end
        return true
    end

    local function okTool(t, only1M, need)
        if R.ok[t] then return true end
        return eligible(toolInfo(t), only1M, need)
    end

    local function bagFruits()
        local list = {}
        for _, c in ipairs({ Player.Backpack, Player.Character }) do
            if c then
                for _, t in ipairs(c:GetChildren()) do
                    if t:IsA("Tool") and (string.find(t.Name, "Fruit") or R.extra[t]) then
                        list[#list + 1] = t
                    end
                end
            end
        end
        return list
    end

    local function hasChip()
        for _, c in ipairs({ Player.Backpack, Player.Character }) do
            if c and c:FindFirstChild("Special Microchip") then return true end
        end
        return false
    end

    -- ilha da raid perto de você (Banana: "Island N" a menos de 3000; Quantum: 3500)
    local function nearIsland()
        local wo = workspace:FindFirstChild("_WorldOrigin")
        local loc = wo and wo:FindFirstChild("Locations")
        local _, hrp = getChar()
        if not (loc and hrp) then return nil end
        local best, bn = nil, 0
        for _, ch in ipairs(loc:GetChildren()) do
            local n = tonumber(string.match(ch.Name, "^Island (%d+)$") or "")
            -- v132: pedido do usuario - "Auto Raid fica parado que nem estatua". O bomba.lua (f85/f86) nao limita a
            -- distancia: acha a "Island N" de maior numero em _WorldOrigin.Locations e vai ate ela. Aqui o limite de
            -- 3500 studs fazia nearIsland() devolver nil (e active() dar falso) quando a raid comecava mais longe
            -- que isso do personagem - o hub achava que nao tinha raid e ficava parado. Tirado o limite.
            if n and n > bn then
                if ch:IsA("BasePart") then best, bn = ch, n
                elseif ch:IsA("Model") then
                    -- v58: ilha que e Model (nao BasePart) era ignorada e o Auto Raid ficava parado em "waiting for mobs"
                    local okp, cf = pcall(function() return ch:GetPivot() end)
                    if okp and cf then best, bn = { Name = ch.Name, Position = cf.Position, CFrame = cf, Parent = ch.Parent }, n end
                end
            end
        end
        return best
    end
    -- em raid = atributo IslandRaiding (Quantum) ou timer da raid visível + ilha por perto (Banana)
    local function active()
        if Player:GetAttribute("IslandRaiding") == true then return true end
        local ok, v = pcall(function() return Player.PlayerGui.Main.TopHUDList.RaidTimer.Visible end)
        if ok and v == true then
            -- v59: entre as ondas a ilha some da pasta por instantes: segura "em raid" por 20 s em vez de largar o personagem
            if nearIsland() ~= nil then R.lastAct = os.clock(); return true end
            if os.clock() - (R.lastAct or 0) < 20 then return true end
        end
        return false
    end
    R.active = active

    local function unequip()
        local _, _, hum = getChar()
        if hum then pcall(function() hum:UnequipTools() end) end
    end

    -- Mysterious Scientist: search the NPC folders; fallback = fixed spots (guess)
    local function scientistCF()
        for _, folder in ipairs({ workspace:FindFirstChild("NPCs"), workspace }) do
            if folder then
                for _, d in ipairs(folder:GetChildren()) do
                    local l = string.lower(d.Name)
                    if d:IsA("Model") and (string.find(l, "scientist", 1, true) or string.find(l, "mysterious", 1, true)) then
                        local p = d:FindFirstChild("HumanoidRootPart") or d.PrimaryPart or d:FindFirstChildWhichIsA("BasePart")
                        if p then return p.CFrame end
                    end
                end
            end
        end
        local sea = getSea()
        if sea == 2 then return CFrame.new(-6438, 250, -4501) end
        if sea == 3 then return CFrame.new(-5017, 313, -2832) end
    end

    local function raidButton()
        local map = workspace:FindFirstChild("Map")
        if not map then return end
        local btn
        pcall(function()
            if getSea() == 3 then btn = map["Boat Castle"].RaidSummon2.Button.Main
            elseif getSea() == 2 then btn = (map.CircleIsland:FindFirstChild("RaidSummon2") or map.CircleIsland.RaidSummon).Button.Main end
        end)
        if not (btn and btn:FindFirstChildOfClass("ClickDetector")) then
            btn = nil
            local sm = map:FindFirstChild("RaidSummon2", true) or map:FindFirstChild("RaidSummon", true)
            local m = sm and sm:FindFirstChild("Main", true)
            if m and m:FindFirstChildOfClass("ClickDetector") then btn = m end
        end
        return btn
    end

    local function waitFor(fn, t)
        local t0 = os.clock()
        while os.clock() - t0 < t do
            if fn() then return true end
            task.wait(0.1)
        end
        return fn() and true or false
    end
    -- v38: remotes do modulo Net (o jogo migrou varias funcoes para la): acha por nome, chama com tempo limite
    local function netRemotes(...)
        local words, out = { ... }, {}
        local m = ReplicatedStorage:FindFirstChild("Modules")
        local n = m and m:FindFirstChild("Net")
        for _, r in ipairs(n and n:GetChildren() or {}) do
            local l = string.lower(r.Name)
            for _, w in ipairs(words) do
                if string.find(l, w, 1, true) then out[#out + 1] = r; break end
            end
        end
        return out
    end
    local function netInvoke(r, ...)
        if not (r and r:IsA("RemoteFunction")) then return false, "not a RemoteFunction" end
        local args, done, ok, res = table.pack(...), false, false, nil
        task.spawn(function() ok, res = pcall(r.InvokeServer, r, table.unpack(args, 1, args.n)); done = true end)
        local t0 = os.clock()
        while not done and os.clock() - t0 < 6 do task.wait(0.05) end
        if not done then return false, "no response (6s)" end
        return ok, res
    end
    -- stored fruits (inventory) that are allowed: returns the candidates, cheapest first { {name, info}, ... }
    -- v30: reads getInventoryFruits and, if empty, getInventory (fruit items); accepts several entry formats
    -- v38: tambem aceita {["Flame-Flame"] = {...}} (nome na chave), tenta remotes Net de inventario e guarda a resposta crua para o Status
    local function storedList(only1M, needMin)
        local names, seen = {}, {}
        local function add(nm)
            nm = tostring(nm)
            if not seen[nm] then seen[nm] = true; names[#names + 1] = nm end
        end
        local function walk(t, depth, fruitOnly)
            for k, it in pairs(t) do
                if type(it) == "table" then
                    local nm = it.Name or it.name or it.ItemName
                    local ty = string.lower(tostring(it.Type or it.type or ""))
                    if nm ~= nil and type(nm) ~= "table" then
                        if not fruitOnly or string.find(ty, "fruit", 1, true) or infoOf(nm) then add(nm) end
                    elseif type(k) == "string" and infoOf(k) then
                        add(k)
                    elseif depth < 3 then walk(it, depth + 1, fruitOnly) end
                elseif type(it) == "string" and type(k) == "number" then
                    add(it)
                elseif type(k) == "string" and (it == true or type(it) == "number") and not fruitOnly then
                    add(k)
                end
            end
        end
        local raw = {}
        local function sample(tag, ok, inv)
            local first
            if type(inv) == "table" then
                local k, v = next(inv)
                first = (k ~= nil) and (tostring(k) .. "=" .. describe(v)) or "empty table"
            else
                first = tostring(inv)
            end
            raw[#raw + 1] = tag .. (ok and "" or " (error)") .. ": " .. first
        end
        local ok, inv = invoke("getInventoryFruits")
        sample("getInventoryFruits", ok, inv)
        if ok and type(inv) == "table" then walk(inv, 1, false) end
        if #names == 0 then
            local ok2, inv2 = invoke("getInventory")
            sample("getInventory", ok2, inv2)
            if ok2 and type(inv2) == "table" then walk(inv2, 1, true) end
        end
        if #names == 0 then
            for i, r in ipairs(netRemotes("inventory")) do
                if i > 4 then break end
                local ok3, inv3 = netInvoke(r)
                sample(r.Name, ok3, inv3)
                if ok3 and type(inv3) == "table" then walk(inv3, 1, true) end
                if #names > 0 then break end
            end
        end
        -- v70: 2 fontes novas vindas dos scripts que o usuario mandou (Auto Pay nunca foi resolvido antes por falta
        -- de dados reais de outra fonte que funcione em alguns builds do jogo):
        -- 1) CommF_:InvokeServer("GetFruits") sem o 2o argumento - formato diferente de "getInventoryFruits" (cada
        --    entrada vem com .Name/.Price/.Rarity direto, sem aninhamento) - as vezes funciona quando a outra nao.
        if #names == 0 then
            local ok4, inv4 = invoke("GetFruits")
            sample("GetFruits", ok4, inv4)
            if ok4 and type(inv4) == "table" then
                for _, it in pairs(inv4) do
                    if type(it) == "table" and it.Name then add(it.Name) end
                end
            end
        end
        -- 2) le o cache do CLIENTE direto (ItemReplicationService/ItemConfig), sem depender de nenhum remote do
        --    servidor responder certo - plano C de ultimo recurso quando os 2 de cima nao devolvem nada.
        if #names == 0 then
            pcall(function()
                local rep = require(RS:WaitForChild("ItemReplicationService", 3))
                local icfg = require(RS:WaitForChild("ItemConfig", 3))
                local cache = rep._UserCache[Player.UserId]
                for _, v in pairs(cache:GetItems("Quantity") or {}) do
                    local ok5, c = pcall(function() return icfg.match(v.ItemId):unwrap() end)
                    if ok5 and c and c.Index and c.Index.IdType == "PhysicalMoveset" then
                        local label = tostring(c.Index.DebugLabel or ""):gsub(" %[.-%]", "")
                        add(label)
                    end
                end
            end)
            sample("ItemReplicationService cache", true, tostring(#names) .. " name(s) found")
        end
        local out = {}
        for _, nm in ipairs(names) do
            local f = infoOf(nm)
            if f and eligible(f, only1M, needMin) then out[#out + 1] = { nm, f } end
        end
        table.sort(out, function(x, y) return x[2][2] < y[2][2] end)
        R.invSummary = #names .. " in inventory, " .. #out .. " allowed" .. (#out > 0 and (" (cheapest: " .. out[1][1] .. ")") or "")
        if #out == 0 then
            if #names > 0 then R.invSummary = R.invSummary .. " | names seen: " .. table.concat(names, ", ", 1, math.min(#names, 6)) end
            R.invSummary = R.invSummary .. " | raw: " .. table.concat(raw, " ; ")
        end
        return out
    end
    -- takes ONE fruit out of the inventory and returns the new backpack tool (or nil)
    -- v37: mais variacoes de nome para o LoadFruit, espera 4s por tentativa e aceita a fruta que ja esta na mochila/mao
    -- v38: se o CommF_ nao entregar, tenta os remotes Net de "load/take/equip fruit"
    local function loadOne(entry)
        local before = {}
        for _, c in ipairs({ Player.Backpack, Player.Character }) do
            for _, t in ipairs(c and c:GetChildren() or {}) do before[t] = true end
        end
        local nm = entry[1]
        local tries, seenT = {}, {}
        local function addTry(a) if a and a ~= "" and not seenT[a] then seenT[a] = true; tries[#tries + 1] = a end end
        addTry(nm)
        local base = string.match(nm, "^(%a+)")
        if base then
            addTry(base .. "-" .. base)
            addTry(base .. " Fruit")
            addTry(base)
        end
        local lowBase = base and string.lower(base)
        local function findLoaded()
            for _, c in ipairs({ Player.Backpack, Player.Character }) do
                for _, t in ipairs(c and c:GetChildren() or {}) do
                    if t:IsA("Tool") then
                        if not before[t] and (c == Player.Backpack or string.find(t.Name, "Fruit")) then return t end
                        if lowBase and string.find(t.Name, "Fruit") and string.sub(string.lower(t:GetAttribute("OriginalName") or t.Name), 1, #lowBase) == lowBase then return t end
                    end
                end
            end
        end
        local replies = {}
        for _, arg in ipairs(tries) do
            local ok, res = invoke("LoadFruit", arg)
            replies[#replies + 1] = arg .. "->" .. (ok and describe(res) or tostring(res))
            Diag.raid = "Auto Pay (fruit): LoadFruit " .. arg .. " -> " .. (ok and describe(res) or tostring(res))
            local found
            waitFor(function() found = findLoaded(); return found ~= nil end, 4)
            if found then R.extra[found] = true; R.ok[found] = true; return found end
        end
        -- plano B: remotes Net com nome de carregar/pegar a fruta
        local cands = netRemotes("loadfruit", "takefruit", "equipfruit", "withdrawfruit", "getfruit")
        for i, r in ipairs(cands) do
            if i > 3 then break end
            for _, arg in ipairs({ nm, tries[2] or nm }) do
                local ok, res = netInvoke(r, arg)
                replies[#replies + 1] = r.Name .. "(" .. arg .. ")->" .. (ok and describe(res) or tostring(res))
                local found
                waitFor(function() found = findLoaded(); return found ~= nil end, 3)
                if found then R.extra[found] = true; R.ok[found] = true; return found end
            end
        end
        local seenNet = {}
        for _, r in ipairs(netRemotes("fruit")) do seenNet[#seenNet + 1] = r.Name; if #seenNet >= 8 then break end end
        R.loadFail = table.concat(replies, " ; ") .. (#seenNet > 0 and (" | Net fruit remotes: " .. table.concat(seenNet, ", ")) or " | no Net fruit remote")
    end

    -- Buy the chip. Money = nothing in hand (once per 2h). Fruit = the cheapest allowed fruit in hand.
    -- Before paying with fruit EVERY forbidden fruit (Mythical, Legendary in -1M mode, skin, unknown) is stored; if one cannot be stored, it does NOT pay.
    -- v30: while paying, R.hold blocks Auto Store and weapon re-equip, so nothing takes the fruit out of the hand.
    -- Returns true (got the chip), false (cannot pay now), nil (still working: traveling / loading a fruit)
    local function setHold(v) R.hold = v; Config.PayHoldUntil = v end
    local function holdFruit(tool)
        local char, _, hum = getChar()
        if not (char and hum and tool and tool.Parent) then return false end
        if tool.Parent == char then return true end
        pcall(function() hum:UnequipTools() end)
        for _ = 1, 6 do
            pcall(function() hum:EquipTool(tool) end)
            task.wait(0.15)
            if tool.Parent == char then return true end
        end
        return tool.Parent == char
    end
    local function prepare(adv, need)
        if Config.PayMode == "Fruit" then
            setHold(os.clock() + 25)
            if adv and Config.PayOnly1M then
                Diag.raid = "Advanced raids need a fruit worth $1M+; turn off 'Pay With -1M Fruit' or pay with money (fragments)"
                setHold(0)
                return false
            end
            local usable, blocked = {}, {}
            for _, t in ipairs(bagFruits()) do
                if okTool(t, Config.PayOnly1M, need) then usable[#usable + 1] = t
                else blocked[#blocked + 1] = t end
            end
            if #usable == 0 then
                local list = storedList(Config.PayOnly1M, need)
                if #list == 0 then
                    Diag.raid = "Auto Pay (fruit): no allowed fruit in the backpack or inventory (" .. tostring(R.invSummary or "inventory unreadable") .. "). Nothing was spent."
                    setHold(0)
                    return false
                end
                local tool
                for i = 1, math.min(3, #list) do
                    Diag.raid = "Auto Pay (fruit): taking " .. list[i][1] .. " out of the inventory"
                    tool = loadOne(list[i])
                    if tool then break end
                end
                if not tool then
                    Diag.raid = "Auto Pay (fruit): the fruit did not come out of the inventory (" .. tostring(R.invSummary) .. ") | " .. tostring(R.loadFail or "")
                    setHold(0)
                    return false
                end
                usable = { tool }
                setHold(os.clock() + 25) -- v40: a fruta acabou de sair do inventario: nada a guarda de volta antes do Select
            end
            table.sort(usable, function(x, y) return ((toolInfo(x) or {})[2] or 0) < ((toolInfo(y) or {})[2] or 0) end)
            -- guarda as proibidas (só as que não são a escolhida)
            for _, t in ipairs(bagFruits()) do
                local ok1 = false
                for _, u in ipairs(usable) do if u == t then ok1 = true break end end
                if not ok1 then
                    invoke("StoreFruit", t:GetAttribute("OriginalName") or t.Name, t)
                    task.wait(0.4)
                end
            end
            for _, t in ipairs(bagFruits()) do
                if not okTool(t, Config.PayOnly1M, need) then
                    Diag.raid = "Auto Pay (fruit): could not store " .. t.Name .. " (forbidden). NOT paid."
                    setHold(0)
                    return false
                end
            end
            if not holdFruit(usable[1]) then
                Diag.raid = "Auto Pay (fruit): could not hold " .. usable[1].Name
                setHold(0)
                return false
            end
            R.heldFruit = usable[1]
            return true
        end
        if not adv and os.time() < R.moneyAt then
            Diag.raid = "Money chip is on cooldown (once every 2h): " .. math.ceil((R.moneyAt - os.time()) / 60) .. " min left"
            return false
        end
        unequip() -- money: nothing in hand, so no fruit can be taken by mistake
        task.wait(0.4)
        return true
    end

    -- uma tentativa de comprar: Check + Select com a fruta na mão, depois espera o chip chegar
    local function trySelect(adv)
        if Config.PayMode == "Fruit" then
            local f = R.heldFruit
            if not (f and f.Parent) or not holdFruit(f) then return false, "fruit is not in hand" end
            setHold(os.clock() + 25)
        end
        invoke("RaidsNpc", "Check")
        local ok, res = invoke("RaidsNpc", "Select", Config.RaidType)
        Diag.raid = string.format("Auto Pay (%s) %s -> %s", Config.PayMode, Config.RaidType, ok and describe(res) or ("error: " .. tostring(res)))
        local got = waitFor(hasChip, 2.5)
        return got
    end

    -- v40: quando o pagamento com fruta falha, avisa na tela e copia o diagnostico (cole no chat para eu ver o que o jogo respondeu)
    local function reportFail(reason)
        if os.clock() - (R.reportAt or 0) < 60 then return end
        R.reportAt = os.clock()
        local bag = {}
        for _, c in ipairs({ Player.Backpack, Player.Character }) do
            for _, t in ipairs(c and c:GetChildren() or {}) do if t:IsA("Tool") then bag[#bag + 1] = t.Name end end
        end
        local rep = table.concat({
            "Auto Pay: " .. tostring(reason),
            "Sea " .. tostring(getSea()) .. " | Level " .. tostring(getPlayerLevel()) .. " | PayMode " .. tostring(Config.PayMode) .. " | Raid " .. tostring(Config.RaidType) .. " | Only-1M " .. tostring(Config.PayOnly1M),
            "Inventory: " .. tostring(R.invSummary),
            "Load: " .. tostring(R.loadFail),
            "Bag: " .. table.concat(bag, ", "),
        }, "\n")
        local okc = pcall(function() setclipboard(rep) end)
        pcall(function()
            Fluent:Notify({ Title = "Moon Hub - Auto Pay", Content = tostring(reason) .. (okc and "\n(diagnostic copied: paste it in the chat)" or ""), Duration = 12 })
        end)
    end

    -- v63: pagamento igual o Auto Raid do bomba.lua + a leitura de frutas guardadas do script de Unstore que o usuario mandou:
    -- RaidsNpc Select direto (sem voar ate o cientista), depois GetFruits / getInventoryFruits (Name + Price + Rarity) e
    -- LoadFruit de cada fruta barata (<= 1.15M ou comum/incomum/rara), com Select logo apos cada uma. Se nao der, o fluxo antigo segue.
    local function fastPay(adv, need)
        local function chipNow() return hasChip() end
        invoke("RaidsNpc", "Select", Config.RaidType)
        if waitFor(chipNow, 1.0) then return true end
        local cands, seen = {}, {}
        local function consider(nm, price, rar)
            nm = tostring(nm or "")
            if nm == "" or seen[nm] then return end
            local info = infoOf(nm)
            price = tonumber(price) or (info and info[2])
            if not price then return end
            local r = string.lower(tostring(rar or ""))
            if r == "" and info then r = ({ C = "common", U = "uncommon", R = "rare", L = "legendary", M = "mythical" })[info[3]] or "" end
            if string.find(string.lower(nm), "skin", 1, true) then return end
            local okp
            if adv then okp = price >= 1000000 and not (r == "mythical" and price > 2500000)
            elseif Config.PayOnly1M then okp = price < 1000000 and (r == "common" or r == "uncommon" or r == "rare" or r == "")
            else okp = (price <= 1150000 or r == "common" or r == "uncommon" or r == "rare") end
            if okp then seen[nm] = true; cands[#cands + 1] = { nm, price } end
        end
        -- v66: "GetFruits" do bomba lista o ESTOQUE do jogo (nao o inventario): ele tenta LoadFruit em todas as baratas e so as que
        -- voce tem funcionam. getInventoryFruits (inventario real, igual o script de Unstore) vem primeiro.
        local blind = false
        for _, src in ipairs({ "getInventoryFruits", "GetFruits" }) do
            blind = (src == "GetFruits")
            local ok, inv = invoke(src)
            if ok and type(inv) == "table" then
                for k, it in pairs(inv) do
                    if type(it) == "table" then
                        consider(it.Name or it.name or it.FruitName or (type(k) == "string" and k or nil), it.Price or it.price or it.Value, it.Rarity or it.rarity)
                    elseif type(it) == "string" then consider(it, nil, nil)
                    elseif type(k) == "string" then consider(k, nil, nil) end
                end
            end
            if #cands > 0 then break end
        end
        if #cands == 0 then
            for _, e in ipairs(storedList(Config.PayOnly1M, need)) do consider(e[1], e[2][2], nil) end
        end
        table.sort(cands, function(x, y) return x[2] < y[2] end)
        R.fastInfo = #cands .. " cheap fruit(s) found" .. (cands[1] and (" (cheapest: " .. cands[1][1] .. ")") or "")
        for i = 1, math.min(blind and 30 or 4, #cands) do
            local nm = cands[i][1]
            Diag.raid = "Auto Pay (fast): LoadFruit " .. nm
            local variants, vs = { nm }, { [nm] = true }
            local base = (not blind) and string.match(nm, "^(%a+)") or nil
            if base then
                for _, v in ipairs({ base .. "-" .. base, base .. " Fruit", base }) do if not vs[v] then vs[v] = true; variants[#variants + 1] = v end end
            end
            for _, v in ipairs(variants) do
                invoke("LoadFruit", v)
                invoke("RaidsNpc", "Select", Config.RaidType)
                if waitFor(chipNow, blind and 0.5 or 1.2) then return true end
                if #bagFruits() > 0 then break end   -- a fruta ja saiu do inventario: nao tenta as outras variacoes
            end
        end
        return false
    end

    local function payChip()
        local adv = ADVANCED[Config.RaidType] == true
        local need = adv and 1000000 or nil
        local fruitMode = Config.PayMode == "Fruit"
        if fruitMode and not (R.heldFruit and R.heldFruit.Parent) and os.clock() - (R.fastAt or 0) > 20 then
            R.fastAt = os.clock()
            State.Mode, State.Text = "Raids", "Auto Pay: buying the chip"
            local okF, gotF = pcall(fastPay, adv, need)
            if okF and gotF then
                R.fails, R.heldFruit = 0, nil
                setHold(0)
                Diag.raid = "Auto Pay (fast): chip received"
                return true
            end
            if not okF then Diag.raid = "Auto Pay (fast) error: " .. tostring(gotF) end
        end
        local cf = scientistCF()
        -- v41: 1) com fruta: pega a fruta PRIMEIRO (mochila ou inventario). Ja com ela na mao, o proximo passo e o cientista.
        if fruitMode then
            local f = R.heldFruit
            if f and f.Parent then
                setHold(os.clock() + 25) -- a fruta continua na mao durante o voo
            else
                R.heldFruit = nil
                State.Mode, State.Text = "Raids", "Taking the fruit"
                local p = prepare(adv, need)
                if p ~= true then
                    if p == false then reportFail(Diag.raid) end
                    return p
                end
                R.travelAt = nil
                Diag.raid = "Auto Pay: got " .. tostring(R.heldFruit and R.heldFruit.Name) .. ", going to the Mysterious Scientist"
            end
        end
        -- 2) voa ate o Mysterious Scientist
        if cf and distanceTo(cf) > 15 then
            R.travelAt = R.travelAt or os.clock()
            if os.clock() - R.travelAt < 60 then
                State.Mode, State.Text = "Raids", "Going to the Mysterious Scientist"
                Diag.raid = "Auto Pay: " .. (fruitMode and "fruit in hand, " or "") .. "flying to the Mysterious Scientist (" .. math.floor(distanceTo(cf)) .. " studs)"
                flyTo(cf * CFrame.new(0, 3, 6))
                return nil
            end
        end
        R.travelAt = nil
        -- 3) perto dele: troca por chip (ate 3 tentativas)
        if os.clock() - (R.selAt or 0) <= 3 then
            State.Mode, State.Text = "Raids", "Waiting at the Scientist"
            return nil
        end
        R.selAt = os.clock()
        State.Mode, State.Text = "Raids", "Trading at the Scientist"
        if not fruitMode then
            local p = prepare(adv, need)
            if p ~= true then return p end
        end
        for _ = 1, 3 do
            if trySelect(adv) then
                if not fruitMode and not adv then R.moneyAt = os.time() + 7200 end
                R.fails, R.heldFruit = 0, nil
                setHold(0)
                return true
            end
        end
        setHold(0)
        Diag.raid = (Diag.raid or "") .. " | no chip received (check level 1100+, money/fragments and the 2h cooldown)"
        if fruitMode then reportFail(Diag.raid) end
        return false
    end

    -- Auto Raid: kill the raid mobs, then move to the most advanced island
    -- v36: (1) so conta mob da propria raid (ate 3500 studs, mesmo raio da ilha): antes qualquer mob do mar entrava na conta
    --      (2) a heuristica de "boss por vida" so vale perto (1200): antes um mob forte de outra ilha sequestrava a raid
    --      (3) a raid avisa que e ela quem esta lutando (R.fightAt), senao o loop principal pulava a propria Raid por 1.5s a cada golpe
    --      (4) sem mob a 700 studs mas com mob vivo na raid: vai ate ele em vez de ficar parado esperando
    -- v28/v97: Bring Mob Raid - junta os outros mobs da raid (nunca o chefe) em cima do alvo, igual ao Bring Mob Dungeons.
    -- v97: refeito do zero, de um jeito so (sem nenhum "V2" junto - a mesma limpeza feita no Bring Mob Dungeons). Antes
    -- existiam dois caminhos: um "V1" com CFrame pontual a cada 0,25s sem nenhuma trava (o mob fugia entre um puxao e
    -- outro) e um "V2" (BodyPosition + CollectionService) que nunca rodava de verdade (Config.BringMobV2 sempre false -
    -- continua existindo so como GET/SET inofensivo pra quem le essa prop por fora, ve pcompat). Agora usa o motor
    -- forte do Bring Mob principal (Core.pullMob/freeMob): colisao desligada em TODA parte do corpo, Animator apagado,
    -- ChangeState(Physics), BodyVelocity "BatmanLock" com forca infinita e CFrame todo frame (dead-zone de 5 studs).
    local Core = __E.Core   -- mesma tabela que getgenv().MoonPremiumCore (raids.lua nao recebe "Core" desestruturado)
    local bringHeld = setmetatable({}, { __mode = "k" })   -- mob -> true enquanto estiver preso no grupo atual
    local function bringClear()
        for m in pairs(bringHeld) do
            bringHeld[m] = nil
            if Core then pcall(Core.freeMob, m) end
        end
    end
    local function bringMobs(target, targetPart, pool)
        if not Config.RaidBring then bringClear(); return end
        if os.clock() - R.bringAt < 0.25 then return end
        R.bringAt = os.clock()
        local center = targetPart.Position
        local lim = math.clamp(tonumber(Config.RaidBringN) or 6, 2, 12)
        local list = {}
        for _, p in ipairs(pool) do
            local m, h, r = p[1], p[2], p[3]
            if m ~= target and h and h.Health > 0 then
                local d = (r.Position - center).Magnitude
                if d <= 160 then list[#list + 1] = { r, d, h, m } end
            end
        end
        table.sort(list, function(a, b) return a[2] < b[2] end)
        local cf, keep = CFrame.new(center), {}
        for i = 1, math.min(lim, #list) do
            local r, h, m = list[i][1], list[i][3], list[i][4]
            keep[m] = true
            if Core then pcall(Core.pullMob, m, r, h, cf) else pcall(function() r.CFrame = cf; r.CanCollide = false end) end
        end
        for m in pairs(bringHeld) do
            if not keep[m] then bringHeld[m] = nil; if Core then pcall(Core.freeMob, m) end end
        end
        for m in pairs(keep) do bringHeld[m] = true end
        pcall(function() sethiddenproperty(Player, "SimulationRadius", math.huge) end)
    end
    -- v28: anti-fantasma - se o alvo que estamos batendo nao perde vida por 18s (preso/rede), ignora ele por 60s e troca
    local function hpOf(m)
        local h = m:FindFirstChildOfClass("Humanoid")
        return h and h.Health
    end
    local function stallSkip(target)
        local now = os.clock()
        local hp = hpOf(target)
        local tr = R.track
        if not tr or tr.m ~= target then tr = { m = target, hp = hp, since = now }; R.track = tr end
        if hp and tr.hp and hp < tr.hp - 0.01 then tr.hp, tr.since = hp, now
        elseif hp and (not tr.hp or hp > tr.hp) then tr.hp = hp end
        if now - tr.since > 18 then
            R.bad[target] = now + 25
            R.track = nil
            Diag.raid = "Raid: " .. target.Name .. " is not losing health (stuck / ghost): skipping it for 60s"
            return true
        end
        return false
    end
    -- v70: Kill Aura (Ilhas 4 e 5) - codigo do script que o usuario mandou (bomba.lua): nessas 2 ilhas (os "waves"
    -- finais da raid, cheios de mob fraco) ele nao perde tempo puxando/batendo um por um - voa pra cima da ilha e
    -- mata todo mundo da pasta Enemies na hora (BreakJoints + Health=0), direto, sem usar a arma. So liga com o
    -- toggle "Kill Aura" (Farm Settings > Raid), nas ilhas 4/5; nas outras ilhas o fight() normal continua igual.
    local function holdHere()
        local _, hr = getChar()
        if hr and not hr:FindFirstChild("FarmHold") then
            local bv = Instance.new("BodyVelocity")
            bv.Name = "FarmHold"
            bv.MaxForce = Vector3.new(1e5, 1e5, 1e5)
            bv.Velocity = Vector3.zero
            bv.Parent = hr
        end
        if hr then hr.AssemblyLinearVelocity = Vector3.zero end
    end
    -- v146: Kill Aura em TODAS as ilhas da raid e instantaneo: mata na hora todo mob que aparece (antes so ilhas 4/5 e
    -- so depois de voar ate 80 studs acima da ilha). Primeiro mata tudo que ja da pra alcancar, depois (se precisar)
    -- voa pra perto da ilha para pegar o dono de rede dos mobs que ainda estao longe.
    local function killAuraKillAll()
        local f = workspace:FindFirstChild("Enemies")
        local killed = 0
        if not f then return 0 end
        for _, e in ipairs(f:GetChildren()) do
            local h = e:FindFirstChildOfClass("Humanoid")
            local er = e:FindFirstChild("HumanoidRootPart")
            if h and er and h.Health > 0 then
                pcall(function()
                    e:BreakJoints()
                    h.Health = 0
                    er.CanCollide = false
                end)
                killed += 1
            end
        end
        return killed
    end
    local function killAuraStep()
        if not Config.KillAura then return false end
        local isl = nearIsland()
        if not isl then return false end
        local n = tonumber(string.match(isl.Name, "(%d+)")) or 0
        pcall(function() sethiddenproperty(Player, "SimulationRadius", math.huge) end)
        local killed = killAuraKillAll()   -- mata na hora, antes de qualquer voo
        local _, hrp = getChar()
        local above = isl.Position + Vector3.new(0, 80, 0)
        if hrp and (hrp.Position - above).Magnitude > 20 then
            State.Mode, State.Text = "Auto Raid", "Kill Aura: going to Island " .. n .. (killed > 0 and (" (" .. killed .. " killed)") or "")
            R.fightAt = os.clock()
            flyTo(CFrame.new(above))
            return true
        end
        pcall(holdHere)     -- v59: ficava parado no ar sem segurar e caia no mar
        State.Mode, State.Text = "Auto Raid", "Kill Aura: Island " .. n .. (killed > 0 and (" (" .. killed .. " killed)") or "")
        R.fightAt = os.clock()
        return true
    end
    -- v146: laco proprio a cada frame: assim que o mob nasce na raid, morre (nao espera o passo do Auto Raid)
    table.insert(conns, RunService.Heartbeat:Connect(function()
        if not (Alive and Config.KillAura and Config.AutoRaid) then return end
        if not active() then return end
        pcall(killAuraKillAll)
    end))
    local function fight()
        if killAuraStep() then return true end
        State.Mode = "Auto Raid"
        local _, hrp = getChar()
        Fly.boost, Fly.boostUntil = nil, os.clock() + 1.5 -- v39: voo direto (sem subir) durante a raid; a velocidade segue o Tween Speed (200)
        local pool = {}
        local function buildPool()
            pool = {}
            for _, e in ipairs(enemiesList()) do
                local eh, er = aliveParts(e)
                if eh and er and (not hrp or (hrp.Position - er.Position).Magnitude < 3500) and not ((R.bad[e] or 0) > os.clock()) then
                    pool[#pool + 1] = { e, eh, er }
                end
            end
        end
        buildPool()
        -- v145: "Auto Raid mata 3 NPC e para": se todos os mobs vivos foram pulados como "fantasma", limpa a lista de ignorados e tenta de novo
        -- v68: enemiesList() esconde os mobs marcados como fantasma pelo anti-fantasma do ataque (Core.ghosts, 10 s): na raid, depois de
        -- puxar varios mobs de uma vez, TODOS viravam "fantasma" ao mesmo tempo, o pool ficava vazio e o hub achava que a ilha tinha acabado
        -- ("mata 3 NPC e desiste"). Sem alvo no pool: limpa os dois filtros e monta o pool de novo.
        if #pool == 0 then
            local had = false
            if next(R.bad) ~= nil then for k in pairs(R.bad) do R.bad[k] = nil end; had = true end
            local gh = Core and Core.ghosts
            if gh and next(gh) ~= nil then for k in pairs(gh) do gh[k] = nil end; had = true end
            if had then
                R.track = nil
                Diag.raid = "Raid: no target left (all skipped/ghost): trying them again"
                buildPool()
            end
        end
        local boss, hs = nil, {}
        for _, p in ipairs(pool) do
            hs[#hs + 1] = { p[1], p[2].MaxHealth, p[3] }
            local l = string.lower(p[1].Name)
            if string.find(l, "boss", 1, true) or l == "order" or string.sub(l, 1, 5) == "order" then boss = p[1] end
        end
        if not boss and #hs >= 2 then
            table.sort(hs, function(x, y) return x[2] > y[2] end)
            local near = (not hrp) or (hrp.Position - hs[1][3].Position).Magnitude < 1200
            if near and hs[1][2] >= hs[2][2] * 2.5 and hs[1][2] >= 50000 then boss = hs[1][1] end
        end
        if boss then
            if stallSkip(boss) then return true end
            State.Text = "Raid: BOSS " .. boss.Name
            Diag.raid = "raid boss detected: " .. boss.Name
            R.fightAt = os.clock()
            fightEnemy(boss, { boss.Name }, false)
            return true
        end
        local best, bd = nil, 700
        for _, p in ipairs(pool) do
            if hrp then
                local d = (hrp.Position - p[3].Position).Magnitude
                if d < bd then best, bd = p[1], d end
            end
        end
        if best then
            if stallSkip(best) then return true end
            State.Text = "Raid: killing " .. best.Name
            R.fightAt = os.clock()
            local bestPart; for _, p in ipairs(pool) do if p[1] == best then bestPart = p[3] end end
            -- v69: pedido do usuario - sem Bring Mob na raid: vai ate o NPC e mata (puxar todos virava fantasma e a raid desistia)
            bringClear()
            fightEnemy(best, { best.Name }, false)
            return true
        end
        -- nenhum mob a 700 studs: se ainda ha mob vivo na raid, vai ate o mais proximo
        local far, fd, fp = nil, math.huge, nil
        for _, p in ipairs(pool) do
            if hrp then
                local d = (hrp.Position - p[3].Position).Magnitude
                if d < fd then far, fd, fp = p[1], d, p[3] end
            end
        end
        if far then
            if fd <= 250 and stallSkip(far) then return true end
            State.Text = "Raid: going to " .. far.Name .. " (" .. math.floor(fd) .. " studs)"
            Diag.raid = "raid mob far away: " .. far.Name .. " at " .. math.floor(fd) .. " studs"
            R.fightAt = os.clock()
            -- v39: longe demais? voa rapido ate perto dele; de perto o fightEnemy assume
            if hrp and fp and fd > 250 then
                flyTo(CFrame.new(fp.Position + Vector3.new(0, 30, 0)))
                return true
            end
            bringClear()
            fightEnemy(far, { far.Name }, false)
            return true
        end
        local isl = nearIsland()
        if isl then
            State.Text = "Raid: going to " .. isl.Name
            local off = (isl.Name == "Island 2" and Config.RaidType == "Phoenix") and Vector3.new(300, 60, 0) or Vector3.new(0, 60, 0)
            -- v39: voa direto e rapido (350 studs/s, sem subir antes). O teleporte instantaneo (v37) bugava a raid.
            flyTo(CFrame.new(isl.Position + off))
            return true
        end
        State.Text = "Raid: waiting for mobs"
        pcall(holdHere)
        return true
    end

    -- v71: Auto Unstore (logica do script que o usuario mandou): em segundo plano, sempre que o Auto Pay esta em "Fruit" e nao ha fruta
    -- na mochila/mao, nem chip, nem raid acontecendo, tira do inventario a fruta mais barata permitida (<1M, ou >=1M nas raids avancadas)
    -- e segura o Auto Store por 40 s para ninguem guardar ela de volta.
    do
        local PRICES = { rocket = 5000, spin = 7500, blade = 30000, spring = 60000, bomb = 80000, smoke = 100000, spike = 180000,
            flame = 250000, ice = 350000, sand = 420000, dark = 500000, eagle = 550000, diamond = 600000, light = 650000,
            rubber = 750000, ghost = 940000, magma = 960000, quake = 1000000, buddha = 1200000, love = 1300000, creation = 1400000,
            spider = 1500000, sound = 1700000, phoenix = 1800000, portal = 1900000, rumble = 2100000, pain = 2300000,
            blizzard = 2400000, gravity = 2500000, mammoth = 2700000, trex = 2700000, dough = 2800000, shadow = 2900000,
            venom = 3000000, control = 3200000, spirit = 3400000, dragon = 3500000, leopard = 5000000, kitsune = 8000000 }
        local function priceOf(name)
            local low = tostring(name):lower():gsub("[%s%-_]", "")
            local bk
            for k in pairs(PRICES) do if low:find(k, 1, true) and (not bk or #k > #bk) then bk = k end end
            return bk and PRICES[bk] or nil
        end
        local function readInv()
            local list, seen = {}, {}
            local function add(nm, pr)
                if type(nm) ~= "string" or nm == "" or seen[nm] then return end
                pr = tonumber(pr) or priceOf(nm)
                if not pr or string.find(string.lower(nm), "skin", 1, true) then return end
                seen[nm] = true; list[#list + 1] = { name = nm, price = pr }
            end
            local ok, inv = invoke("getInventoryFruits")
            if ok and type(inv) == "table" then
                for k, v in pairs(inv) do
                    if type(v) == "table" then add(v.Name or v.name or v.FruitName or (type(k) == "string" and k or nil), v.Price or v.price or v.Value)
                    elseif type(v) == "string" then add(v, nil)
                    elseif type(k) == "string" then add(k, nil) end
                end
            end
            table.sort(list, function(x, y) return x.price < y.price end)
            return list
        end
        task.spawn(function()
            while true do
                task.wait(2)
                pcall(function()
                    if not Alive or not (Config.AutoStartRaid or Config.AutoRaid or Config.AutoPay) or Config.PayMode ~= "Fruit" then return end
                    if getSea() == 1 or (R.unstoreAt or 0) > os.clock() then return end
                    if hasChip() or #bagFruits() > 0 or active() or nearIsland() then return end
                    R.unstoreAt = os.clock() + 8
                    local adv = ADVANCED[Config.RaidType] == true
                    for _, f in ipairs(readInv()) do
                        local okp
                        if adv then okp = f.price >= 1000000 and f.price <= 2500000
                        else okp = f.price <= 1000000 end
                        if okp then
                            local variants = { f.name }
                            local base = f.name:gsub(" Fruit$", "")
                            local b2 = base:match("^([^%-]+)%-") or base
                            for _, v in ipairs({ b2 .. "-" .. b2, b2 .. " Fruit", base }) do if not table.find(variants, v) then variants[#variants + 1] = v end end
                            for _, v in ipairs(variants) do
                                Config.PayHoldUntil = os.clock() + 40
                                invoke("LoadFruit", v)
                                if waitFor(function() return #bagFruits() > 0 end, 2) then
                                    Diag.raid = "Auto Pay: took " .. f.name .. " out of storage"
                                    return
                                end
                            end
                        end
                    end
                end)
            end
        end)
    end

    -- true while it is using the character
    raidStep = function()
        if not (Config.AutoStartRaid or Config.AutoRaid or Config.AutoPay) then return false end
        if getSea() == 1 then
            Diag.raid = "Raids only exist in Seas 2 and 3"
            return false
        end
        if active() then
            R.wasActive = true
            if Config.AutoRaid then return fight() end
            return false
        end
        if R.wasActive then R.wasActive, R.doneAt = false, os.clock(); bringClear() end
        if os.clock() - R.doneAt < 6 then
            State.Mode, State.Text = "Raids", "Raid finished: collecting"
            return true
        end
        local now = os.time()
        local chip = hasChip()
        -- v40: acabou de apertar o botao (o chip some na hora): espera a raid comecar, senao o Auto Pay compraria outro chip
        if not chip and os.clock() - R.pressAt < 25 and R.pressAt > 0 then
            State.Mode, State.Text = "Raids", "Waiting for the raid to start"
            return true
        end
        if not chip and Config.AutoPay and now >= R.payAt then
            if getPlayerLevel() < 1100 then
                Diag.raid = "Raids need level 1100+"
                return false
            end
            State.Mode, State.Text = "Raids", "Buying the chip (" .. Config.RaidType .. ")"
            local r = payChip()
            if r == true then R.fails, chip = 0, true
            elseif r == false then
                R.fails += 1
                R.payAt = now + ((R.fails < 3) and 10 or 60)
            else return true end
        end
        if chip and Config.AutoStartRaid and os.clock() - R.pressAt > 12 then
            local btn = raidButton()
            if not btn then
                -- v40: o botao amarelo so carrega perto dele (streaming): voa ate a area da raid (Castle on the Sea no Mar 3)
                local area = scientistCF()
                if area and distanceTo(area) > 25 then
                    State.Mode, State.Text = "Raids", "Going to the raid area"
                    Diag.raid = "Auto Start Raid: flying to the raid area (" .. math.floor(distanceTo(area)) .. " studs) to load the button"
                    flyTo(area * CFrame.new(0, 3, 6))
                    return true
                end
                Diag.raid = "Raid button not found near the raid area (Hot and Cold Island in Sea 2 / Castle on the Sea in Sea 3)"
                return false
            end
            State.Mode = "Raids"
            if distanceTo(btn.CFrame) > 14 then
                State.Text = "Going to the Raid button"
                flyTo(btn.CFrame * CFrame.new(0, 3, 5))
                return true
            end
            State.Text = "Starting the Raid"
            unequip()
            task.wait(0.3)
            pcall(function() fireclickdetector(btn:FindFirstChildOfClass("ClickDetector")) end)
            R.pressAt = os.clock()
            Diag.raid = "button pressed (" .. Config.RaidType .. ")"
            return true
        elseif not chip and Config.AutoStartRaid and not Config.AutoPay then
            Diag.raid = "no Special Microchip (turn on Auto Pay or buy the chip)"
        end
        return false
    end
end

do
    local T = Tabs.Raid
    local function saveKey(k, v) Config[k] = v; persist() end
    T:AddSection("Select Raid")
    local RV = { "Flame", "Sand", "Ice", "Light", "Dark", "Magma", "Quake", "Spider", "Buddha", "Dough", "Phoenix" }
    local ri = 1
    for i, n in ipairs(RV) do if n == Config.RaidType then ri = i end end
    T:AddDropdown("RaidType", {
        Title = "Raid", Description = "Normal: Flame, Sand, Ice, Light, Dark, Magma, Quake, Spider, Buddha (chip = $100,000 or a fruit). Advanced: Dough, Phoenix (chip = 1,000 Fragments or a $1M+ fruit)",
        Values = RV, Default = ri,
    }):OnChanged(function(v) saveKey("RaidType", v) end)
    T:AddSection("Raid Configs")
    local function tg(id, title, desc)
        T:AddToggle(id, { Title = title, Description = desc, Default = Config[id] and true or false }):OnChanged(function(v)
            Config[id] = v; persist()
            if v and getSea() == 1 then
                Fluent:Notify({ Title = "Moon Hub", Content = "Raids only exist in Seas 2 and 3.", Duration = 5 })
            end
        end)
    end
    tg("AutoStartRaid", "Auto Start Raid", "Flies to the raid button (nothing equipped) and starts the selected raid; needs the chip")
    tg("AutoRaid", "Auto Raid", "Kills the raid mobs and moves on to the next island until the raid ends")
    tg("KillAura", "Kill Aura (Raid)", "On every island of the raid, instantly kills every enemy as soon as it spawns instead of fighting them one by one. Needs Auto Raid on")
    tg("RaidBring", "Bring Mob Raid", "Pulls the nearby raid mobs onto the one you are hitting (never the boss) so you kill them together")
    T:AddSlider("RaidBringN", { Title = "Bring Mob Raid (Select Number)", Description = "How many raid mobs are pulled together",
        Min = 2, Max = 12, Default = tonumber(Config.RaidBringN) or 6, Rounding = 0 })
        :OnChanged(function(v) Config.RaidBringN = math.floor(v); persist() end)
    tg("AutoPay", "Auto Pay", "Goes to the Mysterious Scientist and buys the chip of the selected raid (level 1100+)")
    local pm = (Config.PayMode == "Fruit") and 2 or 1
    T:AddDropdown("PayMode", {
        Title = "Pay With", Description = "Money: nothing in hand, once every 2h (Advanced uses Fragments). Fruit: reads every fruit in your inventory and pays with the cheapest allowed one; skins and Mythicals above $2.5M are never used",
        Values = { "Money (Beli)", "Fruit" }, Default = pm,
    }):OnChanged(function(v) saveKey("PayMode", (v == "Fruit") and "Fruit" or "Beli") end)
    T:AddToggle("PayOnly1M", {
        Title = "Pay With -1M Fruit",
        Description = "With Fruit: only Common, Uncommon and Rare fruits below $1M. Off: uses every fruit in your inventory except Mythicals above $2.5M", Default = Config.PayOnly1M and true or false,
    }):OnChanged(function(v) saveKey("PayOnly1M", v) end)
    T:AddToggle("AutoAwaken", { Title = "Auto Awaken", Description = "Awakens the fruit skills with the Awakener when you have the fragments (Quantum: Awakener Check + Awaken)", Default = Config.AutoAwaken and true or false })
        :OnChanged(function(v) Config.AutoAwaken = v; persist() end)
    task.spawn(function()
        while Alive do
            if Config.AutoAwaken then
                pcall(invoke, "Awakener", "Check")
                pcall(invoke, "Awakener", "Awaken")
            end
            task.wait(1.5)
        end
    end)
    T:AddSection("Raid Status")
    local info = T:AddParagraph({ Title = "Raid", Content = "Checking..." })
    task.spawn(function()
        while Alive do
            pcall(function()
                local fr = {}
                local ok, inv = pcall(function() return Player.Backpack:GetChildren() end)
                if ok then for _, t in ipairs(inv) do if t:IsA("Tool") and string.find(t.Name, "Fruit") then fr[#fr + 1] = t.Name end end end
                local chip = false
                for _, c in ipairs({ Player.Backpack, Player.Character }) do if c and c:FindFirstChild("Special Microchip") then chip = true end end
                info:SetDesc(table.concat({
                    "Sea: " .. getSea() .. " | Level: " .. getPlayerLevel(),
                    "Chip: " .. (chip and "YES" or "no") .. " | Raid running: " .. ((AFL.Raid.active and AFL.Raid.active()) and "YES" or "no"),
                    "Fruits in the backpack: " .. (#fr > 0 and table.concat(fr, ", ") or "none"),
                    "Status: " .. tostring(Diag.raid),
                }, "\n"))
            end)
            task.wait(2)
        end
    end)
end


AFL.raidStep = raidStep
