    PC.src["boss"] = function() return [===[
local __E = ...
local AFL = __E.AFL
local Config, Diag, State, Tabs, aliveParts, distanceTo, enemiesList = __E.Config, __E.Diag, __E.State, __E.Tabs, __E.aliveParts, __E.distanceTo, __E.enemiesList
local fightEnemy, flyTo, getSea, invoke, matchName, persist, questVisible = __E.fightEnemy, __E.flyTo, __E.getSea, __E.invoke, __E.matchName, __E.persist, __E.questVisible
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Alive = true
AFL.onUnload(function() Alive = false end);
-- ============ BOSSES (Update 30 names) ============
-- Quest data (quest name, index) comes from memory/wiki and is a best guess; NPC position is unknown, so the quest is requested from where the player is.
AFL.Boss = { list = {}, q = {}, last = 0 }
do
    local B = AFL.Boss
    local defs = {
        -- quest names/indexes confirmed from the game's Quests module (Moon Dump)
        -- Sea 1
        { "The Gorilla King", "JungleQuest", 3 }, { "Chef", "BuggyQuest1", 3 }, { "The Saw", nil }, { "Yeti", "SnowQuest", 3 },
        { "Mob Leader", nil }, { "Vice Admiral", "MarineQuest2", 2 }, { "Saber Expert", nil }, { "Warden", "ImpelQuest", 2 },
        { "Chief Warden", nil }, { "Swan", nil }, { "Magma Admiral", "MagmaQuest", 3 },
        { "Fishman Lord", "FishmanQuest", 3 }, { "Wysper", "SkyExp1Quest", 3 }, { "Thunder God", "SkyExp2Quest", 3 },
        { "Cyborg", "FountainQuest", 3 },
        -- Sea 2
        { "Diamond", "Area1Quest", 3 }, { "Jeremy", "Area2Quest", 3 }, { "Orbitus", "MarineQuest3", 3 }, { "Don Swan", nil },
        { "Smoke Admiral", "IceSideQuest", 3 }, { "Tide Keeper", "ForgottenQuest", 3 },
        { "Darkbeard", nil }, { "Order", nil }, { "Cursed Captain", nil },
        -- Sea 3
        { "Stone", "PiratePortQuest", 3 }, { "Hydra Leader", "VenomCrewQuest", 3 }, { "Kilo Admiral", "MarineTreeIsland", 3 },
        { "Captain Elephant", "DeepForestIsland", 3 }, { "Beautiful Pirate", "DeepForestIsland2", 3 }, { "Cake Queen", "IceCreamIslandQuest", 3 },
        { "Island Empress", nil }, { "Longma", nil }, { "Soul Reaper", nil }, { "rip_indra True Form", nil }, { "Dough King", nil }, { "Cake Prince", nil },
        { "Greybeard", nil }, { "Leviathan", nil }, { "Terrorshark", nil }, { "Tyrant of the Skies", nil },
        { "Deandre", nil }, { "Urban", nil }, { "Diablo", nil }, { "Core", nil },
    }
    -- Select Boss only shows the bosses of the sea you are in (Sea 1 -> Sea 1 bosses, ...)
    local seaOf = {}
    for _, n in ipairs({ "The Gorilla King", "Chef", "The Saw", "Yeti", "Mob Leader", "Vice Admiral", "Saber Expert", "Warden", "Chief Warden",
        "Swan", "Magma Admiral", "Fishman Lord", "Wysper", "Thunder God", "Cyborg", "Greybeard" }) do seaOf[n] = 1 end
    for _, n in ipairs({ "Diamond", "Jeremy", "Orbitus", "Don Swan", "Smoke Admiral", "Tide Keeper", "Darkbeard", "Order", "Cursed Captain", "Core" }) do seaOf[n] = 2 end
    local mySea = getSea()
    for _, d in ipairs(defs) do
        if mySea == 0 or (seaOf[d[1]] or 3) == mySea then B.list[#B.list + 1] = d[1] end
        if d[2] then B.q[d[1]] = { d[2], d[3] } end
    end
end
function AFL.Boss.find()
    local sel, any = Config.BossSel or {}, false
    for _ in pairs(sel) do any = true break end
    if not any then return nil end
    for _, e in ipairs(enemiesList()) do
        local en = e.Name
        for name in pairs(sel) do
            if en == name or string.find(en, name, 1, true) == 1 then
                if aliveParts(e) then return e, name end
                break
            end
        end
    end
end
function AFL.Boss.step()
    if not (Config.BossKill or Config.BossQuest or Config.BossHop) then return false end
    local boss, name = AFL.Boss.find()
    if boss then
        State.Mode, State.Text = "Auto Boss", "Killing " .. boss.Name
        Diag.boss = "killing " .. boss.Name
        if Config.BossQuest and AFL.Boss.q[name] and os.clock() - AFL.Boss.last > 8 then
            local visible, known = questVisible()
            if not (known and visible) then
                AFL.Boss.last = os.clock()
                invoke("StartQuest", AFL.Boss.q[name][1], AFL.Boss.q[name][2])
            end
        end
        if Config.BossKill then
            fightEnemy(boss, { boss.Name }, false)
        else
            local _, r = aliveParts(boss)
            if r and distanceTo(r.CFrame) > 60 then flyTo(r.CFrame * CFrame.new(0, 20, 0)) end
        end
        return true
    end
    -- boss not spawned: model may sit in ReplicatedStorage (like Elite), fly there
    for name in pairs(Config.BossSel or {}) do
        local m = ReplicatedStorage:FindFirstChild(name)
        local part = m and (m:FindFirstChild("HumanoidRootPart") or m.PrimaryPart)
        if part and Config.BossKill then
            State.Mode, State.Text = "Auto Boss", "Going to " .. name
            flyTo(part.CFrame * CFrame.new(0, 20, 0))
            return true
        end
    end
    Diag.boss = "waiting for a selected boss to spawn"
    if Config.BossHop then
        AFL.hopRequest("boss", function() return AFL.Boss.find() ~= nil end)
    end
    return false
end

-- ---- Awakened bosses ----
-- Awakened bosses are triggered by finishing the island secret (see wiki Awakened_Bosses). The Secrets Master tells which one comes next.
AFL.Awk = { names = { "Awakened Gorilla King", "Awakened Chef", "Awakened Yeti", "Awakened Vice Admiral", "Awakened Warden",
    "Awakened Magma General", "Awakened Fishman Lord", "Awakened Cyborg", "Awakened Sky Warlord", "Awakened Thunder God" },
    how = {
        ["Awakened Gorilla King"] = "Jungle [Banana Tree]. Needs The Thief + The Grappling Hook done (NPC Adventurer, -1680,49,176). When the server says something woke in the canopy, hit the big tree near the dock so bananas fall (banana trees ~ -1530,90,-600), then kill the boss",
        ["Awakened Chef"] = "Pirate Village [Chef's Kiss]. Needs Windmill + Tavern Brawl done (Pirate Adventurer, -1152,14,3863). Tavern 2nd floor: Cauldron (-1136,54,4185) -> put the 2 requested ingredients (they change) -> Cook -> kill the Chef",
        ["Awakened Yeti"] = "Frozen Village [Frozen Defense]. Needs Snowballs + Breaking the Ice done (Villager, 1401,77,-1311). When the blizzard stops, destroy the 3 green ice blocks, then kill the Yeti",
        ["Awakened Vice Admiral"] = "Marine Fortress [Battle Plans]. Needs The Flagpole + The Pirate Raid done (Parlus -4832,234,3851 / Marine -4699,5,4228). Use the dock cannons to destroy the 3 marked structure parts (gate -4862,56,4298), then kill him",
        ["Awakened Warden"] = "Prison [Lever Jailbreak]. Needs Escaping Prisoners + Don Megalo done (Jail Keeper, 5208,16,737). Main building ground floor: 4 levers, the combination changes every time (remotes Pull/Release)",
        ["Awakened Magma General"] = "Magma Village [One Last Eruption]. Needs Magma Geyser + Magma Drilling done (Mayor, -5309,17,8483). Destroy the glowing geysers around the volcano, then kill him",
        ["Awakened Fishman Lord"] = "Underwater City [Pearl of the Deep]. Needs Bubble Cave + Mysterious Lights done (King Neptune, 61406,25,1627). Open the Clam Shells (12 in the city) until the Pearl appears, claim it, kill him in the main building",
        ["Awakened Cyborg"] = "Fountain City [Fountain Wire Repair]. Needs Pipe Repair + The Sewer Gang done (Freezeburg Quest Giver, 5263,75,4088). Hit the broken wires at the Cyborg area, then kill him",
        ["Awakened Sky Warlord"] = "Upper Skylands [The Tyrant Awakens]. Needs The Old Temple done (Sky Quest Giver 2, -7033,5591,1353). Destroy the black clouds above the Sky Warlord area, then kill him",
        ["Awakened Thunder God"] = "Upper Skylands [Echoes Through the Clouds]. Mole (-5949,5468,2087). Interact with the Golden Bell (Map.SkyArea2) and hit 6 sequences with the symbol type (sword / gun / melee), then kill him",
    } }
-- v53: so os Awakened dos Island Secrets (Mar 1). Antes qualquer nome com "Awakened" contava (ex.: o Awakened Ice Admiral
-- do Mar 2) e o Auto Awk / Auto Awaken / Combat v2 ficavam presos nele.
function AFL.Awk.find()
    for _, e in ipairs(enemiesList()) do
        local low = string.lower(e.Name)
        if (matchName(e.Name, AFL.Awk.names) or (string.find(low, "awakened", 1, true) and not string.find(low, "ice admiral", 1, true))) and aliveParts(e) then return e end
    end
end
-- v53: o boss acordou mas esta longe (fora do alcance de carregamento): o jogo guarda o modelo no ReplicatedStorage
function AFL.Awk.findFar()
    for _, n in ipairs(AFL.Awk.names) do
        local m = ReplicatedStorage:FindFirstChild(n)
        local p = m and (m:FindFirstChild("HumanoidRootPart") or m.PrimaryPart)
        local h = m and m:FindFirstChildOfClass("Humanoid")
        if p and (not h or h.Health > 0) then return m, p end
    end
end
function AFL.Awk.hint()
    local A = AFL.Awk
    if A.hintAt and os.clock() - A.hintAt < 10 then return A.hintData end
    A.hintAt = os.clock()
    -- v53: pergunta em segundo plano (o InvokeServer travava o laco principal quando o servidor demorava) e guarda a
    -- ultima resposta boa por ate 60 s (antes zerava a dica a cada 10 s e o Auto Awk "esquecia" a ilha sem resposta)
    if A.hintGotAt and os.clock() - A.hintGotAt > 60 then A.hintData = nil end
    if A.hintBusy and os.clock() - (A.hintAskAt or 0) > 20 then A.hintBusy = false end
    if not A.hintBusy then
        A.hintBusy, A.hintAskAt = true, os.clock()
        task.spawn(function()
            pcall(function()
                local m = ReplicatedStorage:FindFirstChild("Modules")
                local net = m and m:FindFirstChild("Net")
                local rf = net and net:FindFirstChild("RF/RequestNextRaidHint")
                if rf then
                    local r = rf:InvokeServer()
                    if typeof(r) == "table" then A.hintData, A.hintGotAt = r, os.clock() end
                end
            end)
            A.hintBusy = false
        end)
    end
    return A.hintData
end
function AFL.Awk.status()
    local e = AFL.Awk.find()
    if e then return "ALIVE: " .. e.Name end
    local h = AFL.Awk.hint()
    if h then
        local st = tostring(h.State)
        if st == "Arming" then return tostring(h.Boss) .. " is about to stir on " .. tostring(h.Island) .. " (get there now)" end
        if st == "Armed" or st == "Triggered" then return tostring(h.Boss) .. " is already up on " .. tostring(h.Island) end
        if st == "Deferred" then return tostring(h.Boss) .. " is waiting to stir on " .. tostring(h.Island) .. " (another fight is blocking)" end
        local mins = math.max(1, math.ceil((tonumber(h.Seconds) or 0) / 60))
        return "Next: " .. tostring(h.Island) .. " (" .. tostring(h.Boss or "?") .. ") in about " .. mins .. " min"
    end
    return "Nothing is stirring right now (the Secrets Master says the same). Next one is announced a few minutes before."
end
AFL.Awk.spots = {
    { "jungle", CFrame.new(-1680, 60, 176) }, { "pirate", CFrame.new(-1136, 70, 4185) }, { "frozen", CFrame.new(1401, 90, -1311) },
    { "marine", CFrame.new(-4862, 70, 4298) }, { "prison", CFrame.new(5208, 30, 737) }, { "magma", CFrame.new(-5309, 30, 8483) },
    { "underwater", CFrame.new(61406, 40, 1627) }, { "fountain", CFrame.new(5263, 90, 4088) },
}
function AFL.Awk.spot(h)
    local isl = string.lower(tostring(h.Island))
    if string.find(isl, "sky", 1, true) then
        if string.find(string.lower(tostring(h.Boss)), "thunder", 1, true) then
            local m = workspace:FindFirstChild("Map")
            local sa = m and m:FindFirstChild("SkyArea2")
            local gb = sa and sa:FindFirstChild("Golden Bell")
            if gb then
                local ok, p = pcall(function() return gb:GetPivot().Position end)
                if ok then return CFrame.new(p + Vector3.new(0, 40, 0)) end
            end
            return CFrame.new(-7070, 5620, 488)
        end
        return CFrame.new(-7033, 5605, 1353)
    end
    for _, sp in ipairs(AFL.Awk.spots) do
        if string.find(isl, sp[1], 1, true) then return sp[2] end
    end
end
-- flies to the hinted island shortly before the boss stirs and keeps the player there (also used by Auto Secret Quest)
function AFL.Awk.waitAt(h, mode)
    if not (h and h.Island) then return false end
    local st = tostring(h.State)
    local soon = st == "Arming" or st == "Armed" or st == "Triggered" or (tonumber(h.Seconds) or 9999) <= 150
    local cf = soon and AFL.Awk.spot(h)
    if not cf then return false end
    State.Mode, State.Text = mode, "Waiting at " .. tostring(h.Island)
    Diag.awk = "waiting at " .. tostring(h.Island) .. " for " .. tostring(h.Boss)
    if distanceTo(cf) > 40 then flyTo(cf) end
    return true
end
function AFL.Awk.step()
    if not Config.AwkOn then return false end
    -- v53: os Awakened bosses so existem no Mar 1 (nos outros mares o Auto Awk ficava "esperando" a toa)
    local okS, sea = pcall(getSea)
    if okS and sea and sea ~= 1 then Diag.awk = "Awakened bosses only spawn in the First Sea"; return false end
    local e = AFL.Awk.find()
    if not e then
        local far, fp = AFL.Awk.findFar()
        if far then
            State.Mode, State.Text = "Auto Awk Boss", "Flying to " .. far.Name
            Diag.awk = far.Name .. " is up but not loaded yet: flying to it"
            flyTo(fp.CFrame * CFrame.new(0, 30, 0))
            return true
        end
    end
    if e then
        State.Mode, State.Text = "Auto Awk Boss", "Awakened: " .. e.Name
        Diag.awk = "killing " .. e.Name
        if true then
            fightEnemy(e, { e.Name }, false)
        else
            local _, r = aliveParts(e)
            if r and distanceTo(r.CFrame) > 60 then flyTo(r.CFrame * CFrame.new(0, 20, 0)) end
        end
        return true
    end
    -- not spawned yet: the server announces the next one (Secrets Master hint); wait at the island shortly before it stirs
    if AFL.Awk.waitAt(AFL.Awk.hint(), "Auto Awk Boss") then return true end
    Diag.awk = "waiting for the next Awakened boss"
    return false
end

-- ---------- Bosses ----------
do
    local function sub(tab, text) pcall(function() tab:AddSection(text) end) end
    local T = Tabs.Bosses
    T:AddSection("Bosses")
    local bd = T:AddDropdown("BossSel", { Title = "Select Boss", Values = AFL.Boss.list, Multi = true, Default = {},
        Description = "Bosses to hunt (Update 30 names)" })
    bd:OnChanged(function(val)
        local set = {}
        if type(val) == "table" then
            for k, x in pairs(val) do
                if x == true then set[k] = true elseif type(x) == "string" then set[x] = true end
            end
        end
        Config.BossSel = set; persist()
    end)
    pcall(function()
        local d = {}
        for k in pairs(Config.BossSel or {}) do d[k] = true end
        bd:SetValue(d)
    end)
    T:AddToggle("BossKill", { Title = "Auto Kill Boss", Default = Config.BossKill and true or false })
        :OnChanged(function(v) Config.BossKill = v; persist() end)
    T:AddToggle("BossQuest", { Title = "Auto Quest Boss", Description = "Takes the boss quest only when no quest is active", Default = Config.BossQuest and true or false })
        :OnChanged(function(v) Config.BossQuest = v; persist() end)
    T:AddToggle("BossHop", { Title = "Auto Hop Boss", Description = "Hops server when the selected boss is not found (Hop in 10 seconds)", Default = Config.BossHop and true or false })
        :OnChanged(function(v) Config.BossHop = v; persist() end)

    T:AddSection("Auto Awk Boss")
    T:AddToggle("AwkOn", { Title = "Auto Awk Boss", Description = "Fully automatic: flies to the island of the next Awakened boss, does its trigger (Chef, Fishman Lord, Warden, Yeti, Magma General, Gorilla King, Cyborg, Sky Warlord) and kills it. Vice Admiral trigger is still manual.", Default = Config.AwkOn and true or false })
        :OnChanged(function(v) Config.AwkOn = v; persist() end)
    T:AddToggle("AwkKill", { Title = "Auto Kill Boss Awk", Default = Config.AwkKill and true or false })
        :OnChanged(function(v) Config.AwkKill = v; persist() end)
    local info = T:AddParagraph({ Title = "Awakened boss", Content = "Checking..." })
    task.spawn(function()
        while Alive do
            local txt = "?"
            pcall(function() txt = AFL.Awk.status() end)
            pcall(function() info:SetDesc(txt) end)
            task.wait(3)
        end
    end)
    for _, n in ipairs(AFL.Awk.names) do
        if AFL.Awk.how[n] then T:AddParagraph({ Title = n, Content = AFL.Awk.how[n] }) end
    end
end



