local aliveParts, cfAttack, currentTween, enemiesList, equipWeapon, fightEnemy, flyTo = __E.aliveParts, __E.cfAttack, __E.currentTween, __E.enemiesList, __E.equipWeapon, __E.fightEnemy, __E.flyTo
local getChar, persist = __E.getChar, __E.persist
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Alive = true
AFL.onUnload(function() Alive = false end);
-- ============ AUTO FARM CHEST ============
-- ============ SECRET QUEST (Island Secrets, Sea 1) ============


-- Automated: the Awakened boss secrets (Gorilla King, Chef, Fishman Lord, Yeti, Cyborg). They spawn about once an hour;
-- the regular boss does not count, so only enemies with "Awakened" in the name are attacked.
AFL.SecretDefs = {
    { "Jungle", "The Thief" }, { "Jungle", "The Grappling Hook" }, { "Jungle", "Awakened Gorilla King", "gorilla" },
    { "Pirate Village", "Free the Windmill" }, { "Pirate Village", "Tavern Brawl" }, { "Pirate Village", "Awakened Chef", "chef" },
    { "Desert", "Saving Hasan" }, { "Desert", "Cleaning the Runes" }, { "Desert", "Prickly Harvest" },
    { "Frozen Village", "Snowballs" }, { "Frozen Village", "Breaking the Ice" }, { "Frozen Village", "Awakened Yeti", "yeti" },
    { "Marine Fortress", "The Flagpole" }, { "Marine Fortress", "The Pirate Raid" }, { "Marine Fortress", "Awakened Vice Admiral", "vice admiral" },
    { "Lower Skylands", "The Mad Scientist's Lightning Bolt" }, { "Lower Skylands", "A Cloudy Treasure" }, { "Lower Skylands", "Invaders in the Castle" },
    { "Upper Skylands", "The Old Temple" }, { "Upper Skylands", "Awakened Sky Warlord", "sky warlord" }, { "Upper Skylands", "Awakened Thunder God", "thunder god" },
    { "Prison", "Escaping Prisoners" }, { "Prison", "Don Megalo" }, { "Prison", "Awakened Warden", "warden" },
    { "Colosseum", "Colosseum Fight" }, { "Colosseum", "The Champion's Statues" }, { "Colosseum", "The Crowd Favorite" },
    { "Magma Village", "The Magma Geyser" }, { "Magma Village", "Magma Drilling" }, { "Magma Village", "Awakened Magma General", "magma general" },
    { "Underwater City", "Bubble Cave" }, { "Underwater City", "Mysterious Lights" }, { "Underwater City", "Awakened Fishman Lord", "fishman" },
    { "Fountain City", "Pipe Repair" }, { "Fountain City", "The Sewer Gang" }, { "Fountain City", "Awakened Cyborg", "cyborg" },
    { "Middle Town", "The Gamer" }, { "Middle Town", "Lookout Duty" }, { "Middle Town", "The Treasure Hunt" },
}
AFL.SecretList, AFL.SecretKey, AFL.SecretManual = {}, {}, {}
for _, d in ipairs(AFL.SecretDefs) do
    local label = d[1] .. " - " .. d[2] 
    AFL.SecretList[#AFL.SecretList + 1] = label
    if d[3] then AFL.SecretKey[label] = d[3] end -- v32: todas automaticas (sem [manual])
end
function AFL.secretFind(key)
    for _, e in ipairs(enemiesList()) do
        local n = string.lower(e.Name)
        if string.find(n, "awakened", 1, true) and string.find(n, key, 1, true) and aliveParts(e) then return e end
    end
end
function AFL.secretStep()
    if not Config.SecretOn then return false end
    local any = false
    for _ in pairs(Config.SecretSel or {}) do any = true break end
    for _, label in ipairs(AFL.SecretList) do
        if AFL.SecretKey[label] and ((not any) or Config.SecretSel[label]) then
            local boss = AFL.secretFind(AFL.SecretKey[label])
            if boss then
                State.Mode, State.Text = "Auto Secret Quest", "Killing " .. boss.Name
                Diag.secret = "killing " .. boss.Name
                fightEnemy(boss, { boss.Name }, false)
                return true
            end
        end
    end
    -- no selected boss alive: if the server announces one of them, wait at its island
    local h = AFL.Awk.hint()
    if h and h.Boss then
        local nm = string.lower(tostring(h.Boss))
        for _, label in ipairs(AFL.SecretList) do
            local key = AFL.SecretKey[label]
            if key and ((not any) or Config.SecretSel[label]) and string.find(nm, key, 1, true) then
                if AFL.Awk.waitAt(h, "Auto Secret Quest") then return true end
            end
        end
    end
    Diag.secret = "waiting for a selected Awakened boss to spawn"
    return false
end


Tabs.Secrets:AddSection("Auto Secret Quest")
Tabs.Secrets:AddToggle("SecretOn", { Title = "Auto Secret Quest",
    Description = "Sea 1 Island Secrets, fully automatic for what you select below (empty = all): flies to each pending secret, kills its enemies, presses its prompts, triggers the Awakened boss of the islands you picked and kills it. It also reports the steps the game client itself reports (crystals, temple, snowman, vault code, Don Megalo...) and logs every try in MoonHub_Secrets_log.txt. Puzzles that need real hits or aiming (statues, cannons, rhythm, lookout) can still need you. Full guide in the Secrets tab.",
    Default = Config.SecretOn and true or false })
    :OnChanged(function(v) Config.SecretOn = v; persist() end)
do
    local sd = Tabs.Secrets:AddDropdown("SecretSel", { Title = "Auto Select Secret Quest", Values = AFL.SecretList, Multi = true, Default = {},
        Description = "Which secrets to automate. Empty = all. Picking an Awakened boss also does the 2 secrets of its island first. Every secret is automatic: flies there, kills the enemies, presses the prompts." })
    sd:OnChanged(function(val)
        local set = {}
        if type(val) == "table" then
            for k, x in pairs(val) do
                if x == true then set[k] = true elseif type(x) == "string" then set[x] = true end
            end
        end
        for label in pairs(set) do
            if AFL.SecretManual[label] and not (Config.SecretSel or {})[label] then
                Fluent:Notify({ Title = "Secret Quest", Content = label .. ": no boss to kill here - Auto Secret Quest will fly to its NPC and run the steps it knows.", Duration = 6 })
            end
        end
        Config.SecretSel = set
        persist()
    end)
    pcall(function()
        local m = {}
        for k, x in pairs(Config.SecretSel or {}) do if x == true then m[k] = true end end
        sd:SetValue(m)
    end)
end

