    S.byLabel = {}
    for _, d in ipairs(S.defs) do S.byLabel[d[1] .. " - " .. d[2]] = d end

    local function labelKey(l) return (string.gsub(tostring(l), " %[manual%]$", "")) end

    -- progresso real do servidor (RF/RequestBonusMomentReplication {Type="GetMomentProgress"} -> {Data = {[id]=true}})
    function S.refresh(force)
        -- v53: o servidor nao respondeu em 15 s: libera para perguntar de novo (antes o "busy" ficava preso e o progresso parava)
        if S.busy and os.clock() - S.at > 15 then S.busy = false end
        if S.busy or (not force and os.clock() - S.at < 20) then return S.done end
        S.busy, S.at = true, os.clock()
        task.spawn(function()
            pcall(function()
                local m = ReplicatedStorage:FindFirstChild("Modules")
                local net = m and m:FindFirstChild("Net")
                local rf = net and net:FindFirstChild("RF/RequestBonusMomentReplication")
                if rf then
                    local r = rf:InvokeServer({ Type = "GetMomentProgress" })
                    if typeof(r) == "table" and typeof(r.Data) == "table" then S.done = r.Data end
                end
            end)
            S.busy = false
        end)
        return S.done
    end
    function S.isDone(d) return S.done ~= nil and S.done[d[3]] == true end
    function S.summary()
        local done = S.refresh(false)
        if not done then return "Progress not loaded yet (press Refresh Progress)." end
        local n, pend = 0, {}
        for _, d in ipairs(S.defs) do
            if S.isDone(d) then n = n + 1 else pend[#pend + 1] = d[1] .. " - " .. d[2] end
        end
        if #pend == 0 then return "All " .. n .. "/" .. #S.defs .. " secrets done." end
        local shown = {}
        for i = 1, math.min(#pend, 8) do shown[i] = pend[i] end
        return n .. "/" .. #S.defs .. " done. Pending: " .. table.concat(shown, "; ") .. (#pend > 8 and (" ... +" .. (#pend - 8)) or "")
    end

    -- ---------- ajudante (Secret Assist): voa ate o NPC/local do proximo secret pendente e aperta so os prompts conhecidos ----------
    local function selected(d)
        local sel, any = Config.SecretSel or {}, false
        for _ in pairs(sel) do any = true break end
        if not any or Config.SubC2 then return true end
        if sel[d[1] .. " - " .. d[2]] or sel[d[1] .. " - " .. d[2] .. " [manual]"] then return true end
        -- escolheu o Awakened de uma ilha: os 2 secrets dela sao pre-requisito, entram na lista sozinhos
        for _, x in ipairs(S.defs) do
            if x[1] == d[1] and string.find(x[2], "Awakened", 1, true) and sel[x[1] .. " - " .. x[2]] then return true end
        end
        return false
    end
    -- o Awakened (por chave) esta na selecao? (vazia = todos)
    function S.bossSelected(bossName)
        local sel, any = Config.SecretSel or {}, false
        for _ in pairs(sel) do any = true break end
        local nm = string.lower(tostring(bossName))
        if Config.SubC2 then return true end
        for _, label in ipairs(AFL.SecretList) do
            local key = AFL.SecretKey[label]
            if key and string.find(nm, key, 1, true) then
                return (not any) or sel[label] == true
            end
        end
        return not any
    end
    local function scanPrompts(center, want)
        local out = {}
        local map = workspace:FindFirstChild("Map") or workspace
        for _, o in ipairs(map:GetDescendants()) do
            if o:IsA("ProximityPrompt") and o.Enabled then
                local txt = string.lower((o.ActionText or "") .. " " .. (o.ObjectText or ""))
                for _, w in ipairs(want) do
                    if string.find(txt, w, 1, true) then
                        local par = o.Parent
                        local pos = par and (par:IsA("BasePart") and par.Position or (par:IsA("Attachment") and par.WorldPosition))
                        if pos and (pos - center).Magnitude < 160 then out[#out + 1] = { o, pos } end
                        break
                    end
                end
            end
        end
        return out
    end
    function S.assist()
        if not assistOn() then return false end
        -- v53: os Island Secrets sao do Mar 1
        S.refresh(false)
        S.firstTry = S.firstTry or os.clock()
        -- v62: o servidor nao respondeu o progresso em 25 s: assume nada feito e segue (antes ficava parado para sempre, ex.: 7 h AFK sem fazer nada)
        if not S.done and os.clock() - S.firstTry > 25 then S.done = {}; S.guess = true end
        if S.guess and S.at and os.clock() - S.at > 120 then S.firstTry = os.clock() - 20; S.done = nil; S.guess = nil end   -- tenta ler o progresso de novo
        local okSea, sea = pcall(__E.getSea)
        if okSea and sea and sea ~= 1 then
            -- v62: os Island Secrets sao do Mar 1: se ainda ha secret pendente na selecao, viaja para o Mar 1 sozinho (antes so avisava e ficava parado)
            local pend = false
            if S.done then
                for _, x in ipairs(S.defs) do
                    if selected(x) and not S.isDone(x) and not string.find(x[2], "Awakened", 1, true) then pend = true break end
                end
            end
            if pend and os.clock() - (S.travelAt or 0) > 25 then
                S.travelAt = os.clock()
                pcall(function() __E.invoke("TravelMain") end)
            end
            Diag.secret = pend and ("assist: traveling to the First Sea (you are in Sea " .. tostring(sea) .. ")") or ("assist: Island Secrets are in the First Sea (you are in Sea " .. tostring(sea) .. ")")
            if pend then State.Mode, State.Text = "Auto Secret Quest", "Traveling to the First Sea" end
            return pend
        end
        if not S.done then Diag.secret = "assist: waiting for the secret progress"; return false end
        local now = os.clock()
        local d = S.cur
        if d and (S.isDone(d) or not selected(d) or now - S.curSince > (autoOn() and 300 or 90)) then
            if not S.isDone(d) and selected(d) then S.skip[d[3]] = now + 180 end
            d, S.cur, S.arrived = nil, nil, nil
        end
        local _, hrp = getChar()
        if not hrp then return false end
        if not d then
            -- v53: pega o secret pendente MAIS PERTO (antes ia sempre no primeiro da lista, atravessando o mapa)
            local bd
            for _, x in ipairs(S.defs) do
                if selected(x) and not S.isDone(x) and (S.skip[x[3]] or 0) < now and not string.find(x[2], "Awakened", 1, true) then
                    local dd = (hrp.Position - x[5]).Magnitude
                    if not bd or dd < bd then d, bd = x, dd end
                end
            end
            if not d then Diag.secret = "assist: nothing pending in the selection"; return false end
            S.cur, S.curSince, S.arrived = d, now, nil
        end
        State.Mode, State.Text = "Auto Secret Quest", d[1] .. " - " .. d[2]
        local pos = d[5] + Vector3.new(0, 3, 0)
        local dist = (hrp.Position - pos).Magnitude
        -- v53: depois de chegar no NPC, a missao pode levar o personagem ate ~1200 studs dali (inimigos, prompts, objetos).
        -- Antes, a cada passo (>30 studs do NPC) ele voava de volta para o NPC e largava a missao: vai-e-volta sem fim.
        if dist <= 30 then S.arrived = d end
        if S.arrived ~= d or dist > 1200 then
            if dist > 1200 then S.arrived = nil end
            Diag.secret = "assist: flying to " .. d[4] .. " (" .. d[1] .. ")"
            flyTo(CFrame.new(pos))
            return true
        end
        Diag.secret = "assist: at " .. d[4] .. " - " .. d[2] .. " (do the steps; known prompts are pressed)"
        if autoOn() and S.autoStep then
            local okA, handled = pcall(S.autoStep, d)
            if okA and handled then return true end
            if not okA then Diag.secret = "auto error: " .. tostring(handled) end
        end
        if #d[7] > 0 and fireproximityprompt and now - (S.lastScan or 0) > 4 then
            S.lastScan = now
            for _, pr in ipairs(scanPrompts(d[5], d[7])) do
                local p, at = pr[1], pr[2]
                if (hrp.Position - at).Magnitude > 12 then
                    flyTo(CFrame.new(at + Vector3.new(0, 3, 0)))
                    return true
                end
                pcall(fireproximityprompt, p, 1)
            end
        end
        -- nada para fazer longe do NPC: volta para perto dele (espera a mensagem / o evento do secret)
        if dist > 30 then flyTo(CFrame.new(pos)) end
        return true
    end
    local origStep = AFL.secretStep
    AFL.secretStep = function()
        local ok, r = pcall(origStep)
        if ok and r then return true end
        if Config.SecretOn then
            local okT, rT = pcall(S.trigger, true)
            if okT and rT then return true end
        end
        local ok2, r2 = pcall(S.assist)
        return ok2 and r2 or false
    end

    -- ---------- catalogo de texto ----------
    S.remotesTxt = [[
SECRETS - REMOTES (all verified in the dumps)
ReplicatedStorage.Remotes.BonusMomentsRemoteEvent:FireServer(<ModuleName>, ...)   -- every secret uses this
ReplicatedStorage.Remotes.BonusMomentsRemoteFunction:InvokeServer(<ModuleName>, ...)
  per-secret verbs: ClaimHat, TakeRope, Hoist, Start, BreakDoor, ReadLetter, CutsceneDone, GuardsOut, Provoke, BeginFight, IsBruteActive, Collect,
  OpenChest, Initialize, Complete, OpenClam, ClaimPearl, OpenCauldron, Insert, Cook, CloseCauldron, GetState, GrabSnowball, BallLost, Pull, Release,
  BouncerReady, TakeKey, Unlock, TakeCape, StartMatch, State, Struck, PickupMap, CollectCheckpoint, ClaimTreasure, FinishFinale
Net (ReplicatedStorage.Modules.Net):
  RF/RequestBonusMomentReplication({Type="GetMomentProgress"}) -> {Data={["Sea1/<Island>/<Moment>"]=true,...}}
  RF/RequestSecretStories({Type="GetPhase"}) -> {Phase="Repair"|"Locked"|...}
  RF/RequestNextRaidHint() -> {State="Dormant|Arming|Armed|Triggered|Deferred", Boss, Island, Seconds, Rumor={...}}   -- next Awakened boss
  RF/BonusMomentsGuide("InteractQuestGiver", <name>) / ("GetRewardTracker")
  RF/RequestMomentEventStages, RE/OnBonusMomentReplicatedChange, RE/MomentEventStage, RF/BossCutscene, RF/GetPlayerFlag, RF/GetManyPlayerFlags
NPC to ask which Awakened boss is next: Secrets Master (-839, 28, 1603)
]]
    local function guideFor(island)
        local lines, npcs = {}, {}
        for _, d in ipairs(S.defs) do
            if d[1] == island then
                if not npcs[d[4]] then
                    npcs[d[4]] = true
                    lines[#lines + 1] = "NPC: " .. d[4] .. " (" .. math.floor(d[5].X) .. ", " .. math.floor(d[5].Y) .. ", " .. math.floor(d[5].Z) .. ")"
                end
            end
        end
        for _, d in ipairs(S.defs) do
            if d[1] == island then
                lines[#lines + 1] = "* " .. d[2] .. " [" .. string.match(d[3], "([^/]+)$") .. "]: " .. d[6]
            end
        end
        return table.concat(lines, "\n")
    end
    local islands, seenIsl = {}, {}
    for _, d in ipairs(S.defs) do if not seenIsl[d[1]] then seenIsl[d[1]] = true; islands[#islands + 1] = d[1] end end

    -- ---------- Auto Awaken: faz o gatilho de cada Awakened boss ----------
    -- Alta confianca (codigo lido): Chef (OpenCauldron/Insert/Cook), Fishman Lord (OpenClam/ClaimPearl), Warden (Pull nas 4 alavancas, testa as ordens).
    -- Media/baixa (acerta o objeto com o item/skills escolhidos em Vulcan "rocks"): Yeti (iceRock), Magma General (geiseres), Gorilla King (arvore).
    -- Novos: Cyborg (fios Broken, M1), Sky Warlord (voa ate a arena do evento; nuvens por nome = palpite), Thunder God (so vai ao sino), Vice Admiral (sentar no canhao + clicar = palpite).
    S.log, S.evInst, S.t, S.cool, S.began, S.hitN = {}, {}, {}, {}, {}, setmetatable({}, { __mode = "k" })
    S.evPos, S.evAt = {}, {}
    function S.ser(x, depth)
        local t = typeof(x)
        if t == "Instance" then return x:GetFullName() end
        if t == "Vector3" then return string.format("V3(%.0f,%.0f,%.0f)", x.X, x.Y, x.Z) end
        if t == "table" then
            if depth > 0 then return "{...}" end
            local out, n = {}, 0
            for k, v in pairs(x) do
                n = n + 1
                if n > 6 then out[#out + 1] = "..."; break end
                out[#out + 1] = tostring(k) .. "=" .. S.ser(v, 1)
            end
            return "{" .. table.concat(out, ",") .. "}"
        end
        return tostring(x)
    end
    local function rem(name)
        local f = ReplicatedStorage:FindFirstChild("Remotes")
        return f and f:FindFirstChild(name)
    end
    task.spawn(function()
        local f = ReplicatedStorage:WaitForChild("Remotes", 10)
        local re = f and f:WaitForChild("BonusMomentsRemoteEvent", 10)
        if not re then return end
        re.OnClientEvent:Connect(function(...)
            local a, parts, insts = { ... }, {}, {}
            for i = 1, math.min(#a, 6) do
                local x = a[i]
                if typeof(x) == "Instance" then insts[#insts + 1] = x
                elseif typeof(x) == "Vector3" and type(a[1]) == "string" then S.evPos[a[1]], S.evAt[a[1]] = x, os.clock()
                elseif typeof(x) == "CFrame" and type(a[1]) == "string" then S.evPos[a[1]], S.evAt[a[1]] = x.Position, os.clock()
                elseif typeof(x) == "table" and type(a[1]) == "string" and a[2] == "Setup" then
                    -- One Last Eruption: Setup(moment, {[i]=CFrame}) = lugares das fissuras
                    local pts = {}
                    for _, v in pairs(x) do if typeof(v) == "CFrame" then pts[#pts + 1] = v.Position end end
                    if #pts > 0 then S.evPts = S.evPts or {}; S.evPts[a[1]] = pts end
                end
                parts[i] = S.ser(x, 0)
            end
            S.log[#S.log + 1] = os.date("%H:%M:%S") .. " " .. table.concat(parts, " | ")
            if #S.log > 80 then table.remove(S.log, 1) end
            if #insts > 0 and type(a[1]) == "string" then S.evInst[a[1]] = insts end
        end)
    end)
    local function posOf(inst)
        if not inst then return end
        if inst:IsA("BasePart") then return inst.Position end
        local ok, p = pcall(function() return inst:GetPivot().Position end)
        if ok then return p end
    end
    local function near(pos, r, up)
        local _, hrp = getChar()
        if not hrp then return false end
        if (hrp.Position - pos).Magnitude > r then
            flyTo(CFrame.new(pos + Vector3.new(0, up or 3, 0)))
            return false
        end
        return true
    end
    local function every(key, sec)
        if os.clock() - (S.t[key] or 0) < sec then return false end
        S.t[key] = os.clock()
        return true
    end
    local function mapChild(...)
        local c = workspace
        for _, n in ipairs({ ... }) do
            c = c and c:FindFirstChild(n)
        end
        return c
    end

    -- Chef: workspace.Map.Pirate.Cauldron_Moment.Cauldron ; remote "Chef's Kiss"
    local function chefRun()
        local c = mapChild("Map", "Pirate", "Cauldron_Moment", "Cauldron")
        local pos = posOf(c) or V(-1136, 54, 4185)
        if not near(pos, 11, 5) then Diag.awk = "Auto Awaken (Chef): flying to the cauldron"; return true end
        if not every("chef", 4) then return true end
        local rf = rem("BonusMomentsRemoteFunction")
        if not rf then Diag.awk = "Auto Awaken (Chef): remote not found"; return false end
        local ok, st = pcall(rf.InvokeServer, rf, "Chef's Kiss", "OpenCauldron")
        if not ok or typeof(st) ~= "table" then Diag.awk = "Auto Awaken (Chef): cauldron not open yet (" .. tostring(st) .. ")"; return true end
        local placed = {}
        for _, m in ipairs(st.Placed or {}) do placed[m] = true end
        local missing = {}
        for _, m in ipairs(st.Recipe or {}) do
            if not placed[m] then
                local ok2, r = pcall(rf.InvokeServer, rf, "Chef's Kiss", "Insert", m)
                if ok2 and r then placed[m] = true else missing[#missing + 1] = m .. " (owned " .. tostring((st.Owned or {})[m] or 0) .. ")" end
            end
        end
        if #missing > 0 then
            Diag.awk = "Auto Awaken (Chef): missing ingredients: " .. table.concat(missing, ", ")
            pcall(function() rem("BonusMomentsRemoteEvent"):FireServer("Chef's Kiss", "CloseCauldron") end)
            return true
        end
        local ok3, r3 = pcall(rf.InvokeServer, rf, "Chef's Kiss", "Cook")
        Diag.awk = "Auto Awaken (Chef): cooked -> " .. tostring(r3)
        pcall(function() rem("BonusMomentsRemoteEvent"):FireServer("Chef's Kiss", "CloseCauldron") end)
        return true
    end

    -- Fishman Lord: Map.Fishmen.Clams.Clam1..12 -> OpenClam(clam) ("Black" = the pearl clam) -> ClaimPearl
    S.fish = { done = {}, tries = {}, pearl = nil, pearlAt = 0 }
    local function fishRun()
        local clams = mapChild("Map", "Fishmen", "Clams")
        if not clams then Diag.awk = "Auto Awaken (Fishman): Clams folder not found"; return false end
        local F = S.fish
        local rf = rem("BonusMomentsRemoteFunction")
        if not rf then return false end
        if F.pearl then
            local pos = posOf(F.pearl) or V(61300, 20, 1600)
            if not near(pos, 9, 3) then return true end
            if os.clock() - F.pearlAt < 1.3 or not every("fishclaim", 1.5) then return true end
            local ok, r = pcall(rf.InvokeServer, rf, "Pearl of the Deep", "ClaimPearl")
            Diag.awk = "Auto Awaken (Fishman): ClaimPearl -> " .. tostring(r)
            if ok and r == true then F.pearl = nil end
            return true
        end
        for _, c in ipairs(clams:GetChildren()) do
            if not F.done[c] and (F.tries[c] or 0) < 3 then
                local pos = posOf(c)
                if pos then
                    Diag.awk = "Auto Awaken (Fishman): opening " .. c.Name
                    if not near(pos, 9, 3) then return true end
                    if not every("fishopen", 1.2) then return true end
                    F.tries[c] = (F.tries[c] or 0) + 1
                    local ok, r = pcall(rf.InvokeServer, rf, "Pearl of the Deep", "OpenClam", c)
                    if ok and r == "Black" then F.pearl, F.pearlAt = c, os.clock(); F.done[c] = true
                    elseif ok and r then F.done[c] = true end
                    return true
                end
            end
        end
        Diag.awk = "Auto Awaken (Fishman): all clams tried"
        return false
    end

    -- Warden: levers sorted by X then Z ; Pull(i) -> {Result="Accepted"|"Solved"|other}. Tries the orders step by step, replaying the prefix after a miss.
    S.lev = { prefix = {}, tried = {}, replay = nil, n = 0 }
    local function leverList()
        local loc = mapChild("Map", "Prison")
        local folder = loc and loc:FindFirstChild("BonusMoment_Locations", true)
        if not folder then
            local m = workspace:FindFirstChild("Map")
            folder = m and m:FindFirstChild("BonusMoment_Locations", true)
        end
        local lv = folder and folder:FindFirstChild("Levers")
        local out = {}
        for _, c in ipairs(lv and lv:GetChildren() or {}) do
            local arm = c:IsA("Model") and c:FindFirstChild("Lever")
            if arm and arm:IsA("BasePart") then out[#out + 1] = arm end
        end
        table.sort(out, function(a, b)
            if math.abs(a.Position.X - b.Position.X) > 0.001 then return a.Position.X < b.Position.X end
            return a.Position.Z < b.Position.Z
        end)
        return out
    end
    local function wardenRun()
        local lv = leverList()
        if #lv == 0 then Diag.awk = "Auto Awaken (Warden): levers not loaded (get closer to the main building)"; return false end
        local c = V(0, 0, 0)
        for _, a in ipairs(lv) do c = c + a.Position end
        c = c / #lv
        if not near(c, 14, 4) then Diag.awk = "Auto Awaken (Warden): flying to the levers"; return true end
        if not every("lever", 0.8) then return true end
        local rf = rem("BonusMomentsRemoteFunction")
        if not rf then return false end
        local L = S.lev
        local idx
        if L.replay and #L.replay > 0 then idx = table.remove(L.replay, 1)
        else
            L.tried[#L.prefix + 1] = L.tried[#L.prefix + 1] or {}
            local used = {}
            for _, i in ipairs(L.prefix) do used[i] = true end
            for i = 1, #lv do
                if not used[i] and not L.tried[#L.prefix + 1][i] then idx = i; break end
            end
            if not idx then L.prefix, L.tried, L.replay = {}, {}, nil; Diag.awk = "Auto Awaken (Warden): no order worked, restarting"; return true end
        end
        local ok, r = pcall(rf.InvokeServer, rf, "Lever Jailbreak", "Pull", idx)
        local res = ok and typeof(r) == "table" and r.Result or nil
        L.n = L.n + 1
        Diag.awk = "Auto Awaken (Warden): pull " .. idx .. " -> " .. tostring(res) .. " (known order: " .. table.concat(L.prefix, ",") .. ")"
        if L.replay then
            if res ~= "Accepted" and res ~= "Solved" then L.prefix, L.tried, L.replay = {}, {}, nil end
            return true
        end
        if res == "Accepted" then L.prefix[#L.prefix + 1] = idx
        elseif res == "Solved" then L.prefix = {}; L.tried = {}
        elseif res ~= nil then
            L.tried[#L.prefix + 1][idx] = true
            if #L.prefix > 0 then L.replay = { table.unpack(L.prefix) } end
        end
        return true
    end

    -- acerta um objeto com o item/skills de "break rocks" escolhidos na aba Vulcan (ou M1 se nada escolhido)
    local function hitObject(obj, label)
        local pos = posOf(obj)
        if not pos then return false end
        Diag.awk = "Auto Awaken (" .. label .. "): hitting " .. obj.Name
        if not near(pos, 16, 7) then return true end
        S.hitN[obj] = (S.hitN[obj] or 0) + 1
        local part = obj:IsA("BasePart") and obj or obj:FindFirstChildWhichIsA("BasePart", true)
        local used = false
        if part and AFL.Vulc and AFL.Vulc.useSet then
            local ok, u = pcall(AFL.Vulc.useSet, "VulcRockW", "VulcRockK", part)
            used = ok and u
        end
        if not used then
            pcall(equipWeapon)
            if part then Aim.part = part end
            pcall(cfAttack)
            pcall(function()
                local tool = Player.Character and Player.Character:FindFirstChildOfClass("Tool")
                if tool then tool:Activate() end
            end)
        end
        return true
    end
    local function pickHit(list, label)
        for _, o in ipairs(list) do
            if o.Parent and (S.hitN[o] or 0) < 30 then return hitObject(o, label) end
        end
        Diag.awk = "Auto Awaken (" .. label .. "): nothing left to hit"
        return false
    end
    local function yetiRun()
        local ice = mapChild("Map", "Ice")
        local folder = (ice and ice:FindFirstChild("BonusMoment_Locations", true)) or (workspace:FindFirstChild("Map") and workspace.Map:FindFirstChild("BonusMoment_Locations", true))
        local list = {}
        for _, c in ipairs(folder and folder:GetChildren() or {}) do
            if c.Name == "iceRock" and c:IsA("BasePart") and c.Transparency < 0.95 and c:GetAttribute("FrozenDefenseRockPresent") ~= false then list[#list + 1] = c end
        end
        return pickHit(list, "Yeti")
    end
    local function magmaRun()
        local list = {}
        if every("magmascan", 6) or not S.magma then
            S.magma = {}
            -- as fissuras (Model "MagmaFissure") sao criadas pelo cliente direto em workspace; o "Vent" fica dentro delas
            for _, d in ipairs(workspace:GetChildren()) do
                if d.Name == "MagmaFissure" and d:IsA("Model") then S.magma[#S.magma + 1] = d end
            end
            for _, root in ipairs({ workspace:FindFirstChild("Map"), workspace:FindFirstChild("_WorldOrigin"), workspace.Terrain }) do
                for _, d in ipairs(root:GetDescendants()) do
                    if (d.Name == "LavaGeyser" or d.Name == "MagmaFissure") and (d:IsA("Model") or d:IsA("BasePart")) then
                        S.magma[#S.magma + 1] = d
                    end
                end
            end
        end
        for _, d in ipairs(S.magma) do if d.Parent then list[#list + 1] = d end end
        if #list == 0 then
            -- fissuras ainda nao abertas: vai ate o primeiro ponto que o servidor mandou em Setup
            local pts = S.evPts and S.evPts["One Last Eruption"]
            if pts and #pts > 0 then
                Diag.awk = "Auto Awaken (Magma General): flying to the fissure spots the server sent"
                near(pts[1], 40, 15)
                return true
            end
        end
        return pickHit(list, "Magma General")
    end
    local function gorillaRun()
        local list = {}
        for _, x in ipairs(S.evInst["Banana Tree"] or {}) do if x.Parent and (x:IsA("Model") or x:IsA("BasePart")) then list[#list + 1] = x end end
        if #list == 0 then
            local jungle = mapChild("Map", "Jungle")
            for _, d in ipairs(jungle and jungle:GetDescendants() or {}) do
                if d.Name == "JungleTree" and d:IsA("Model") and d:FindFirstChild("BananaLeaf", true) then list[#list + 1] = d end
            end
            local _, hrp = getChar()
            if hrp then table.sort(list, function(a, b) return (posOf(a) - hrp.Position).Magnitude < (posOf(b) - hrp.Position).Magnitude end) end
        end
        return pickHit(list, "Gorilla King")
    end
    -- Cyborg: partes com atributo FountainWireRole == "Broken" (reparadas com M1; o modulo marca "Repaired" quando acerta)
    local function cyborgRun()
        if every("wirescan", 4) or not S.wires then
            S.wires = {}
            for _, root in ipairs({ workspace:FindFirstChild("_WorldOrigin"), workspace:FindFirstChild("Map") }) do
                for _, d in ipairs(root:GetDescendants()) do
                    if d:IsA("BasePart") and d:GetAttribute("FountainWireRole") == "Broken" then S.wires[#S.wires + 1] = d end
                end
            end
        end
        local list = {}
        for _, w in ipairs(S.wires) do
            if w.Parent and w:GetAttribute("FountainWireRole") == "Broken" then list[#list + 1] = w end
        end
        if #list == 0 then
            Diag.awk = "Auto Awaken (Cyborg): no broken wires loaded yet - flying to the Fountain City quest giver"
            near(V(5263, 75, 4088), 40, 10)
            return true
        end
        return pickHit(list, "Cyborg")
    end
    -- Sky Warlord: o evento Awakened manda o centro da arena (Vector3). Nuvens negras: palpite pelo nome.
    local function warlordRun()
        local p = S.evPos["The Tyrant Awakens"]
        if p and os.clock() - (S.evAt["The Tyrant Awakens"] or 0) > 1200 then p = nil end
        if every("cloudscan", 6) or not S.clouds then
            S.clouds = {}
            local sky = mapChild("Map", "SkyArea2")
            for _, d in ipairs(sky and sky:GetDescendants() or {}) do
                local n = string.lower(d.Name)
                if (d:IsA("BasePart") or d:IsA("Model")) and (string.find(n, "stormcloud", 1, true) or string.find(n, "blackcloud", 1, true) or string.find(n, "darkcloud", 1, true)) then
                    local dp = posOf(d)
                    if dp and (not p or (dp - p).Magnitude < 600) then S.clouds[#S.clouds + 1] = d end
                end
            end
        end
        local list = {}
        for _, c in ipairs(S.clouds) do if c.Parent then list[#list + 1] = c end end
        if #list > 0 then return pickHit(list, "Sky Warlord") end
        if p then
            Diag.awk = "Auto Awaken (Sky Warlord): at the arena the server sent; black clouds not found by name - destroy them by hand"
            near(p, 60, 25)
            return true
        end
        Diag.awk = "Auto Awaken (Sky Warlord): waiting for the server event with the arena position"
        return false
    end
    -- Thunder God: vai ao Golden Bell e aperta os prompts perto. A parte do ritmo e manual.
    -- ---- Echoes Through the Clouds (Thunder God): o servidor manda "Listen"(notas, inicio, batida, perfeito, bom); cada nota e um tipo
    -- (Melee / Sword / Fruit / Gun) e tem que ser acertada no sino em Start + (i-1)*Beat (janela "Good"). Detecta o tipo na hora e usa o item certo ----
    S.echo = { token = 0, until_ = 0 }
    S.echoTip = { Melee = "Melee", Sword = "Sword", Gun = "Gun", Fruit = "Blox Fruit" }
    local function noteType(n)
        if type(n) == "string" then return n end
        if type(n) == "table" then return n.Type or n.type or n.Kind or n.kind or n[1] end
        return nil
    end
    local function findTool(typ)
        local tip = S.echoTip[typ] or typ
        local ch = Player.Character
        for _, c in ipairs({ ch, Player:FindFirstChild("Backpack") }) do
            for _, t in ipairs(c and c:GetChildren() or {}) do
                if t:IsA("Tool") and t.ToolTip == tip then return t end
            end
        end
        return nil
    end
    function S.echoHit(typ, part)
        local tool = findTool(typ)
        if not tool then S.slog("Echoes: no " .. tostring(typ) .. " item found in the backpack"); return false end
        local ch = Player.Character
        local hum = ch and ch:FindFirstChildOfClass("Humanoid")
        if hum and tool.Parent ~= ch then pcall(function() hum:EquipTool(tool) end); task.wait(0.05) end
        if part then Aim.part = part end
        pcall(cfAttack)
        pcall(function() tool:Activate() end)
        if typ == "Fruit" then
            pcall(function()
                local vim = game:GetService("VirtualInputManager")
                vim:SendKeyEvent(true, Enum.KeyCode.Z, false, game)
                task.wait(0.05)
                vim:SendKeyEvent(false, Enum.KeyCode.Z, false, game)
            end)
        end
        return true
    end
    function S.echoRound(notes, start, beat)
        S.echo.token = S.echo.token + 1
        local my = S.echo.token
        local bell = mapChild("Map", "SkyArea2", "Golden Bell")
        local part = bell and (bell:IsA("BasePart") and bell or bell:FindFirstChildWhichIsA("BasePart", true))
        S.echo.until_ = os.clock() + (#notes) * (tonumber(beat) or 1) + 12
        task.spawn(function()
            for i, n in ipairs(notes) do
                if S.echo.token ~= my then return end
                local typ = noteType(n)
                local target = start + (i - 1) * beat
                -- equipa o item da proxima nota um pouco antes
                while workspace:GetServerTimeNow() < target - 0.45 and S.echo.token == my do task.wait(0.03) end
                local tool = typ and findTool(typ)
                local ch = Player.Character
                local hum = ch and ch:FindFirstChildOfClass("Humanoid")
                if tool and hum and tool.Parent ~= ch then pcall(function() hum:EquipTool(tool) end) end
                while workspace:GetServerTimeNow() < target - 0.04 and S.echo.token == my do task.wait(0.01) end
                if S.echo.token ~= my then return end
                S.echoHit(typ, part)
                S.slog(string.format("Echoes note %d/%d %s at %.2f (target %.2f)", i, #notes, tostring(typ), workspace:GetServerTimeNow(), target))
                Diag.awk = string.format("Auto Awaken (Thunder God): note %d/%d = %s", i, #notes, tostring(typ))
            end
        end)
    end
    task.spawn(function()
        local rs = ReplicatedStorage:WaitForChild("Remotes", 20)
        local re = rs and rs:WaitForChild("BonusMomentsRemoteEvent", 20)
        if not re then return end
        re.OnClientEvent:Connect(function(mod, ev, ...)
            if mod ~= "Echoes Through the Clouds" then return end
            local a = { ... }
            S.slog("Echoes event " .. tostring(ev) .. " n=" .. #a)
            if ev == "Listen" and (Config.AwkOn or Config.AwkTrigger or Config.SecretOn) and type(a[1]) == "table" and tonumber(a[2]) and tonumber(a[3]) then
                pcall(S.echoRound, a[1], tonumber(a[2]), tonumber(a[3]))
            end
        end)
    end)
    local function thunderRun(h)
        local bell = mapChild("Map", "SkyArea2", "Golden Bell")
        local pos = posOf(bell)
        if not pos then
            local cf = AFL.Awk.spot and AFL.Awk.spot(h)
            pos = cf and cf.Position
        end
        if not pos then Diag.awk = "Auto Awaken (Thunder God): bell not found"; return false end
        if not near(pos, 25, 8) then Diag.awk = "Auto Awaken (Thunder God): flying to the Golden Bell"; return true end
        if os.clock() < (S.echo.until_ or 0) then Diag.awk = "Auto Awaken (Thunder God): playing the notes with the right item"; return true end
        if fireproximityprompt and every("bell", 3) then
            for _, pr in ipairs(scanPrompts(pos, { "" })) do pcall(fireproximityprompt, pr[1], 1) end
        end
        Diag.awk = "Auto Awaken (Thunder God): at the Golden Bell, started - waiting for the notes"
        return true
    end
    -- Vice Admiral: canhoes MarineBusterCannon (Seat). Palpite: sentar e clicar. Sem mira automatica.
    local function viceRun()
        if every("cannonscan", 8) or not S.cannons then
            S.cannons = {}
            local m = workspace:FindFirstChild("Map")
            for _, d in ipairs(m and m:GetDescendants() or {}) do
                if d.Name == "BonusMoment_Locations" then
                    for _, c in ipairs(d:GetChildren()) do
                        local seat = c.Name == "MarineBusterCannon" and c:FindFirstChild("Seat")
                        if seat and seat:IsA("BasePart") then S.cannons[#S.cannons + 1] = seat end
                    end
                end
            end
        end
        local _, hrp = getChar()
        local best
        for _, st in ipairs(S.cannons) do
            if st.Parent and hrp and (not best or (st.Position - hrp.Position).Magnitude < (best.Position - hrp.Position).Magnitude) then best = st end
        end
        if not best then Diag.awk = "Auto Awaken (Vice Admiral): cannons not loaded - go to the Marine Fortress docks"; near(V(-4630, 74, 4037), 40, 10); return true end
        if not near(best.Position, 10, 4) then Diag.awk = "Auto Awaken (Vice Admiral): flying to the cannon"; return true end
        local hum = Player.Character and Player.Character:FindFirstChildOfClass("Humanoid")
        if hum and hum.SeatPart ~= best and every("sit", 3) then pcall(function() best:Sit(hum) end) end
        if hum and hum.SeatPart == best and mouse1click and getgenv().MoonWinOn() and every("fire", 1.3) then pcall(mouse1click) end
        Diag.awk = "Auto Awaken (Vice Admiral): on the cannon, clicking (GUESS - aim at the 3 marked parts by hand if nothing happens)"
        return true
    end
    S.routines = {
        { key = "chef", run = chefRun }, { key = "fishman", run = fishRun }, { key = "warden", run = wardenRun },
        { key = "yeti", run = yetiRun }, { key = "magma", run = magmaRun }, { key = "gorilla", run = gorillaRun },
        { key = "cyborg", run = cyborgRun }, { key = "sky warlord", run = warlordRun }, { key = "thunder", alt = "lightning", run = thunderRun }, { key = "vice", alt = "admiral", run = viceRun },
    }
    function S.trigger(onlySel)
        if AFL.Awk.find() or AFL.Awk.findFar() then return false end   -- v53: boss ja acordado (perto ou longe): agora e so matar
        local okS, sea = pcall(__E.getSea)
        if okS and sea and sea ~= 1 then return false end
        local h = AFL.Awk.hint()
        if not (h and h.Boss) then return false end
        local st = tostring(h.State)
        if not (st ~= "Dormant" or (tonumber(h.Seconds) or 9999) <= 150) then return false end
        local boss, now = string.lower(tostring(h.Boss)), os.clock()
        if onlySel and not S.bossSelected(boss) then return false end
        for _, r in ipairs(S.routines) do
            if string.find(boss, r.key, 1, true) or (r.alt and string.find(boss, r.alt, 1, true)) then
                if (S.cool[r.key] or 0) > now then return false end
                S.began[r.key] = S.began[r.key] or now
                if now - S.began[r.key] > 420 then S.cool[r.key], S.began[r.key] = now + 300, nil; return false end
                State.Mode, State.Text = "Auto Awk Boss", "Awakening " .. tostring(h.Boss)
                local ok, res = pcall(r.run, h)
                if not ok then Diag.awk = "Auto Awaken error: " .. tostring(res); return false end
                return res and true or false
            end
        end
        Diag.awk = "Auto Awaken: no automatic trigger for " .. tostring(h.Boss) .. " yet - do it by hand (see the guide), the script kills it afterwards"
        return false
    end
    local origAwk = AFL.Awk.step
    AFL.Awk.step = function()
        if Config.AwkOn then   -- Auto Awk Boss agora faz tudo: voa, acorda (gatilho automatico) e mata
            local ok, r = pcall(S.trigger)
            if ok and r then return true end
        end
        return origAwk()
    end

