    local function enemyByNames(names, center, r)
        for _, e in ipairs(enemiesList()) do
            local n = string.lower(e.Name)
            for _, w in ipairs(names) do
                if string.find(n, w, 1, true) then
                    local eh, er = aliveParts(e)
                    if eh and (not center or (er.Position - center).Magnitude <= r) then return e end
                    break
                end
            end
        end
    end
    local function findPrompts(words)
        local key = table.concat(words, "|")
        S.pcache = S.pcache or {}
        local c = S.pcache[key]
        if not c or os.clock() - c.at > 3 then
            c = { at = os.clock(), list = {} }
            S.pcache[key] = c
            local map = workspace:FindFirstChild("Map") or workspace
            for _, o in ipairs(map:GetDescendants()) do
                if o:IsA("ProximityPrompt") then
                    local txt = string.lower((o.ActionText or "") .. " " .. (o.ObjectText or ""))
                    for _, w in ipairs(words) do
                        if string.find(txt, w, 1, true) then c.list[#c.list + 1] = o; break end
                    end
                end
            end
        end
        return c.list
    end
    -- ---------- passos que o proprio CLIENTE do jogo reporta ao servidor (lidos do codigo do jogo) ----------
    -- "I" = BonusMomentsRemoteFunction:InvokeServer(modulo, verbo), "F" = BonusMomentsRemoteEvent:FireServer(modulo, verbo).
    -- Se o servidor recusar (estado errado) so devolve false/nil; tudo e registrado em MoonHub_Secrets_log.txt
    S.force = {
        ["Fishman Karate"] = { { "I", "Initialize" }, { "I", "Complete" } },
        ["Temple Intel"] = { { "I", "TakeIntel" }, { "F", "Solved" } },
        ["Snowman"] = { { "F", "Init" }, { "F", "Finished" } },
        ["Zipline Repair"] = { { "F", "Initialize" }, { "F", "PickupTool" } },
        ["X Marks The Spot"] = { { "F", "Initialize" }, { "F", "PickupMap" }, { "F", "CollectCheckpoint" } },
        ["Don Megalo"] = { { "I", "TakeKey" }, { "I", "Unlock" }, { "I", "TakeCape" }, { "I", "ClaimCape" } },
        ["Tavern Brawl"] = { { "F", "ClaimReward" } },
        ["The Thieving Monkey"] = { { "F", "Initialize" }, { "I", "ReturnHat" } },
        ["Rescue Hasan"] = { { "F", "StartWaves" } },
        ["Fountain Pipe Repair"] = { { "I", "TurnIn" } },
        ["Pearl of the Deep"] = { { "I", "ClaimPearl" } },
    }
    S.forceTries = {}
    function S.slog(t)
        pcall(function() if appendfile then appendfile("MoonHub_Secrets_log.txt", string.format("[%s] %s\n", os.date("%H:%M:%S"), t)) end end)
    end
    function S.forceRun(d)
        local mod = string.match(d[3], "([^/]+)$")
        S.forceTries[d[3]] = (S.forceTries[d[3]] or 0) + 1
        if S.forceTries[d[3]] > 8 then return end
        local rf, re = rem("BonusMomentsRemoteFunction"), rem("BonusMomentsRemoteEvent")
        if mod == "Unexpected Guest" then
            -- cofre do Angelic Vault: o servidor entrega os codigos do jogador (VaultCodes) e confere com TryCode
            if rf then
                local ok, codes = pcall(rf.InvokeServer, rf, mod, "VaultCodes")
                S.slog("Unexpected Guest VaultCodes -> " .. tostring(ok) .. " " .. typeof(codes) .. " " .. tostring(codes))
                local list = {}
                if type(codes) == "table" then for _, v in pairs(codes) do list[#list + 1] = tostring(v) end
                elseif codes ~= nil then list[1] = tostring(codes) end
                for _, c in ipairs(list) do
                    local ok2, r = pcall(rf.InvokeServer, rf, mod, "TryCode", c)
                    S.slog("Unexpected Guest TryCode " .. c .. " -> " .. tostring(r))
                    if r == true then pcall(rf.InvokeServer, rf, mod, "TakeChest") break end
                end
            end
            return
        end
        for _, st in ipairs(S.force[mod] or {}) do
            local kind, verb = st[1], st[2]
            local r
            if kind == "I" and rf then
                local ok, res = pcall(rf.InvokeServer, rf, mod, verb)
                r = tostring(ok) .. " " .. tostring(res)
            elseif kind == "F" and re then
                pcall(re.FireServer, re, mod, verb)
                r = "fired"
            end
            S.slog(mod .. " " .. kind .. ":" .. verb .. " -> " .. tostring(r))
            task.wait(0.4)
        end
    end
    -- ---------- objetos que precisam ser acertados (nomes lidos do codigo do jogo); item = tipo do ataque ----------
    S.hitDefs = {
        ["Sea1/Desert/Archaeologist's Tablet"] = { names = { "rune" }, types = { "Melee", "Sword" } },
        ["Sea1/Frozen Village/Breaking the Ice"] = { names = { "iceberg", "frozentrainer" }, types = { "Melee", "Sword" } },
        ["Sea1/Desert/Prickly Harvest"] = { names = { "cacti", "cactus" }, types = { "Melee", "Sword" } },
        ["Sea1/Pirate Village/Windmill Maintenance"] = { names = { "rope" }, types = { "Sword" } },
        ["Sea1/Magma Village/Evil Slimes"] = { names = { "slimegeyser" }, types = { "Melee", "Sword" } },
        ["Sea1/Colosseum/Crowd Favorite"] = { names = { "target" }, types = { "Gun" } },
        ["Sea1/Sky/Electric Fighting Teacher"] = { names = { "stormcloud", "darkcloud", "lightningcloud" }, types = { "Melee", "Sword", "Gun" } },
        ["Sea1/SkyArea2/Temple Intel"] = { names = { "templeintelstormcloud" }, types = { "Melee", "Sword", "Gun" } },
        ["Sea1/Jungle/Banana Tree"] = { names = { "banana" }, types = { "Melee", "Sword" } },
    }
    S.hitCount = setmetatable({}, { __mode = "k" })
    S.statue = { pass = {} }
    function S.statueList()
        local out = {}
        local okM, PodiumClient = pcall(function() return require(ReplicatedStorage.ClientComponents.PodiumClient) end)
        if not okM or not PodiumClient then return out end
        local okA, all = pcall(function() return PodiumClient:GetAll() end)
        for _, v in pairs(okA and type(all) == "table" and all or {}) do
            local mdl
            pcall(function() mdl = v:GetModel() end)
            local pt = v.PodiumType
            if mdl and pt then out[#out + 1] = { model = mdl, typ = (pt == "Demon Fruit") and "Fruit" or pt } end
        end
        return out
    end
    function S.hitStep(d, hrp)
        local now = os.clock()
        -- estatuas
        if d[3] == "Sea1/Colosseum/Legendary Creator Statues" then
            local list = S.statueList()
            for _, st in ipairs(list) do
                local n = S.statue.pass[st.model] or 0
                if n < 14 and st.model.Parent then
                    local pos = st.model:GetPivot().Position
                    Diag.secret = "auto: statue " .. tostring(st.typ) .. " (" .. n .. ")"
                    State.Mode, State.Text = "Auto Secret Quest", d[2] .. ": hitting a " .. tostring(st.typ) .. " statue"
                    if not near(pos, 9, 3) then return true end
                    if every("statuehit", 0.8) then
                        S.statue.pass[st.model] = n + 1
                        local part = st.model:FindFirstChildWhichIsA("BasePart", true)
                        S.echoHit(st.typ, part)
                        S.slog("statue " .. tostring(st.typ) .. " hit " .. (n + 1))
                    end
                    return true
                end
            end
            return false
        end
        local hd = S.hitDefs[d[3]]
        if not hd then return false end
        -- procura objetos pelo nome perto do NPC (Map e _WorldOrigin)
        local key = "hitscan" .. d[3]
        S.hitCache = S.hitCache or {}
        local c = S.hitCache[key]
        if not c or now - c.at > 3 then
            c = { at = now, list = {} }
            S.hitCache[key] = c
            for _, rootName in ipairs({ "Map", "_WorldOrigin" }) do
                local root = workspace:FindFirstChild(rootName)
                for _, o in ipairs(root and root:GetDescendants() or {}) do
                    if o:IsA("BasePart") then
                        local nm = string.lower(o.Name)
                        local pn = o.Parent and string.lower(o.Parent.Name) or ""
                        for _, w in ipairs(hd.names) do
                            if string.find(nm, w, 1, true) or string.find(pn, w, 1, true) then
                                if (o.Position - d[5]).Magnitude <= 900 then c.list[#c.list + 1] = o end
                                break
                            end
                        end
                    end
                    if #c.list >= 60 then break end
                end
            end
        end
        local best, bd
        for _, o in ipairs(c.list) do
            if o.Parent and (S.hitCount[o] or 0) < 12 then
                local dd = (o.Position - hrp.Position).Magnitude
                if not bd or dd < bd then best, bd = o, dd end
            end
        end
        if not best then return false end
        Diag.secret = "auto: hitting " .. best.Name
        State.Mode, State.Text = "Auto Secret Quest", d[2] .. ": hitting " .. best.Name
        if not near(best.Position, 12, 5) then return true end
        if every("secrethit", 0.7) then
            S.hitCount[best] = (S.hitCount[best] or 0) + 1
            local typ = hd.types[(S.hitCount[best] - 1) % #hd.types + 1]
            S.echoHit(typ, best)
        end
        return true
    end
    function S.autoStep(d)
        local now = os.clock()
        local _, hrp = getChar()
        if not hrp then return false end
        -- 1) inimigos da missao
        local names = S.fightNames[d[3]]
        local e = names and enemyByNames(names, d[5], 900)
        if e then
            State.Mode, State.Text = "Auto Secret Quest", d[2] .. ": fighting " .. e.Name
            Diag.secret = "auto: fighting " .. e.Name
            fightEnemy(e, { e.Name }, false)
            return true
        end
        -- 1b) estatuas do Coliseu (cada uma pede um tipo: o servidor/cliente guarda PodiumType) e objetos que precisam ser acertados
        do
            local okH, hres = pcall(S.hitStep, d, hrp)
            if okH and hres then return true end
        end
        -- 2) prompts do mapa todo (inclusive os criados pelo modulo no cliente, ex: Don Megalo)
        if #d[7] > 0 and fireproximityprompt then
            local best, bd
            for _, o in ipairs(findPrompts(d[7])) do
                if o.Parent and o.Enabled then
                    local par = o.Parent
                    local pos = par:IsA("BasePart") and par.Position or (par:IsA("Attachment") and par.WorldPosition)
                    -- v53: so prompts da ilha deste secret (antes podia voar ate um "pick up" de outra ilha)
                    if pos and (pos - d[5]).Magnitude <= 1500 then
                        local dist = (pos - hrp.Position).Magnitude
                        if not bd or dist < bd then best, bd = o, dist end
                    end
                end
            end
            if best then
                local par = best.Parent
                local pos = par:IsA("BasePart") and par.Position or par.WorldPosition
                Diag.secret = "auto: prompt '" .. tostring(best.ActionText) .. " " .. tostring(best.ObjectText) .. "'"
                if not near(pos, math.max(6, math.min(best.MaxActivationDistance - 3, 10)), 3) then return true end
                if best.HoldDuration > 0.5 then
                    if now - (S.holdAt or 0) > best.HoldDuration + 1.5 then
                        S.holdAt = now
                        task.spawn(function()
                            pcall(function() best:InputHoldBegin() end)
                            task.wait(best.HoldDuration + 0.4)
                            pcall(function() best:InputHoldEnd() end)
                        end)
                    end
                elseif every("autoprompt", 1) then
                    pcall(fireproximityprompt, best, 1)
                end
                return true
            end
        end
        -- 3) verbos seguros
        local pk = S.pokes[d[3]]
        if pk and every("poke" .. d[3], 10) then
            local rf, re = rem("BonusMomentsRemoteFunction"), rem("BonusMomentsRemoteEvent")
            local mod = string.match(d[3], "([^/]+)$")
            for _, v in ipairs(pk) do
                if rf then pcall(rf.InvokeServer, rf, mod, v) end
                if re then pcall(re.FireServer, re, mod, v) end
            end
        end
        -- 4) passos que o cliente do jogo reporta sozinho (depois de uns 20 s no local, tenta de tempos em tempos, no maximo 8 vezes)
        if now - (S.curSince or now) > 20 and every("force" .. d[3], 15) then pcall(S.forceRun, d) end
        return false
    end

    -- ---------- UI ----------
    local sel = { label = nil }
    local token = nil
    local function travel(pos, label)
        local mine = {}
        token = mine
        Fluent:Notify({ Title = "Moon Hub - Secrets", Content = "Flying to " .. tostring(label), Duration = 3 })
        task.spawn(function()
            local t0, lastClip = os.clock(), 0
            while Alive and token == mine and os.clock() - t0 < 150 do
                local char, hrp = getChar()
                if not hrp then break end
                if os.clock() - lastClip > 0.25 then
                    lastClip = os.clock()
                    for _, p in ipairs(char:GetDescendants()) do
                        if p:IsA("BasePart") then p.CanCollide = false end
                    end
                end
                if (hrp.Position - pos).Magnitude < 6 then break end
                flyTo(CFrame.new(pos))
                task.wait(0.2)
            end
            if token == mine then token = nil end
            if currentTween then currentTween:Cancel() end
        end)
    end

