    PC.src["chest"] = function() return [===[
local __E = ...
local AFL = __E.AFL
local Config, State, currentTween, findToolByName, flyTo, getChar = __E.Config, __E.State, __E.currentTween, __E.findToolByName, __E.flyTo, __E.getChar;
AFL.Chest = { n = 0, bl = setmetatable({}, { __mode = "k" }), cur = nil, since = 0, noneSince = nil, tour = nil, tourI = 1, tourAt = 0, dwell = nil, restUntil = 0 }
function AFL.chestList()
    local out, seen = {}, {}
    local function add(inst)
        if seen[inst] or (AFL.Chest.bl[inst] or 0) > os.clock() then return end
        local part = inst:IsA("BasePart") and inst or (inst:IsA("Model") and (inst.PrimaryPart or inst:FindFirstChildWhichIsA("BasePart", true)))
        if part and part:IsDescendantOf(workspace) then
            seen[inst] = true
            out[#out + 1] = { inst = inst, part = part }
        end
    end
    pcall(function()
        for _, c in ipairs(game:GetService("CollectionService"):GetTagged("_ChestTagged")) do add(c) end
    end)
    local folder = workspace:FindFirstChild("ChestModels")
    if folder then
        for _, c in ipairs(folder:GetChildren()) do add(c) end
    end
    pcall(function()
        for _, c in ipairs(workspace:GetChildren()) do
            if string.match(c.Name, "^Chest%d") then add(c) end
        end
    end)
    return out
end
-- Island tour: chests only exist near the player, so with none loaded he flies over every island of the map
function AFL.chestTourBuild(from)
    local list = {}
    local map = workspace:FindFirstChild("Map")
    if map then
        for _, m in ipairs(map:GetChildren()) do
            if m:IsA("Model") then
                local ok, sz = pcall(function() return m:GetExtentsSize() end)
                if ok and sz.Magnitude > 150 then
                    local ok2, cf = pcall(function() return m:GetPivot() end)
                    -- v76: ignora modelos de agua/limite do mar e pivos no nivel do mar ou abaixo (o hub voava para a agua no Sea 2)
                    local nm = m.Name:lower()
                    local bad = nm:find("water", 1, true) or nm:find("ocean", 1, true) or nm:find("sea", 1, true) or nm:find("fog", 1, true)
                        or nm:find("border", 1, true) or nm:find("barrier", 1, true) or nm:find("boundary", 1, true) or nm:find("skybox", 1, true)
                    if ok2 and not bad and cf.Position.Y > 3 then list[#list + 1] = cf.Position end
                end
            end
        end
    end
    local out, cur = {}, from
    while #list > 0 do
        local bi, bd = 1, math.huge
        for i, p in ipairs(list) do
            local d = (p - cur).Magnitude
            if d < bd then bi, bd = i, d end
        end
        cur = table.remove(list, bi)
        out[#out + 1] = cur
    end
    return out
end
-- opts (v24, usado pelo Auto Fully): { hop = bool, count = n } troca as opcoes Chest Hop / Chest Count so nesta chamada
function AFL.chestStep(opts)
    local C = AFL.Chest
    local _, hrp = getChar()
    if not hrp then return false end
    local hop, count = Config.ChestHop, Config.ChestCount or 10
    if type(opts) == "table" then
        if opts.hop ~= nil then hop = opts.hop and true or false end
        if opts.count then count = tonumber(opts.count) or count end
    end
    -- reached the chosen amount: stop collecting and (with Chest Hop) change server
    if hop and C.n >= count then
        State.Mode, State.Text = "Auto Farm Chest", string.format("%d/%d chests: changing server", C.n, count)
        AFL.hopRequest("chests collected (" .. C.n .. ")", function() return findToolByName and findToolByName("fist of darkness") ~= nil end)
        return false
    end
    if C.cur then
        local gone = (not C.cur.inst.Parent) or (not C.cur.part.Parent) or (not C.cur.part:IsDescendantOf(workspace))
        if gone then
            C.n += 1
            C.cur = nil
        elseif C.touchAt and os.clock() - C.touchAt > 1.2 then
            C.n += 1
            C.bl[C.cur.inst] = os.clock() + 600
            C.cur = nil
        elseif os.clock() - C.since > 25 then
            C.bl[C.cur.inst] = os.clock() + 120
            C.cur = nil
        end
    end
    if not C.cur then
        C.touchAt = nil
        local best, bd = nil, math.huge
        for _, ch in ipairs(AFL.chestList()) do
            local d = (ch.part.Position - hrp.Position).Magnitude
            if d < bd then best, bd = ch, d end
        end
        if best then
            C.cur, C.since, C.noneSince, C.dwell = best, os.clock(), nil, nil
        else
            -- no chest loaded: visit the islands one by one (hover above each for a moment so its chests load)
            if os.clock() >= C.restUntil then
                if not C.tour then C.tour, C.tourI, C.tourAt, C.dwell = AFL.chestTourBuild(hrp.Position), 1, os.clock(), nil end
                local tgt = C.tour[C.tourI]
                if tgt then
                    C.noneSince = nil
                    State.Mode = "Auto Farm Chest"
                    State.Text = string.format("Searching chests: island %d/%d (%d collected)", C.tourI, #C.tour, C.n)
                    local goal = tgt + Vector3.new(0, 90, 0)
                    if (hrp.Position - goal).Magnitude > 60 and os.clock() - C.tourAt < 40 then
                        flyTo(CFrame.new(goal))
                        return true
                    end
                    C.dwell = C.dwell or (os.clock() + 1.5)
                    if os.clock() < C.dwell then return true end
                    C.tourI, C.tourAt, C.dwell = C.tourI + 1, os.clock(), nil
                    return true
                end
                C.tour, C.restUntil = nil, os.clock() + 30 -- tour finished: rest 30s before the next one
            end
            C.noneSince = C.noneSince or os.clock()
            State.Mode, State.Text = "Auto Farm Chest", "no chests left (" .. C.n .. " collected)"
            if hop and os.clock() - C.noneSince > 60 then AFL.hopRequest("no chests in this server") end
            return false
        end
    end
    State.Mode = "Auto Farm Chest"
    State.Text = string.format("Collecting chest (%d collected%s)", C.n, hop and ("/" .. tostring(count)) or "")
    local part = C.cur.part
    if (hrp.Position - part.Position).Magnitude > 12 then
        C.touchAt = nil
        flyTo(part.CFrame)
    else
        if currentTween then currentTween:Cancel() end
        pcall(function()
            hrp.CFrame = part.CFrame
            hrp.AssemblyLinearVelocity = Vector3.zero
            if firetouchinterest then
                firetouchinterest(hrp, part, 0)
                firetouchinterest(hrp, part, 1)
            end
        end)
        C.touchAt = C.touchAt or os.clock()
    end
    return true
end




