    PC.src["stack"] = function() return [===[
local __E = ...
local AFL = __E.AFL
local Config, Diag, EliteNames, EliteS, Fluent, State, Tabs = __E.Config, __E.Diag, __E.EliteNames, __E.EliteS, __E.Fluent, __E.State, __E.Tabs
local Window, activeQuestTitle, aliveParts, distanceTo, enemiesList, fightEnemy, findEnemy = __E.Window, __E.activeQuestTitle, __E.aliveParts, __E.distanceTo, __E.enemiesList, __E.fightEnemy, __E.findEnemy
local flyTo, getChar, getSea, invoke, isEliteTitle, persist, questVisible = __E.flyTo, __E.getChar, __E.getSea, __E.invoke, __E.isEliteTitle, __E.persist, __E.questVisible
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local E = __E;
-- ============ STACK FARM: Pirate Raid (Mar 3), Elite Hunter (Mar 3), Factory (Mar 2) ============
-- Mobs dos Mares 1 e 2 (nomes exatos) - no Mar 3 so aparecem durante o Pirate Raid. Lidos da tabela do Level Farm do Premium.
local RaidSet = {}
do
    local D = E.LV and E.LV.DATA or {}
    local sea3 = {}
    for _, q in ipairs(D[3] or {}) do sea3[q.mob] = true end
    for _, sea in ipairs({ 1, 2 }) do
        for _, q in ipairs(D[sea] or {}) do
            if not sea3[q.mob] then RaidSet[q.mob] = true end
        end
    end
end
-- v28: anti-fantasma comum aos 3 farms do Stack - se o alvo nao perde vida por 15s (preso/rede), ignora por 45s e troca
-- (antes de so ir matar quando spawnar, as vezes ficava "preso" no mesmo mob que nao morria)
local StackBad = setmetatable({}, { __mode = "k" })
local StackTrack = nil
local function stackHp(m)
    local h = m:FindFirstChildOfClass("Humanoid")
    return h and h.Health
end
local function stackStall(target)
    local now = os.clock()
    local hp = stackHp(target)
    local tr = StackTrack
    if not tr or tr.m ~= target then tr = { m = target, hp = hp, since = now }; StackTrack = tr end
    if hp and tr.hp and hp < tr.hp - 0.01 then tr.hp, tr.since = hp, now
    elseif hp and (not tr.hp or hp > tr.hp) then tr.hp = hp end
    if now - tr.since > 15 then
        StackBad[target] = now + 45
        StackTrack = nil
        return true
    end
    return false
end
-- ============ STACK FARM (sempre na frente do Normal Farm) ============
-- Mar 3: Pirate Raid - mobs dos Mares 1/2 aparecem perto do Castle on the Sea (a cada ~1h15)
local PR = { lastSeen = 0, lastProbe = 0, probeUntil = 0 }
local PIRATE_POINT = CFrame.new(-5539, 313, -2972) -- Castle on the Sea (posição aproximada)
-- v100: pedido do usuario - o NPC "Tank" (dropa fruta) tem prioridade de morte sobre qualquer outro mob da raid,
-- mesmo que esteja mais longe. Ele NAO entra no RaidSet (que so cobre os mobs normais dos Mares 1/2 usados nas
-- quests do Level Farm) - por isso o match e por nome (contem "tank", sem diferenciar maiusculas), igual outras
-- listas de nome parcial do script (BEAST etc), e tratado como alvo valido por fora do filtro RaidSet.
local function isTankMob(name)
    return type(name) == "string" and string.find(string.lower(name), "tank", 1, true) ~= nil
end
-- v66: deteccao do Pirate Raid igual o bomba.lua: quando a raid esta rolando, os modelos dos mobs aparecem como filhos do
-- ReplicatedStorage / do workspace (mesmo antes de carregarem perto de voce) - e o bomba voa ate (-5496, 313, -2841).
local PR_NAMES = {}
for _, n in ipairs({ "Galley Pirate", "Galley Captain", "Raider", "Mercenary", "Vampire", "Zombie", "Snow Trooper", "Winter Warrior",
    "Lab Subordinate", "Horned Warrior", "Magma Ninja", "Lava Pirate", "Ship Deckhand", "Ship Engineer", "Ship Steward", "Ship Officer",
    "Arctic Warrior", "Snow Lurker", "Sea Soldier", "Water Fighter" }) do PR_NAMES[n] = true end
local PR_CASTLE = CFrame.new(-5496, 313.8, -2841.5)
local function prSignal()
    local okR, rs = pcall(function() return game:GetService("ReplicatedStorage") end)
    if okR and rs then
        for _, c in ipairs(rs:GetChildren()) do if PR_NAMES[c.Name] then return true end end
    end
    for _, c in ipairs(workspace:GetChildren()) do if PR_NAMES[c.Name] then return true end end
    local en = workspace:FindFirstChild("Enemies")
    if en then
        for _, c in ipairs(en:GetChildren()) do
            if PR_NAMES[c.Name] then
                local r = c:FindFirstChild("HumanoidRootPart")
                if r and (r.Position - PR_CASTLE.Position).Magnitude <= 2000 then return true end
            end
        end
    end
    return false
end
local function pirateRaidStep()
    local _, hrp = getChar()
    if not hrp then return false end
    local tankOn = Config.PirateTankPriority ~= false
    local best, bestDist, bestIsTank = nil, math.huge, false
    for _, e in ipairs(enemiesList()) do
        local isTank = tankOn and isTankMob(e.Name)
        if (isTank or RaidSet[e.Name]) and not ((StackBad[e] or 0) > os.clock()) then
            local eh, er = aliveParts(e)
            if eh then
                local d = (hrp.Position - er.Position).Magnitude
                if isTank and not bestIsTank then
                    best, bestDist, bestIsTank = e, d, true           -- primeiro Tank visto: assume na hora, mesmo que mais longe
                elseif isTank == bestIsTank and d < bestDist then
                    best, bestDist = e, d                              -- mesma "classe" (os dois Tank ou os dois normais): o mais perto
                end
            end
        end
    end
    local now = os.clock()
    if best then
        PR.lastSeen = now
        if stackStall(best) then return true end
        State.Mode = "Auto Pirate Raid"
        State.Text = (bestIsTank and "Killing TANK (fruit drop) " or "Killing ") .. best.Name
        fightEnemy(best, { best.Name }, true)
        return true
    end
    -- v61 fix: "esperando a proxima onda" e "indo olhar o castelo" devolviam true mesmo sem nenhum mob pra matar -
    -- isso "travava" a prioridade (nada de prioridade mais baixa rodava enquanto o Pirate Raid so ficava parado
    -- esperando). Agora so devolve true quando REALMENTE tem o que fazer (matando ou de fato indo pra uma raid que
    -- ja comecou); esperar/checar o castelo continua rodando em segundo plano mas deixa o resto da prioridade livre.
    -- Os mobs da raid só carregam perto do Castle on the Sea. Entre uma onda e outra, fica por lá.
    -- v66: raid detectada pelo sinal do bomba (mobs no ReplicatedStorage/workspace): voa ate o castelo e fica la (seguro: 5 min
    -- no castelo sem nenhum mob da raid = desiste por 10 min)
    if now >= (PR.backoff or 0) and prSignal() then
        if distanceTo(PR_CASTLE) > 500 then
            PR.lastSeen = now
            PR.arrivedAt = nil
            State.Mode, State.Text = "Auto Pirate Raid", "Raid detected: flying to the Castle on the Sea"
            flyTo(PR_CASTLE * CFrame.new(0, 40, 0))
            return true
        end
        PR.arrivedAt = PR.arrivedAt or now
        if now - PR.arrivedAt > 300 then
            PR.backoff, PR.arrivedAt = now + 600, nil
        else
            PR.lastSeen = now
            State.Mode, State.Text = "Auto Pirate Raid", "At the Castle: waiting for the raid mobs"
            return true
        end
    end
    if now - PR.lastSeen < 25 then
        State.Mode, State.Text = "Auto Pirate Raid", "Waiting for the next wave"
        -- com o Break Pumpkins ligado, nao puxa o personagem de volta ao castelo (as duas funcoes brigavam pelo voo)
        if not (Config.PumpOn or Config.PumpHop) and distanceTo(PIRATE_POINT) > 150 then flyTo(PIRATE_POINT * CFrame.new(0, 40, 0)) end
        return false
    end
    -- v100: pedido do usuario - "se ele tiver longe do castelo ele vai voando ate la pra fazer a raid pirata".
    -- Antes, com "Events Only When They Spawn" ligado (Farm Settings - vem ligado por padrao), o Pirate Raid NUNCA
    -- ia olhar o castelo (so matava se um mob da raid ja estivesse carregado por acaso perto de voce) - o castelo e
    -- um unico ponto fixo onde a raid inteira acontece, bem diferente de "rodar o mapa atras de fruta" (que e o que
    -- esse toggle foi feito pra evitar), entao o Pirate Raid passa a ignorar esse toggle e sempre ir conferir.
    -- Sem raid à vista: a cada 90s vai ao Castle olhar se ela começou (tempo da viagem + 6s)
    -- v67: pedido do usuario - so vai ao castelo quando o evento COMECA (sinal acima). Sem raid, nao viaja mais para conferir.
    return false
end

-- Mar 3: Elite Hunter - pega a quest e mata o Deandre / Urban / Diablo
local EliteAsk = 0
-- NPC Elite Hunter (procura no workspace.NPCs; senão usa a posição conhecida perto do Castle on the Sea)
local function eliteNpcCF()
    local npcs = workspace:FindFirstChild("NPCs")
    local m = npcs and npcs:FindFirstChild("Elite Hunter")
    local part = m and (m:FindFirstChild("HumanoidRootPart") or m.PrimaryPart or m:FindFirstChildWhichIsA("BasePart"))
    return part and part.CFrame or CFrame.new(-5418, 314, -2825)
end
local function eliteStep(askQuest)
    local boss = findEnemy(EliteNames)
    if boss and not ((StackBad[boss] or 0) > os.clock()) then
        if stackStall(boss) then return true end
        State.Mode = "Auto Elite Hunter"
        State.Text = "Killing " .. boss.Name
        fightEnemy(boss, EliteNames, false)
        return true
    end
    -- o elite ainda não carregou: o modelo fica em ReplicatedStorage, voa até a posição dele
    for _, n in ipairs(EliteNames) do
        local m = ReplicatedStorage:FindFirstChild(n)
        local part = m and (m:FindFirstChild("HumanoidRootPart") or m.PrimaryPart)
        if part then
            State.Mode = "Auto Elite Hunter"
            State.Text = "Going to " .. n
            flyTo(part.CFrame * CFrame.new(0, 20, 0))
            return true
        end
    end
    -- sem elite ativo: vai até o NPC Elite Hunter e pede a quest (só se "Auto Quest Elite Hunter" estiver ligado)
    if askQuest and os.clock() >= EliteS.pauseUntil then
        local visible, known = questVisible()
        local hasEliteQuest = known and visible and isEliteTitle(activeQuestTitle())
        if not hasEliteQuest then
            local cf = eliteNpcCF()
            if distanceTo(cf) > 25 then
                if EliteS.travelSince == 0 then EliteS.travelSince = os.clock() end
                if os.clock() - EliteS.travelSince > 45 then
                    EliteS.travelSince, EliteS.pauseUntil = 0, os.clock() + 60
                    Diag.elite = "trip to the Elite Hunter took too long; trying again in 60s"
                    return false
                end
                State.Mode, State.Text = "Auto Elite Hunter", "Going to the Elite Hunter NPC"
                flyTo(cf * CFrame.new(0, 3, 4))
                return true
            end
            EliteS.travelSince = 0
            State.Mode, State.Text = "Auto Elite Hunter", "Asking the Elite Hunter for the quest"
            if os.clock() - EliteAsk > 12 then
                EliteAsk = os.clock()
                if known and visible then -- tem outra quest ativa: abandona antes
                    invoke("AbandonQuest")
                    task.wait(0.4)
                end
                local ok, r = invoke("EliteHunter")
                Diag.elite = (ok and "EliteHunter -> " or "error -> ") .. tostring(r)
                local low = string.lower(tostring(r))
                if string.find(low, "later", 1, true) or string.find(low, "don't have", 1, true)
                    or string.find(low, "come back", 1, true) then
                    EliteS.pauseUntil = os.clock() + 120 -- sem elite disponível agora: volta ao farm e tenta depois
                    EliteS.unavailAt = EliteS.unavailAt or os.clock()
                    local mins, secs = tonumber(string.match(low, "(%d+)%s*min")), tonumber(string.match(low, "(%d+)%s*sec"))
                    local mm, ss = string.match(low, "(%d+):(%d+)")
                    EliteS.remain = mins and (mins * 60 + (secs or 0)) or (mm and (tonumber(mm) * 60 + tonumber(ss))) or secs
                    return false
                else
                    -- v46: o texto da resposta varia; confere se a quest abriu mesmo. Se nao abriu e nao ha Elite, nao tem Elite agora
                    task.wait(1.2)
                    local v2, k2 = questVisible()
                    local got = (k2 and v2 and isEliteTitle(activeQuestTitle())) or findEnemy(EliteNames) ~= nil
                    if got then
                        EliteS.unavailAt, EliteS.remain = nil, nil
                    else
                        EliteS.pauseUntil = os.clock() + 120
                        EliteS.unavailAt = EliteS.unavailAt or os.clock()
                        EliteS.remain = EliteS.remain
                        return false
                    end
                end
            end
            return true
        end
    end
    return false
end

-- Mar 2: Factory Raid - o boss "Core" aparece na Factory a cada ~1h30 (5 min para matar)
local function factoryStep()
    local core = findEnemy({ "Core" })
    if core and (StackBad[core] or 0) > os.clock() then core = nil end
    if not core then
        local cm = ReplicatedStorage:FindFirstChild("Core")
        local chrp = cm and cm:FindFirstChild("HumanoidRootPart")
        local chum = cm and cm:FindFirstChildOfClass("Humanoid")
        if chrp and chum and chum.Health > 0 then
            State.Mode, State.Text = "Auto Factory", "Going to the Core"
            flyTo(chrp.CFrame * CFrame.new(0, 20, 0))
            return true
        end
        return false
    end
    if stackStall(core) then return true end
    State.Mode = "Auto Factory"
    State.Text = "Killing the Core"
    fightEnemy(core, { "Core" }, false)
    return true
end
AFL.pirateRaidStep, AFL.eliteStep, AFL.factoryStep = pirateRaidStep, eliteStep, factoryStep

do
    local function sub(tab, text)
        local seen = {}
        local scanRoot = tab.Container or Window.Root
        for _, d in ipairs(scanRoot:GetDescendants()) do
            if d:IsA("TextLabel") then seen[d] = true end
        end
        pcall(function() tab:AddSection(text) end)
        for _, d in ipairs(scanRoot:GetDescendants()) do
            if d:IsA("TextLabel") and not seen[d] and d.Text == text then
                pcall(function() d.TextSize = 12; d.TextTransparency = 0.15 end)
                break
            end
        end
    end
    local function seaToggle(tab, id, title, key, sea, desc)
        local t = tab:AddToggle(id, { Title = title, Description = desc, Default = Config[key] and true or false })
        t:OnChanged(function(v)
            if v and sea and getSea() ~= sea then
                Fluent:Notify({ Title = "Moon Hub", Content = title .. " only works in Sea " .. sea .. ".", Duration = 5 })
                t:SetValue(false)
                return
            end
            Config[key] = v
            persist()
        end)
    end
    Tabs.Stack:AddSection("Stack Farm")
    sub(Tabs.Stack, "Third Sea")
    seaToggle(Tabs.Stack, "PirateRaid", "Auto Pirate Raid", "PirateRaid", 3)
    do
        local t = Tabs.Stack:AddToggle("PirateTankPriority", { Title = "TANK Priority Kill", Description = "When the TANK npc (fruit drop) shows up, kill it first - even if farther than other raid mobs", Default = Config.PirateTankPriority ~= false })
        t:OnChanged(function(v) Config.PirateTankPriority = v; persist() end)
    end
    sub(Tabs.Stack, "Second Sea")
    seaToggle(Tabs.Stack, "Factory", "Auto Factory", "Factory", 2)
    sub(Tabs.Stack, "Elite Hunter")
    seaToggle(Tabs.Stack, "Elite", "Auto Elite Hunter", "Elite", 3, "Takes the Elite Hunter mission at the Castle on the Sea and kills the Elite")
    seaToggle(Tabs.Stack, "EliteHop", "Auto Farm Elite Hunter Server Hop", "EliteHop", 3,
        "Only works with Auto Elite Hunter on. Changes server when the Elite has not spawned (does not change if 2 min or less are left for it to spawn, nor before killing). Shows Hop in 10 seconds in red.")
    sub(Tabs.Stack, "Chest")
    seaToggle(Tabs.Stack, "ChestFarm", "Auto Farm Chest", "ChestFarm", nil, "Flies to the map chests and collects them one by one")
    seaToggle(Tabs.Stack, "ChestHop", "Auto Farm Chest Hop", "ChestHop", nil,
        "Changes server only after collecting the number of chests chosen below (shows Hop in 10 seconds in red)")
    Tabs.Stack:AddSlider("ChestCount", {
        Title = "How many chests to collect", Description = "Exact number of chests per server before the hop",
        Min = 1, Max = 100, Default = math.clamp(tonumber(Config.ChestCount) or 10, 1, 100), Rounding = 0,
        Callback = function(v) Config.ChestCount = v; persist() end,
    })
end



]===] end
    PC.src["subfarm"] = function() return [===[
local __E = ...
local AFL = __E.AFL
local Config, Connections, Diag, Fluent, Player, State, Tabs = __E.Config, __E.Connections, __E.Diag, __E.Fluent, __E.Player, __E.State, __E.Tabs
local Window, aliveParts, enemiesList, fightEnemy, findEnemy, findSpawn, flyTo = __E.Window, __E.aliveParts, __E.enemiesList, __E.fightEnemy, __E.findEnemy, __E.findSpawn, __E.flyTo
local getChar, getSea, invoke, matchName, persist, questVisible = __E.getChar, __E.getSea, __E.invoke, __E.matchName, __E.persist, __E.questVisible
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local eliteStep = AFL.eliteStep
local Alive = true
AFL.onUnload(function() Alive = false end);
-- ---------- Sub Farm: Unlock Melees / Swords (CDK, TTK) ----------
-- Remotes e fluxos tirados dos hubs de referencia (QuantumOnyx): Buy<Nome sem espacos> no CommF_, BlackbeardReward (Dragon Claw),
-- LegendarySwordDealer 1/2, CDKQuest, TushitaProgress, EliteHunter Progress. Nada disto foi testado no jogo.
(function()
    local T = Tabs.SubFarm
    local RS = ReplicatedStorage
    local V3 = Vector3.new
    local SF = { status = "idle", at = {}, fail = {}, cool = {} }
    AFL.Sub = SF
    local function d(k, v) if Config[k] == nil then Config[k] = v end end
    for _, k in ipairs({ "SubGod", "SubC2", "SubV2", "SubTTK", "SubDT", "SubBL", "SubEl", "SubFK", "SubDC", "SubDS", "SubSK", "SubEC", "SubSan",
        "SubYama", "SubTushita", "SubCDK", "SubLegSword", "SubLegHop", "SubFullTTK", "SubSea2", "SubSea3" }) do d(k, false) end
    d("SubTravel", true)

    -- ---------- helpers ----------
    local function every(key, sec)
        if os.clock() - (SF.at[key] or 0) < sec then return false end
        SF.at[key] = os.clock()
        return true
    end
    local function note(txt) SF.status = txt; Diag.sub = txt end
    local function set(txt)
        SF.status = txt; Diag.sub = txt
        State.Mode, State.Text = "Auto Sub Farm", txt
    end
    local ALIAS = { ["Dragon Claw"] = "Dragon Breath" } -- o estilo mudou de nome no jogo
    local function tool(name)
        for _, c in ipairs({ Player.Character, Player.Backpack }) do
            local t = c and (c:FindFirstChild(name) or (ALIAS[name] and c:FindFirstChild(ALIAS[name])))
            if t and t:IsA("Tool") then return t end
        end
    end
    local function lvl(name)
        local t = tool(name)
        local l = t and t:FindFirstChild("Level")
        return l and tonumber(l.Value) or 0
    end
    local function owns(name)
        if tool(name) then return true end
        local ok, n = pcall(function() return AFL.Inv.count(name) + (ALIAS[name] and AFL.Inv.count(ALIAS[name]) or 0) end)
        return ok and (tonumber(n) or 0) > 0
    end
    local function loadItem(name)
        if owns(name) and not tool(name) and every("load" .. name, 3) then invoke("LoadItem", name) end
        return tool(name)
    end
    local function findNpc(pats)
        for _, root in ipairs({ workspace:FindFirstChild("NPCs"), RS:FindFirstChild("NPCs") }) do
            for _, n in ipairs(root and root:GetChildren() or {}) do
                local low = string.lower(n.Name)
                for _, p in ipairs(pats) do
                    if string.find(low, p, 1, true) then
                        local ok, cf = pcall(function() return n:GetPivot() end)
                        if ok and cf and cf.Position.Magnitude > 5 then return cf end
                    end
                end
            end
        end
    end
    local function goTo(cf, r, label)
        local _, hrp = getChar()
        if not hrp then return false end
        if (hrp.Position - cf.Position).Magnitude <= (r or 10) then return true end
        set("Flying to " .. label)
        flyTo(cf * CFrame.new(0, 3, 0))
        return false
    end

    -- viagem entre mares. Retorna (errado, ocupado): se errado, o passo deve devolver "ocupado"
    local SEACMD = { "TravelMain", "TravelDressrosa", "TravelZou" }
    local function wrongSea(seas)
        local want = type(seas) == "table" and seas or { seas }
        local cur = getSea()
        for _, s in ipairs(want) do if s == cur then return false end end
        local target = want[1]
        if not Config.SubTravel then note("Go to Sea " .. target .. " (Auto travel between seas is off)"); return true, false end
        if (SF.cool.travel or 0) > os.clock() then note("Sea travel to " .. target .. " failed repeatedly - paused"); return true, false end
        if every("travel", 25) then
            SF.travelN = (SF.travelN or 0) + 1
            if SF.travelN > 4 then SF.travelN, SF.cool.travel = 0, os.clock() + 300; return true, false end
            invoke(SEACMD[target])
        end
        set("Travelling to Sea " .. target)
        return true, true
    end
    table.insert(Connections, Player.CharacterAdded:Connect(function() SF.travelN = 0 end))

    -- ---------- treino de mastery ----------
    local MOBS = {
        ["Black Leg"] = { "Arctic Warrior", "Snow Lurker" }, ["Death Step"] = { "Arctic Warrior", "Snow Lurker" }, ["Superhuman"] = { "Arctic Warrior", "Snow Lurker" },
        ["Fishman Karate"] = { "Water Fighter" }, ["Sharkman Karate"] = { "Water Fighter" },
        ["Electro"] = { "Fishman Raider" }, ["Electric Claw"] = { "Fishman Raider" },
        ["Dragon Claw"] = { "Reborn Skeleton" }, ["Dragon Talon"] = { "Reborn Skeleton" },
    }
    local function nearestAny()
        local _, hrp = getChar()
        if not hrp then return end
        local best, bd
        for _, e in ipairs(enemiesList()) do
            local eh, er = aliveParts(e)
            if eh and not matchName(e.Name, Config.KillAllSkip or {}) then
                local dd = (er.Position - hrp.Position).Magnitude
                if not bd or dd < bd then best, bd = e, dd end
            end
        end
        return best
    end
    local function anySpawn()
        local _, hrp = getChar()
        if not hrp then return end
        local origin = workspace:FindFirstChild("_WorldOrigin")
        local folders = {}
        if origin and origin:FindFirstChild("EnemySpawns") then folders[#folders + 1] = origin.EnemySpawns end
        if workspace:FindFirstChild("EnemySpawns") then folders[#folders + 1] = workspace.EnemySpawns end
        local best, bd
        for _, f in ipairs(folders) do
            for _, sp in ipairs(f:GetChildren()) do
                if sp:IsA("BasePart") then
                    local dd = (sp.Position - hrp.Position).Magnitude
                    if not bd or dd < bd then best, bd = sp, dd end
                end
            end
        end
        return best
    end
    -- v77: STY/def precisam existir ANTES de train() pra ele conseguir checar o mar certo de cada estilo (ver
    -- comentario completo dentro de train() abaixo) - movido pra cima do que estava antes (depois de train()).
    local STY = {}
    local function def(s) STY[s.tool] = s; return s end

    -- bate em mobs com o item escolhido ate chegar na mastery. Retorna true enquanto estiver treinando
    local function train(name, target)
        local l = lvl(name)
        if l >= target then return false end
        -- v77 fix: "Auto Combate V2" (Auto Superhuman e as outras masteries em cadeia: Godhuman, Dragon Talon,
        -- Death Step, Sharkman Karate) so ficava dando TP entre os mares sem nunca treinar de fato. A causa: esse
        -- train() nunca checava se o mar atual tinha os mobs certos pra aquele estilo - se o personagem estava no
        -- mar errado, findEnemy/findSpawn nao achavam nada e a funcao caia no "No mobs found to train" devolvendo
        -- FALSE, exatamente o MESMO valor que devolve quando a mastery ja esta completa (l >= target). O ensure()
        -- la em cima nao sabe diferenciar os dois casos e trata "sem mobs aqui" como "treino concluido", entao
        -- segue direto pra COMPRAR o proximo estilo/mar, que te leva pra outro mar sem mob certo de novo - um ciclo
        -- infinito de compra+viagem sem nenhum treino real. Agora: antes de procurar mob, viaja pro mar certo do
        -- estilo (STY[name].seas, o mesmo mar onde ele e comprado/usado) quando o auto-travel estiver ligado, igual
        -- farmMat() ja faz pros materiais - so procura/luta mob depois de estar no mar certo.
        local sty = STY[name]
        if sty and sty.seas then
            local w, b = wrongSea(sty.seas)
            if w then return b end
        end
        local tl = tool(name)
        Config.ForceTool, Config.ForceUntil = string.lower(tl and tl.Name or name), os.clock() + 3
        set(string.format("Training %s mastery %d/%d", name, l, target))
        local mobs = MOBS[name]
        local e = (mobs and findEnemy(mobs)) or nearestAny()
        if e then fightEnemy(e, { e.Name }, true); return true end
        local sp = (mobs and findSpawn(mobs)) or anySpawn()
        if sp then flyTo(sp.CFrame * CFrame.new(0, 25, 0)); return true end
        note("No mobs found to train " .. name)
        return false
    end
    -- fisica de materiais de quest
    local function farmMat(m)
        local have = 0
        pcall(function() have = AFL.Inv.count(m.name) end)
        if have >= m.n then return false end
        if m.manual then note("Missing " .. m.name .. ": beat the Leviathan in Sea Events (it drops it)"); return false end
        local w, b = wrongSea(m.seas)
        if w then return b end
        set(string.format("Farming %s %d/%d", m.name, have, m.n))
        local e = findEnemy(m.mobs)
        if e then fightEnemy(e, m.mobs, true); return true end
        local sp = findSpawn(m.mobs)
        if sp then flyTo(sp.CFrame * CFrame.new(0, 25, 0)); return true end
        note("No " .. m.mobs[1] .. " found for " .. m.name)
        return false
    end

    -- ---------- melees ----------
    -- (STY/def agora declarados mais acima, antes de train() - v77)

    -- Death Step: porta da biblioteca fechada => precisa da Library Key (Awakened Ice Admiral)
    local function dsExtra()
        local ok, door = pcall(function() return workspace.Map.IceCastle.Hall.LibraryDoor.PhoeyuDoor end)
        if ok and door and door.Transparency == 0 and not tool("Library Key") then
            local e = findEnemy({ "Awakened Ice Admiral" })
            if e then set("Death Step: fighting the Awakened Ice Admiral (Library Key)"); fightEnemy(e, { e.Name }, false); return "busy" end
            set("Death Step: waiting at the Ice Castle for the Awakened Ice Admiral")
            flyTo(CFrame.new(5669, 29, -6483))
            return "busy"
        end
    end
    -- Sharkman: a propria compra responde "keys" quando falta a Water Key (Tide Keeper)
    local function skKeyStep()
        if not SF.sharkKey then return end
        if tool("Water Key") then
            if goTo(CFrame.new(-2605, 239, -10315), 8, "the Water Key door") and every("sharkdoor", 3) then invoke("BuySharkmanKarate") end
            return "busy"
        end
        local e = findEnemy({ "Tide Keeper" })
        if e then set("Sharkman: fighting the Tide Keeper (Water Key)"); fightEnemy(e, { e.Name }, false); return "busy" end
        set("Sharkman: going to the Tide Keeper")
        flyTo(CFrame.new(-3054, 237, -10145))
        return "busy"
    end
    -- Dragon Talon: Fire Essence vem da recompensa de Bones
    local function dtExtra()
        if tool("Fire Essence") then return end
        local dk = findNpc({ "death king" })
        if dk and not goTo(dk, 12, "the Death King") then return "busy" end
        if every("bones", 3) then invoke("Bones", "Buy", 1, 1) end
        note("Dragon Talon: spending Bones at the Death King until a Fire Essence drops (50 Bones per try) - farm Bones")
        return "block"
    end

    local function skExtra()
        if every("shark", 3) then
            local _, r = invoke("BuySharkmanKarate")
            SF.sharkKey = type(r) == "string" and string.find(r, "keys", 1, true) ~= nil
        end
        return skKeyStep()
    end

    -- Electric Claw: Previous Hero manda correr ate a Mansion em menos de 30s
    local function ecExtra()
        local run = SF.ecRun
        if run and os.clock() - run < 40 then
            if goTo(CFrame.new(-12468, 376, -7536), 14, "the Mansion (timed run)") then
                if every("ecbuy", 1.5) then
                    local _, r = invoke("BuyElectricClaw")
                    note("Electric Claw: run finished -> " .. tostring(r))
                    SF.ecRun = nil
                end
            end
            return "busy"
        end
    end

    local BL = def({ tool = "Black Leg", label = "Black Leg", npc = { "dark step" }, seas = { 1, 2 }, buy = { { "BuyBlackLeg" } } })
    local EL = def({ tool = "Electro", label = "Electro", npc = { "mad scientist" }, seas = { 1, 2 }, buy = { { "BuyElectro" } } })
    local FK = def({ tool = "Fishman Karate", label = "Fishman Karate", npc = { "water kung" }, seas = { 1, 2 }, buy = { { "BuyFishmanKarate" } } })
    local DC = def({ tool = "Dragon Claw", label = "Dragon Breath", npc = { "sabi" }, noNpc = true, seas = { 2 }, buy = { { "BlackbeardReward", "DragonClaw", "1" }, { "BlackbeardReward", "DragonClaw", "2" } } })
    local SUP = def({ tool = "Superhuman", label = "Superhuman", npc = { "martial arts" }, seas = { 1, 2 }, buy = { { "BuySuperhuman" } },
        pre = { { "Black Leg", 300 }, { "Electro", 300 }, { "Fishman Karate", 300 }, { "Dragon Claw", 300 } } })
    local DS = def({ tool = "Death Step", label = "Death Step", npc = { "phoeyu" }, pos = V3(6371, 297, -6841), seas = { 2 }, buy = { { "BuyDeathStep" } },
        pre = { { "Black Leg", 400 } }, extra = dsExtra })
    local SK = def({ tool = "Sharkman Karate", label = "Sharkman Karate", npc = { "sharkman" }, seas = { 2 }, buy = { { "BuySharkmanKarate" } },
        pre = { { "Fishman Karate", 400 } }, extra = skExtra })
    local EC = def({ tool = "Electric Claw", label = "Electric Claw", npc = { "previous hero" }, pos = V3(-12548, 337, -7481), seas = { 3 },
        buy = { { "BuyElectricClaw", "Start" } }, pre = { { "Electro", 400 } }, extra = ecExtra,
        after = function() SF.ecRun = os.clock() end })
    local DT = def({ tool = "Dragon Talon", label = "Dragon Talon", npc = { "uzoth" }, seas = { 3 }, buy = { { "BuyDragonTalon" } },
        pre = { { "Dragon Claw", 400 } }, extra = dtExtra })
    local GOD = def({ tool = "Godhuman", label = "Godhuman", npc = { "ancient monk" }, seas = { 3 }, buy = { { "BuyGodhuman" } },
        pre = { { "Superhuman", 400 }, { "Death Step", 400 }, { "Sharkman Karate", 400 }, { "Electric Claw", 400 }, { "Dragon Talon", 400 } },
        mats = { { name = "Fish Tail", n = 20, mobs = { "Fishman Warrior", "Fishman Commando" }, seas = { 1 } },
            { name = "Magma Ore", n = 20, mobs = { "Military Soldier", "Military Spy", "Lava Pirate" }, seas = { 1, 2 } },
            { name = "Mystic Droplet", n = 10, mobs = { "Sea Soldier", "Water Fighter" }, seas = { 2 } },
            { name = "Dragon Scale", n = 10, mobs = { "Dragon Crew Warrior", "Dragon Crew Archer" }, seas = { 3 } } } })
    local SAN = def({ tool = "Sanguine Art", label = "Sanguine Art", npc = { "shafi" }, seas = { 3 }, buy = { { "BuySanguineArt" } },
        mats = { { name = "Vampire Fang", n = 20, mobs = { "Vampire" }, seas = { 2 } },
            { name = "Demonic Wisp", n = 20, mobs = { "Demonic Soul" }, seas = { 3 } },
            { name = "Leviathan Heart", n = 1, mobs = { "Leviathan" }, seas = { 3 }, manual = true } } })

    local ensure
    function ensure(s)
        if tool(s.tool) then return false end
        if (SF.cool[s.tool] or 0) > os.clock() then return false end
        -- 1) estilos pre-requisito: primeiro compra os que faltam, depois treina
        for _, p in ipairs(s.pre or {}) do
            if not tool(p[1]) then
                if ensure(STY[p[1]]) then return true end
                note(s.label .. ": could not get " .. p[1] .. " yet")
                return false
            end
        end
        for _, p in ipairs(s.pre or {}) do
            if train(p[1], p[2]) then return true end
        end
        -- 2) materiais
        for _, m in ipairs(s.mats or {}) do
            if farmMat(m) then return true end
            local have = 0
            pcall(function() have = AFL.Inv.count(m.name) end)
            if have < m.n then note(s.label .. ": missing " .. m.name .. " " .. have .. "/" .. m.n); return false end
        end
        -- 3) mar certo
        if s.seas then
            local w, b = wrongSea(s.seas)
            if w then return b end
        end
        -- 4) passos especiais
        if s.extra then
            local r = s.extra(s)
            if r == "busy" then return true end
            if r == "block" then return false end
        end
        -- 5) compra
        local cf = (s.npc and findNpc(s.npc)) or (s.pos and CFrame.new(s.pos))
        if not cf and not s.noNpc then note(s.label .. ": teacher NPC not found in this sea"); return false end
        if cf and not goTo(cf, 10, s.label .. " teacher") then return true end
        if not every("buy" .. s.tool, 4) then
            set("Buying " .. s.label)
            return true
        end
        local last
        for _, a in ipairs(s.buy) do
            local _, r = invoke(table.unpack(a))
            last = r
        end
        set(s.label .. ": server replied " .. tostring(last))
        if s.after then s.after() end
        SF.fail[s.tool] = (SF.fail[s.tool] or 0) + 1
        if SF.fail[s.tool] >= 6 then
            SF.fail[s.tool] = 0
            SF.cool[s.tool] = os.clock() + 180
            note(s.label .. ": purchase keeps failing (" .. tostring(last) .. ") - retrying in 3 min")
            return false
        end
        return true
    end

    -- ---------- CDK ----------
    local function eliteCount()
        local _, r = invoke("EliteHunter", "Progress")
        return tonumber(r) or 0
    end
    local function yamaStep()
        if owns("Yama") then return false end
        local w, b = wrongSea(3)
        if w then return b end
        if not SF.eliteN or every("elitecnt", 4) then SF.eliteN = eliteCount() end
        local n = SF.eliteN
        if n < 30 then
            note(string.format("Yama: Elite Hunter %d/30", n))
            if eliteStep(true) then return true end
            -- v26: sem Elite neste servidor -> troca de servidor ate completar os 30 (mesmo sistema do Auto Bounty)
            if AFL.eliteHopTick then pcall(AFL.eliteHopTick, true) end
            return AFL.Hop and AFL.Hop.active or false
        end
        local m = workspace:FindFirstChild("Map")
        local wf = m and m:FindFirstChild("Waterfall")
        local hit = wf and wf:FindFirstChild("SealedKatana")
        hit = hit and hit:FindFirstChild("Hitbox")
        if not hit then
            set("Yama: flying to the waterfall (Sealed Katana)")
            flyTo(CFrame.new(5289, 1005, 393))
            return true
        end
        if not goTo(hit.CFrame * CFrame.new(0, 3, 0), 10, "the Sealed Katana") then return true end
        local cd = hit:FindFirstChildWhichIsA("ClickDetector", true)
        if cd and fireclickdetector and every("katana", 1.5) then pcall(fireclickdetector, cd) end
        set("Yama: pulling the Sealed Katana")
        return true
    end
    local function tushitaStep()
        if owns("Tushita") then return false end
        local w, b = wrongSea(3)
        if w then return b end
        if not SF.tush or every("tushprog", 2) then
            local _, pr = invoke("TushitaProgress")
            SF.tush = type(pr) == "table" and pr or { Torches = { false, false, false, false, false } }
        end
        local prog = SF.tush
        if prog.OpenedDoor then
            local e = findEnemy({ "Longma" })
            if e then set("Tushita: fighting Longma"); fightEnemy(e, { e.Name }, false); return true end
            set("Tushita: going to Longma")
            flyTo(CFrame.new(-10237, 339, 8758))
            return true
        end
        if findEnemy({ "rip_indra True Form" }) or tool("Holy Torch") then
            if not tool("Holy Torch") then
                set("Tushita: waiting for the Holy Torch (kill rip_indra True Form)")
                flyTo(CFrame.new(5713, 19, 255))
                local e = findEnemy({ "rip_indra True Form" })
                if e then fightEnemy(e, { e.Name }, false) end
                return true
            end
            local _, _, hum = getChar()
            local ht = tool("Holy Torch")
            if hum and ht and ht.Parent ~= Player.Character then hum:EquipTool(ht) end
            for i, lit in ipairs(prog.Torches or {}) do
                if not lit then invoke("TushitaProgress", "Torch", i) end
            end
            set("Tushita: lighting the torches")
            return true
        end
        -- v26: antes de trocar de servidor vai para a Ilha da Hydra e entra num servidor que ja tem o Rip_Indra (API do Quantum). So depois faz o puzzle.
        if Config.SubRipApi ~= false and not tool("God's Chalice") then
            local hydra = Vector3.new(5228, 603, 345)
            local _, hrp = getChar()
            if hrp and (hrp.Position - hydra).Magnitude > 400 and not (AFL.Hop and AFL.Hop.active) and not (AFL.QApi and AFL.QApi.joining) then
                set("Tushita: flying to Hydra Island before changing server")
                flyTo(CFrame.new(hydra)); return true
            end
            set("Tushita: joining a server that has Rip_Indra")
            AFL.apiJoin("Ripindra", function() return findEnemy({ "rip_indra True Form" }) ~= nil end, "Rip_Indra")
            return true
        end
        local chalice = tool("God's Chalice")
        if chalice then
            local _, _, hum = getChar()
            if hum and chalice.Parent ~= Player.Character then hum:EquipTool(chalice) end
            set("Tushita: placing the God's Chalice")
            flyTo(CFrame.new(-5561, 314, -2663))
            return true
        end
        note("Tushita: getting a God's Chalice (Elites / chests)")
        if eliteStep(true) then return true end
        if AFL.chestStep and AFL.chestStep() then return true end
        return false
    end

    local CDKPOS = { V3(-4602, 16, -2881), V3(-6126, 16, -2250), V3(3911, 7, -2582), V3(-426, 11, 5301) }
    local function cursed() local m = workspace:FindFirstChild("Map"); local t = m and m:FindFirstChild("Turtle"); return t and t:FindFirstChild("Cursed") end
    local function press(p) if p and fireproximityprompt then pcall(fireproximityprompt, p, 1) end end
    local function touch(part)
        local _, hrp = getChar()
        if hrp and part and firetouchinterest then
            pcall(function() firetouchinterest(hrp, part, 0); firetouchinterest(hrp, part, 1) end)
        end
    end
    -- CDKfix: maestria lida tambem pelo inventario (a espada pode nao estar na mochila ainda)
    local function mastOf(name)
        local v = lvl(name)
        local ok, m = pcall(function() return AFL.Inv.mastery and AFL.Inv.mastery(name) end)
        m = ok and tonumber(m) or nil
        if m and m > v then v = m end
        return v
    end
    -- CDKfix: leitura robusta do progresso (tabela, numero ou chamada por lado) e guarda o valor cru para mostrar no status
    local function cdkProgress()
        local q, how
        local ok, r = invoke("CDKQuest", "Progress")
        if ok and type(r) == "table" then q, how = r, "table" end
        if not q then
            local function num(v)
                if type(v) == "table" then v = v.Progress or v.Stage or v.Value or v[1] end
                return tonumber(v)
            end
            local ok1, g = invoke("CDKQuest", "Progress", "Good")
            local ok2, e = invoke("CDKQuest", "Progress", "Evil")
            if (ok1 and num(g)) or (ok2 and num(e)) then
                q, how = { Good = (ok1 and num(g)) or -2, Evil = (ok2 and num(e)) or -2 }, "sides"
            end
        end
        if not q then
            SF.cdkRaw = "no answer from the server (" .. tostring(r) .. ")"
            return "None"
        end
        local evil, good = tonumber(q.Evil) or -2, tonumber(q.Good) or -2
        SF.cdkRaw = string.format("%s Good=%s Evil=%s", tostring(how), tostring(q.Good), tostring(q.Evil))
        if q.Finished == true or (evil == 4 and good == 4) then return "Alucard Boss" end
        if good == 0 or good == -3 then return "Boat Quest" end
        if good == 1 or good == -4 then return "Raid Quest" end
        if good == 2 or good == -5 then return "Heavenly Quest" end
        if good == 3 then return "Burn Tushita Scroll" end
        if evil == 0 or evil == -3 then return "Pain Quest" end
        if evil == 1 or evil == -4 then return "Haze Quest" end
        if evil == 2 or evil == -5 then return "Hell Quest" end
        if evil == 3 then return "Burn Yama Scroll" end
        if good == -2 and evil == -2 then return owns("Tushita") and "Start Tushita" or "Start Yama" end
        if good == -2 then return "Start Tushita" end
        if evil == -2 then return "Start Yama" end
        return "None"
    end
    -- CDKfix: pedestal pode ser Part ou Model; segura a espada certa na mao e aperta o prompt mesmo se vier desativado
    local function posOf(o)
        if not o then return nil end
        if o:IsA("BasePart") then return o.CFrame end
        local ok, cf = pcall(function() return o:GetPivot() end)
        return ok and cf or nil
    end
    local function holdSword(kind)
        local nm = (kind == "Evil") and "Yama" or "Tushita"
        local t = tool(nm)
        local _, _, hum = getChar()
        if hum and t and t.Parent ~= Player.Character then pcall(function() hum:EquipTool(t) end) end
    end
    local function pedestal(name, kind)
        local c = cursed()
        local p = c and c:FindFirstChild(name)
        local cf = posOf(p)
        if p and cf then
            holdSword(kind)
            if not goTo(cf, 11, "the " .. name) then return end
            local pp = p:FindFirstChildWhichIsA("ProximityPrompt", true)
            if every("pedestal", 1.5) then
                if pp then
                    pcall(function() pp.HoldDuration = 0; pp.RequiresLineOfSight = false end)
                    press(pp)
                end
                invoke("CDKQuest", "StartTrial", kind)
            end
            set("CDK: at the " .. name .. " (" .. kind .. " trial) - " .. tostring(SF.cdkRaw or ""))
        else
            if every("pedestal", 1.5) then invoke("CDKQuest", "StartTrial", kind) end
            set("CDK: flying to the Turtle pedestals")
            flyTo(CFrame.new(-12391, 600, kind == "Evil" and -6500 or -6599))
        end
    end
    local function nearestEnemy(r)
        local _, hrp = getChar()
        if not hrp then return end
        local best, bd = nil, r or 150
        for _, e in ipairs(enemiesList()) do
            local eh, er = aliveParts(e)
            if eh then
                local dd = (er.Position - hrp.Position).Magnitude
                if dd < bd then best, bd = e, dd end
            end
        end
        return best
    end
    -- dimensoes Hell / Heavenly: mata tudo, acende as tochas, sai pela porta quando muda de cor
    local function dimension(folderName, locName, exitColor)
        local wo = workspace:FindFirstChild("_WorldOrigin")
        local locs = wo and wo:FindFirstChild("Locations")
        local loc = locs and locs:FindFirstChild(locName)
        local m = workspace:FindFirstChild("Map")
        local dim = m and m:FindFirstChild(folderName)
        local _, hrp = getChar()
        if not hrp then return false end
        local inside = (loc and (hrp.Position - loc.Position).Magnitude <= 1000)
            or (dim and dim:FindFirstChild("Exit") and (hrp.Position - dim.Exit.Position).Magnitude <= 1000)
        if not inside then return false end
        local ex = dim and dim:FindFirstChild("Exit")
        if ex and ex.BrickColor == BrickColor.new(exitColor) then
            if (hrp.Position - ex.Position).Magnitude <= 25 then touch(ex) end
            set("CDK: leaving the dimension")
            flyTo(ex.CFrame)
            return true
        end
        local e = nearestEnemy(150)
        if e then set("CDK: fighting inside the dimension"); fightEnemy(e, { e.Name }, false); return true end
        for _, c in ipairs(dim and dim:GetChildren() or {}) do
            if string.find(c.Name, "Torch", 1, true) and c:IsA("MeshPart") then
                local pp = c:FindFirstChildOfClass("ProximityPrompt")
                if pp and pp.Enabled then
                    set("CDK: lighting a torch")
                    if goTo(c.CFrame, 12, "a torch") then press(pp) end
                    return true
                end
            end
        end
        set("CDK: waiting inside the dimension")
        return true
    end
    local function hazeStep()
        local qh = Player:FindFirstChild("QuestHaze")
        if not qh then
            if every("hazeStart", 4) then invoke("CDKQuest", "StartTrial", "Evil") end
            note("CDK: starting the Haze quest")
            return true
        end
        local best, bd
        local _, hrp = getChar()
        for _, c in ipairs(qh:GetChildren()) do
            if tonumber(c.Value) and c.Value > 0 then
                for _, e in ipairs(enemiesList()) do
                    -- CDKfix v108: nome EXATO (era string.find/substring) - pegava mob errado que so tinha o nome parecido
                    -- e nao contava pra quest, por isso so matava "alguns" e nunca fechava a Haze Quest.
                    if hrp and e.Name == c.Name then
                        local eh, er = aliveParts(e)
                        if eh then
                            local dd = (er.Position - hrp.Position).Magnitude
                            if not bd or dd < bd then best, bd = e, dd end
                        end
                    end
                end
            end
        end
        if best then set("CDK Haze: killing " .. best.Name); fightEnemy(best, { best.Name }, true); return true end
        for _, c in ipairs(qh:GetChildren()) do
            if tonumber(c.Value) and c.Value > 0 then
                local sp = findSpawn({ c.Name })
                if sp then set("CDK Haze: going to " .. c.Name); flyTo(sp.CFrame * CFrame.new(0, 20, 0)); return true end
            end
        end
        set("CDK Haze: looking for the marked mobs")
        flyTo(CFrame.new(-12391, 600, -6500))
        return true
    end
    local function cdkCore()
        local w, b = wrongSea(3)
        if w then return b end
        if not owns("Tushita") then note("CDK: getting Tushita first"); return tushitaStep() end
        if not owns("Yama") then note("CDK: getting Yama (30 Elite Hunters)"); return yamaStep() end
        if not loadItem("Yama") or not loadItem("Tushita") then set("CDK: loading Yama / Tushita into the backpack"); return false end
        if mastOf("Yama") < 400 and train("Yama", 400) then return true end
        if mastOf("Tushita") < 400 and train("Tushita", 400) then return true end
        if owns("Cursed Dual Katana") then note("CDK: you already have the Cursed Dual Katana"); return false end
        local st = SF.cdkState
        if not st or every("cdkprog", 2) then st = cdkProgress(); SF.cdkState = st end
        if st == "Start Yama" or st == "Burn Yama Scroll" then
            pedestal("Pedestal2", "Evil")
        elseif st == "Start Tushita" or st == "Burn Tushita Scroll" then
            pedestal("Pedestal1", "Good")
        elseif st == "Pain Quest" then
            -- CDKfix v108: essa trial pede pra MORRER pro Marine Commodore, nao matar ele.
            -- Antes o bot lutava com ele (fightEnemy); agora so se aproxima e fica parado perto, sem atacar, levando dano até morrer.
            if every("pain", 10) then invoke("CDKQuest", "StartTrial", "Evil") end
            local e = findEnemy({ "Marine Commodore" })
            if e then
                local _, er = aliveParts(e)
                if er then
                    set("CDK Pain: perto do " .. e.Name .. " levando dano (sem atacar, precisa morrer)")
                    flyTo(er.CFrame * CFrame.new(0, 0, 3))
                end
            else
                local sp = findSpawn({ "Marine Commodore" })
                if sp then set("CDK Pain: going to the Marine Commodore"); flyTo(sp.CFrame * CFrame.new(0, 60, 0))
                else set("CDK Pain: looking for the Marine Commodore"); flyTo(CFrame.new(-13234, 520, -6800)) end
            end
        elseif st == "Haze Quest" then
            hazeStep()
        elseif st == "Hell Quest" then
            if every("hell", 10) then invoke("CDKQuest", "StartTrial", "Evil") end
            if not dimension("HellDimension", "Hell Dimension", "Olivine") then
                local e = findEnemy({ "Soul Reaper" })
                if e then
                    set("CDK Hell: fighting the Soul Reaper"); fightEnemy(e, { e.Name }, false)
                elseif tool("Hallow Essence") then
                    local _, _, hum = getChar()
                    local he = tool("Hallow Essence")
                    if hum and he.Parent ~= Player.Character then hum:EquipTool(he) end
                    set("CDK Hell: summoning the Soul Reaper")
                    flyTo(CFrame.new(-8932, 142, 6063))
                else
                    local _, bones = invoke("Bones", "Check")
                    if (tonumber(bones) or 0) >= 50 then
                        if goTo(CFrame.new(-8934, 142, 6036), 40, "the Bone Necromancer") and every("hallow", 4) then invoke("Bones", "Buy", 1, 1) end
                    else
                        note("CDK Hell: needs 50 Bones for a Hallow Essence, or a server where the Soul Reaper is alive")
                        return false
                    end
                end
            end
        elseif st == "Boat Quest" then
            if every("boat", 10) then invoke("CDKQuest", "StartTrial", "Good") end
            SF.boatI = SF.boatI or 1
            local pos = CDKPOS[SF.boatI] or CDKPOS[1]
            local dealer = workspace:FindFirstChild("NPCs") and workspace.NPCs:FindFirstChild("Luxury Boat Dealer")
            if goTo(CFrame.new(pos), 15, "the Luxury Boat Dealer spot " .. SF.boatI) then
                if dealer and every("boatq", 2) then
                    pcall(function()
                        invoke("CDKQuest", "BoatQuest", dealer, "Check")
                        invoke("CDKQuest", "BoatQuest", dealer)
                        invoke("CDKQuest", "BoatQuest", dealer, "Pardon me...")
                    end)
                end
                if every("boatnext", 4) then SF.boatI = SF.boatI % #CDKPOS + 1 end
            elseif dealer and (dealer:GetPivot().Position - pos).Magnitude < 40 and every("boatq2", 2) then
                invoke("CDKQuest", "BoatQuest", dealer, "Check")
            end
        elseif st == "Raid Quest" then
            if every("raidq", 10) then invoke("CDKQuest", "StartTrial", "Good") end
            local center = V3(-5542, 314, -2971)
            local best, bd
            for _, e in ipairs(enemiesList()) do
                local eh, er = aliveParts(e)
                if eh and (er.Position - center).Magnitude <= 1200 then
                    local dd = (er.Position - center).Magnitude
                    if not bd or dd < bd then best, bd = e, dd end
                end
            end
            if best then set("CDK Raid: killing " .. best.Name); fightEnemy(best, { best.Name }, true)
            else set("CDK Raid: waiting for the pirate raid at the Castle on the Sea"); flyTo(CFrame.new(-5542, 330, -2971)) end
        elseif st == "Heavenly Quest" then
            if every("heavq", 10) then invoke("CDKQuest", "StartTrial", "Good") end
            if not dimension("HeavenlyDimension", "Heavenly Dimension", "Cloudy grey") then
                local e = findEnemy({ "Cake Queen" })
                if e then set("CDK Heavenly: fighting the Cake Queen"); fightEnemy(e, { e.Name }, true)
                else
                    local sp = findSpawn({ "Cake Queen" })
                    if sp then set("CDK Heavenly: going to the Cake Queen"); flyTo(sp.CFrame * CFrame.new(0, 25, 0))
                    else note("CDK Heavenly: Cake Queen not found"); return false end
                end
            end
        elseif st == "Alucard Boss" then
            local c = cursed()
            if not c then set("CDK: flying to the Turtle"); flyTo(CFrame.new(-12389, 601, -6548))
            elseif c:FindFirstChild("PlacedGem") and c.PlacedGem.Transparency == 0 then
                local e = findEnemy({ "Cursed Skeleton Boss" })
                if e then set("CDK: fighting Alucard (Cursed Skeleton Boss)"); fightEnemy(e, { e.Name }, false)
                else set("CDK: waiting for Alucard"); flyTo(CFrame.new(-12341, 603, -6550)) end
            else
                local p3 = c:FindFirstChild("Pedestal3")
                local pp = p3 and p3:FindFirstChild("ProximityPrompt")
                if pp then
                    if goTo(p3.CFrame, 11, "the final pedestal") then press(pp) end
                else
                    invoke("CDKQuest", "Alucard")
                    flyTo(CFrame.new(-12356, 600, -6551))
                end
            end
        else
            -- CDKfix: estado desconhecido nao deixa o personagem parado: tenta as duas pedestais, alternando
            SF.kickN = SF.kickN or 0
            if every("kickswap", 12) then SF.kickN = SF.kickN + 1 end
            note("CDK: unknown quest state (" .. tostring(SF.cdkRaw) .. ") - trying the pedestals")
            if SF.kickN % 2 == 0 then pedestal("Pedestal2", "Evil") else pedestal("Pedestal1", "Good") end
        end
        return true
    end

    -- CDKfix: vigia. Erro interno nao some em silencio, e parado 30s no mesmo passo/lugar = relê o progresso e recomeca o passo
    local function cdkStep()
        local ok, r = pcall(cdkCore)
        if not ok then
            pcall(function() AFL.logErr("SubFarm CDK", r) end)
            note("CDK: internal error, retrying (" .. tostring(r) .. ")")
            SF.cdkState, SF.cdkWd = nil, nil
            return false
        end
        local _, hrp = getChar()
        local W = SF.cdkWd
        if r and hrp then
            local sig = tostring(SF.status)
            if not W or W.sig ~= sig or (hrp.Position - W.pos).Magnitude > 6 then
                SF.cdkWd = { sig = sig, pos = hrp.Position, t = os.clock() }
            elseif os.clock() - W.t > 30 then
                SF.cdkWd = nil
                SF.cdkState, SF.tush, SF.eliteN, SF.kickN = nil, nil, nil, (SF.kickN or 0) + 1
                SF.boatI = ((SF.boatI or 1) % #CDKPOS) + 1
                set("CDK: stuck 30s on '" .. sig .. "' - reading the quest again")
            end
        else
            SF.cdkWd = nil
        end
        return r
    end

    -- ---------- TTK: espadas lendarias (Shizu / Saishi / Oroshi) ----------
