        while Alive do
            task.wait(4)
            if Config.SubLegSword then
                pcall(function()
                    if getSea() ~= 2 then
                        SF.legStatus = "Legendary Swords: needs Sea 2" .. (Config.SubTravel and " (travelling)" or " (auto travel is off)")
                        if Config.SubTravel and every("legtravel", 30) then invoke("TravelDressrosa") end
                        return
                    end
                    local _, a = invoke("LegendarySwordDealer", "1")
                    if a then
                        local _, b = invoke("LegendarySwordDealer", "2")
