                        elseif b == 2 then SF.legStatus = "Legendary Swords: you already have this sword"
                        else SF.legStatus = "Legendary Swords: bought -> " .. tostring(b) end
                    else
                        SF.legStatus = "Legendary Swords: the dealer has nothing in this server"
                        if Config.SubLegHop and AFL.hopRequest then AFL.hopRequest("Legendary Sword Dealer", function() return not (Config.SubLegSword and Config.SubLegHop) end) end
                    end
                end)
            end
        end
    end)

