    -- ---------- Combat v2 (Advanced Combat): segredos + Awakened bosses so com Combat ----------
    d("SubC2Kills", {})
    local function c2Count()
        local n = 0
        for _ in pairs(Config.SubC2Kills or {}) do n = n + 1 end
        return n
    end
    -- conta cada Awakened boss (por nome) que morreu perto de voce enquanto o Combat v2 esta ligado
    -- v53: so conta se voce bateu nele com o Combat (outra arma na mao perto do boss = nao vale) e avisa na tela
    task.spawn(function()
        local cur, lastPos, tainted, hit
        while Alive do
            task.wait(0.5)
            if Config.SubC2 and AFL.Awk then
                pcall(function()
                    local e = AFL.Awk.find()
                    local _, hrp = getChar()
                    if e then
                        if e ~= cur then cur, tainted, hit = e, false, false end
                        local _, er = aliveParts(e)
                        lastPos = er and er.Position or lastPos
                        if hrp and lastPos and (hrp.Position - lastPos).Magnitude < 200 then
                            local t = Player.Character and Player.Character:FindFirstChildOfClass("Tool")
                            if t then
                                if t.Name == "Combat" then hit = true else tainted = true end
                            end
                        end
                    elseif cur then
                        local eh = cur.Parent and cur:FindFirstChildOfClass("Humanoid")
                        local died = (not cur.Parent) or (eh ~= nil and eh.Health <= 0)
                        local close = hrp ~= nil and lastPos ~= nil and (hrp.Position - lastPos).Magnitude < 200
                        if died and close and hit and not tainted then
                            Config.SubC2Kills = Config.SubC2Kills or {}
                            Config.SubC2Kills[cur.Name] = true
                            persist()
                            pcall(function() Fluent:Notify({ Title = "Combat v2", Content = cur.Name .. " counted (killed with Combat)", Duration = 5 }) end)
                        elseif died and close and tainted then
                            pcall(function() Fluent:Notify({ Title = "Combat v2", Content = cur.Name .. " NOT counted: another weapon was in your hand", Duration = 6 }) end)
                        end
                        cur, tainted, hit = nil, false, false
                    end
                end)
            end
        end
    end)
    local function pressNear(model, fallbackPos)
        if not fireproximityprompt then return end
        for _, o in ipairs(model and model:GetDescendants() or {}) do
            if o:IsA("ProximityPrompt") and o.Enabled then pcall(fireproximityprompt, o, 1) end
        end
    end
    local function c2Step()
        local Sec = AFL.Sec
        if not Sec then note("Combat v2: Secrets module not loaded"); return false end
        -- v53: tudo do Combat v2 (Island Secrets, Awakened bosses, Remove Blox Fruit, Secrets Master) e no Mar 1.
        -- Antes, fora do Mar 1 ele ficava parado em "loading secrets progress" para sempre.
        local wrong, busy = wrongSea(1)
        if wrong then return busy end
        -- tudo automatico: segredos de TODAS as ilhas + gatilho/kill dos Awakened
        if not Config.SecretAssist then Config.SecretAssist = true; persist(); pcall(function() Fluent.Options.SecretAssist:SetValue(true) end) end
        if not Config.SecretAuto then Config.SecretAuto = true; persist(); pcall(function() Fluent.Options.SecretAuto:SetValue(true) end) end
        if not Config.AwkOn then Config.AwkOn = true; persist(); pcall(function() Fluent.Options.AwkOn:SetValue(true) end) end
        if not Config.AwkTrigger then Config.AwkTrigger = true; persist(); pcall(function() Fluent.Options.AwkTrigger:SetValue(true) end) end
        -- v53: sem o "Auto Kill Boss Awk" o Auto Awk so voava ate o boss e ficava parado (nunca matava = nunca contava)
        if not Config.AwkKill then Config.AwkKill = true; persist(); pcall(function() Fluent.Options.AwkKill:SetValue(true) end) end
        Sec.refresh(false)
        if not Sec.done then note("Combat v2: loading secrets progress"); return false end
        local n = 0
        for _, df in ipairs(Sec.defs) do if Sec.isDone(df) then n = n + 1 end end
        local kills = c2Count()
        if n < #Sec.defs then
            note(string.format("Combat v2 step 1/3: Island Secrets %d/%d (automatic) | Awakened bosses killed with Combat: %d/10", n, #Sec.defs, kills))
            -- os Awakened ja liberados so valem com Combat: se ja tem Combat e sem fruta, usa Combat desde ja
        end
        local combat = tool("Combat")
        local hasFruit = false
        for _, c in ipairs({ Player.Character, Player.Backpack }) do
            for _, t in ipairs(c and c:GetChildren() or {}) do
                if t:IsA("Tool") and t.ToolTip == "Blox Fruit" then hasFruit = true end
            end
        end
        -- v53: o Combat fica na mao sempre que existir (antes so sem fruta, e as kills feitas com a fruta nao valiam)
        if combat then
            Config.Weapon = "Melee"
            Config.ForceTool, Config.ForceUntil = "combat", os.clock() + 3
        end
        if n < #Sec.defs then return false end
        if not combat or hasFruit then
            local npcCF = findNpc({ "remove blox fruit" }) or CFrame.new(5262.8, 345.9, 766.7)
            if not goTo(npcCF, 12, "the Remove Blox Fruit NPC") then
                note("Combat v2 step 2/3: flying to the Remove Blox Fruit NPC (top of the Prison)")
                return true
            end
            if every("c2remove", 3) then
                local npcs = workspace:FindFirstChild("NPCs")
                pressNear(npcs and npcs:FindFirstChild("Remove Blox Fruit"))
            end
            note("Combat v2 step 2/3: at the NPC - remove your Blox Fruit, then choose 'Remove my Fighting Style' in the dialogue (that choice is manual)")
            return true
        end
        if kills >= 10 then
            local smCF = findNpc({ "secrets master" }) or CFrame.new(-838.9, 28.4, 1603.1)
            if not goTo(smCF, 12, "the Secrets Master") then
                note(string.format("Combat v2 step 3/3: %d Awakened bosses killed - flying to the Secrets Master", kills))
                return true
            end
            if every("c2talk", 5) then
                local npcs = workspace:FindFirstChild("NPCs")
                pressNear(npcs and npcs:FindFirstChild("Secrets Master"))
            end
            note("Combat v2 step 3/3: at the Secrets Master - pick the Advanced Combat option in the dialogue")
            return true
        end
        note(string.format("Combat v2 step 3/3: killing the Awakened bosses with Combat only (%d/10 done: %s)", kills, (function()
            local t = {}
            for k in pairs(Config.SubC2Kills or {}) do t[#t + 1] = (string.gsub(k, "Awakened ", "")) end
            return #t > 0 and table.concat(t, ", ") or "none yet"
        end)()))
        return false
    end

    -- ---------- AUTO FULLY TTK: compra as 3 espadas, masteriza e compra a True Triple Katana ----------
    -- 1) Sea 2: pede espada ao Legendary Sword Dealer ate ter Shizu, Saishi e Oroshi (troca de servidor se o dealer nao tem nada)
    -- 2) carrega cada espada e treina em mobs ate 300 de mastery
    -- 3) pergunta ao Mysterious Man; se ainda nao deu a TTK, sobe a meta para 350 e tenta de novo
    local TTK_SWORDS = { "Shizu", "Saishi", "Oroshi" }
    local function ttkFullStep()
        if owns("True Triple Katana") then
            note("Fully TTK: you already have the True Triple Katana")
            return false
        end
        local missing = {}
        for _, n in ipairs(TTK_SWORDS) do if not owns(n) then missing[#missing + 1] = n end end
        -- 1) comprar as espadas
        if #missing > 0 then
            local w, b = wrongSea(2)
            if w then return b end
            set("Fully TTK: buying swords (missing " .. table.concat(missing, ", ") .. ")")
            if every("ttkdealer", 3) then
                local _, a = invoke("LegendarySwordDealer", "1")
                if a then
                    local _, r = invoke("LegendarySwordDealer", "2")
                    SF.ttkNoBeli = (r == 0)
                    note(r == 0 and "Fully TTK: not enough Beli for the next sword (keep another farm on)" or ("Fully TTK: dealer answered -> " .. tostring(r)))
                else
                    SF.ttkNoBeli = false
                    note("Fully TTK: the dealer has nothing in this server, hopping")
                    if AFL.apiJoin then AFL.apiJoin("LegendarySwordDealer", function() return not Config.SubFullTTK end, "Legendary Sword Dealer")
                    elseif AFL.hopRequest then AFL.hopRequest("Legendary Sword Dealer", function() return not Config.SubFullTTK end) end
                end
            end
            if SF.ttkNoBeli then return false end -- sem Beli: deixa os outros farms rodarem
            return true
        end
        -- 2) masterizar
        for _, n in ipairs(TTK_SWORDS) do
            if not loadItem(n) then note("Fully TTK: loading " .. n); return false end
        end
        local target = SF.ttkTarget or 300
        for _, n in ipairs(TTK_SWORDS) do
            if train(n, target) then return true end
        end
        -- 3) comprar a TTK
        if every("ttkbuy", 4) then
            local _, r = invoke("MysteriousMan", "2")
            SF.ttkReply = r
            if not owns("True Triple Katana") then
                if target < 350 then
                    SF.ttkTarget = 350
                    note("Fully TTK: not accepted at 300 (reply " .. tostring(r) .. "), training to 350")
                    return true
                end
                note("Fully TTK: Mysterious Man replied -> " .. tostring(r) .. " (swords are at " .. target .. " mastery)")
            end
        end
        return false
    end

    -- ---------- Auto Sea 2 / Auto Sea 3 ----------
    -- Mar 2: Detective (Key) -> porta do Ice Castle -> Ice Admiral -> TravelDressrosa.
    -- Mar 3: missao do Bartilo (Swan Pirates x50, Jeremy, placas) -> level 1500 -> TravelZou.
    -- Remotes e coordenadas tirados de scripts de referencia. Nada disto foi testado no jogo; o Status mostra cada passo e cada resposta do servidor.
    do
        local ICE_DOOR = CFrame.new(1347.7124, 37.3751, -1325.6488)
        local BARTILO_NPC = CFrame.new(-456.28952, 73.0200958, 299.895966)
        local JEREMY_POS = CFrame.new(2316, 449, 787)
        local SWAN_AREA = CFrame.new(638, 71, 918)
        local DON_SWAN_ROOM = CFrame.new(2288, 15, 863)
        local PLATES = {
            V3(-1836, 11, 1714), V3(-1850.49, 13.17, 1750.89), V3(-1858.87, 19.37, 1712.01),
            V3(-1803.94, 16.58, 1750.89), V3(-1858.55, 16.88, 1724.79), V3(-1869.54, 15.98, 1681.00),
            V3(-1800.09, 16.49, 1684.52), V3(-1819.26, 14.79, 1717.90), V3(-1813.51, 14.86, 1724.79),
        }

        local function myLevel()
            local ok, v = pcall(function() return Player.Data.Level.Value end)
            return (ok and tonumber(v)) or 0
        end
        local function equipTool(t)
            local _, _, hum = getChar()
            if hum and t and t.Parent ~= Player.Character and every("equip" .. t.Name, 1) then pcall(function() hum:EquipTool(t) end) end
        end
        local function iceDoorOpen()
            local ok, door = pcall(function() return workspace.Map.Ice.Door end)
            if ok and door and door:IsA("BasePart") then
                return door.CanCollide == false and door.Transparency >= 0.9
            end
            return false
        end

        -- ===== Mar 2 =====
        local function sea2Step()
            if getSea() ~= 1 then return false end
            local lv = myLevel()
            if lv < 700 then
                note("Auto Sea 2: needs level 700 (you are level " .. lv .. ") - another farm raises the level")
                return false
            end
            if (SF.cool.sea2 or 0) > os.clock() then
                note("Auto Sea 2: paused for a few minutes after repeated failures")
                return false
            end
            -- 1) se a viagem ja esta liberada, vai direto
            if not SF.s2Tried then
                SF.s2Tried = true
                SF.s2WaitUntil = os.clock() + 8
                invoke("TravelDressrosa")
            end
            if os.clock() < (SF.s2WaitUntil or 0) then
                set("Auto Sea 2: trying to travel to the Second Sea")
                return true
            end
            -- 2) Ice Admiral vivo: mata
            local boss = findEnemy({ "Ice Admiral" })
            if boss then
                set("Auto Sea 2: killing the Ice Admiral")
                fightEnemy(boss, { boss.Name }, false)
                return true
            end
            -- 3) Key do Detective (so precisa se a porta ainda esta fechada)
            local open = iceDoorOpen()
            local key = tool("Key")
            if not key and not open then
                if (SF.cool.s2key or 0) > os.clock() then
                    note("Auto Sea 2: the Detective did not give the Key (reply: " .. tostring(SF.s2Reply) .. ") - paused for 2 min")
                    return false
                end
                local dn = findNpc({ "detective" })
                if dn and not goTo(dn, 20, "the Detective") then return true end
                if every("s2key", 5) then
                    SF.keyN = (SF.keyN or 0) + 1
                    if SF.keyN > 6 then
                        SF.keyN, SF.cool.s2key = 0, os.clock() + 120
                        return false
                    end
                    local _, r = invoke("DressrosaQuestProgress", "Detective")
                    SF.s2Reply = tostring(r)
                end
                set("Auto Sea 2: asking the Detective for the Key (reply: " .. tostring(SF.s2Reply) .. ")")
                return true
            end
            SF.keyN = 0
            if key then equipTool(key) end
            -- 4) vai ate a porta do Ice Castle com a Key na mao
            if not goTo(ICE_DOOR, 12, "the Ice Castle door") then return true end
            if open then
                local sp = findSpawn({ "Ice Admiral" })
                if sp and (sp.Position - ICE_DOOR.Position).Magnitude > 30 then
                    set("Auto Sea 2: flying to the Ice Admiral spawn")
                    flyTo(sp.CFrame * CFrame.new(0, 25, 0))
                    return true
                end
            end
            -- 5) o Ice Admiral ja morreu (ou vai nascer): tenta viajar de tempos em tempos
            if every("s2travel", 15) then
                SF.s2TravelN = (SF.s2TravelN or 0) + 1
                if SF.s2TravelN > 40 then
                    SF.s2TravelN, SF.cool.sea2 = 0, os.clock() + 300
                    return false
                end
                invoke("TravelDressrosa")
            end
            set(open and "Auto Sea 2: door open - waiting for the Ice Admiral / sea change"
                or "Auto Sea 2: at the Ice Castle door with the Key")
            return true
        end

        -- ===== Mar 3: missao do Bartilo. Retorna (ocupado, concluida) =====
        local function bartiloStep()
            if os.clock() - (SF.bartAt or 0) > 2 then
                SF.bartAt = os.clock()
                local ok, p = invoke("BartiloQuestProgress", "Bartilo")
                if ok then SF.bartVal, SF.bartErr = p, nil else SF.bartVal, SF.bartErr = "err", tostring(p) end
            end
            local p = SF.bartVal
            if p == "err" then
                note("Auto Sea 3: could not read Bartilo's quest (" .. tostring(SF.bartErr) .. ")")
                return false, false
            end
            if p == 0 then
                -- Swan Pirates x50
                local okq, vis, known = pcall(questVisible)
                local haveQuest = okq and known and vis
                if not haveQuest and os.clock() - (SF.at.s3quest or 0) > 30 then
                    if not goTo(BARTILO_NPC, 14, "Bartilo") then return true, false end
                    SF.at.s3quest = os.clock()
                    invoke("StartQuest", "BartiloQuest", 1)
                    set("Auto Sea 3: took Bartilo's quest")
                    return true, false
                end
                local e = findEnemy({ "Swan Pirate" })
                if e then
                    set("Auto Sea 3: Bartilo's quest - killing Swan Pirates")
                    fightEnemy(e, { e.Name }, true)
                    return true, false
                end
                local sp = findSpawn({ "Swan Pirate" })
                set("Auto Sea 3: Bartilo's quest - going to the Swan Pirates")
                flyTo((sp and sp.CFrame or SWAN_AREA) * CFrame.new(0, 25, 0))
                return true, false
            elseif p == 1 then
                -- Jeremy
                local e = findEnemy({ "Jeremy" })
                if e then
                    set("Auto Sea 3: Bartilo's quest - killing Jeremy")
                    fightEnemy(e, { e.Name }, false)
                    return true, false
                end
                if not goTo(JEREMY_POS, 15, "Jeremy") then return true, false end
                set("Auto Sea 3: Bartilo's quest - waiting for Jeremy to spawn")
                return true, false
            elseif p == 2 then
                -- placas
                local _, hrp = getChar()
                if not hrp then return true, false end
                SF.plate = SF.plate or 1
                local tgt = CFrame.new(PLATES[SF.plate] + V3(0, 1, 0))
                if (hrp.Position - tgt.Position).Magnitude > 4 then
                    set("Auto Sea 3: Bartilo's quest - stepping on the plates (" .. SF.plate .. "/" .. #PLATES .. ")")
                    flyTo(tgt)
                    return true, false
                end
                SF.plateAt = SF.plateAt or os.clock()
                if os.clock() - SF.plateAt < 0.7 then
                    set("Auto Sea 3: Bartilo's quest - stepping on the plates (" .. SF.plate .. "/" .. #PLATES .. ")")
                    return true, false
                end
                SF.plateAt = nil
                SF.plate = SF.plate + 1
                if SF.plate > #PLATES then SF.plate = 1 end
                return true, false
            end
            return false, true -- 3 ou qualquer outra resposta: missao concluida
        end

        local function sea3Step()
            local sea = getSea()
            if sea == 3 then return false end
            if sea == 1 then return sea2Step() end -- sozinho, o Auto Sea 3 tambem leva do Mar 1 ao Mar 2
            if sea ~= 2 then return false end
            local lv = myLevel()
            if lv < 850 then
                note("Auto Sea 3: needs level 850 for Bartilo's quest (you are level " .. lv .. ") - another farm raises the level")
                return false
            end
            if (SF.cool.sea3 or 0) > os.clock() then
                note("Auto Sea 3: paused for a few minutes (TravelZou reply: " .. tostring(SF.s3Reply) .. ", ZQuest check: " .. tostring(SF.zCheck) .. ")")
                return false
            end
            local busy, done = bartiloStep()
            if busy then return true end
            if not done then return false end
            if lv < 1500 then
                note("Auto Sea 3: Bartilo's quest is done; the Third Sea needs level 1500 (you are level " .. lv .. ")")
                return false
            end
            -- 1) viagem direta (ja liberada)
            if not SF.s3Tried then
                SF.s3Tried = true
                SF.s3WaitUntil = os.clock() + 8
                invoke("TravelZou")
            end
            if os.clock() < (SF.s3WaitUntil or 0) then
                set("Auto Sea 3: trying to travel to the Third Sea")
                return true
            end
            -- 2) bosses do caminho do Mar 3
            local boss = findEnemy({ "rip_indra", "Rip_Indra", "Don Swan" })
            if boss then
                set("Auto Sea 3: killing " .. boss.Name)
                fightEnemy(boss, { boss.Name }, false)
                return true
            end
            -- 3) tenta a missao Zou / viagem de tempos em tempos
            if every("s3z", 15) then
                SF.s3N = (SF.s3N or 0) + 1
                if SF.s3N > 20 then
                    SF.s3N, SF.cool.sea3 = 0, os.clock() + 300
                    return false
                end
                local _, c = invoke("ZQuestProgress", "Check")
                SF.zCheck = tostring(c)
                if c == 0 then invoke("ZQuestProgress", "Begin") end
                local _, r = invoke("TravelZou")
                SF.s3Reply = tostring(r)
            end
            if not goTo(DON_SWAN_ROOM, 25, "Don Swan's room") then return true end
            set("Auto Sea 3: waiting - TravelZou reply: " .. tostring(SF.s3Reply) .. " | ZQuest check: " .. tostring(SF.zCheck))
            return true
        end

        SF.sea2Step, SF.sea3Step = sea2Step, sea3Step
    end

    -- ---------- passo do scheduler ----------
    local ORDER = {
        { "SubSea2", SF.sea2Step }, { "SubSea3", SF.sea3Step },
        { "SubC2", c2Step },
        { "SubGod", function() return ensure(GOD) end }, { "SubV2", function() return ensure(SUP) end }, { "SubDT", function() return ensure(DT) end },
        { "SubDS", function() return ensure(DS) end }, { "SubSK", function() return ensure(SK) end }, { "SubEC", function() return ensure(EC) end },
        { "SubSan", function() return ensure(SAN) end }, { "SubBL", function() return ensure(BL) end }, { "SubEl", function() return ensure(EL) end },
        { "SubFK", function() return ensure(FK) end }, { "SubDC", function() return ensure(DC) end },
        { "SubYama", yamaStep }, { "SubTushita", tushitaStep }, { "SubCDK", cdkStep }, { "SubFullTTK", ttkFullStep },
    }
    function SF.listed()
        for _, o in ipairs(ORDER) do if Config[o[1]] then return true end end
        return false
    end
    function SF.step()
        if not getChar() then return false end
        for _, o in ipairs(ORDER) do
            if Config[o[1]] then
                local ok, busy = pcall(o[2])
                if not ok then AFL.logErr("SubFarm " .. o[1], busy)
                elseif busy then return true end
            end
        end
        return false
    end

    -- ---------- UI ----------
    local function sub(text)
        local seen = {}
        local scanRoot = T.Container or Window.Root
        for _, x in ipairs(scanRoot:GetDescendants()) do
            if x:IsA("TextLabel") then seen[x] = true end
        end
        pcall(function() T:AddSection(text) end)
        for _, x in ipairs(scanRoot:GetDescendants()) do
            if x:IsA("TextLabel") and not seen[x] and x.Text == text then
                pcall(function() x.TextSize = 12; x.TextTransparency = 0.15 end)
                break
            end
        end
    end
    local function tog(id, title, desc)
        T:AddToggle(id, { Title = title, Description = desc, Default = Config[id] and true or false })
            :OnChanged(function(v) Config[id] = v; persist() end)
    end

    T:AddSection("Sub Farm")
    local info = T:AddParagraph({ Title = "Status", Content = "idle" })
    local mast = T:AddParagraph({ Title = "Melee mastery", Content = "..." })
    task.spawn(function()
        while Alive do
            pcall(function()
                local txt = SF.status
                if SF.legStatus and Config.SubLegSword then txt = txt .. "\n" .. SF.legStatus end
                if SF.ttkStatus and Config.SubTTK then txt = txt .. "\n" .. SF.ttkStatus end
                info:SetDesc(txt)
                local parts = {}
                for _, n in ipairs({ "Black Leg", "Electro", "Fishman Karate", "Dragon Claw", "Superhuman", "Death Step", "Sharkman Karate", "Electric Claw", "Dragon Talon", "Godhuman", "Sanguine Art" }) do
                    if tool(n) then parts[#parts + 1] = n .. " " .. lvl(n) end
                end
                mast:SetDesc(#parts > 0 and table.concat(parts, " | ") or "No melee found yet")
            end)
            task.wait(2)
        end
    end)
    tog("SubTravel", "Auto travel between seas",
        "Lets the Sub Farm options switch seas by themselves (TravelMain / TravelDressrosa / TravelZou) when a step needs another sea. Off = it only tells you which sea to go to.")

    T:AddSection("Seas")
    tog("SubSea2", "Auto Sea 2",
        "First Sea, level 700+: asks the Detective for the Key, opens the Ice Castle door, kills the Ice Admiral and travels to the Second Sea by itself. Below level 700 it does nothing, so your level farm keeps running.")
    tog("SubSea3", "Auto Sea 3",
        "Second Sea: does Bartilo's quest (50 Swan Pirates, Jeremy, plates), kills Don Swan / Rip_Indra if they are up, and travels to the Third Sea at level 1500. Turned on in the First Sea it also does Auto Sea 2 first. The Status line shows each step and the server replies.")

    T:AddSection("Unlock Melees")
    tog("SubGod", "Auto God Human",
        "Buys / trains everything Godhuman needs (Superhuman, Death Step, Sharkman Karate, Electric Claw, Dragon Talon at 400 mastery), farms the materials (Fish Tail 20, Magma Ore 20, Mystic Droplet 10, Dragon Scale 10) and buys it at the Ancient Monk. Needs the beli / fragments.")
    tog("SubC2", "Auto Combat v2 (Advanced Combat)",
        "Automatic Advanced Combat: does ALL the Sea 1 Island Secrets (every island, ignores the selection), flies you to the Remove Blox Fruit NPC when they are done, keeps Combat equipped, triggers and kills the Awakened bosses (counted in Status), then flies you to the Secrets Master. Only the dialogue choices (remove fighting style / take Advanced Combat) are yours.")
    tog("SubV2", "Auto Superhuman",
        "Buys Dark Step, Electro, Water Kung Fu and Dragon Breath, trains each to 300 mastery, then buys Superhuman at the Martial Arts Master.")
    tog("SubDT", "Auto Dragon Talon", "Dragon Breath 400 mastery + Fire Essence (spend Bones at the Death King) -> Uzoth in the Third Sea.")
    tog("SubDS", "Auto Death Step", "Black Leg 400 mastery + Library Key (Awakened Ice Admiral) -> Phoeyu in the Second Sea.")
    tog("SubSK", "Auto Sharkman Karate", "Fishman Karate 400 mastery + Water Key (Tide Keeper) -> Sharkman teacher in the Second Sea.")
    tog("SubEC", "Auto Electric Claw", "Electro 400 mastery -> Previous Hero (Floating Turtle), then the timed run to the Mansion.")
    tog("SubSan", "Auto Sanguine Art", "Farms 20 Vampire Fang + 20 Demonic Wisp, needs a Leviathan Heart (kill the Leviathan yourself), then buys it from Shafi in the Third Sea.")
    sub("Basic styles")
    tog("SubBL", "Auto Black Leg (Dark Step)", "Buys it from the Dark Step Teacher.")
    tog("SubEl", "Auto Electro", "Buys it from the Mad Scientist.")
    tog("SubFK", "Auto Fishman Karate", "Buys it from the Water Kung-fu Teacher.")
    tog("SubDC", "Auto Dragon Breath", "Buys it for 1,500 fragments from Sabi (Kingdom of Rose, Second Sea).")

    T:AddSection("Swords")
    sub("CDK")
    tog("SubYama", "Auto Fully Yama", "Sea 3: hops until 30 Elite Hunters are dead, then takes the Yama.")
    tog("SubTushita", "Auto Fully Tushita", "Sea 3: Hydra Island > Rip_Indra server (Quantum API) > Holy Torch > Longma.")
    tog("SubCDK", "Auto Fully CDK", "Gets Yama and Tushita if missing, trains them to 400 mastery and runs the Cursed Dual Katana trials (Pain, Haze, Hell, Boat, Raid, Heavenly, Alucard).")
    sub("TTK")
    tog("SubFullTTK", "Auto Fully TTK", "Does the whole True Triple Katana by itself: buys Shizu, Saishi and Oroshi at the Legendary Sword Dealer (Sea 2, hops servers when the dealer has nothing), trains each sword to 300 mastery (raises to 350 if needed) and buys the TTK from the Mysterious Man. Needs the Beli for the swords.")
    tog("SubTTK", "Auto Buy TTK", "Asks the Mysterious Man for the True Triple Katana every few seconds (needs Shizu, Saishi and Oroshi at 300 mastery).")
    tog("SubLegSword", "Auto Buy Legendary Swords", "Second Sea: asks the Legendary Sword Dealer for a sword every few seconds and buys it (Shizu / Saishi / Oroshi). Works from anywhere in the sea.")
    tog("SubLegHop", "Hop when the dealer has no sword", "Only with Auto Buy Legendary Swords on: server hops when the dealer has nothing.")

    -- botoes de apoio do Combat v2
    local tok
    local function fly(pos, label)
        local mine = {}
        tok = mine
        Fluent:Notify({ Title = "Moon Hub - Sub Farm", Content = "Flying to " .. label, Duration = 3 })
        task.spawn(function()
            local t0 = os.clock()
            while Alive and tok == mine and os.clock() - t0 < 150 do
                local _, hrp = getChar()
                if not hrp or (hrp.Position - pos).Magnitude < 8 then break end
                flyTo(CFrame.new(pos + Vector3.new(0, 3, 0)))
                task.wait(0.25)
            end
            if tok == mine then tok = nil end
        end)
    end
    T:AddButton({ Title = "Reset Combat v2 boss counter", Description = "Forgets which Awakened bosses were counted",
        Callback = function() Config.SubC2Kills = {}; persist() end })
    T:AddButton({ Title = "Fly To The Remove Blox Fruit NPC", Description = "Top of the Prison: remove your fruit, then 'Remove my Fighting Style' (needed for Combat v2)",
        Callback = function() fly(V3(5262.8, 345.9, 766.7), "Remove Blox Fruit NPC") end })
    T:AddButton({ Title = "Fly To The Secrets Master", Description = "Middle Town: final step of Combat v2",
        Callback = function() fly(V3(-838.9, 28.4, 1603.1), "Secrets Master") end })
end)()




]===] end
    PC.src["mastery"] = function() return [===[
local __E = ...
local AFL = __E.AFL
local Aim, Config, FruitM1, LV, Player, State, Tabs = __E.Aim, __E.Config, __E.FruitM1, __E.LV, __E.Player, __E.State, __E.Tabs
local aliveParts, enemiesList, fightEnemy, findEnemy, findSpawn, findTool, flyTo = __E.aliveParts, __E.enemiesList, __E.fightEnemy, __E.findEnemy, __E.findSpawn, __E.findTool, __E.flyTo
local getChar, getSea, invoke, persist = __E.getChar, __E.getSea, __E.invoke, __E.persist
local VirtualInputManager = game:GetService("VirtualInputManager")
local Alive = true
AFL.onUnload(function() Alive = false end);
-- ---------- Farm Mastery ----------
-- Banana (Farm Mastery: bate normal até o mob chegar em X% de vida e termina com fruta/gun) + Quantum (Enable Mastery / Health Mob% / Auto Mastery Swords).
(function()
    local T = Tabs.Mastery
    local M = {}
    AFL.Mast = M
    local function d(k, v) if Config[k] == nil then Config[k] = v end end
    d("MastOn", false); d("MastMethod", "Blox Fruit"); d("MastHP", 40); d("MastKeys", { Z = true, X = true, C = true, V = true })
    d("MastGunKeys", { M1 = true, Z = true, X = true }); d("MastMode", "Finish at Health %")
    d("MastGunAim", true); d("MastAim", true); d("MastFast", true); d("MastHold", 0.3); d("MastAllSword", false); d("MastAllMelee", false); d("MastAllGun", false); d("MastAllFruit", false)
    local KEYS = { "Z", "X", "C", "V", "F" }
    local ki, keyAt = 0, 0
    M.status = "idle"

    local function ratio(h) return h.MaxHealth > 0 and (h.Health / h.MaxHealth) or 1 end
    local function methodTool() return (findTool(Config.MastMethod)) end
    -- mobs com pouca vida: o ataque normal ignora eles (ficam vivos) e a fruta/gun termina
    local function onlyMode() return Config.MastMode == "Mastery weapon only" end
    Config.MastSkip = function(h)
        if not Config.MastOn or not h then return false end
        if not onlyMode() and ratio(h) > (tonumber(Config.MastHP) or 40) / 100 then return false end
        return methodTool() ~= nil
    end
    local function lowMob(hrp)
        local f = workspace:FindFirstChild("Enemies"); if not f then return end
        local best, bd
        local cur = M.lastMob
        if cur and cur.Parent == f then
            local h, r = cur:FindFirstChildOfClass("Humanoid"), cur:FindFirstChild("HumanoidRootPart")
            if h and r and h.Health > 0 and (r.Position - hrp.Position).Magnitude <= 80 then return cur end
        end
        for _, m in ipairs(f:GetChildren()) do
            local h, r = m:FindFirstChildOfClass("Humanoid"), m:FindFirstChild("HumanoidRootPart")
            if h and r and h.Health > 0 and not m:GetAttribute("IsBoat") and (onlyMode() or ratio(h) <= (tonumber(Config.MastHP) or 40) / 100) then
                local dist = (r.Position - hrp.Position).Magnitude
                if dist <= 80 and (not bd or dist < bd) then best, bd = m, dist end
            end
        end
        M.lastMob = best
        return best
    end
    -- aimbot da Mastery: crava a câmera no mob (com previsão de movimento) para fruta e gun sempre acertarem
    local function aimAt(part)
        if not (Config.MastAim and part and part.Parent) then return part and part.Position end
        local pos = part.Position
        pcall(function() pos = pos + part.AssemblyLinearVelocity * 0.1 end)
        pcall(function()
            local cam = workspace.CurrentCamera
            if cam then cam.CFrame = CFrame.lookAt(cam.CFrame.Position, pos) end
        end)
        return pos
    end
    local function pickKey(set)
        for _ = 1, #KEYS do
            ki = ki % #KEYS + 1
            if set[KEYS[ki]] then return KEYS[ki] end
        end
    end
    -- uma rodada de ataques da arma de maestria: M1 (clique) e/ou a próxima skill escolhida, com a mira cravada no mob
    local function fireRound(kind, part)
        local set = (kind == "Gun") and (Config.MastGunKeys or {}) or (Config.MastKeys or {})
        Aim.part = part
        local apos = aimAt(part)
        if set.M1 then
            if kind == "Gun" then
                if Config.MastGunAim then
                    -- aimbot de gun: crava a câmera no mob e clica com a arma (Tool:Activate)
                    pcall(function()
                        aimAt(part)
                        local char = Player.Character
                        local tool = char and char:FindFirstChildOfClass("Tool")
                        if tool then tool:Activate() end
                    end)
                    if Config.ShotFire then pcall(Config.ShotFire, { kind = "gun", part = part }) end
                elseif Config.ShotFire then pcall(Config.ShotFire, { kind = "gun", part = part }) end
            elseif kind == "Melee" or kind == "Sword" then
                -- v60 fix: antes QUALQUER coisa que nao fosse "Gun" caia aqui e chamava FruitM1.tick (golpe de fruta) -
                -- Melee/Sword na Mastery nunca davam o golpe de verdade. Agora usa o mesmo click unificado do motor principal.
                pcall(Core.meleeSwordClick, kind)
            else
                pcall(FruitM1.tick)
            end
        end
        local gap = Config.MastFast and 0.07 or ((tonumber(Config.MastHold) or 0.3) + 0.1)
        if os.clock() - keyAt < gap then return true end
        local key = pickKey(set)
        if not key then
            if not set.M1 then M.status = "no skill / M1 selected for " .. kind end
            return true
        end
        keyAt = os.clock()
        M.status = kind .. ": " .. key .. (set.M1 and " + M1" or "") .. " on " .. tostring(part.Parent and part.Parent.Name)
        pcall(AFL.tvHook)
        AFL.TV.aimPos, AFL.TV.aimPart = apos or part.Position, part
        pcall(function()
            local kc = Enum.KeyCode[key]
            VirtualInputManager:SendKeyEvent(true, kc, false, game)
            task.wait(Config.MastFast and 0.03 or (tonumber(Config.MastHold) or 0.3))
            VirtualInputManager:SendKeyEvent(false, kc, false, game)
        end)
        task.delay(0.2, function() if AFL.TV.aimPart == part then AFL.TV.aimPos, AFL.TV.aimPart = nil, nil end end)
        return true
    end
    -- chamado pelo loop de ataque: devolve true quando a Mastery cuidou do tick (o ataque normal pula)
    function M.tick()
        -- Auto Farm ALL Gun 600: a arma de fogo equipada pelo farm atira no mob mais perto (M1 + skills escolhidas)
        if Config.MastName and (M.curKind == "Gun" or M.curKind == "Fruit") then
            local char, hrp = getChar()
            local f = workspace:FindFirstChild("Enemies")
            if char and hrp and f then
                local best, bd
                for _, m in ipairs(f:GetChildren()) do
                    local h, r = m:FindFirstChildOfClass("Humanoid"), m:FindFirstChild("HumanoidRootPart")
                    if h and r and h.Health > 0 and not m:GetAttribute("IsBoat") then
                        local dist = (r.Position - hrp.Position).Magnitude
                        if dist <= 120 and (not bd or dist < bd) then best, bd = r, dist end
                    end
                end
                local held = char:FindFirstChildOfClass("Tool")
                if best and held and held.Name == Config.MastName then
                    return fireRound(M.curKind, best)
                end
            end
            return false
        end
        if not Config.MastOn then return false end
        local char, hrp, hum = getChar()
        if not char then return false end
        local mob = lowMob(hrp)
        if not mob then return false end
        -- v30: enquanto acabando o mob, o equipWeapon do farm NÃO troca de volta para a arma normal (era o "troca troca")
        Config.MastFinishUntil = os.clock() + 0.6
        local tool, equipped = findTool(Config.MastMethod)
        if not tool then M.status = "no " .. tostring(Config.MastMethod) .. " in the backpack"; return false end
        if not equipped then hum:EquipTool(tool); M.status = "equipping " .. tool.Name; return true end
        local part = mob:FindFirstChild("HumanoidRootPart")
        return fireRound(Config.MastMethod == "Gun" and "Gun" or "Fruit", part)
    end
    Config.MastTick = M.tick

    -- Auto Farm ALL Sword/Melee 600: uma arma por vez (sticky) até 600, depois a próxima, sem parar
    local MAXM = 600
    local MELEES = { ["combat"]=1, ["black leg"]=1, ["electro"]=1, ["fishman karate"]=1, ["dragon claw"]=1, ["superhuman"]=1, ["death step"]=1, ["sharkman karate"]=1, ["electric claw"]=1, ["dragon talon"]=1, ["godhuman"]=1, ["sanguine art"]=1, ["advanced combat"]=1 }
    local function kind(t)
        local tip = t.ToolTip
        if tip == "Sword" or tip == "Melee" or tip == "Gun" then return tip end
        if tip == "Blox Fruit" then return "Fruit" end
        if MELEES[string.lower(t.Name)] then return "Melee" end
        return nil
    end
    local function readMast(t)
        local v = t:FindFirstChild("Level") or t:FindFirstChild("Mastery")
        if v and v:IsA("ValueBase") and tonumber(v.Value) then return tonumber(v.Value) end
        local a = t:GetAttribute("Level") or t:GetAttribute("Mastery")
        if tonumber(a) then return tonumber(a) end
        return AFL.Inv.mastery and AFL.Inv.mastery(t.Name) or nil
    end
    M.readMast = readMast
    local function tools(want)
        local out = {}
        for _, c in ipairs({ Player.Backpack, Player.Character }) do
            if c then for _, t in ipairs(c:GetChildren()) do
                if t:IsA("Tool") and kind(t) == want then out[#out + 1] = t end
            end end
        end
        return out
    end
    M.cur = nil
    function M.pickWeapon()
        Config.MastName = nil
        for _, want in ipairs({ "Sword", "Melee", "Gun", "Fruit" }) do
            if (want == "Sword" and Config.MastAllSword) or (want == "Melee" and Config.MastAllMelee) or (want == "Gun" and Config.MastAllGun) or (want == "Fruit" and Config.MastAllFruit) then
                local list = tools(want)
                -- continua na arma atual até 600
                if M.cur and M.curKind == want then
                    for _, t in ipairs(list) do
                        if t.Name == M.cur then
                            local m = readMast(t)
                            if m and m < MAXM then Config.MastName = t.Name; M.weaponText = want .. ": " .. t.Name .. " (" .. math.floor(m) .. "/" .. MAXM .. ")"; return end
                        end
                    end
                end
                local best, bm, unk, done = nil, nil, 0, 0
                for _, t in ipairs(list) do
                    local m = readMast(t)
                    if not m then unk += 1
                    elseif m >= MAXM then done += 1
                    elseif not bm or m < bm then best, bm = t, m end
                end
                if best then
                    M.cur, M.curKind = best.Name, want
                    Config.MastName = best.Name
                    M.weaponText = want .. ": " .. best.Name .. " (" .. math.floor(bm) .. "/" .. MAXM .. ") | done " .. done .. "/" .. #list
                    return
                end
                M.weaponText = want .. ": nothing to farm (" .. done .. " at 600, " .. unk .. " unreadable of " .. #list .. ")"
            end
        end
    end
    task.spawn(function()
        while Alive do
            pcall(M.pickWeapon)
            task.wait(3)
        end
    end)
    -- v26: o Auto 600 agora trabalha SOZINHO (antes so funcionava dentro de outra farm): mata o mob mais perto com a arma que esta subindo ate 600
    function M.farm()
        if not (Config.MastAllSword or Config.MastAllMelee or Config.MastAllGun or Config.MastAllFruit) then return false end
        pcall(M.pickWeapon)
        if not Config.MastName then M.status = "Auto 600: every selected weapon is at 600 (or its mastery cannot be read)"; return false end
        local _, hrp = getChar()
        if not hrp then return false end
        local best, bd
        for _, e in ipairs(enemiesList()) do
            local h, r = aliveParts(e)
            if h and r and not e:GetAttribute("IsBoat") then
                local dist = (r.Position - hrp.Position).Magnitude
                if not bd or dist < bd then best, bd = e, dist end
            end
        end
        if best and bd <= 700 then
            M.status = "Auto 600: " .. tostring(M.weaponText or Config.MastName) .. " on " .. best.Name
            State.Mode, State.Text = "Auto Mastery 600", M.status
            fightEnemy(best, { best.Name }, true)
            -- v60 fix: so o fightEnemy (golpe normal) rodava aqui - as skills escolhidas (MastKeys/MastGunKeys) e a mira
            -- cravada no mob (fireRound/aimAt) nunca eram chamadas pro Auto 600 ALL, so pro "Farm Mastery" de 1 arma so.
            local _, r = aliveParts(best)
            if r then pcall(fireRound, M.curKind, r) end
            return true
        end
        local sp
        pcall(function()
            local e = LV and LV.entry
            if e and e.sp and e.sp[1] then sp = Vector3.new(e.sp[1][1], e.sp[1][2] + 25, e.sp[1][3]) end
        end)
        if not sp then
            local f = workspace:FindFirstChild("_WorldOrigin")
            f = f and f:FindFirstChild("EnemySpawns")
            local nd
            for _, s in ipairs(f and f:GetChildren() or {}) do
                local p = s:IsA("BasePart") and s or s:FindFirstChildWhichIsA("BasePart")
                if p then
                    local dist = (p.Position - hrp.Position).Magnitude
                    if not nd or dist < nd then nd, sp = dist, p.Position + Vector3.new(0, 25, 0) end
                end
            end
        end
        if sp then
            M.status = "Auto 600: flying to the mobs"
            State.Mode, State.Text = "Auto Mastery 600", M.status
            flyTo(CFrame.new(sp)); return true
        end
        M.status = "Auto 600: no mobs found"
        return false
    end

    -- ===== Auto Upgrade Materials (v29) =====
    -- Farma os materiais do Ferreiro (Port Town) pra colocar estrela em Guns/Swords. Materiais comuns (Angel Wings, Scrap Metal,
    -- Leather) caem de qualquer NPC no mar certo; os outros tem mob especifico (tabela conferida: bloxodes.com/wiki/blox-fruits/materials,
    -- cruzada com os materiais de estilo de luta ja usados neste projeto). Angel Wings so existe no Mar 1 -> viaja pra la sozinho.
    -- NAO automatiza o clique final no Ferreiro: nao achei o remote exato pra isso com seguranca, so farma e avisa quando tiver o suficiente.
    d("FullMastMats", false); d("MastMatTarget", 15)
    local MATS = {
        { name = "Angel Wings", seas = { 1 } },
        { name = "Scrap Metal", seas = { 1, 2, 3 } },
        { name = "Leather", seas = { 1, 2, 3 } },
        { name = "Magma Ore", seas = { 1, 2 }, mobs = { "Military Soldier", "Military Spy", "Lava Pirate" } },
        { name = "Fish Tail", seas = { 1, 3 }, mobs = { "Fishman Warrior", "Fishman Commando" } },
        { name = "Mystic Droplet", seas = { 2 }, mobs = { "Sea Soldier", "Water Fighter" } },
        { name = "Vampire Fang", seas = { 2 }, mobs = { "Vampire" } },
        { name = "Dragon Scale", seas = { 3 }, mobs = { "Dragon Crew Warrior", "Dragon Crew Archer" } },
        { name = "Demonic Wisp", seas = { 3 }, mobs = { "Demonic Soul" } },
    }
    local MATSEACMD = { "TravelMain", "TravelDressrosa", "TravelZou" }
    local matTravelAt, matTravelN = 0, 0
    local function matWrongSea(seas)
        local cur = getSea()
        for _, s in ipairs(seas) do if s == cur then return false end end
        local target = seas[1]
        if not Config.FullTravel then M.status = "Materials: go to Sea " .. target .. " yourself (Auto Travel is off in Auto Fully)"; return true end
        if os.clock() - matTravelAt > 25 then
            matTravelAt = os.clock()
            matTravelN += 1
            if matTravelN <= 4 then invoke(MATSEACMD[target]) end
        end
        M.status = "Materials: travelling to Sea " .. target
        return true
    end
    function M.materialsStep()
        if not Config.FullMastMats then return false end
        local target = tonumber(Config.MastMatTarget) or 15
        for _, mat in ipairs(MATS) do
            local have = 0
            pcall(function() have = AFL.Inv.count(mat.name) end)
            if have < target then
                if matWrongSea(mat.seas) then State.Mode, State.Text = "Auto Upgrade Materials", M.status; return true end
                State.Mode = "Auto Upgrade Materials"
                M.status = string.format("Farming %s %d/%d", mat.name, have, target)
                State.Text = M.status
                if mat.mobs then
                    local e = findEnemy(mat.mobs)
                    if e then fightEnemy(e, mat.mobs, true); return true end
                    local sp = findSpawn(mat.mobs)
                    if sp then flyTo(sp.CFrame * CFrame.new(0, 25, 0)); return true end
                    M.status = "Materials: no " .. mat.mobs[1] .. " found for " .. mat.name
                    return true
                end
                -- material comum (sem mob especifico): qualquer NPC do mar serve
                local f = workspace:FindFirstChild("Enemies")
                local best, bd
                local _, hrp = getChar()
                if f and hrp then
                    for _, e in ipairs(f:GetChildren()) do
                        local eh, er = aliveParts(e)
                        if eh and er then
                            local dist = (er.Position - hrp.Position).Magnitude
                            if not bd or dist < bd then best, bd = e, dist end
                        end
                    end
                end
                if best then fightEnemy(best, { best.Name }, true); return true end
                M.status = "Materials: waiting for mobs to farm " .. mat.name
                return true
            end
        end
        M.status = "Materials: all at " .. target .. "+ - go upgrade at the Blacksmith (Port Town)"
        return false
    end

    -- ===== UI =====
    local function tg(id, title, desc)
        T:AddToggle(id, { Title = title, Description = desc, Default = Config[id] and true or false }):OnChanged(function(v) Config[id] = v; persist() end)
    end
    T:AddSection("Mastery Farm")
    local MV = { "Blox Fruit", "Gun" }
    T:AddDropdown("MastMethod", { Title = "Select Method Farm Mastery", Description = "Weapon that finishes the mobs (the one that gains mastery)", Values = MV, Default = (Config.MastMethod == "Gun") and 2 or 1 })
        :OnChanged(function(v) Config.MastMethod = v; persist() end)
    T:AddSlider("MastHP", { Title = "Health %", Description = "The normal attack stops when the mob reaches this life; the fruit/gun finishes it", Min = 15, Max = 100, Default = tonumber(Config.MastHP) or 40, Rounding = 0 })
        :OnChanged(function(v) Config.MastHP = math.floor(v); persist() end)
    tg("MastOn", "Farm Mastery", "Works inside the other farms (Level, Bones, Dough...): hits normally, then finishes each mob with the fruit skills or the gun")
    T:AddDropdown("MastMode", { Title = "Mastery Mode", Description = "Finish at Health % = hit with your Farm weapon, then finish with the mastery weapon | Mastery weapon only = never swaps: kills everything with the mastery weapon", Values = { "Finish at Health %", "Mastery weapon only" }, Default = (Config.MastMode == "Mastery weapon only") and 2 or 1 })
        :OnChanged(function(v) Config.MastMode = v; persist() end)
    local function setOf(val)
        local set = {}
        if type(val) == "table" then for k, x in pairs(val) do if x == true then set[k] = true elseif type(x) == "string" then set[x] = true end end end
        return set
    end
    local function copy(t) local o = {} for k, v in pairs(t or {}) do if v == true then o[k] = true end end return o end
    T:AddSection("Skills (Blox Fruit)")
    T:AddDropdown("MastKeysDD", { Title = "Fruit Attacks", Description = "M1 = fruit click, Z X C V F = skills. Used on the mob with the aim locked on it", Values = { "M1", "Z", "X", "C", "V", "F" }, Multi = true, Default = copy(Config.MastKeys) })
        :OnChanged(function(val) Config.MastKeys = setOf(val); persist() end)
    T:AddSection("Skills (Gun)")
    tg("MastAim", "Mastery Aimbot (always hit)", "Locks the camera on the mob with movement prediction before every fruit skill / gun shot so they always land")
    tg("MastGunAim", "Gun Aimbot (gun click)", "Locks the camera on the mob and clicks with the gun (Tool click) on every shot of the Farm Mastery / ALL Gun 600")
    T:AddDropdown("MastGunKeysDD", { Title = "Gun Attacks", Description = "M1 = gun shot (click), Z X = gun skills. Also used by Auto Farm ALL Gun 600", Values = { "M1", "Z", "X" }, Multi = true, Default = copy(Config.MastGunKeys) })
        :OnChanged(function(val) Config.MastGunKeys = setOf(val); persist() end)
    tg("MastFast", "Use skill fast (don't hold)", "Taps the keys quickly. Off: holds each key for the time below")
    T:AddSlider("MastHold", { Title = "Skill Hold Time (s)", Min = 0, Max = 3, Default = tonumber(Config.MastHold) or 0.3, Rounding = 1 })
        :OnChanged(function(v) Config.MastHold = v; persist() end)
    T:AddSection("Mastery Weapon")
    tg("MastAllSword", "Auto Farm ALL Sword 600", "Finds the sword below 600 mastery, equips it, farms it to 600, then switches to the next one, forever (one at a time)")
    tg("MastAllMelee", "Auto Farm ALL Melee 600", "Same for fighting styles: equips the one below 600 and farms it to 600, then the next (one at a time)")
    tg("MastAllFruit", "Auto Farm ALL Fruit 600", "Same for Blox Fruits in your backpack: equips the fruit below 600 mastery and uses its skills on the mobs until 600, then the next (one at a time)")
    tg("MastAllGun", "Auto Farm ALL Gun 600", "Same for guns: equips the gun below 600 mastery and shoots the mobs by remote until 600, then the next (one at a time)")
    T:AddSection("Upgrade Materials")
    tg("FullMastMats", "Auto Upgrade Gun & Sword (Farm Materials)", "Farms the Blacksmith materials (Scrap Metal, Angel Wings, Magma Ore...) one at a time; travels to Sea 1 by itself for Angel Wings (Sea 1 only). Does not click the final upgrade - notifies when you have enough")
    T:AddSlider("MastMatTarget", { Title = "Target per Material", Min = 5, Max = 50, Default = math.clamp(tonumber(Config.MastMatTarget) or 15, 5, 50), Rounding = 0 })
        :OnChanged(function(v) Config.MastMatTarget = math.floor(v); persist() end)
    T:AddSection("Mastery Status")
    local info = T:AddParagraph({ Title = "Mastery", Content = "Checking..." })
    task.spawn(function()
        while Alive do
            pcall(function()
                info:SetDesc(table.concat({
                    "Method: " .. tostring(Config.MastMethod) .. " | finishes at " .. tostring(Config.MastHP) .. "% life | " .. (Config.MastOn and "ON" or "off"),
                    "Now: " .. tostring(M.status),
                    "Weapon being farmed: " .. tostring(M.weaponText or "-"),
                    "Inventory: " .. tostring(AFL.Inv.state),
                }, "\n"))
            end)
            task.wait(2)
        end
    end)
end)()





