    PC.src["esp"] = function() return [===[
local __E = ...
local AFL = __E.AFL
local Config, Player, Tabs, getChar, persist = __E.Config, __E.Player, __E.Tabs, __E.getChar, __E.persist
local Alive = true
AFL.onUnload(function() Alive = false end);
-- ---------- ESP ----------
do
    local T = Tabs.ESP
    local CS = game:GetService("CollectionService")
    local marks = { Player = {}, Fruit = {}, Berry = {}, Island = {} }
    local COLORS = { Player = Color3.fromRGB(255, 80, 80), Fruit = Color3.fromRGB(255, 210, 60), Berry = Color3.fromRGB(120, 255, 120), Island = Color3.fromRGB(120, 200, 255) }
    local function myPos()
        local _, hrp = getChar()
        return hrp and hrp.Position
    end
    -- draws (or updates) the label above `adornee`
    local function mark(kind, key, adornee, text, model)
        if not (adornee and adornee.Parent) then return end
        local m = marks[kind][key]
        if not (m and m.gui and m.gui.Parent) then
            local gui = Instance.new("BillboardGui")
            gui.Name = "MHEsp"
            gui.AlwaysOnTop = true
            gui.Size = UDim2.fromOffset(180, 28)
            gui.StudsOffset = Vector3.new(0, 3, 0)
            gui.Adornee = adornee
            local lb = Instance.new("TextLabel")
            lb.Size = UDim2.fromScale(1, 1)
            lb.BackgroundTransparency = 1
            lb.Font = Enum.Font.GothamBold
            lb.TextSize = 14
            lb.TextColor3 = COLORS[kind]
            lb.TextStrokeTransparency = 0.3
            lb.Parent = gui
            gui.Parent = adornee
            m = { gui = gui, lb = lb }
            if model then
                local ok, h = pcall(function()
                    local hl = Instance.new("Highlight")
                    hl.FillColor, hl.OutlineColor, hl.FillTransparency, hl.Adornee = COLORS[kind], COLORS[kind], 0.75, model
                    hl.Parent = model
                    return hl
                end)
                if ok then m.hl = h end
            end
            marks[kind][key] = m
        end
        if m.txt ~= text then m.txt = text; m.lb.Text = text end
    end
    local function sweep(kind, seen)
        for key, m in pairs(marks[kind]) do
            if not (seen and seen[key]) then
                pcall(function() m.gui:Destroy() end)
                pcall(function() if m.hl then m.hl:Destroy() end end)
                marks[kind][key] = nil
            end
        end
    end
    local function dist(p)
        local mp = myPos()
        return mp and math.floor((mp - p).Magnitude) or 0
    end
    local function firstPart(inst)
        if not inst then return end
        if inst:IsA("BasePart") then return inst end
        return inst:FindFirstChildWhichIsA("BasePart", true)
    end

    local scans = {
        Player = function()
            local seen = {}
            for _, pl in ipairs(game:GetService("Players"):GetPlayers()) do
                local ch = pl.Character
                local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
                local hum = ch and ch:FindFirstChildOfClass("Humanoid")
                if pl ~= Player and hrp then
                    seen[pl] = true
                    mark("Player", pl, hrp, string.format("%s [%dm] HP %d", pl.DisplayName ~= "" and pl.DisplayName or pl.Name, dist(hrp.Position), hum and math.floor(hum.Health) or 0), ch)
                end
            end
            return seen
        end,
        Fruit = function()
            local seen = {}
            for _, t in ipairs(workspace:GetChildren()) do
                if t:IsA("Tool") and string.find(t.Name, "Fruit") then
                    local h = t:FindFirstChild("Handle")
                    if h then
                        seen[t] = true
                        mark("Fruit", t, h, string.format("%s [%dm]", t.Name, dist(h.Position)))
                    end
                end
            end
            return seen
        end,
        Berry = function()
            local seen = {}
            for _, b in ipairs(CS:GetTagged("BerryBush")) do
                local p = firstPart(b.Parent and b.Parent:IsA("Model") and b.Parent or b)
                if p then
                    seen[b] = true
                    mark("Berry", b, p, string.format("%s [%dm]", b.Name, dist(p.Position)))
                end
            end
            return seen
        end,
        Island = function()
            local seen = {}
            local wo = workspace:FindFirstChild("_WorldOrigin")
            local loc = wo and wo:FindFirstChild("Locations")
            for _, isl in ipairs(loc and loc:GetChildren() or {}) do
                local p = firstPart(isl)
                if p then
                    seen[isl] = true
                    mark("Island", isl, p, string.format("%s [%dm]", isl.Name, dist(p.Position)))
                end
            end
            return seen
        end,
    }
    local cfgKey = { Player = "EspPlayer", Fruit = "EspFruit", Berry = "EspBerry", Island = "EspIsland" }
    task.spawn(function()
        while Alive do
            for kind, scan in pairs(scans) do
                if Config[cfgKey[kind]] then
                    local ok, seen = pcall(scan)
                    sweep(kind, ok and seen or nil)
                else
                    sweep(kind, nil)
                end
            end
            task.wait(0.4)
        end
        for kind in pairs(marks) do sweep(kind, nil) end
    end)

    local function tg(id, title, desc)
        T:AddToggle(id, { Title = title, Description = desc, Default = Config[id] and true or false }):OnChanged(function(v) Config[id] = v; persist() end)
    end
    T:AddSection("ESP Configs")
    tg("EspPlayer", "ESP Player", "Name, distance and health of every player (red)")
    tg("EspFruit", "ESP Fruit", "Shows the fruits lying on the map (yellow)")
    tg("EspBerry", "ESP Berry", "Shows the berry bushes (green)")
    tg("EspIsland", "ESP Island", "Shows the islands with the distance (blue)")
    T:AddSection("ESP Status")
    local info = T:AddParagraph({ Title = "ESP", Content = "Checking..." })
    task.spawn(function()
        while Alive do
            pcall(function()
                local function n(k) local c = 0; for _ in pairs(marks[k]) do c += 1 end; return c end
                info:SetDesc(table.concat({
                    "Players: " .. (Config.EspPlayer and n("Player") or "off"),
                    "Fruits: " .. (Config.EspFruit and n("Fruit") or "off"),
                    "Berries: " .. (Config.EspBerry and n("Berry") or "off"),
                    "Islands: " .. (Config.EspIsland and n("Island") or "off"),
                }, "\n"))
            end)
            task.wait(1.5)
        end
    end)
end



]===] end
    PC.src["pvp"] = function() return [===[
local __E = ...
local AFL = __E.AFL
local Config, Connections, Player, Tabs, flyTo, getChar, persist = __E.Config, __E.Connections, __E.Player, __E.Tabs, __E.flyTo, __E.getChar, __E.persist
local RunService = game:GetService("RunService")
local Alive = true
AFL.onUnload(function() Alive = false end);
-- ---------- PVP ----------
do
    local T = Tabs.PVP
    local Players = game:GetService("Players")
    local selected
    local function names()
        local l = {}
        for _, p in ipairs(Players:GetPlayers()) do if p ~= Player then l[#l + 1] = p.Name end end
        table.sort(l)
        if #l == 0 then l[1] = "(no players)" end
        return l
    end
    T:AddSection("Select Player")
    local dd = T:AddDropdown("PvpPlayer", { Title = "Select Player PVP", Values = names(), Default = 1 })
    dd:OnChanged(function(v) selected = v end)
    selected = names()[1]
    T:AddButton({ Title = "Refresh Player", Description = "Updates the player list", Callback = function()
        pcall(function() dd:SetValues(names()) end)
    end })
    local function target()
        local p = selected and Players:FindFirstChild(selected)
        local ch = p and p.Character
        return ch and ch:FindFirstChild("HumanoidRootPart")
    end
    T:AddSection("PVP Configs")
    T:AddButton({ Title = "Teleport To Player", Description = "Flies to the selected player once", Callback = function()
        local h = target()
        if h then
            AFL.tpTravel(function()
                local t = target()
                return t and (t.CFrame * CFrame.new(0, 0, 4)).Position or nil
            end, selected or "player")
        end
    end })
    local follow = false
    T:AddToggle("PvpFollow", { Title = "Follow Player", Description = "Keeps flying to the selected player", Default = false }):OnChanged(function(v)
        follow = v
        if v then
            task.spawn(function()
                while Alive and follow do
                    local h = target()
                    if h then pcall(flyTo, h.CFrame * CFrame.new(0, 0, 4)) end
                    task.wait(0.3)
                end
            end)
        end
    end)

    T:AddSection("Movement")
    local ws, jp = tonumber(Config.PvpWS) or 16, tonumber(Config.PvpJP) or 50
    local wsOn, jpOn = false, false
    -- Input sem "Finished": aplica enquanto digita (antes só valia depois do Enter). A cada frame + sinal de mudança, porque o jogo reescreve o WalkSpeed o tempo todo.
    T:AddInput("PvpWalkSpeed", { Title = "Input WalkSpeed", Default = tostring(ws), Numeric = true, Placeholder = "16" }):OnChanged(function(v) ws = tonumber(v) or 16; Config.PvpWS = ws end)
    T:AddToggle("PvpWalkSpeedOn", { Title = "Change WalkSpeed", Default = false }):OnChanged(function(v)
        wsOn = v
        if not v then local _, _, hum = getChar(); if hum then pcall(function() hum.WalkSpeed = 16 end) end end
    end)
    T:AddInput("PvpJumpPower", { Title = "Input JumpPower", Default = tostring(jp), Numeric = true, Placeholder = "50" }):OnChanged(function(v) jp = tonumber(v) or 50; Config.PvpJP = jp end)
    T:AddToggle("PvpJumpPowerOn", { Title = "Change JumpPower", Default = false }):OnChanged(function(v)
        jpOn = v
        if not v then local _, _, hum = getChar(); if hum then pcall(function() hum.JumpPower = 50 end) end end
    end)
    local hooked = setmetatable({}, { __mode = "k" })
    local function applyMove(hum)
        if wsOn and hum.WalkSpeed ~= ws then hum.WalkSpeed = ws end
        if jpOn then
            if not hum.UseJumpPower then hum.UseJumpPower = true end
            if hum.JumpPower ~= jp then hum.JumpPower = jp end
        end
    end
    table.insert(Connections, RunService.Heartbeat:Connect(function()
        if not Alive or not (wsOn or jpOn) then return end
        local c = Player.Character
        local hum = c and c:FindFirstChildOfClass("Humanoid")
        if not hum then return end
        pcall(applyMove, hum)
        if not hooked[hum] then
            hooked[hum] = true
            for _, prop in ipairs({ "WalkSpeed", "JumpPower", "UseJumpPower" }) do
                pcall(function() hum:GetPropertyChangedSignal(prop):Connect(function() pcall(applyMove, hum) end) end)
            end
        end
    end))

    -- Walk On Water (igual ao Banana): plataforma invisível sob os pés em Y = -5 enquanto você está na faixa do mar (Y de -120 a 0)
    local plat
    local water = false
    T:AddToggle("WalkWater", { Title = "Walk On Water", Description = "You walk on top of the sea", Default = Config.WalkWater and true or false }):OnChanged(function(v)
        water = v; Config.WalkWater = v; persist()
        if not v and plat then pcall(function() plat:Destroy() end); plat = nil end
    end)
    water = Config.WalkWater and true or false
    table.insert(Connections, RunService.Heartbeat:Connect(function()
        if not (Alive and water) then return end
        local _, hrp, hum = getChar()
        if not hrp then return end
        if not (plat and plat.Parent) then
            plat = Instance.new("Part")
            plat.Name = "MHWaterWalk"
            plat.Size = Vector3.new(2048, 1, 2048)
            plat.Transparency = 1
            plat.Anchored = true
            plat.CanCollide = false
            plat.Parent = workspace
        end
        local y = hrp.Position.Y
        local sitting = hum and hum.Sit
        if sitting or y > 0 or y < -120 then
            plat.CanCollide = false
        else
            plat.CanCollide = true
            plat.CFrame = CFrame.new(hrp.Position.X, -5, hrp.Position.Z)
        end
    end))
    T:AddSection("PVP Status")
    local pinfo = T:AddParagraph({ Title = "PVP", Content = "Checking..." })
    task.spawn(function()
        while Alive do
            pcall(function()
                local h = target()
                pinfo:SetDesc(table.concat({
                    "Selected: " .. tostring(selected),
                    "Distance: " .. (h and (math.floor((h.Position - (select(2, getChar())).Position).Magnitude) .. "m") or "player not found"),
                    "Follow: " .. (follow and "ON" or "off") .. " | Walk On Water: " .. (water and "ON" or "off"),
                }, "\n"))
            end)
            task.wait(1)
        end
    end)
end



]===] end
    PC.src["aimbot"] = function() return [===[
local __E = ...
local AFL = __E.AFL
local Config, Connections, Fluent, Player, Tabs, persist = __E.Config, __E.Connections, __E.Fluent, __E.Player, __E.Tabs, __E.persist
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local UserInputService = game:GetService("UserInputService")
local Alive = true
AFL.onUnload(function() Alive = false end);
-- ---------- Aimbot nativo (v30, reescrito do zero) ----------
-- Silent Aim (Mouse.Hit / Target / UnitRay / X / Y + GetMouseLocation + ScreenPointToRay), Camera Lock suave e independente do FPS,
-- previsão de movimento por velocidade medida + ping, escolha de alvo estável (sticky), FOV, wall check preguiçoso, team/ForceField/amigos.
-- O silent só altera a mira ENQUANTO você usa uma skill / clica (gate), então botões e menus do jogo nunca ficam desalinhados.
(function()
    local A = Tabs.Aimbot
    local AB = {}
    AFL.Aim = AB
    local UIS = UserInputService
    local touchOnly = UIS.TouchEnabled and not UIS.KeyboardEnabled
    local function d(k, v) if Config[k] == nil then Config[k] = v end end
    d("AimOn", false); d("AimMode", "Silent"); d("AimTargets", "Players"); d("AimPriority", "Closest to Crosshair"); d("AimPart", "HumanoidRootPart")
    d("AimFOV", 160); d("AimShowFOV", true); d("AimFOVColor", "Cyan"); d("AimFOVOrigin", touchOnly and "Center" or "Mouse")
    d("AimSmooth", 0.35); d("AimPredict", 0.1); d("AimPredictOn", true); d("AimAutoPing", true); d("AimHitChance", 100); d("AimGuarantee", true)
    d("AimMaxDist", 1500); d("AimVisible", false); d("AimTeam", true); d("AimFF", true); d("AimFriends", false); d("AimSticky", true)
    d("AimTrigger", "Always On"); d("AimKey", "Q"); d("AimGate", "On Skill / Click")
    d("AimHighlight", true); d("AimLine", false); d("AimInfo", true); d("AimMinHP", 0)
    d("AimGateKeys", { Z = true, X = true, C = true, V = true, F = true }); d("AimIgnoreNames", "")
    d("AimLowHPFinisher", false); d("AimLowHPThreshold", 25); d("AimOffsetY", 0)

    local COLORS = {
        White = Color3.fromRGB(255, 255, 255), Cyan = Color3.fromRGB(0, 230, 255), Red = Color3.fromRGB(255, 60, 60),
        Green = Color3.fromRGB(70, 255, 110), Purple = Color3.fromRGB(180, 110, 255), Yellow = Color3.fromRGB(255, 225, 60),
        Pink = Color3.fromRGB(255, 105, 200), Orange = Color3.fromRGB(255, 150, 40),
    }
    -- v104: pedido do usuario - mais configuravel. Antes a tecla que "abre" o Silent Aim (gatilho) era fixa em Z/X/C/V/F -
    -- quem remapeia as skills do Blox Fruits (bem comum) ficava sem o redirect funcionar nas teclas certas. Agora e
    -- escolhido na UI (multi-select) e reconstruido na hora quando o usuario muda a selecao.
    local GATE_KEY_NAMES = { "Z", "X", "C", "V", "F", "Q", "E", "R", "T", "G", "B" }
    local SKILL_KEYS = {}
    local function rebuildGateKeys()
        table.clear(SKILL_KEYS)
        local set = Config.AimGateKeys
        if type(set) == "table" then
            for _, n in ipairs(GATE_KEY_NAMES) do
                if set[n] then
                    local ok, kc = pcall(function() return Enum.KeyCode[n] end)
                    if ok then SKILL_KEYS[#SKILL_KEYS + 1] = kc end
                end
            end
        end
        if #SKILL_KEYS == 0 then SKILL_KEYS[1] = Enum.KeyCode.Z end -- nunca fica sem nenhuma tecla de gatilho
    end
    rebuildGateKeys()
    -- v104: lista de nomes ignorados (comma-separated) - pra quando Team Check/Friends nao cobrem (ex: duo fora do
    -- sistema de time do jogo). Recalculada so quando o texto muda (nao a cada frame).
    local ignoreSet, ignoreRaw = {}, nil
    local function ignoredNames()
        local raw = Config.AimIgnoreNames or ""
        if raw ~= ignoreRaw then
            ignoreRaw = raw
            table.clear(ignoreSet)
            for name in string.gmatch(raw, "[^,]+") do
                name = string.gsub(string.gsub(name, "^%s+", ""), "%s+$", "")
                if name ~= "" then ignoreSet[string.lower(name)] = true end
            end
        end
        return ignoreSet
    end
    local R15_PARTS = { "Head", "UpperTorso", "HumanoidRootPart", "LowerTorso", "Torso" }

    -- ===== estado =====
    local held, toggled = false, false
    local cur = nil                         -- registro do alvo atual { char, part, hum, dist, sd, key }
    local SA = { pos = nil, part = nil, sx = 0, sy = 0, roll = true, rollAt = 0, releaseAt = 0 } -- dados do silent (lidos pelos hooks)
    local active = false
    local Track = setmetatable({}, { __mode = "k" }) -- parte -> velocidade medida
    local friendCache = {}
    local pickAt, randAt, randIdx = 0, 0, 1
    AB.status = "idle"

    -- ===== helpers de UI =====
    local function idx(list, v) for i, x in ipairs(list) do if x == v then return i end end return 1 end
    local function dd(id, title, desc, list, key)
        A:AddDropdown(id, { Title = title, Description = desc, Values = list, Default = idx(list, Config[key]) }):OnChanged(function(v) Config[key] = v; persist() end)
    end
    local function tg(id, title, desc, key)
        A:AddToggle(id, { Title = title, Description = desc, Default = Config[key] and true or false }):OnChanged(function(v) Config[key] = v; persist() end)
    end
    local function setOf(v)
        local o = {}
        if type(v) == "table" then
            for k, val in pairs(v) do
                if val == true then o[k] = true elseif type(val) == "string" then o[val] = true end
            end
        end
        return o
    end
    local function multiDD(id, title, desc, list, key, after)
        A:AddDropdown(id, { Title = title, Description = desc, Values = list, Multi = true, Default = setOf(Config[key]) }):OnChanged(function(v)
            Config[key] = setOf(v); persist()
            if after then after() end
        end)
    end
    local function sl(id, title, desc, key, mn, mx, rnd)
        A:AddSlider(id, { Title = title, Description = desc, Min = mn, Max = mx, Default = math.clamp(tonumber(Config[key]) or mn, mn, mx), Rounding = rnd or 0 }):OnChanged(function(v) Config[key] = v; persist() end)
    end

    -- ===== desenhos =====
    local circle, line, label, hasDrawing
    pcall(function()
        if Drawing and Drawing.new then
            circle = Drawing.new("Circle"); circle.Thickness = 1.5; circle.NumSides = 72; circle.Filled = false; circle.Visible = false
            line = Drawing.new("Line"); line.Thickness = 1.5; line.Visible = false
            label = Drawing.new("Text"); label.Size = 14; label.Center = true; label.Outline = true; label.Visible = false
            hasDrawing = true
        end
    end)
    local fgui, fframe
    if not hasDrawing then
        pcall(function()
            fgui = Instance.new("ScreenGui"); fgui.Name = "MoonAimFOV"; fgui.IgnoreGuiInset = true; fgui.ResetOnSpawn = false
            fgui.Parent = (type(gethui) == "function" and gethui()) or game:GetService("CoreGui")
            fframe = Instance.new("Frame"); fframe.BackgroundTransparency = 1; fframe.AnchorPoint = Vector2.new(0.5, 0.5); fframe.Visible = false; fframe.Parent = fgui
            Instance.new("UICorner", fframe).CornerRadius = UDim.new(1, 0)
            Instance.new("UIStroke", fframe).Thickness = 1.5
        end)
    end
    local hl
    pcall(function()
        hl = Instance.new("Highlight"); hl.FillTransparency = 0.75; hl.OutlineTransparency = 0; hl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
        hl.Enabled = false; hl.Parent = workspace
    end)

    -- ===== velocidade medida do alvo (jogadores do Blox Fruits voam/dão dash por CFrame, a velocidade da física não serve) =====
    local function velocityOf(part, now)
        local p = part.Position
        local tr = Track[part]
        if not tr or now - tr.t > 0.4 then
            Track[part] = { p = p, t = now, v = Vector3.zero }
            return part.AssemblyLinearVelocity
        end
        local dt = now - tr.t
        if dt > 0.0005 then
            local inst = (p - tr.p) / dt
            if inst.Magnitude > 450 then inst = tr.v end -- teletransporte / glitch: ignora
            tr.v = tr.v:Lerp(inst, math.clamp(dt * 16, 0.12, 1))
            tr.p, tr.t = p, now
        end
        local pv = part.AssemblyLinearVelocity
        return (pv.Magnitude > tr.v.Magnitude) and pv or tr.v
    end
    local function leadPos(part, now)
        local pos = part.Position
        if not Config.AimPredictOn then return pos end
        local t = tonumber(Config.AimPredict) or 0
        if Config.AimAutoPing then
            local ok, ping = pcall(function() return Player:GetNetworkPing() end)
            if ok and ping then t += math.clamp(ping, 0, 0.4) end
        end
        local off = velocityOf(part, now) * math.clamp(t, 0, 0.7)
        if off.Magnitude > 70 then off = off.Unit * 70 end
        return pos + off
    end

    -- ===== candidatos =====
    local function isFriend(p)
        local c = friendCache[p.UserId]
        if c == nil then
            friendCache[p.UserId] = false
            task.spawn(function()
                local ok, r = pcall(function() return Player:IsFriendsWith(p.UserId) end)
                friendCache[p.UserId] = ok and r == true
            end)
            return false
        end
        return c
    end
    local function allowedPlayer(p)
        if p == Player or not p.Character then return false end
        if Config.AimTeam and p.Team ~= nil and p.Team == Player.Team then return false end
        if Config.AimFriends and isFriend(p) then return false end
        if Config.AimFF and p.Character:FindFirstChildOfClass("ForceField") then return false end
        if ignoredNames()[string.lower(p.Name)] or ignoredNames()[string.lower(p.DisplayName or "")] then return false end
        return true
    end
    local list = {}
    local function gather()
        table.clear(list)
        local want = Config.AimTargets
        if want == "Players" or want == "Both" then
            for _, p in ipairs(Players:GetPlayers()) do
                if allowedPlayer(p) then list[#list + 1] = p.Character end
            end
        end
        if want == "NPCs" or want == "Both" then
            local f = workspace:FindFirstChild("Enemies")
            if f then
                for _, m in ipairs(f:GetChildren()) do
                    if not m:GetAttribute("IsBoat") then list[#list + 1] = m end
                end
            end
        end
    end

    -- ===== escolha da parte do corpo =====
    local function partOf(char, origin, cam)
        local w = Config.AimPart
        if w == "Closest Part" then
            local best, bd
            for _, n in ipairs(R15_PARTS) do
                local p = char:FindFirstChild(n)
                if p then
                    local v, on = cam:WorldToViewportPoint(p.Position)
                    if on then
                        local dist = (Vector2.new(v.X, v.Y) - origin).Magnitude
                        if not bd or dist < bd then best, bd = p, dist end
                    end
                end
            end
            return best or char:FindFirstChild("HumanoidRootPart")
        elseif w == "Random" then
            return char:FindFirstChild(R15_PARTS[randIdx]) or char:FindFirstChild("HumanoidRootPart")
        elseif w == "Torso" then
            return char:FindFirstChild("UpperTorso") or char:FindFirstChild("Torso") or char:FindFirstChild("HumanoidRootPart")
        end
        return char:FindFirstChild(w) or char:FindFirstChild("HumanoidRootPart")
    end

    local rayParams = RaycastParams.new()
    rayParams.FilterType = Enum.RaycastFilterType.Exclude
    rayParams.RespectCanCollide = true
    local function visible(cam, char, part)
        local mine = Player.Character
        rayParams.FilterDescendantsInstances = { mine or cam, char }
        local o = cam.CFrame.Position
        return workspace:Raycast(o, part.Position - o, rayParams) == nil
    end

    -- avalia 1 modelo: devolve registro ou nil (sem raycast; a visibilidade é testada só nos melhores)
    local function evaluate(cam, char, mult, origin)
        local hum, hrp = char:FindFirstChildOfClass("Humanoid"), char:FindFirstChild("HumanoidRootPart")
        if not (hum and hrp) or hum.Health <= 0 then return end
        if (tonumber(Config.AimMinHP) or 0) > 0 and hum.MaxHealth > 0 and hum.Health / hum.MaxHealth * 100 < Config.AimMinHP then return end
        local dist = (hrp.Position - cam.CFrame.Position).Magnitude
        if dist > (Config.AimGuarantee and math.max(tonumber(Config.AimMaxDist) or 1500, 3000) or (tonumber(Config.AimMaxDist) or 1500)) * (mult > 1 and 1.2 or 1) then return end
        local part = partOf(char, origin, cam) or hrp
        local v, on = cam:WorldToViewportPoint(part.Position)
        -- v103: pedido do usuario - "100% garantido" tinha um furo: um alvo atras da camera (fora da tela) tinha
        -- "on" false e era descartado ANTES de chegar no bypass do FOV, mesmo com Guaranteed Hit ligado - contra
        -- alguem batendo pelas costas o aimbot simplesmente nao via o alvo. Guaranteed Hit nao precisa do ponto na
        -- tela pra nada (o redirect do Silent Aim usa so a posicao 3D) - so segue descartando "atras de voce" quando
        -- Guaranteed Hit esta DESLIGADO (onde a FOV na tela ainda faz sentido pros outros modos manuais).
        if not on and not Config.AimGuarantee then return end
        local sd = on and (Vector2.new(v.X, v.Y) - origin).Magnitude or math.huge
        if not Config.AimGuarantee and sd > (tonumber(Config.AimFOV) or 160) * mult then return end
        local pr = Config.AimPriority
        -- v106: "Lowest/Highest Health" comparava vida ABSOLUTA - contra alvos com Max HP bem diferentes (ex: um
        -- boss com 50k de vida e um NPC comum com 500) isso quase sempre escolhia o tipo de alvo errado em vez do
        -- que realmente esta mais perto de morrer. Agora usa HP% (Health / MaxHealth), que e justo entre alvos
        -- de qualquer tamanho - pedido do usuario: "focar em quem ta com menos vida".
        local hpPct = hum.MaxHealth > 0 and (hum.Health / hum.MaxHealth * 100) or 100
        local key
        if pr == "Closest Distance" then key = dist
        elseif pr == "Lowest Health" then key = hpPct
        elseif pr == "Highest Health" then key = -hpPct
        else key = on and sd or dist end -- fora da tela: "mais perto da mira" nao existe, usa distancia
        return { char = char, part = part, hum = hum, dist = dist, sd = sd, hpPct = hpPct, key = key }
    end

    -- v106: "Low HP Finisher" - pedido do usuario ("muito mais configuracao" em cima do foco por vida). Quando
    -- ligado, isso ANULA a prioridade escolhida acima sempre que existir um alvo valido com HP% <= limite: garante
    -- que voce sempre termina quem esta quase morrendo em vez de ficar preso num alvo mais distante/mais forte so
    -- porque a prioridade normal (ex: Closest to Crosshair) mandava assim. So roda a varredura extra quando o
    -- toggle esta ligado, pra nao pesar nada em quem nao usa.
    local function findFinisher(recs, cam)
        local th = tonumber(Config.AimLowHPThreshold) or 25
        local best, bestHp
        for _, r in ipairs(recs) do
            if r.hpPct <= th and (not bestHp or r.hpPct < bestHp) then
                if Config.AimGuarantee or not Config.AimVisible or visible(cam, r.char, r.part) then best, bestHp = r, r.hpPct end
            end
        end
        return best
    end
    local function pick(cam, origin)
        if Config.AimLowHPFinisher then
            gather()
            local recs = {}
            for _, c in ipairs(list) do
                local r = evaluate(cam, c, 1, origin)
                if r then recs[#recs + 1] = r end
            end
            local fin = findFinisher(recs, cam)
            if fin then return fin end
            if Config.AimSticky and cur and cur.char.Parent then
                local r = evaluate(cam, cur.char, 1.5, origin)
                if r and (Config.AimGuarantee or not Config.AimVisible or visible(cam, r.char, r.part)) then return r end
            end
            table.sort(recs, function(a, b) return a.key < b.key end)
            if Config.AimGuarantee or not Config.AimVisible then return recs[1] end
            for i = 1, math.min(#recs, 6) do
                if visible(cam, recs[i].char, recs[i].part) then return recs[i] end
            end
            return
        end
        -- alvo atual continua enquanto ficar na FOV ampliada (evita pular entre alvos)
        if Config.AimSticky and cur and cur.char.Parent then
            local r = evaluate(cam, cur.char, 1.5, origin)
            if r and (Config.AimGuarantee or not Config.AimVisible or visible(cam, r.char, r.part)) then return r end
        end
        gather()
        local recs = {}
        for _, c in ipairs(list) do
            local r = evaluate(cam, c, 1, origin)
            if r then recs[#recs + 1] = r end
        end
        table.sort(recs, function(a, b) return a.key < b.key end)
        if Config.AimGuarantee or not Config.AimVisible then return recs[1] end
        for i = 1, math.min(#recs, 6) do
            if visible(cam, recs[i].char, recs[i].part) then return recs[i] end
        end
    end

    -- ===== ativação =====
    local function isKey(i)
        local k = Config.AimKey
        if k == "MouseButton2" then return i.UserInputType == Enum.UserInputType.MouseButton2 end
        local ok, kc = pcall(function() return Enum.KeyCode[k] end)
        return ok and i.KeyCode == kc
    end
    table.insert(Connections, UIS.InputBegan:Connect(function(i, gp)
        if gp and Config.AimKey ~= "MouseButton2" then return end
        if isKey(i) then held = true; toggled = not toggled end
    end))
    table.insert(Connections, UIS.InputEnded:Connect(function(i)
        if isKey(i) then held = false end
        SA.releaseAt = os.clock()
    end))
    local function isActive()
        if not Config.AimOn then return false end
        if Config.AimTrigger == "Hold Key" then return held or (touchOnly and toggled) end
        if Config.AimTrigger == "Toggle Key" then return toggled end
        return true
    end

    -- botão flutuante "AIM" (celular)
    local abtn, agui
    if UIS.TouchEnabled then
        pcall(function()
            agui = Instance.new("ScreenGui")
            agui.Name, agui.ResetOnSpawn, agui.IgnoreGuiInset, agui.DisplayOrder = "MoonAimBtn", false, true, 998
            agui.Parent = (type(gethui) == "function" and gethui()) or game:GetService("CoreGui")
            abtn = Instance.new("TextButton")
            abtn.Size, abtn.Position, abtn.AnchorPoint = UDim2.fromOffset(58, 58), UDim2.new(1, -90, 0.5, 0), Vector2.new(0, 0.5)
            abtn.Text, abtn.Font, abtn.TextSize, abtn.TextColor3 = "AIM", Enum.Font.GothamBold, 16, Color3.fromRGB(255, 255, 255)
            abtn.BackgroundColor3, abtn.BackgroundTransparency, abtn.Visible = Color3.fromRGB(20, 30, 40), 0.25, false
            abtn.Parent = agui
            Instance.new("UICorner", abtn).CornerRadius = UDim.new(1, 0)
            local st = Instance.new("UIStroke", abtn); st.Color, st.Thickness = Color3.fromRGB(0, 230, 255), 2
            abtn.MouseButton1Click:Connect(function() toggled = not toggled end)
        end)
    end

    -- ===== Silent Aim (hooks) =====
    -- gate: só mexe na mira enquanto você usa uma skill (Z X C V F), segura o clique, ou até 0,35s depois de soltar
    local function gateOpen()
        if not SA.pos or not SA.roll then return false end
        if Config.AimGate == "Always" or touchOnly then return true end
        if UIS:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) then return true end
        for _, k in ipairs(SKILL_KEYS) do
            if UIS:IsKeyDown(k) then return true end
        end
        return os.clock() - SA.releaseAt < 0.35
    end
    local function effMode()
        local m = Config.AimMode
        if (m == "Silent" or m == "Both") and not hookmetamethod then return "Camera Lock" end
        return m
    end
    local hooked = false
    local function installHooks()
        if hooked or not hookmetamethod then return end
        hooked = true
        local mouse = Player:GetMouse()
        local wrap = newcclosure or function(f) return f end
        local isCaller = checkcaller or function() return false end
        local ok1 = pcall(function()
            local old
            old = hookmetamethod(game, "__index", wrap(function(self, key)
                if self == mouse and (key == "Hit" or key == "Target" or key == "X" or key == "Y" or key == "UnitRay")
                    and Alive and effMode() ~= "Camera Lock" and gateOpen() and not isCaller() and not (AFL.TV and AFL.TV.aimPos) then
                    if key == "Hit" then return CFrame.new(SA.pos)
                    elseif key == "Target" then return SA.part
                    elseif key == "X" then return SA.sx
                    elseif key == "Y" then return SA.sy
                    else
                        local cam = workspace.CurrentCamera
                        local o = cam and cam.CFrame.Position or Vector3.zero
                        return Ray.new(o, (SA.pos - o).Unit)
                    end
                end
                return old(self, key)
            end))
        end)
        if not ok1 then hooked = false; return end
        pcall(function()
            if not getnamecallmethod then return end
            local oldNc
            oldNc = hookmetamethod(game, "__namecall", wrap(function(self, ...)
                local m = getnamecallmethod()
                if (m == "GetMouseLocation" or m == "ScreenPointToRay" or m == "ViewportPointToRay")
                    and Alive and SA.pos and effMode() ~= "Camera Lock" and not isCaller() and gateOpen() then
                    if m == "GetMouseLocation" then
                        if self == UIS then return Vector2.new(SA.sx, SA.sy) end
                    elseif self == workspace.CurrentCamera then
                        local o = self.CFrame.Position
                        return Ray.new(o, (SA.pos - o).Unit)
                    end
                end
                if (m == "FireServer" or m == "InvokeServer") and Alive and SA.pos and effMode() ~= "Camera Lock"
                    and typeof(self) == "Instance" and not isCaller() and not (AFL.TV and AFL.TV.aimPos) then
                    local tool = Player.Character and Player.Character:FindFirstChildOfClass("Tool")
                    if tool and self:IsDescendantOf(tool) and self.Name ~= "LeftClickRemote" and gateOpen() then
                        local args = table.pack(...)
                        local changed = false
                        for i = 1, args.n do
                            local a = args[i]
                            if typeof(a) == "Vector3" and a.Magnitude > 3 and not changed then
                                args[i] = SA.pos; changed = true
                            end
                        end
                        if changed then
                            setnamecallmethod(m)
                            return oldNc(self, table.unpack(args, 1, args.n))
                        end
                    end
                end
                -- as chamadas aninhadas acima mudam o "método atual": restaura antes de chamar o original
                if setnamecallmethod then setnamecallmethod(m) end
                return oldNc(self, ...)
            end))
        end)
    end

    -- ===== loop principal =====
    local hiddenAll, offDone = false, false -- v43: esconder só escreve nas propriedades uma vez (e de novo depois de mostrar)
    local function hideAll()
        cur = nil
        SA.pos, SA.part = nil, nil
        if hiddenAll then return end
        hiddenAll = true
        if hl then hl.Enabled = false end
        if line then line.Visible = false end
        if label then label.Visible = false end
    end
    pcall(function() RunService:UnbindFromRenderStep("MoonHubAimbot") end)
    RunService:BindToRenderStep("MoonHubAimbot", Enum.RenderPriority.Camera.Value + 1, function(dt)
        if not Alive then
            pcall(function() RunService:UnbindFromRenderStep("MoonHubAimbot") end)
            SA.pos, SA.part = nil, nil
            pcall(function() if circle then circle:Remove() end end)
            pcall(function() if line then line:Remove() end end)
            pcall(function() if label then label:Remove() end end)
            pcall(function() if hl then hl:Destroy() end end)
            pcall(function() if fgui then fgui:Destroy() end end)
            pcall(function() if agui then agui:Destroy() end end)
            return
        end
        if not Config.AimOn then
            -- v43: Aimbot desligado: uma passada para esconder tudo e depois nenhum custo por frame
            if offDone then return end
            offDone, active = true, false
            if abtn then abtn.Visible = false end
            if circle then circle.Visible = false elseif fframe then fframe.Visible = false end
            hideAll()
            AB.status = "off"
            return
        end
        offDone = false
        local cam = workspace.CurrentCamera
        if not cam then return end
        if abtn then
            abtn.Visible = Config.AimOn and Config.AimTrigger ~= "Always On"
            abtn.BackgroundColor3 = toggled and Color3.fromRGB(0, 120, 150) or Color3.fromRGB(20, 30, 40)
        end
        local color = COLORS[Config.AimFOVColor] or COLORS.Cyan
        local origin = (Config.AimFOVOrigin == "Center" or touchOnly) and (cam.ViewportSize / 2) or UIS:GetMouseLocation()
        local fov = tonumber(Config.AimFOV) or 160
        local showFov = Config.AimOn and Config.AimShowFOV
        if circle then
            circle.Visible = showFov and true or false
            if showFov then circle.Position = origin; circle.Radius = fov; circle.Color = color end
        elseif fframe then
            fframe.Visible = showFov and true or false
            if showFov then
                fframe.Size = UDim2.fromOffset(fov * 2, fov * 2)
                fframe.Position = UDim2.fromOffset(origin.X, origin.Y)
                local st = fframe:FindFirstChildOfClass("UIStroke"); if st then st.Color = color end
            end
        end

        active = isActive()
        if not active then
            hideAll()
            AB.status = Config.AimOn and "waiting for the key" or "off"
            return
        end

        local now = os.clock()
        if now - randAt > 0.5 then randAt = now; randIdx = math.random(1, #R15_PARTS) end
        if now - SA.rollAt > 0.3 then
            SA.rollAt = now
            SA.roll = Config.AimGuarantee or math.random(1, 100) <= (tonumber(Config.AimHitChance) or 100)
        end
        -- procura alvo a ~33 Hz (o movimento da mira roda todo frame)
        if now - pickAt >= 0.03 or not cur then
            pickAt = now
            cur = pick(cam, origin)
        end
        -- v86: tentativa de deixar a mira mais resistente ao "solta o alvo depois de um golpe" - quando o personagem
        -- do alvo continua valido mas a PARTE que a mira usava (ex: HumanoidRootPart) sumiu por um instante (comum
        -- durante o "flinch"/ragdoll/animacao de dano de um hit), em vez de descartar o alvo inteiro ele tenta achar
        -- de novo a parte/Humanoid no MESMO personagem antes de desistir. Nao achei com certeza absoluta a causa
        -- exata sem testar ao vivo, mas isso cobre o padrao mais comum desse tipo de bug em jogos Roblox.
        if cur and cur.char and cur.char.Parent and not (cur.part and cur.part.Parent) then
            local hum2 = cur.char:FindFirstChildOfClass("Humanoid")
            local hrp2 = (cur.part and cur.char:FindFirstChild(cur.part.Name)) or cur.char:FindFirstChild("HumanoidRootPart")
            if hum2 and hrp2 and hum2.Health > 0 then cur.hum, cur.part = hum2, hrp2 else cur = nil end
        end
        if not (cur and cur.part and cur.part.Parent and cur.hum.Health > 0) then
            hideAll()
            AB.status = "no target in FOV"
            AB.cur = nil
            return
        end
        hiddenAll = false
        -- atualiza distância / parte (ela se mexe entre as buscas)
        cur.dist = (cur.part.Position - cam.CFrame.Position).Magnitude
        AB.cur = cur
        local pos = leadPos(cur.part, now)
        local offY = tonumber(Config.AimOffsetY) or 0
        if offY ~= 0 then pos = pos + Vector3.new(0, offY, 0) end
        local sv, son = cam:WorldToViewportPoint(pos)
        SA.pos, SA.part, SA.sx, SA.sy = pos, cur.part, sv.X, sv.Y

        local mode = effMode()
        if mode == "Silent" or mode == "Both" then installHooks() end
        if mode == "Camera Lock" or mode == "Both" then
            local goal = CFrame.lookAt(cam.CFrame.Position, pos)
            local s = Config.AimGuarantee and 1 or math.clamp(tonumber(Config.AimSmooth) or 0.35, 0.02, 1)
            local a = (s >= 1) and 1 or (1 - (1 - s) ^ (math.min(dt, 0.1) * 60))
            cam.CFrame = cam.CFrame:Lerp(goal, a)
        end
        if hl then
            hl.Enabled = Config.AimHighlight and true or false
            if hl.Adornee ~= cur.char then hl.Adornee = cur.char end
            hl.FillColor, hl.OutlineColor = color, color
        end
        if line then
            line.Visible = Config.AimLine and son and true or false
            if Config.AimLine then line.From, line.To, line.Color = origin, Vector2.new(sv.X, sv.Y), color end
        end
        local who = Players:GetPlayerFromCharacter(cur.char)
        local nm = who and who.Name or cur.char.Name
        local hp = cur.hum.MaxHealth > 0 and math.floor(cur.hum.Health / cur.hum.MaxHealth * 100) or 0
        if label then
            label.Visible = Config.AimInfo and son and true or false
            if Config.AimInfo then
                label.Text = string.format("%s  |  %dm  |  %d%%", nm, math.floor(cur.dist), hp)
                label.Position = Vector2.new(sv.X, sv.Y - 34)
                label.Color = color
            end
        end
        AB.status = string.format("%s -> %s (%dm, %d%% HP)%s", mode, nm, math.floor(cur.dist), hp, SA.roll and "" or " [miss roll]")
    end)

    -- ===== UI =====
    A:AddSection("Quick Setup")
    A:AddButton({ Title = "PvP Setup (One Click)", Description = "Sets everything up for fighting other players: Silent Aim, Players only, Guaranteed Hit, Always On, redirects on every attack (no need to hold a skill key)", Label = "Apply", Callback = function()
        local set = { AimOn = true, AimMode = "Silent", AimTargets = "Players", AimGuarantee = true, AimTrigger = "Always On", AimGate = "Always", AimPart = "HumanoidRootPart", AimSticky = true }
        for k, v in pairs(set) do
            Config[k] = v
            local o = Fluent.Options[k]
            if o and o.SetValue then pcall(function() o:SetValue(v) end) end
        end
        persist()
        pcall(function() Fluent:Notify({ Title = "Aimbot", Content = "PvP setup applied.", Duration = 3 }) end)
    end })

    A:AddSection("Aimbot")
    tg("AimOn", "Enable Aimbot", "Master switch. With a hold/toggle key below it only locks while that key is active", "AimOn")
    dd("AimMode", "Aim Mode", "Silent = your skills and clicks go to the target without moving the camera | Camera Lock = smooth camera lock | Both", { "Silent", "Camera Lock", "Both" }, "AimMode")
    dd("AimTargets", "Targets", "Who the aimbot locks on", { "Players", "NPCs", "Both" }, "AimTargets")
    dd("AimPriority", "Target Priority", "How the target is chosen inside the FOV. Lowest/Highest Health compare by HP % (fair between a boss and a common NPC)", { "Closest to Crosshair", "Closest Distance", "Lowest Health", "Highest Health" }, "AimPriority")
    dd("AimPart", "Aim Part", "Body part to aim at", { "HumanoidRootPart", "Head", "Torso", "Closest Part", "Random" }, "AimPart")

    A:AddSection("Low HP Finisher")
    tg("AimLowHPFinisher", "Enable Low HP Finisher", "Overrides whatever Target Priority is set above: whenever someone valid drops to/below the HP% threshold, the aimbot switches to them to secure the kill", "AimLowHPFinisher")
    sl("AimLowHPThreshold", "Finisher HP % Threshold", "A target at or below this HP% is always preferred over everyone else", "AimLowHPThreshold", 1, 100)

    A:AddSection("Activation")
    dd("AimTrigger", "Activation", "Always On, or only while holding / after toggling the key (mobile gets an AIM button)", { "Always On", "Hold Key", "Toggle Key" }, "AimTrigger")
    dd("AimKey", "Activation Key", "Key (or right mouse button) for Hold / Toggle", { "Q", "E", "R", "T", "G", "H", "LeftShift", "Space", "LeftAlt", "LeftControl", "CapsLock", "MouseButton2" }, "AimKey")
    dd("AimGate", "Silent Aim Gate", "On Skill / Click = the silent redirect only happens while you press one of the Gate Keys below or click (menus and buttons keep working) | Always = redirect all the time", { "On Skill / Click", "Always" }, "AimGate")
    multiDD("AimGateKeysDD", "Gate Keys", "Which keys count as 'using a skill' for the Gate above. Change this if you remapped your Blox Fruit skill keybinds in the game's own settings", GATE_KEY_NAMES, "AimGateKeys", rebuildGateKeys)

    A:AddSection("FOV")
    tg("AimShowFOV", "Show FOV Circle", "Draws the circle that limits the aimbot", "AimShowFOV")
    tg("AimGuarantee", "Guaranteed Hit", "Never misses: ignores FOV, wall check, hit chance and smoothing (instant lock, always redirects). Turn off to use the manual options below", "AimGuarantee")
    sl("AimFOV", "FOV Size", "Radius of the circle in pixels", "AimFOV", 30, 800)
    dd("AimFOVOrigin", "FOV Origin", "Follow the mouse or stay in the screen center", { "Mouse", "Center" }, "AimFOVOrigin")

    A:AddSection("Tuning")
    sl("AimSmooth", "Smoothness (Camera Lock)", "Low = slow and smooth, 1 = instant. Same feel at any FPS", "AimSmooth", 0.02, 1, 2)
    tg("AimPredictOn", "Prediction", "Leads the target using its measured movement (works with players that fly / dash)", "AimPredictOn")
    sl("AimPredict", "Prediction Time (s)", "Extra lead time on top of your ping", "AimPredict", 0, 0.6, 2)
    tg("AimAutoPing", "Ping Compensation", "Adds your current network ping to the prediction time", "AimAutoPing")
    sl("AimHitChance", "Silent Hit Chance %", "Chance that each silent redirect is applied (lower looks more legit)", "AimHitChance", 1, 100)
    sl("AimMaxDist", "Max Distance", "Ignore targets farther than this (studs)", "AimMaxDist", 50, 5000)
    sl("AimMinHP", "Min Target HP % (0 = off)", "Ignores targets with less life than this percent", "AimMinHP", 0, 100)
    sl("AimOffsetY", "Aim Offset Y (studs)", "Fine-tune exactly where the lock lands vertically on the chosen Aim Part. Positive = higher, negative = lower", "AimOffsetY", -50, 50)

    A:AddSection("Filters")
    tg("AimVisible", "Visible Check", "Skips targets behind walls", "AimVisible")
    tg("AimTeam", "Team Check", "Skips players of your own team", "AimTeam")
    tg("AimFF", "Ignore Safe Zone", "Skips players with a ForceField (spawn / safe zone)", "AimFF")
    tg("AimFriends", "Ignore Friends", "Skips your Roblox friends", "AimFriends")
    tg("AimSticky", "Sticky Target", "Keeps the same target until it leaves the FOV", "AimSticky")
    A:AddInput("AimIgnoreNames", { Title = "Ignore Usernames", Description = "Comma-separated usernames to never target (duo partners outside Team/Friends, your alt account...)", Default = tostring(Config.AimIgnoreNames or ""), Placeholder = "name1, name2", Numeric = false, Finished = true })
        :OnChanged(function(v) Config.AimIgnoreNames = tostring(v or ""); persist() end)

    A:AddSection("Visuals")
    dd("AimFOVColor", "Color", "Color of the circle / highlight / line / label", { "Cyan", "White", "Red", "Green", "Purple", "Yellow", "Pink", "Orange" }, "AimFOVColor")
    tg("AimHighlight", "Highlight Target", "Outlines the locked target", "AimHighlight")
    tg("AimInfo", "Target Info", "Shows name, distance and HP above the target (needs Drawing support)", "AimInfo")
    tg("AimLine", "Target Line", "Line from the FOV center to the target (needs Drawing support)", "AimLine")

    A:AddSection("Aimbot Status")
    local ainfo = A:AddParagraph({ Title = "Aimbot", Content = "Checking..." })
    task.spawn(function()
        while Alive do
            pcall(function()
                ainfo:SetDesc(table.concat({
                    "Aimbot: " .. (Config.AimOn and "ON" or "off") .. " | " .. tostring(Config.AimMode) .. " | " .. tostring(Config.AimTargets),
                    "Now: " .. tostring(AB.status),
                    "Silent hooks: " .. (hookmetamethod and (hooked and "active" or "ready") or "NOT supported by your executor (use Camera Lock)"),
                    "Drawing: " .. (hasDrawing and "yes" or "no (using a frame, no label/line)"),
                }, "\n"))
            end)
            task.wait(1)
        end
    end)
end)()




