    PC.src["macro"] = function() return [===[
local __E = ...
local AFL = __E.AFL
local Config, Connections, Fluent, Player, Tabs, persist = __E.Config, __E.Connections, __E.Fluent, __E.Player, __E.Tabs, __E.persist
local UserInputService = game:GetService("UserInputService")
local VirtualInputManager = game:GetService("VirtualInputManager")
local Alive = true
AFL.onUnload(function() Alive = false end)
-- ---------- Macro: combo configuravel disparado por uma tecla (v105, pedido do usuario) ----------
-- Cada passo tem: item (nome exato do Tool, equipado se precisar), acao (M1 ou tecla de skill Z/X/C/V/F) e um
-- delay antes do proximo passo. Reaproveita o MESMO jeito de clicar/apertar tecla que o resto do hub ja usa
-- (LeftClickRemote "as cegas" pra M1, VirtualInputManager:SendKeyEvent pra skill) - nada novo/arriscado.
;(function()
    local T = Tabs.Macro
    local UIS = UserInputService
    local M = {}
    AFL.Macro = M
    local function d(k, v) if Config[k] == nil then Config[k] = v end end
    d("MacroOn", false); d("MacroKey", "G"); d("MacroCooldown", 1)
    local SLOTS = 6
    local ACTIONS = { "M1 (Click)", "Z", "X", "C", "V", "F" }
    local KEY_LIST = { "G", "H", "T", "B", "N", "M", "Tab", "CapsLock", "LeftAlt", "LeftControl", "MouseButton2" }
    if type(Config.MacroSteps) ~= "table" then Config.MacroSteps = {} end
    for i = 1, SLOTS do
        local s = Config.MacroSteps[i]
        if type(s) ~= "table" then s = {}; Config.MacroSteps[i] = s end
        if s.on == nil then s.on = false end
        s.item = s.item or ""
        s.action = s.action or "M1 (Click)"
        s.delay = tonumber(s.delay) or 150
    end

    -- ===== execucao =====
    local running, lastRun = false, 0
    local function findTool(name)
        name = tostring(name or "")
        name = string.gsub(string.gsub(name, "^%s+", ""), "%s+$", "")
        if name == "" then return nil end
        local char, bp = Player.Character, Player.Backpack
        local t = (char and char:FindFirstChild(name)) or (bp and bp:FindFirstChild(name))
        return (t and t:IsA("Tool")) and t or nil
    end
    local function pressSkill(name)
        local kc = Enum.KeyCode[name]
        if not kc then return end
        pcall(function()
            VirtualInputManager:SendKeyEvent(true, kc, false, game)
            task.wait(0.1)
            VirtualInputManager:SendKeyEvent(false, kc, false, game)
        end)
    end
    local function fireM1(t)
        pcall(function() t:Activate() end)
        local remote = t:FindFirstChild("LeftClickRemote")
        if remote then pcall(remote.FireServer, remote, Vector3.new(0.01, -500, 0.01), 1, true) end
    end
    local function runStep(s)
        local t = findTool(s.item)
        if not t then M.status = "Macro: '" .. tostring(s.item) .. "' not found (backpack/equipped)"; return end
        local hum = Player.Character and Player.Character:FindFirstChildOfClass("Humanoid")
        if hum and t.Parent ~= Player.Character then
            pcall(function() hum:EquipTool(t) end)
            task.wait(0.15) -- tempo pro equip replicar antes de atacar (igual ao Double Attack)
        end
        if s.action == "M1 (Click)" then fireM1(t) else pressSkill(s.action) end
    end
    function M.run()
        if running then return end
        running = true
        M.status = "Macro: running"
        for i = 1, SLOTS do
            if not Alive then break end
            local s = Config.MacroSteps[i]
            if s and s.on and s.item ~= "" then
                runStep(s)
                task.wait(math.clamp((tonumber(s.delay) or 150) / 1000, 0.03, 5))
            end
        end
        M.status = "Macro: idle"
        running = false
    end

    -- ===== gatilho =====
    local function isMacroKey(i)
        local k = Config.MacroKey
        if k == "MouseButton2" then return i.UserInputType == Enum.UserInputType.MouseButton2 end
        local ok, kc = pcall(function() return Enum.KeyCode[k] end)
        return ok and i.KeyCode == kc
    end
    table.insert(Connections, UIS.InputBegan:Connect(function(i, gp)
        if gp then return end
        if not Config.MacroOn then return end
        if not isMacroKey(i) then return end
        local now = os.clock()
        if now - lastRun < (tonumber(Config.MacroCooldown) or 1) then return end
        lastRun = now
        task.spawn(M.run)
    end))

    -- ===== UI =====
    T:AddSection("Macro")
    T:AddToggle("MacroOn", { Title = "Enable Macro", Description = "Turns the key below into your combo trigger", Default = Config.MacroOn and true or false })
        :OnChanged(function(v) Config.MacroOn = v; persist() end)
    do
        local function idx(list, v) for i, x in ipairs(list) do if x == v then return i end end return 1 end
        T:AddDropdown("MacroKeyDD", { Title = "Macro Key", Description = "Key that fires the whole combo below", Values = KEY_LIST, Default = idx(KEY_LIST, Config.MacroKey) })
            :OnChanged(function(v) Config.MacroKey = v; persist() end)
    end
    T:AddSlider("MacroCooldown", { Title = "Cooldown Between Runs (s)", Description = "Minimum time before the key can fire the combo again (avoids restarting mid-combo if you hold/mash it)", Min = 0.2, Max = 5, Default = math.clamp(tonumber(Config.MacroCooldown) or 1, 0.2, 5), Rounding = 1 })
        :OnChanged(function(v) Config.MacroCooldown = v; persist() end)
    T:AddButton({ Title = "Run Once (Test)", Description = "Runs the combo right now, without needing the key - useful to check the order while not in a fight", Label = "Run", Callback = function() task.spawn(M.run) end })

    for i = 1, SLOTS do
        T:AddSubSection("Step " .. i)
        local s = Config.MacroSteps[i]
        T:AddToggle("MacroStepOn" .. i, { Title = "Enabled", Description = "Off = this step is skipped entirely", Default = s.on and true or false })
            :OnChanged(function(v) Config.MacroSteps[i].on = v; persist() end)
        T:AddInput("MacroStepItem" .. i, { Title = "Item (exact name)", Description = "Exact Tool name - a sword, gun or Blox Fruit, equipped or in your backpack", Default = tostring(s.item or ""), Placeholder = "e.g. Dark Blade, Dragon Breath", Numeric = false, Finished = true })
            :OnChanged(function(v) Config.MacroSteps[i].item = tostring(v or ""); persist() end)
        do
            local function idx(list, v) for j, x in ipairs(list) do if x == v then return j end end return 1 end
            T:AddDropdown("MacroStepAction" .. i, { Title = "Attack", Description = "M1 = basic click. Z/X/C/V/F = that skill key (pressed while the item above is equipped)", Values = ACTIONS, Default = idx(ACTIONS, s.action) })
                :OnChanged(function(v) Config.MacroSteps[i].action = v; persist() end)
        end
        T:AddSlider("MacroStepDelay" .. i, { Title = "Delay After (ms)", Description = "Wait time before the next step runs", Min = 30, Max = 1000, Default = math.clamp(tonumber(s.delay) or 150, 30, 1000), Rounding = 0 })
            :OnChanged(function(v) Config.MacroSteps[i].delay = v; persist() end)
    end

    T:AddSection("Status")
    M.status = "Macro: idle"
    local para = T:AddParagraph({ Title = "Macro", Content = "Idle" })
    task.spawn(function()
        while Alive do
            pcall(function() para:SetDesc(M.status or "Idle") end)
            task.wait(0.3)
        end
    end)
end)()
]===] end
    PC.src["extras"] = function() return [===[
local __E = ...
local AFL = __E.AFL
local Config, Connections, Fight, Fluent, Player, StartTime, State = __E.Config, __E.Connections, __E.Fight, __E.Fluent, __E.Player, __E.StartTime, __E.State
local Tabs, flyTo, getChar, getPlayerLevel, getSea, persist = __E.Tabs, __E.flyTo, __E.getChar, __E.getPlayerLevel, __E.getSea, __E.persist
local Players = game:GetService("Players")
local Alive = true
AFL.onUnload(function() Alive = false end);
-- ---------- Extras (v32): Safe Mode, Time Hop, re-run after a hop, personal Discord webhook ----------
(function()
    local HttpSvc = game:GetService("HttpService")
    local function d(k, v) if Config[k] == nil then Config[k] = v end end
    d("SafeMode", false); d("SafeLow", 30); d("SafeHigh", 80)
    d("TimeHop", false); d("TimeHopMin", 20); d("HopReexec", true)
    d("UwUrl", ""); d("UwDeath", true); d("UwHop", true); d("UwEvents", true); d("UwErrors", false); d("UwEvery", 0); d("UwPing", "")
    d("MobileUI", false)

    -- text boxes: the value is applied right away (pasting works) and the file is saved 1.2s after the last key
    local persistSeq = 0
    local function persistSoon()
        persistSeq += 1
        local mine = persistSeq
        task.delay(1.2, function() if Alive and persistSeq == mine then persist() end end)
    end
    local function fmt(n)
        n = tonumber(n)
        if not n then return "-" end
        local s = tostring(math.floor(n))
        return (s:reverse():gsub("(%d%d%d)", "%1,"):reverse():gsub("^,", ""))
    end
    local function dataVal(name)
        local ok, v = pcall(function() return Player.Data[name].Value end)
        return ok and v or nil
    end

    -- ===== Safe Mode: low HP = fly straight up out of reach, rest, then go back to farming =====
    local S = { on = false, since = 0, upY = 0 }
    AFL.Safe = S
    local function controlling()
        if Config.Mode ~= nil or Config.KillTyrant then return true end
        for k, f in pairs(AFL.feat) do
            if k ~= "Safe" and not f.hidden and AFL.featOn(k, f) then return true end
        end
        return false
    end
    function S.step()
        local _, hrp, hum = getChar()
        if not (Config.SafeMode and hum and hrp) then S.on = false return false end
        local pct = hum.Health / math.max(1, hum.MaxHealth) * 100
        local low = math.clamp(tonumber(Config.SafeLow) or 30, 5, 90)
        local high = math.clamp(tonumber(Config.SafeHigh) or 80, low + 5, 100)
        if not S.on then
            -- only when the script is the one controlling the character (never yanks you around while you play by hand), and not on a boat
            if pct >= low or hum.SeatPart or not controlling() then return false end
            S.on, S.since, S.upY = true, os.clock(), hrp.Position.Y + 500
            pcall(function() Fluent:Notify({ Title = "Safe Mode", Content = string.format("HP at %d%%: flying up to recover", math.floor(pct)), Duration = 4 }) end)
        elseif pct >= high or os.clock() - S.since > 180 or not controlling() then
            S.on = false
            return false
        end
        State.Mode, State.Text = "Safe Mode", string.format("recovering HP: %d%% (back at %d%%)", math.floor(pct), math.floor(high))
        State.atkAt = os.clock() -- the supervisor must not think the farm is stuck while we rest
        Fight.active, Fight.inPos = false, false
        Config.AttackUntil = 0
        flyTo(CFrame.new(hrp.Position.X, math.max(S.upY, hrp.Position.Y), hrp.Position.Z))
        return true
    end
    AFL.feat.Safe = { label = "Safe Mode", hidden = true, listed = function() return false end, on = function() return Config.SafeMode == true end,
        run = function() return S.step() end }


    -- ===== Time Hop: change server every N minutes =====
    task.spawn(function()
        while Alive do
            task.wait(5)
            pcall(function()
                if not Config.TimeHop then return end
                local H = AFL.Hop
                local mins = math.clamp(tonumber(Config.TimeHopMin) or 20, 3, 120)
                if H.active or os.clock() - H.serverAt < mins * 60 or os.clock() - H.failAt < 30 then return end
                -- never in the middle of a boss fight, a raid or a dungeon
                if os.clock() - (State.bossAt or 0) < 15 then return end
                if AFL.Raid and AFL.Raid.active and AFL.Raid.active() then return end
                if AFL.Dun and AFL.Dun.active then return end
                AFL.hopRequest(string.format("timer (%d min)", mins), function() return not Config.TimeHop end)
            end)
        end
    end)

    -- ===== personal Discord webhook (each player uses THEIR OWN url) =====
    local UW = {}
    AFL.UW = UW
    UW.last = "-"
    local requestFn = (syn and syn.request) or http_request or (http and http.request) or request or httprequest
    local queue, pumping, lastSend = {}, false, 0
    local HOSTS = { "discord.com", "discordapp.com", "canary.discord.com", "ptb.discord.com" }
    function UW.valid()
        local u = Config.UwUrl
        if type(u) ~= "string" or #u < 45 then return false end
        for _, h in ipairs(HOSTS) do
            if string.sub(u, 1, #h + 22) == "https://" .. h .. "/api/web" .. "hooks/" then return true end
        end
        return false
    end
    local function pingInfo()
        local p = string.gsub(tostring(Config.UwPing or ""), "%s", "")
        local pl = string.lower(p)
        if pl == "everyone" or pl == "@everyone" then return "@everyone", { parse = { "everyone" } } end
        if pl == "here" or pl == "@here" then return "@here", { parse = { "everyone" } } end
        local id = string.match(p, "^<@!?(%d+)>$") or string.match(p, "^(%d+)$")
        if id and #id >= 15 then return "<@" .. id .. ">", { users = { id } } end
        return nil
    end
    local function post(payload)
        if not requestFn then return nil, "your executor has no request/http_request" end
        local ok, res = pcall(requestFn, {
            Url = Config.UwUrl, Method = "POST",
            Headers = { ["Content-Type"] = "application/json" },
            Body = HttpSvc:JSONEncode(payload),
        })
        if not ok then return nil, tostring(res) end
        local code = type(res) == "table" and (res.StatusCode or res.status_code) or nil
        return tonumber(code), res
    end
    function UW.pump()
        while Alive and #queue > 0 do
            local gap = 2.2 - (os.clock() - lastSend)
            if gap > 0 then task.wait(gap) end
            local p = table.remove(queue, 1)
            lastSend = os.clock()
            local code, res = post(p)
            if code == 429 then
                local ra = 3
                pcall(function() ra = tonumber(HttpSvc:JSONDecode(res.Body).retry_after) or 3 end)
                table.insert(queue, 1, p)
                UW.last = "rate limited by Discord, waiting " .. math.ceil(ra) .. "s"
                task.wait(math.clamp(ra, 1, 30))
            elseif code == 401 or code == 404 then
                queue = {}
                UW.last = "error " .. code .. " (invalid or deleted webhook)"
            elseif code and code < 300 then
                UW.last = "ok " .. os.date("%H:%M:%S")
            else
                UW.last = "error " .. tostring(code or res)
            end
        end
        pumping = false
    end
    -- v92: avatar da conta (so busca 1x - nao muda durante a sessao), pra entrar como thumbnail/autor do embed e o
    -- webhook parar de parecer uma mensagem de texto crua e ficar com cara de "card" de verdade, igual o resto do hub
    local AVATAR_URL
    pcall(function() AVATAR_URL = Players:GetUserThumbnailAsync(Player.UserId, Enum.ThumbnailType.HeadShot, Enum.ThumbnailSize.Size180x180) end)
    function UW.send(title, desc, color, fields, ping, noAvatar)
        if not UW.valid() then return false end
        if #queue >= 12 then table.remove(queue, 1) end
        local embed = {
            title = title, description = desc, color = color or 0x7A5CFF, fields = fields,
            author = { name = Player.Name .. " | Moon Hub Premium", icon_url = (not noAvatar) and AVATAR_URL or nil },
            thumbnail = (not noAvatar) and AVATAR_URL and { url = AVATAR_URL } or nil,
            footer = { text = "Moon Hub Premium  •  Blox Fruits" },
            timestamp = os.date("!%Y-%m-%dT%H:%M:%SZ"),
        }
        local payload = { username = "Moon Hub", embeds = { embed } }
        if ping then
            local txt, allowed = pingInfo()
            if txt then payload.content, payload.allowed_mentions = txt, allowed end
        end
        queue[#queue + 1] = payload
        if not pumping then pumping = true; task.spawn(UW.pump) end
        return true
    end
    local function hms(s) s = math.max(0, math.floor(s)); return string.format("%dh%02dm", math.floor(s / 3600), math.floor((s % 3600) / 60)) end
    local function stateFields()
        local f = {
            { name = "🏷️ Level", value = fmt(getPlayerLevel()), inline = true },
            { name = "💰 Beli", value = fmt(dataVal("Beli")), inline = true },
            { name = "🧩 Fragments", value = fmt(dataVal("Fragments")), inline = true },
            { name = "🌊 Sea", value = tostring(getSea()), inline = true },
            { name = "👥 Server", value = string.format("%d players", #Players:GetPlayers()), inline = true },
            { name = "⏱️ Script running", value = hms(os.time() - StartTime), inline = true },
            { name = "🎯 Doing", value = string.sub(tostring(State.Mode) .. " — " .. tostring(State.Text), 1, 200), inline = false },
        }
        return f
    end
    -- cada tipo de evento conhecido ganha emoji + cor proprios, em vez de tudo cair na mesma cor laranja generica
    local EVENT_LOOK = {
        { "awaken", "👑", 0xFFD700 }, { "mirage", "🌙", 0x9B59B6 }, { "prehistoric", "🦖", 0x2ECC71 },
        { "leviathan", "🐉", 0xE74C3C }, { "volcano", "🌋", 0xE67E22 }, { "volcanic", "🌋", 0xE67E22 },
    }
    local function eventLook(title)
        local low = string.lower(tostring(title))
        for _, kv in ipairs(EVENT_LOOK) do
            if string.find(low, kv[1], 1, true) then return kv[2], kv[3] end
        end
        return "📢", 0xF39C12
    end
    function UW.event(title, text)
        if not (Config.UwEvents and UW.valid()) then return end
        local emoji, color = eventLook(title)
        UW.send(emoji .. " " .. tostring(title), tostring(text), color, {
            { name = "🧭 JobId (join)", value = "```" .. tostring(game.JobId) .. "```", inline = false },
            { name = "🌊 Sea", value = tostring(getSea()), inline = true },
        })
    end
    function UW.hop(reason)
        if not (Config.UwHop and UW.valid()) then return end
        UW.send("🔁 Server hop", "**Reason:** " .. tostring(reason), 0x3498DB, stateFields())
    end
    function UW.death()
        if not (Config.UwDeath and UW.valid()) then return end
        UW.send("💀 You died", "Your character died.", 0xE74C3C, stateFields(), true)
    end
    local errAt = {}
    function UW.err(key, msg)
        if not (Config.UwErrors and UW.valid()) then return end
        local now = os.clock()
        if now - (errAt[key] or -1e9) < 300 or now - (errAt._any or -1e9) < 30 then return end
        errAt[key], errAt._any = now, now
        UW.send("⚠️ Script error", "**" .. tostring(key) .. "**\n```" .. string.sub(tostring(msg), 1, 500) .. "```", 0x992D22, nil, true)
    end
    function UW.summary()
        return UW.send("📊 Status report", "Here's how your Moon Hub Premium session is doing right now.", 0x9B59B6, stateFields())
    end
    function UW.test()
        if not UW.valid() then return false, "Invalid webhook URL (paste the full link Discord gives you for the channel webhook)" end
        if not requestFn then return false, "Your executor has no request/http_request" end
        UW.send("✅ Webhook test", "If you can read this, the webhook works! You'll get messages here for the events you turned on below.", 0x7A5CFF, {
            { name = "👤 Player", value = Player.Name, inline = true },
            { name = "🧭 Server", value = "`" .. string.sub(tostring(game.JobId), 1, 8) .. "…`", inline = true },
        })
        return true
    end
    function UW.statusText()
        return table.concat({
            "URL: " .. (UW.valid() and "ok" or ((Config.UwUrl or "") == "" and "empty" or "invalid")),
            "Executor: " .. (requestFn and "has request" or "NO request/http_request"),
            "Last send: " .. tostring(UW.last),
        }, "\n")
    end
    -- own death
    local function watchDeath(char)
        task.spawn(function()
            local hum = char:WaitForChild("Humanoid", 15)
            if not hum then return end
            table.insert(Connections, hum.Died:Connect(function() if Alive then pcall(UW.death) end end))
        end)
    end
    if Player.Character then watchDeath(Player.Character) end
    table.insert(Connections, Player.CharacterAdded:Connect(watchDeath))
    -- periodic report (the countdown restarts when you turn it on)
    task.spawn(function()
        local lastReport = os.clock()
        while Alive do
            task.wait(4)
            pcall(function()
                local every = tonumber(Config.UwEvery) or 0
                if every <= 0 then
                    lastReport = os.clock()
                elseif UW.valid() and os.clock() - lastReport >= every * 60 then
                    lastReport = os.clock()
                    UW.summary()
                end
            end)
        end
    end)

    -- ===== UI: Script Settings > Safety & Server =====
    local T = Tabs.Script
    T:AddSection("Safety & Server")
    T:AddToggle("SafeMode", { Title = "Safe Mode", Description = "When your HP gets low, the script flies you up out of reach, waits for your HP to recover and then goes back to farming (only while a farm function is on)", Default = Config.SafeMode and true or false })
        :OnChanged(function(v) Config.SafeMode = v; persist() end)
    T:AddSlider("SafeLow", { Title = "Safe Mode: escape below (% HP)", Description = "Escape when your HP drops under this", Min = 10, Max = 70, Default = math.clamp(tonumber(Config.SafeLow) or 30, 10, 70), Rounding = 0 })
        :OnChanged(function(v) Config.SafeLow = v; persist() end)
    T:AddSlider("SafeHigh", { Title = "Safe Mode: come back at (% HP)", Description = "Goes back to farming when your HP reaches this", Min = 40, Max = 100, Default = math.clamp(tonumber(Config.SafeHigh) or 80, 40, 100), Rounding = 0 })
        :OnChanged(function(v) Config.SafeHigh = v; persist() end)
    T:AddToggle("TimeHop", { Title = "Time Hop", Description = "Changes server every N minutes (never during a boss fight, raid or dungeon)", Default = Config.TimeHop and true or false })
        :OnChanged(function(v) Config.TimeHop = v; persist() end)
    T:AddSlider("TimeHopMin", { Title = "Time Hop: minutes in each server", Description = "How long to stay before changing server", Min = 3, Max = 120, Default = math.clamp(tonumber(Config.TimeHopMin) or 20, 3, 120), Rounding = 0 })
        :OnChanged(function(v) Config.TimeHopMin = v; persist() end)
    T:AddToggle("HopReexec", { Title = "Re-run after a server hop", Description = "After ANY teleport (hop made by the script, you changing server, a dungeon or changing sea) the loader runs again by itself and your options come back (needs the loader with your key; turn off if your executor already auto-executes)", Default = Config.HopReexec ~= false })
        :OnChanged(function(v) Config.HopReexec = v; persist() end)

    T:AddSection("Interface & Farm")
    T:AddToggle("MobileUI", { Title = "Mobile UI Version", Description = "Shrinks and repositions the window for a phone screen, so panels (like your profile card) don't overlap or get cut off. Takes effect right away; reopen a tab if something still looks off", Default = Config.MobileUI and true or false })
        :OnChanged(function(v) Config.MobileUI = v; persist(); pcall(function() if AFL.applyMobileUI then AFL.applyMobileUI() end end) end)
    -- v31: Bring Mob V2 mudou pra Farm Settings (junto do Bring Mob V1) - continua ligado por Config.BringMobV2, so que
    -- agora espelhando cfg.bringMobV2 (ve GET/SET BringMobV2 em pcompat.lua)

    -- ===== UI: Webhook tab (v92: reorganizada em sub-secoes + card de status "vivo", no lugar do paragrafo cru) =====
    local W = Tabs.Webhook
    W:AddSection("Discord Webhook")
    W:AddParagraph({ Title = "📡 Como funciona", Content = "Manda pro SEU canal do Discord: mortes, troca de servidor, eventos (Awakened Boss, Mirage Island, Prehistoric Island), erros e um relatorio de status - com cores, emoji e a foto do seu personagem em cada card. No Discord: canal > Editar Canal > Integracoes > Webhooks > Novo Webhook > Copiar URL. Nunca mostra essa URL pra ninguem: quem tiver ela consegue postar no seu canal." })

    W:AddSubSection("🔗 Conexao")
    W:AddInput("UwUrl", { Title = "Webhook URL", Description = "Cole o link do webhook do seu canal do Discord", Default = tostring(Config.UwUrl or ""), Placeholder = "cole o link do seu webhook aqui", Numeric = false })
        :OnChanged(function(v) Config.UwUrl = tostring(v or ""); persistSoon() end)
    W:AddInput("UwPing", { Title = "Me mencionar (na morte)", Description = "Seu ID numerico do Discord, everyone ou here. Vazio = sem mencao", Default = tostring(Config.UwPing or ""), Placeholder = "123456789012345678", Numeric = false })
        :OnChanged(function(v) Config.UwPing = tostring(v or ""); persistSoon() end)

    W:AddSubSection("🔔 O que avisar")
    W:AddToggle("UwDeath", { Title = "Avisar quando eu morrer", Description = "Manda uma mensagem quando seu personagem morre", Default = Config.UwDeath ~= false })
        :OnChanged(function(v) Config.UwDeath = v; persist() end)
    W:AddToggle("UwHop", { Title = "Avisar troca de servidor", Description = "Manda o motivo e seu status antes de trocar de servidor", Default = Config.UwHop ~= false })
        :OnChanged(function(v) Config.UwHop = v; persist() end)
    W:AddToggle("UwEvents", { Title = "Avisar eventos", Description = "Awakened Boss, Mirage Island e Prehistoric Island (com o JobId pra entrar junto)", Default = Config.UwEvents ~= false })
        :OnChanged(function(v) Config.UwEvents = v; persist() end)
    W:AddToggle("UwErrors", { Title = "Avisar erros do script", Description = "Manda uma mensagem quando uma funcao fica falhando (no maximo 1 a cada 30s)", Default = Config.UwErrors == true })
        :OnChanged(function(v) Config.UwErrors = v; persist() end)
    W:AddSlider("UwEvery", { Title = "Relatorio de status a cada (min, 0 = desliga)", Description = "Manda nivel, Beli, fragmentos e o que o script ta fazendo", Min = 0, Max = 120, Default = math.clamp(tonumber(Config.UwEvery) or 0, 0, 120), Rounding = 0 })
        :OnChanged(function(v) Config.UwEvery = v; persist() end)

    W:AddSubSection("🧪 Testar agora")
    W:AddButton({ Title = "Testar Webhook", Description = "Manda uma mensagem de teste agora", Callback = function()
        local ok, msg = UW.test()
        pcall(function() Fluent:Notify({ Title = "Webhook", Content = ok and "Mensagem de teste enviada. Olha seu canal." or tostring(msg), Duration = 6 }) end)
    end })
    W:AddButton({ Title = "Enviar relatorio agora", Description = "Manda o relatorio de status agora mesmo", Callback = function()
        local ok = UW.summary()
        pcall(function() Fluent:Notify({ Title = "Webhook", Content = ok and "Relatorio enviado." or "Webhook vazio ou invalido.", Duration = 5 }) end)
    end })

    W:AddSubSection("📶 Status")
    local whStat = W:AddStatus({ Title = "Webhook", Content = "Checando..." })
    local function uwState()
        if not requestFn then return "bad", "No HTTP", "Seu executor nao tem request/http_request" end
        local u = tostring(Config.UwUrl or "")
        if u == "" then return "off", "Vazio", "Cole a URL do seu webhook ali em cima pra ligar" end
        if not UW.valid() then return "bad", "Invalido", "Isso nao parece uma URL de webhook do Discord" end
        return "ok", "Pronto", "Ultimo envio: " .. tostring(UW.last)
    end
    task.spawn(function()
        while Alive do
            pcall(function()
                local st, pill, sub = uwState()
                whStat:Set(st, nil, sub, pill)
            end)
            task.wait(1)
        end
    end)
end)()




