    PC.src["normal2"] = function() return [===[
local __E = ...
local AFL = __E.AFL
local Config, Connections, Core, Diag, Fluent, InvCache, Player = __E.Config, __E.Connections, __E.Core, __E.Diag, __E.Fluent, __E.InvCache, __E.Player
local State, Tabs, aliveParts, bossAlive, cfAttack, currentTween, distanceTo = __E.State, __E.Tabs, __E.aliveParts, __E.bossAlive, __E.cfAttack, __E.currentTween, __E.distanceTo
local enemiesList, fightEnemy, findTool, findToolByName, flyTo, getChar, getPlayerLevel = __E.enemiesList, __E.fightEnemy, __E.findTool, __E.findToolByName, __E.flyTo, __E.getChar, __E.getPlayerLevel
local getSea, hasItem, invCount, invoke, matchName, persist = __E.getSea, __E.hasItem, __E.invCount, __E.invoke, __E.matchName, __E.persist
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")
local VirtualInputManager = game:GetService("VirtualInputManager")
local VirtualUser = game:GetService("VirtualUser")
local eliteStep = AFL.eliteStep
local Alive = true
AFL.onUnload(function() Alive = false end);
-- ============ Normal Farm extras (portado do v52) ============
-- Tyrant of the Skies, Dough King, Soul Reaper e extras do Bones (Random Surprise / Pray / Try Luck).
-- Os mobs sao farmados pelo motor do Premium (Core.groupStep: voo, Bring Mob, quest); aqui ficam as etapas especiais.
local Groups = Core.groups
local TyrantApi, KingApi, ReaperApi = {}, {}, {}
local Sum = { prince = 0, king = 0, reaper = 0, bones = 0 }

-- v71b: Core.groupStep (farm do Tiki Outpost / Cake Land / Conjured Cocoa) usa o motor de voo do Level Farm
-- (LV.active/LV.fly/LV.hold, heartbeat proprio), enquanto o resto do Auto Tyrant/Dough King (matar o boss, voar
-- pro boss/NPC, invocar) usa o motor compartilhado (flyTo/Fly.goal/currentTween, outro heartbeat). Quando um
-- passo troca de motor sem soltar o anterior, os dois ficam escrevendo no CFrame do personagem ao mesmo tempo
-- e por fora isso parece o personagem "voar e travar no ar" ate reativar a funcao (so ai o watchdog externo,
-- que demora até 0,8-1,2s, solta o motor antigo). Agora cada passo solta explicitamente o que nao vai usar.
local function releaseGroupEngine()
    for _, g in pairs(Groups) do
        if g.owned or g.ext then
            g.owned, g.ext = false, false
            pcall(function() if Core.level and Core.level.release then Core.level.release() end end)
        end
    end
end

local function posOf(inst)
    if inst:IsA("BasePart") then return inst.CFrame end
    if inst:IsA("Model") then return inst:GetPivot() end
end

-- ================================================================== TYRANT OF THE SKIES ====
-- Spawn do boss (wiki): matar 300 inimigos no Tiki Outpost (75 por olho das estatuas) e quebrar os 4 vasos da arena.
-- Aqui: vai ao Tiki Outpost, farma os mobs de la (toda kill conta) e mata o Tyrant assim que ele existir.
-- Com os 4 olhos acesos, quebra os 4 vasos (Skull Guitar mirando para baixo, ou M1 + skills das armas).
do
    local V = AFL.TV
    V.vases = {
        Vector3.new(-16230.123046875, 153.8718719482422, 1449.07373046875),
        Vector3.new(-16309.607421875, 153.9078826904297, 1452.01708984375),
        Vector3.new(-16313.8388671875, 153.9078826904297, 1339.071533203125),
        Vector3.new(-16234.29296875, 153.79917907714844, 1336.2052001953125),
    }
    V.transform = { "dragon", "leopard", "kitsune", "t-rex", "trex", "yeti", "mammoth", "venom", "gas" }
    V.needReset, V.running, V.idx, V.warnAt = false, false, 0, 0
    V.done = V.done or 0

    local Tiki = { pos = nil, at = -1e9, since = 0, last = 0 }
    local TikiMobs = { "Isle Outlaw", "Island Boy", "Sun-kissed Warrior", "Isle Champion", "Serpent Hunter", "Skull Slayer" }
    local TyrantNeed = 300
    local Count = { n = 0, hooked = setmetatable({}, { __mode = "k" }), boss = false, seenRev = -1, scanAt = 0, revAt = 0, pending = false }
    local Watch = { rev = 0, folder = nil }
    -- v53: o Tyrant pode nascer longe (fora do alcance de carregamento): ai o jogo guarda o modelo no ReplicatedStorage
    V.tyrantFar = function()
        local m = ReplicatedStorage:FindFirstChild("Tyrant of the Skies")
        if not m then return nil end
        local h = m:FindFirstChildOfClass("Humanoid")
        local p = m:FindFirstChild("HumanoidRootPart") or m.PrimaryPart
        if p and (not h or h.Health > 0) then return p end
    end

    -- todos os nomes de mobs vivos na ilha (para matar TODOS, nao so o tipo da quest)
    local function tikiNames(loc)
        local names, seen = {}, {}
        for _, n in ipairs(TikiMobs) do names[#names + 1] = n; seen[n] = true end
        for _, e in ipairs(enemiesList()) do
            local eh, er = aliveParts(e)
            if eh and not seen[e.Name] and not string.find(e.Name, "Tyrant", 1, true) and (er.Position - loc).Magnitude < 1500 then
                seen[e.Name] = true
                names[#names + 1] = e.Name
            end
        end
        return names
    end
    local function tikiLocation()
        if Tiki.pos or os.clock() - Tiki.at < 20 then return Tiki.pos end
        Tiki.at = os.clock()
        local pos
        pcall(function()
            local wo = workspace:FindFirstChild("_WorldOrigin")
            local locs = wo and wo:FindFirstChild("Locations")
            if locs then
                for _, p in ipairs(locs:GetChildren()) do
                    if string.find(string.lower(p.Name), "tiki", 1, true) then
                        pos = p:IsA("BasePart") and p.Position or (p.PrimaryPart and p.PrimaryPart.Position)
                        if pos then break end
                    end
                end
            end
            if not pos then
                local map = workspace:FindFirstChild("Map")
                if map then
                    for _, m in ipairs(map:GetChildren()) do
                        if string.find(string.lower(m.Name), "tiki", 1, true) and m:IsA("Model") then
                            pos = m:GetPivot().Position
                            break
                        end
                    end
                end
            end
        end)
        Tiki.pos = pos
        return pos
    end
    -- pontos de spawn de mobs perto do Tiki (do mais perto do centro para o mais longe)
    local function tikiSpawns(loc)
        local folders = {}
        local origin = workspace:FindFirstChild("_WorldOrigin")
        local f1 = origin and origin:FindFirstChild("EnemySpawns")
        local f2 = workspace:FindFirstChild("EnemySpawns")
        if f1 then table.insert(folders, f1) end
        if f2 then table.insert(folders, f2) end
        local out = {}
        for _, folder in ipairs(folders) do
            for _, sp in ipairs(folder:GetChildren()) do
                if sp:IsA("BasePart") and (sp.Position - loc).Magnitude < 1500 then
                    out[#out + 1] = { cf = sp.CFrame, d = (sp.Position - loc).Magnitude }
                end
            end
        end
        table.sort(out, function(a, b) return a.d < b.d end)
        return out
    end
    -- contador de mudancas da pasta Enemies (mob entrou/saiu): quem so precisa saber "algo mudou?" le Watch.rev
    local function watchEnemies()
        local f = workspace:FindFirstChild("Enemies")
        if f == Watch.folder then return f end
        for _, c in ipairs(Watch.cons or {}) do pcall(function() c:Disconnect() end) end
        Watch.folder, Watch.cons, Watch.rev = f, {}, Watch.rev + 1
        if f then
            local function bump() Watch.rev += 1 end
            Watch.cons[1], Watch.cons[2] = f.ChildAdded:Connect(bump), f.ChildRemoved:Connect(bump)
            table.insert(Connections, Watch.cons[1]); table.insert(Connections, Watch.cons[2])
        end
        return f
    end
    -- O jogo nao expoe o contador de kills; o script conta as mortes de mobs do Tiki que ele enxerga (usado so se o mapa
    -- nao tiver o modelo dos olhos). 300 kills = 4 olhos. Zera quando o Tyrant nasce.
    local function track()
        if getSea() ~= 3 then return end
        local loc = tikiLocation()
        watchEnemies()
        local now = os.clock()
        if Watch.rev == Count.seenRev then
            if now - Count.scanAt < 2 and not (Count.pending and now - Count.revAt < 3) then return end
        else
            Count.seenRev, Count.revAt = Watch.rev, now
        end
        Count.scanAt, Count.pending = now, false
        if bossAlive("Tyrant of the Skies") then
            Count.boss, Count.n = true, 0 -- o boss nasceu: o ciclo foi consumido
            V.needReset = true
            return
        end
        Count.boss = false
        for _, e in ipairs(enemiesList()) do
            if not Count.hooked[e] then
                local hum, er = e:FindFirstChildOfClass("Humanoid"), e:FindFirstChild("HumanoidRootPart")
                if not (hum and er) then Count.pending = true end
                if hum and er and hum.Health > 0 then
                    Count.hooked[e] = true
                    if not string.find(e.Name, "Tyrant", 1, true)
                        and ((loc and (er.Position - loc).Magnitude < 1500) or matchName(e.Name, TikiMobs)) then
                        local done, c1, c2 = false, nil, nil
                        local function dead()
                            if done then return end
                            done = true
                            if c1 then c1:Disconnect() end
                            if c2 then c2:Disconnect() end
                            if not Count.boss then Count.n = math.min(TyrantNeed, Count.n + 1) end
                        end
                        c1 = hum.Died:Connect(dead)
                        c2 = hum:GetPropertyChangedSignal("Health"):Connect(function()
                            if hum.Health <= 0 then dead() end
                        end)
                    end
                end
            end
        end
    end
    task.spawn(function()
        while Alive do
            if Config.KillTyrant then pcall(track) end
            task.wait(0.25)
        end
    end)

    -- olhos: lidos do mapa (TikiOutpost.IslandModel.Eye1..4, Transparency == 0)
    local function eyes()
        local map = workspace:FindFirstChild("Map")
        local tiki = map and map:FindFirstChild("TikiOutpost")
        local island = tiki and tiki:FindFirstChild("IslandModel")
        if not island then return 0, false end
        local c = 0
        for i = 1, 4 do
            local eye = island:FindFirstChild("Eye" .. i, true)
            if eye and eye:IsA("BasePart") and eye.Transparency == 0 then c += 1 end
        end
        return c, true
    end

    -- vasos: arma e teclas escolhidas na aba Normal Farm. Padrao: Skull Guitar com M1 + X
    local function potWeapon()
        local w = Config.PotWeapon
        if type(w) ~= "string" or w == "" then w = "Skull Guitar" end
        return w
    end
    local function potKeys()
        local k = Config.PotKeys
        if type(k) ~= "table" or next(k) == nil then return { M1 = true, X = true } end
        return k
    end
    local function potKey(name)
        local kc = Enum.KeyCode[name]
        if not kc then return end
        pcall(function()
            VirtualInputManager:SendKeyEvent(true, kc, false, game)
            task.wait(0.1)
            VirtualInputManager:SendKeyEvent(false, kc, false, game)
        end)
    end
    -- mira PARA BAIXO (camera -89 graus + hook no mouse) e executa a acao
    local function aimDown(pos, action)
        local char = Player.Character
        if not char then return end
        local params = RaycastParams.new()
        params.FilterType = Enum.RaycastFilterType.Exclude
        params.FilterDescendantsInstances = { char, workspace:FindFirstChild("Enemies") or char }
        local hit = workspace:Raycast(pos, Vector3.new(0, -300, 0), params)
        local aimPos = hit and hit.Position or (pos - Vector3.new(0, 20, 0))
        local aimPart = hit and hit.Instance
        AFL.tvHook()
        V.aimPos, V.aimPart = aimPos, aimPart
        local cam = workspace.CurrentCamera
        pcall(function() RunService:UnbindFromRenderStep("MoonHubAimDown") end)
        pcall(function()
            RunService:BindToRenderStep("MoonHubAimDown", Enum.RenderPriority.Camera.Value + 2, function()
                local _, yaw = cam.CFrame:ToOrientation()
                cam.CFrame = CFrame.new(cam.CFrame.Position) * CFrame.fromOrientation(-math.rad(89), yaw, 0)
            end)
        end)
        task.wait(0.2)
        pcall(action, aimPos, aimPart)
        pcall(function() RunService:UnbindFromRenderStep("MoonHubAimDown") end)
        V.aimPos, V.aimPart = nil, nil
    end
    local function shoot(pos)
        aimDown(pos, function(aimPos, aimPart)
            local char = Player.Character
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            local netF = ReplicatedStorage:FindFirstChild("Modules") and ReplicatedStorage.Modules:FindFirstChild("Net")
            local shootEvent = netF and netF:FindFirstChild("RE/ShootGunEvent")
            local cam = workspace.CurrentCamera
            local keys = potKeys()
            local function sgTool()
                local tool = char and char:FindFirstChildOfClass("Tool")
                if not (tool and tool.Name == "Skull Guitar") then
                    local g = Player.Backpack:FindFirstChild("Skull Guitar")
                    if g and hum then hum:EquipTool(g) task.wait(0.3) end
                    tool = char and char:FindFirstChildOfClass("Tool")
                end
                return tool
            end
            for _ = 1, (keys.M1 and 5 or 0) do
                if not (Alive and Config.KillTyrant) then return end
                local tool = sgTool()
                if not tool then return end
                pcall(function() tool:Activate() end)
                pcall(function()
                    VirtualUser:CaptureController()
                    VirtualUser:Button1Down(Vector2.new(1280, 672))
                    VirtualUser:Button1Up(Vector2.new(1280, 672))
                end)
                if mouse1click and getgenv().MoonWinOn() then pcall(mouse1click) end
                pcall(function()
                    local s = cam.ViewportSize
                    local cx, cy = s.X / 2, s.Y / 2
                    VirtualInputManager:SendMouseButtonEvent(cx, cy, 0, true, game, 0)
                    VirtualInputManager:SendMouseButtonEvent(cx, cy, 0, false, game, 0)
                end)
                pcall(function()
                    local s = cam.ViewportSize
                    local cx, cy = s.X / 2, s.Y / 2
                    VirtualInputManager:SendTouchEvent(1, 0, cx, cy)
                    task.wait(0.05)
                    VirtualInputManager:SendTouchEvent(1, 2, cx, cy)
                end)
                if shootEvent then pcall(shootEvent.FireServer, shootEvent, aimPos, { aimPart }) end
                local sf = tool:FindFirstChild("RemoteFunctionShoot")
                if sf then task.spawn(pcall, sf.InvokeServer, sf, aimPos, aimPart) end
                task.wait(0.3)
            end
            for _, k in ipairs({ "Z", "X", "C", "V", "F" }) do
                if not (Alive and Config.KillTyrant) then return end
                if keys[k] and sgTool() then
                    potKey(k)
                    task.wait(0.4)
                end
            end
        end)
    end
    -- sem Skull Guitar: cada arma que voce tiver (fruta, melee, espada, gun): M1 por ~1s + skills Z X C V F
    local function skills(abort, only)
        local char = Player.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if not hum then return end
        local keys = only and potKeys() or nil
        for _, tip in ipairs(only and { only } or { "Blox Fruit", "Melee", "Sword", "Gun" }) do
            if abort() then return end
            local tool = findTool(tip)
            if tool then
                hum:EquipTool(tool)
                task.wait(0.3)
                local t0 = os.clock()
                while (not keys or keys.M1) and os.clock() - t0 < 1.2 and not abort() do
                    if tip == "Melee" then
                        pcall(cfAttack)
                    elseif tip == "Blox Fruit" then
                        -- v53: M1 de fruta pelo motor do Premium (remote mirado) + Activate: bem mais rapido
                        pcall(Core.fruitTick)
                        pcall(function() tool:Activate() end)
                    else
                        pcall(function() tool:Activate() end)
                    end
                    task.wait(tip == "Blox Fruit" and 0.03 or 0.06)
                end
                local low = string.lower(tool.Name)
                local isTransform = false
                for _, w in ipairs(V.transform) do
                    if tip == "Blox Fruit" and string.find(low, w, 1, true) then isTransform = true end
                end
                for _, k in ipairs({ "Z", "X", "C", "V", "F" }) do
                    if abort() then return end
                    if (not keys or keys[k]) and not (isTransform and k == "V" and not keys) then
                        potKey(k)
                        task.wait(0.3)
                    end
                end
            end
        end
    end
    -- uma rodada nos 4 vasos (em segundo plano; so inicia se nao houver outra em andamento)
    local function round()
        if V.running then return end
        V.running = true
        task.spawn(function()
            local function abort()
                if not (Alive and Config.KillTyrant and Config.TyrantSpawn) then return true end
                if bossAlive("Tyrant of the Skies") ~= nil or V.tyrantFar() ~= nil then return true end
                -- v53: outra funcao (ou o Safe Mode) pegou o personagem: para a rodada em vez de brigar com ela pelo voo
                if Core.owner and Core.owner ~= "Auto Tyrant" then return true end
                return false
            end
            local ok, err = pcall(function()
                for i, pos in ipairs(V.vases) do
                    if abort() then break end
                    V.idx = i
                    local cf = CFrame.new(pos)
                    local t0 = os.clock()
                    while not abort() and os.clock() - t0 < 60 do
                        local _, hrp = getChar()
                        if not hrp or (hrp.Position - pos).Magnitude <= 8 then break end
                        flyTo(cf)
                        task.wait(0.1)
                    end
                    if abort() then break end
                    local _, hrp = getChar()
                    if hrp then
                        if currentTween then currentTween:Cancel() end
                        hrp.CFrame = cf
                        hrp.AssemblyLinearVelocity = Vector3.zero
                    end
                    local pw = potWeapon()
                    if pw ~= "Skull Guitar" and pw ~= "All weapons" and findTool(pw) then
                        Diag.summon = string.format("Auto Tyrant step 2: pot %d/%d with %s (selected keys)", i, #V.vases, pw)
                        aimDown(pos, function() skills(abort, pw) end)
                    elseif pw == "Skull Guitar" and findToolByName("skull guitar") then
                        Diag.summon = string.format("Auto Tyrant step 2: pot %d/%d with the Skull Guitar", i, #V.vases)
                        shoot(pos)
                    else
                        if os.clock() - V.warnAt > 30 then
                            V.warnAt = os.clock()
                            pcall(function() Fluent:Notify({ Title = "Moon Hub - Tyrant", Content = "No Skull Guitar: using M1 + weapon skills", Duration = 5 }) end)
                        end
                        Diag.summon = string.format("Auto Tyrant step 2: pot %d/%d with M1 + skills (no Skull Guitar)", i, #V.vases)
                        aimDown(pos, function() skills(abort) end)
                    end
                    local t1 = os.clock()
                    while os.clock() - t1 < 0.6 and not abort() do task.wait(0.1) end   -- v53: 2 s -> 0,6 s entre os vasos
                end
                V.done += 1
            end)
            if not ok then Diag.summon = "Auto Tyrant step 2: error " .. tostring(err) end
            pcall(function() RunService:UnbindFromRenderStep("MoonHubAimDown") end)
            V.aimPos, V.aimPart = nil, nil
            V.running = false
        end)
    end

    function TyrantApi.statusText()
        if getSea() ~= 3 then return "Only works in Sea 3" end
        if Count.boss then return "Tyrant of the Skies has already spawned! (count reset)" end
        local left = math.max(0, TyrantNeed - Count.n)
        local tag = Config.KillTyrant and "" or "  [Auto Tyrant off]"
        local eyesRead, known = eyes()
        if known then
            if eyesRead >= 4 then
                return string.format("Eyes 4/4 lit - step 2: breaking the pots (rounds: %d). Then the Tyrant spawns.%s", V.done or 0, tag)
            end
            return string.format("Eyes %d/4 (read from the map) - script count: %d/%d NPCs%s", eyesRead, Count.n, TyrantNeed, tag)
        end
        if left <= 0 then
            return string.format("%d/%d - step 2: breaking the pots (rounds: %d).%s", Count.n, TyrantNeed, V.done or 0, tag)
        end
        local e4 = math.min(4, math.floor(Count.n / 75))
        return string.format("%d NPCs left (%d/%d) - eyes %d/4, %d to the next%s", left, Count.n, TyrantNeed, e4, 75 - (Count.n % 75), tag)
    end

    -- um passo do Auto Tyrant (chamado pelo arbitro)
    function TyrantApi.step()
        if getSea() ~= 3 then
            Diag.summon = "Auto Tyrant: only works in Sea 3"
            return false
        end
        local _, hrp = getChar()
        if not hrp then return false end
        -- boss vivo: mata primeiro (so com "Auto Kill Tyrant")
        if Config.TyrantKill then
            local boss = bossAlive("Tyrant of the Skies")
            if boss then
                releaseGroupEngine()
                State.Mode, State.Text = "Auto Tyrant of the Skies", "Killing " .. boss.Name
                fightEnemy(boss, { boss.Name }, false)
                return true
            end
            -- v53: o boss nasceu mas ainda nao carregou (longe): voa ate ele em vez de continuar farmando/quebrando vaso
            local far = V.tyrantFar()
            if far then
                releaseGroupEngine()
                State.Mode, State.Text = "Auto Tyrant of the Skies", "Tyrant spawned: flying to it"
                Diag.summon = "Auto Tyrant: the boss is alive but not loaded yet - flying to it"
                flyTo(far.CFrame * CFrame.new(0, 40, 0))
                return true
            end
        end
        -- 4 olhos acesos (lidos do mapa) = proxima missao: quebrar os 4 vasos. Sem o modelo dos olhos: 300 kills.
        local eyeN, known = eyes()
        local lit = known and (eyeN >= 4) or ((not known) and Count.n >= TyrantNeed)
        if not lit then V.needReset, V.stuckSince = false, nil end
        -- v71: anti-travada - se os "4 olhos acesos" continuam lidos assim por muito tempo com o boss ja morto/sem
        -- nascer de novo e o round() nao estiver rodando, o ciclo provavelmente ficou presa (olhos nao resetaram
        -- visualmente, ou a contagem de kills de reserva nunca chegou nos 300 nesse build do jogo). Forca um novo
        -- ciclo em vez de ficar "travado" pra sempre - e o mesmo tipo de watchdog que o Status ja usa pro M1.
        if lit and V.needReset and not Count.boss then
            V.stuckSince = V.stuckSince or os.clock()
            if os.clock() - V.stuckSince > 90 and not V.running then
                Diag.summon = "Auto Tyrant: still showing eyes 4/4 after 90s with no boss - forcing a new cycle"
                V.needReset = false
            end
        end
        if lit and not V.needReset and not Count.boss then
            if not Config.TyrantSpawn then
                Diag.summon = "Auto Tyrant: Auto Spawn is off (the pots will not be broken)"
                return false
            end
            releaseGroupEngine()
            V.stuckSince = nil
            State.Mode = "Auto Tyrant of the Skies"
            State.Text = string.format("Breaking pots (%d/%d, rounds: %d)", math.max(V.idx, 1), #V.vases, V.done)
            round()
            return true
        end

        local loc = tikiLocation()
        if not loc then
            Diag.summon = "Auto Tyrant: could not find the Tiki Outpost on the map (go there once)"
            return false
        end
        local best, bd, n = nil, math.huge, 0
        for _, e in ipairs(enemiesList()) do
            local eh, er = aliveParts(e)
            if eh and not string.find(e.Name, "Tyrant", 1, true)
                and ((er.Position - loc).Magnitude < 1500 or matchName(e.Name, TikiMobs)) then
                n += 1
                local d = (hrp.Position - er.Position).Magnitude
                if d < bd then best, bd = e, d end
            end
        end
        State.Mode = "Auto Tyrant of the Skies"
        local now = os.clock()
        if best then
            Tiki.since, Tiki.last = now, now
            Diag.summon = string.format("Auto Tyrant: Tiki Outpost; mobs alive nearby: %d (every kill counts for the statues)", n)
            if getPlayerLevel() >= 2450 then
                -- motor de farm do Premium (quest da ilha Tiki opcional): solta o motor de voo compartilhado
                -- (senao os dois motores ficam escrevendo no CFrame do personagem ao mesmo tempo)
                pcall(function() currentTween:Cancel() end)
                Core.groupStep(Groups.Tiki, Config.TyrantQuest == true)
                State.Text = "Tiki Outpost: " .. tostring(Groups.Tiki.text) .. string.format(" (%d NPCs left)", math.max(0, TyrantNeed - Count.n))
            else
                releaseGroupEngine()
                State.Text = string.format("Farming the Tiki Outpost: %s (%d NPCs left)", best.Name, math.max(0, TyrantNeed - Count.n))
                fightEnemy(best, tikiNames(loc), true)
            end
            return true
        end
        -- nenhum mob carregado: patrulha para o jogo carregar/nascer os mobs
        releaseGroupEngine()
        if now - Tiki.last > 3 then Tiki.since = now end -- comecou uma nova busca
        Tiki.last = now
        local t = now - Tiki.since
        local sps = tikiSpawns(loc)
        local target
        if #sps > 0 then
            local idx = (math.floor(t / 6) % #sps) + 1
            target = sps[idx].cf * CFrame.new(0, 25, 0)
            State.Text = string.format("Tiki Outpost: looking for mobs (point %d/%d)", idx, #sps)
            Diag.summon = string.format("Auto Tyrant: no mobs alive; visiting Tiki spawns (%d/%d)", idx, #sps)
        else
            local k = math.floor(t / 5) % 8
            local ang = k * math.pi / 4
            local r = 250 + 200 * (math.floor(t / 40) % 3)
            target = CFrame.new(loc + Vector3.new(math.cos(ang) * r, 60, math.sin(ang) * r))
            State.Text = "Tiki Outpost: looking for mobs (patrolling around the island)"
            Diag.summon = string.format("Auto Tyrant: no mobs and no known spawns; patrolling around (radius %d)", r)
        end
        flyTo(target)
        return true
    end
    TyrantApi.potWeapon, TyrantApi.potKeys = potWeapon, potKeys
end

-- ===================================================================== DOUGH KING ====
-- Auto Dough King: 1) Elite Hunter ate dropar o God's Chalice  2) 10 Conjured Cocoa  3) troca no Sweet Crafter pelo
-- Sweet Chalice  4) com o calice, farma a Cake Land (500 kills) e invoca/mata o boss.
do
    local lastTrade = 0
    local COCOA_NPC = CFrame.new(231, 23, -12200)
    local function farmDough(label)
        local g = Groups.Dough
        pcall(function() currentTween:Cancel() end)
        Core.groupStep(g, Config.AutoQuestKing ~= false)
        State.Text = label .. ": " .. tostring(g.text)
    end
    local function chain()
        State.Mode = "Auto Dough King"
        if Config.IgnoreDoughChaliceFarm and not hasItem("Sweet Chalice") then
            farmDough("Dough King: farm/boss only (Ignore item)")
            return
        end
        if hasItem("Sweet Chalice") then
            if not tostring(Diag.summon or ""):find("Dough King") then Diag.summon = "Sweet Chalice ready: farming Cake Land (500 kills)" end
            farmDough("Cake Land (500 kills)")
            return
        end
        if not hasItem("God's Chalice") then
            State.Text = "Elite Hunter (looking for God's Chalice)"
            if eliteStep(Config.AutoQuestKing ~= false) then return end
            farmDough("Cake Land")
            return
        end
        local cocoa = invCount("Conjured Cocoa")
        if cocoa < 10 then
            local g = Groups.Cocoa
            pcall(function() currentTween:Cancel() end)
            Core.groupStep(g, Config.AutoQuestKing ~= false)
            State.Text = string.format("Farming Conjured Cocoa (%d/10): %s", cocoa, tostring(g.text))
            return
        end
        State.Text = "Switching to the Sweet Chalice"
        if os.clock() - lastTrade > 8 then
            lastTrade = os.clock()
            InvCache.at = 0
            local ok, r = invoke("SweetChaliceNpc")
            Diag.summon = "Sweet Crafter: " .. (ok and "" or "error ") .. tostring(r)
        end
        releaseGroupEngine()
        if distanceTo(COCOA_NPC) > 300 then flyTo(COCOA_NPC) end -- Chocolate Land (o NPC fica por perto)
    end

    function KingApi.step()
        if getSea() ~= 3 then return false end
        local now = os.clock()
        -- boss vivo: mata primeiro
        if Config.KillDoughKing then
            local boss = bossAlive("Dough King")
            if boss then
                releaseGroupEngine()
                State.Mode, State.Text = "Auto Kill Dough King", "Killing " .. boss.Name
                fightEnemy(boss, { boss.Name }, false)
                return true
            end
        end
        -- invoca com o Sweet Chalice
        if Config.SummonDoughKing and now - Sum.king > 6 and not bossAlive("Dough King") then
            Sum.king = now
            if hasItem("Sweet Chalice") then
                task.spawn(function()
                    local ok, r = invoke("CakePrinceSpawner")
                    Diag.summon = "Dough King: " .. (ok and "" or "error ") .. tostring(r)
                end)
            else
                Diag.summon = "Dough King: no Sweet Chalice (use Auto Dough King to get one)"
            end
        end
        if Config.KingOn then
            chain()
            return true
        end
        return false
    end
    KingApi.chain = chain
end

-- =================================================================== SOUL REAPER ====
do
    function ReaperApi.step()
        if getSea() ~= 3 then return false end
        local now = os.clock()
        if Config.KillReaper then
            local boss = bossAlive("Soul Reaper")
            if boss then
                State.Mode, State.Text = "Auto Kill Soul Reaper", "Killing " .. boss.Name
                fightEnemy(boss, { boss.Name }, false)
                return true
            end
        end
        -- Soul Reaper: usa a Hallow Essence no altar (precisa estar com ela)
        if Config.SummonReaper and not bossAlive("Soul Reaper") then
            if not hasItem("Hallow Essence") then
                Diag.summon = "Soul Reaper: no Hallow Essence"
            elseif now - Sum.reaper > 8 then
                local map = workspace:FindFirstChild("Map")
                local hc = map and map:FindFirstChild("Haunted Castle")
                local altar = hc and hc:FindFirstChild("Summoner", true)
                local cf = altar and posOf(altar)
                if not cf then
                    Diag.summon = "Soul Reaper: altar not found (go to the Haunted Castle with the Hallow Essence)"
                elseif distanceTo(cf) > 14 then
                    State.Mode, State.Text = "Auto Summon Soul Reaper", "Going to the altar"
                    flyTo(cf * CFrame.new(0, 4, 0))
                    return true
                else
                    Sum.reaper = now
                    local _, hrp, hum = getChar()
                    local tool = Player.Backpack:FindFirstChild("Hallow Essence")
                    if tool and hum then pcall(function() hum:EquipTool(tool) end) end
                    pcall(function()
                        for _, d in ipairs(altar:GetDescendants()) do
                            if d:IsA("BasePart") and hrp then
                                firetouchinterest(hrp, d, 0)
                                firetouchinterest(hrp, d, 1)
                            end
                        end
                        if altar:IsA("BasePart") and hrp then
                            firetouchinterest(hrp, altar, 0)
                            firetouchinterest(hrp, altar, 1)
                        end
                    end)
                    Diag.summon = "Soul Reaper: touched the altar with the Hallow Essence"
                end
            end
        end
        return false
    end
end

-- ===================================== extras do Bones (rotina de fundo, nao ocupa o personagem) ====
task.spawn(function()
    while Alive do
        task.wait(0.5)
        pcall(function()
            local now = os.clock()
            if Config.AutoPray and now - (Sum.pray or 0) > 1 then
                Sum.pray = now
                task.spawn(function() invoke("gravestoneEvent", 1) end)
            end
            if Config.AutoTryLuck and now - (Sum.luck or 0) > 1 then
                Sum.luck = now
                task.spawn(function() invoke("gravestoneEvent", 2) end)
            end
            if Config.RandomBones and now - Sum.bones > 2 and invCount("Bones") >= 50 then
                Sum.bones = now
                task.spawn(function()
                    local ok, r
                    for _ = 1, 10 do -- 10 giros por rodada
                        ok, r = invoke("Bones", "Buy", 1, 1)
                        if not ok then break end
                        task.wait(0.15)
                    end
                    Diag.bones = "Random Bones (10x): " .. (ok and "" or "error ") .. tostring(r)
                end)
            end
        end)
    end
end)

