    PC.src["fish"] = function() return [===[
local __E = ...
local AFL = __E.AFL
local Config, Connections, Diag, Fluent, Player, State, Tabs = __E.Config, __E.Connections, __E.Diag, __E.Fluent, __E.Player, __E.State, __E.Tabs
local flyTo, getChar, invoke, persist = __E.flyTo, __E.getChar, __E.invoke, __E.persist
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")
local Alive = true
AFL.onUnload(function() Alive = false end);
-- ============ Auto Fishing (portado do bomba.lua / Axl Hub, com ideias do Banana Hub) ============
-- Remotes (conferidos nos dumps do jogo):
--   ReplicatedStorage.FishReplicated.FishingRequest            RemoteFunction  ("StartCasting", "CastLineAtLocation", "Catching", "Catch")
--   ReplicatedStorage.Modules.Net["RF/JobsRemoteFunction"]    ("FishingNPC", "Angler", "AskQuest" / "CheckQuest" / "Speak") e ("FishingNPC", "SellFish")
--   ReplicatedStorage.Modules.Net["RF/JobToolAbilities"]      ("Z", true)  -> habilidade da vara
--   ReplicatedStorage.Modules.Net["RF/Craft"]                 ("Craft", isca, 1, {})
--   Remotes.CommF_  ("LoadItem", isca, {"Usables"}), ("getInventory")
-- A parte que mexe no personagem (vara na mao, posicao salva, lancar/pegar) roda pelo arbitro (Auto Fishing) para nao brigar
-- com os farms; o resto (isca, quest, vender, Fish Slap) e rotina de fundo que so usa remotes.
local RS = ReplicatedStorage
local Fish = { status = "Off", caught = 0, sold = 0, busy = false, busyAt = 0, castAt = 0, at = {}, stateAt = 0, lastState = nil, warnAt = {} }
AFL.Fish = Fish

local BAITS = { "Basic Bait", "Kelp Bait", "Good Bait", "Abyssal Bait", "Frozen Bait", "Epic Bait", "Carnivore Bait" }
local function d(k, v) if Config[k] == nil then Config[k] = v end end
d("FishBait", "Basic Bait")

-- ------------------------------------------------------------------ helpers ----
local function say(txt) Fish.status = txt; Diag.fish = txt end
local function notify(txt, secs)
    pcall(function() Fluent:Notify({ Title = "Moon Hub - Fishing", Content = txt, Duration = secs or 4 }) end)
end
local function warnEvery(key, secs, txt)
    if os.clock() - (Fish.warnAt[key] or 0) >= secs then Fish.warnAt[key] = os.clock(); notify(txt, 4) end
end
local function net(name)
    local m = RS:FindFirstChild("Modules")
    local n = m and m:FindFirstChild("Net")
    return n and n:FindFirstChild(name)
end
local function request()
    local f = RS:FindFirstChild("FishReplicated")
    return f and f:FindFirstChild("FishingRequest")
end
-- InvokeServer com limite de tempo (um remote sem resposta nao trava nada)
local function call(rf, ...)
    if not rf then return false, "remote not found" end
    local args = table.pack(...)
    local done, ok, res = false, false, nil
    task.spawn(function()
        ok, res = pcall(function() return rf:InvokeServer(table.unpack(args, 1, args.n)) end)
        done = true
    end)
    local t0 = os.clock()
    while not done and os.clock() - t0 < 6 do task.wait(0.05) end
    if not done then return false, "no response (6s)" end
    return ok, res
end
local function jobs(...) return call(net("RF/JobsRemoteFunction"), ...) end

local function isRod(t)
    if not (t and t:IsA("Tool")) then return false end
    if string.find(t.Name, "Rod", 1, true) then return true end
    return t:FindFirstChild("FishingRodData") ~= nil
end
local function findRod()
    local char = Player.Character
    if char then
        for _, t in ipairs(char:GetChildren()) do if isRod(t) then return t, true end end
    end
    local bp = Player:FindFirstChild("Backpack")
    if bp then
        for _, t in ipairs(bp:GetChildren()) do if isRod(t) then return t, false end end
    end
end

-- config do jogo (distancia maxima do arremesso) e altura da agua; tudo opcional
local Mods = { tried = 0 }
local function loadMods()
    if Mods.ok or os.clock() - Mods.tried < 5 then return Mods.ok end
    Mods.tried = os.clock()
    pcall(function()
        local fr = RS:FindFirstChild("FishReplicated")
        local cm = fr and fr:FindFirstChild("FishingClient") and fr.FishingClient:FindFirstChild("Config")
        if cm then Mods.cfg = require(cm) end
        local util = RS:FindFirstChild("Util")
        local wm = util and util:FindFirstChild("GetWaterHeightAtLocation")
        if wm then Mods.water = require(wm) end
        local bd = fr and fr:FindFirstChild("BaitData")
        if bd then
            local bm = require(bd)
            local list = {}
            for name in pairs(bm.Types or {}) do list[#list + 1] = name end
            table.sort(list)
            if #list > 0 then Mods.baits = list end
        end
    end)
    Mods.ok = Mods.cfg ~= nil
    return Mods.ok
end

-- ponto onde a linha cai: raio a frente do personagem (ate a distancia maxima da vara), na altura da agua
local function castTarget(char, hrp, rod)
    loadMods()
    local maxDist = tonumber(rod:GetAttribute("MaxLaunchDistance")) or (Mods.cfg and Mods.cfg.Rod and tonumber(Mods.cfg.Rod.MaxLaunchDistance)) or 100
    local water = 0
    if Mods.water then
        local ok, h = pcall(Mods.water, hrp.Position)
        if ok and tonumber(h) then water = h end
    end
    local head = char:FindFirstChild("Head")
    local origin = head and head.Position or hrp.Position
    local dir = hrp.CFrame.LookVector * maxDist
    local ignore = { char }
    for _, n in ipairs({ "Characters", "Enemies" }) do
        local f = workspace:FindFirstChild(n)
        if f then ignore[#ignore + 1] = f end
    end
    local hit = origin + dir
    pcall(function()
        local rp = RaycastParams.new()
        rp.FilterType = Enum.RaycastFilterType.Exclude
        rp.FilterDescendantsInstances = ignore
        local r = workspace:Raycast(origin, dir, rp)
        if r and r.Position then hit = r.Position end
    end)
    return Vector3.new(hit.X, math.max(hit.Y, water), hit.Z)
end

-- -------------------------------------------------------------------- isca ----
local invAt, invCache = -1e9, nil
local function inventory()
    if os.clock() - invAt > 4 then
        invAt = os.clock()
        local ok, inv = invoke("getInventory")
        if ok and type(inv) == "table" then invCache = inv end
    end
    return invCache
end
local function baitOwned(name)
    local inv = inventory()
    if not inv then return nil end
    local n = 0
    for _, it in pairs(inv) do
        if type(it) == "table" and it.Name then
            local nm = tostring(it.Name)
            if string.find(nm, "-", 1, true) then nm = string.split(nm, "-")[1] end
            if nm == name then n += tonumber(it.Count or it.Amount) or 1 end
        end
    end
    return n
end
local function fishOwned()
    local inv = inventory()
    if not inv then return 0 end
    local n = 0
    for _, it in pairs(inv) do
        if type(it) == "table" and it.Type == "Fish" then n += tonumber(it.Count or it.Amount) or 1 end
    end
    return n
end
local function selectedBait()
    local ok, v = pcall(function() return Player.Data.FishingData:GetAttribute("SelectedBait") end)
    if ok and type(v) == "string" and v ~= "" then return v end
    local ok2, t = pcall(function() return Player.PlayerGui.Main.BottomHUDList.CurrentBait.Text end)
    if ok2 and type(t) == "string" then return string.match(t, "Selected Bait: (.-) x%d+") end
end
-- coloca a isca escolhida na vara (no maximo a cada 5s)
local function ensureBait()
    local want = Config.FishBait
    if type(want) ~= "string" or want == "" then return end
    if selectedBait() == want then return end
    local n = baitOwned(want)
    if n ~= nil and n <= 0 then warnEvery("nobait", 6, "You don't have " .. want .. " to use"); return end
    if os.clock() - (Fish.at.load or 0) < 5 then return end
    Fish.at.load = os.clock()
    task.spawn(function() invoke("LoadItem", want, { "Usables" }) end)
end

-- --------------------------------------------------------- rotina de fundo (so remotes) ----
local function questActive()
    local pg = Player:FindFirstChild("PlayerGui")
    local q = pg and (pg:FindFirstChild("Quest") or pg:FindFirstChild("QuestGui"))
    return q ~= nil and q:FindFirstChild("Container") ~= nil and q.Container:FindFirstChild("QuestTitle") ~= nil
end
task.spawn(function()
    while Alive do
        task.wait(0.5)
        pcall(function()
            local now = os.clock()
            if Config.FishBuyBait and now - (Fish.at.craft or 0) > 2 then
                Fish.at.craft = now
                task.spawn(function() call(net("RF/Craft"), "Craft", Config.FishBait, 1, {}) end)
            end
            if Config.FishQuest and now - (Fish.at.ask or 0) > 1 and not questActive() then
                Fish.at.ask = now
                task.spawn(function() jobs("FishingNPC", "Angler", "AskQuest") end)
            end
            if Config.FishQuestDone and now - (Fish.at.done or 0) > 5 then
                Fish.at.done = now
                task.spawn(function()
                    local had = questActive()
                    local ok, r = jobs("FishingNPC", "Angler", "CheckQuest")
                    if ok and r ~= false and had then
                        task.wait(0.5)
                        if not questActive() then notify("Fishing quest completed!", 5) end
                    end
                end)
            end
            if Config.FishSell and now - (Fish.at.sell or 0) > 5 then
                Fish.at.sell = now
                task.spawn(function()
                    invAt = -1e9
                    local before = fishOwned()
                    jobs("FishingNPC", "SellFish")
                    task.wait(0.8)
                    invAt = -1e9
                    local gone = before - fishOwned()
                    if gone > 0 then Fish.sold += gone end
                end)
            end
            -- habilidade da vara com ela na mao (mesmo sem o Auto Fishing)
            if Config.FishSkill and not Config.FishOn and now - (Fish.at.skill or 0) > 0.5 then
                local rod, eq = findRod()
                if rod and eq then
                    Fish.at.skill = now
                    task.spawn(function() call(net("RF/JobToolAbilities"), "Z", true) end)
                end
            end
        end)
    end
end)

-- Fish Slap: acerta o botao quando o ponteiro passa pela zona verde
table.insert(Connections, RunService.RenderStepped:Connect(function()
    if not Config.FishSlap then return end
    pcall(function()
        local pg = Player:FindFirstChildOfClass("PlayerGui")
        local g = pg and pg:FindFirstChild("FishSlapMinigame")
        if not g then return end
        local bar = g:FindFirstChild("Bar")
        local zone, tick_, btn = bar and bar:FindFirstChild("GreenZone"), bar and bar:FindFirstChild("Tick"), g:FindFirstChild("SlapButton")
        if zone and tick_ and btn then
            local p, s, zp, zs = tick_.AbsolutePosition, tick_.AbsoluteSize, zone.AbsolutePosition, zone.AbsoluteSize
            if p.X < zp.X + zs.X and zp.X < p.X + s.X and p.Y < zp.Y + zs.Y and zp.Y < p.Y + s.Y then
                firesignal(btn.Activated)
            end
        end
        local cs = pg:FindFirstChild("ContinueScreen")
        local cont = cs and cs:FindFirstChild("Continue")
        if cont and cont.Visible then firesignal(cont.Activated) end
    end)
end))

-- -------------------------------------------------------------- posicao e vortex ----
local function savedGoal()
    local p = Config.FishPos
    if type(p) ~= "table" or not tonumber(p.x) then return nil end
    local pos = Vector3.new(p.x, p.y, p.z)
    return CFrame.new(pos, pos + Vector3.new(tonumber(p.lx) or 0, 0, tonumber(p.lz) or -1))
end
function Fish.savePosition()
    local _, hrp = getChar()
    if not hrp then return false end
    local look = hrp.CFrame.LookVector
    Config.FishPos = { x = hrp.Position.X, y = hrp.Position.Y, z = hrp.Position.Z, lx = look.X, lz = look.Z }
    persist()
    return true
end

-- Golden Vortex (evento de pesca): fica numa superficie firme perto dele, olhando para ele
local Vortex = { part = nil, stand = nil, scanning = false }
local function findVortex()
    local f = workspace:FindFirstChild("ActiveFishingSpots")
    local best, bd = nil, math.huge
    local _, hrp = getChar()
    if f and hrp then
        for _, v in ipairs(f:GetChildren()) do
            if v.Name == "GoldenVortex" then
                local pos = v:IsA("BasePart") and v.Position or (v.PrimaryPart and v.PrimaryPart.Position)
                if pos then
                    local dist = (hrp.Position - pos).Magnitude
                    if dist < bd then best, bd = v, dist end
                end
            end
        end
    end
    return best
end
local function vortexPos(v) return v:IsA("BasePart") and v.Position or (v.PrimaryPart and v.PrimaryPart.Position) end
-- procura (aos poucos, sem travar o jogo) o chao firme mais perto do vortex
local function scanStand(v)
    if Vortex.scanning then return end
    Vortex.scanning = true
    task.spawn(function()
        local vp = vortexPos(v)
        local map = workspace:FindFirstChild("Map")
        local best, bd = nil, math.huge
        if vp and map then
            local n = 0
            for _, p in ipairs(map:GetDescendants()) do
                n += 1
                if n % 400 == 0 then task.wait() end
                if p:IsA("BasePart") and p.CanCollide and p.Size.X > 4 and p.Size.Z > 4 then
                    local top = p.Position.Y + p.Size.Y / 2
                    local dist = (p.Position - vp).Magnitude
                    if top > vp.Y + 1 and dist < bd and dist < 400 then best, bd = Vector3.new(p.Position.X, top + 3, p.Position.Z), dist end
                end
            end
        end
        Vortex.part, Vortex.stand, Vortex.scanning = v, best, false
    end)
end

-- ------------------------------------------------------------------ o passo ----
-- chamado pelo arbitro (a cada ~0.12s) enquanto o Auto Fishing estiver ligado. Devolve true quando ocupa o personagem.
function Fish.step()
    local char, hrp, hum = getChar()
    if not char then say("Waiting for your character"); return false end
    local now = os.clock()
    State.Mode, State.Text = "Auto Fishing", Fish.status

    -- 1) onde ficar: vortex do evento ou posicao salva
    local goal, why
    if Config.FishVortex then
        local v = findVortex()
        if v then
            if Vortex.part ~= v and not Vortex.scanning then scanStand(v) end
            if Vortex.part == v and Vortex.stand then goal, why = CFrame.new(Vortex.stand), "Golden Vortex" end
            if not goal then say("Golden Vortex found: looking for solid ground nearby"); return true end
        end
    end
    if not goal and Config.FishStay then
        goal, why = savedGoal(), "your saved spot"
    end
    if goal then
        local face = Vector3.new(goal.LookVector.X, 0, goal.LookVector.Z)
        if why == "Golden Vortex" then
            local v = Vortex.part
            local vp = v and vortexPos(v)
            if vp then face = Vector3.new(vp.X - goal.X, 0, vp.Z - goal.Z) end
        end
        if (hrp.Position - goal.Position).Magnitude > 8 then
            say("Going to " .. why)
            State.Text = Fish.status
            flyTo(goal)
            return true
        end
        if face.Magnitude > 0.1 and hrp.CFrame.LookVector:Dot(face.Unit) < 0.98 then
            hrp.CFrame = CFrame.new(hrp.Position, hrp.Position + face.Unit)
        end
    end

    -- 2) vara na mao
    local rod, equipped = findRod()
    if not rod then
        say("No fishing rod in your backpack")
        warnEvery("norod", 8, "You don't have any fishing rod in your backpack")
        return false
    end
    if not equipped then
        say("Equipping the rod")
        hum:EquipTool(rod)
        return true
    end

    -- 3) trabalhos que usam a mao (bau afundado) e isca
    if Fish.busy and now - Fish.busyAt > 12 then Fish.busy = false end
    if Fish.busy then return true end
    if Config.FishChest and now - (Fish.at.chest or 0) > 1.5 then
        local bp = Player:FindFirstChild("Backpack")
        local chest = bp and bp:FindFirstChild("Sunken Chest")
        if chest then
            Fish.at.chest = now
            Fish.busy, Fish.busyAt = true, now
            say("Opening a Sunken Chest")
            task.spawn(function()
                pcall(function()
                    hum:EquipTool(chest)
                    task.wait(0.5)
                    local re = chest:FindFirstChild("RemoteEvent")
                    if re then
                        re:FireServer("Visual")
                        task.wait(0.3)
                        re:FireServer("Open")
                    end
                end)
                Fish.busy = false
            end)
            return true
        end
    end
    ensureBait()

    -- 4) maquina de estados da vara
    local state, server = rod:GetAttribute("State"), rod:GetAttribute("ServerState")
    local cur = tostring(server or state)
    if cur ~= Fish.lastState then Fish.lastState, Fish.stateAt = cur, now end
    if Config.FishSkill and now - (Fish.at.skill or 0) > 0.5 then
        local charge = rod:GetAttribute("SkillChargeAlpha")
        if charge == nil or tonumber(charge) >= 1 then
            Fish.at.skill = now
            task.spawn(function() call(net("RF/JobToolAbilities"), "Z", true) end)
        end
    end
    if server == "Biting" then
        Fish.busy, Fish.busyAt = true, now
        say("Fish biting: catching it")
        task.spawn(function()
            local rf = request()
            if rf then
                pcall(function()
                    rf:InvokeServer("Catching", true)
                    task.wait(0.1)
                    local ok, r = pcall(function() return rf:InvokeServer("Catch", 1, 1, 1) end)
                    task.wait(0.1)
                    pcall(function() rf:InvokeServer("Catching", false) end)
                    if ok and r ~= false then Fish.caught += 1 end
                    local w = 0
                    while w < 3 and Alive and rod.Parent and rod:GetAttribute("ServerState") == "Biting" do task.wait(0.1); w += 0.1 end
                end)
            end
            Fish.castAt = os.clock() - 1.5
            Fish.busy = false
        end)
    elseif (state == "ReeledIn" or server == "ReeledIn") and now - Fish.castAt > 2.5 then
        Fish.castAt = now
        Fish.busy, Fish.busyAt = true, now
        say("Casting the line")
        task.spawn(function()
            local rf = request()
            if rf then
                pcall(function()
                    local target = castTarget(char, hrp, rod)
                    rf:InvokeServer("StartCasting")
                    task.wait()
                    rf:InvokeServer("CastLineAtLocation", target, 100, true)
                end)
            end
            Fish.busy = false
        end)
    else
        say("Waiting for a fish (" .. cur .. ")")
        -- vara travada no mesmo estado por muito tempo: guarda e pega de novo
        if now - Fish.stateAt > 25 then
            Fish.stateAt = now
            pcall(function() hum:UnequipTools() end)
        end
    end
    State.Text = Fish.status
    return true
end

