        pcall(function() Player:WaitForChild("PlayerGui"):SetAttribute("FishIndexVisible", true) end)
    end })
    task.spawn(function()
        while Alive do
            task.wait(1.5)
            pcall(function()
                info:SetDesc(string.format("%s\nCaught: %d | Sold: %d", Fish.status, Fish.caught, Fish.sold))
            end)
        end
    end)
end



