    PC.src["halloween"] = function() return [===[
local __E = ...
local AFL = __E.AFL
local Aim, Config, Core, Diag, Fluent, Player, State, Tabs = __E.Aim, __E.Config, __E.Core, __E.Diag, __E.Fluent, __E.Player, __E.State, __E.Tabs
local aliveParts, equipWeapon, fightEnemy, flyTo, getChar, persist = __E.aliveParts, __E.equipWeapon, __E.fightEnemy, __E.flyTo, __E.getChar, __E.persist
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Alive = true
AFL.onUnload(function() Alive = false end);
-- ============ HALLOWEEN 2026 (Sea 1) ============
-- guarda as frutas que o Gacha do evento da (independente do Auto Store da aba Fruits): no maximo 2 tentativas por fruta
do
    local StoreT = setmetatable({}, { __mode = "k" })
    task.spawn(function()
        while Alive do
            task.wait(2)
            if Config.HalStore and Config.HalGacha and (Config.PayHoldUntil or 0) < os.clock() then
                pcall(function()
                    for _, c in ipairs({ Player.Backpack, Player.Character }) do
                        for _, t in ipairs(c and c:GetChildren() or {}) do
                            if t:IsA("Tool") and string.find(t.Name, "Fruit") and (StoreT[t] or 0) < 2 then
                                StoreT[t] = (StoreT[t] or 0) + 1
                                __E.invoke("StoreFruit", t:GetAttribute("OriginalName") or t.Name, t)
                                task.wait(0.3)
                            end
                        end
                    end
                end)
            end
        end
    end)
end
-- Break Pumpkins: as aboboras ficam em workspace.PumpkinHunt (um Model por abobora). O codigo do jogo (HalloweenLocal.PumpkinHunt) diz:
--   * atributos do Model: PumpkinState ("Idle" -> "Shaking" -> "Burst"/"Awakening"; a rara usa "Summoning"), PumpkinHits (0..3),
--     PumpkinRare, PumpkinCrackedBy (UserId de quem quebrou); HITS_TO_BREAK = 3
--   * o golpe sai pelo combate normal: RE/RegisterAttack:FireServer() e RE/RegisterHit:FireServer(<parte da abobora>)
--     (formas conferidas no dump pos-update: 5980x FireServer() e 143x FireServer(MeshPart de PumpkinHunt.Pumpkin.pumpkinv2))
-- Hop: sem abobora no servidor depois de rodar o mapa, troca de servidor (mesmo AFL.hopRequest dos outros farms).
local function d(k, v) if Config[k] == nil then Config[k] = v end end
d("PumpOn", false); d("PumpHop", false); d("PumpRare", true); d("PumpTool", "Melee"); d("PumpSkills", { Z = true, X = true, C = true, V = true }); d("GhostTools", { Melee = true, ["Blox Fruit"] = true }); d("GhostSkills", { Z = true, X = true }); d("HalGacha", false); d("HalStore", true); d("HalEvent", false); d("HalBoss", false); d("HalGreat", false)

local P = { n = 0, cur = nil, since = 0, hitsSeen = 0, hitsAt = 0, bl = setmetatable({}, { __mode = "k" }), tour = nil, tourI = 1, tourAt = 0,
    dwell = nil, restUntil = 0, noneSince = nil, status = "Off", lastShot = 0 }
AFL.Pump = P

local function say(t) P.status = t; Diag.pump = t end
local function net(name)
    local m = ReplicatedStorage:FindFirstChild("Modules")
    local n = m and m:FindFirstChild("Net")
    return n and n:FindFirstChild(name)
end
local function pumpFolder() return workspace:FindFirstChild("PumpkinHunt") end
local function partOf(m)
    if not m then return nil end
    if m:IsA("BasePart") then return m end
    if m:IsA("Model") and m.PrimaryPart then return m.PrimaryPart end
    local best
    for _, x in ipairs(m:GetDescendants()) do
        if x:IsA("MeshPart") then return x end
        if x:IsA("BasePart") and not best then best = x end
    end
    return best
end
-- aboboras que ainda podem ser quebradas (Idle ou sem estado ainda)
function P.list()
    local out = {}
    local f = pumpFolder()
    if not f then return out end
    for _, m in ipairs(f:GetChildren()) do
        if m:IsA("Model") and m.Parent then
            local st = m:GetAttribute("PumpkinState")
            local rare = m:GetAttribute("PumpkinRare") == true
            if (st == nil or st == "Idle") and (Config.PumpRare ~= false or not rare) and (P.bl[m] or 0) < os.clock() then
                local p = partOf(m)
                local py = p and p.Position.Y
                if p and py > -150 and py < 3500 then out[#out + 1] = { m = m, p = p } end
            end
        end
    end
    return out
end
local function shoot(part, tip, stuck)
    -- 1 golpe por chamada: o do proprio jogo (CombatFramework) + os remotes de registro com os argumentos reais
    Aim.part = part
    tip = tip or "Melee"
    pcall(function()
        if tip == "Gun" then
            -- Gun: so o Activate abaixo
        elseif tip == "Blox Fruit" then
            if Core and Core.fruitTick then Core.fruitTick() end
        elseif Core and Core.meleeSwordClick then Core.meleeSwordClick(tip) end
        local c = Player.Character
        local t = c and c:FindFirstChildOfClass("Tool")
        if t then t:Activate() end
    end)
    -- estilos de luta (Dark Step etc.): alem do M1, solta as skills Z/X/C/V do Soco em rodizio
    if stuck and Core and Core.pressKey and os.clock() - (P.hitsAt or 0) > 4 and os.clock() - (P.skillAt or 0) > 1.2 then
        local sel = type(Config.PumpSkills) == "table" and Config.PumpSkills or {}
        local keys = {}
        for _, kn in ipairs({ "Z", "X", "C", "V", "F" }) do if sel[kn] then keys[#keys + 1] = kn end end
        if #keys > 0 then
            P.skillAt = os.clock()
            P.skillI = (P.skillI or 0) % #keys + 1
            local k = Enum.KeyCode[keys[P.skillI]]
            task.spawn(function() Core.pressKey(k) end)
        end
    end
    -- v145: "clique de fruta ainda mais rapido": rajada de ~0,35 s com 1 golpe por FRAME (o passo normal roda a cada 0,12 s = ~8 golpes/s)
    if (tip == "Blox Fruit" or tip == "Melee" or tip == "Sword") and not P.bursting then
        P.bursting = true
        task.spawn(function()
            local t0 = os.clock()
            while (Config.PumpOn or Config.PumpHop) and part.Parent and Aim.part == part and os.clock() - t0 < 30 do   -- v78: sem limite de duracao da rajada   -- v77: rajada continua (1 golpe por frame, sem pausa entre rajadas)
                for _ = 1, 2 do
                    pcall(function()
                        if tip == "Blox Fruit" then
                            if Core and Core.fruitTick then Core.fruitTick() end
                        elseif Core and Core.meleeSwordClick then
                            Core.meleeSwordClick(tip)
                            -- v78: o motor limita o golpe do jogo (cfAttack) a 1 a cada 0,2 s; aqui chama direto, em todo frame
                            if Core.cfAttack then Core.cfAttack() end
                        end
                    end)
                end
                task.wait()
            end
            P.bursting = false
        end)
    end
    local now = os.clock()
    -- v145: relato de muitos Kicks no Break Pumpkins: o RegisterAttack/RegisterHit "crus" (sem os argumentos de validacao do jogo) eram
    -- disparados 8x por segundo o tempo todo. Agora so como reforco (sem dano ha 1,5 s) e no maximo 3x por segundo.
    if now - P.lastShot >= 0.05 then   -- v78: sem limite (a cada passo)
        P.lastShot = now
        pcall(function()
            local ra, rh = net("RE/RegisterAttack"), net("RE/RegisterHit")
            if ra then ra:FireServer() end
            if rh then rh:FireServer(part) end
        end)
    end
end

-- Quando uma abobora "acorda" (PumpkinState = "Awakening") o jogo cria o NPC "Jack o' Lantern" (PumpkinHunt.JACK_NAME) em workspace.Enemies;
-- a abobora rara vira "Pumpkin Snowman". O jogador precisa mata-los, entao isso tem prioridade sobre quebrar a proxima abobora.
P.foeBl = setmetatable({}, { __mode = "k" })
local FOES = { "Jack o' Lantern", "Pumpkin Snowman" }
local function findFoe(hrp)
    local en = workspace:FindFirstChild("Enemies")
    if not en then return nil end
    local best, bd
    for _, e in ipairs(en:GetChildren()) do
        local hit = false
        for _, n in ipairs(FOES) do if string.find(e.Name, n, 1, true) then hit = true break end end
        if hit and (P.foeBl[e] or 0) < os.clock() then
            local hum, root = aliveParts(e)
            if hum and root then
                local dist = (root.Position - hrp.Position).Magnitude
                -- so os NPCs da abobora que NOS quebramos (perto dela, ate 90 s depois) ou o que ja estamos matando:
                -- os NPCs que outros jogadores acordam nao levam dano nosso (o script ficava grudado neles batendo em nada)
                local mine = P.foe == e
                local lb = P.lastBroken
                if not mine and lb and os.clock() - lb.t < 90 and (root.Position - lb.pos).Magnitude < 90 then mine = true end
                if mine and dist < 400 and (not bd or dist < bd) then best, bd = e, dist end
            end
        end
    end
    return best
end

function P.step()
    local char, hrp = getChar()
    if not (char and hrp) then return false end
    -- Auto Halloween Event / Boss tem prioridade: enquanto ele tem o que fazer, as aboboras esperam
    local he = AFL.HalEvent
    if he and he.wants and he.wants() then return false end
    local hop = Config.PumpHop and true or false
    local foe = findFoe(hrp)
    if foe then
        if P.foe ~= foe then P.foe, P.foeAt, P.foeHp = foe, os.clock(), nil end
        do
            local fh = foe:FindFirstChildOfClass("Humanoid")
            local hp = fh and fh.Health
            if hp and (not P.foeHp or hp < P.foeHp - 1) then P.foeAt = os.clock() end   -- esta perdendo vida: continua
            if hp then P.foeHp = hp end
        end
        if os.clock() - P.foeAt > 10 then
            P.foeBl[foe] = os.clock() + 300; P.foe = nil      -- 10 s sem perder vida: nao e nosso / nao leva dano, deixa pra la
            local hh = AFL.HalEvent; if hh and hh.log then hh.log("pumpkin: foe " .. foe.Name .. " is not taking damage, skipping it") end
        else
            State.Mode = "Break Pumpkins"
            if P.foe ~= P.loggedFoe then P.loggedFoe = P.foe; local hh = AFL.HalEvent; if hh and hh.log then hh.log("pumpkin: killing " .. foe.Name) end end
            say("Killing " .. foe.Name .. " (" .. P.n .. " pumpkins broken)")
            State.Text = P.status
            P.noneSince = nil
            local hh = AFL.HalEvent
            if hh and hh.pinOn and hh.pinOn(hrp, foe) then return true end
            fightEnemy(foe, { foe.Name }, false)
            return true
        end
    end
    if P.cur then
        local m = P.cur.m
        local st = m.Parent and m:GetAttribute("PumpkinState")
        -- o estado muda assim que a abobora leva o primeiro golpe: so conta como quebrada se sumiu, ou se o estado ficou fora de "Idle" e os golpes pararam
        local gone = not m.Parent
        -- v56: a abobora sumiu ENQUANTO ele ainda voava ate ela (streaming tirou o modelo, ou outro jogador quebrou): antes contava
        -- como "quebrada" e trocava de alvo, voando de abobora em abobora sobre o mar sem nunca chegar. Agora continua indo ate a
        -- ultima posicao conhecida (o voo ja pede o mapa em volta) e so desiste ao chegar ou depois de 45 s.
        if not gone and P.cur.p and P.cur.p.Parent then P.cur.pos = P.cur.p.Position end
        if gone and P.cur.pos and (P.cur.pos - hrp.Position).Magnitude > 120 and os.clock() - P.since < 45 then
            State.Mode = "Break Pumpkins"
            say(string.format("Going to the pumpkin area (%d broken)", P.n))
            State.Text = P.status
            if not P.streaming then P.streaming = true; local sp = P.cur.pos; task.spawn(function() pcall(function() Player:RequestStreamAroundAsync(sp, 2) end); P.streaming = false end) end
            local nl = P.list()
            local back
            for _, it in ipairs(nl) do
                if (it.p.Position - P.cur.pos).Magnitude < 150 then back = it; break end
            end
            if back then
                P.cur = back; P.cur.pos = back.p.Position; P.since = os.clock()
            else
                flyTo(CFrame.new(P.cur.pos + Vector3.new(0, 4, 0)))
                return true
            end
            m = P.cur.m
            gone = not m.Parent
            st = m.Parent and m:GetAttribute("PumpkinState")
        end
        local nonIdle = st ~= nil and st ~= "Idle"
        if nonIdle then
            P.stateAt = P.stateAt or os.clock()
            local hNow = tonumber(m:GetAttribute("PumpkinHits")) or 0
            if hNow ~= P.stateHits then P.stateHits, P.stateHitAt = hNow, os.clock() end
        else
            P.stateAt, P.stateHits, P.stateHitAt = nil, nil, nil
        end
        local settled = nonIdle and ((os.clock() - P.stateAt > 1.3 and os.clock() - (P.stateHitAt or P.stateAt) > 0.7)   -- v75: voltou ao ritmo seguro
            or (tonumber(m:GetAttribute("PumpkinHits")) or 0) >= 3)       -- 3 golpes confirmados pelo jogo = quebrada
        if gone or settled then
            pcall(function() P.lastBroken = { pos = P.cur.pos or P.cur.p.Position, t = os.clock() } end)
            if not gone or not P.cur.pos or (P.cur.pos - hrp.Position).Magnitude < 200 then P.n += 1 end
            P.cur = nil; P.noneSince = nil; P.stateAt, P.stateHits, P.stateHitAt = nil, nil, nil
        elseif false then
            P.n += 1; P.cur = nil; P.noneSince = nil; P.stateAt, P.stateHits, P.stateHitAt = nil, nil, nil
        elseif os.clock() - P.since > 30 then
            P.bl[m] = os.clock() + 120; P.cur = nil
        else
            local h = tonumber(m:GetAttribute("PumpkinHits")) or 0
            if h ~= P.hitsSeen then P.hitsSeen, P.hitsAt = h, os.clock(); if P.tipNow then P.tipGood = P.tipNow end
            elseif os.clock() - P.hitsAt > 12 then P.bl[m] = os.clock() + 90; P.cur = nil; local hh = AFL.HalEvent; if hh and hh.log then hh.log("pumpkin: not taking damage, skipping it") end end    -- nao esta levando dano: deixa pra la
        end
    end
    if not P.cur then
        local best, bd = nil, math.huge
        for _, it in ipairs(P.list()) do
            local dist = (it.p.Position - hrp.Position).Magnitude
            if dist < bd then best, bd = it, dist end
        end
        if best then
            P.cur, P.since, P.hitsSeen, P.hitsAt, P.noneSince, P.tour, P.dwell = best, os.clock(), tonumber(best.m:GetAttribute("PumpkinHits")) or 0, os.clock(), nil, nil, nil
        else
            -- nenhuma abobora carregada: visita as ilhas (elas so aparecem perto) e, no fim, troca de servidor (se Hop estiver ligado)
            if os.clock() >= P.restUntil then
                if not P.tour then P.tour, P.tourI, P.tourAt, P.dwell = AFL.chestTourBuild(hrp.Position), 1, os.clock(), nil end
                local tgt = P.tour[P.tourI]
                if tgt then
                    P.noneSince = nil
                    State.Mode = "Break Pumpkins"
                    say(string.format("Searching pumpkins: island %d/%d (%d broken)", P.tourI, #P.tour, P.n))
                    State.Text = P.status
                    local goal = tgt + Vector3.new(0, 90, 0)
                    if (hrp.Position - goal).Magnitude > 60 and os.clock() - P.tourAt < 40 then flyTo(CFrame.new(goal)); return true end
                    P.dwell = P.dwell or (os.clock() + 1.5)
                    if os.clock() < P.dwell then return true end
                    P.tourI, P.tourAt, P.dwell = P.tourI + 1, os.clock(), nil
                    return true
                end
                P.tour, P.restUntil = nil, os.clock() + (hop and 4 or 30)
            end
            P.noneSince = P.noneSince or os.clock()
            State.Mode = "Break Pumpkins"
            say("No pumpkins left here (" .. P.n .. " broken)")
            State.Text = P.status
            if hop and os.clock() - P.noneSince > 3 then
                AFL.hopRequest("no pumpkins left", function() return #P.list() > 0 or not Config.PumpHop end, 20)   -- 20 s de contagem: da tempo de desligar
            end
            return false
        end
    end
    local part = P.cur.p
    -- NPC colado na abobora: o golpe do jogo bate no NPC e nao na abobora. Mata os NPCs que estao perto dela primeiro.
    do
        local en = workspace:FindFirstChild("Enemies")
        local near, nd
        for _, e in ipairs(en and en:GetChildren() or {}) do
            if (P.foeBl[e] or 0) < os.clock() then
                local hum, root = aliveParts(e)
                if hum and root and hum.MaxHealth <= 150000 then
                    local d = math.min((root.Position - part.Position).Magnitude, (root.Position - hrp.Position).Magnitude)
                    if d < 38 and (not nd or d < nd) then near, nd = e, d end
                end
            end
        end
        if near then
            if P.nearFoe ~= near then P.nearFoe, P.nearAt = near, os.clock() end
            if os.clock() - P.nearAt > 10 then
                P.foeBl[near] = os.clock() + 300; P.nearFoe = nil
            else
                State.Mode = "Break Pumpkins"
                say("Clearing NPC next to the pumpkin: " .. near.Name)
                State.Text = P.status
                P.since = os.clock()          -- o tempo de limpar o NPC nao conta contra a abobora
                P.hitsAt = os.clock()
                fightEnemy(near, { near.Name }, false)
                return true
            end
        end
    end
    State.Mode = "Break Pumpkins"
    say(string.format("Breaking pumpkin (%d broken%s)", P.n, hop and ", hop on" or ""))
    State.Text = P.status
    local goal = part.Position + Vector3.new(0, 4, 0)
    if (hrp.Position - goal).Magnitude > 9 then
        flyTo(CFrame.new(goal))
        return true
    end
    -- arma: comeca pela que ja funcionou (ou Melee); sem dano em 2,5 s troca (Melee -> Sword -> Fruta) a cada 2,5 s
    -- arma e skills escolhidas pelo jogador (Halloween > Pumpkin weapon / Pumpkin skills); padrao: Melee + Z X C V
    local stuckT = os.clock() - P.hitsAt
    local tip = Config.PumpTool
    if tip ~= "Melee" and tip ~= "Sword" and tip ~= "Blox Fruit" and tip ~= "Gun" then tip = "Melee" end
    if tip ~= P.tipNow then
        P.tipNow = tip
        local hh = AFL.HalEvent; if hh and hh.log then hh.log("pumpkin: using " .. tip .. (stuckT > 2.5 and " (no damage yet)" or "")) end
    end
    pcall(function()
        Config.SeaTool, Config.SeaUntil = { tip = tip }, os.clock() + 1.5
        equipWeapon()
    end)
    -- fica grudado em cima da abobora olhando PARA BAIXO (o golpe de soco/espada sai na frente do personagem: de lado ele passava reto)
    pcall(function()
        hrp.CFrame = CFrame.new(part.Position + Vector3.new(0, 4, 0)) * CFrame.Angles(math.rad(-90), 0, 0)
        hrp.AssemblyLinearVelocity = Vector3.zero
    end)
    shoot(part, tip, true)
    -- v81: removido o clique de MOUSE de verdade (VirtualUser / mouse1click / VirtualInputManager no centro da tela): ele caia em cima da
    -- janela do hub e ligava/desligava funcoes sozinho. O dano vem do golpe do jogo + remotes de registro, que nao usam o mouse.
    return true
end

-- ============ Auto Roll Gacha Event (Spooky Halloween Gacha, Zioles) ============
-- Confirmado no codigo do jogo (GachaClient): consulta = GachaNetworkRF:InvokeServer({Context="Check", BoxName=...}) e giro =
-- GachaNetworkRF:InvokeServer({Context="Purchase", BoxName=...}) (o Random Fruit do hub ja gira assim, de longe, com "ZiolesGacha").
-- O Check devolve Cooldown.RequirementMet / Cooldown.RollTotal / Cooldown.RollCount e Price.RequirementMet (500 Candy Corn);
-- o hub so gira quando os dois estao OK (ate 2 giros por hora). O giro nao mexe no personagem, entao roda em segundo plano.
local G = { box = "Halloween26Gacha", status = "Off", rolls = 0, nextAt = 0, last = "" }
AFL.HalGacha = G
local function gcallMulti(tbl)
    local rf = net("RF/GachaNetworkRF")
    if not rf then return false, "remote not found" end
    local done, res = false, nil
    task.spawn(function()
        res = table.pack(pcall(function() return rf:InvokeServer(tbl) end))
        done = true
    end)
    local t0 = os.clock()
    while not done and os.clock() - t0 < 8 do task.wait(0.05) end
    if not done then return false, "no response (8s)" end
    return res[1], res[2], res[3]
end
local function gsay(t) G.status = t; Diag.halgacha = t end
function G.check()
    local ok, r = gcallMulti({ Context = "Check", BoxName = G.box })
    if ok and type(r) == "table" then return r end
    return nil, r
end
local function met(x) return type(x) == "table" and x.RequirementMet == true end
function G.cycle()
    local info, why = G.check()
    if not info then
        gsay("Check failed: " .. tostring(why))
        G.nextAt = os.clock() + 90
        return
    end
    local restricted = type(info.PaidRandomItemsRestricted) == "table" and info.PaidRandomItemsRestricted.Value == true
    local left
    if type(info.Cooldown) == "table" and info.Cooldown.RollTotal then left = info.Cooldown.RollTotal - (info.Cooldown.RollCount or 0) end
    if restricted then gsay("Paid random items are restricted on this account"); G.nextAt = os.clock() + 600; return end
    local known = type(info.Price) == "table" and type(info.Cooldown) == "table"      -- formato do Check nao reconhecido: tenta girar mesmo assim
    if known and not met(info.Price) then gsay("Not enough Candy Corn (500 needed)"); G.nextAt = os.clock() + 60; return end
    if known and not met(info.Cooldown) then
        gsay("Waiting for the next roll window" .. (left and (" (rolls left: " .. left .. ")") or ""))
        G.nextAt = os.clock() + 60
        return
    end
    local ok, a, b = gcallMulti({ Context = "Purchase", BoxName = G.box })
    if ok and a then
        G.rolls += 1
        G.last = "rolled"
        gsay(string.format("Rolled the Spooky Gacha (%d this session)", G.rolls))
        G.nextAt = os.clock() + 5      -- confere de novo: pode ter o segundo giro
    else
        local msg = type(b) == "table" and tostring(b.ErrorMessage) or tostring(a or b)
        G.last = msg
        gsay("Roll refused: " .. msg)
        G.nextAt = os.clock() + 120
    end
end
task.spawn(function()
    while Alive do
        task.wait(1)
        if Config.HalGacha and os.clock() >= G.nextAt then
            local ok, err = pcall(G.cycle)
            if not ok then gsay("error: " .. tostring(err)); G.nextAt = os.clock() + 60 end
        elseif not Config.HalGacha then
            G.status = "Off"
        end
    end
end)

-- ============ Auto Halloween Event (portas da cidade, Sea 1) ============
-- Fluxo conferido no codigo do jogo (HalloweenLocal):
--   * portas: Model "HalloweenDoor" (workspace.Map.Town.HalloweenDecor) com Proximity.ProximityPrompt ("E"); o toque chama
--     Remotes.HalloweenFunction:InvokeServer(porta). Atributos da porta: CooldownUntil (tempo do servidor), DoorOpen, EventId.
--   * o servidor responde por Remotes.HalloweenEvent: "DoorOpened"(porta, jogador, {Event, Scene, Boss}) e "EventFinished"(porta).
--   * portas "treat" (maioria, lista em TreatDoors): o servidor espera HalloweenEvent:FireServer("AcceptReward") (paga os Candy Corn)
--     e depois "TreatDialogueClosed". Cenas especiais usam um RemoteEvent proprio em ReplicatedStorage[EventId][nome] (abaixo).
--   * cenas de luta: os inimigos nascem em workspace.Enemies - o hub mata os que aparecem perto da porta.
-- Cenas especiais (Gravedigger, Sweet Ride, Magma Recipe, Don't Be Greedy, Mystery Hall, Ghost Chase, Zer0 Slap, Tarot) tem protocolo proprio (tabela SP abaixo).
local H = { status = "Off", n = 0, restUntil = 0, door = nil, doorAt = 0, info = nil, finished = false, handled = false, pressAt = 0, snap = nil,
    bl = setmetatable({}, { __mode = "k" }), cache = {}, cacheAt = 0, last = "" }
AFL.HalEvent = H
-- lista (em cache) dos textos do PlayerGui: varrer GetDescendants() a cada passo travava o jogo
H.guiSet, H.guiArr, H.guiDirty, H.guiHooked = {}, {}, true, false
function H.gui(pg)
    if not pg then return {} end
    if not H.guiHooked then
        H.guiHooked = true
        local function add(d)
            if d:IsA("TextLabel") or d:IsA("TextButton") then H.guiSet[d] = true; H.guiDirty = true end
        end
        for _, d in ipairs(pg:GetDescendants()) do add(d) end
        pg.DescendantAdded:Connect(add)
        pg.DescendantRemoving:Connect(function(d) if H.guiSet[d] then H.guiSet[d] = nil; H.guiDirty = true end end)
    end
    if H.guiDirty then
        H.guiDirty = false
        local arr = {}
        for d in pairs(H.guiSet) do arr[#arr + 1] = d end
        H.guiArr = arr
    end
    return H.guiArr
end
-- log de diagnostico (arquivo MoonHub_Halloween_log.txt na pasta do executor): o que cada porta abriu, o que o hub fez e os inimigos do boss
local LOGF = "MoonHub_Halloween_log.txt"
local logBuf = {}
pcall(function() if writefile then writefile(LOGF, "Moon Hub - Halloween log\n") end end)
function H.log(m)
    local line = string.format("[%s] %s", os.date("%H:%M:%S"), tostring(m))
    pcall(function()
        if appendfile then appendfile(LOGF, line .. "\n")
        elseif writefile then
            logBuf[#logBuf + 1] = line
            if #logBuf > 400 then table.remove(logBuf, 1) end
            writefile(LOGF, table.concat(logBuf, "\n"))
        end
    end)
end
local function hsay(t)
    if H.lastSay ~= t then H.lastSay = t; H.log("status: " .. t) end
    H.status = t; Diag.halevent = t
end
local function hremote()
    local r = ReplicatedStorage:FindFirstChild("Remotes")
    return r and r:FindFirstChild("HalloweenEvent")
end
task.spawn(function()
    local r = ReplicatedStorage:WaitForChild("Remotes", 15)
    local he = r and r:WaitForChild("HalloweenEvent", 15)
    if not he then return end
    he.OnClientEvent:Connect(function(cmd, door, plr, info)
        if cmd == "DoorOpened" then
            local ok, dn = pcall(function() return door:GetFullName() end)
            H.log(string.format("DoorOpened by %s | Event=%s Boss=%s Scene=%s | %s", tostring(plr), tostring(type(info) == "table" and info.Event), tostring(type(info) == "table" and info.Boss), tostring(type(info) == "table" and info.Scene), ok and dn or "?"))
        elseif cmd ~= "PumpkinCandy" then
            H.log("server event: " .. tostring(cmd))
        end
        if cmd == "DoorOpened" and type(info) == "table" and (info.Boss == true or info.Event == "Boss Fight" or info.Event == "Hellfire Boss") then
            -- porta de boss (Lobisomen / Hellfire): vale para qualquer jogador que abriu, o portal aparece para todos
            H.boss = { door = door, ev = info.Event, t = os.clock(), stage = 0 }
        elseif cmd == "HellfireBossExit" or cmd == "HellfireBossDeath" then
            H.bossOver = os.clock()
        elseif cmd == "BossTeleportSound" and H.boss and H.boss.stage == 0 then
            H.boss.stage, H.boss.inAt = 1, os.clock()      -- o servidor acabou de levar o jogador para o dominio do boss
        end
        if cmd == "DoorOpened" and (plr == nil or plr == Player) and not (type(info) == "table" and (info.Boss == true or info.Event == "Boss Fight" or info.Event == "Hellfire Boss")) then
            -- abriu uma porta que nao e de boss: as portas de boss travadas voltam a poder ser abertas
            local okp, _, opos = pcall(function() return H.doorParts(door) end)
            H.unlockBossDoors(okp and opos or nil)
        end
        if cmd == "DoorOpened" and door == H.door and (plr == nil or plr == Player) then
            H.info = type(info) == "table" and info or {}
            H.openedAt = os.clock()
        elseif cmd == "EventFinished" and door == H.door then
            H.finished = true
        end
    end)
end)
-- cenas com remote proprio: { remote = nome, steps = { cmd | numero (espera em s) ... } }
local SCENES = {
    ["Fruit Dealer"] = { remote = "FruitDealer", steps = { "Beg", 9, "Done" } },                      -- 10 Candy Corn
    ["Cute Zer0"] = { remote = "ZeroLab", steps = { "Accept" } },                                      -- 30 Candy Corn
    ["Turtle Island Encounter"] = { remote = "TurtleTale", steps = { 8.15, "Listened", 8.15, "Done" } },   -- 30 Candy Corn
    ["parlus Scam"] = { treatArg = "None" },                                                           -- "dar" o candy e golpe: recusa
}
local SKIP = {}
local function waitUntil(t, cond)
    local t0 = os.clock()
    while Alive and os.clock() - t0 < t and not (cond and cond()) do task.wait(0.1) end
end
local function sceneRemote(door, name)
    local id = door:GetAttribute("EventId")
    if id == nil then return nil end
    local f = ReplicatedStorage:WaitForChild(tostring(id), 10)
    return f and f:WaitForChild(name, 10)
end

-- ---- cenas especiais (protocolo conferido no codigo do jogo; cada uma roda na sua propria thread) ----
local SP = {}
local function sfire(r, ...)
    local a = table.pack(...)
    pcall(function()
        if r:IsA("RemoteFunction") then r:InvokeServer(table.unpack(a, 1, a.n)) else r:FireServer(table.unpack(a, 1, a.n)) end
    end)
end
local function sinv(r, ...)
    local a = table.pack(...)
    local ok, res = pcall(function() return r:InvokeServer(table.unpack(a, 1, a.n)) end)
    if ok then return res end
    return nil
end
local function live(door) return Alive and H.door == door and not H.finished end
local function sleep(door, t) waitUntil(t, function() return not live(door) end) end
local function swing()
    pcall(function() if Core and Core.meleeSwordClick then Core.meleeSwordClick("Melee") end end)
    pcall(function() local ra = net("RE/RegisterAttack"); if ra then ra:FireServer() end end)
end

-- Gravedigger: Choose(1-4) -> mensagem "Outcome" -> (Stubborn: Focus) -> Ready (o servidor so aceita depois de um tempo minimo de cada resultado)
SP["Gravedigger"] = function(door)
    local r = sceneRemote(door, "Gravedigger"); if not r then return end
    local outcome
    local c = r.OnClientEvent:Connect(function(m, a, b) if m == "Outcome" then outcome = b end end)
    sleep(door, 1.5)
    local t0 = os.clock()
    -- v71: escolhe uma cova aleatoria (I, II ou III) clicando no dialogo; se nao pegar, manda o remote direto
    do
        local gr = math.random(1, 3)
        local pat = ({ "grave iii", "grave ii", "grave i" })[gr]
        local clicked = H.pickOption and H.pickOption({ pat }, 4)
        H.log("gravedigger: grave " .. gr .. (clicked and " (clicked)" or " (remote)"))
        if not clicked then sfire(r, "Choose", gr) end
    end
    while live(door) and not outcome and os.clock() - t0 < 16 do
        sfire(r, "Choose", math.random(1, 3)); sleep(door, 3)
    end
    if outcome then H.log("gravedigger: outcome " .. tostring(outcome)) end
    c:Disconnect()
    local min = ({ Ghosts = 3, Pumpkin = 4, Brother = 6, Stubborn = 4 })[outcome] or 5
    if outcome == "Stubborn" then sleep(door, 3.5); sfire(r, "Focus") end
    sleep(door, min + 0.5)
    for _ = 1, 6 do
        if not live(door) then break end
        sfire(r, "Ready"); sleep(door, 3)
    end
end
-- Sweet Ride: Fix -> (empurrar a roda) -> Returned ate chegar a mensagem "Fixed" (60 Candy Corn); se nao rolar, Rob e mata os ladroes
SP["Sweet Ride"] = function(door)
    local r = sceneRemote(door, "SweetRide"); if not r then return end
    local fixed = false
    local c = r.OnClientEvent:Connect(function(m) if m == "Fixed" then fixed = true end end)
    sleep(door, 2)
    sfire(r, "Fix"); sleep(door, 3)
    for _ = 1, 14 do
        if fixed or not live(door) then break end
        sfire(r, "Returned"); sleep(door, 1.5)
    end
    if not fixed and live(door) then sfire(r, "Rob") end
    c:Disconnect()
end
-- Don't Be Greedy: pega 4 punhados (a chance de ele ficar bravo e tomar tudo so sobe depois disso) e sai com "Leave"
SP["Don't Be Greedy"] = function(door)
    local r = sceneRemote(door, "GreedyBasket"); if not r then return end
    sleep(door, 3)
    for i = 1, 6 do
        if not live(door) then return end
        local res = sinv(r, "Grab")
        if type(res) ~= "table" then break end
        if res.Result == "Angry" or res.Result == "Empty" then return end
        if (res.Grabs or i) >= 4 then break end
        sleep(door, 1.6)
    end
    sinv(r, "Leave")
end
-- Magma Recipe: depois da animacao o cliente manda "Spill"; os slimes de magma que nascem sao mortos pelo loop normal da porta
SP["Magma Recipe"] = function(door)
    local r = sceneRemote(door, "MagmaRecipe"); if not r then return end
    local spilled = false
    local c = r.OnClientEvent:Connect(function(m) if m == "Spill" then spilled = true end end)
    sleep(door, math.max(0, 13 - (os.clock() - (H.openedAt or os.clock()))))
    for _ = 1, 4 do
        if spilled or not live(door) then break end
        sfire(r, "Spill"); sleep(door, 4)
    end
    c:Disconnect()
end

-- ---- clique na interface do jogo (dialogos e minigame das cartas) ----
local GuiService = game:GetService("GuiService")
local VIM
pcall(function() VIM = game:GetService("VirtualInputManager") end)
local function shown(g)
    local o = g
    while o and o ~= game do
        if o:IsA("GuiObject") and not o.Visible then return false end
        if o:IsA("ScreenGui") and not o.Enabled then return false end
        o = o.Parent
    end
    return true
end
local PICK_ALT = false
local function clickGui(g)
    if VIM then
        local pos, size = g.AbsolutePosition, g.AbsoluteSize
        local sg = g:FindFirstAncestorOfClass("ScreenGui")
        local ins = (sg and sg.IgnoreGuiInset) and Vector2.new(0, 0) or GuiService:GetGuiInset()
        if PICK_ALT then ins = (ins.Y > 0) and Vector2.new(0, 0) or GuiService:GetGuiInset() end
        local x, y = pos.X + size.X / 2 + ins.X, pos.Y + size.Y / 2 + ins.Y
        pcall(function()
            VIM:SendMouseMoveEvent(x, y, game)
            task.wait(0.05)
            VIM:SendMouseButtonEvent(x, y, 0, true, game, 1)
            task.wait(0.06)
            VIM:SendMouseButtonEvent(x, y, 0, false, game, 1)
        end)
    elseif firesignal and g:IsA("GuiButton") then
        pcall(function() firesignal(g.Activated); firesignal(g.MouseButton1Click) end)
    end
end
-- ---- escolher opcao de dialogo SEM clicar: usa o proprio DialogueController do jogo (DialogueController.select(opcao)) ----
local function optText(o)
    local parts, seen = {}, {}
    local function walk(v, depth)
        if depth > 3 or seen[v] then return end
        if type(v) == "string" then parts[#parts + 1] = v:lower():gsub("<[^>]+>", "") return end
        if type(v) ~= "table" then return end
        seen[v] = true
        for k, x in pairs(v) do
            if type(k) == "string" and (k == "_parent" or k == "_dialogue" or k == "_window") then continue end
            if type(x) == "string" or type(x) == "table" then walk(x, depth + 1) end
        end
    end
    pcall(walk, o, 0)
    return table.concat(parts, " | ")
end
local function dlgCur()
    local ok, DC = pcall(require, ReplicatedStorage:FindFirstChild("DialogueController"))
    if not ok or type(DC) ~= "table" or not DC.getActiveDialogue then return nil end
    local ok2, d = pcall(DC.getActiveDialogue)
    if not ok2 or not d then return nil end
    local ok3, cur = pcall(function() return d:getCurrent() end)
    if not ok3 or not cur then return nil end
    return DC, cur
end
-- pats: lista de textos (minusculos) ou nil = primeira opcao que nao seja a de cancelar; "nevermind" = a opcao de cancelar
local function dlgTry(pats)
    local DC, cur = dlgCur()
    if not cur then return false end
    local opts = cur._options or {}
    local function fire(o)
        if o._locked then return false end
        local ok = pcall(DC.select, o)
        if ok then H.log("dialogue: selected option via DialogueController (" .. optText(o):sub(1, 50) .. ")") end
        return ok
    end
    if pats then
        for _, pt in ipairs(pats) do
            if pt == "nevermind" or pt == "never mind" then
                local ok, c = pcall(function() return cur:getCancelOption() end)
                if ok and c and fire(c) then return true end
            end
        end
        for _, o in ipairs(opts) do
            local t = optText(o)
            for _, pt in ipairs(pats) do
                if t:find(pt, 1, true) and fire(o) then return true end
            end
        end
        return false
    end
    for _, o in ipairs(opts) do
        if fire(o) then return true end
    end
    return false
end
-- acha a opcao de dialogo pelo texto (o menor texto que contem o padrao = o botao, nao a fala) e clica
local function pickOption(pats, timeout)
    local t0 = os.clock()
    while Alive and os.clock() - t0 < timeout do
        if dlgTry(pats) then task.wait(0.15); return true end
        local pg = Player:FindFirstChild("PlayerGui")
        local best, bl
        for _, d in ipairs(H.gui(pg)) do
            if (d:IsA("TextLabel") or d:IsA("TextButton")) and d.Text ~= "" and d.AbsoluteSize.X > 0 and shown(d) then
                local t = (d.Text:lower():gsub("<[^>]+>", ""))
                for _, pt in ipairs(pats) do
                    if t:find(pt, 1, true) and (not bl or #t < bl) then best, bl = d, #t end
                end
            end
        end
        if best and bl <= 60 then
            local tgt = best
            while tgt and not tgt:IsA("GuiButton") and not tgt:IsA("ScreenGui") do tgt = tgt.Parent end
            if not (tgt and tgt:IsA("GuiButton")) then tgt = best end
            task.wait(0.12)
            clickGui(tgt)
            -- confere se o clique pegou (a opcao some da tela); se nao, tenta de outros jeitos
            local function gone()
                task.wait(0.45)
                return not (best.Parent and shown(best) and best.AbsoluteSize.X > 0)
            end
            local ok = gone()
            if not ok then
                if firesignal then
                    local b = best
                    while b and not b:IsA("GuiButton") and not b:IsA("ScreenGui") do b = b.Parent end
                    if b and b:IsA("GuiButton") then
                        pcall(function() firesignal(b.MouseButton1Down) end)
                        pcall(function() firesignal(b.MouseButton1Up) end)
                        pcall(function() firesignal(b.MouseButton1Click) end)
                        pcall(function() firesignal(b.Activated) end)
                    end
                end
                ok = gone()
                if not ok then
                    -- segunda tentativa de clique com o outro modo de inset
                    PICK_ALT = not PICK_ALT
                    clickGui(tgt)
                    ok = gone()
                end
            end
            if not ok then H.log("click did not register: " .. tostring(best.Text):sub(1, 40)) end
            return ok
        end
        task.wait(0.3)
    end
    return false
end
H.pickOption = pickOption
local function closeDlg()
    pcall(function() require(ReplicatedStorage.DialogueController).close() end)
end
-- ---- Tarot: jogo da memoria (10 cartas, 5 pares) ----
local function content(c)
    local t = {}
    local function add(d)
        if d:IsA("ImageLabel") or d:IsA("ImageButton") then t[#t + 1] = d.Image .. "|" .. tostring(d.ImageRectOffset) .. "|" .. tostring(d.ImageRectSize)
        elseif d:IsA("TextLabel") then t[#t + 1] = d.Text end
    end
    add(c)
    for _, d in ipairs(c:GetDescendants()) do add(d) end
    return table.concat(t, ";")
end
local function cstate(c)
    local t = {}
    local function add(d)
        if d:IsA("GuiObject") then t[#t + 1] = tostring(d.Visible) end
        if d:IsA("ImageLabel") or d:IsA("ImageButton") then t[#t + 1] = string.format("%.1f", d.ImageTransparency) end
    end
    add(c)
    for _, d in ipairs(c:GetDescendants()) do add(d) end
    return table.concat(t, ",")
end
local function findCards()
    local pg = Player:FindFirstChild("PlayerGui")
    if not pg then return nil end
    local buckets = {}
    for _, d in ipairs(pg:GetDescendants()) do
        if d:IsA("GuiObject") and d.AbsoluteSize.X > 40 and d.AbsoluteSize.X < 420 and d.AbsoluteSize.Y > d.AbsoluteSize.X * 1.1 and shown(d) then
            local par = d.Parent
            if par then
                local key = math.floor(d.AbsoluteSize.X / 3) .. "x" .. math.floor(d.AbsoluteSize.Y / 3)
                buckets[par] = buckets[par] or {}
                buckets[par][key] = buckets[par][key] or {}
                table.insert(buckets[par][key], d)
            end
        end
    end
    local best
    for _, byKey in pairs(buckets) do
        for _, list in pairs(byKey) do
            local n = #list
            if n >= 6 and n <= 20 and n % 2 == 0 then
                local score = (n == 10 and 100 or 0) + n
                if not best or score > best.score then best = { score = score, list = list } end
            end
        end
    end
    if not best then return nil end
    table.sort(best.list, function(a, b)
        local ra, rb = math.floor(a.AbsolutePosition.Y / (a.AbsoluteSize.Y * 0.5)), math.floor(b.AbsolutePosition.Y / (b.AbsoluteSize.Y * 0.5))
        if ra ~= rb then return ra < rb end
        return a.AbsolutePosition.X < b.AbsolutePosition.X
    end)
    return best.list
end
local function gameOpen(cg, cards)
    if cg then
        local ok, v = pcall(function() return cg:IsOpen() end)
        if ok then return v and true or false end
    end
    return cards and cards[1] and cards[1].Parent ~= nil and shown(cards[1]) or false
end
local function playCards(door, cg)
    local t0 = os.clock()
    local cards
    while live(door) and os.clock() - t0 < 40 and not cards do
        cards = findCards()
        if not cards then task.wait(0.5) end
    end
    if not cards then hsay("Tarot: cards not found"); return false end
    local n = #cards
    local base, baseS = {}, {}
    for i, c in ipairs(cards) do base[i], baseS[i] = content(c), cstate(c) end
    local function flip(i)
        clickGui(cards[i])
        local t = os.clock()
        while os.clock() - t < 1.6 do
            task.wait(0.1)
            if content(cards[i]) ~= base[i] or cstate(cards[i]) ~= baseS[i] then task.wait(0.55); return true end
        end
        return false
    end
    local function waitBack(a, b)
        local t = os.clock()
        while os.clock() - t < 3.5 do
            if cstate(cards[a]) == baseS[a] and cstate(cards[b]) == baseS[b] then break end
            task.wait(0.15)
        end
        task.wait(0.35)
    end
    local matched, count = {}, 0
    -- 1) as faces ja aparecem no baseline (imagem escondida)? entao os pares ja estao dados
    local groups = {}
    for i = 1, n do groups[base[i]] = groups[base[i]] or {}; table.insert(groups[base[i]], i) end
    local revealed = true
    local ng = 0
    for _, g in pairs(groups) do ng += 1; if #g ~= 2 then revealed = false end end
    if revealed and ng == n / 2 then
        for _, g in pairs(groups) do
            if not (live(door) and gameOpen(cg, cards)) then break end
            flip(g[1]); flip(g[2]); task.wait(0.7)
        end
        return true
    end
    -- 2) vira e memoriza
    local face = {}
    local guard = 0
    while live(door) and gameOpen(cg, cards) and count < n and guard < 80 do
        guard += 1
        hsay(string.format("Tarot: %d/%d cards matched", count, n))
        local a, b
        for i = 1, n do
            if not matched[i] and face[i] then
                for j = i + 1, n do
                    if not matched[j] and face[j] == face[i] then a, b = i, j; break end
                end
            end
            if a then break end
        end
        if a then
            flip(a); flip(b)
            matched[a], matched[b] = true, true; count += 2
            task.wait(0.6)
        else
            local x
            for i = 1, n do if not matched[i] and not face[i] then x = i; break end end
            if not x then break end
            if not flip(x) then task.wait(0.5) else
                face[x] = content(cards[x])
                local partner
                for j = 1, n do if j ~= x and not matched[j] and face[j] == face[x] then partner = j; break end end
                if partner then
                    flip(partner); matched[x], matched[partner] = true, true; count += 2; task.wait(0.6)
                else
                    local y
                    for i = 1, n do if i ~= x and not matched[i] and not face[i] then y = i; break end end
                    if y and flip(y) then
                        face[y] = content(cards[y])
                        if face[y] == face[x] then matched[x], matched[y] = true, true; count += 2; task.wait(0.6)
                        else waitBack(x, y) end
                    end
                end
            end
        end
    end
    return count >= n
end
-- Tarot (bruxa) e Mystery Hall (Frankenstein & cia): pula direto - clica "Nevermind" (ou manda Decline) e vai para a proxima porta
SP["Tarot"] = function(door)
    -- recusa na hora (remote), fecha o dialogo e, se ele ainda estiver na tela, clica "Nevermind"
    local r = sceneRemote(door, "TarotReading")
    if r then sfire(r, "Decline") end
