    pickOption({ "nevermind" }, 1.5)
end
-- Zer0 Slap (rip_return pescando): clica "TRICK OR TREAT!" na tela; sem tela, usa a RemoteFunction (workspace._WorldOrigin[EventId]._storagePtr)
SP["Zer0 Slap"] = function(door)
    H.fishUntil = os.clock() + 90
    local got = pickOption({ "trick or treat" }, 14)
    if got then
        -- se a fala "TRICK OR TREAT!" continua na tela, o clique nao pegou: manda direto pelo RemoteFunction
        local still = false
        local pg = Player:FindFirstChild("PlayerGui")
        for _, d in ipairs(H.gui(pg)) do
            if d:IsA("TextLabel") and d.Text:lower():find("trick or treat", 1, true) and shown(d) and d.AbsoluteSize.X > 0 then still = true break end
        end
        if not still then sleep(door, 1); closeDlg(); return end
        H.log("zer0: click did not register, using the RemoteFunction")
    end
    local wo = workspace:FindFirstChild("_WorldOrigin")
    local box = wo and wo:WaitForChild(tostring(door:GetAttribute("EventId")), 20)
    local ptr = box and box:WaitForChild("_storagePtr", 20)
    if not ptr then return end
    local t0 = os.clock()
    while live(door) and not ptr.Value and os.clock() - t0 < 10 do task.wait(0.2) end
    local rf = ptr.Value and ptr.Value:WaitForChild("RemoteFunction", 10)
    if not rf then return end
    sinv(rf, "activate", "candy")
    sleep(door, 2); closeDlg()
end
-- One Free Roll (Zioles): escolhe "One free roll!" (o jogo faz Roll/Revealed/Done sozinho); sem tela, manda os remotes
