-- Ghost Chase: AcceptReward, o fantasma foge com o saco (posicao em door:GetAttribute("GhostLeg")); bate nele e depois pega os docinhos
-- que caem (atributos GhostCandy_<id> com a posicao) mandando HalloweenEvent:FireServer("GhostCandy", id)
local function ghostPos(door)
    local a = door:GetAttribute("GhostLeg")
    if type(a) ~= "string" then return nil end
    local t = {}
    for n in a:gmatch("[^,]+") do t[#t + 1] = tonumber(n) end
    if #t ~= 8 then return nil end
    local span = t[8] - t[7]
    local k = span <= 0 and 1 or math.clamp((workspace:GetServerTimeNow() - t[7]) / span, 0, 1)
    return Vector3.new(t[1], t[2], t[3]):Lerp(Vector3.new(t[4], t[5], t[6]), math.sin(k * math.pi / 2))
end
-- v71: ataque dedicado no fantasma. Antes dependia do "pin" do boss (H.bossDmg so roda com H.pin ativo), entao so perseguia e nunca batia.
-- Itens (Config.GhostTools) em rodizio + skills (Config.GhostSkills) escolhidas pelo jogador; mira numa parte invisivel colada no fantasma.
function H.ghostHit(gp)
    local ch = Player.Character
    local hum = ch and ch:FindFirstChildOfClass("Humanoid")
    if not hum then return end
    local ap = H.ghostAim
    if not (ap and ap.Parent) then
        ap = Instance.new("Part"); ap.Name = "MoonGhostAim"; ap.Size = Vector3.new(3, 3, 3); ap.Anchored = true
        ap.CanCollide = false; ap.CanQuery = false; ap.CanTouch = false; ap.Transparency = 1; ap.Parent = workspace
        H.ghostAim = ap
    end
    ap.CFrame = CFrame.new(gp)
    pcall(function() Aim.part = ap end)
    local sel = type(Config.GhostTools) == "table" and Config.GhostTools or {}
    local tips = {}
    for _, t in ipairs({ "Melee", "Blox Fruit", "Sword", "Gun" }) do if sel[t] then tips[#tips + 1] = t end end
    if #tips == 0 then tips = { "Melee" } end
    local now = os.clock()
    if now - (H.ghostTipAt or 0) > 0.7 or not H.ghostTip then
        H.ghostTipAt = now
        H.ghostTipI = (H.ghostTipI or 0) % #tips + 1
        H.ghostTip = tips[H.ghostTipI]
    end
    local tip = H.ghostTip
    local tool = H.bossTool(tip)
    if tool then pcall(function() if tool.Parent ~= ch then hum:EquipTool(tool) end end) end
    if tip == "Melee" then pcall(__E.cfAttack or function() end)
    elseif tip == "Blox Fruit" then pcall(function() if Core.fruitTick then Core.fruitTick() end end)
    elseif tip == "Sword" then pcall(function() if Core.meleeSwordClick then Core.meleeSwordClick("Sword") end end) end
    pcall(function() local t = ch:FindFirstChildOfClass("Tool"); if t then t:Activate() end end)
    pcall(function() local ra = net("RE/RegisterAttack"); if ra then ra:FireServer() end end)
    local sk = type(Config.GhostSkills) == "table" and Config.GhostSkills or {}
    if now - (H.ghostSkAt or 0) > 0.9 and Core and Core.pressKey then
        local keys = {}
        for _, kn in ipairs({ "Z", "X", "C", "V", "F" }) do if sk[kn] then keys[#keys + 1] = kn end end
        if #keys > 0 then
            H.ghostSkAt = now
            H.ghostSkI = (H.ghostSkI or 0) % #keys + 1
            local k = Enum.KeyCode[keys[H.ghostSkI]]
            task.spawn(function() Core.pressKey(k) end)
        end
    end
end
SP["Ghost Chase"] = function(door)
    local he = hremote()
    sleep(door, 1.5)
    if pickOption({ "trick or treat" }, 8) then H.clickedDoor = door
    elseif he then pcall(function() he:FireServer("AcceptReward") end) end
    local t0 = os.clock()
    while live(door) and door:GetAttribute("GhostState") ~= "Fleeing" and os.clock() - t0 < 10 do task.wait(0.2) end
    local t1 = os.clock()
    while live(door) and door:GetAttribute("GhostState") == "Fleeing" and os.clock() - t1 < 45 do
        H.holdUntil = os.clock() + 2
        local _, hrp = getChar()
        local gp = ghostPos(door)
        if hrp and gp then
            -- v145: gruda no fantasma a cada frame (antes 0,12 s) e bate com todas as armas escolhidas em rodizio (Melee/Fruta/Espada/Gun)
            if (hrp.Position - gp).Magnitude > 2 then hrp.CFrame = CFrame.new(gp + Vector3.new(0, 1, 2)); hrp.AssemblyLinearVelocity = Vector3.zero end
            H.ghostHit(gp)
        end
        task.wait()
    end
    pcall(function() Aim.part = nil end)
    -- docinhos que ficaram
    local t2 = os.clock()
    local got = {}
    while live(door) and os.clock() - t2 < 14 do
        H.holdUntil = os.clock() + 2
        local any = false
        for name, v in pairs(door:GetAttributes()) do
            if type(name) == "string" and name:sub(1, 11) == "GhostCandy_" and typeof(v) == "Vector3" and not got[name] then
                any = true
                local id = tonumber(name:sub(12))
                local _, hrp = getChar()
                if hrp and id then
                    hrp.CFrame = CFrame.new(v + Vector3.new(0, 2, 0))
                    task.wait(0.15)
                    if he then pcall(function() he:FireServer("GhostCandy", id) end) end
                    got[name] = true
                end
            end
        end
        if not any then
            local st = door:GetAttribute("GhostState")
            if st == "Caught" or st == "Escaped" or os.clock() - t2 > 5 then break end
        end
        task.wait(0.2)
    end
end
function H.handle(door, info)
    local ev = info and info.Event
    H.last = tostring(ev)
    H.log("handling scene: " .. tostring(ev) .. (SP[ev or ""] and " (special)" or (SCENES[ev or ""] and " (remote scene)" or " (treat/fight)")))
    if info and (info.Boss == true or ev == "Boss Fight" or ev == "Hellfire Boss") then return end
    if ev and SKIP[ev] then return end
    if ev == "Dragon Hunter" then
        -- v71: cena do cofre ("Grab a Hand"): vigia a tela e os prompts perto do jogador durante a porta e clica sozinho
        task.spawn(function()
            local t0 = os.clock()
            local pats = { "grab a hand", "grab the hand", "grab hand", "grab his hand", "grab a", "a hand" }
            while live(door) and os.clock() - t0 < 120 do
                if pickOption(pats, 0.5) then H.log("dragon hunter: clicked the grab option"); task.wait(1.2) end
                local _, hrp = getChar()
                if hrp and fireproximityprompt then
                    pcall(function()
                        local seen = {}
                        for _, part in ipairs(workspace:GetPartBoundsInRadius(hrp.Position, 45)) do
                            for _, o in ipairs(part:GetChildren()) do
                                if o:IsA("ProximityPrompt") and o.Enabled and not seen[o] then
                                    seen[o] = true
                                    local t = ((o.ActionText or "") .. " " .. (o.ObjectText or "")):lower()
                                    if t:find("hand", 1, true) or t:find("grab", 1, true) then
                                        o.HoldDuration = 0
                                        fireproximityprompt(o)
                                        H.log("dragon hunter: fired prompt '" .. t .. "'")
                                    end
                                end
                            end
                        end
                    end)
                end
                task.wait(0.3)
            end
        end)
    end
    if ev and SP[ev] then SP[ev](door, info); return end
    local he = hremote()
    local sc = ev and SCENES[ev]
    if sc and sc.remote then
        local r = sceneRemote(door, sc.remote)
        if not r then return end
        for _, st in ipairs(sc.steps) do
            if H.door ~= door or not Alive then return end
            if type(st) == "number" then waitUntil(st, function() return H.finished end)
            else pcall(function() r:FireServer(st) end) end
        end
        pcall(closeDlg)
        return
    end
    -- porta "treat": aceita o doce e fecha o dialogo
    if not he then return end
    -- o clique automatico no dialogo ("Trick or Treat!" etc.) faz o proprio jogo mandar o AcceptReward; sem dialogo em 5 s, manda direto
    do
        local t0 = os.clock()
        while live(door) and H.clickedDoor ~= door and os.clock() - t0 < 2.5 do task.wait(0.1) end
        if H.clickedDoor == door then sleep(door, 0.3) end    -- da tempo do jogo mandar o AcceptReward sozinho
    end
    -- o dialogo ainda esta na tela (o clique nao pegou)? manda o aceite direto e fecha
    local function dlgOpen()
        local pg = Player:FindFirstChild("PlayerGui")
        for _, d in ipairs(H.gui(pg)) do
            if d:IsA("TextLabel") and d.AbsoluteSize.X > 0 then
                local t = d.Text:lower()
                if (t:find("nevermind", 1, true) or t:find("never mind", 1, true)) and shown(d) then return true end
            end
        end
        return false
    end
    if H.clickedDoor ~= door or dlgOpen() then
        pcall(function() if sc and sc.treatArg then he:FireServer("AcceptReward", sc.treatArg) else he:FireServer("AcceptReward") end end)
        sleep(door, 0.6)
        closeDlg()
    end
    waitUntil(1.5, function() return H.finished end)
    pcall(function() he:FireServer("TreatDialogueClosed") end)
end
local function doorParts(door)
    local prox = door:FindFirstChild("Proximity")
    local prompt = prox and prox:FindFirstChild("ProximityPrompt")
    local pos
    if prox and prox:IsA("BasePart") then pos = prox.Position
    else
        local part = door:FindFirstChild("Part")
        if part and part:IsA("BasePart") then pos = part.Position end
    end
    return prompt, pos
end
H.doorParts = doorParts
H.blockPos = {}
-- v64: porta bloqueada tambem por POSICAO (o jogo recria o modelo da porta com outra instancia; so a instancia nao bastava e o hub voltava na mesma porta do portal)
function H.blockDoor(door, secs, sticky)
    if not door then return end
    H.bl[door] = os.clock() + secs
    local _, pos = doorParts(door)
    if pos then H.blockPos[#H.blockPos + 1] = { pos = pos, t = os.clock() + secs, sticky = sticky } end
end
-- v71: o jogo so deixa abrir a porta do boss de novo depois de abrir OUTRA porta. Guarda as portas de boss vistas (a do portal pode ser outra)
-- e trava todas ate o jogador abrir uma porta diferente.
H.bossSeen = {}
function H.noteBossDoors()
    for d in pairs(H.set) do
        if d.Parent and d:GetAttribute("BOSS_ACTIVE_SERVER") then
            local _, pos = doorParts(d)
            if pos then H.bossSeen[d] = pos end
        end
    end
end
function H.lockBossDoors()
    H.noteBossDoors()
    for d, pos in pairs(H.bossSeen) do
        H.bl[d] = os.clock() + 3600
        H.blockPos[#H.blockPos + 1] = { pos = pos, t = os.clock() + 3600, sticky = true }
    end
    H.bossSeen = {}
end
function H.unlockBossDoors(openedPos)
    for bi = #H.blockPos, 1, -1 do
        local bp = H.blockPos[bi]
        if bp.sticky and (not openedPos or (bp.pos - openedPos).Magnitude >= 20) then table.remove(H.blockPos, bi) end
    end
    for d, t in pairs(H.bl) do
        local _, pos = doorParts(d)
        if t > os.clock() + 700 and (not openedPos or not pos or (pos - openedPos).Magnitude >= 20) then H.bl[d] = nil end
    end
end
local function doorReady(door)
    if not door.Parent or (H.bl[door] or 0) > os.clock() then return false end
    do
        local _, dpos = doorParts(door)
        if dpos then
            for bi = #H.blockPos, 1, -1 do
                local bp = H.blockPos[bi]
                if os.clock() > bp.t then table.remove(H.blockPos, bi)
                elseif (bp.pos - dpos).Magnitude < 20 then return false end
            end
        end
    end
    if door:GetAttribute("DoorOpen") then return false end
    local cd = door:GetAttribute("CooldownUntil")
    if type(cd) == "number" and workspace:GetServerTimeNow() < cd then return false end
    local prompt, pos = doorParts(door)
    return prompt ~= nil and pos ~= nil and prompt.Enabled
end
H.set = {}
task.spawn(function()
    local map = workspace:WaitForChild("Map", 30)
    if not map then return end
    local function adopt(d) if d.Name == "HalloweenDoor" and d:IsA("Model") then H.set[d] = true end end
    map.DescendantAdded:Connect(adopt)
    for _, d in ipairs(map:GetDescendants()) do adopt(d) end
end)
function H.active() return workspace:GetAttribute("HalloweenEventActive") == true end
function H.doors()
    if os.clock() - H.cacheAt > 1 then
        H.cacheAt = os.clock()
        H.cache = {}
        for d in pairs(H.set) do
            if d.Parent then H.cache[#H.cache + 1] = d else H.set[d] = nil end
        end
    end
    return H.cache
end
local function enemySet()
    local set = setmetatable({}, { __mode = "k" })
    local en = workspace:FindFirstChild("Enemies")
    for _, e in ipairs(en and en:GetChildren() or {}) do set[e] = true end
    return set
end
local function newFoe(hrp, center)
    local en = workspace:FindFirstChild("Enemies")
    local best, bd, deep, dd
    for _, e in ipairs(en and en:GetChildren() or {}) do
        if not (H.snap and H.snap[e]) then
            local hum, root = aliveParts(e)
            if hum and root and (root.Position - center).Magnitude < ((H.last == "Gravedigger" or H.last == "Dragon Hunter") and 800 or 300) then
                local dist = (root.Position - hrp.Position).Magnitude
                if root.Position.Y < center.Y - 5 and not (H.last == "Gravedigger" and (root.Position - center).Magnitude > 300) then
                    if not dd or dist < dd then deep, dd = e, dist end      -- debaixo da agua: espera subir
                elseif not bd or dist < bd then best, bd = e, dist end
            end
        end
    end
    return best, deep
end
local function give_up(why, secs)
    H.bl[H.door] = os.clock() + (secs or 120)
    hsay("Skipping door: " .. why)
    H.door, H.info, H.finished, H.handled, H.snap = nil, nil, false, false, nil
end
-- ---- Auto Kill Halloween Bosses (Lobisomen "Boss Fight" e "Hellfire Boss") ----
-- O portal (parte "comm") aparece em door.Part; o servidor leva quem estiver na porta para o dominio do boss
-- (evento "BossTeleportSound"; o dominio fica bem longe/abaixo do mapa) e o boss nasce em workspace.Enemies
-- ("Unbound Werewolf"; o Hellfire e achado por nome com "Hell"/"Fire" ou por ser o inimigo vivo mais perto no dominio).
local function bossPos(door)
    local part = door and door:FindFirstChild("Part")
    if part and part:IsA("BasePart") then return (part.CFrame * CFrame.new(0, 0, -0.5)).Position end
    local _, pos = doorParts(door)
    return pos
end
local function bossFoe(hrp)
    local en = workspace:FindFirstChild("Enemies")
    local best, bd, pref
    for _, e in ipairs(en and en:GetChildren() or {}) do
        local hum, root = aliveParts(e)
        if hum and root then
            local dist = (root.Position - hrp.Position).Magnitude
            local nm = e.Name:lower()
            local p = (nm:find("werewolf", 1, true) or nm:find("hell", 1, true) or nm:find("inferno", 1, true) or nm:find("boss", 1, true)) and dist < 450
            if p and not pref then best, bd, pref = e, dist, true
            elseif (p and pref or (not p and not pref)) and (not bd or dist < bd) and dist < 800 then best, bd = e, dist end
        end
    end
    return best
end
-- dentro do dominio do boss: o inimigo NOVO (que nao existia antes do portal) ou com nome de boss; sem limite de distancia
local function bossFoe2(hrp, snap)
    local en = workspace:FindFirstChild("Enemies")
    local best, bs, bd
    for _, e in ipairs(en and en:GetChildren() or {}) do
        local hum, root = aliveParts(e)
        if hum and root then
            local nm = e.Name:lower()
            local named = nm:find("werewolf", 1, true) or nm:find("hell", 1, true) or nm:find("inferno", 1, true) or nm:find("boss", 1, true) or nm:find("unbound", 1, true)
            local isNew = not (snap and snap[e])
            local dist = (root.Position - hrp.Position).Magnitude
            local score
            if named and isNew then score = 0
            elseif named and dist < 450 then score = 1
            elseif isNew and dist < 600 then score = 2 end
            if score and (not bs or score < bs or (score == bs and dist < bd)) then best, bs, bd = e, score, dist end
        end
    end
    return best
end
function H.logEnemies(hrp, tag)
    if os.clock() - (H.lastEn or 0) < 4 then return end
    H.lastEn = os.clock()
    local en = workspace:FindFirstChild("Enemies")
    local parts = {}
    for _, e in ipairs(en and en:GetChildren() or {}) do
        local hum, root = aliveParts(e)
        if hum and root then
            parts[#parts + 1] = string.format("%s hp=%d/%d dist=%d y=%d", e.Name, hum.Health, hum.MaxHealth, (root.Position - hrp.Position).Magnitude, root.Position.Y)
        end
        if #parts >= 8 then break end
    end
    local hum = hrp.Parent and hrp.Parent:FindFirstChildOfClass("Humanoid")
    H.log(string.format("%s | me hp=%d/%d pos=(%d,%d,%d) | enemies: %s", tag, hum and hum.Health or -1, hum and hum.MaxHealth or -1, hrp.Position.X, hrp.Position.Y, hrp.Position.Z, #parts > 0 and table.concat(parts, " ; ") or "none"))
end
-- arena do boss Hellfire (workspace.Map.HellfireBossRealm / HellfireBossArena): caixa que limita ate onde o personagem pode subir
local function arenaBox(pos)
    local Map = workspace:FindFirstChild("Map")
    if not Map then return nil end
    for _, nm in ipairs({ "HellfireBossArena", "HellfireBossRealm" }) do
        local m = Map:FindFirstChild(nm)
        if m and m:IsA("Model") then
            local ok, cf, sz = pcall(function() local a, b = m:GetBoundingBox() return a, b end)
            if ok and cf and sz then
                local o = cf:PointToObjectSpace(pos)
                if math.abs(o.X) <= sz.X / 2 and math.abs(o.Y) <= sz.Y / 2 and math.abs(o.Z) <= sz.Z / 2 then return cf, sz end
            end
        end
    end
    return nil
end
-- posicao de ataque: em cima do boss, mas nunca mais alto que a altitude em que chegamos (+45) nem que o teto da arena; o boss que sobe nao leva o personagem junto
local function pinPos(b, fr)
    local y = fr.Position.Y + 9
    if b then
        local cap = (b.arriveY or y) + 45
        -- cratera do Dapper Jack (boss do caldeirao): ele voa alto, entao o limite e o teto da arena, nao a altura de chegada
        local g = H.great
        local gc = g and g.center and g.center()
        if gc and math.abs(fr.Position.Y - gc.Y) <= 420 and Vector3.new(fr.Position.X - gc.X, 0, fr.Position.Z - gc.Z).Magnitude <= 360 then cap = gc.Y + 380 end
        local cf, sz = arenaBox(fr.Position)
        if cf then cap = math.min(cap, cf.Position.Y + sz.Y / 2 - 3) end
        if y > cap then y = cap end
    end
    return Vector3.new(fr.Position.X, y, fr.Position.Z)
end
-- boss extra (ex.: abobora gigante / raid boss que nasce com materiais na bruxa): qualquer inimigo vivo com esses nomes, em qualquer lugar
local EXTRA = { "great pumpkin", "pumpkin boss", "pumpkin king", "headless", "raid boss", "giant pumpkin", "pumpkin lord", "dapper jack" }
H.bigSeen = setmetatable({}, { __mode = "k" })
function H.extraBoss(hrp)
    if os.clock() - (H.extraScan or 0) < 0.5 then return H.extraFoe ~= nil and H.extraFoe.Parent ~= nil and (os.clock() < (H.extraUntil or 0)) end
    H.extraScan = os.clock()
    local en = workspace:FindFirstChild("Enemies")
    local found
    for _, e in ipairs(en and en:GetChildren() or {}) do
        local hum, root = aliveParts(e)
        if hum and root then
            local nm = e.Name:lower()
            if hum.MaxHealth >= 100000 and not H.bigSeen[e] then
                H.bigSeen[e] = true
                H.log(string.format("big enemy: %s hp=%d/%d dist=%d", e.Name, hum.Health, hum.MaxHealth, (root.Position - hrp.Position).Magnitude))
            end
            for _, pt in ipairs(EXTRA) do
                if nm:find(pt, 1, true) then found = e break end
            end
            if found then break end
        end
    end
    H.extraFoe = found
    if found then H.extraUntil = os.clock() + 3 end
    return found ~= nil
end
function H.pinOn(hrp, foe)
    local fr = foe and (foe:FindFirstChild("HumanoidRootPart") or foe:FindFirstChildWhichIsA("BasePart"))
    if not fr then return false end
    H.extraB = H.extraB or {}
    if H.extraB.foe ~= foe then H.extraB = { foe = foe, arriveY = hrp.Position.Y } end
    H.pin = { part = fr, b = H.extraB, until_ = os.clock() + 1.0 }
    pcall(function()
        hrp.CFrame = CFrame.new(pinPos(H.extraB, fr)) * CFrame.Angles(0, 0, 0)
        hrp.AssemblyLinearVelocity = Vector3.zero
    end)
    pcall(function() Aim.part = fr end)
    pcall(equipWeapon)
    if __E.wantAttack then pcall(__E.wantAttack, false) end
    return true
end
-- dano no boss grande (Great Pumpkin): rodizio de armas (fruta, soco, espada, arma) com M1 + skills Z X C V F, em segundo plano
function H.bossTool(tip)
    local ch = Player.Character
    for _, c in ipairs({ ch, Player:FindFirstChild("Backpack") }) do
        for _, t in ipairs(c and c:GetChildren() or {}) do
            if t:IsA("Tool") and t.ToolTip == tip then return t end
        end
    end
end
function H.bossDmg()
    if H.dmgRunning then return end
    H.dmgRunning = true
    task.spawn(function()
        local tips = { "Blox Fruit", "Melee", "Sword", "Gun" }
        local i = 0
        local function active() return Alive and H.pin and os.clock() < (H.pin.until_ or 0) + 0.6 end
        -- v64: usa SO a arma escolhida em Farm Settings (antes alternava Fruta/Soco/Espada a cada 1,5 s). So troca de arma se o
        -- boss ficar 10 s sem perder vida com ela (ai volta a rodar as outras ate algo funcionar).
        local sel = Config.Weapon
        if sel ~= "Blox Fruit" and sel ~= "Melee" and sel ~= "Sword" then sel = "Melee" end
        local lastHp, lastDrop = nil, os.clock()
        -- v80: antes alternava Fruta/Soco/Espada/Arma a cada 10 s sem dano e o equipWeapon() (arma das configuracoes) brigava com ela,
        -- trocando o clique toda hora. Agora fica SEMPRE na arma escolhida; so troca (e fica na nova) depois de 25 s sem nenhum dano,
        -- e avisa o equipWeapon() qual e a arma atual (Config.SeaTool) para os dois nao se contradizerem.
        local cur = sel
        while active() do
            local mdl = H.pin and H.pin.part and H.pin.part:FindFirstAncestorOfClass("Model")
            local bh = mdl and mdl:FindFirstChildOfClass("Humanoid")
            if bh then
                if not lastHp or bh.Health < lastHp - 0.5 then lastDrop = os.clock() end
                lastHp = bh.Health
            end
            if os.clock() - lastDrop > 25 then
                local idx = 1
                for k, v in ipairs(tips) do if v == cur then idx = k end end
                cur = tips[idx % #tips + 1]
                lastDrop = os.clock()
                H.log("boss: no damage for 25 s, switching weapon to " .. cur)
            end
            local tip = cur
            pcall(function() Config.SeaTool, Config.SeaUntil = { tip = tip }, os.clock() + 1.5 end)
            local tool = H.bossTool(tip)
            local ch = Player.Character
            local hum = ch and ch:FindFirstChildOfClass("Humanoid")
            if tool and hum then
                pcall(function() hum:EquipTool(tool) end)
                task.wait(0.12)
                local t0 = os.clock()
                while active() and os.clock() - t0 < 1.5 do
                    if tip == "Melee" then pcall(__E.cfAttack or function() end)
                    elseif tip == "Blox Fruit" then pcall(function() if Core.fruitTick then Core.fruitTick() end end)
                    elseif Core.meleeSwordClick and tip == "Sword" then pcall(Core.meleeSwordClick, tip) end
                    pcall(function() tool:Activate() end)
                    task.wait(0.03)
                end
                -- so clique (M1): as skills (ex.: Sanguine Art X) faziam o boss sumir da luta
            else
                task.wait(0.1)
            end
        end
        H.dmgRunning = false
    end)
end
function H.extraStep(hrp)
    local foe = H.extraFoe
    if not (foe and foe.Parent) then
        if foe and H.extraLogged == foe and not H.vanishLogged then H.vanishLogged = true; H.log("extra boss: the boss model was removed from workspace") end
        H.pin = nil
        return false
    end
    H.vanishLogged = nil
    local fr = foe:FindFirstChild("HumanoidRootPart") or foe:FindFirstChildWhichIsA("BasePart")
    if not fr then return false end
    -- posicao absurda (boss "sumiu" e a parte foi parar longe / no vazio): nao voa atras dela
    do
        local pp = fr.Position
        local GRr = H.great
        local c = GRr and GRr.center and GRr.center()
        local bad = pp.Y < -400 or pp.Y > 5000 or (c and (pp - c).Magnitude > 700) or (hrp.Position - pp).Magnitude > 3000
        if bad then
            H.log(string.format("extra boss: %s is at a bad position (%.0f, %.0f, %.0f) - dropping it", foe.Name, pp.X, pp.Y, pp.Z))
            H.extraFoe, H.extraUntil, H.pin = nil, 0, nil
            if GRr and GRr.bad then GRr.bad[foe] = os.clock() + 60 end
            return false
        end
    end
    hsay("Boss: killing " .. foe.Name)
    State.Text = H.status
    if H.extraLogged ~= foe then H.extraLogged = foe; H.log(string.format("extra boss: pinning on %s (%d studs away)", foe.Name, (fr.Position - hrp.Position).Magnitude)) end
    H.extraB = H.extraB or {}
    if H.extraB.foe ~= foe then H.extraB = { foe = foe, arriveY = hrp.Position.Y } end
    H.pin = { part = fr, b = H.extraB, until_ = os.clock() + 1.0 }
    pcall(function()
        hrp.CFrame = CFrame.new(pinPos(H.extraB, fr)) * CFrame.Angles(0, 0, 0)
        hrp.AssemblyLinearVelocity = Vector3.zero
    end)
    pcall(function() Aim.part = fr end)
    pcall(equipWeapon)
    if __E.wantAttack then pcall(__E.wantAttack, false) end
    pcall(H.bossDmg)
    return true
end
-- boss ativo (porta de boss aberta, ou boss extra vivo): prioridade maxima, passa na frente de TUDO (so o Safe Mode fica por cima)
function H.bossWants()
    if H.greatWants and H.greatWants() then return true end
    if not (Config.HalBoss or Config.HalGreat) then return false end
    if H.boss and os.clock() - H.boss.t < (H.boss.door and H.boss.door.Parent and H.boss.door:GetAttribute("BOSS_ACTIVE_SERVER") and 900 or 240) then return true end
    return os.clock() < (H.extraUntil or 0)
end
function H.wants()
    do
        -- evento acabou de comecar: comeca a procurar as portas na hora (mesmo que esteja descansando de uma volta anterior)
        local act = H.active()
        if act and not H.wasActive then H.restUntil, H.tour = 0, nil end
        H.wasActive = act
    end
    if H.greatWants and H.greatWants() then return true end
    if (Config.HalBoss or Config.HalGreat) and os.clock() < (H.extraUntil or 0) then return true end
    if H.boss and Config.HalBoss and os.clock() - H.boss.t < (H.boss.door and H.boss.door.Parent and H.boss.door:GetAttribute("BOSS_ACTIVE_SERVER") and 900 or 240) then return true end
    if not Config.HalEvent then return false end
    if H.door then return true end
    if not H.active() then return false end
    for _, d in ipairs(H.doors()) do if doorReady(d) then return true end end
    -- procurando portas pelas ilhas (as aboboras so esperam depois que uma volta inteira nao achou nada: ver H.restUntil em H.step)
    return os.clock() >= (H.restUntil or 0)
end
-- ---- Auto Pumpkin Boss (Great Pumpkin / "Dapper Jack"): faz o ritual na bruxa, entra no portal da cratera e mata o boss ----
-- ritual: Remotes.DapperJackRitual:InvokeServer("Status"|"Summon"); portal = atributo "DapperJackGateway" (Vector3) no workspace;
-- entrar = HalloweenEvent:FireServer("DapperJackArenaEnter"); arena = workspace.Map.DapperJackArena (atributo ArenaCenter, raio 360)
local GR = {}
H.great = GR
local CollS = game:GetService("CollectionService")
function GR.rf()
    local r = ReplicatedStorage:FindFirstChild("Remotes")
    local f = r and r:FindFirstChild("DapperJackRitual")
    return (f and f:IsA("RemoteFunction")) and f or nil
end
function GR.center()
    local m = workspace:FindFirstChild("Map")
    m = m and m:FindFirstChild("DapperJackArena")
    local c = m and m:GetAttribute("ArenaCenter")
    if typeof(c) == "Vector3" then return c end
    -- v71: sem o atributo, usa o centro do modelo da arena (antes nunca "entrava" e ficava parado em "going into the portal")
    if m then
        local okp, pv = pcall(function() return m:GetPivot().Position end)
        if okp and typeof(pv) == "Vector3" then return pv end
    end
    return nil
end
function GR.inside(hrp)
    local c = GR.center()
    if not c then return false, nil end
    local d = hrp.Position - c
    return Vector3.new(d.X, 0, d.Z).Magnitude <= 360 and math.abs(d.Y) <= 420, c
end
function GR.gate()
    local g = workspace:GetAttribute("DapperJackGateway")
    if typeof(g) == "Vector3" and g.Y > 2 and g.Y < 3000 then return g end
    return nil
end
function GR.cauldron()
    -- v71: ignora posicoes debaixo da agua / fora do mapa (NPC ainda nao carregado ia parar la e o hub voava para baixo da agua)
    local function sane(p) return p and p.Y > 2 and p.Y < 1500 and math.abs(p.X) < 20000 and math.abs(p.Z) < 20000 end
    for _, v in ipairs(CollS:GetTagged("DapperJackCauldron")) do
        local ok, p = pcall(function() return v:IsA("BasePart") and v.Position or v:GetPivot().Position end)
        if ok and sane(p) then return p end
    end
    local n = workspace:FindFirstChild("NPCs")
    local w = n and n:FindFirstChild("Witch")
    if w then
        local ok, p = pcall(function() return w:GetPivot().Position end)
        if ok and sane(p) then return p end
    end
    return nil
end
-- consulta o estado do ritual (aberto / ingredientes) de tempos em tempos
task.spawn(function()
    while Alive do
        task.wait(5)
        if Config.HalGreat and not GR.polling then
            GR.polling = true
            pcall(function()
                local rf = GR.rf()
                if not rf then GR.can = false return end
                local ok, st = pcall(rf.InvokeServer, rf, "Status")
                if ok and type(st) == "table" then
                    local afford = true
                    for _, c in pairs(type(st.Costs) == "table" and st.Costs or {}) do
                        if type(c) == "table" and (tonumber(c.Have) or 0) < (tonumber(c.Amount) or 0) then afford = false end
                    end
                    local can = (st.Open and not st.Active and not st.Busy and afford) and true or false
                    local txt = string.format("open=%s active=%s busy=%s afford=%s", tostring(st.Open), tostring(st.Active), tostring(st.Busy), tostring(afford))
                    if GR.lastTxt ~= txt then GR.lastTxt = txt; H.log("great pumpkin ritual status: " .. txt) end
                    GR.can = can
                    GR.active = (st.Active or st.Busy) and true or false
                    GR.activeAt = os.clock()
                    GR.statusTxt = txt
                else
                    GR.can = false
                end
            end)
            GR.polling = false
        end
    end
end)
-- solta o personagem: cancela o voo, tira o "FarmHold" e limpa os alvos (ao desligar a funcao ou acabar o boss)
function H.release()
    H.pin, H.greatBusy, H.extraUntil, H.extraFoe = nil, 0, 0, nil
    pcall(function() __E.currentTween:Cancel() end)
    pcall(function()
        local _, hrp = getChar()
        local fh = hrp and hrp:FindFirstChild("FarmHold")
        if fh then fh:Destroy() end
    end)
    pcall(function() Aim.part = nil end)
end
-- doces que o Great Pumpkin larga no chao da cratera
GR.picked = setmetatable({}, { __mode = "k" })
GR.bad = setmetatable({}, { __mode = "k" })
function GR.pickup(hrp, center)
    if H.collectStep(hrp) then return true end
    if os.clock() - (GR.pAt or 0) > 1.5 then
        GR.pAt = os.clock()
        GR.pList = {}
        local root = workspace:FindFirstChild("Map")
        root = root and root:FindFirstChild("DapperJackArena") or workspace
        for _, o in ipairs(root:GetDescendants()) do
            if o:IsA("BasePart") and (GR.picked[o] or 0) < 4 and o.Name:lower():find("candy", 1, true)
                and not o:IsDescendantOf(Player.Character) and not o:FindFirstAncestor("Enemies")
                and (o.Position - center).Magnitude < 380 then
                GR.pList[#GR.pList + 1] = o
                if #GR.pList >= 40 then break end
            end
        end
    end
    local best, bd
    for _, o in ipairs(GR.pList or {}) do
        if o.Parent and (GR.picked[o] or 0) < 4 then
            local d = (o.Position - hrp.Position).Magnitude
            if not bd or d < bd then best, bd = o, d end
        end
    end
    if not best then return false end
    GR.picked[best] = (GR.picked[best] or 0) + 1
    pcall(function()
        hrp.CFrame = CFrame.new(best.Position + Vector3.new(0, 2, 0))
        if firetouchinterest then firetouchinterest(hrp, best, 0); firetouchinterest(hrp, best, 1) end
    end)
    task.wait(0.15)
    return true
end
function H.greatWants()
    if not Config.HalGreat then return false end
    if os.clock() < (H.greatBusy or 0) then return true end
    if GR.gate() then return GR.cool == nil or os.clock() >= GR.cool end
    return GR.can == true and (GR.cool == nil or os.clock() >= GR.cool)
end
function H.greatStep(hrp)
    if not Config.HalGreat then return false end
    local inside, center = GR.inside(hrp)
    if inside then
        -- dentro da cratera: so o boss importa
        H.greatBusy = os.clock() + 40
        GR.wasInside = true
        GR.enterAt = GR.enterAt or os.clock()
        local en = workspace:FindFirstChild("Enemies")
        local best, bs = nil, 0
        for _, e in ipairs(en and en:GetChildren() or {}) do
            local hum, root = aliveParts(e)
            if hum and root and (root.Position - center).Magnitude < 420 and (GR.bad[e] or 0) < os.clock() then
                local sc = e.Name:lower():find("dapper", 1, true) and 1e12 or hum.MaxHealth
                if sc > bs then best, bs = e, sc end
            end
        end
        if best then
            GR.lastFoe = os.clock()
            H.extraFoe, H.extraUntil = best, os.clock() + 3
            if GR.logged ~= best then GR.logged = best; H.log("great pumpkin: boss found: " .. best.Name) end
            if H.extraStep(hrp) then return true end
        end
        if GR.lastFoe and os.clock() - GR.lastFoe < 90 then
            -- boss morto: pega os doces que ele largou
            local okP, got = pcall(GR.pickup, hrp, center)
            if okP and got then
                hsay("Pumpkin boss: collecting the candy")
                State.Text = H.status
                return true
            end
        end
        if GR.lastFoe and os.clock() - GR.lastFoe > 4 and H.exitStep and H.exitStep(hrp) then
            return true      -- v79: boss morto e sem doces: vai para o portal de saida da arena
        end
        if os.clock() - (GR.lastFoe or GR.enterAt) > (GR.lastFoe and 30 or 120) then
            -- boss morto (ou nunca apareceu) e o jogo nao devolveu o jogador: volta para onde estava
            H.log("great pumpkin: no boss for 120 s, leaving the crater")
            if GR.home then pcall(function() hrp.CFrame = CFrame.new(GR.home + Vector3.new(0, 5, 0)) end) end
            GR.enterAt, GR.lastFoe, GR.cool, H.greatBusy = nil, nil, os.clock() + 20, 0
            return false
        end
        hsay("Pumpkin boss: in the crater, waiting for the boss")
        State.Text = H.status
        return true
    end
    GR.enterAt, GR.lastFoe = nil, nil
    if GR.wasInside then
        -- o jogo costuma tirar o jogador da cratera quando o boss morre: ainda da tempo de pegar os doces que ele largou
        GR.after = GR.after or os.clock()
        if os.clock() - GR.after < 45 then
            local okC, got = pcall(H.collectStep, hrp, 1500)
            if okC and got then
                H.greatBusy = os.clock() + 8
                return true
            end
            if os.clock() - GR.after < 6 then H.greatBusy = os.clock() + 3; return true end
        end
        GR.after = nil
        -- saiu da cratera (boss morto): solta o voo e espera um pouco antes de pensar em outro ritual
        GR.wasInside, GR.cool, GR.gateSince = false, os.clock() + 90, nil
        H.log("great pumpkin: left the crater, resting 90 s")
        H.release()
        return false
    end
    -- v71: ja mandou entrar no portal e o boss esta por perto (a checagem da arena falhou): luta mesmo assim
    if GR.enterTry and os.clock() - GR.enterTry < 90 then
        pcall(H.extraBoss, hrp)
        local ef = H.extraFoe
        local er = ef and ef.Parent and (ef:FindFirstChild("HumanoidRootPart") or ef:FindFirstChildWhichIsA("BasePart"))
        if er and (er.Position - hrp.Position).Magnitude < 800 then
            H.greatBusy = os.clock() + 40
            if H.extraStep(hrp) then return true end
        end
    end
    if GR.cool and os.clock() < GR.cool then return false end
    if not GR.home then GR.home = hrp.Position end
    local gw = GR.gate()
    -- o atributo do portal pode ficar velho depois do boss: so persegue se o ritual esta mesmo ativo (ou acabou de ser iniciado)
    if gw and not (GR.active or (GR.summonAt and os.clock() - GR.summonAt < 150)) then
        if GR.staleLogged ~= gw then GR.staleLogged = gw; H.log("great pumpkin: portal attribute present but no ritual active - ignoring it") end
        gw = nil
    end
    if gw then
        GR.gateSince = GR.gateSince or os.clock()
        if os.clock() - GR.gateSince > 75 then
            -- o portal nao existe mais (atributo velho): nao fica voando atras dele
            GR.gateSince, GR.cool = nil, os.clock() + 120
            H.log("great pumpkin: portal not reachable, giving up for 120 s")
            H.release()
            return false
        end
        H.greatBusy = os.clock() + 30
        hsay("Pumpkin boss: going into the crater portal")
        State.Text = H.status
        if (hrp.Position - gw).Magnitude > 6 then flyTo(CFrame.new(gw + Vector3.new(0, 3, 0))); return true end
        if os.clock() - (GR.tryAt or 0) > 1.2 then
            GR.tryAt = os.clock()
            GR.tries = (GR.tries or 0) + 1
            local f = workspace:FindFirstChild("DapperJackGateway")
            for _, d in ipairs(f and f:GetDescendants() or {}) do
                if d:IsA("ProximityPrompt") then pcall(function() d.HoldDuration = 0; fireproximityprompt(d) end) break end
            end
            local he = hremote()
            if he then pcall(function() he:FireServer("DapperJackArenaEnter") end) end
            GR.enterTry = os.clock()
            H.log("great pumpkin: enter try " .. GR.tries)
            if GR.tries > 25 then GR.tries, GR.cool, H.greatBusy = 0, os.clock() + 60, 0 end
        end
        return true
    end
    GR.tries, GR.gateSince = 0, nil
    -- ritual em andamento (a cratera abre uns 13 s depois do "Summon")
    if GR.summonAt and os.clock() - GR.summonAt < 40 then
        H.greatBusy = os.clock() + 5
        hsay("Pumpkin boss: the witch is brewing the curse")
        State.Text = H.status
        return true
    end
    if not GR.can then return false end
    local cp = GR.cauldron()
    if not cp then
        -- a bruxa fica na Middle Town (Mar 1) e so carrega quando o jogador chega perto: voa por la ate o caldeirao/bruxa aparecer
        local okS, sea = pcall(__E.getSea)
        if okS and sea and sea ~= 1 then
            hsay("Pumpkin boss: the witch is in Sea 1 (Middle Town)")
            GR.cool = os.clock() + 60
            return false
        end
        GR.tour = GR.tour or { Vector3.new(-1000, 40, 1700), Vector3.new(-1130, 40, 1717), Vector3.new(-839, 40, 1603), Vector3.new(-1043, 40, 1792), Vector3.new(-1250, 40, 1900), Vector3.new(-900, 40, 1950), Vector3.new(-1300, 40, 1550) }
        GR.ti = GR.ti or 1
        local goal = GR.tour[GR.ti]
        H.greatBusy = os.clock() + 30
        hsay(string.format("Pumpkin boss: flying to Middle Town to find the witch (%d/%d)", GR.ti, #GR.tour))
        State.Text = H.status
        if (hrp.Position - goal).Magnitude > 50 and os.clock() - (GR.spotAt or os.clock()) < 45 then
            GR.spotAt = GR.spotAt or os.clock()
            flyTo(CFrame.new(goal))
            return true
        end
        GR.dwell = GR.dwell or (os.clock() + 3)
        if os.clock() < GR.dwell then return true end
        GR.ti, GR.spotAt, GR.dwell = GR.ti % #GR.tour + 1, nil, nil
        return true
    end
    GR.ti, GR.spotAt, GR.dwell = nil, nil, nil
    H.greatBusy = os.clock() + 30
    hsay("Pumpkin boss: going to the witch")
    State.Text = H.status
    if (hrp.Position - cp).Magnitude > 10 then flyTo(CFrame.new(cp + Vector3.new(0, 4, 0))); return true end
    local rf = GR.rf()
    if not rf then GR.cool = os.clock() + 30 return false end
    local ok, res = pcall(rf.InvokeServer, rf, "Summon")
    H.log("great pumpkin: Summon -> " .. tostring(res))
    GR.can = false
    if ok and res == "Started" then
        GR.summonAt = os.clock()
        H.greatBusy = os.clock() + 40
    else
        GR.cool = os.clock() + 20
        H.greatBusy = 0
    end
    return true
end
-- minigame "BREAK FREE!" (o boss te prende): aperta ESPACO sem parar enquanto o aviso estiver na tela
-- cache de TextLabels (varrer o PlayerGui inteiro 5x por segundo travava/crashava o jogo)
local BF = { labels = {}, n = 0, hooked = false }
local function breakFreeShown()
    local pg = Player:FindFirstChild("PlayerGui")
    if not pg then return false end
    if not BF.hooked then
        BF.hooked = true
        local function add(d)
            if d:IsA("TextLabel") then BF.labels[d] = true end
        end
        for _, d in ipairs(pg:GetDescendants()) do add(d) end
        pg.DescendantAdded:Connect(add)
        pg.DescendantRemoving:Connect(function(d) BF.labels[d] = nil end)
    end
    for d in pairs(BF.labels) do
        if d.Parent and d.Text ~= "" and d.AbsoluteSize.X > 0 and d.Text:lower():find("break free", 1, true) and shown(d) then return true end
    end
    return false
end
task.spawn(function()
    while Alive do
        task.wait(0.35)
        if (Config.HalBoss or Config.HalEvent) and breakFreeShown() then
            H.log("minigame: BREAK FREE - pressing Space")
            local t0, chk = os.clock(), os.clock()
            while Alive and os.clock() - t0 < 15 do
                if VIM then
                    pcall(function() VIM:SendKeyEvent(true, Enum.KeyCode.Space, false, game) end)
                    task.wait(0.025)
                    pcall(function() VIM:SendKeyEvent(false, Enum.KeyCode.Space, false, game) end)
                end
                pcall(function()
                    local c = Player.Character
                    local hm = c and c:FindFirstChildOfClass("Humanoid")
                    if hm then hm.Jump = true end
                end)
                task.wait(0.025)
                if os.clock() - chk > 0.4 then
                    chk = os.clock()
                    if not breakFreeShown() then break end
                end
            end
        end
    end
end)
-- saiu das funcoes (ou o boss acabou) com o personagem dentro da arena do Hellfire: leva de volta para onde estava (senao outra farm voa "para sempre" ate o alvo)
task.spawn(function()
    while Alive do
        task.wait(1)
        local _, hrp = getChar()
        if hrp and H.homePos and arenaBox(hrp.Position) then
            local fighting = Config.HalBoss and H.boss and H.boss.stage == 1
            if not fighting then
                H.log("leaving the arena: going back to where we were")
                pcall(function() hrp.CFrame = CFrame.new(H.homePos + Vector3.new(0, 5, 0)); hrp.AssemblyLinearVelocity = Vector3.zero end)
                H.homePos = nil
            end
        end
    end
end)
-- mantem o personagem grudado em cima do boss entre um passo e outro (a cada frame)
game:GetService("RunService").Heartbeat:Connect(function()
    local pn = H.pin
    if not (Alive and pn and os.clock() < pn.until_ and pn.part and pn.part.Parent) then return end
    local _, hrp = getChar()
    if not hrp then return end
    -- alvo em posicao absurda (boss sumiu / parte foi pro vazio): larga o pin em vez de te levar junto
    local pp = pn.part.Position
    if pp.Y < -400 or pp.Y > 6000 or (hrp.Position - pp).Magnitude > 4000 then H.pin = nil; return end
    hrp.CFrame = CFrame.new(pinPos(pn.b, pn.part)) * CFrame.Angles(0, 0, 0)
    hrp.AssemblyLinearVelocity = Vector3.zero
end)
-- volta tudo ao normal depois de um boss (ou de um voo estranho): solta o voo, limpa porta/boss/alvos e, se estiver longe/no mar, volta pra terra
function H.recover(home, why)
    H.log("recover: " .. tostring(why))
    getgenv().MoonBossLock = 0
    if H.boss and H.boss.door then pcall(H.blockDoor, H.boss.door, 3600, true) end
    pcall(H.lockBossDoors)
    H.release()
    H.boss, H.pin, H.extraFoe, H.extraUntil, H.bossOver = nil, nil, nil, 0, nil
    H.door, H.info, H.finished, H.handled, H.snap = nil, nil, false, false, nil
    H.restUntil, H.tour = 0, nil
    local _, hr = getChar()
    if hr then
        pcall(function() if __E.Fly then __E.Fly.goal = nil end end)
        if home and ((hr.Position - home).Magnitude > 900 or hr.Position.Y < home.Y - 60) then
            H.log("recover: going back to land near the door")
            hr.CFrame = CFrame.new(home + Vector3.new(0, 5, 0))
            hr.AssemblyLinearVelocity = Vector3.zero
        end
    end
    H.recoverUntil = os.clock() + 2.5
end
-- v79: depois de matar o boss o jogo cria um portal de saida no meio da arena; o hub ficava "esperando o boss" (e a fisica o empurrava para cima).
-- Procura partes/prompts de portal perto, vai ate o mais proximo e encosta/ativa. Registra os nomes achados no log (uma vez) para ajuste.
function H.exitStep(hrp)
    if os.clock() - (H.exitAt or 0) < 0.4 then return false end
    H.exitAt = os.clock()
    pcall(function() hrp.AssemblyLinearVelocity = Vector3.zero end)
    pcall(function() local fh = hrp:FindFirstChild("FarmHold"); if fh then fh:Destroy() end end)
    local best, bd, names = nil, math.huge, {}
    pcall(function()
        for _, part in ipairs(workspace:GetPartBoundsInRadius(hrp.Position, 700)) do
            if not part:IsDescendantOf(Player.Character) and not part:FindFirstAncestor("Enemies") then
                local nm = (part.Name .. " " .. (part.Parent and part.Parent.Name or "")):lower()
                local pp = part:FindFirstChildWhichIsA("ProximityPrompt")
                local isP = nm:find("portal", 1, true) or nm:find("exit", 1, true) or nm:find("vortex", 1, true) or nm:find("return", 1, true) or nm:find("comm", 1, true)
                if (isP or pp) and not nm:find("door", 1, true) then
                    names[#names + 1] = part.Name
                    local d = (part.Position - hrp.Position).Magnitude
                    if d < bd then best, bd = part, d end
                end
            end
        end
    end)
    if not H.exitLogged and #names > 0 then
        H.exitLogged = true
        H.log("boss exit: candidates: " .. table.concat(names, ", "):sub(1, 300))
    end
    if not best then return false end
    hsay("Boss dead: going into the exit portal")
    State.Text = H.status
    pcall(function() hrp.CFrame = CFrame.new(best.Position + Vector3.new(0, 3, 0)) end)
    pcall(function()
        if firetouchinterest then firetouchinterest(hrp, best, 0); firetouchinterest(hrp, best, 1) end
        local pp = best:FindFirstChildWhichIsA("ProximityPrompt")
        if pp and fireproximityprompt then pp.HoldDuration = 0; fireproximityprompt(pp) end
    end)
    return true
end
function H.bossStep(hrp)
    local b = H.boss
    if not b or not Config.HalBoss then return false end
    local age = os.clock() - b.t
    local active = b.door and b.door.Parent and b.door:GetAttribute("BOSS_ACTIVE_SERVER")
    if age > (active and 900 or 240) or not b.door or not b.door.Parent then H.bossDone = b.door; H.boss = nil; return false end
    pcall(H.noteBossDoors)
    local tag = (b.ev == "Hellfire Boss") and "Hellfire" or "Werewolf"
    -- morreu no dominio do boss (personagem novo, ou de volta perto de casa): recomeca do portal com tudo limpo
    if b.stage == 1 then
        local ch = Player.Character
        b.char = b.char or ch
        local home = b.home and (hrp.Position - b.home).Magnitude < 300 and os.clock() - (b.inAt or 0) > 6
        if ch ~= b.char or home then
            H.log("boss: died / left the arena - going back through the portal")
            b.stage, b.char = 0, nil
            b.reached, b.near, b.touch, b.poke, b.k, b.lastPos = nil, nil, nil, nil, nil, nil
            b.arriveY, b.pinLogged, b.lastFoe, b.inAt = nil, nil, nil, nil
            b.t = os.clock() - 30        -- o portal ja esta aberto: nao espera a cutscene de novo
            H.pin = nil
            pcall(function() Aim.part = nil end)
            return true
        end
    end
    b.snap = b.snap or enemySet()
    local foe = (b.stage == 0) and bossFoe(hrp) or bossFoe2(hrp, b.snap)
    H.logEnemies(hrp, "boss stage " .. b.stage)
    if b.stage == 0 then
        -- ainda na cidade: vai ate o portal e espera o teleporte
        local pos = bossPos(b.door)
        if not pos then H.boss = nil; return false end
        -- v145: "casa" = perto da porta (terra firme). Antes era a posicao do personagem no 1o passo (podia ser no ar sobre o mar):
        -- depois do boss o script te levava pra la = "voa pra agua e nao volta mais"
        b.doorHome = b.doorHome or (pos + Vector3.new(0, 6, 0))
        b.home = b.home or (((hrp.Position - pos).Magnitude < 150) and hrp.Position or b.doorHome)
        if not b.homeSet then b.homeSet = true; H.homePos = b.home end
        -- o portal teleporta de uma vez: um salto grande de posicao (ou o evento BossTeleportSound) = ja estamos no dominio do boss
        local jumped = b.lastPos and (hrp.Position - b.lastPos).Magnitude > 150 and (b.lastPos - pos).Magnitude < 60
        b.lastPos = hrp.Position
        if not jumped and arenaBox(hrp.Position) then jumped = true; H.log("boss: inside the Hellfire arena") end
        if jumped then H.log("boss: teleport detected (jump)") end
        -- um inimigo novo com nome de boss apareceu (nao existia quando a porta abriu) = o boss nasceu e ja estamos no dominio dele
        if not jumped and b.snap and age > 3 then
            local en0 = workspace:FindFirstChild("Enemies")
            for _, e in ipairs(en0 and en0:GetChildren() or {}) do
                if not b.snap[e] then
                    local nm = e.Name:lower()
                    if nm:find("werewolf", 1, true) or nm:find("hell", 1, true) or nm:find("inferno", 1, true) or nm:find("unbound", 1, true) then
                        local hm, rt = aliveParts(e)
                        if hm and rt and (rt.Position - hrp.Position).Magnitude < 2500 then jumped = true; H.log("boss: new boss enemy detected: " .. e.Name) break end
                    end
                end
            end
        end
        if jumped or (hrp.Position - b.home).Magnitude > 600 or hrp.Position.Y < -1500 or (foe and (foe.Name:lower():find("werewolf", 1, true) or foe.Name:lower():find("hell", 1, true)) and (foe:GetPivot().Position - hrp.Position).Magnitude < 250) then
            b.stage, b.inAt = 1, os.clock()
            b.char = Player.Character
            return true
        end
        hsay(string.format("%s boss: going into the portal", tag))
        State.Text = H.status
        if not b.logged then
            b.logged = true
            local at = {}
            for k, v in pairs(b.door:GetAttributes()) do at[#at + 1] = tostring(k) .. "=" .. tostring(v) end
            H.log("boss door attributes: " .. table.concat(at, ", ") .. " | portal pos (" .. math.floor(pos.X) .. "," .. math.floor(pos.Y) .. "," .. math.floor(pos.Z) .. ")")
        end
        -- o portal so aparece depois da cutscene (o servidor marca BOSS_ACTIVE_SERVER na porta): espera perto, sem encostar antes
        local ready = b.door:GetAttribute("BOSS_ACTIVE_SERVER") or age > 25
        if not ready then
            if (hrp.Position - pos).Magnitude > 25 then flyTo(CFrame.new(pos + Vector3.new(0, 6, 0))) end
            return true
        end
        if (hrp.Position - pos).Magnitude > 3 and not b.reached then flyTo(CFrame.new(pos)); return true end
        b.reached = true
        b.near = b.near or os.clock()
        -- encostar no portal teleporta: força o toque na parte do portal/porta
        if os.clock() - (b.touch or 0) > 1.5 then
            b.touch = os.clock()
            local pp = b.door:FindFirstChild("Part")
            if pp and pp:IsA("BasePart") and firetouchinterest then
                pcall(function() firetouchinterest(hrp, pp, 0); task.wait(); firetouchinterest(hrp, pp, 1) end)
            end
            -- o portal que o servidor ve pode ser outra parte da porta: encosta em todas (ate 40) e em partes "comm"/"portal" por perto
            if firetouchinterest then
                local n = 0
                pcall(function()
                    for _, x in ipairs(b.door:GetDescendants()) do
                        if x:IsA("BasePart") and x ~= pp then
                            firetouchinterest(hrp, x, 0); firetouchinterest(hrp, x, 1)
                            n += 1
                            if n >= 40 then break end
                        end
                    end
                    for _, x in ipairs(workspace:GetChildren()) do
                        local nm = x.Name:lower()
                        if (nm == "comm" or nm:find("portal", 1, true)) and x:IsA("Model") or (nm == "comm" and x:IsA("BasePart")) then
                            local pt = x:IsA("BasePart") and x or x:FindFirstChildWhichIsA("BasePart", true)
                            if pt and (pt.Position - pos).Magnitude < 60 then firetouchinterest(hrp, pt, 0); firetouchinterest(hrp, pt, 1) end
                        end
                    end
                end)
            end
            -- balanca em volta do centro do portal para garantir contato fisico (frente/tras/cima)
            b.k = (b.k or 0) + 1
            local offs = { Vector3.new(0, 0, 0), Vector3.new(0, 2, 0), Vector3.new(2, 0, 0), Vector3.new(-2, 0, 0), Vector3.new(0, 0, 2), Vector3.new(0, 0, -2) }
            pcall(function() hrp.CFrame = CFrame.new(pos + offs[(b.k - 1) % #offs + 1]); hrp.AssemblyLinearVelocity = Vector3.zero end)
        end
        local hf = ReplicatedStorage:FindFirstChild("Remotes") and ReplicatedStorage.Remotes:FindFirstChild("HalloweenFunction")
        if os.clock() - b.near > 1.2 and os.clock() - (b.poke or 0) > 2.5 then
            b.poke = os.clock()
            local prompt = doorParts(b.door)
            pcall(function() if prompt then fireproximityprompt(prompt) end end)
            if hf and hf:IsA("RemoteFunction") then task.spawn(function() pcall(function() hf:InvokeServer(b.door) end) end) end
        end
        if age > 90 and not foe and not active then H.boss = nil; return false end
        return true
    end
    -- dentro do dominio do boss
    -- v66: o voo ate o portal (stage 0) deixava o destino antigo no motor de voo: dentro da arena ele continuava puxando o
    -- personagem para a ilha de fora ("fica tentando dar tp pra outra ilha enquanto mata o boss"). Limpa o destino e trava novos voos.
    pcall(function() if __E.Fly then __E.Fly.goal = nil end end)
    pcall(function() __E.currentTween.PlaybackState = Enum.PlaybackState.Completed end)
    getgenv().MoonBossLock = os.clock() + 2
    if foe then
        b.lastFoe = os.clock()
        hsay(string.format("%s boss: killing %s", tag, foe.Name))
        State.Text = H.status
        local fr = foe:FindFirstChild("HumanoidRootPart") or foe:FindFirstChildWhichIsA("BasePart")
        if fr then
            -- fica grudado em cima do boss (teleporte a cada passo e a cada frame): nao depende de voar ate ele nem de ele ficar parado
            if not b.pinLogged then b.pinLogged = true; H.log(string.format("boss: pinning on %s (%d studs away)", foe.Name, (fr.Position - hrp.Position).Magnitude)) end
            b.arriveY = b.arriveY or hrp.Position.Y
            H.pin = { part = fr, b = b, until_ = os.clock() + 1.0 }
            pcall(function()
                hrp.CFrame = CFrame.new(pinPos(b, fr)) * CFrame.Angles(0, 0, 0)
                hrp.AssemblyLinearVelocity = Vector3.zero
            end)
            hsay(string.format("%s boss: %s | boss y=%d me y=%d dist=%d", tag, foe.Name, fr.Position.Y, hrp.Position.Y, (fr.Position - hrp.Position).Magnitude))
            State.Text = H.status
            pcall(function() Aim.part = fr end)
            pcall(equipWeapon)
            local wa = __E.wantAttack
            if wa then pcall(wa, false) end
            if not wa then getgenv().MoonBossLock = 0; fightEnemy(foe, { foe.Name }, false) end
            pcall(H.bossDmg)
        else
            getgenv().MoonBossLock = 0
            fightEnemy(foe, { foe.Name }, false)
        end
        return true
    end
    H.pin = nil
    -- sem inimigo: acabou (ou ainda esta carregando)
    local idle = os.clock() - (b.lastFoe or b.inAt)
    if b.lastFoe and idle > 3 and idle < 25 then
        pcall(function() Aim.part = nil end)
        if H.exitStep(hrp) then return true end
    else
        H.exitLogged = nil
    end
    -- v83: boss morto ha mais de 20 s e o portal de saida nao funcionou: nao fica esperando ate 240 s, volta para a terra
    if (idle < 45 or (active and idle < 240)) and not H.bossOver and not (b.lastFoe and idle > 20) then
        hsay(string.format("%s boss: waiting for the boss", tag))
        State.Text = H.status
        return true
    end
    H.n += 1
    hsay(string.format("%s boss done (%d done)", tag, H.n))
    -- se o jogo nao devolveu o jogador, volta para onde estava (perto da porta, em terra)
    do
        local back = b.doorHome or b.home or H.safePos
        if back and (hrp.Position - back).Magnitude > 600 then
            task.wait(4)
            local _, h2 = getChar()
            if h2 and (h2.Position - back).Magnitude > 600 then pcall(function() h2.CFrame = CFrame.new(back + Vector3.new(0, 5, 0)) end) end
        end
        H.homePos = nil
        H.noCollectUntil = os.clock() + 25      -- nada de teleporte para doces/peixes logo depois do boss
        pcall(function() __E.currentTween:Cancel() end)
        pcall(function() if __E.Fly then __E.Fly.goal = nil end end)
    end
    H.bossOver = nil
    H.bossDone = b.door
    H.bossHome = b.doorHome
    H.boss = nil
    getgenv().MoonBossLock = 0
    return true
end

-- vigia: se o Halloween Event esta no controle, nao tem porta/boss/alvo e mesmo assim o personagem anda >1200 studs em 8 s, e um voo estranho
task.spawn(function()
    local hist = {}
    while Alive do
        task.wait(1)
        pcall(function()
            if not (Config.HalEvent or Config.HalBoss or Config.HalGreat) then hist = {}; return end
            local _, hr = getChar()
            if not hr then hist = {}; return end
            local now = os.clock()
            hist[#hist + 1] = { now, hr.Position }
            while #hist > 0 and now - hist[1][1] > 8.5 do table.remove(hist, 1) end
            local own = Core and Core.owner
            local busy = H.door or H.boss or (H.extraUntil or 0) > now or (H.greatBusy or 0) > now or H.tour or (H.recoverUntil or 0) > now
            if own == "Halloween Event" and not busy and #hist >= 8 then
                local d = (hr.Position - hist[1][2]).Magnitude
                if d > 1200 then
                    H.log(string.format("watchdog: unexpected long flight (%.0f studs in 8 s) - resetting", d))
                    H.recover(nil, "watchdog")
                    hist = {}
                end
            end
        end)
    end
end)
-- v83: vigia de "preso": Halloween no controle, sem porta/boss/alvo ativo e o personagem parado (menos de 6 studs) por 70 s -> recupera tudo
task.spawn(function()
    local ref, refAt = nil, os.clock()
    while Alive do
        task.wait(2)
        pcall(function()
            if not (Config.HalEvent or Config.HalBoss or Config.HalGreat) then ref = nil; return end
            local _, hr = getChar()
            if not hr then ref = nil; return end
            local now = os.clock()
            if not ref or (hr.Position - ref).Magnitude > 6 then ref, refAt = hr.Position, now; return end
            local own = Core and Core.owner
            local inDoorScene = H.door and H.info
            if own == "Halloween Event" and not inDoorScene and not H.boss and (H.greatBusy or 0) < now and (H.extraUntil or 0) < now and now - refAt > 70 then
                H.log("watchdog: stuck for 70 s without a door scene - recovering")
                H.recover(H.safePos, "stuck")
                ref, refAt = nil, now
            end
        end)
    end
end)
-- ---- clique automatico em qualquer dialogo de porta (primeira opcao que nao seja "Nevermind") ----
local NOCLICK = { ["Tarot"] = true, ["Mystery Hall"] = true, ["Don't Be Greedy"] = true, ["Gravedigger"] = true, ["Sweet Ride"] = true,
    ["One Free Roll"] = true, ["Zer0 Slap"] = true, ["Magma Recipe"] = true }
local function firstOption()
    local pg = Player:FindFirstChild("PlayerGui")
    if not pg then return nil end
    local cancel
    for _, d in ipairs(H.gui(pg)) do
        if (d:IsA("TextLabel") or d:IsA("TextButton")) and d.AbsoluteSize.X > 0 then
            local t = d.Text:lower()
            if (t:find("nevermind", 1, true) or t:find("never mind", 1, true)) and shown(d) then cancel = d; break end
        end
    end
    if not cancel then return nil end
    local function hasText(c)
        if (c:IsA("TextLabel") or c:IsA("TextButton")) and c.Text ~= "" and not c.Text:lower():find("never", 1, true) then return true end
        for _, x in ipairs(c:GetDescendants()) do
            if (x:IsA("TextLabel") or x:IsA("TextButton")) and x.Text ~= "" and not x.Text:lower():find("never", 1, true) then return true end
        end
        return false
    end
    local function clickable(c)
        if c:IsA("GuiButton") then return true end
        for _, x in ipairs(c:GetDescendants()) do if x:IsA("GuiButton") then return true end end
        return false
    end
    local row, cont = cancel, cancel.Parent
    for _ = 1, 6 do
        if not cont or cont == pg then break end
        local others = {}
        for _, c in ipairs(cont:GetChildren()) do
            if c ~= row and c:IsA("GuiObject") and c.Visible and c.AbsoluteSize.X > 0 and hasText(c) and clickable(c) then others[#others + 1] = c end
        end
        if #others >= 1 then
            table.sort(others, function(a, b) return a.AbsolutePosition.Y < b.AbsolutePosition.Y end)
            return others[1]
        end
        row, cont = cont, cont.Parent
    end
    return nil
end
task.spawn(function()
    local lastClick, n, nDoor = 0, 0, nil
    while Alive do
        task.wait(0.25)
        local door, info = H.door, H.info
        if Config.HalEvent and door and info and not H.finished then
            if nDoor ~= door then nDoor, n = door, 0 end
            local ev = info.Event
            if not (ev and NOCLICK[ev]) and not (info.Boss == true) and n < 6 and os.clock() - lastClick > 0.8 and dlgTry(nil) then
                lastClick = os.clock(); n += 1
                H.clickedDoor = door
            elseif not (ev and NOCLICK[ev]) and not (info.Boss == true) and n < 3 and os.clock() - lastClick > 1.2 then
                local opt = firstOption()
                if opt then
                    lastClick = os.clock(); n += 1
                    H.clickedDoor = door
                    H.log("dialogue: clicking first option (" .. tostring(ev) .. ")")
                    clickGui(opt)
                end
            end
        end
    end
end)
-- ---- peixes/itens do rip_return (Zer0 Slap): o servidor cria objetos "Candyfish" depois do Trick or Treat ----
H.fish = setmetatable({}, { __mode = "k" })
task.spawn(function()
    workspace.DescendantAdded:Connect(function(d)
        if not Alive then return end
        local n = d.Name:lower()
        if (d:IsA("BasePart") or d:IsA("Model")) and (n:find("fish", 1, true) or (n:find("candy", 1, true) and os.clock() < (H.fishUntil or 0))) and os.clock() < (H.fishUntil or 0) + 30 then
            H.fish[d] = { t = os.clock(), n = 0 }
            H.log("item spawned: " .. d:GetFullName() .. " [" .. d.ClassName .. "]")
        end
    end)
end)
function H.fishStep(hrp)
    local best, bd
    for inst, rec in pairs(H.fish) do
        if inst.Parent and rec.n < 4 and os.clock() - rec.t < 120 then
            local ok, pos = pcall(function() return inst:IsA("BasePart") and inst.Position or inst:GetPivot().Position end)
            if ok and pos then
                local d = (pos - hrp.Position).Magnitude
                if d < 600 and (not bd or d < bd) then best, bd = { inst = inst, rec = rec, pos = pos }, d end
            end
        else H.fish[inst] = nil end
    end
    if not best then return false end
    hsay("Collecting dropped fish")
    State.Text = H.status
    best.rec.n += 1
    pcall(function() hrp.CFrame = CFrame.new(best.pos + Vector3.new(0, 2, 0)) end)
    task.wait(0.15)
    pcall(function()
        for _, x in ipairs(best.inst:GetDescendants()) do
            if x:IsA("ProximityPrompt") and fireproximityprompt then fireproximityprompt(x)
            elseif x:IsA("ClickDetector") and fireclickdetector then fireclickdetector(x) end
        end
        if best.inst:IsA("BasePart") and firetouchinterest then firetouchinterest(hrp, best.inst, 0); firetouchinterest(hrp, best.inst, 1)
        else
            local pt = best.inst:FindFirstChildWhichIsA("BasePart", true)
            if pt and firetouchinterest then firetouchinterest(hrp, pt, 0); firetouchinterest(hrp, pt, 1) end
        end
    end)
    task.wait(0.5)
    return true
end
-- ---- coleta de itens que caem (CandySpill: pecas "Candy_N" e baus "Chest_tipo_N" em pastas com a tag HalloweenCandySpill) ----
local CS = game:GetService("CollectionService")
H.tried = setmetatable({}, { __mode = "k" })
function H.collectStep(hrp, maxD)
    local best
    for _, f in ipairs(CS:GetTagged("HalloweenCandySpill")) do
        if f.Parent then
            local owner = f:GetAttribute("SpillOwner")
            if owner == nil or owner == Player.UserId then
                local tr = H.tried[f]
                if not tr then tr = {}; H.tried[f] = tr end
                for name, v in pairs(f:GetAttributes()) do
                    if type(name) == "string" and (name:sub(1, 6) == "Candy_" or name:sub(1, 6) == "Chest_") and typeof(v) == "Vector3" then
                        local rec = tr[name]
                        if not rec or (rec.n < 5 and os.clock() - rec.t > 1.3) then
                            local d = (v - hrp.Position).Magnitude
                            if d < (maxD or 400) and (not best or d < best.d) then best = { f = f, name = name, pos = v, d = d } end
                        end
                    end
                end
            end
        end
    end
    if not best then return false end
    local tr = H.tried[best.f]
    local rec = tr[best.name] or { n = 0, t = 0 }
    tr[best.name] = rec
    hsay("Collecting dropped items")
    State.Text = H.status
    if best.d > 120 and rec.n == 0 then flyTo(CFrame.new(best.pos + Vector3.new(0, 3, 0))); return true end
    rec.n += 1; rec.t = os.clock()
    hrp.CFrame = CFrame.new(best.pos + Vector3.new(0, 2, 0))
    -- o proprio jogo coleta ao chegar a 7 studs; se a peca continuar la depois de um tempo, manda o pedido direto
    task.delay(1, function()
        local he = hremote()
        if he and best.f.Parent and best.f:GetAttribute(best.name) ~= nil then
            local id = tonumber(best.name:match("(%d+)$"))
            if id then pcall(function() he:FireServer("CandySpillClaim", best.f.Name, id) end) end
        end
    end)
    return true
end
function H.step()
    local char, hrp = getChar()
    if not (char and hrp) then return false end
    -- v83: ultima posicao em terra fora de arena/dominio de boss (para voltar se o jogo nao devolver o jogador)
    if not H.boss and not GR.wasInside and hrp.Position.Y > 5 and os.clock() > (H.recoverUntil or 0) then H.safePos = hrp.Position end
    State.Mode = "Halloween Event"
    -- boss acabou: a porta do boss nao "termina" como as outras (ficava esperando ate estourar o tempo e o Auto Halloween Event nao abria mais portas)
    if H.bossDone then
        H.blockDoor(H.bossDone, 3600, true)
        pcall(H.lockBossDoors)
        H.greatBusy = 0
        local home = H.bossHome
        H.bossDone, H.bossHome = nil, nil
        H.recover(home, "boss finished")
        H.bossRest = os.clock() + 10      -- v71: espera ~10 s antes de ir atras de outra porta
    end
    -- 2,5 s parado logo depois do boss: nenhuma outra funcao puxa o personagem enquanto o jogo devolve ele ao mapa
    if os.clock() < (H.recoverUntil or 0) then
        hsay("Boss finished: getting back to the event")
        State.Text = H.status
        return true
    end
    if H.boss and Config.HalBoss then
        if H.bossStep(hrp) then return true end
    end
    if Config.HalGreat and H.greatStep(hrp) then return true end
    if (Config.HalBoss or Config.HalGreat) and H.extraBoss(hrp) and H.extraStep(hrp) then return true end
    if not Config.HalEvent then return false end
    if os.clock() >= (H.noCollectUntil or 0) then
        if H.collectStep(hrp) then return true end
        if H.fishStep(hrp) then return true end
    end
    -- ---- porta em andamento ----
    local door = H.door
    if door then
        if not door.Parent then give_up("door gone", 30); return true end
        local prompt, dpos = doorParts(door)
        if not dpos then give_up("door has no position", 60); return true end
        if not H.info then
            -- ainda nao abriu: chega perto e aperta o "E"
            hsay(string.format("Going to a door (%d done)", H.n))
            State.Text = H.status
            if (hrp.Position - dpos).Magnitude > 7 then flyTo(CFrame.new(dpos + Vector3.new(0, 3, 0))); return true end
            if os.clock() - H.doorAt > 20 then
                -- v71: porta que nao abre: cada falha bloqueia por mais tempo (inclusive por posicao) e o hub troca para outra porta
                H.fail = H.fail or {}
                local fk = math.floor(dpos.X / 15) .. "," .. math.floor(dpos.Z / 15)
                H.fail[fk] = (H.fail[fk] or 0) + 1
                local secs = 150 * H.fail[fk]
                pcall(H.blockDoor, door, secs)
                give_up("door did not open (try " .. H.fail[fk] .. ")", secs)
                return true
            end
            if os.clock() - H.pressAt > 0.6 then
                H.pressAt = os.clock()
                pcall(function() if prompt then fireproximityprompt(prompt) end end)
                -- abre direto pelo servidor (pula a espera de 1,2 s do "toque" do cliente)
                local hf = ReplicatedStorage:FindFirstChild("Remotes") and ReplicatedStorage.Remotes:FindFirstChild("HalloweenFunction")
                if hf and hf:IsA("RemoteFunction") and os.clock() - (H.invAt or 0) > 1.0 then
                    H.invAt = os.clock()
                    task.spawn(function() pcall(function() hf:InvokeServer(door) end) end)
                end
            end
            return true
        end
        -- ---- cena em andamento ----
        do
            local inf = H.info
            if inf and (inf.Boss == true or inf.Event == "Boss Fight" or inf.Event == "Hellfire Boss") and not Config.HalBoss then
                -- porta de boss com "Auto Kill Halloween Bosses" desligado: sai de perto para o portal nao te levar ao reino do boss
                if (hrp.Position - dpos).Magnitude < 110 then
                    hsay("Boss door, Auto Kill Halloween Bosses is off: staying away from the portal")
                    State.Text = H.status
                    flyTo(CFrame.new(dpos + Vector3.new(0, 50, 110)))
                    return true
                end
                give_up("boss door (Auto Kill Halloween Bosses is off)", 400)
                return true
            end
        end
        if not H.handled then
            H.handled = true
            local info = H.info
            task.spawn(function() pcall(H.handle, door, info) end)
        end
        if H.finished then
            H.n += 1
            hsay(string.format("Door done: %s (%d done)", H.last, H.n))
            H.bl[door] = os.clock() + 20
            H.door, H.info, H.finished, H.handled, H.snap = nil, nil, false, false, nil
            task.spawn(closeDlg)
            return true
        end
        if os.clock() - (H.openedAt or os.clock()) > ((H.last == "Mystery Hall" or H.last == "Tarot") and 240 or 130) then give_up("scene timed out (" .. H.last .. ")", 150); return true end
        State.Text = H.status
        if hrp.Position.Y < dpos.Y - 12 then hrp.CFrame = CFrame.new(dpos + Vector3.new(0, 6, 0)) end   -- nunca fica debaixo da agua
        local foe, deepFoe = newFoe(hrp, dpos)
        if foe then
            H.deepSince = nil
            hsay("Killing " .. foe.Name .. " (" .. H.last .. ")")
            State.Text = H.status
            fightEnemy(foe, { foe.Name }, false)
            return true
        end
        if deepFoe then
            -- inimigo ainda debaixo da agua: fica em cima, perto da porta, e espera ele subir (so mergulha depois de 35 s)
            if H.deepDoor ~= door or not H.deepSince then H.deepDoor, H.deepSince = door, os.clock() end
            if os.clock() - H.deepSince < 35 then
                hsay("Waiting for " .. deepFoe.Name .. " to come up (" .. H.last .. ")")
                State.Text = H.status
                if (hrp.Position - (dpos + Vector3.new(0, 4, 0))).Magnitude > 8 then flyTo(CFrame.new(dpos + Vector3.new(0, 4, 0))) end
                return true
            end
            fightEnemy(deepFoe, { deepFoe.Name }, false)
            return true
        end
        hsay("Scene: " .. H.last)
        State.Text = H.status
        if (hrp.Position - dpos).Magnitude > 40 and os.clock() >= (H.holdUntil or 0) then flyTo(CFrame.new(dpos + Vector3.new(0, 3, 0))) end
        return true
    end
    -- ---- escolher a proxima porta ----
    if os.clock() < (H.bossRest or 0) then
        hsay(string.format("Boss finished: waiting %d s before the next door", math.ceil(H.bossRest - os.clock())))
        State.Text = H.status
        return true
    end
    local best, bd
    for _, d in ipairs(H.doors()) do
        if doorReady(d) then
            local _, pos = doorParts(d)
            local dist = (pos - hrp.Position).Magnitude
            if not bd or dist < bd then best, bd = d, dist end
        end
    end
    if not best then
        local n = #H.doors()
        if not H.active() then
            hsay(string.format("Waiting for the event (starts at every XX:00) - %d done", H.n))
            State.Text = H.status
            H.tour = nil
            return false
        end
        -- evento ativo mas nenhuma porta pronta carregada: as portas ficam espalhadas pelo mapa e so carregam perto,
        -- entao visita as ilhas uma a uma (igual ao Chest Farm) ate achar uma
        if os.clock() >= (H.restUntil or 0) then
            if not H.tour then H.tour, H.tourI, H.tourAt, H.dwell = AFL.chestTourBuild(hrp.Position), 1, os.clock(), nil end
            local tgt = H.tour[H.tourI]
            if tgt then
                hsay(string.format("Looking for doors: island %d/%d (%d doors known, %d done)", H.tourI, #H.tour, n, H.n))
                State.Text = H.status
                local goal = tgt + Vector3.new(0, 90, 0)
                if (hrp.Position - goal).Magnitude > 60 and os.clock() - H.tourAt < 40 then flyTo(CFrame.new(goal)); return true end
                H.dwell = H.dwell or (os.clock() + 1.5)
                if os.clock() < H.dwell then return true end
                H.tourI, H.tourAt, H.dwell = H.tourI + 1, os.clock(), nil
                return true
            end
            -- volta completa sem achar porta: com o Break Pumpkins ligado as aboboras ganham 150 s antes de procurar de novo
            H.tour, H.restUntil = nil, os.clock() + ((Config.PumpOn or Config.PumpHop) and 150 or 120)
        end
        hsay(string.format("Event is on, but no ready door found (%d done, %d doors known)", H.n, n))
        State.Text = H.status
        return false
    end
    H.door, H.doorAt, H.info, H.finished, H.handled, H.pressAt, H.snap = best, os.clock(), nil, false, false, 0, enemySet()
    return true
end

-- Sea 2 (cafe): se o personagem sentar numa cadeira/banco no meio do farm, levanta sozinho (pula)
task.spawn(function()
    while Alive do
        task.wait(0.4)
        if Config.HalEvent or Config.HalBoss or Config.PumpOn or Config.PumpHop then
            pcall(function()
                local c = getChar()
                local hum = c and c:FindFirstChildOfClass("Humanoid")
                if hum and hum.Sit then
                    hum.Sit = false
                    hum:ChangeState(Enum.HumanoidStateType.Jumping)
                    hum.Jump = true
                end
            end)
        end
    end
end)

