    PC.src["shop"] = function() return [===[
local __E = ...
local AFL = __E.AFL
local Config, Fluent, InvCache, Player, Tabs, getSea, hasItem = __E.Config, __E.Fluent, __E.InvCache, __E.Player, __E.Tabs, __E.getSea, __E.hasItem
local invoke, persist = __E.invoke, __E.persist
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Alive = true
AFL.onUnload(function() Alive = false end);
-- ============ SHOP (portado do bomba.lua "Shop" + QuantumOnyx: Fruit Dealer / janelas do jogo) ============
-- Tudo aqui e compra por remote. Os remotes (todos do Remotes.CommF_) foram copiados do bomba.lua / Quantum:
--   ("BuyHaki", "Buso"|"Geppo"|"Soru"), ("KenTalk", "Buy"), ("ColorsDealer", "2")
--   ("BuyBlackLeg"), ("BuyElectro"), ("BuyFishmanKarate"), ("BuySuperhuman") ... estilos de luta (precisa estar perto do NPC)
--   ("BuyItem", nome) | ("Ectoplasm", "Buy", 1|2) | ("BlackbeardReward", "Slingshot", "2")      acessorios e armas
--   ("CraftItem", "Craft", nome)                                                              itens de eventos do mar
--   ("BlackbeardReward", "Refund"|"Reroll", "2") | ("Ectoplasm", "Change", 4) | ("CyborgTrainer", "Buy")   loja de Fragments
--   ("GetFruits"[, true]) e ("PurchaseRawFruit", nome[, true])                                  Fruit Dealer (normal / Mirage)
-- Os estilos de luta (e "ir ate o NPC") usam o AFL.goDo do arbitro: o personagem voa ate o NPC, compra e solta o controle.
local RS = ReplicatedStorage
local Shop = { status = "Idle", bought = 0, armed = {}, busyAt = 0 }
AFL.Shop = Shop
local function d(k, v) if Config[k] == nil then Config[k] = v end end
d("SnipeOn", false); d("SnipeFruit", "None"); d("SnipeMOn", false); d("SnipeMFruit", "None")

local MAIN = { [2753915549] = true, [85211729168715] = true, [4442272183] = true, [79091703265657] = true, [7449423635] = true, [100117331123089] = true }
local function inMain() return MAIN[game.PlaceId] == true end

-- ------------------------------------------------------------------ helpers ----
local function notify(txt, secs)
    pcall(function() Fluent:Notify({ Title = "Moon Hub - Shop", Content = txt, Duration = secs or 4 }) end)
end
local function reply(r)
    if type(r) == "string" and #r > 0 then return " (" .. string.sub(r, 1, 70) .. ")" end
    if type(r) == "number" then return " (code " .. tostring(r) .. ")" end
    return ""
end
local function dataNum(name)
    local ok, v = pcall(function() return Player.Data[name].Value end)
    return ok and tonumber(v) or 0
end
local function myRace()
    local ok, v = pcall(function() return Player.Data.Race.Value end)
    return ok and tostring(v) or ""
end
local function normFruit(n)
    n = string.lower(tostring(n))
    local half = string.match(n, "^(.+)%-%1$")
    if half then n = half end
    return (string.gsub(n, "[^%w]", ""))
end
-- NPC pelo nome (parte do nome): procura em workspace.NPCs e ReplicatedStorage.NPCs; devolve (modelo, posicao)
local function findNpc(part)
    part = string.lower(part)
    for _, root in ipairs({ workspace:FindFirstChild("NPCs"), RS:FindFirstChild("NPCs") }) do
        if root then
            for _, n in ipairs(root:GetChildren()) do
                if string.find(string.lower(n.Name), part, 1, true) then
                    local p = n:FindFirstChild("HumanoidRootPart") or n.PrimaryPart or n:FindFirstChildWhichIsA("BasePart", true)
                    if p then return n, p.Position end
                end
            end
        end
    end
end
-- botoes que gastam Fragments pedem um segundo toque em ate 4s
local function confirm(key, what)
    local now = os.clock()
    if Shop.armed[key] and now - Shop.armed[key] < 4 then Shop.armed[key] = nil return true end
    Shop.armed[key] = now
    notify("Press it again within 4 seconds to confirm: " .. what, 4)
    return false
end

-- compra por remote (sem andar): label, argumentos do CommF_, checkOwned = nao compra se ja tem
local function doBuy(label, args, checkOwned)
    if os.clock() - Shop.busyAt < 1 then return end
    Shop.busyAt = os.clock()
    task.spawn(function()
        local okAll, err = pcall(function()
            if checkOwned and hasItem(label) then notify("You already own " .. label, 3) return end
            Shop.status = "Buying " .. label
            local ok, r = invoke(table.unpack(args))
            InvCache.at = 0
            if not ok then notify(label .. ": the request failed (" .. tostring(r) .. ")", 5) return end
            if r == false then notify(label .. ": the server refused (not enough Beli/Fragments or level?)", 5) return end
            if checkOwned then
                task.wait(0.8)
                InvCache.at = 0
                if hasItem(label) then Shop.bought += 1; notify(label .. " purchased!", 4)
                else notify(label .. ": request sent" .. reply(r) .. " - not in your inventory yet", 5) end
            else
                notify(label .. ": request sent" .. reply(r), 4)
            end
        end)
        Shop.status = "Idle"
        if not okAll then AFL.logErr("shop " .. label, err) end
    end)
end

-- ---------------------------------------------------------- ir ate o NPC e comprar ----
-- AFL.goDo (pcompat2) voa ate o NPC pelo arbitro, chama a acao de compra la e solta o controle
function Shop.go(name, pos, act) AFL.goDo(name, pos, act) end
function Shop.stop() AFL.goStop() end

