-- craft de itens: o remote do bomba (CraftItem) primeiro; se o servidor responder "false", tenta o RF/Craft do jogo novo
local function craft(name)
    if os.clock() - Shop.busyAt < 1 then return end
    Shop.busyAt = os.clock()
    task.spawn(function()
        local okAll, err = pcall(function()
            Shop.status = "Crafting " .. name
            local ok, r = invoke("CraftItem", "Craft", name)
            if ok and r == false then
                local net = RS:FindFirstChild("Modules") and RS.Modules:FindFirstChild("Net")
                local rf = net and net:FindFirstChild("RF/Craft")
                if rf then ok, r = pcall(function() return rf:InvokeServer("Craft", name, 1, {}) end) end
            end
            InvCache.at = 0
            if not ok then notify(name .. ": the craft request failed (" .. tostring(r) .. ")", 5)
            elseif r == false then notify(name .. ": the server refused (missing materials?)", 5)
            else notify(name .. ": craft requested" .. reply(r), 4) end
        end)
        Shop.status = "Idle"
        if not okAll then AFL.logErr("shop craft " .. name, err) end
    end)
end

-- ----------------------------------------------------------------- Fruit Dealer ----
-- compra a fruta escolhida se ela estiver a venda e voce tiver Beli. mirage = estoque do Advanced Fruit Dealer
local Snipe = { n = 0, m = 0, noMoney = {} }
local function stockOf(mirage)
    local ok, stock
    if mirage then ok, stock = invoke("GetFruits", true) else ok, stock = invoke("GetFruits") end
    if ok and type(stock) == "table" then return stock end
end
local function buyFruit(want, mirage, silent)
    local stock = stockOf(mirage)
    if not stock then
        if not silent then notify("Could not read the fruit stock", 4) end
        return false
    end
    local nk = normFruit(want)
    for _, v in pairs(stock) do
        if type(v) == "table" and v.Name and normFruit(v.Name) == nk then
            if v.OnSale ~= true then
                if not silent then notify(tostring(v.Name) .. " is not in stock right now", 4) end
                return false
            end
            local price = tonumber(v.Price) or 0
            if dataNum("Beli") < price then
                local k = tostring(v.Name) .. (mirage and "M" or "N")
                if not silent or not Snipe.noMoney[k] then notify("Not enough Beli for " .. tostring(v.Name) .. " ($" .. tostring(price) .. ")", 5) end
                Snipe.noMoney[k] = true
                return false
            end
            local ok, r
            if mirage then ok, r = invoke("PurchaseRawFruit", v.Name, true) else ok, r = invoke("PurchaseRawFruit", v.Name) end
            InvCache.at = 0
            if ok and r ~= false then
                Shop.bought += 1
                notify((silent and "Fruit Sniper: " or "") .. "bought " .. tostring(v.Name) .. " for $" .. tostring(price) .. reply(r), 6)
                return true
            end
            notify(tostring(v.Name) .. ": the server refused the purchase" .. reply(r), 5)
            return false
        end
    end
    if not silent then notify("That fruit is not in the " .. (mirage and "Advanced" or "normal") .. " dealer list", 4) end
    return false
end
task.spawn(function()
    while Alive do
        task.wait(3)
        pcall(function()
            if not inMain() then return end
            local now = os.clock()
            -- depois de uma compra espera 2 minutos antes de tentar a mesma fruta de novo (nao esvazia a carteira se o estoque nao baixar)
            if Config.SnipeOn and Config.SnipeFruit ~= "None" and now - Snipe.n > 10 then
                Snipe.n = now
                if buyFruit(Config.SnipeFruit, false, true) then Snipe.n = now + 110 end
            end
            if Config.SnipeMOn and Config.SnipeMFruit ~= "None" and now - Snipe.m > 10 then
                Snipe.m = now
                if buyFruit(Config.SnipeMFruit, true, true) then Snipe.m = now + 110 end
            end
        end)
    end
end)

