    PC.src["player"] = function() return [===[
local __E = ...
local AFL = __E.AFL
local Config, Fluent, Player, Tabs, getChar, invoke, persist = __E.Config, __E.Fluent, __E.Player, __E.Tabs, __E.getChar, __E.invoke, __E.persist
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")
local Alive = true
AFL.onUnload(function() Alive = false end);
-- ============ PLAYER (portado do bomba.lua "Misc"/"Local Player" + QuantumOnyx + codigos do Moon v52) ============
-- Dash Length (atributo "DashLength" do personagem), Black Screen / White Screen (3D off), Remove Damage Indicators, Infinite Zoom,
-- Auto Add Points (CommF_ "AddPoint"), Redeem All Codes (Remotes.Redeem, com leitura opcional da wiki) e botoes de servidor.
local RS = ReplicatedStorage
local Plr = { status = "Idle", dashOrig = nil, codes = { ok = 0, bad = 0, busy = false }, cancelHop = false }
AFL.Plr = Plr
local function d(k, v) if Config[k] == nil then Config[k] = v end end
d("PlrDash", false); d("PlrDashV", "100"); d("PlrBlack", false); d("PlrWhite", false); d("PlrNoDmg", false); d("PlrZoom", false)
d("PlrStatOn", false); d("PlrStatN", 1); d("PlrFetchCodes", true)
-- v64: WalkSpeed/JumpPower customizaveis (pedido: opcoes novas e funcionais com base nos 2 scripts de referencia,
-- que tem esse ajuste). Fica desligado por padrao e nao muda nada sem o usuario ligar.
d("PlrSpeedOn", false); d("PlrSpeedV", "16"); d("PlrJumpOn", false); d("PlrJumpV", "50")
d("PlrNoclip", false)   -- v64: Noclip manual do jogador (atravessar paredes/pisos) - pedido com base nos scripts de referencia
if type(Config.PlrStats) ~= "table" then Config.PlrStats = { "Melee" } end

local function notify(txt, secs)
    pcall(function() Fluent:Notify({ Title = "Moon Hub - Player", Content = txt, Duration = secs or 4 }) end)
end
local function dataNum(name)
    local ok, v = pcall(function() return Player.Data[name].Value end)
    return ok and tonumber(v) or 0
end

-- ------------------------------------------------------------------ Dash Length ----
local function dashApply(char)
    if not char then return end
    local cur = char:GetAttribute("DashLength")
    if cur == nil then return end
    if Config.PlrDash then
        local v = tonumber(Config.PlrDashV)
        if not v then return end
        if Plr.dashOrig == nil then Plr.dashOrig = cur end
        if cur ~= v then char:SetAttribute("DashLength", v) end
    elseif Plr.dashOrig ~= nil then
        if cur ~= Plr.dashOrig then char:SetAttribute("DashLength", Plr.dashOrig) end
    end
end

-- ------------------------------------------------------------------ WalkSpeed / JumpPower ----
local function speedApply(char)
    char = char or Player.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if not hum then return end
    if Config.PlrSpeedOn then
        local v = tonumber(Config.PlrSpeedV)
        if v and v > 0 then pcall(function() hum.WalkSpeed = v end) end
    end
    if Config.PlrJumpOn then
        local v = tonumber(Config.PlrJumpV)
        if v and v > 0 then pcall(function() hum.JumpPower = v; hum.UseJumpPower = true end) end
    end
end
Player.CharacterAdded:Connect(function(c) task.wait(0.5); if Alive then speedApply(c) end end)
task.spawn(function()
    while Alive do
        if Config.PlrSpeedOn or Config.PlrJumpOn then pcall(speedApply) end   -- reaplica (o jogo zera as vezes apos dash/stun/respawn)
        task.wait(1)
    end
end)

-- ------------------------------------------------------------------ Noclip manual ----
-- Atravessar parede/piso enquanto o toggle estiver ligado. So tira a colisao do PROPRIO personagem (nunca de outra
-- coisa no mapa), e devolve tudo certinho ao desligar.
local noclipConn, noclipOrig = nil, setmetatable({}, { __mode = "k" })
local function noclip(on)
    if on then
        if noclipConn then return end
        noclipConn = RunService.Stepped:Connect(function()
            local c = Player.Character
            if c then
                for _, p in ipairs(c:GetDescendants()) do
                    if p:IsA("BasePart") and p.CanCollide then
                        if noclipOrig[p] == nil then noclipOrig[p] = true end   -- so lembra quem FOMOS nos que mudamos
                        p.CanCollide = false
                    end
                end
            end
        end)
    else
        if noclipConn then pcall(function() noclipConn:Disconnect() end); noclipConn = nil end
        local c = Player.Character
        if c then for _, p in ipairs(c:GetDescendants()) do if noclipOrig[p] then pcall(function() p.CanCollide = true end) end end end
        noclipOrig = setmetatable({}, { __mode = "k" })
    end
end
AFL.onUnload(function() if noclipConn then pcall(function() noclipConn:Disconnect() end) end end)

-- ----------------------------------------------------------------- tela e GUI ----
local function blackScreen(on)
    local pg = Player:FindFirstChildOfClass("PlayerGui")
    if not pg then return end
    local old = pg:FindFirstChild("MoonBlackOverlay")
    if old then old:Destroy() end
    if not on then return end
    local g = Instance.new("ScreenGui")
    g.Name, g.IgnoreGuiInset, g.ResetOnSpawn, g.DisplayOrder = "MoonBlackOverlay", true, false, -999
    local f = Instance.new("Frame")
    f.Name, f.Size, f.BackgroundColor3, f.BorderSizePixel, f.ZIndex = "Background", UDim2.new(1, 0, 1, 0), Color3.new(0, 0, 0), 0, 0
    f.Parent = g
    g.Parent = pg
end
local function render3d(off)
    pcall(function() RunService:Set3dRenderingEnabled(not off) end)
end
local function damageGui(hide)
    pcall(function()
        local a = RS:FindFirstChild("Assets")
        local dc = a and a:FindFirstChild("GUI") and a.GUI:FindFirstChild("DamageCounter")
        if dc and dc.Enabled == hide then dc.Enabled = not hide end
        local n = Player:FindFirstChildOfClass("PlayerGui") and Player.PlayerGui:FindFirstChild("Notifications")
        if n and n.Enabled == hide then n.Enabled = not hide end
    end)
end
local zoomOrig = Player.CameraMaxZoomDistance
local function zoom(on)
    pcall(function() Player.CameraMaxZoomDistance = on and math.huge or zoomOrig end)
end

-- v61 fix: relato de nao conseguir desligar o Black/White Screen pelo toggle (com o mundo 3D desligado, o clique pode
-- nao registrar certo em alguns executores). Tecla de emergencia (End) desliga os dois na hora, sem depender da UI.
pcall(function()
    local UIS = game:GetService("UserInputService")
    UIS.InputBegan:Connect(function(input, gameProcessed)
        if Alive and input.KeyCode == Enum.KeyCode.End then
            if Config.PlrBlack then Config.PlrBlack = false; pcall(blackScreen, false); persist() end
            if Config.PlrWhite then Config.PlrWhite = false; pcall(render3d, false); persist() end
        end
    end)
end)

-- estado salvo (so mexe no que o usuario ligou; ao fechar o hub volta tudo)
if Config.PlrBlack then blackScreen(true) end
if Config.PlrWhite then render3d(true) end
if Config.PlrZoom then zoom(true) end
if Config.PlrNoclip then noclip(true) end
AFL.onUnload(function()
    pcall(blackScreen, false)
    pcall(render3d, false)
    pcall(damageGui, false)
    pcall(zoom, false)
    pcall(noclip, false)
    pcall(function()
        local char = Player.Character
        if char and Plr.dashOrig ~= nil then char:SetAttribute("DashLength", Plr.dashOrig) end
    end)
end)
task.spawn(function()
    while Alive do
        task.wait(0.5)
        pcall(function()
            dashApply(Player.Character)
            if Config.PlrNoDmg then damageGui(true) end
        end)
    end
end)

-- ---------------------------------------------------------------- Add Points ----
local STATS = { { "Melee", "Melee" }, { "Defense", "Defense" }, { "Sword", "Sword" }, { "Gun", "Gun" }, { "Demon Fruit", "Demon Fruit" } }
local function selected()
    local set = {}
    for _, n in ipairs(Config.PlrStats or {}) do set[n] = true end
    return set
end
function Plr.addPoints()
    local pts = dataNum("Points")
    if pts < 1 then return 0 end
    local sel, per, spent = selected(), math.clamp(math.floor(tonumber(Config.PlrStatN) or 1), 1, 100), 0
    for _, st in ipairs(STATS) do
        if sel[st[1]] and pts > 0 then
            local n = math.min(per, pts)
            local ok, r = invoke("AddPoint", st[2], n)
            if ok and r ~= false then pts -= n; spent += n end
        end
    end
    return spent
end
task.spawn(function()
    while Alive do
        task.wait(0.4)
        if Config.PlrStatOn then pcall(Plr.addPoints) end
    end
end)

-- --------------------------------------------------------------------- codigos ----
-- lista do bomba.lua + lista do Moon v52 (sem repetir). Os expirados so respondem erro; para somar um novo e so colocar aqui.
local CODES = {
    "KITT_RESET", "Sub2UncleKizaru", "SUB2GAMERROBOT_RESET1", "Sub2Fer999", "Enyu_is_Pro", "JCWK", "StarcodeHEO", "MagicBus", "KittGaming",
    "Sub2CaptainMaui", "Sub2OfficalNoobie", "TheGreatAce", "Sub2NoobMaster123", "Sub2Daigrock", "Axiore", "StrawHatMaine", "TantaiGaming",
    "Bluxxy", "SUB2GAMERROBOT_EXP1", "Chandler", "NOMOREHACK", "BANEXPLOIT", "WildDares", "BossBuild", "GetPranked", "EARN_FRUITS",
    "FIGHT4FRUIT", "NOEXPLOITER", "NOOB2ADMIN", "CODESLIDE", "ADMINHACKED", "ADMINDARES", "fruitconcepts", "krazydares", "TRIPLEABUSE",
    "SEATROLLING", "24NOADMIN", "REWARDFUN", "NEWTROLL", "fudd10_v2", "Fudd10", "Bignews", "SECRET_ADMIN",
    "SEA_DESTROYERS", "NOOB_BOAT", "ADMIN_CAVES", "FIGHTING_4_FRUITS", "BLUDFRUIT", "TANTAITV", "EASTEREXP", "SEATROLL", "ADMIN_TROLL",
    "EXP_5B", "XMASEXP", "UPD16", "UPD15", "3BVISITS", "2BILLION", "1MLIKES_RESET", "15B_LIKES", "CONTROL", "COLOSSEUM", "GAMERROBOT_RESET",
}
local httpFn = (syn and syn.request) or (http and http.request) or http_request or request or httprequest
-- codigos atuais da wiki do Blox Fruits (opcional; se der erro usa so a lista de cima)
local function wikiCodes()
    local out = {}
    if not httpFn then return out end
    pcall(function()
        local r = httpFn({ Url = "https://blox-fruits.fandom.com/wiki/Codes", Method = "GET" })
        local body = r and (r.StatusCode == 200 or r.Success) and r.Body
        if type(body) ~= "string" then return end
        local a = string.find(body, "Working_Codes", 1, true)
        if not a then return end
        local b = string.find(body, "Expired_Codes", a, true)
        local part = b and string.sub(body, a, b) or string.sub(body, a, a + 35000)
        for code in string.gmatch(part, "<td><code>([^<]+)</code>") do
            code = string.gsub(string.gsub(string.gsub(code, "%s+", ""), '"', ""), "'", "")
            if code ~= "" then out[#out + 1] = code end
        end
    end)
    return out
end
local function tryRedeem(code)
    local rems = RS:FindFirstChild("Remotes")
    local rf = rems and rems:FindFirstChild("Redeem")
    if not (rf and rf:IsA("RemoteFunction")) then return false, "remote Redeem not found" end
    local done, ok, res = false, false, nil
    task.spawn(function()
        ok, res = pcall(function() return rf:InvokeServer(code) end)
        done = true
    end)
    local t0 = os.clock()
    while not done and os.clock() - t0 < 6 do task.wait(0.05) end
    if not done then return false, "no response (6s)" end
    return ok, res
end
function Plr.redeemAll()
    local C = Plr.codes
    if C.busy then notify("Already redeeming codes...", 3) return end
    C.busy, C.ok, C.bad = true, 0, 0
    task.spawn(function()
        local list, seen = {}, {}
        local function add(code)
            local k = string.upper(code)
            if not seen[k] then seen[k] = true; list[#list + 1] = code end
        end
        if Config.PlrFetchCodes then
            Plr.status = "Reading the working codes from the wiki..."
            for _, c in ipairs(wikiCodes()) do add(c) end
        end
        for _, c in ipairs(CODES) do add(c) end
        for i, code in ipairs(list) do
            if not Alive then break end
            Plr.status = string.format("Redeeming codes %d/%d", i, #list)
            local ok, res = tryRedeem(code)
            -- o jogo responde com texto de erro quando nao resgata
            local bad = (not ok) or res == nil or res == false
            if not bad and type(res) == "string" then
                local l = string.lower(res)
                bad = string.find(l, "invalid", 1, true) or string.find(l, "expired", 1, true) or string.find(l, "already", 1, true)
                    or string.find(l, "used", 1, true) or string.find(l, "not valid", 1, true)
            end
            if bad then C.bad += 1 else C.ok += 1 end
            task.wait(0.4)
        end
        Plr.status = string.format("Codes done: %d redeemed, %d skipped", C.ok, C.bad)
        notify(string.format("Codes done: %d redeemed, %d skipped (expired / already used)", C.ok, C.bad), 8)
        C.busy = false
    end)
end

-- -------------------------------------------------------------------- servidor ----
local function jobId()
    local sb = RS:FindFirstChild("__ServerBrowser")
    if sb and AFL.invokeT then
        local ok, id = AFL.invokeT(sb, 5, "getjob")
        if ok and type(id) == "string" and #id > 5 then return id end
    end
    return game.JobId
end

