    PC.src["dungeon2"] = function() return [===[
local __E = ...
local AFL = __E.AFL
local Config, Fluent, Player, Tabs, persist = __E.Config, __E.Fluent, __E.Player, __E.Tabs, __E.persist
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Alive = true
AFL.onUnload(function() Alive = false end);
-- ============ DUNGEON EXTRAS (portado do bomba.lua + QuantumOnyx): Trinkets, Unlock Difficulty, Dungeon Hub ============
-- Remotes (conferidos nos dumps do jogo):
--   ReplicatedStorage.Remotes.AccessoryInteract                  RemoteFunction  ("d") comprar | ("a", u1, u2, u3) fundir | ("c", u1) refinar | ("b", {uids}) desmanchar
--   ReplicatedStorage.Modules.Net["RF/GetAllItemValues"]         devolve a lista de itens; os Trinkets tem Key "AccessoryType"/"Type" = "Trinket" e NetworkedUID
--   ReplicatedStorage.DungeonShared.DataRemote                   ("TryUnlockDifficulty", "Simulation", "Hard"|"Challenge")
--   ReplicatedStorage.Modules.Net["RF/DungeonNPCNetworkFunction"] ("TeleportToDungeonHub", false) | ("TeleportBack") | ("UnlockDifficulty"/"UnlockNext")
local RS = ReplicatedStorage
local X = { status = "Idle", uids = {}, uidsAt = -1e9, at = {}, buys = 0, fuses = 0, refines = 0, scraps = 0 }
AFL.Dun2 = X
local DUNGEON_PLACE = 73902483975735
local function d(k, v) if Config[k] == nil then Config[k] = v end end
d("TrinketBuy", false); d("TrinketFuse", false); d("TrinketRefine", false); d("TrinketScrap", false); d("DunUnlock", false)

local function notify(txt, secs)
    pcall(function() Fluent:Notify({ Title = "Moon Hub - Dungeon", Content = txt, Duration = secs or 4 }) end)
end
local function net(name)
    local m = RS:FindFirstChild("Modules")
    local n = m and m:FindFirstChild("Net")
    return n and n:FindFirstChild(name)
end
-- InvokeServer com limite de tempo
local function call(rf, ...)
    if not rf then return false, "remote not found" end
    local args = table.pack(...)
    local done, ok, res = false, false, nil
    task.spawn(function()
        ok, res = pcall(function() return rf:InvokeServer(table.unpack(args, 1, args.n)) end)
        done = true
    end)
    local t0 = os.clock()
    while not done and os.clock() - t0 < 6 do task.wait(0.05) end
    if not done then return false, "no response (6s)" end
    return ok, res
end
local function accessory()
    local r = RS:FindFirstChild("Remotes")
    return r and r:FindFirstChild("AccessoryInteract")
end
local function inRun()
    local map = workspace:FindFirstChild("Map")
    return map ~= nil and map:FindFirstChild("Dungeon") ~= nil
end

-- ------------------------------------------------------------------ trinkets ----
-- uids dos Trinkets que voce tem (lista guardada por 1.5s, as 4 funcoes dividem a mesma leitura)
local function trinkets(force)
    if not force and os.clock() - X.uidsAt < 1.5 then return X.uids end
    X.uidsAt = os.clock()
    local ok, res = call(net("RF/GetAllItemValues"))
    if ok and type(res) == "table" then
        local list, seen = {}, {}
        for _, e in pairs(res) do
            if type(e) == "table" and (e.Key == "AccessoryType" or e.Key == "Type") and e.Value == "Trinket" and e.NetworkedUID and not seen[e.NetworkedUID] then
                seen[e.NetworkedUID] = true
                list[#list + 1] = e.NetworkedUID
            end
        end
        X.uids = list
    end
    return X.uids
end
function X.buy()
    local ok, r = call(accessory(), "d")
    if ok and r ~= false then X.buys += 1 end
    return ok and r ~= false, r
end
function X.fuse()
    local u = trinkets(true)
    if #u < 3 then return false, "need 3 trinkets (you have " .. #u .. ")" end
    local ok, r = call(accessory(), "a", u[1], u[2], u[3])
    if ok and r ~= false then X.fuses += 1; X.uidsAt = -1e9 end
    return ok and r ~= false, r
end
function X.refine()
    local u = trinkets(true)
    if #u < 1 then return false, "no trinket to refine" end
    local ok, r = call(accessory(), "c", u[1])
    if ok and r ~= false then X.refines += 1; X.uidsAt = -1e9 end
    return ok and r ~= false, r
end
-- desmancha os que passam de 3 (fica com os 3 primeiros, ate 7 por vez)
function X.scrap()
    local u = trinkets(true)
    if #u <= 3 then return false, "nothing extra to scrap (keeps the first 3)" end
    local extra = {}
    for i = 4, math.min(#u, 10) do extra[#extra + 1] = u[i] end
    local ok, r = call(accessory(), "b", extra)
    if ok and r ~= false then X.scraps += #extra; X.uidsAt = -1e9 end
    return ok and r ~= false, r
end
function X.unlock()
    local shared = RS:FindFirstChild("DungeonShared")
    local data = shared and shared:FindFirstChild("DataRemote")
    if data then
        call(data, "TryUnlockDifficulty", "Simulation", "Hard")
        call(data, "TryUnlockDifficulty", "Simulation", "Challenge")
    end
    local rf = net("RF/DungeonNPCNetworkFunction")
    if rf then
        for _, a in ipairs({ "UnlockDifficulty", "UnlockNext", "Unlock" }) do call(rf, a) end
    end
end

-- rotinas automaticas (cada uma no seu ritmo; se o servidor recusar espera mais antes de tentar de novo)
local PLAN = {
    { "TrinketBuy", 1.5, "buy" }, { "TrinketFuse", 2, "fuse" }, { "TrinketRefine", 2, "refine" }, { "TrinketScrap", 3, "scrap" },
}
task.spawn(function()
    while Alive do
        task.wait(0.5)
        pcall(function()
            local now = os.clock()
            for _, p in ipairs(PLAN) do
                local key, every, fn = p[1], p[2], p[3]
                if Config[key] and now - (X.at[key] or 0) >= every then
                    X.at[key] = now
                    task.spawn(function()
                        local ok = X[fn]()
                        if not ok then X.at[key] = os.clock() + 4 end   -- recusou: espera mais um pouco
                    end)
                end
            end
            -- desbloquear dificuldades: so no lugar da dungeon e fora de uma run
            if Config.DunUnlock and game.PlaceId == DUNGEON_PLACE and not inRun() and now - (X.at.unlock or 0) >= 5 then
                X.at.unlock = now
                task.spawn(X.unlock)
            end
        end)
    end
end)

-- ----------------------------------------------------------------------- UI ----
do
    local T = Tabs.Dungeons
    local function tog(id, title, desc, key)
        T:AddToggle(id, { Title = title, Description = desc, Default = Config[key] and true or false })
            :OnChanged(function(v) Config[key] = v and true or false; persist() end)
    end
    local function shot(title, desc, fn, okText)
        T:AddButton({ Title = title, Description = desc, Callback = function()
            task.spawn(function()
                local ok, r = fn()
                if ok then notify((okText or title) .. ": done", 3)
                else notify(title .. ": " .. (type(r) == "string" and r or "the server refused"), 4) end
            end)
        end })
    end

    T:AddSection("Dungeon Hub")
    T:AddButton({ Title = "Teleport To Dungeon Hub", Description = "Goes to the dungeon hub from any sea", Callback = function()
        task.spawn(function() call(net("RF/DungeonNPCNetworkFunction"), "TeleportToDungeonHub", false) end)
    end })
    T:AddButton({ Title = "Return To Previous Sea", Description = "Leaves the dungeon hub and goes back to the sea you came from", Callback = function()
        task.spawn(function() call(net("RF/DungeonNPCNetworkFunction"), "TeleportBack") end)
    end })

    T:AddSection("Difficulty")
    tog("DunUnlock", "Auto Unlock Difficulties", "Unlocks Hard and Challenge with your Simulation Data (only works inside the dungeon hub, between runs)", "DunUnlock")
    shot("Unlock Next Difficulty", "Tries to unlock the next difficulty once (dungeon hub)", function() X.unlock(); return true end, "Unlock attempt")

    T:AddSection("Trinkets")
    tog("TrinketBuy", "Auto Buy Trinkets", "Buys trinkets over and over", "TrinketBuy")
    tog("TrinketFuse", "Auto Fuse Trinkets", "Fuses 3 trinkets at a time", "TrinketFuse")
    tog("TrinketRefine", "Auto Refine Trinkets", "Refines your trinkets", "TrinketRefine")
    tog("TrinketScrap", "Auto Scrap Trinkets", "Scraps the extra trinkets and keeps the first 3", "TrinketScrap")
    shot("Buy Trinket", "Buys one trinket", X.buy)
    shot("Fuse 3 Trinkets", "Fuses 3 of your trinkets", X.fuse)
    shot("Refine Trinket", "Refines one trinket", X.refine)
    shot("Scrap Extra Trinkets", "Scraps the trinkets after the first 3", X.scrap)
    local function open(label, gui, arg)
        T:AddButton({ Title = "Open " .. label, Description = "Opens the game's " .. label .. " window", Callback = function()
            local ok = pcall(function()
                local g = Player.PlayerGui:WaitForChild(gui, 3)
                if arg == nil then g.Open:Fire() else g.Open:Fire(arg) end
            end)
            if not ok then notify(label .. " could not be opened here", 3) end
        end })
    end
    open("Trinket Merge", "AccessoryMerge", false)
    open("Trinket Refine", "AccessoryMerge", true)
    open("Trinket Scrap", "AccessoryTrasher", nil)

    T:AddSection("Trinket Info")
    local info = T:AddParagraph({ Title = "Trinkets", Content = "Idle" })
    task.spawn(function()
        while Alive do
            task.wait(2)
            pcall(function()
                info:SetDesc(string.format("Bought %d | Fused %d | Refined %d | Scrapped %d", X.buys, X.fuses, X.refines, X.scraps))
            end)
        end
    end)
end



]===] end
    PC.src["draco"] = function() return [===[
local __E = ...
local AFL = __E.AFL
local Config, Fluent, Player, State, Tabs, fightEnemy, findEnemy = __E.Config, __E.Fluent, __E.Player, __E.State, __E.Tabs, __E.fightEnemy, __E.findEnemy
local findSpawn, flyTo, getChar, persist = __E.findSpawn, __E.flyTo, __E.getChar, __E.persist
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Alive = true
AFL.onUnload(function() Alive = false end);
-- ============ DRACO / DRAGON DOJO (portado do QuantumOnyx): trocar pra Draco, Trial, Fire Flowers, Dragon Talon ============
-- Tudo copiado da logica do Quantum (remotes e caminhos conferidos la):
--   ReplicatedStorage.Modules.Net["RF/InteractDragonQuest"]   ({ NPC = "Dragon Wizard", Command = "DragonRace" })  vira Draco (perto do Dragon Wizard)
--                                                             ({ NPC = "Uzoth", Command = "Upgrade" })            melhora o Dragon Talon
--   ReplicatedStorage.Remotes.DracoTrial                      RemoteFunction que comeca a Trial da raca Draco
--   workspace.Map.DracoTrial                                  mapa da Trial: Relic1, EndRelic1, Relic2, EndRelic2, Relic3, EndRelic3 (ProximityPrompt) e TrialDoor.DoorTouch
--   workspace.FireFlowers                                     flores de fogo (Models com ProximityPrompt), usadas no V2 do Draco
--   workspace.Map.PrehistoricIsland.TrialTeleport             entrada da Trial
-- As funcoes que ficam rodando (Trial, Fire Flowers, Dragon Talon) entram no arbitro como "Draco"; os botoes usam o AFL.goDo.
local RS = ReplicatedStorage
local D = { status = "Idle", stage = 1, flowers = 0, talons = 0, trials = 0, trialAt = -1e9, seenAt = -1e9, talonAt = -1e9, modelAt = -1e9 }
AFL.Draco = D
local function dflt(k, v) if Config[k] == nil then Config[k] = v end end
dflt("DracoTrial", false); dflt("DracoFlowers", false); dflt("DracoTalon", false)

local SEQ = { "Relic1", "EndRelic1", "Relic2", "EndRelic2", "Relic3", "EndRelic3" }
local WIZARD = Vector3.new(5773, 1210, 807)
local TALON = Vector3.new(5661.89, 1211.32, 864.84)
local DOJO = {
    { "Dojo Trainer", Vector3.new(5867, 1208, 870) },
    { "Dragon Hunter", Vector3.new(5864, 1209, 808) },
    { "Dragon Wizard", Vector3.new(5775, 1209, 806) },
    { "Uzoth (Dragon Talon)", TALON },
}

-- ------------------------------------------------------------------ helpers ----
local function notify(txt, secs)
    pcall(function() Fluent:Notify({ Title = "Moon Hub - Draco", Content = txt, Duration = secs or 4 }) end)
end
local function net(name)
    local m = RS:FindFirstChild("Modules")
    local n = m and m:FindFirstChild("Net")
    return n and n:FindFirstChild(name)
end
-- InvokeServer com limite de tempo (um remote sem resposta nao trava o hub)
local function call(rf, ...)
    if not rf then return false, "remote not found" end
    local args = table.pack(...)
    local done, ok, res = false, false, nil
    task.spawn(function()
        ok, res = pcall(function() return rf:InvokeServer(table.unpack(args, 1, args.n)) end)
        done = true
    end)
    local t0 = os.clock()
    while not done and os.clock() - t0 < 6 do task.wait(0.05) end
    if not done then return false, "no response (6s)" end
    return ok, res
end
local function myRace()
    local ok, v = pcall(function() return Player.Data.Race.Value end)
    return ok and tostring(v) or "?"
end
local function trialRemote()
    local r = RS:FindFirstChild("Remotes")
    return r and r:FindFirstChild("DracoTrial")
end
-- o relogio da Trial e o mesmo da Raid (TopHUDList.RaidTimer)
local function timerOn()
    local ok, v = pcall(function() return Player.PlayerGui.Main.TopHUDList.RaidTimer.Visible end)
    return ok and v == true
end
local cachedModel
local function trialModel()
    if cachedModel and cachedModel.Parent then return cachedModel end
    local map = workspace:FindFirstChild("Map")
    local m = map and map:FindFirstChild("DracoTrial")
    -- a busca funda no workspace inteiro e pesada: so de vez em quando
    if not m and os.clock() - D.modelAt > 3 then
        D.modelAt = os.clock()
        m = workspace:FindFirstChild("DracoTrial", true)
    end
    cachedModel = m
    return m
end
local function partOf(o)
    if not o then return nil end
    if o:IsA("BasePart") then return o end
    return o.PrimaryPart or o:FindFirstChildWhichIsA("BasePart", true)
end
local function posOf(p)
    local ok, v = pcall(function() return p:GetPivot().Position end)
    if ok and v then return v end
    return p.Position
end
-- voa ate chegar perto (raio) ou estourar o tempo; devolve se chegou
local function approach(pos, radius, secs)
    local t0 = os.clock()
    while os.clock() - t0 < (secs or 8) do
        local _, hrp = getChar()
        if not hrp then return false end
        if (hrp.Position - pos).Magnitude <= (radius or 5) then return true end
        flyTo(CFrame.new(pos))
        task.wait(0.1)
    end
    return false
end
local function itemPrompt(o)
    return o and (o:FindFirstChildOfClass("ProximityPrompt") or o:FindFirstChildWhichIsA("ProximityPrompt", true))
end

-- ------------------------------------------------------------ passos do arbitro ----
-- Trial: dentro dela pega as reliquias na ordem e vai ate a porta; fora dela pede ao servidor para comecar
function D.trialStep()
    if not timerOn() then
        D.stage = 1
        if os.clock() - D.trialAt >= 2.5 then
            D.trialAt = os.clock()
            task.spawn(function()
                local rf = trialRemote()
                if rf then
                    local ok = call(rf)
                    if ok then D.trials += 1 end
                end
            end)
        end
        -- acabou de sair/entrar: segura o controle 2s para as outras funcoes nao puxarem o personagem no meio
        return os.clock() - D.seenAt < 2
    end
    local trial = trialModel()
    if not trial then return false end              -- relogio ligado por outro evento (raid etc.)
    D.seenAt = os.clock()
    local _, hrp = getChar()
    if not hrp then return false end
    for i = D.stage, #SEQ do
        local obj = trial:FindFirstChild(SEQ[i], true)
        local pp = itemPrompt(obj)
        if pp and pp.Enabled then
            D.stage = i
            local part = pp.Parent:IsA("BasePart") and pp.Parent or partOf(obj)
            if part then
                flyTo(part.CFrame)
                if (part.Position - hrp.Position).Magnitude <= 20 then
                    if fireproximityprompt then pcall(fireproximityprompt, pp, math.huge) end
                    task.wait(0.3)
                    if not pp.Enabled then D.stage = i + 1 end
                end
            end
            D.status = "Trial: " .. SEQ[i]
            return true
        end
    end
    local door = trial:FindFirstChild("TrialDoor", true)
    local touch = door and (door:FindFirstChild("DoorTouch", true) or door:FindFirstChildWhichIsA("BasePart", true))
    if touch then
        flyTo(touch.CFrame)
        D.status = "Trial: door"
        return true
    end
    D.status = "Trial: waiting"
    return true
end

-- Fire Flowers (V2 do Draco): pega as flores do mapa; sem flor, caca Forest Pirate
function D.flowerStep()
    local _, hrp = getChar()
    if not hrp then return false end
    local folder = workspace:FindFirstChild("FireFlowers")
    if folder then
        for _, f in ipairs(folder:GetChildren()) do
            local part = f:IsA("Model") and (f.PrimaryPart or f:FindFirstChildOfClass("MeshPart") or f:FindFirstChildWhichIsA("BasePart", true))
            if part then
                D.status = "Fire Flowers: collecting"
                if (part.Position - hrp.Position).Magnitude > 6 then
                    flyTo(part.CFrame)
                else
                    local pp = itemPrompt(f)
                    if pp and fireproximityprompt then pcall(fireproximityprompt, pp, math.huge) end
                    D.flowers += 1
                    task.wait(0.5)
                end
                return true
            end
        end
    end
    local e = findEnemy({ "Forest Pirate" })
    if e then
        D.status = "Fire Flowers: Forest Pirates"
        fightEnemy(e, { e.Name }, true)
        return true
    end
    local sp = findSpawn({ "Forest Pirate" })
    if sp then
        D.status = "Fire Flowers: going to the Forest Pirates"
        flyTo(sp.CFrame * CFrame.new(0, 12, 0))
        return true
    end
    D.status = "Fire Flowers: no flowers and no Forest Pirates here"
    return false
end

-- Dragon Talon: fica no Uzoth e pede o upgrade a cada 0.5s
function D.talonStep()
    local _, hrp = getChar()
    if not hrp then return false end
    if (hrp.Position - TALON).Magnitude > 5 then
        D.status = "Dragon Talon: going to Uzoth"
        flyTo(CFrame.new(TALON))
        return true
    end
    D.status = "Dragon Talon: upgrading"
    if os.clock() - D.talonAt >= 0.5 then
        D.talonAt = os.clock()
        task.spawn(function()
            local ok, r = call(net("RF/InteractDragonQuest"), { NPC = "Uzoth", Command = "Upgrade" })
            if ok and r ~= false then D.talons += 1 end
        end)
    end
    return true
end

-- passo unico do arbitro (ordem: Trial > Fire Flowers > Dragon Talon)
function D.step()
    if Config.DracoTrial then
        local ok, busy = pcall(D.trialStep)
        if not ok then AFL.logErr("Draco trial", busy) elseif busy then return true end
    end
    if Config.DracoFlowers then
        local ok, busy = pcall(D.flowerStep)
        if not ok then AFL.logErr("Draco flowers", busy) elseif busy then return true end
    end
    if Config.DracoTalon then
        local ok, busy = pcall(D.talonStep)
        if not ok then AFL.logErr("Draco talon", busy) elseif busy then return true end
    end
    return false
end

-- ====================================================================== v29: FULLY DRACO (V1 -> V3/V4) ====================================================================
-- V1: vira Draco no Dragon Wizard (mesmo remote/comando do botao "Change To Draco Race").
-- V2/V3: nao existe no codebase (nem em nenhum hub de referencia ja visto) um remote separado so pra "submeter" a V2/V3 - o fluxo real do
-- jogo e falar de novo com o Dragon Wizard depois de cumprir o requisito (5 Fire Flowers + $ pra V2, derrotar o Terrorshark + $ pra V3) e o
-- servidor decide se libera. Por isso aqui a gente reusa o UNICO remote de quest do Draco ja verificado (RF/InteractDragonQuest, Command =
-- "DragonRace") pra "falar com o wizard" depois de cada requisito - e um palpite razoavel (e o padrao do proprio jogo), nao um remote inventado,
-- mas pode nao disparar a troca se o servidor exigir outro Command. Isso fica avisado na entrega.
-- V4: exige Dragonheart + Dragonstorm com mastria 500 (isso a gente LE de verdade, igual ao Mastery) e o Coracao do Leviathan (reusa os toggles
-- LevFind/LevStart/LevAttack/LevHeart que ja existem). Depois disso o jogo pede congelar a Hydra levando o barco pela cachoeira + resolver o
-- puzzle do Vault Room (lanternas + 3 reliquias + Ember) - NENHUM remote disso foi encontrado/confirmado em lugar nenhum, entao o bot NAO tenta
-- essa parte: ele para e avisa que falta fazer isso manualmente.
local fullSubmitAt = -1e9
local function findToolByName(nm)
    for _, c in ipairs({ Player.Backpack, Player.Character }) do
        if c then
            local t = c:FindFirstChild(nm)
            if t and t:IsA("Tool") then return t end
        end
    end
end
local function submitToWizard()
    if os.clock() - fullSubmitAt < 3 then return end
    fullSubmitAt = os.clock()
    task.spawn(function() call(net("RF/InteractDragonQuest"), { NPC = "Dragon Wizard", Command = "DragonRace" }) end)
end
-- V1: vai ate o wizard e pede a troca de raca (repete ate Player.Data.Race virar "Draco")
local function v1Step()
    if myRace() == "Draco" then return false end
    local _, hrp = getChar()
    if not hrp then return true end
    if (hrp.Position - WIZARD).Magnitude > 6 then
        D.status = "Full Draco V1: going to the Dragon Wizard"
        flyTo(CFrame.new(WIZARD))
        return true
    end
    D.status = "Full Draco V1: asking for the Draco race"
    submitToWizard()
    return true
end
-- V2: junta 5 Fire Flowers (reusa D.flowerStep) e depois vai falar com o wizard algumas vezes; sem forma confiavel de saber se o
-- servidor ja aceitou, para de tentar depois de algumas tentativas pra nao travar o V3 pra sempre caso a V2 ja tenha sido concluida antes
local v2Submits = 0
local function v2Step()
    if D.flowers < 5 then
        local ok, busy = pcall(D.flowerStep)
        if ok then D.status = "Full Draco V2: " .. D.status; return busy end
        return false
    end
    if v2Submits >= 6 then return false end
    local _, hrp = getChar()
    if hrp and (hrp.Position - WIZARD).Magnitude > 6 then
        D.status = "Full Draco V2: got the flowers, going to the Dragon Wizard"
        flyTo(CFrame.new(WIZARD))
        return true
    end
    D.status = "Full Draco V2: flowers ready, asking the Dragon Wizard (" .. (v2Submits + 1) .. "/6)"
    if os.clock() - fullSubmitAt >= 3 then v2Submits += 1 end
    submitToWizard()
    return true
end
-- V3: cata Terrorshark (mesmo mecanismo generico de combate das outras rotinas) e depois vai falar com o wizard algumas vezes
local v3Submits = 0
local function v3Step()
    local e = findEnemy({ "Terrorshark" })
    if e then
        D.status = "Full Draco V3: fighting the Terrorshark"
        fightEnemy(e, { "Terrorshark" }, true)
        return true
    end
    local sp = findSpawn({ "Terrorshark" })
    if sp then
        D.status = "Full Draco V3: going to the Terrorshark"
        flyTo(sp.CFrame * CFrame.new(0, 12, 0))
        return true
    end
    if v3Submits >= 6 then return false end
    local _, hrp = getChar()
    if hrp and (hrp.Position - WIZARD).Magnitude > 6 then
        D.status = "Full Draco V3: no Terrorshark around, trying the Dragon Wizard"
        flyTo(CFrame.new(WIZARD))
        return true
    end
    D.status = "Full Draco V3: asking the Dragon Wizard (" .. (v3Submits + 1) .. "/6)"
    if os.clock() - fullSubmitAt >= 3 then v3Submits += 1 end
    submitToWizard()
    return true
end
-- V4: so checa os pre-requisitos que a gente consegue ler/fazer de verdade (mastria 500 e o Coracao do Leviathan via toggles existentes);
-- nao tenta a parte da Hydra congelada / Vault Room (sem remote verificado).
local function v4Step()
    local heart = findToolByName("Dragonheart")
    local storm = findToolByName("Dragonstorm")
    local mHeart = heart and AFL.Mast and AFL.Mast.readMast(heart)
    local mStorm = storm and AFL.Mast and AFL.Mast.readMast(storm)
    if not (heart and storm and mHeart and mStorm and mHeart >= 500 and mStorm >= 500) then
        D.status = string.format("Full Draco V4: need Dragonheart+Dragonstorm at mastery 500 (have Dragonheart %s, Dragonstorm %s)",
            heart and (mHeart and math.floor(mHeart) or "?") or "missing", storm and (mStorm and math.floor(mStorm) or "?") or "missing")
        return true
    end
    if Config.LevHeart and AFL.SeaEv and AFL.SeaEv.levStep then
        local ok, busy = pcall(AFL.SeaEv.levStep)
        if ok and busy then D.status = "Full Draco V4: getting the Leviathan Heart"; return true end
    end
    D.status = "Full Draco V4: Dragonheart/Dragonstorm ready - the rest (freeze the Hydra by boat + Vault Room puzzle) has no safe remote to automate, do it yourself"
    return false
end
-- passo unico (so roda quando FullDraco esta ligado; nao interfere com os toggles manuais DracoTrial/Flowers/Talon acima)
function D.fullStep()
    if not Config.FullDraco then return false end
    local target = Config.DracoTarget or "V3"
    if myRace() ~= "Draco" then
        local ok, busy = pcall(v1Step)
        State.Mode, State.Text = "Fully Draco", D.status
        return ok and busy
    end
    -- v2/v3/v4 nao tem leitura de "versao atual" confiavel: a gente roda flores -> Terrorshark em sequencia (cada uma e inofensiva se o
    -- requisito dela ja foi cumprido - o wizard so nao avanca se o servidor achar que ja passou daquela etapa), e so entra no V4 se o
    -- alvo escolhido for V4.
    local ok2, busy2 = pcall(v2Step)
    if ok2 and busy2 then State.Mode, State.Text = "Fully Draco", D.status; return true end
    local ok3, busy3 = pcall(v3Step)
    if ok3 and busy3 then State.Mode, State.Text = "Fully Draco", D.status; return true end
    if target == "V4" then
        local ok4, busy4 = pcall(v4Step)
        State.Mode, State.Text = "Fully Draco", D.status
        return ok4 and busy4
    end
    return false
end

-- ------------------------------------------------------------------ botoes ----
function D.changeRace()
    if myRace() == "Draco" then notify("You are already a Draco", 3) return end
    AFL.goDo("Dragon Wizard", WIZARD, function()
        if not approach(WIZARD, 5, 8) then notify("Could not get close to the Dragon Wizard", 4) return end
        local ok, r = call(net("RF/InteractDragonQuest"), { NPC = "Dragon Wizard", Command = "DragonRace" })
        task.wait(1.5)
        if myRace() == "Draco" then notify("Your race is now Draco!", 5)
        elseif not ok then notify("Change race failed: " .. tostring(r), 5)
        else notify("Request sent, but the race did not change (the server may want something first)", 6) end
    end)
end
function D.toTrial()
    local function where()
        local map = workspace:FindFirstChild("Map")
        local isl = map and map:FindFirstChild("PrehistoricIsland")
        local tp = isl and isl:FindFirstChild("TrialTeleport")
        return tp and posOf(tp) or nil
    end
    AFL.goDo("Draco Trial", where, function()
        local pos = where()
        if pos then approach(pos, 3, 8) end
        task.wait(2)
    end)
end
function D.upgradeOnce()
    AFL.goDo("Uzoth", TALON, function()
        if not approach(TALON, 5, 8) then notify("Could not get close to Uzoth", 4) return end
        local ok, r = call(net("RF/InteractDragonQuest"), { NPC = "Uzoth", Command = "Upgrade" })
        if ok and r ~= false then D.talons += 1; notify("Dragon Talon upgrade requested", 4)
        else notify("Dragon Talon: " .. tostring(ok and "the server refused (materials missing?)" or r), 5) end
    end)
end

-- ----------------------------------------------------------------------- UI ----
do
    local T = Tabs.Races
    local function tog(id, title, desc)
        T:AddToggle(id, { Title = title, Description = desc, Default = Config[id] and true or false })
            :OnChanged(function(v) Config[id] = v and true or false; persist() end)
    end
    T:AddSection("Draco Race")
    local info = T:AddParagraph({ Title = "Draco", Content = "Checking..." })
    task.spawn(function()
        while Alive do
            pcall(function()
                info:SetDesc(string.format("Race: %s | Trial: %s | Flowers: %d | Talon upgrades: %d\nStatus: %s",
                    myRace(), timerOn() and trialModel() and "in progress" or "-", D.flowers, D.talons, D.status))
            end)
            task.wait(1.5)
        end
    end)
    T:AddButton({ Title = "Change To Draco Race", Description = "Flies to the Dragon Wizard (Dragon Dojo) and asks for the Draco race", Callback = D.changeRace })
    tog("DracoTrial", "Auto Complete Draco Trial", "Inside the trial it takes the relics in order and goes to the door. Outside it asks the server to start the trial")
    T:AddButton({ Title = "Teleport To Draco Trial", Description = "Flies to the trial entrance on the Prehistoric Island (the island has to be spawned)", Callback = D.toTrial })
    tog("DracoFlowers", "Auto Draco Race V2 (Fire Flowers)", "Collects the Fire Flowers; with none on the map it hunts Forest Pirates")

    T:AddSection("Fully Draco")
    T:AddDropdown("DracoTarget", { Title = "Target Version", Description = "How far to push the race automatically", Values = { "V3", "V4" }, Default = (Config.DracoTarget == "V4") and 2 or 1 })
        :OnChanged(function(v) Config.DracoTarget = v; persist() end)
    tog("FullDraco", "Fully Draco (V1 -> V3/V4)", "Changes race to Draco, farms Fire Flowers for V2, fights the Terrorshark for V3, and for V4 checks Dragonheart+Dragonstorm at mastery 500 plus the Leviathan Heart - freezing the Hydra and the Vault Room puzzle still need to be done by hand")

    T:AddSection("Dragon Dojo")
    tog("DracoTalon", "Auto Upgrade Dragon Talon", "Stays next to Uzoth and keeps asking for the upgrade")
    T:AddButton({ Title = "Upgrade Dragon Talon Once", Description = "Flies to Uzoth and asks for one upgrade", Callback = D.upgradeOnce })
    for _, e in ipairs(DOJO) do
        T:AddButton({ Title = "Teleport: " .. e[1], Callback = function()
            AFL.goDo(e[1], e[2], function() task.wait(0.5) end)
        end })
    end
end



]===] end
    PC.src["fully"] = function() return [===[
local __E = ...
local AFL = __E.AFL
local Config, Connections, Core, Diag, Fluent, Player, State = __E.Config, __E.Connections, __E.Core, __E.Diag, __E.Fluent, __E.Player, __E.State
local Tabs, activeQuestTitle, fightEnemy, findEnemy, findSpawn, flyTo, getChar = __E.Tabs, __E.activeQuestTitle, __E.fightEnemy, __E.findEnemy, __E.findSpawn, __E.flyTo, __E.getChar
local getPlayerLevel, getSea, hasItem, invCount, invoke, persist, questVisible = __E.getPlayerLevel, __E.getSea, __E.hasItem, __E.invCount, __E.invoke, __E.persist, __E.questVisible
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Alive = true
AFL.onUnload(function() Alive = false end);
-- ---------- Auto Fully (v24): rotinas "faz tudo sozinho" ----------
-- Fluxos e remotes portados dos hubs de referencia: bomba (Saber, Darkbeard, Cursed Captain, Rip Indra, Law Raid), Quantum Onyx (Rengoku, Law Raid,
-- Rainbow Haki, Observation V2, Soul Guitar) e Banana (pads de Haki do Rip Indra). Nada disto foi testado no jogo real, so no simulador.
-- Uma rotina por vez, na ordem de F.list. Cada rotina: { key, cfg, title, sea, done(), step(r) -> true se ocupou o turno }.
AFL.Fully = { list = {}, by = {}, at = {}, cool = {}, status = "Idle", cur = nil, started = os.clock() }
do
    local F = AFL.Fully
    local RS = ReplicatedStorage
    local V3 = Vector3.new
    local SEACMD = { "TravelMain", "TravelDressrosa", "TravelZou" }
    local SEALV = { 0, 700, 1500 }
    F.R = {}

    -- ---------- helpers ----------
    local function every(key, sec)
        if os.clock() - (F.at[key] or -1e9) < sec then return false end
        F.at[key] = os.clock()
        return true
    end
    F.every = every
    local function inv(...)
        local ok, res = invoke(...)
        if ok then return res end
        return nil
    end
    F.inv = inv
    local function dval(n)
        local d = Player:FindFirstChild("Data")
        local v = d and d:FindFirstChild(n)
        return v and tonumber(v.Value) or 0
    end
    F.dval = dval
    local function raceName()
        local d = Player:FindFirstChild("Data")
        local r = d and d:FindFirstChild("Race")
        return r and tostring(r.Value) or "?"
    end
    F.raceName = raceName
    local function tool(name)
        for _, c in ipairs({ Player.Character, Player.Backpack }) do
            local t = c and c:FindFirstChild(name)
            if t and t:IsA("Tool") then return t end
        end
    end
    F.tool = tool
    local function equip(name)
        local t = tool(name)
        if t and t.Parent ~= Player.Character then
            local _, _, hum = getChar()
            if hum then hum:EquipTool(t) end
        end
        return t
    end
    F.equip = equip
    local function owns(name)
        return tool(name) ~= nil or hasItem(name)
    end
    F.owns = owns
    -- itens que ja estao no inventario mas fora da mao (espadas) voltam para a mochila com LoadItem
    local function loadItem(name)
        if owns(name) and not tool(name) and every("load" .. name, 3) then invoke("LoadItem", name) end
        return tool(name)
    end
    F.loadItem = loadItem
    local function goTo(cf, r, up)
        local _, hrp = getChar()
        if not hrp then return false end
        if (hrp.Position - cf.Position).Magnitude <= (r or 8) then return true end
        flyTo(up and (cf * CFrame.new(0, up, 0)) or cf)
        return false
    end
    F.goTo = goTo
    local function near(v, r)
        local _, hrp = getChar()
        return hrp ~= nil and (hrp.Position - v).Magnitude <= (r or 8)
    end
    local function touch(part)
        local _, hrp = getChar()
        if hrp and part and firetouchinterest then
            pcall(function() firetouchinterest(hrp, part, 0); firetouchinterest(hrp, part, 1) end)
        end
    end
    local function click(cd) if cd and fireclickdetector then pcall(fireclickdetector, cd) end end
    local function press(pp) if pp and fireproximityprompt then pcall(fireproximityprompt, pp, 1) end end
    local function shut(p) return p ~= nil and p.Transparency < 0.5 and p.CanCollide ~= false end   -- parede/porta ainda fechada
    local function rsHas(name) return RS:FindFirstChild(name) ~= nil end
    -- inimigo vivo no servidor (ou carregado) -> luta. Retorna true se ocupou o turno
    local function fightNamed(names, canPull, r, label)
        local e = findEnemy(names)
        if not e then return false end
        if r then r.S("run", (label or "Fighting") .. " " .. e.Name) end
        fightEnemy(e, { e.Name }, canPull and true or false)
        return true
    end
    F.fightNamed = fightNamed
    F.near, F.touch, F.click, F.press, F.shut = near, touch, click, press, shut

    -- ---------- viagem entre mares ----------
    -- Retorna (errado, ocupado). errado = nao esta no mar certo; ocupado = o script esta viajando (o passo devolve "ocupado")
    local function wrongSea(r, want0)
        local want = want0 or r.sea
        if not want then return false, false end
        local seas = type(want) == "table" and want or { want }
        local cur = getSea()
        for _, s in ipairs(seas) do if s == cur then return false, false end end
        local target = seas[1]
        if getPlayerLevel() < SEALV[target] then
            r.S("wait", string.format("Needs level %d for Sea %d", SEALV[target], target)); return true, false
        end
        if not Config.FullTravel then r.S("wait", "Go to Sea " .. target .. " (Auto travel is off)"); return true, false end
        if (F.cool.travel or 0) > os.clock() then r.S("wait", "Sea travel failed repeatedly - paused for a few minutes"); return true, false end
        if every("travel", 25) then
            F.travelN = (F.travelN or 0) + 1
            if F.travelN > 4 then F.travelN, F.cool.travel = 0, os.clock() + 300; return true, false end
            invoke(SEACMD[target])
        end
        r.S("run", "Travelling to Sea " .. target)
        return true, true
    end
    table.insert(Connections, Player.CharacterAdded:Connect(function() F.travelN = 0 end))

    -- ---------- registro de rotinas ----------
    -- o = { key, cfg, title, sea, level, done = function() end, step = function(r) end, icon }
    local function define(o)
        local r = o
        r.state, r.msg, r.pct, r.t = "idle", "Idle", nil, os.clock()
        r.errN = 0
        function r.S(state, msg, pct)
            r.state, r.msg, r.pct, r.t = state, msg, pct, os.clock()
            if state == "run" then
                F.status = r.title .. ": " .. msg
                State.Mode, State.Text = "Auto Fully", F.status
                Diag.fully = F.status
            end
        end
        F.list[#F.list + 1] = r
        F.by[r.key] = r
        F.R[r.key] = r
        return r
    end
    F.define = define
    F.wrongSea = wrongSea

    -- ---------- passo principal ----------
    function F.enabled(r) return Config[r.cfg] and true or false end
    function F.step()
        if getChar() == nil then return false end
        for _, r in ipairs(F.list) do
            if F.enabled(r) then
                if (r.cool or 0) > os.clock() then
                    -- em pausa por erros seguidos: segue para a proxima rotina
                elseif r.done and r.done() then
                    r.S("done", r.doneMsg or "Done")
                else
                    local wrong, busy = wrongSea(r)
                    if wrong then
                        if busy then F.cur = r; return true end
                    elseif r.level and getPlayerLevel() < r.level then
                        r.S("wait", string.format("Needs level %d (you are %d)", r.level, getPlayerLevel()))
                    else
                        local ok, res = pcall(r.step, r)
                        if not ok then
                            r.errN += 1
                            AFL.logErr("Fully " .. r.key, res)
                            r.S("err", "Error: " .. tostring(res):sub(1, 60))
                            if r.errN >= 3 then r.errN, r.cool = 0, os.clock() + 30; r.S("err", "Paused 30s after 3 errors") end
                        else
                            r.errN = 0
                            if res then F.cur = r; return true end
                            if r.state == "run" then r.S("wait", r.msg, r.pct) end
                        end
                    end
                end
            else
                if r.state ~= "off" then r.state, r.msg, r.pct = "off", "Off", nil end
            end
        end
        F.cur = nil
        return false
    end
    function F.listed()
        for _, r in ipairs(F.list) do if Config[r.cfg] then return true end end
        return false
    end
    function F.counts()
        local on, done, run = 0, 0, 0
        for _, r in ipairs(F.list) do
            if Config[r.cfg] then
                on += 1
                if r.state == "done" then done += 1 elseif r.state == "run" then run += 1 end
            end
        end
        return on, done, run
    end

    -- ---------- baus (God's Chalice / Fist of Darkness) ----------
    local function chests(r, why)
        r.S("run", why)
        local opts = { hop = Config.FullHop and true or false, count = tonumber(Config.FullChestCount) or 20 }
        local ok, busy = pcall(AFL.chestStep, opts)
        if not ok then AFL.logErr("Fully chests", busy) return false end
        return busy and true or false
    end
    F.chests = chests

    -- =====================================================================================================
    -- SABER (Mar 1, level 200)  [bomba: AutoSaber | Quantum: AutoUnlockSaber]
    -- placas da Jungle -> Torch -> queimar a barreira do Desert -> Cup + Sick Man -> Mob Leader -> Relic -> Saber Expert -> PlaceRelic
    -- =====================================================================================================
    do
        local PLATES = V3(-1612.559, 36.977, 148.720)
        local TORCH_AT = V3(-1610.008, 11.505, 164.002)
        local FIRE_AT = V3(1114.615, 5.047, 4350.228)
        local CUP_AT = V3(1112, 5, 4365)
        local MOBLEADER_AT = V3(-2967.595, -4.911, 5328.707)
        local ALTAR_AT = V3(-1404.915, 29.977, 3.806)
        local EXPERT_AT = V3(-1401.850, 29.977, 8.819)
        local function pq(...) return inv("ProQuestProgress", ...) end
        local function pqCached(sub, sec)
            local c = F.pq or {}
            F.pq = c
            if not c[sub] or os.clock() - c[sub].t > sec then c[sub] = { v = pq(sub), t = os.clock() } end
            return c[sub].v
        end
        local r = define({ key = "saber", cfg = "FullSaber", title = "Auto Saber", sea = 1, level = 200, doneMsg = "You have the Saber" })
        r.done = function() return owns("Saber") end
        local seenExpert = false
        r.step = function(self)
            local map = workspace:FindFirstChild("Map")
            local jungle, desert = map and map:FindFirstChild("Jungle"), map and map:FindFirstChild("Desert")
            if not (jungle and desert) then
                self.S("run", "Flying to the Jungle (map not loaded)", 0)
                flyTo(CFrame.new(PLATES)); return true
            end
            local final = jungle:FindFirstChild("Final"); final = final and final:FindFirstChild("Part")
            local qp = jungle:FindFirstChild("QuestPlates")
            local door = qp and qp:FindFirstChild("Door")
            local burn = desert:FindFirstChild("Burn")
            local burnPart = burn and burn:FindFirstChild("Part")
            -- porta final aberta: Saber Expert
            if final and not shut(final) then
                local e = findEnemy({ "Saber Expert" })
                if e then
                    seenExpert = true
                    self.S("run", "Fighting the Saber Expert", 5 / 6)
                    fightEnemy(e, { e.Name }, false); return true
                end
                if seenExpert and every("placerelic", 2) then pq("PlaceRelic"); seenExpert = false end
                self.S("run", "Waiting for the Saber Expert", 5 / 6)
                if every("placerelic2", 5) then pq("PlaceRelic") end
                if not goTo(CFrame.new(EXPERT_AT), 10) then return true end
                return true
            end
            -- 1) placas
            if shut(door) then
                self.S("run", "Pressing the 5 plates in the Jungle", 0)
                if not near(PLATES, 100) then flyTo(CFrame.new(PLATES)); return true end
                if every("plates", 6) then
                    local list, all = {}, {}
                    for i = 1, 5 do
                        local pl = qp and qp:FindFirstChild("Plate" .. i)
                        local b = pl and pl:FindFirstChild("Button")
                        if b then
                            all[#all + 1] = b
                            if b:FindFirstChild("TouchInterest") then list[#list + 1] = b end
                        end
                    end
                    if #list == 0 then list = all end
                    for _, b in ipairs(list) do
                        local _, hrp = getChar()
                        if not hrp then break end
                        hrp.CFrame = b.CFrame
                        touch(b)
                        task.wait(0.5)
                    end
                end
                return true
            end
            -- 2) Torch + barreira do Desert
            if shut(burnPart) then
                local tt = tool("Torch")
                if tt then
                    equip("Torch")
                    local fire = burn and burn:FindFirstChild("Fire")
                    self.S("run", "Burning the Desert barrier with the Torch", 1 / 6)
                    if not near(FIRE_AT, 8) then flyTo(CFrame.new(FIRE_AT)); return true end
                    local h = tt:FindFirstChild("Handle")
                    if fire and h and firetouchinterest then pcall(function() firetouchinterest(h, fire, 0); firetouchinterest(h, fire, 1) end) end
                    return true
                end
                local tp = jungle:FindFirstChild("Torch")
                local tpart = tp and (tp:IsA("BasePart") and tp or tp:FindFirstChildWhichIsA("BasePart", true))
                self.S("run", "Picking up the Torch", 1 / 6)
                local at = tpart and tpart.CFrame or CFrame.new(TORCH_AT)
                if not goTo(at, 6) then return true end
                if tpart then touch(tpart) end
                return true
            end
            -- 3) Cup / Sick Man / Mob Leader / Relic
            local sick = pqCached("SickMan", 1.5)
            if sick ~= 0 then
                if not tool("Cup") then
                    self.S("run", "Getting the Cup", 2 / 6)
                    if every("getcup", 2) then pq("GetCup") end
                    local cup = desert:FindFirstChild("Cup")
                    if cup and not tool("Cup") then
                        if not goTo(CFrame.new(CUP_AT), 6) then return true end
                        local cp = cup:IsA("BasePart") and cup or cup:FindFirstChildWhichIsA("BasePart", true)
                        if cp then touch(cp) end
                    end
                    return true
                end
                equip("Cup")
                self.S("run", "Giving water to the Sick Man", 2 / 6)
                if every("fillcup", 3) then
                    local ch = Player.Character
                    pq("FillCup", ch and ch:FindFirstChild("Cup"))
                    task.wait(0.5)
                    F.pq = nil
                    pq("SickMan")
                end
                return true
            end
            local rich = pqCached("RichSon", 1.5)
            if rich == 0 then
                self.S("run", "Killing Mob Leader", 3 / 6)
                local e = findEnemy({ "Mob Leader" })
                if e then fightEnemy(e, { e.Name }, false); return true end
                self.S("run", "Waiting for the Mob Leader to spawn", 3 / 6)
                flyTo(CFrame.new(MOBLEADER_AT)); return true
            elseif rich == 1 or tool("Relic") then
                self.S("run", "Taking the Relic to the altar", 4 / 6)
                if not tool("Relic") and every("relic", 2) then pq("RichSon"); F.pq = nil end
                equip("Relic")
                flyTo(CFrame.new(ALTAR_AT)); return true
            end
            -- primeira conversa com o Sick Man / RichSon ainda sem resposta
            if every("richstart", 2) then pq("RichSon"); F.pq = nil end
            self.S("run", "Talking to the Sick Man", 2 / 6)
            return true
        end
    end

    -- =====================================================================================================
    -- RENGOKU (Mar 2)  [Quantum: AutoRengoku]  Hidden Key -> porta do Ice Castle
    -- =====================================================================================================
    do
        local DOOR = V3(6571, 299, -6968)
        local r = define({ key = "rengoku", cfg = "FullRengoku", title = "Auto Rengoku", sea = 2, doneMsg = "You have the Rengoku" })
        r.done = function() return owns("Rengoku") end
        local MOBS = { "Arctic Warrior", "Snow Lurker" }
        r.step = function(self)
            if fightNamed({ "Awakened Ice Admiral" }, false, self, "Fighting") then return true end
            local key = tool("Hidden Key")
            if key then
                equip("Hidden Key")
                self.S("run", "Using the Hidden Key at the Ice Castle door", 0.8)
                if not near(DOOR, 3) then flyTo(CFrame.new(DOOR)); return true end
                return true
            end
            self.S("run", "Farming Arctic Warriors / Snow Lurkers for the Hidden Key", 0.2)
            local e = findEnemy(MOBS)
            if e then fightEnemy(e, { e.Name }, true); return true end
            local sp = findSpawn(MOBS)
            if sp then flyTo(sp.CFrame * CFrame.new(0, 25, 0)); return true end
            self.S("wait", "No Arctic Warrior / Snow Lurker found")
            return false
        end
    end

    -- =====================================================================================================
    -- DARKBEARD (Mar 2)  [bomba: AutoDarkbeard | Banana: DarkbeardArena.Summoner]
    -- baus -> Fist of Darkness -> altar da arena -> mata o Darkbeard
    -- =====================================================================================================
    do
        local ALTAR = V3(3677.082, 62.752, -3144.833)
        local r = define({ key = "darkbeard", cfg = "FullDarkbeard", title = "Auto Darkbeard", sea = 2 })
        local function altarCF()
            local m = workspace:FindFirstChild("Map")
            local a = m and m:FindFirstChild("DarkbeardArena")
            local s = a and a:FindFirstChild("Summoner")
            local d = s and s:FindFirstChild("Detection")
            if d and d:IsA("BasePart") then return d.CFrame end
            return CFrame.new(ALTAR)
        end
        local fistAt, seenBoss = 0, false
        r.step = function(self)
            if fightNamed({ "Darkbeard" }, false, self, "Fighting") then seenBoss = true; return true end
            if seenBoss then seenBoss, fistAt = false, 0 end        -- ele morreu: ja pode juntar baus para o proximo
            if tool("Fist of Darkness") then
                fistAt = os.clock()
                equip("Fist of Darkness")
                self.S("run", "Placing the Fist of Darkness at the altar", 0.6)
                goTo(altarCF(), 6)
                return true
            end
            if os.clock() - fistAt < 12 then
                self.S("run", "Waiting for Darkbeard to spawn", 0.8)
                goTo(altarCF(), 20)
                return true
            end
            return chests(self, "Collecting chests for the Fist of Darkness")
        end
    end

    -- =====================================================================================================
    -- CURSED CAPTAIN (Mar 2, Ghost Ship)  [bomba: AutoCursedCaptain | Conte_do_colado: join API]
    -- =====================================================================================================
    do
        local SHIP = V3(923.213, 125.398, 32852.832)
        local CAP_AT = V3(921.484, 181.469, 33306.668)
        local r = define({ key = "cursed", cfg = "FullCursed", title = "Auto Cursed Captain", sea = 2 })
        local function inside() local _, hrp = getChar(); return hrp and (hrp.Position - SHIP).Magnitude <= 1000 end
        r.step = function(self)
            local e = findEnemy({ "Cursed Captain" })
            if e then
                if not inside() then
                    self.S("run", "Entering the Ghost Ship")
                    if every("shipin", 4) then invoke("requestEntrance", SHIP) end
                    return true
                end
                self.S("run", "Fighting the Cursed Captain")
                fightEnemy(e, { e.Name }, false); return true
            end
            if Config.FullHop and AFL.Race and AFL.Race.joinBoss then
                self.S("run", "No Cursed Captain here: looking for a server that has one")
                if not inside() and every("shipin", 4) then invoke("requestEntrance", SHIP) end
                AFL.Race.joinBoss("CursedCaptain")
                return true
            end
            self.S("run", "Waiting at the Ghost Ship for the Cursed Captain")
            if not inside() then
                if every("shipin", 4) then invoke("requestEntrance", SHIP) end
                return true
            end
            goTo(CFrame.new(CAP_AT), 30)
            return true
        end
    end

    -- =====================================================================================================
    -- RIP INDRA (Mar 3)  [bomba: AutoRipIndra | Banana: pads de Haki | Quantum: AutoRipIndra]
    -- God's Chalice (Elite Hunter / baus) -> pads de Haki lendario do Boat Castle -> Chalice no Summoner -> mata o rip_indra True Form
    -- =====================================================================================================
    do
        local CASTLE_AT = V3(-5500, 314, -2855)
        local ALTAR = V3(-5561, 314, -2663)
        local PADS = { ["Hot pink"] = "Winter Sky", ["Really red"] = "Pure Red", ["Oyster"] = "Snow White" }
        local LEG = { "Winter Sky", "Pure Red", "Snow White" }
        local r = define({ key = "ripindra", cfg = "FullRip", title = "Auto Rip Indra", sea = 3 })
        local function summoner()
            local m = workspace:FindFirstChild("Map")
            local c = m and m:FindFirstChild("Boat Castle")
            return c and c:FindFirstChild("Summoner")
        end
        local function pad()
            local s = summoner()
            local circ = s and s:FindFirstChild("Circle")
            if not circ then return nil, nil end
            local first
            for _, ch in ipairs(circ:GetChildren()) do
                first = first or ch
                local inner = ch:FindFirstChild("Part")
                local bc = (inner and inner.BrickColor) or ch.BrickColor
                if bc and bc.Name ~= "Lime green" then return ch, bc.Name end
            end
            return nil, first and "ok" or nil
        end
        local function missingColors()
            local res = inv("getColors")
            local miss = {}
            if type(res) == "table" then
                for _, c in pairs(res) do
                    if type(c) == "table" and table.find(LEG, c.HiddenName) and not c.Unlocked then miss[#miss + 1] = c.HiddenName end
                end
            end
            return miss
        end
        local function useColor(name)
            pcall(function()
                local net = RS:FindFirstChild("Modules") and RS.Modules:FindFirstChild("Net")
                local rf = net and net:FindFirstChild("RF/FruitCustomizerRF")
                if rf then rf:InvokeServer({ StorageName = name, Type = "AuraSkin", Context = "Equip" }) end
            end)
            if name ~= "Winter Sky" then invoke("activateColor", name) end
        end
        F.padColors = PADS
        local missText
        r.step = function(self)
            local boss = findEnemy({ "rip_indra True Form" })
            if boss then
                self.S("run", "Fighting rip_indra True Form", 1)
                fightEnemy(boss, { boss.Name }, false); return true
            end
            if not (owns("God's Chalice")) then
                self.S("run", "Getting a God's Chalice (Elite Hunter / chests)", 0.1)
                local ok, busy = pcall(AFL.eliteStep, true)
                if ok and busy then return true end
                return chests(self, "Collecting chests for the God's Chalice")
            end
            local s = summoner()
            if not s then
                self.S("run", "Flying to the Castle on the Sea", 0.3)
                flyTo(CFrame.new(CASTLE_AT)); return true
            end
            local p, colorName = pad()
            if p then
                local want = PADS[colorName]
                if not want then
                    self.S("wait", "Unknown pad colour: " .. tostring(colorName))
                else
                    self.S("run", "Haki pad (" .. want .. ")", 0.4)
                    local pcf = (p:IsA("BasePart") and p.CFrame) or p:GetPivot()
                    if not near(pcf.Position, 6) then flyTo(pcf * CFrame.new(0, 3, 0)); return true end
                    if every("padcolor" .. want, 4) then useColor(want); task.wait(2) end
                    return true
                end
                return false
            end
            equip("God's Chalice")
            local d = s:FindFirstChild("Detection")
            local cf = (d and d:IsA("BasePart") and d.CFrame) or CFrame.new(ALTAR)
            goTo(cf, 6)
            if near(cf.Position, 6) then
                -- no altar e o chefe nao aparece: confere se falta algum Haki lendario (e deixa o aviso na tela)
                if every("ripmiss", 20) then
                    local miss = missingColors()
                    missText = #miss > 0 and ("Missing legendary Haki: " .. table.concat(miss, ", ")) or nil
                end
                if missText then self.S("wait", missText, 0.8); return true end
            end
            self.S("run", "Placing the God's Chalice at the altar", 0.8)
            return true
        end
    end

    -- =====================================================================================================
    -- LAW RAID (Mar 2)  [Quantum: AutoLawRaid | bomba: AutoLawRaid]  Microchip -> maquina da Circle Island -> mata o Order
    -- =====================================================================================================
    do
        local MACHINE = V3(-5544, 229, -5938)
        local WAIT_AT = V3(-6300, 16, -4997)
        local r = define({ key = "law", cfg = "FullLaw", title = "Auto Law Raid", sea = 2 })
        local usedAt = 0
        local function machineCD()
            local m = workspace:FindFirstChild("Map")
            local ci = m and m:FindFirstChild("CircleIsland")
            local rs = ci and ci:FindFirstChild("RaidSummon")
            local b = rs and rs:FindFirstChild("Button")
            local mn = b and b:FindFirstChild("Main")
            return mn and mn:FindFirstChildOfClass("ClickDetector")
        end
        r.step = function(self)
            if fightNamed({ "Order" }, false, self, "Fighting") then usedAt = os.clock(); return true end
            if os.clock() - usedAt < 25 then
                self.S("run", "Waiting for the Order boss")
                goTo(CFrame.new(WAIT_AT), 40); return true
            end
            if tool("Microchip") then
                equip("Microchip")
                self.S("run", "Putting the Microchip in the machine")
                if not near(MACHINE, 7) then flyTo(CFrame.new(MACHINE)); return true end
                if every("lawclick", 1.5) then click(machineCD()); usedAt = os.clock() end
                return true
            end
            if dval("Fragments") >= 1000 then
                self.S("run", "Buying a Microchip (1000 fragments)")
                if every("microbuy", 3) then inv("BlackbeardReward", "Microchip", "2") end
                return true
            end
            self.S("wait", "Need 1000 fragments for the Microchip")
            return false
        end
    end
end

-- ---------- Auto Fully, parte 2: Rainbow Haki, Observation V2, Farm Observation, Soul Guitar ----------
-- Fluxos do Quantum Onyx (GetRainbowHaki, CompleteCitizenQuest, AutoKenV2, AutoFarmObservation, fn29 = Soul Guitar) e do Banana (HornedMan, KenTalk).
do
    local F = AFL.Fully
    local RS = ReplicatedStorage
    local V3 = Vector3.new
    local inv, every, tool, equip, owns, goTo, define = F.inv, F.every, F.tool, F.equip, F.owns, F.goTo, F.define
    local near, touch, click, fightNamed, dval = F.near, F.touch, F.click, F.fightNamed, F.dval

    -- a missao ativa (Quest GUI) tem todos estes trechos no titulo?
    local function verifyQuest(...)
        local title, vis = activeQuestTitle(), questVisible()
        if not (title and vis) then return false end
        for _, s in ipairs({ ... }) do
            if not string.find(title, s, 1, true) then return false end
        end
        return true
    end
    local function kenNumber()
        local v = Player:FindFirstChild("VisionRadius")
        if v and tonumber(v.Value) then return tonumber(v.Value) end
        local res = inv("KenTalk", "Status")
        return tonumber(res and string.match(tostring(res), "%d+"))
    end

    -- =====================================================================================================
    -- RAINBOW HAKI (Mar 3, Hydra Island)  [Quantum: GetRainbowHaki | Banana: HornedMan]
    -- Horned Man -> Bet -> mata o chefe da missao (Stone / Hydra Leader / Kilo Admiral / Captain Elephant / Beautiful Pirate), 5 vezes
    -- =====================================================================================================
    do
        local BOSSES = { "Stone", "Hydra Leader", "Kilo Admiral", "Captain Elephant", "Beautiful Pirate" }
        local HORNED = V3(-11892, 931, -8761)
        local r = define({ key = "rainbow", cfg = "FullRainbow", title = "Auto Rainbow Haki", sea = 3, doneMsg = "Rainbow Haki unlocked" })
        local isDone, checkedAt = false, -100
        r.done = function()
            if isDone then return true end
            if os.clock() - checkedAt < 20 then return false end
            checkedAt = os.clock()
            isDone = (inv("HornedMan") == 1)
            return isDone
        end
        r.step = function(self)
            if verifyQuest() then
                local title = activeQuestTitle()
                for i, name in ipairs(BOSSES) do
                    if string.find(title, name, 1, true) then
                        self.S("run", "Quest: kill " .. name, (i - 1) / #BOSSES)
                        local e = findEnemy({ name })
                        if e then fightEnemy(e, { e.Name }, false); return true end
                        self.S("run", "Waiting for " .. name .. " to spawn", (i - 1) / #BOSSES)
                        local sp = findSpawn({ name })
                        if sp then flyTo(sp.CFrame * CFrame.new(0, 30, 0)) end
                        return true
                    end
                end
            end
            self.S("run", "Going to the Horned Man", 0)
            if not goTo(CFrame.new(HORNED), 9) then return true end
            self.S("run", "Betting with the Horned Man", 0)
            if every("hornedbet", 3) then inv("HornedMan", "Bet") end
            return true
        end
    end

    -- =====================================================================================================
    -- OBSERVATION V2 (Mar 3, Floating Turtle)  [Quantum: CompleteCitizenQuest + AutoKenV2 | Banana: CitizenQuestProgress / KenTalk2]
    -- quest do Citizen (50 Forest Pirate -> Captain Elephant -> tesouro) -> Apple + Banana + Pineapple -> Fruit Bowl -> Ken (KenTalk2 Start / Buy)
    -- =====================================================================================================
    do
        local NPC = V3(-12445, 332, -7676)
        local KEN = V3(-10920, 624, -10267)
        local TREASURE = V3(-12512, 340, -9872)
        local FOREST = V3(-13497, 391, -7909)
        local ELEPHANT = V3(-13382, 367, -8539)
        local FRUITS = { "Apple", "Banana", "Pineapple" }
        local r = define({ key = "kenv2", cfg = "FullKenV2", title = "Auto Observation V2", sea = 3, doneMsg = "Observation V2 done" })
        r.done = function() return Config.FullKenDone == true end
        local function fruitHandle(name)
            local sp = workspace:FindFirstChild(name .. "Spawner")
            local t = sp and sp:FindFirstChildOfClass("Tool")
            local h = t and t:FindFirstChild("Handle")
            if h then return h end
            for _, c in ipairs(workspace:GetChildren()) do
                if c.Name == name then
                    local hh = c:FindFirstChild("Handle")
                    if hh then return hh end
                end
            end
        end
        local function citizen(self, p)
            if p.KilledBoss then
                self.S("run", "Citizen quest: going to the treasure", 0.3)
                flyTo(CFrame.new(TREASURE)); return true
            end
            if not p.KilledBandits then
                if verifyQuest("Forest Pirate", "50") then
                    self.S("run", "Citizen quest: killing 50 Forest Pirates", 0.1)
                    local e = findEnemy({ "Forest Pirate" })
                    if e then fightEnemy(e, { e.Name }, true); return true end
                    flyTo(CFrame.new(FOREST)); return true
                end
                self.S("run", "Citizen quest: asking the Citizen for the mission", 0.05)
                if not near(NPC, 8) then flyTo(CFrame.new(NPC)); return true end
                if every("citstart", 2) then inv("StartQuest", "CitizenQuest", 1) end
                return true
            end
            if verifyQuest("Captain Elephant") then
                self.S("run", "Citizen quest: killing Captain Elephant", 0.2)
                local e = findEnemy({ "Captain Elephant" })
                if e then fightEnemy(e, { e.Name }, false); return true end
                flyTo(CFrame.new(ELEPHANT)); return true
            end
            self.S("run", "Citizen quest: reporting the bandits", 0.15)
            if not near(NPC, 8) then flyTo(CFrame.new(NPC)); return true end
            if every("citturn", 2) then inv("CitizenQuestProgress", "Citizen") end
            return true
        end
        r.step = function(self)
            if tool("Fruit Bowl") then
                equip("Fruit Bowl")
                self.S("run", "Giving the Fruit Bowl to Ken", 0.9)
                if not goTo(CFrame.new(KEN), 8) then return true end
                if dval("Beli") < 5000000 then self.S("wait", "Need 5,000,000 Beli to finish Observation V2"); return false end
                if every("kenbuy", 4) then
                    inv("KenTalk2", "Start"); task.wait(0.1)
                    inv("KenTalk2", "Buy"); task.wait(1)
                    if not tool("Fruit Bowl") then Config.FullKenDone = true; persist() end
                end
                return true
            end
            local p = F.citizenCache
            if not p or os.clock() - p.t > 2 then
                p = { t = os.clock(), v = inv("CitizenQuestProgress") }
                F.citizenCache = p
            end
            if type(p.v) == "table" and not p.v.FoundTreasure then return citizen(self, p.v) end
            -- tesouro achado: frutas
            local have = 0
            for _, n in ipairs(FRUITS) do if tool(n) then have += 1 end end
            if have < 3 then
                for _, n in ipairs(FRUITS) do
                    if not tool(n) then
                        self.S("run", string.format("Collecting the fruits for the Citizen (%d/3): %s", have, n), 0.4 + 0.1 * have)
                        local h = fruitHandle(n)
                        if h then
                            if not near(h.Position, 6) then flyTo(CFrame.new(h.Position)); return true end
                            touch(h); return true
                        end
                        self.S("wait", "Waiting for the " .. n .. " to spawn")
                        return false
                    end
                end
            end
            self.S("run", "Delivering the fruits to the Citizen", 0.8)
            if not near(NPC, 8) then flyTo(CFrame.new(NPC)); return true end
            if every("citfruit", 2) then inv("CitizenQuestProgress", "Citizen") end
            return true
        end
    end

    -- =====================================================================================================
    -- FARM OBSERVATION  [Quantum: AutoFarmObservation]
    -- fica do lado de um mob que ataca (Ken ligado) para desviar e subir o nivel; com 0 desvios sobe 50 studs ate recarregar
    -- =====================================================================================================
    do
        local SPOTS = { { "Galley Captain", V3(5533, 88, 4852) }, { "Lava Pirate", V3(-5478, 16, -5247) }, { "Venomous Assailant", V3(4731.27, 1090.18, 1078.17) } }
        local CS = game:GetService("CollectionService")
        local r = define({ key = "obs", cfg = "FullObs", title = "Auto Farm Observation", doneMsg = "Observation is at the maximum" })
        local numAt, num = -100, nil
        r.done = function()
            if os.clock() - numAt > 30 then numAt = os.clock(); num = kenNumber() end
            return num ~= nil and num >= 5000
        end
        local function ken()
            local rem = RS:FindFirstChild("Remotes")
            local ce = rem and rem:FindFirstChild("CommE")
            if ce then pcall(function() ce:FireServer("Ken", true) end) end
        end
        r.step = function(self)
            local char = Player.Character
            if char and not CS:HasTag(char, "Ken") and every("kenon", 3) then ken() end
            local left = tonumber(Player:GetAttribute("KenDodgesLeft")) or 0
            local max = tonumber(Player:GetAttribute("KenMaxDodges")) or 8
            local spot = SPOTS[getSea()]
            if not spot then self.S("wait", "No farm spot for this sea"); return false end
            local e = findEnemy({ spot[1] })
            local pct = num and math.clamp(num / 5000, 0, 1) or nil
            if e then
                local er = e:FindFirstChild("HumanoidRootPart")
                if er then
                    if left >= 1 then
                        self.S("run", string.format("Dodging %s (%d/%d dodges)", e.Name, math.floor(left), max), pct)
                        flyTo(er.CFrame * CFrame.new(3, 0, 0))
                    else
                        self.S("run", string.format("Out of dodges: waiting above %s", e.Name), pct)
                        flyTo(er.CFrame * CFrame.new(0, 50, 10))
                    end
                    if left <= 0.5 and every("kenlow", 3) then ken() end
                    return true
                end
            end
            self.S("run", "Going to the " .. spot[1] .. " spawn", pct)
            flyTo(CFrame.new(spot[2])); return true
        end
    end

    -- =====================================================================================================
    -- SOUL GUITAR (Mar 3, Haunted Castle, lua cheia, level 2300)  [Quantum: fn29 / AutoGetSkullGuitar]
    -- puzzles: Living Zombie (Swamp) -> placas do cemiterio -> Ghost -> Trophies (tabletes) -> Pipes (chao colorido) -> soulGuitarBuy
    -- material: 250 Ectoplasm (Ghost Ship, Mar 2) + 1 Dark Fragment (Darkbeard, Mar 2) quando o ultimo puzzle esta pronto
    -- =====================================================================================================
    do
        local SHIP_MOBS = { "Ship Deckhand", "Ship Engineer", "Ship Steward", "Ship Officer" }
        local SHIP = V3(923.213, 125.398, 32852.832)
        local PLACARDS = { Placard1 = "Right", Placard2 = "Right", Placard3 = "Left", Placard4 = "Right", Placard5 = "Left", Placard6 = "Left", Placard7 = "Left" }
        local TROPHIES = { Segment1 = "Trophy1", Segment3 = "Trophy2", Segment4 = "Trophy3", Segment7 = "Trophy4", Segment10 = "Trophy5" }
        local FLOOR = { Part1 = "Really black", Part2 = "Really black", Part3 = "Dusty Rose", Part4 = "Storm blue", Part5 = "Really black",
            Part6 = "Parsley green", Part7 = "Really black", Part8 = "Dusty Rose", Part9 = "Really black", Part10 = "Storm blue" }
        local r = define({ key = "guitar", cfg = "FullGuitar", title = "Auto Soul Guitar", doneMsg = "You have the Soul Guitar" })
        r.done = function() return owns("Soul Guitar") end
        local function castle()
            local m = workspace:FindFirstChild("Map")
            return m and m:FindFirstChild("Haunted Castle")
        end
        local function cd(x) return x and x:FindFirstChild("ClickDetector") end
        -- clica ate a condicao ficar verdadeira (no maximo 'n' cliques)
        local function clickUntil(detector, cond, n)
            for _ = 1, n or 12 do
                if cond() then return true end
                click(detector)
                task.wait(0.05)
            end
            return cond()
        end
        local function rotZ(tab) local l = tab and tab:FindFirstChild("Line"); return l and tonumber(l.Rotation.Z) or 0 end
        local function trophies(hc)
            local tab = hc:FindFirstChild("Tablet")
            if not tab then return end
            for _, seg in ipairs({ "Segment6", "Segment2", "Segment8", "Segment9", "Segment5" }) do
                local t = tab:FindFirstChild(seg)
                if t then clickUntil(cd(t), function() return math.abs(rotZ(t)) < 0.5 end) end
            end
            local tq = hc:FindFirstChild("Trophies")
            tq = tq and tq:FindFirstChild("Quest")
            for seg, trophy in pairs(TROPHIES) do
                local t, tr = tab:FindFirstChild(seg), tq and tq:FindFirstChild(trophy)
                local h = tr and tr:FindFirstChild("Handle")
                if t and h then
                    local _, _, _, r00 = h.CFrame:GetComponents()
                    local want = (math.abs(math.abs(r00) - 1) < 1e-3) and 90 or 180
                    clickUntil(cd(t), function() return math.abs(math.abs(rotZ(t)) - want) < 1 end)
                end
            end
        end
        local function pipes(hc)
            local lab = hc:FindFirstChild("Lab Puzzle")
            local cf = lab and lab:FindFirstChild("ColorFloor")
            local model = cf and cf:FindFirstChild("Model")
            if not model then return end
            for k, color in pairs(FLOOR) do
                local part = model:FindFirstChild(k)
                if part then clickUntil(cd(part), function() return part.BrickColor.Name == color end) end
            end
        end
        local function ghostShipMobs(self, n)
            self.S("run", string.format("Soul Guitar: Ectoplasm %d/250 (Ghost Ship)", n), math.clamp(n / 250, 0, 1) * 0.3)
            local _, hrp = getChar()
            if hrp and (hrp.Position - SHIP).Magnitude > 1000 then
                if every("gshipin", 4) then invoke("requestEntrance", SHIP) end
                return true
            end
            local e = findEnemy(SHIP_MOBS)
            if e then fightEnemy(e, { e.Name }, true); return true end
            flyTo(CFrame.new(SHIP + Vector3.new(0, 30, 0))); return true
        end
        r.step = function(self)
            local prog = F.guitarCache
            if not prog or os.clock() - prog.t > 3 then
                prog = { t = os.clock(), v = inv("GuitarPuzzleProgress", "Check") }
                F.guitarCache = prog
            end
            local p = type(prog.v) == "table" and prog.v or nil
            -- tudo pronto para comprar: precisa dos materiais do Mar 2
            if p and p.Pipes then
                local ecto = invCount("Ectoplasm")
                if ecto < 250 then
                    local wrong, busy = F.wrongSea(self, 2)
                    if wrong then return busy end
                    return ghostShipMobs(self, ecto)
                end
                if invCount("Dark Fragment") < 1 then
                    local wrong, busy = F.wrongSea(self, 2)
                    if wrong then return busy end
                    self.S("run", "Soul Guitar: getting a Dark Fragment (Darkbeard)", 0.3)
                    return F.R.darkbeard.step(F.R.darkbeard)
                end
            end
            local lv = getPlayerLevel()
            if lv < 2300 then self.S("wait", string.format("Needs level 2300 (you are %d)", lv)); return false end
            local phase = game:GetService("Lighting"):GetAttribute("MoonPhase")
            if phase ~= 5 then self.S("wait", "Waiting for the full moon (moon phase 5)"); return false end
            local wrong, busy = F.wrongSea(self, 3)
            if wrong then return busy end
            local hc = castle()
            if not p then
                self.S("run", "Soul Guitar: starting the graveyard event", 0.05)
                local at = V3(-8654, 141, 6169)
                if not near(at, 10) then flyTo(CFrame.new(at)); return true end
                if every("gravestart", 3) then inv("gravestoneEvent", 2, true) end
                return true
            end
            if not hc then
                self.S("run", "Flying to the Haunted Castle", 0.05)
                flyTo(CFrame.new(-9500, 100, 6100)); return true
            end
            if p.Pipes then
                self.S("run", "Soul Guitar: buying it", 0.95)
                local at = V3(-9680, 6, 6346)
                if not near(at, 5) then flyTo(CFrame.new(at)); return true end
                if every("guitarbuy", 3) then inv("soulGuitarBuy", true) end
                return true
            end
            if not p.Swamp then
                self.S("run", "Soul Guitar: killing Living Zombies (swamp)", 0.35)
                local e = findEnemy({ "Living Zombie" })
                if e then fightEnemy(e, { e.Name }, true); return true end
                local sp = findSpawn({ "Living Zombie" })
                if sp then flyTo(sp.CFrame * CFrame.new(0, 25, 0)) end
                return true
            end
            if not p.Gravestones then
                self.S("run", "Soul Guitar: gravestone placards", 0.5)
                local at = V3(-8800, 178, 6033)
                if not near(at, 10) then flyTo(CFrame.new(at)); return true end
                if every("placards", 3) then
                    for k, side in pairs(PLACARDS) do
                        local pl = hc:FindFirstChild(k)
                        local sd = pl and pl:FindFirstChild(side)
                        click(cd(sd))
                    end
                end
                return true
            end
            if not p.Ghost then
                self.S("run", "Soul Guitar: the ghost", 0.62)
                local at = V3(-9758, 270, 6291)
                if not near(at, 10) then flyTo(CFrame.new(at)); return true end
                if every("ghost", 3) then
                    inv("GuitarPuzzleProgress", "Ghost"); inv("GuitarPuzzleProgress", "Ghost", true)
                    task.wait(0.1)
                    F.guitarCache = nil
                end
                return true
            end
            if not p.Trophies then
                self.S("run", "Soul Guitar: trophy tablets", 0.75)
                local at = V3(-9529, 6, 6039)
                if not near(at, 10) then flyTo(CFrame.new(at)); return true end
                if every("trophies", 4) then trophies(hc); F.guitarCache = nil end
                return true
            end
            self.S("run", "Soul Guitar: lab floor colours", 0.88)
            local at = V3(-9576, 6, 6230)
            if not near(at, 10) then flyTo(CFrame.new(at)); return true end
            if every("pipes", 4) then pipes(hc); F.guitarCache = nil end
            return true
        end
    end

    -- =====================================================================================================
    -- FULLY MIRROR FRACTAL (Mar 3)  [v26]: entra direto num servidor com Dough King pela API do Quantum e mata ele. Sempre.
    -- =====================================================================================================
    do
        local r = define({ key = "mirror", cfg = "FullMirror", title = "Auto Fully Mirror Fractal", sea = 3 })
        local FALLBACK = V3(-2077, 252, -12373)
        local function mirrorPos()
            local m = workspace:FindFirstChild("Map")
            local cl = m and m:FindFirstChild("CakeLoaf")
            local bm = cl and cl:FindFirstChild("BigMirror")
            local mn = bm and bm:FindFirstChild("Main")
            return mn and mn:IsA("BasePart") and mn.Position or FALLBACK
        end
        local function king() return findEnemy({ "Dough King" }) end
        r.step = function(self)
            local boss = king()
            if boss then
                self.S("run", "Killing the Dough King", 0.8)
                F.mirrorKills = F.mirrorKills or 0
                fightEnemy(boss, { boss.Name }, false)
                F.mirrorSeen = true
                return true
            end
            if F.mirrorSeen then F.mirrorSeen = nil; F.mirrorKills = (F.mirrorKills or 0) + 1 end
            -- vai ate o espelho antes de procurar (chega perto do boss quando ele carrega)
            local at = mirrorPos()
            if not near(at, 60) and not (AFL.Hop and AFL.Hop.active) and not (AFL.QApi and AFL.QApi.joining) then
                self.S("run", "Flying to the Mirror Fractal", 0.4)
                flyTo(CFrame.new(at.X, at.Y + 30, at.Z)); return true
            end
            self.S("run", "No Dough King here: joining a server that has one (kills " .. (F.mirrorKills or 0) .. ")", 0.2)
            AFL.apiJoin("DoughKing", function() return king() ~= nil end, "Dough King")
            return true
        end
    end
end

-- ================================================================ aba Auto Fully (v24) ====
-- Todas as funcoes "faz tudo sozinho" num lugar so: estado ao vivo, opcoes comuns, racas, espadas, bosses, haki e eventos.
-- As opcoes que ja existem em outras abas (Ghoul, Cyborg, CDK, TTK, Vulcan...) aparecem aqui como o MESMO botao (ficam em sincronia).
do
    local T = Tabs.Fully
    local F = AFL.Fully
    local TG = {}                                              -- interruptores (para o texto "ao vivo")
    local function tg(id, title, desc)
        local o = T:AddToggle(id, { Title = title, Description = desc, Default = Config[id] and true or false, NoBadge = (id == "FullTravel" or id == "FullHop" or string.find(id, "Hop$") ~= nil) })
        o:OnChanged(function(v) Config[id] = v; persist() end)
        TG[id] = o
        return o
    end
    local function note(text, secs)
        pcall(function() Fluent:Notify({ Title = "Auto Fully", Content = text, Duration = secs or 4 }) end)
    end
    local ALLKEYS = { "RaceGhoul", "RaceCyborg", "RaceV2", "RaceV3", "RaceLever", "SubYama", "SubTushita", "SubCDK", "SubFullTTK", "VulcFull", "FullKitsune" }
    for _, r in ipairs(F.list) do ALLKEYS[#ALLKEYS + 1] = r.cfg end

    -- ------------------------------------------------------------------ estado ao vivo ----
    T:AddSection("Live Status")
    local sNow = T:AddStatus({ Title = "Auto Fully Engine", Content = "Checking..." })
    local sStats = T:AddStats({ Labels = { "Enabled", "Running", "Done", "Waiting" } })

    -- ---------------------------------------------------------------------- opcoes ----
    T:AddSection("General Settings")
