    tg("FullHop", "Server Hop When Needed", "Changes server when a boss, ship mobs or chests are not here")
    T:AddSlider("FullChestCount", { Title = "Chests Before Hop", Description = "Chests collected in a server before it hops (Fist of Darkness, Chalice)",
        Min = 5, Max = 60, Default = math.clamp(tonumber(Config.FullChestCount) or 20, 5, 60), Rounding = 0 })
        :OnChanged(function(v) Config.FullChestCount = v; persist() end)

    -- ---------------------------------------------------------------------- racas ----
    T:AddSection("Races")
