    tg("RaceGhoul", "Auto Fully Ghoul", "Ectoplasm > Cursed Captain > Hellfire Torch > buys Ghoul")
    tg("RaceGhoulHop", "Ghoul: Server Hop", "Sea 2 only: hops (Auto Bounty system) when there are no ship mobs. Captain server: Quantum API")
    local sCyborg = T:AddStatus({ Title = "Cyborg Progress", Content = "Checking...", Height = 58 })
    tg("RaceCyborg", "Auto Fully Cyborg", "20 chests on every Sea 2 island > Fist of Darkness > Law raid > Core Brain > buys")
    tg("RaceCyborgHop", "Cyborg: Chest Server Hop", "Hops to servers with 4h+ uptime (more chests) and keeps hopping on empty chests, until the Fist of Darkness drops")
    T:AddSubSection("Upgrades")
    tg("RaceV2", "Auto Upgrade Race V2", "Alchemist quest: 3 flowers (night), needs 500k Beli. Sea 2")
    tg("RaceV3", "Auto Upgrade Race V3", "Wenlocktoad quest (level 1000, 2M Beli)")
    tg("RaceLever", "Auto Fully V4 (Pull Lever)", "Finds the Blue Gear on Mirage, opens the temple, pulls the lever")

    -- ------------------------------------------------------------------- espadas ----
    T:AddSection("Swords")
    tg("FullSaber", "Auto Saber", "Sea 1: plates, torch, cup, Mob Leader, relic and the Saber Expert")
    tg("FullRengoku", "Auto Rengoku", "Sea 2: farms the Hidden Key and opens the Ice Castle door")
    tg("SubFullTTK", "Auto Fully TTK", "Buys Shizu, Saishi and Oroshi (Quantum API server), trains them, buys the TTK")
    T:AddSubSection("Cursed Dual Katana")
    tg("SubYama", "Auto Fully Yama", "Sea 3: hops until 30 Elite Hunters are dead, then takes the Yama")
    tg("SubTushita", "Auto Fully Tushita", "Sea 3: Hydra Island > Rip_Indra server (Quantum API) > Tushita puzzle")
    tg("SubCDK", "Auto Fully CDK", "Tushita, then Yama, 400 mastery on both, then all the trials")

    -- -------------------------------------------------------------------- bosses ----
    T:AddSection("Bosses")
    tg("FullDarkbeard", "Auto Darkbeard", "Sea 2: chests > Fist of Darkness > summons and kills Darkbeard")
    tg("FullCursed", "Auto Cursed Captain", "Sea 2: Ghost Ship, kills the Cursed Captain (hops if he is not up)")
    tg("FullRip", "Auto Rip Indra", "Sea 3: Chalice > Haki pads > summons and kills rip_indra True Form")
    tg("FullLaw", "Auto Law Raid", "Sea 2: buys a Microchip, starts the Law raid and kills Order")
    tg("FullMirror", "Auto Fully Mirror Fractal", "Sea 3: Dough King server (Quantum API) > Mirror Fractal > kills it. Always")

    -- ------------------------------------------------------------- haki e habilidades ----
    T:AddSection("Haki & Skills")
    tg("FullRainbow", "Auto Rainbow Haki", "Sea 3: Horned Man bets + the 5 boss quests")
    tg("FullKenV2", "Auto Observation V2", "Sea 3: Citizen quest, 3 fruits, Fruit Bowl, Ken (needs 5M Beli)")
    tg("FullObs", "Auto Farm Observation", "Stays next to a mob so you dodge and level up Observation")
    tg("FullGuitar", "Auto Soul Guitar", "Sea 3, level 2300, full moon: Haunted Castle puzzles, then buys it")

    -- ------------------------------------------------------------------- eventos ----
    T:AddSection("Events")
    tg("VulcFull", "Auto Fully Vulcan", "Magnet items > sail > find the island > start it > eggs & bones")
    T:AddSubSection("Kitsune Island")
    tg("FullKitsune", "Auto Fully Kitsune Island", "")
    do
        local boatValues = { "Guardian", "Lantern", "Beast Hunter", "Sleigh", "Brigade", "Grand Brigade" }
        local bi = 1
        for i, n in ipairs(boatValues) do if n == Config.KitBoat then bi = i end end
        T:AddDropdown("KitBoat", { Title = "Kitsune: Boat To Buy", Values = boatValues, Default = bi,
            Description = "" })
            :OnChanged(function(v) Config.KitBoat = tostring(v); persist() end)
    end
    T:AddSlider("KitSpeed", { Title = "Kitsune: Tween Speed (Boat)", Description = "Boat speed to zone 6 and to the island (100-500)", Min = 100, Max = 500, Default = math.clamp(tonumber(Config.KitSpeed) or 200, 100, 500), Rounding = 0 })
        :OnChanged(function(v) Config.KitSpeed = math.floor(v); persist() end)
    T:AddSlider("KitAzure", { Title = "Kitsune: Azure Ember Amount To Trade", Description = "   ", Min = 1, Max = 50, Default = math.clamp(tonumber(Config.KitAzure) or 10, 1, 50), Rounding = 0 })
        :OnChanged(function(v) Config.KitAzure = math.floor(v); persist() end)
    AFL.kiPara = T:AddParagraph({ Title = "Kitsune Status", Content = "..." })

    -- ------------------------------------------------------------------- atalhos ----
    T:AddSection("Shortcuts")
