        local n = 0
        for _, id in ipairs(ALLKEYS) do
            if Config[id] then
                n += 1
                local o = Fluent.Options[id]
                if o and o.SetValue then o:SetValue(false) else Config[id] = false end
            end
        end
        persist()
        AFL.goStop()
        note(n > 0 and (n .. " function(s) turned off") or "Nothing was on", 3)
    end })
    T:AddButton({ Title = "Forget Observation V2 Progress", Description = "Use it if the script thinks Observation V2 is done and it is not", Label = "Reset", Callback = function()
        Config.FullKenDone = false; persist()
        note("Observation V2 progress forgotten", 3)
    end })
    T:AddButton({ Title = "Fly To The Horned Man", Description = "Hydra Island (Rainbow Haki)", Label = "Go", Callback = function()
        AFL.goDo("Horned Man", Vector3.new(-11892, 931, -8761), function() task.wait(0.3) end, 12)
    end })
    T:AddButton({ Title = "Fly To The Citizen", Description = "Floating Turtle (Observation V2 quest)", Label = "Go", Callback = function()
        AFL.goDo("Citizen", Vector3.new(-12445, 332, -7676), function() task.wait(0.3) end, 12)
    end })
    T:AddButton({ Title = "Fly To The Haunted Castle", Description = "Soul Guitar puzzles (Sea 3)", Label = "Go", Callback = function()
        AFL.goDo("Haunted Castle", Vector3.new(-9500, 100, 6100), function() task.wait(0.3) end, 40)
    end })
    T:AddButton({ Title = "Stop Flying", Description = "Cancels a shortcut that is still flying", Label = "Stop", Callback = function() AFL.goStop() end })

    -- ------------------------------------------------------------ atualizacao ao vivo ----
    local STATE = { run = "ok", done = "ok", wait = "warn", err = "bad", idle = "info", off = "off" }
    local function liveText(r)
        if not Config[r.cfg] then return nil end
        if r.state == "done" then return "Done: " .. (r.doneMsg or "finished") end
        if r.state == "idle" then return "Waiting for its turn" end
        if r.state == "off" then return nil end
        return r.msg
    end
    local function raceCard(card, key, label)
        local R = rawget(AFL, "Race")
        local st = R and R.st and R.st[key]
        local on = Config[key == "ghoul" and "RaceGhoul" or "RaceCyborg"]
        if not on then
            card:Set("off", nil, "Off. Turn it on below and it does everything by itself", "OFF")
        elseif not st then
            card:Set("info", nil, "Waiting for its turn", "READY")
        else
            card:Set(st.state or "info", nil, st.msg or "...", st.pill or "WORKING")
        end
    end
    local function refresh()
        -- cartao principal
        local on, done, run = F.counts()
        local waiting = 0
        for _, r in ipairs(F.list) do if Config[r.cfg] and (r.state == "wait" or r.state == "idle") then waiting += 1 end end
        local extra = 0
        for _, id in ipairs({ "RaceGhoul", "RaceCyborg", "RaceV2", "RaceV3", "RaceLever", "SubYama", "SubTushita", "SubCDK", "SubFullTTK", "VulcFull", "FullKitsune" }) do
            if Config[id] then extra += 1 end
        end
        local total = on + extra
        if total == 0 then
            sNow:Set("off", "Auto Fully Engine", "Turn on any function below. Each one does the whole job by itself", "IDLE")
        elseif Core.owner == "Auto Fully" and F.cur then
            sNow:Set("ok", "Auto Fully Engine", F.cur.title .. ": " .. tostring(F.cur.msg), "RUNNING")
        elseif Core.owner then
            sNow:Set("info", "Auto Fully Engine", tostring(Core.owner) .. " has the character right now. Auto Fully takes over when it has something to do", "STANDBY")
        elseif on > 0 then
            local firstWait
            for _, r in ipairs(F.list) do if Config[r.cfg] and r.state == "wait" then firstWait = r break end end
            sNow:Set(firstWait and "warn" or "info", "Auto Fully Engine", firstWait and (firstWait.title .. ": " .. tostring(firstWait.msg)) or "Ready", firstWait and "WAITING" or "READY")
        else
            sNow:Set("info", "Auto Fully Engine", "Ready: the races / swords / events you turned on run from their own tabs", "READY")
        end
        sStats:Set({ total, run, done, waiting })
        -- linha ao vivo de cada interruptor
        for _, r in ipairs(F.list) do
            local o = TG[r.cfg]
            if o then o:SetLive(liveText(r)) end
        end
        local R = rawget(AFL, "Race")
        raceCard(sGhoul, "ghoul")
        raceCard(sCyborg, "cyborg")
        if TG.RaceGhoul then TG.RaceGhoul:SetLive(Config.RaceGhoul and R and R.st and R.st.ghoul and R.st.ghoul.msg or nil) end
        if TG.RaceCyborg then TG.RaceCyborg:SetLive(Config.RaceCyborg and R and R.st and R.st.cyborg and R.st.cyborg.msg or nil) end
        if TG.VulcFull then TG.VulcFull:SetLive(Config.VulcFull and tostring(Diag.vulc or "") ~= "" and tostring(Diag.vulc) or nil) end
        -- CDKfix: mostra na aba Fully o que o Sub Farm (Yama / Tushita / CDK / TTK) esta fazendo agora
        for _, id in ipairs({ "SubYama", "SubTushita", "SubCDK", "SubFullTTK" }) do
            local o = TG[id]
            if o then
                pcall(function()
                    local sf = rawget(AFL, "Sub")
                    local s = sf and sf.status
                    o:SetLive((Config[id] and s and tostring(s) ~= "") and tostring(s) or nil)
                end)
            end
        end
    end
    local warned = false
    task.spawn(function()
        task.wait(0.6)
        while Alive do
            local vis = T:IsVisible()
            if vis then
                local ok, e = pcall(refresh)
                if not ok and not warned then warned = true; AFL.logErr("fully ui", e) end
            end
            task.wait(vis and 1.2 or 0.8)
        end
    end)
end



