-- ===================================================== relatorio de depuracao (aba Status Server/Script) ====
-- Mostra os ultimos erros do script e copia um relatorio completo (para mandar quando algo nao funcionar).
do
    local AFL, ST, Diag, M, Core = PC.AFL, PC.State, PC.Diag, PC.M, PC.Core
    local stTab
    for _, t in ipairs(tabs) do if t.name == "Status Server/Script" then stTab = t end end
    if stTab then
        local tab = PC.mkTabObj(stTab, 9000)
        local function errLines(n)
            local L, out = AFL.Err.list, {}
            for i = math.max(1, #L - n + 1), #L do
                local e = L[i]
                out[#out + 1] = string.format("[%s] %s: %s", e.t, tostring(e.key), string.sub(tostring(e.msg), 1, 220))
            end
            return out
        end
        local function modLines()
            local out = {}
            for _, name in ipairs(PC.order) do
                local st = PC.loaded[name]
                if st == true then out[#out + 1] = name .. ": loaded"
                elseif st == false then out[#out + 1] = name .. ": FAILED - " .. string.sub(tostring(PC.err[name]), 1, 200)
                elseif st == "loading" then out[#out + 1] = name .. ": loading" end
            end
            return out
        end
        local function report()
            local L = { "Moon Hub [ " .. TIER_LABEL .. " ] - debug report", "time: " .. os.date("%Y-%m-%d %H:%M:%S") }
            local ex = "?"
            pcall(function() if identifyexecutor then local a, b = identifyexecutor(); ex = tostring(a) .. (b and (" " .. tostring(b)) or "") end end)
            L[#L + 1] = "executor: " .. ex
            local lvl, sea = "?", "?"
            pcall(function() lvl = tostring(LP.Data.Level.Value) end)
            pcall(function() sea = tostring(PC.getSea()) end)
            L[#L + 1] = string.format("place: %s | sea: %s | level: %s | job: %s", tostring(game.PlaceId), sea, lvl, tostring(game.JobId))
            L[#L + 1] = string.format("mode: %s | %s | owner: %s | busy: %s", tostring(ST.Mode), tostring(ST.Text), tostring(Core.owner), tostring(ST.Busy))
            pcall(function() L[#L + 1] = "priority: " .. table.concat(Core.priorityOrder(), " > ") end)
            L[#L + 1] = string.format("cfg: tool=%s method=%s cps=%s range=%s tween=%s height=%s bring=%s", tostring(cfg.tool), tostring(cfg.method), tostring(cfg.cps), tostring(cfg.range), tostring(cfg.tspeed), tostring(cfg.height), tostring(cfg.bringN))
            pcall(function()                                                -- velocidades (todas devem estar em 200 por padrao)
                local m = type(cfg.m) == "table" and cfg.m or {}
                L[#L + 1] = string.format("speeds: tween=%s island=%s boat=%s flyboat=%s leviathan=%s | flytween=%s | cps=%s", tostring(cfg.tspeed), tostring(m.IslandSpeed), tostring(m.SeaSpeed), tostring(m.SeaFlySpeed), tostring(m.LevSpeed), tostring(cfg.flytween), tostring(cfg.cps))
            end)
            pcall(function()                                                -- voo e alvos fantasma
                local ms = Core.moveStat or {}
                L[#L + 1] = string.format("movement: rollbacks=%s | ghost targets skipped=%s | targets=%s", tostring(ms.rollbacks or 0), tostring(Core.ghostCount or 0), type(cfg.targets) == "table" and ((cfg.targets.NPC and "NPC " or "") .. (cfg.targets.BOSS and "BOSS " or "") .. (cfg.targets.PLAYER and "PLAYER" or "")) or "?")
            end)
            pcall(function()                                                -- aparencia
                local nf = 0
                for _, v in pairs(type(cfg.fold) == "table" and cfg.fold or {}) do if v then nf += 1 end end
                local cur = TH.cur or {}
                L[#L + 1] = string.format("ui: row icons=%s | window corners=%s px | roundness=x%s | folded sections=%d | theme=%s", tostring(cfg.rowIcons), tostring(SHAPE.R), tostring(cur.round or 1), nf, tostring(cfg.theme))
            end)
            L[#L + 1] = "-- modules"
            for _, s in ipairs(modLines()) do L[#L + 1] = s end
            L[#L + 1] = "-- options ON"
            local on = {}
            for k, v in pairs(M) do if v == true then on[#on + 1] = k end end
            table.sort(on)
            L[#L + 1] = #on > 0 and table.concat(on, ", ") or "none"
            L[#L + 1] = "-- errors (last 20)"
            local es = errLines(20)
            for _, s in ipairs(es) do L[#L + 1] = s end
            if #es == 0 then L[#L + 1] = "none" end
            L[#L + 1] = "-- diag"
            local keys = {}
            for k in pairs(Diag) do keys[#keys + 1] = tostring(k) end
            table.sort(keys)
            for _, k in ipairs(keys) do
                local v = Diag[k]
                L[#L + 1] = k .. ": " .. string.sub(tostring(v), 1, 200)
            end
            return table.concat(L, "\n")
        end
        PC.debugReport = report

        tab:AddSection("Debug")
        local pm = tab:AddParagraph({ Title = "Modules", Content = "..." })
        local pe = tab:AddParagraph({ Title = "Last errors", Content = "none" })
        tab:AddButton({ Title = "Copy Debug Report", Description = "Copies modules, errors, options and diagnostics. Send it if something does not work", Callback = function()
            local txt = report()
            local ok = false
            if setclipboard then ok = pcall(setclipboard, txt) end
            notify(ok and "Debug report copied" or "Could not copy", ok and "Paste it in the chat with the staff." or "Your executor has no clipboard function.", ok and "ok" or "bad", 3)
        end })
        tab:AddButton({ Title = "Clear Errors", Description = "Empties the error list", Callback = function()
            local L = AFL.Err.list
            for i = #L, 1, -1 do L[i] = nil end
            AFL.Err.count, AFL.Err.quar = {}, {}
        end })
        task.spawn(function()
            while alive do
                task.wait(3)
                pcall(function()
                    local m = modLines()
                    pm:SetDesc(#m > 0 and table.concat(m, "\n") or "No extra module loaded yet (they load when you open their tab or turn a function on)")
                    local es = errLines(6)
                    pe:SetDesc(#es > 0 and table.concat(es, "\n") or "none")
                end)
            end
        end)
    end
end

-- ====================================================== aba Script Settings ====
local sett = addTab("Script Settings", ICON.settings)
local tgl = {}
do
    local B = sett.body
    section(B, "Configs", 1)
    tgl.autosave = mkToggle(B, ICON.save, "Auto Save Script", "Saves your settings and loads them next time", 2, cfg.autosave, function(v)
        cfg.autosave = v
        if writefile then pcall(writefile, CFG_FILE, HttpService:JSONEncode(cfg)) end   -- grava o estado (ligado ou desligado)
        notify("Auto Save", v and "Your settings will be saved." or "Auto save is off.", v and "ok" or "warn", 2.5)
    end)

    -- Toggle UI (tecla + botao)
    do
        local r = row(B, ICON.keyboard, "Toggle UI", "Show / hide the hub with a key", 56, 3)
        ORG.R(r, 202)
        local tbtn = smallButton(r, "Toggle", 66, UDim2.new(1, -80, 0.5, -14), true)
        local kbtn = smallButton(r, cfg.toggleKey, 104, UDim2.new(1, -192, 0.5, -14), false)
        local capturing = false
        kbtn.MouseButton1Click:Connect(function() capturing = true; kbtn.Text = "Press a key..." end)
        tbtn.MouseButton1Click:Connect(function() setOpen(not isOpen) end)
        table.insert(conns, UIS.InputBegan:Connect(function(i, gp)
            if i.UserInputType ~= Enum.UserInputType.Keyboard then return end
            if capturing then
                capturing = false
                if i.KeyCode ~= Enum.KeyCode.Escape then cfg.toggleKey = i.KeyCode.Name; persist() end
                kbtn.Text = cfg.toggleKey
                return
            end
            if not gp and i.KeyCode.Name == cfg.toggleKey then setOpen(not isOpen) end
        end))
    end

    section(B, "General", 4)
    tgl.antiafk = mkToggle(B, ICON.hourglass, "Anti AFK", "Stops the game from kicking you for being idle", 5, cfg.antiafk, function(v)
        cfg.antiafk = v; persist(); FX.antiafk(v)
    end)
    tgl.rejoin = mkToggle(B, ICON.repeatI, "Auto Rejoin", "Reconnects you automatically if you get disconnected", 6, cfg.rejoin, function(v)
        cfg.rejoin = v; persist(); FX.rejoin(v)
    end)
    tgl.events = mkToggle(B, ICON.bell, "Event Notifications", "Alerts for Full Moon, Mirage, Kitsune and more", 7, cfg.events, function(v)
        cfg.events = v; persist(); FX.events(v, true)
        if v then notify("Events", "Watching for server events.", "ok", 2.5) end
    end)

    section(B, "Boosters FPS", 8)
    tgl.fps1 = mkToggle(B, ICON.gauge, "Booster Fps", "Removes textures", 9, cfg.fps == 1, function(v)
        if v then tgl.fps2.set(false, true) end
        cfg.fps = v and 1 or 0; persist(); FX.fps(cfg.fps)
    end)
    tgl.fps2 = mkToggle(B, ICON.rocket, "Super Booster Fps", "Removes textures and effects", 10, cfg.fps == 2, function(v)
        if v then tgl.fps1.set(false, true) end
        cfg.fps = v and 2 or 0; persist(); FX.fps(cfg.fps)
    end)
    tgl.fog = mkToggle(B, ICON.fog, "Remove Fog", "Clears the fog for a clear view", 11, cfg.fog, function(v)
        cfg.fog = v; persist(); FX.fog(v)
    end)

    section(B, "Themes", 12)
    local holder = new("Frame", { Size = UDim2.new(1, 0, 0, math.ceil(#THEME_ORDER / 3) * 96), BackgroundTransparency = 1, LayoutOrder = 13, ZIndex = 4 }, B)
    local cards = {}
    local function renderThemes()
        for n, c in pairs(cards) do
            local on = n == TH.name
            tween(c.st, 0.25, { Color = on and TH.cur.acc or TH.cur.rowS, Transparency = on and 0 or TH.cur.rowST, Thickness = on and 2 or 1 })
            tween(c.chk, 0.25, { ImageTransparency = on and 0 or 1 })
        end
    end
    for i, name in ipairs(THEME_ORDER) do
        local th = THEMES[name]
        local c = new("TextButton", { Size = UDim2.new(1 / 3, -8, 0, 88), Position = UDim2.new(((i - 1) % 3) / 3, 0, 0, math.floor((i - 1) / 3) * 96), BorderSizePixel = 0, Text = "", AutoButtonColor = false, ZIndex = 5 }, holder)
        bind(c, "BackgroundColor3", "row"); bind(c, "BackgroundTransparency", "rowT")
        corner(c, 11)
        local st = stroke(c, C.white, 1, 0.9)
        local sw = new("Frame", { Size = UDim2.new(1, -16, 0, 44), Position = UDim2.fromOffset(8, 8), BackgroundColor3 = th.prev, BackgroundTransparency = (name == "Water" and 0.45) or (th.tintA and 0.15) or 0, BorderSizePixel = 0, ZIndex = 6 }, c)
        corner(sw, 8); stroke(sw, name == "Full White" and Color3.fromRGB(190, 194, 210) or C.white, 1, 0.6)
        if th.tintA and name ~= "Dog Manin" then grad(sw, th.tintA, th.tintB, 35) end
        if name == "Water" then grad(sw, Color3.fromRGB(150, 210, 255), Color3.fromRGB(70, 140, 230), 45) end
        if name == "Default" then grad(sw, Color3.fromRGB(52, 54, 64), Color3.fromRGB(28, 29, 34), 45) end
        local swImg
        if name == "Dog Manin" then
            grad(sw, Color3.fromRGB(255, 214, 102), Color3.fromRGB(60, 54, 58), 20)
            swImg = new("ImageLabel", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, ScaleType = Enum.ScaleType.Crop, Image = "", ZIndex = 7 }, sw)
            corner(swImg, 8)
        end
        local chk = new("ImageLabel", { Size = UDim2.fromOffset(16, 16), Position = UDim2.new(1, -22, 0, 6), BackgroundTransparency = 1, Image = ICON.check, ImageColor3 = name == "Full White" and C.blue or C.white, ImageTransparency = 1, ZIndex = 8 }, sw)
        text(c, { Position = UDim2.fromOffset(0, 58), Size = UDim2.new(1, 0, 0, 26), Text = name, TextSize = 11, TextXAlignment = Enum.TextXAlignment.Center, ZIndex = 6 })
        cards[name] = { st = st, chk = chk, img = swImg, sw = sw }
        UI.press(c)
        c.MouseButton1Click:Connect(function()
            if TH.name == name then return end
            TH.apply(name)
            cfg.theme = name; persist()
            renderThemes()
        end)
    end
    table.insert(TH.hooks, function() renderThemes(); if cards.Custom then cards.Custom.sw.BackgroundColor3 = THEMES.Custom.win end end)
    renderThemes()
    UIX.button(B, ICON.palette, "Build Your Theme!", "Change the color of everything: gradient, border, letters and more", 14, "Open", function() selectTab(BLD.tab) end)
    tgl.dogSw = cards["Dog Manin"] and cards["Dog Manin"].img

    -- v24: velocidade das animacoes do hub
    section(B, "Interface", 15)
    tgl.anim = UIX.select(B, ICON.gauge, "Animations", "Off = instant (lighter on weak phones), Slow = relaxed", 16,
        { "Off", "Fast", "Normal", "Slow" }, cfg.anim, false, function(v)
            UI.setSpeed(v); persist()
            if v ~= "Off" then notify("Animations", v .. " speed", "ok", 1.8) end
        end)
    -- v89: UI Scale - resize a janela inteira (menor = mais leve/discreta num celular fraco, maior = telao/baixa visao)
    UIX.slider(B, ICON.gauge, "UI Scale", "Resizes the whole hub window", 17, 70, 130, math.clamp(tonumber(cfg.uiScale) or 100, 70, 130), function(v)
        cfg.uiScale = v; persist(); UI.setScale(v)
    end, function(v) return string.format("%d%%", v) end)

    -- v90: Config Profiles - varios setups salvos (ex: "Leveling", "Sea Events") pra trocar rapido sem perder nada
    section(B, "Config Profiles", 18)
    local function profOptions()
        local names = profileNames()
        return #names > 0 and names or { "(none yet)" }
    end
    local profNameBox = UIX.input(B, ICON.save, "Profile Name", "Type a name, then press \"Save As New Profile\" below", 19, "", "e.g. Leveling", false)
    local dProf = UIX.select(B, ICON.layers, "Saved Profiles", "Pick a profile to load or delete", 20, profOptions(), profOptions()[1], false, function() end)
    local function refreshProfiles()
        local opts = profOptions()
        dProf.setOptions(opts)
        if not profiles[dProf.value] then dProf.set(opts[1]) end
    end
    UIX.button(B, ICON.save, "Save As New Profile", "Saves EVERYTHING (every tab) under the name typed above - overwrites if that name already exists", 21, "Save", function()
        local name = (profNameBox.get() or ""):gsub("^%s+", ""):gsub("%s+$", "")
        if name == "" or name == "(none yet)" then notify("Config Profiles", "Type a name first.", "warn", 3); return end
        local ok, snap = pcall(function() return HttpService:JSONDecode(HttpService:JSONEncode(cfg)) end)
        if not ok then notify("Config Profiles", "Could not save this profile.", "warn", 3); return end
        profiles[name] = snap
        saveProfilesFile()
        refreshProfiles(); dProf.set(name)
        notify("Config Profiles", "Saved as \"" .. name .. "\".", "ok", 3)
    end)
    UIX.button(B, ICON.refresh, "Load Selected Profile", "Replaces EVERYTHING (every tab) with the saved profile above - reopen the tabs (or re-run the script) after, so the screen updates too", 22, "Load", function()
        local p = profiles[dProf.value]
        if not p then notify("Config Profiles", "No profile selected.", "warn", 3); return end
        for k, v in pairs(p) do if cfg[k] ~= nil then cfg[k] = v end end
        persist()
        notify("Config Profiles", "Loaded \"" .. tostring(dProf.value) .. "\". Reopen the tabs (or re-run the script) so the screen updates too.", "ok", 5)
    end)
    UIX.button(B, ICON.x, "Delete Selected Profile", "Permanently deletes the saved profile above", 23, "Delete", function()
        if not profiles[dProf.value] then notify("Config Profiles", "No profile selected.", "warn", 3); return end
        local name = dProf.value
        profiles[name] = nil
        saveProfilesFile()
        refreshProfiles()
        notify("Config Profiles", "Deleted \"" .. tostring(name) .. "\".", "ok", 3)
    end)
end

-- imagem do tema Dog Manin (vem do servidor; fica em cache no disco)
local dogAsset
local function loadDogAsset()
    if dogAsset then return dogAsset end
    local fn = "MoonHub_theme_dogmanin.png"
    pcall(function() if isfile and isfile(fn) and getcustomasset then dogAsset = getcustomasset(fn) end end)
    if dogAsset then return dogAsset end
    if not httpFn or not writefile or not getcustomasset then return nil end
    local ok, r = pcall(httpFn, { Url = (S.base or "") .. "/v2/asset", Method = "POST", Headers = { ["Content-Type"] = "application/json" }, Body = HttpService:JSONEncode({ token = State.token, name = "dogmanin" }) })
    if ok and r and r.StatusCode == 200 and r.Body and #r.Body > 2000 and r.Body:sub(2, 4) == "PNG" then
        if pcall(writefile, fn, r.Body) then
            local ok2, a = pcall(getcustomasset, fn)
            if ok2 then dogAsset = a end
        end
    end
    return dogAsset
end
local function applyBackground()
    if TH.cur.image then
        task.spawn(function()
            local a = loadDogAsset()
            if not a then notify("Dog Manin", "Could not load the theme image.", "warn", 4); return end
            if TH.cur.image then
                bgImg.Image = a; bgImg.Visible = true; bgImg.ImageTransparency = 1
                tween(bgImg, 0.7, { ImageTransparency = 0.1 })
            end
            if tgl.dogSw then tgl.dogSw.Image = a end
        end)
    else
        tween(bgImg, 0.3, { ImageTransparency = 1 })
        task.delay(0.32, function() if not TH.cur.image then bgImg.Visible = false end end)
    end
end
table.insert(TH.hooks, applyBackground)

