    bind(profileCard, "BackgroundColor3", "card"); bind(profileCard, "BackgroundTransparency", "cardT")
    SHAPE.add(corner(profileCard, 16))         -- acompanha o raio da janela (Build Your Theme! > Window corners)
    local ps = stroke(profileCard, C.white, 1.2, 0.5); ui.cardG = grad(ps, C.white, C.blue, 0)
    -- banner: o banner personalizado do Discord; sem banner = sem cor nenhuma
    if State.user.bannerAsset then
        local bn = new("ImageLabel", { Size = UDim2.new(1, 0, 0, 104), BackgroundTransparency = 1, Image = State.user.bannerAsset, ScaleType = Enum.ScaleType.Crop, BorderSizePixel = 0, ZIndex = 31 }, profileCard)
        -- banner animado (gif): o bot manda uma folha de frames e o hub toca em loop
        local an = State.user.banner_anim
        if type(an) == "table" and an.sheet and (tonumber(an.frames) or 0) > 1 and httpFn and writefile and getcustomasset then
            task.spawn(function()
                local ok = pcall(function()
                    local fn = "MoonHub_BannerSheet_" .. tostring(State.user.id) .. "_" .. tostring(an.ver or 0) .. ".png"
                    if not (isfile and isfile(fn)) then
                        local r = httpFn({ Url = an.sheet, Method = "GET" })
                        if not (r and r.Body and #r.Body > 200) then error("sheet") end
                        writefile(fn, r.Body)
                    end
                    local sheet = getcustomasset(fn)
                    local fw, fh, cols, n = an.fw, an.fh, an.cols, an.frames
                    bn.Image = sheet
                    bn.ScaleType = Enum.ScaleType.Crop
                    bn.ImageRectSize = Vector2.new(fw, fh)
                    local i = 0
                    while bn.Parent and ui.alive ~= false do
                        bn.ImageRectOffset = Vector2.new((i % cols) * fw, math.floor(i / cols) * fh)
                        local d = (tonumber(an.delays and an.delays[i + 1]) or 80) / 1000
                        i = (i + 1) % n
                        if profileCard.Visible then task.wait(math.max(0.05, d)) else task.wait(0.4) end
                    end
                end)
                if not ok then pcall(function() bn.ImageRectSize = Vector2.new(0, 0); bn.Image = State.user.bannerAsset end) end
            end)
        end
    end
    -- botao X: no celular o card cobre o botao do perfil, entao precisa de uma saida dentro do proprio card
