    corner(ui.cardClose, 20)
    local ring = new("Frame", { Size = UDim2.fromOffset(96, 96), Position = UDim2.fromOffset(20, 52), BorderSizePixel = 0, ZIndex = 33 }, profileCard)
    bind(ring, "BackgroundColor3", "card"); corner(ring, 48)
    local av = new("ImageLabel", { Size = UDim2.fromOffset(86, 86), Position = UDim2.fromOffset(5, 5), BackgroundColor3 = Color3.fromRGB(58, 60, 72), BorderSizePixel = 0, Image = State.user.avatarAsset or "", ZIndex = 34 }, ring)
    corner(av, 43)
