        text(av, { Size = UDim2.fromScale(1, 1), Text = string.upper(string.sub(State.user.display or "U", 1, 1)), TextSize = 34, TextXAlignment = Enum.TextXAlignment.Center, ZIndex = 35 })
    end
    local dot = new("Frame", { Size = UDim2.fromOffset(20, 20), Position = UDim2.fromOffset(72, 72), BackgroundColor3 = C.ok, BorderSizePixel = 0, ZIndex = 36 }, ring)
    corner(dot, 10); local ds = stroke(dot, C.white, 3, 0); bind(ds, "Color", "card")
