    text(profileCard, { Position = UDim2.fromOffset(20, 156), Size = UDim2.new(1, -40, 0, 22), Text = State.user.display or "User", TextSize = 17, ZIndex = 33, TextTruncate = Enum.TextTruncate.AtEnd })
    text(profileCard, { Position = UDim2.fromOffset(20, 178), Size = UDim2.new(1, -40, 0, 14), Text = "@" .. (State.user.name or "user"), TextSize = 11, Font = Enum.Font.Gotham, TextColor3 = C.dim, ZIndex = 33, TextTruncate = Enum.TextTruncate.AtEnd })
    local panel = new("Frame", { Size = UDim2.new(1, -24, 0, 138), Position = UDim2.fromOffset(12, 202), BorderSizePixel = 0, ZIndex = 32 }, profileCard)
