local cardOpen = false
local function cardFits()
    local cam = workspace.CurrentCamera
    local vp = cam and cam.ViewportSize or Vector2.new(1200, 700)
    return (vp.X / scale.Scale) >= (W + 340 + 40)
end
-- v29: Mobile UI Version - no celular (ou com ela ligada na mao) o card do perfil nunca flutua pra fora da janela
-- (ficaria fora da tela), sempre fica "dockado" por cima do conteudo igual no PC estreito - mas aqui a gente poe
-- um fundo escurecido atras dele (cardBackdrop) pra nao deixar os toggles do Script Settings aparecerem por
-- tras/ao redor do card (era exatamente o bug da foto que o usuario mandou). Tocar fora do card fecha ele.
local cardBackdrop = new("Frame", { Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.new(0, 0, 0), BackgroundTransparency = 0.45, BorderSizePixel = 0, ZIndex = 29, Visible = false }, win)
local backdropBtn = new("TextButton", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Text = "", AutoButtonColor = false, ZIndex = 29 }, cardBackdrop)
backdropBtn.MouseButton1Click:Connect(function() if cardOpen then showCard(false) end end)
local function cardPos()
    if mobileUIActive then return UDim2.fromOffset(SIDE_W + 16, 58) end
    return cardFits() and UDim2.fromOffset(-312, 48) or UDim2.fromOffset(SIDE_W + 16, 58)
end
local function dockedNow() return mobileUIActive or not cardFits() end
local function showCard(on, instant)
    cardOpen = on
    local p = cardPos()
    cardBackdrop.Visible = on and dockedNow()
    if on then
        profileCard.Visible = true
        profileCard.Position = UDim2.new(p.X.Scale, p.X.Offset - (instant and 0 or 14), p.Y.Scale, p.Y.Offset)
        profileCard.GroupTransparency = instant and 0 or 1
        tween(profileCard, instant and 0 or 0.4, { Position = p, GroupTransparency = 0 })
    else
        tween(profileCard, 0.22, { Position = UDim2.new(p.X.Scale, p.X.Offset - 10, p.Y.Scale, p.Y.Offset), GroupTransparency = 1 }, Enum.EasingStyle.Quad)
        task.delay(0.24, function() if not cardOpen then profileCard.Visible = false; cardBackdrop.Visible = false end end)
    end
end
-- v29: liga/desliga o Mobile UI Version a partir do toggle em Script Settings (extras.lua chama AFL.applyMobileUI);
-- tambem roda uma vez aqui no boot pra ja aplicar se o usuario tinha salvo ligado antes
PC.AFL.applyMobileUI = function()
    mobileUIActive = PC.Config.MobileUI == true
    fit()
    if cardOpen then showCard(true, true) else cardBackdrop.Visible = false end
end
