local function setStatus(on)
    State.online = on
    local col = on and C.ok or C.bad
    ui.stLab.Text = on and "ON" or "OFF"
    ui.stLab.TextColor3 = col
    tween(ui.stDot, 0.3, { BackgroundColor3 = col })
end
local function refresh()
    local info = State.info
    if info.lifetime then
        ui.timeLab.Text = "Lifetime"
        ui.pb.Size = UDim2.fromScale(1, 1)
        sidePlan.Text = "Plan: " .. TIER_LABEL .. " - Lifetime"
    elseif State.exp then
        local left = State.exp - os.time()
        ui.timeLab.Text = fmtLeft(left)
        ui.timeLab.TextColor3 = left < 3600 and C.bad or (left < 86400 and C.warn or TH.cur.text)
        local frac = math.clamp(left / (State.totalSecs or 1), 0, 1)
        tween(ui.pb, 0.9, { Size = UDim2.fromScale(frac, 1) }, Enum.EasingStyle.Linear)
        sidePlan.Text = "Plan: " .. TIER_LABEL .. " - " .. fmtShort(left)
        if left <= 0 and alive then setStatus(false) end
    end
    local rw = State.rw and (State.rw - os.time()) or 0
    if rw > 0 then
        ui.whid2.Text = "ReWhid Time: " .. fmtShort(rw); ui.whid2.TextColor3 = C.warn
    else
        ui.whid2.Text = "ReWhid Time: Ready to reset!"; ui.whid2.TextColor3 = C.ok
    end
    ui.cardPlan.Text = TIER_LABEL .. " - " .. (info.lifetime and "Lifetime" or planName())
    ui.cardPillLab.Text = TIER_LABEL:upper() .. " \u{2022} " .. (info.lifetime and "Lifetime" or planName())
    ui.whid1.Text = info.hwid_linked == false and "Waiting to link this device" or "Connected to this Device"
end
refresh()

