local lastSec = 0
table.insert(conns, RunService.RenderStepped:Connect(function()
    local t = os.clock() - t0
    winG.Rotation = ((t * (TH.cur.winSpin or 30)) % 360)
    if ui.ringG then ui.ringG.Rotation = (t * 90) % 360 end
    if ui.thxG then ui.thxG.Rotation = (t * 60) % 360 end
    if ui.cardG then ui.cardG.Rotation = (t * 40) % 360 end
    if t - lastSec >= 1 then lastSec = t; refresh() end
end))

-- verificacao periodica com o servidor (revoga na hora se a key cair)
local FATAL = { revoked = true, expired = true, hwid_mismatch = true, not_premium = true, bad_token = true }
task.spawn(function()
    local fails, fatal, nextWait = 0, 0, 45
    while alive do
        task.wait(nextWait)
        nextWait = 45
        if not alive then break end
        local res
        local tPing = os.clock()
        if httpFn then
            local ok, r = pcall(httpFn, { Url = (S.base or "") .. "/v2/status", Method = "POST", Headers = { ["Content-Type"] = "application/json" }, Body = HttpService:JSONEncode({ token = State.token }) })
            if ok and r and r.Body then
                local ok2, d = pcall(HttpService.JSONDecode, HttpService, r.Body)
                if ok2 then res = d end
            end
        end
        if res and res.ok then
            fails, fatal = 0, 0
            pingLab.Text = string.format("Server online  \u{2022}  %dms", math.floor((os.clock() - tPing) * 1000))
            State.token = res.token or State.token
            S.token = State.token
            applyInfo(res.info or State.info)
            if res.info then State.info = res.info end
            if not State.online then setStatus(true) end
            refresh()
        elseif res and FATAL[res.reason] and fatal < 2 then
            -- v53: uma resposta ruim sozinha (instabilidade do servidor) fechava o hub na hora. Agora confere mais 2 vezes
            -- (15 s entre elas); so fecha se o servidor confirmar. Key expirada/revogada de verdade continua fechando.
            fatal += 1
            nextWait = 15
            pingLab.Text = "Checking key (" .. fatal .. "/3)..."
        elseif res and FATAL[res.reason] then
            setStatus(false)
            notify("Key disabled", "Your Premium key is no longer valid (" .. tostring(res.reason) .. ").", "bad", 5)
            task.wait(4)
            destroyHub()
            break
        else
            fails += 1
            pingLab.Text = "Reconnecting..."
            if fails == 3 then notify("Connection", "Can't reach the Moon Hub server. Retrying...", "warn", 4) end
        end
    end
end)

